export const dynamic = 'force-dynamic'

/**
 * /api/db/migrations — Migration Status Endpoint
 *
 * Returns the list of applied migrations and their timestamps.
 * Admin-only (requires `admin` role).
 *
 * GET /api/db/migrations
 * Response: {
 *   applied: Array<{ version: string, applied_at: string, checksum: string | null }>,
 *   pending: string[],
 *   total: number
 * }
 */

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { getPool } from '@/lib/db'

export const GET = apiHandler(
  { auth: true, roles: ['admin'] },
  async (_req, _ctx) => {
    const pool = getPool()

    // Ensure schema_migrations table exists before querying
    const { rows: tables } = await pool.query(
      `SELECT table_name FROM information_schema.tables
       WHERE table_schema = 'public' AND table_name = 'schema_migrations'`
    )

    if (tables.length === 0) {
      return NextResponse.json({
        applied: [],
        pending: [],
        total: 0,
        message: 'schema_migrations table does not exist yet — no migrations have been run',
      })
    }

    // Get applied migrations
    const { rows: applied } = await pool.query(
      'SELECT version, applied_at, checksum FROM schema_migrations ORDER BY applied_at'
    )

    // Get all migration files from the filesystem
    // We use pg's ls_dir won't work, so we query the table and cross-reference
    // with what's known. For a complete picture, we return what's in the DB.
    // The CLI `migrate:status` does the full filesystem scan.
    const appliedVersions = new Set(applied.map((r: { version: string }) => r.version))

    return NextResponse.json({
      applied: applied.map((r: { version: string; applied_at: Date; checksum: string | null }) => ({
        version: r.version,
        applied_at: r.applied_at instanceof Date ? r.applied_at.toISOString() : String(r.applied_at),
        checksum: r.checksum,
      })),
      applied_count: applied.length,
      table_exists: true,
    })
  }
)

export const dynamic = 'force-dynamic'

/**
 * /api/db — Database proxy for client-side queries
 *
 * Client components send query specs here, this route executes them
 * against the VM PostgreSQL. Auth is verified via NextAuth session.
 *
 * SECURITY:
 * - Table whitelist prevents arbitrary table access
 * - User-scoped tables automatically filter by session user_id
 * - Admin-only tables restricted to ADMIN_EMAILS
 * - Rate-limited to prevent abuse
 * - Parameterized queries prevent SQL injection
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { apiHandler } from '@/lib/apiHandler'
import { setCurrentUserId } from '@/lib/db'
import { getPool } from '@/lib/db'
import { QueryBuilder } from '@/lib/db/queryBuilder'
import { env } from '@/lib/env'

// ponytail: Phase 6 Batch 7 — typed request body for /api/db proxy.
// Browser client posts this shape; server-side narrowing guards each field.
interface DbFilter {
  op: string
  column: string
  value: unknown
}

interface DbOrderClause {
  column: string
  ascending: boolean
}

interface DbRequestBody {
  table?: string
  operation?: string
  columns?: string
  filters?: DbFilter[]
  orFilters?: string[]
  order?: DbOrderClause[]
  limit?: number
  offset?: number
  single?: boolean
  maybeSingle?: boolean
  count?: string
  head?: boolean
  payload?: Record<string, unknown> | Record<string, unknown>[]
  onConflict?: string
}

// Tables that can be queried without authentication
const PUBLIC_TABLES = new Set([
  'benchmarks', 'survey_standards', 'countries', 'professional_bodies',
])

// Tables that are scoped to the authenticated user's ID
const USER_SCOPED_TABLES = new Set([
  'projects', 'profiles',
  'project_members', 'user_subscriptions',
  'collaboration_sessions', 'cpd_activities', 'peer_reviews',
  'peer_review_payments', 'digital_signatures', 'cleaned_datasets',
  'cadastra_validations', 'mine_twins', 'workflows', 'bathymetric_surveys',
  'usv_missions', 'safety_incidents', 'geofusion_projects', 'geofusion_layers',
  'deed_plans', 'survey_reports', 'parcel_metadata', 'gnss_sessions',
  'signatures', 'equipment', 'equipment_calibrations', 'job_applications',
  'job_reviews', 'payment_history', 'render_jobs', 'project_submissions',
  'submission_documents', 'import_sessions', 'online_service_logs',
  'surveyor_profiles', 'plan_usage', 'field_projects',
  'scheme_details', 'blocks', 'parcel_traverses',
  'traverse_observations', 'traverse_coordinates', 'block_assignments',
  'scheme_activity_log',
  'survey_firms', 'raw_observations', 'control_points', 'road_centrelines',
  'levelling_observations', 'monitoring_epochs', 'data_audit',
  'fieldbooks', 'cpd_records', 'cpd_certificates', 'notifications',
])

// Tables scoped to project_id (not user_id).
const PROJECT_SCOPED_TABLES = new Set([
  'survey_points', 'parcels', 'alignments', 'cross_sections',
  'project_fieldbook_entries', 'survey_epochs', 'leveling_runs',
  'parcel_traverses', 'network_adjustments',
  'mining_surveys', 'hydro_surveys', 'gnss_sessions',
  'peer_review_requests', 'supporting_documents',
])

// Tables that are read-only for all authenticated users
const READ_ONLY_SHARED_TABLES = new Set([
  'benchmarks', 'survey_standards', 'countries', 'professional_bodies',
  'land_law_cases', 'land_law_regulations', 'nlims_cache',
  'public_beacons',
])

// Tables accessible only by admins
const ADMIN_ONLY_TABLES = new Set([
  'audit_logs', 'analytics_events', 'rate_limit_events',
  'enterprise_organizations', 'enterprise_members', 'enterprise_invitations',
  'enterprise_settings',
])

// Public browse tables
const PUBLIC_BROWSE_TABLES = new Set([
  'jobs', 'job_missions', 'newsletter_subscribers', 'feedback',
  'survey_type_expand', 'community',
])

// Build the full allowlist from all sets
const ALLOWED_TABLES = new Set([
  ...Array.from(USER_SCOPED_TABLES),
  ...Array.from(PROJECT_SCOPED_TABLES),
  ...Array.from(READ_ONLY_SHARED_TABLES),
  ...Array.from(ADMIN_ONLY_TABLES),
  ...Array.from(PUBLIC_BROWSE_TABLES),
  'project_sheets', 'survey_photos',
])

// NEVER allow these tables through the proxy
const FORBIDDEN_TABLES = new Set([
  'password_reset_tokens', 'users',
])

function isAdmin(email: string | null | undefined): boolean {
  if (!email) return false
  const adminEmails = (env.ADMIN_EMAILS || '').split(',').map(e => e.trim().toLowerCase())
  return adminEmails.includes(email.toLowerCase())
}

// Note: This route uses apiHandler({ auth: false }) because it has conditional auth
// (public tables don't need auth). We handle auth manually inside the handler
// and set RLS context ourselves when a session is found.
export const POST = apiHandler({ auth: false, rateLimit: { max: 120, windowMs: 60000 } }, async (request, ctx) => {
  const body = ctx.body as DbRequestBody
  const { table, operation, columns, filters, orFilters, order, limit, offset, single, maybeSingle, count, head, payload, onConflict } = body

  // ─── Table validation ─────────────────────────────────────────
  if (!table || FORBIDDEN_TABLES.has(table as string)) {
    return NextResponse.json(
      { data: null, error: { message: 'Access denied', code: 'FORBIDDEN' } },
      { status: 403 }
    )
  }

  if (!ALLOWED_TABLES.has(table as string)) {
    return NextResponse.json(
      { data: null, error: { message: `Table not allowed: ${table}`, code: 'FORBIDDEN' } },
      { status: 403 }
    )
  }

  // ─── Auth check ───────────────────────────────────────────────
  let userId: string | null = null
  let userEmail: string | null = null

  if (!PUBLIC_TABLES.has(table as string)) {
    // /api/db uses apiHandler({ auth: false }) for conditional auth, so
    // ctx.session is NOT populated by the wrapper. Fetch the session here
    // directly so authenticated (non-public) tables are properly gated.
    const session = await getServerSession(authOptions)
    if (!session?.user) {
      return NextResponse.json(
        { data: null, error: { message: 'Not authenticated', code: 'AUTH_REQUIRED' } },
        { status: 401 }
      )
    }
    userId = (session.user as { id: string }).id
    userEmail = session.user.email ?? null

    // Set RLS context
    if (userId) {
      setCurrentUserId(userId)
    }
  }

  // ─── Admin-only table check ───────────────────────────────────
  if (ADMIN_ONLY_TABLES.has(table as string) && !isAdmin(userEmail)) {
    return NextResponse.json(
      { data: null, error: { message: 'Admin access required', code: 'FORBIDDEN' } },
      { status: 403 }
    )
  }

  // ─── Read-only shared table check ────────────────────────────
  if (READ_ONLY_SHARED_TABLES.has(table as string) && operation !== 'select') {
    return NextResponse.json(
      { data: null, error: { message: 'This table is read-only', code: 'FORBIDDEN' } },
      { status: 403 }
    )
  }

  let qb = new QueryBuilder(getPool(), table as string)

  // Apply operation
  if (operation === 'select') {
    qb = qb.select((columns as string) || '*', { count: count ? 'exact' : undefined, head: head as boolean | undefined })
  } else if (operation === 'insert') {
    const insertPayload = payload as Record<string, unknown> | Record<string, unknown>[]
    // For user-scoped tables, inject user_id into the payload
    if (USER_SCOPED_TABLES.has(table as string) && userId) {
      if (Array.isArray(insertPayload)) {
        for (const row of insertPayload) { row.user_id = userId }
      } else if (insertPayload) {
        insertPayload.user_id = userId
      }
    }
    qb = qb.insert(insertPayload)
  } else if (operation === 'update') {
    qb = qb.update(payload as Record<string, unknown>)
  } else if (operation === 'delete') {
    qb = qb.delete()
  } else if (operation === 'upsert') {
    const upsertPayload = payload as Record<string, unknown> | Record<string, unknown>[]
    if (USER_SCOPED_TABLES.has(table as string) && userId) {
      if (Array.isArray(upsertPayload)) {
        for (const row of upsertPayload) { row.user_id = userId }
      } else if (upsertPayload) {
        upsertPayload.user_id = userId
      }
    }
    // onConflict (e.g. 'user_id,parcel_number') is validated synchronously
    // inside upsert() via validateIdentifier — each comma-separated column
    // must match the strict identifier allowlist, so it cannot inject SQL.
    qb = qb.upsert(upsertPayload, onConflict ? { onConflict } : undefined)
  }

  // ─── User-scoped row-level security ──────────────────────────
  if (USER_SCOPED_TABLES.has(table as string) && userId) {
    qb = qb.eq('user_id', userId)
  }

  // Apply filters
  const filterArr = filters as DbFilter[] | undefined
  if (Array.isArray(filterArr)) {
    for (const f of filterArr) {
      const method = f.op
      // Prevent client from overriding user_id filter on scoped tables
      if (USER_SCOPED_TABLES.has(table as string) && f.column === 'user_id') continue

      if (method === 'eq') qb = qb.eq(f.column, f.value)
      else if (method === 'neq') qb = qb.neq(f.column, f.value)
      else if (method === 'gt') qb = qb.gt(f.column, f.value)
      else if (method === 'gte') qb = qb.gte(f.column, f.value)
      else if (method === 'lt') qb = qb.lt(f.column, f.value)
      else if (method === 'lte') qb = qb.lte(f.column, f.value)
      else if (method === 'like') qb = qb.like(f.column, f.value as string)
      else if (method === 'ilike') qb = qb.ilike(f.column, f.value as string)
      else if (method === 'in') qb = qb.in(f.column, f.value as unknown[])
      else if (method === 'is') qb = qb.is(f.column, f.value)
      else if (method === 'contains') qb = qb.contains(f.column, f.value)
    }
  }

  // Apply OR filters
  const orFilterArr = orFilters as string[] | undefined
  if (Array.isArray(orFilterArr)) {
    for (const of_ of orFilterArr) {
      qb = qb.or(of_)
    }
  }

  // Apply order
  const orderArr = order as DbOrderClause[] | undefined
  if (Array.isArray(orderArr)) {
    for (const o of orderArr) {
      qb = qb.order(o.column, { ascending: o.ascending })
    }
  }

  // Apply limit/offset
  if (limit != null) qb = qb.limit(limit as number)
  if (offset != null) {
    qb = qb.range(offset as number, (offset as number) + ((limit as number) ?? 50) - 1)
  }

  // Apply single/maybeSingle
  if (single) qb = qb.single()
  else if (maybeSingle) qb = qb.maybeSingle()

  // Execute
  const result = await qb
  return NextResponse.json(result)
})

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '@/lib/logger'
import { apiHandler } from '@/lib/apiHandler'
import { z } from 'zod'
import type { DeedPlanInput, DeedPlanOutput } from '@/types/deedPlan'
import { computeBoundaryLegs, computeArea, computeClosureCheck } from '@/lib/compute/deedPlan'
import { renderDeedPlanSVG } from '@/lib/compute/deedPlanRenderer'
import { runStatutoryGate, type StatutoryGateResult } from '@/lib/validation/statutoryGate'

const BoundaryPointSchema = z.object({
  id: z.string().optional(),
  easting: z.number(),
  northing: z.number(),
  elevation: z.number().optional(),
  markType: z.string().optional(),
  markStatus: z.string().optional(),
  description: z.string().optional(),
})

const DeedPlanRequestSchema = z.object({
  surveyNumber: z.string().optional(),
  drawingNumber: z.string().optional(),
  parcelNumber: z.string().optional(),
  locality: z.string().optional(),
  area: z.number().optional(),
  registrationSection: z.string().optional(),
  county: z.string().optional(),
  utmZone: z.number().optional(),
  hemisphere: z.enum(['N', 'S']).optional(),
  scale: z.enum(['500', '1000', '2500', '5000']).optional(),
  datum: z.enum(['ARC1960', 'WGS84']).optional(),
  projectionType: z.enum(['UTM', 'Cassini']).optional(),
  // Grid-to-ground correction (RDM 1.1)
  scaleFactor: z.number().optional(),
  meanElevation: z.number().optional(),
  gridArea: z.number().optional(),
  // SRVY2025-1 submission
  submissionNumber: z.string().optional(),
  sheetNumber: z.number().optional(),
  totalSheets: z.number().optional(),
  boundaryPoints: z.array(BoundaryPointSchema).min(3, 'A deed plan requires at least 3 boundary points'),
  abuttalNorth: z.string().optional(),
  abuttalSouth: z.string().optional(),
  abuttalEast: z.string().optional(),
  abuttalWest: z.string().optional(),
  surveyorName: z.string().optional(),
  iskNumber: z.string().optional(),
  firmName: z.string().optional(),
  firmAddress: z.string().optional(),
  surveyDate: z.string().optional(),
  signatureDate: z.string().optional(),
  clientName: z.string().optional(),
  titleDeedNumber: z.string().optional(),
  firNumber: z.string().optional(),
  registryMapSheet: z.string().optional(),
  drawnBy: z.string().optional(),
  checkedBy: z.string().optional(),
  controlClass: z.enum(['FIRST', 'SECOND', 'THIRD', 'FOURTH']).optional(),
})

export const POST = apiHandler(
  { auth: true, schema: DeedPlanRequestSchema, audit: 'deed_plan_generated',
    auditChain: { entityType: 'document', action: 'generate', projectIdFromBody: 'projectId' },
    rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const raw = ctx.body as z.infer<typeof DeedPlanRequestSchema>

    const input: DeedPlanInput = {
      surveyNumber: raw.surveyNumber || '',
      drawingNumber: raw.drawingNumber || '',
      parcelNumber: raw.parcelNumber || '',
      locality: raw.locality || '',
      area: raw.area || 0,
      registrationSection: raw.registrationSection || '',
      county: raw.county || '',
      utmZone: raw.utmZone || 37,
      hemisphere: raw.hemisphere || 'S',
      scale: (Number(raw.scale) || 1000) as 500 | 1000 | 2500 | 5000,
      datum: raw.datum || 'ARC1960',
      projectionType: (raw.projectionType || 'UTM') as 'UTM' | 'Cassini',
      boundaryPoints: raw.boundaryPoints.map((p, i) => ({
        id: p.id || `P${i + 1}`,
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation,
        markType: (p.markType || 'CONCRETE_BEACON') as import('@/types/deedPlan').BeaconType,
        markStatus: (p.markStatus || 'SET') as import('@/types/deedPlan').BeaconStatus,
        description: p.description,
      })),
      abuttalNorth: raw.abuttalNorth || '',
      abuttalSouth: raw.abuttalSouth || '',
      abuttalEast: raw.abuttalEast || '',
      abuttalWest: raw.abuttalWest || '',
      surveyorName: raw.surveyorName || '',
      iskNumber: raw.iskNumber || '',
      firmName: raw.firmName || '',
      firmAddress: raw.firmAddress || '',
      surveyDate: raw.surveyDate || '',
      signatureDate: raw.signatureDate || '',
      clientName: raw.clientName,
      titleDeedNumber: raw.titleDeedNumber,
      firNumber: raw.firNumber,
      registryMapSheet: raw.registryMapSheet,
      drawnBy: raw.drawnBy,
      checkedBy: raw.checkedBy,
      // SRVY2025-1
      submissionNumber: raw.submissionNumber,
      sheetNumber: raw.sheetNumber,
      totalSheets: raw.totalSheets,
      // Grid-to-ground
      scaleFactor: raw.scaleFactor,
      meanElevation: raw.meanElevation,
      gridArea: raw.gridArea,
      controlClass: raw.controlClass,
    }

    const bearingSchedule = computeBoundaryLegs(input.boundaryPoints)
    const area = computeArea(input.boundaryPoints)
    const closureCheck = computeClosureCheck(input.boundaryPoints)

    // ── AUDIT FIX (2026-07-05): Run cross-checks before generating deed plan ──
    // These independent verification methods catch computation errors
    // that could lead to incorrect boundaries and encroachment disputes.
    const crossCheckIssues: string[] = []

    try {
      const { crossCheckArea, crossCheckClosure } = await import('@/lib/engine/calculationCrossCheck')

      // Convert boundary points to Point2D format for cross-checks
      const points2D = input.boundaryPoints.map(p => ({
        easting: p.easting,
        northing: p.northing,
      }))

      // Area cross-check: Shoelace vs. triangulation
      const areaCheck = crossCheckArea(points2D)
      if (!areaCheck.passed) {
        crossCheckIssues.push(`Area cross-check failed: ${areaCheck.message}`)
      }

      // Closure cross-check: coordinate round-trip
      if (points2D.length >= 2) {
        const start = points2D[0]
        const end = points2D[points2D.length - 1]
        const linearError = Math.sqrt(
          closureCheck.closingErrorE ** 2 + closureCheck.closingErrorN ** 2
        )
        const closureCheckResult = crossCheckClosure(
          start.easting, start.northing,
          end.easting, end.northing,
          linearError, 0,
          0.001
        )
        if (!closureCheckResult.passed) {
          crossCheckIssues.push(`Closure cross-check failed: ${closureCheckResult.message}`)
        }
      }
    } catch {
      // Cross-check module not available — non-blocking but log
      logger.warn('[deed-plan] Cross-check module not available')
    }

    // If cross-checks found issues, include them in the output as warnings
    if (crossCheckIssues.length > 0) {
      logger.warn('[deed-plan] Cross-check issues:', { crossCheckIssues })
    }

    // ── AUDIT FIX (2026-07-05): Run statutory gate ──
    let gateResult: StatutoryGateResult | null = null
    try {
      const linearError = Math.sqrt(
        closureCheck.closingErrorE ** 2 + closureCheck.closingErrorN ** 2
      )
      const precisionRatioNum = linearError > 0
        ? Math.round(closureCheck.perimeter / linearError)
        : 999999

      gateResult = runStatutoryGate({
        surveyType: 'cadastral',
        surveyor: {
          name: input.surveyorName || 'Unknown',
          licenseNumber: input.iskNumber || 'N/A',
        },
        traverse: {
          stationCount: input.boundaryPoints.length,
          linearErrorM: linearError,
          totalDistanceM: closureCheck.perimeter,
          precisionRatio: precisionRatioNum,
        },
        parcels: [{
          vertices: input.boundaryPoints.map(p => ({
            easting: p.easting,
            northing: p.northing,
          })),
          parcelNumber: input.parcelNumber || '',
        }],
      })

      if (!gateResult.passed) {
        logger.warn('[deed-plan] Statutory gate blocked:', { summary: gateResult.summary })
      }
    } catch (err) {
      logger.warn('[deed-plan] Statutory gate failed to run:', { error: err })
    }

    const svg = renderDeedPlanSVG({ ...input, area }, bearingSchedule, closureCheck)

    const output: DeedPlanOutput = {
      svg,
      bearingSchedule,
      coordinateSchedule: input.boundaryPoints,
      closureCheck,
      ...(crossCheckIssues.length > 0 ? { crossCheckWarnings: crossCheckIssues } : {}),
      ...(gateResult ? { statutoryGate: gateResult } : {}),
    }

    return NextResponse.json(output)
  }
)

