// ---------------------------------------------------------------------------
// POST – file upload (logo or favicon via FormData)
// ---------------------------------------------------------------------------

const UPLOAD_BASE = join(process.cwd(), 'public', 'uploads', 'white-label')

/**
 * Allowed file extensions for white-label uploads.
 * SECURITY: SVG is intentionally EXCLUDED because Next.js serves
 * .svg files with Content-Type: image/svg+xml, which browsers
 * will execute as HTML/JS. An attacker uploading a malicious SVG
 * would get script execution on the white-labelled domain.
 */
const ALLOWED_EXTENSIONS = new Set(['png', 'jpg', 'jpeg', 'gif', 'webp', 'ico'])

/**
 * Allowed MIME types — must match the extension whitelist.
 */
const ALLOWED_MIME_TYPES = new Set([
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
  'image/x-icon',
  'image/vnd.microsoft.icon',
])

export const POST = apiHandler({ auth: true, rawBody: true }, async (request, ctx) => {
  const formData = await request.formData()
  const file = formData.get('file') as File | null
  const type = formData.get('type') as string | null // 'logo' | 'favicon'

  if (!file) {
    return NextResponse.json(apiError('No file provided'), { status: 400 })
  }

  if (!type || !['logo', 'favicon'].includes(type)) {
    return NextResponse.json(apiError('Missing or invalid type field (must be "logo" or "favicon")'), { status: 400 })
  }

  // Validate MIME type — strict allowlist, no SVG
  if (!ALLOWED_MIME_TYPES.has(file.type)) {
    return NextResponse.json(
      apiError('Invalid file type. Allowed: PNG, JPEG, GIF, WebP, ICO. SVG is not allowed for security reasons.'),
      { status: 400 }
    )
  }

  // SECURITY: derive extension from MIME type (not from user-supplied filename).
  // Then generate a UUID filename — never trust user-supplied names.
  const extByMime: Record<string, string> = {
    'image/png': 'png',
    'image/jpeg': 'jpg',
    'image/gif': 'gif',
    'image/webp': 'webp',
    'image/x-icon': 'ico',
    'image/vnd.microsoft.icon': 'ico',
  }
  const ext = extByMime[file.type]
  if (!ext || !ALLOWED_EXTENSIONS.has(ext)) {
    return NextResponse.json(apiError('Could not determine safe file extension'), { status: 400 })
  }

  // UUID filename — prevents path traversal and filename collisions
  const fileName = `${ctx.userId}_${randomUUID()}.${ext}`
  const filePath = join(UPLOAD_BASE, fileName)

  // Ensure upload directory exists
  if (!existsSync(UPLOAD_BASE)) {
    await mkdir(UPLOAD_BASE, { recursive: true })
  }

  const bytes = await file.arrayBuffer()
  await writeFile(filePath, Buffer.from(bytes))

  const publicUrl = `/uploads/white-label/${fileName}`
  const dbColumn = type === 'logo' ? 'logo_url' : 'favicon_url'
  const fileKeyColumn = type === 'logo' ? 'logo_file_key' : 'favicon_file_key'

  // Upsert the URL into the config row.
  // dbColumn is from a hardcoded set above, not user input — safe to interpolate.
  await db.query<never>(
    `INSERT INTO white_label_configs (user_id, ${dbColumn}, ${fileKeyColumn})
     VALUES ($1, $2, $3)
     ON CONFLICT (user_id) DO UPDATE SET
       ${dbColumn}    = EXCLUDED.${dbColumn},
       ${fileKeyColumn} = EXCLUDED.${fileKeyColumn},
       updated_at     = NOW()`,
    [ctx.userId, publicUrl, fileName]
  )

  return NextResponse.json(
    apiSuccess({
      type,
      url: publicUrl,
      fileName,
    })
  )
})

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface BackgroundJobRow {
  id: string
  job_type: string
  status: string | null
  priority: number | null
  created_at: Date | null
  payload: unknown
  attempts: number | null
  max_attempts: number | null
  started_at: Date | null
  completed_at: Date | null
  error_message: string | null
  result: unknown | null
  updated_at: Date | null
}
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const body = ctx.body as {
    jobType: string
    projectId?: string
    payload?: Record<string, unknown>
    priority?: number
  }

  if (!body.jobType) {
    return NextResponse.json({ error: 'Missing jobType' }, { status: 400 })
  }

  const validTypes = [
    'pdf_generation',
    'dxf_generation',
    'assemble_submission',
    'report_processing',
    'traverse_compute',
    'earthworks_boq',
  ]
  if (!validTypes.includes(body.jobType)) {
    return NextResponse.json({ error: 'Invalid jobType' }, { status: 400 })
  }

  // Build payload — merge projectId into payload if provided separately
  const payload = { ...(body.payload || {}) }
  if (body.projectId) {
    payload.project_id = body.projectId
  }
  // Thread userId so the worker can attribute audit entries correctly
  payload.userId = ctx.userId

  const priority = typeof body.priority === 'number'
    ? Math.max(0, Math.min(10, body.priority))
    : 5

  const { rows } = await db.query<BackgroundJobRow>(
    `INSERT INTO background_jobs (job_type, payload, priority)
     VALUES ($1, $2, $3)
     RETURNING id, job_type, status, priority, created_at`,
    [body.jobType, JSON.stringify(payload), priority]
  )

  return NextResponse.json({ success: true, job: rows[0], jobId: rows[0].id })
})

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req) => {
  const { searchParams } = new URL(req.url)
  const status = searchParams.get('status')

  let query = 'SELECT * FROM background_jobs WHERE 1=1'
  const params: unknown[] = []
  let paramIndex = 1

  if (status) {
    query += ` AND status = $${paramIndex++}`
    params.push(status)
  }

  query += ' ORDER BY priority DESC, created_at DESC LIMIT 50'

  const { rows } = await db.query<BackgroundJobRow>(query, params)
  return NextResponse.json({ jobs: rows })
})

/**
 * GET /api/workspaces?surveyType=cadastral
 *
 * Returns the workspace configuration for the given survey type.
 * If surveyType is omitted, returns all available workspaces.
 *
 * Used by the frontend to morph the UI based on the active workspace
 * (tool categories, map layers, hotkeys, document types).
 */

export const dynamic = 'force-dynamic'

import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import {
  getWorkspaceConfig,
  listWorkspaces,
  autoDetectWorkspace,
  type WorkspaceId,
} from '@/lib/workspaces/config'

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, _ctx) => {
    const url = new URL(req.url)
    const surveyType = url.searchParams.get('surveyType')

    if (surveyType) {
      // Auto-detect workspace from survey type and return its config
      const workspaceId = autoDetectWorkspace(surveyType)
      const config = getWorkspaceConfig(workspaceId)
      return apiSuccess({ workspace: config })
    }

    // No surveyType — return all workspaces for the switcher UI
    const workspaces = listWorkspaces()
    return apiSuccess({ workspaces })
  }
)

'use client';
import React from 'react'

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { createClient } from '@/lib/api-client/client'
import { utmToGeographic } from '@/lib/geodesy/coordinates'
import Link from 'next/link'
import { BeaconRegistryPanel } from '@/components/beacons/BeaconRegistryPanel'
import { ControlPointRegistry } from '@/components/survey/ControlPointRegistry'
// ponytail: Phase 6 — use typed imports from ol (which ships its own .d.ts files)
// instead of dynamic imports + `as any` casts. Same bundle (Next.js code-splits
// these automatically), but now TypeScript can catch API misuse.
import Map from 'ol/Map'
import View from 'ol/View'
import TileLayer from 'ol/layer/Tile'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import OSM from 'ol/source/OSM'
import Style from 'ol/style/Style'
import CircleStyle from 'ol/style/Circle'
import Fill from 'ol/style/Fill'
import Stroke from 'ol/style/Stroke'
import Text from 'ol/style/Text'
import Feature from 'ol/Feature'
import Point from 'ol/geom/Point'
import { fromLonLat } from 'ol/proj'
import Overlay from 'ol/Overlay'
import type { Map as MapType, Overlay as OverlayType } from 'ol'
import { logger } from '@/lib/logger'

interface Beacon {
  id: string
  name: string
  easting: number
  northing: number
  elevation?: number
  utm_zone: number
  hemisphere: string
  authority?: string
  beacon_type: string
  description?: string
  datum?: string  // T1.5d: added for beacon import
}

interface Project {
  id: string
  name: string
  location?: string
  survey_type?: string
  created_at: string
}

function getMarkerIcon(type: string) {
  const icons: Record<string, string> = {
    trig: '▲',
    control: '●',
    boundary: '■',
    benchmark: '◆',
    gnss: '',
    other: '●'
  }
  return icons[type] || '●'
}

function getMarkerColor(type: string) {
  const colors: Record<string, string> = {
    trig: '#ef4444',
    control: '#f97316',
    boundary: '#eab308',
    benchmark: '#22c55e',
    gnss: '#3b82f6',
    other: '#6b7280'
  }
  return colors[type] || '#6b7280'
}

export default function BeaconsPage() {
  const [importMsg, setImportMsg] = React.useState<{text:string;ok:boolean}|null>(null)
  // AUDIT FIX (2026-07-03): Removed 'activity' view — it placed projects
  // at Math.random() positions (pins jumped on every refresh). Only
  // the 'beacons' view is real.
  const [beacons, setBeacons] = useState<Beacon[]>([])
  const [projects, setProjects] = useState<Project[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [search, setSearch] = useState('')
  const [importProject, setImportProject] = useState('')
  const [importBeacon, setImportBeacon] = useState<Beacon | null>(null)
  const [importLoading, setImportLoading] = useState(false)

  const mapRef = useRef<HTMLDivElement>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const mapInstance = useRef<MapType | null>(null)
  const overlayRef = useRef<OverlayType | null>(null)

  // AUDIT FIX (H-007, 2026-07-27): useMemo to prevent infinite loop on /beacons.
  // Same pattern as H-003 in /fieldbook.
  const dbClient = useMemo(() => createClient(), [])

  const fetchData = useCallback(async () => {
    setLoading(true)
    
    const [beaconsRes, projectsRes] = await Promise.all([
      dbClient.from('public_beacons').select('*').eq('status', 'verified'),
      dbClient.from('projects').select('id, name, location, survey_type, created_at')
    ])

    if (beaconsRes.data) setBeacons(beaconsRes.data as unknown as Beacon[])
    if (projectsRes.data) setProjects(projectsRes.data as unknown as Project[])
    setLoading(false)
  }, [dbClient])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  // Initialize map once (typed ol imports — Next.js still code-splits)
  useEffect(() => {
    if (!mapRef.current) return

    let cancelled = false

    async function initMap() {
      try {
        // ponytail: imports are now at module top-level (typed). The async
        // wrapper is kept for the cancelled-flag pattern.
        await Promise.resolve() // keep async signature for callers
        if (cancelled || !mapRef.current) return

        const map = new Map({
          target: mapRef.current,
          layers: [new TileLayer({ source: new OSM() })],
          view: new View({
            center: fromLonLat([36.8219, -1.2921]),
            zoom: 6,
          }),
        })

        if (popupRef.current) {
          const overlay = new Overlay({
            element: popupRef.current,
            autoPan: { animation: { duration: 250 } },
          })
          map.addOverlay(overlay)
          overlayRef.current = overlay
        }

        mapInstance.current = map

        // Click handler for popup
        // ponytail: use a structural type for evt; cast handler when
        // registering with map.on() so TS doesn't complain about the
        // ol MapBrowserEvent<UIEvent> signature mismatch.
        const handleClick = (evt: { pixel: [number, number]; coordinate: [number, number] }) => {
          const overlay = overlayRef.current
          if (!overlay || !popupRef.current) return

          const feature = map.forEachFeatureAtPixel(evt.pixel, (f) => f as Feature)
          const popupData = feature?.get('popupData') as
            | { color: string; icon: string; name: string; authority?: string; beacon_type: string; easting: number; northing: number; elevation?: number; utm_zone: number; hemisphere: string }
            | undefined
          if (feature && popupData && popupRef.current) {
            // VULN-002 FIX: render with textContent, never innerHTML.
            const el = popupRef.current
            el.replaceChildren()

            const wrap = document.createElement('div')
            wrap.className = 'text-sm min-w-[200px]'
            wrap.style.color = 'var(--text-primary)'

            const title = document.createElement('div')
            title.style.cssText = 'font-weight:bold;font-size:1.1rem;color:' + popupData.color
            title.textContent = `${popupData.icon} ${popupData.name}`
            wrap.append(title)

            if (popupData.authority) {
              const authority = document.createElement('div')
              authority.style.cssText = 'color:var(--text-muted);margin-top:4px'
              authority.textContent = `Authority: ${popupData.authority}`
              wrap.append(authority)
            }

            const typeRow = document.createElement('div')
            typeRow.style.cssText = 'color:var(--text-muted);text-transform:capitalize'
            typeRow.textContent = `Type: ${popupData.beacon_type}`
            wrap.append(typeRow)

            const coords = document.createElement('div')
            // white-space:pre-line preserves the \n line break (textContent
            // would otherwise collapse it to a space, unlike the old <br/>).
            coords.style.cssText = 'font-family:monospace;margin-top:8px;white-space:pre-line'
            coords.textContent = `E: ${popupData.easting.toFixed(4)}\nN: ${popupData.northing.toFixed(4)}`
            wrap.append(coords)

            if (popupData.elevation) {
              const elev = document.createElement('div')
              elev.style.cssText = 'color:var(--text-muted)'
              elev.textContent = `Elev: ${popupData.elevation.toFixed(3)} m`
              wrap.append(elev)
            }

            const utm = document.createElement('div')
            utm.style.cssText = 'color:var(--text-muted);font-size:0.75rem;margin-top:4px'
            utm.textContent = `UTM Zone ${popupData.utm_zone}${popupData.hemisphere}`
            wrap.append(utm)

            el.append(wrap)
            overlay.setPosition(evt.coordinate)
          } else {
            overlay.setPosition(undefined)
          }
        }
        map.on('click', handleClick as (e: unknown) => void)
      } catch (err) {
        logger.error('Beacons map init failed:', { error: err })
      }
    }

    initMap()

    return () => {
      cancelled = true
      if (mapInstance.current) mapInstance.current.setTarget(undefined)
      overlayRef.current = null
    }
  }, [])

  // Update map features when data changes
  useEffect(() => {
    const map = mapInstance.current
    if (!map || loading) return

    let cancelled = false

    async function updateFeatures() {
      try {
        // ponytail: re-assert map is non-null inside async closure (TS can't
        // track the outer null check across the async boundary)
        if (!map || cancelled) return

        const vectorSource = new VectorSource()

      const filteredBeacons = beacons.filter((b) => {
        if (filter !== 'all' && b.beacon_type !== filter) return false
        if (search && !b.name.toLowerCase().includes(search.toLowerCase()) &&
            !b.authority?.toLowerCase().includes(search.toLowerCase())) return false
        return true
      })

      filteredBeacons.forEach((beacon) => {
        const coords = utmToGeographic(beacon.easting, beacon.northing, beacon.utm_zone, beacon.hemisphere as 'N' | 'S')
        const color = getMarkerColor(beacon.beacon_type)
        const icon = getMarkerIcon(beacon.beacon_type)

        const feature = new Feature({
          geometry: new Point(fromLonLat([coords.lon, coords.lat])),
        })
        feature.setStyle(new Style({
          image: new CircleStyle({
            radius: 8,
            fill: new Fill({ color }),
            stroke: new Stroke({ color: '#fff', width: 2 }),
          }),
          text: new Text({ text: icon, font: '12px sans-serif', fill: new Fill({ color: '#fff' }) }),
        }))
        // VULN-002 FIX (security review 2026-08-03): store structured data
        // instead of an HTML string — beacon names/authorities are
        // user-entered and would otherwise execute as stored XSS. The popup
        // is rendered with textContent in the click handler below.
        feature.set('popupData', {
          color,
          icon,
          name: beacon.name,
          authority: beacon.authority,
          beacon_type: beacon.beacon_type,
          easting: beacon.easting,
          northing: beacon.northing,
          elevation: beacon.elevation,
          utm_zone: beacon.utm_zone,
          hemisphere: beacon.hemisphere,
        })
        feature.set('beaconId', beacon.id)
        vectorSource.addFeature(feature)
      })

      // Pan to Kenya/East Africa if beacons exist
      if (filteredBeacons.length > 0) {
        const extent = vectorSource.getExtent()
        if (extent && (extent[2] - extent[0] > 0 || extent[3] - extent[1] > 0)) {
          map.getView().fit(extent, { padding: [50, 50, 50, 50], maxZoom: 10 })
        }
      } else {
        map.getView().setCenter(fromLonLat([36.8219, -1.2921]))
        map.getView().setZoom(6)
      }

        // Remove old vector layers, add new one
        const existing = map.getLayers().getArray().find((l) => l instanceof VectorLayer)
        if (existing) map.removeLayer(existing)
        map.addLayer(new VectorLayer({ source: vectorSource }))
      } catch (err) {
        logger.error('Beacons map feature update failed:', { error: err })
      }
    }

    updateFeatures()

    return () => {
      cancelled = true
    }
  }, [beacons, projects, filter, search, loading])

  const handleImport = async () => {
    if (!importBeacon || !importProject) return
    
    setImportLoading(true)
    
    try {
      const { error } = await dbClient.from('survey_points').insert({
        project_id: importProject,
        point_name: importBeacon.name,  // T1.5d FIX: was 'name' (column doesn't exist)
        easting: importBeacon.easting,
        northing: importBeacon.northing,
        elevation: importBeacon.elevation,
        is_control: true,
        // T1.5d: control_order and locked columns don't exist — removed.
        // The beacon's datum/utm_zone could be carried over here too.
        datum: importBeacon.datum || 'Arc 1960',
        utm_zone: importBeacon.utm_zone || 37,
        source: 'beacon_registry',
      })

      if (error) throw error
      
      setImportMsg({text:'Beacon imported successfully!', ok:true}); setTimeout(()=>setImportMsg(null),3000)
      setImportBeacon(null)
      setImportProject('')
    } catch (err: unknown) {
      const msg = err instanceof Error ? (err as Error).message : String(err)
      setImportMsg({text:'Error: '+msg, ok:false}); setTimeout(()=>setImportMsg(null),4000)
    }
    
    setImportLoading(false)
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex flex-col">
      <header className="bg-[var(--bg-secondary)] border-b border-[var(--border-color)] px-4 py-4">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-2xl font-bold text-[var(--text-primary)]">Community Beacons</h1>
              <p className="text-sm text-[var(--text-secondary)]">East Africa Control Network</p>
            </div>
            <div className="flex gap-3">
              <Link
                href="/beacons/submit"
                className="px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg"
              >
                + Submit Beacon
              </Link>
            </div>
          </div>

          <div className="flex gap-4 items-center">
              <input
                type="text"
                placeholder="Search by name or authority..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)]"
              />
              <div className="flex gap-2">
                {['all', 'trig', 'control', 'boundary', 'benchmark'].map((f) => (
                  <button
                    key={f}
                    onClick={() => setFilter(f)}
                    className={`px-3 py-2 rounded text-sm capitalize ${
                      filter === f ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                    }`}
                  >
                    {f}
                  </button>
                ))}
              </div>
            </div>
        </div>
      </header>

      <main className="flex-1 relative">
        {loading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full"></div>
          </div>
        ) : (
          <div className="h-full" style={{ height: 'calc(100vh - 140px)' }}>
            <div ref={mapRef} className="w-full h-full" />
            <div ref={popupRef} className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded p-2 text-sm shadow-lg" style={{ display: 'none' }}></div>
          </div>
        )}
      </main>

      {/* Import Modal */}
      {importBeacon && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-6 max-w-md w-full mx-4">
            <h3 className="text-lg font-bold text-[var(--text-primary)] mb-4">Import Beacon</h3>
            <p className="text-[var(--text-primary)] mb-4">
              Import {importBeacon.name} as a locked Primary control point?
            </p>
            
            <div className="mb-4">
              <label htmlFor="beacon-project" className="block text-sm text-[var(--text-secondary)] mb-2">Select Project</label>
              <select
                id="beacon-project"
                value={importProject}
                onChange={e => setImportProject(e.target.value)}
                className="w-full px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
              >
                <option value="">Choose project...</option>
                {projects.map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setImportBeacon(null)}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded"
              >
                Cancel
              </button>
              <button
                onClick={handleImport}
                disabled={!importProject || importLoading}
                className="flex-1 px-4 py-2 bg-[var(--accent)] text-black font-semibold rounded disabled:opacity-50"
              >
                {importLoading ? 'Importing...' : 'Import'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Beacon Registry — searchable global database */}
      <div className="max-w-7xl mx-auto w-full px-4 py-6">
        <BeaconRegistryPanel />
      </div>

      {/* Control Point Registry — SoK Trig stations, KENCORS, benchmarks */}
      <div className="max-w-7xl mx-auto w-full px-4 pb-6">
        <ControlPointRegistry />
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { 
  signDocument, 
  verifySignature, 
  generateQRPayload, 
  parseQRPayload,
  createSurveyReportSignature,
  SignedDocument,
  QRVerificationResult
} from '@/lib/integrations/digitalSignature'

export default function DigitalSignaturePage() {
  const [validationMsg, setValidationMsg] = useState<string|null>(null)
  const [activeTab, setActiveTab] = useState<'sign' | 'verify'>('sign')
  const [signForm, setSignForm] = useState({
    documentId: '',
    content: '',
    signerId: '',
    secret: ''
  })
  const [verifyForm, setVerifyForm] = useState({
    qrPayload: '',
    originalContent: '',
    secret: ''
  })
  const [signedDoc, setSignedDoc] = useState<SignedDocument | null>(null)
  const [verificationResult, setVerificationResult] = useState<QRVerificationResult | null>(null)
  const [qrCode, setQrCode] = useState('')

  const handleSign = async () => {
    if (!signForm.documentId || !signForm.content || !signForm.signerId || !signForm.secret) {
      setValidationMsg('Please fill all required fields.'); return
    }
    const signed = await signDocument(
      signForm.documentId,
      signForm.content,
      signForm.signerId,
      signForm.secret
    )
    setSignedDoc(signed)
    setQrCode(generateQRPayload(signed))
  }

  const handleVerify = async () => {
    if (!verifyForm.qrPayload || !verifyForm.originalContent || !verifyForm.secret) {
      setValidationMsg('Please fill all required fields.'); return
    }
    const parsed = parseQRPayload(verifyForm.qrPayload)
    if (!parsed) {
      setVerificationResult({
        valid: false,
        message: 'Invalid QR payload format',
        verifiedAt: Date.now()
      })
      return
    }
    const result = await verifySignature(parsed, verifyForm.originalContent, verifyForm.secret)
    setVerificationResult(result)
  }

  const handleSurveySign = async () => {
    if (!signForm.signerId || !signForm.secret) {
      setValidationMsg('Please enter your signer ID and secret key.'); return
    }
    const measurements: Record<string, number> = {
      pointA_Easting: 500000.00,
      pointA_Northing: 9800000.00,
      pointB_Easting: 500100.00,
      pointB_Northing: 9800100.00,
      distance_AB: 141.42,
      bearing_AB_Value: 45.0
    }
    const signed = await createSurveyReportSignature(
      `SURVEY-${Date.now()}`,
      signForm.signerId,
      measurements,
      signForm.secret
    )
    setSignedDoc(signed)
    setQrCode(generateQRPayload(signed))
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-2">Digital Signature & QR Verification</h1>
        <p className="text-[var(--text-muted)] mb-8">Sign survey documents and verify signatures with QR codes</p>

        <div className="flex gap-2 mb-6">
          <button
            onClick={() => setActiveTab('sign')}
            className={`px-4 py-2 rounded-lg font-medium ${
              activeTab === 'sign' 
                ? 'bg-blue-600 text-white' 
                : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] border border-[var(--border-color)]'
            }`}
          >
            Sign Document
          </button>
          <button
            onClick={() => setActiveTab('verify')}
            className={`px-4 py-2 rounded-lg font-medium ${
              activeTab === 'verify' 
                ? 'bg-blue-600 text-white' 
                : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] border border-[var(--border-color)]'
            }`}
          >
            Verify Signature
          </button>
        </div>

        {activeTab === 'sign' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Sign a Document</h2>
            
            <div className="space-y-4 mb-6">
              <div>
                <label htmlFor="sig-document-id" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Document ID
                </label>
                <input
                  id="sig-document-id"
                  type="text"
                  value={signForm.documentId}
                  onChange={e => setSignForm({...signForm, documentId: e.target.value})}
                  aria-label="Document ID" placeholder="e.g., SURVEY-2024-001"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="sig-content" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Document Content
                </label>
                <textarea
                  id="sig-content"
                  value={signForm.content}
                  onChange={e => setSignForm({...signForm, content: e.target.value})}
                  placeholder="Enter document content to sign..."
                  rows={4}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="sig-signer-id" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Signer ID (License Number)
                </label>
                <input
                  id="sig-signer-id"
                  type="text"
                  value={signForm.signerId}
                  onChange={e => setSignForm({...signForm, signerId: e.target.value})}
                  aria-label="Signer ID (License Number)" placeholder="e.g., LS/2024/1234"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="sig-secret" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Secret Key
                </label>
                <input
                  id="sig-secret"
                  type="password"
                  value={signForm.secret}
                  onChange={e => setSignForm({...signForm, secret: e.target.value})}
                  aria-label="Secret key" placeholder="Enter signing secret"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
            </div>

            <div className="flex gap-3 mb-6">
              <button
                onClick={handleSign}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                Sign Document
              </button>
              <button
                onClick={handleSurveySign}
                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
              >
                Quick Survey Report Sign
              </button>
            </div>

            {signedDoc && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <h3 className="font-medium text-green-800 mb-2"> Document Signed Successfully</h3>
                <div className="text-sm text-green-700 space-y-1">
                  <p><strong>Document ID:</strong> {signedDoc.documentId}</p>
                  <p><strong>Signer:</strong> {signedDoc.signerId}</p>
                  <p><strong>Timestamp:</strong> {new Date(signedDoc.timestamp).toLocaleString()}</p>
                  <p><strong>Document Hash:</strong> <code className="text-xs">{signedDoc.documentHash}</code></p>
                  <p><strong>Signature:</strong> <code className="text-xs">{signedDoc.signature}</code></p>
                </div>
                
                {qrCode && (
                  <div className="mt-4 p-4 bg-[var(--bg-secondary)] rounded-lg border border-[var(--border-color)]">
                    <p className="text-sm font-medium text-[var(--text-secondary)] mb-2">QR Payload (Base64):</p>
                    <textarea
                      readOnly
                      value={qrCode}
                      className="w-full p-2 text-xs font-mono border rounded bg-[var(--bg-secondary)] text-[var(--text-primary)]"
                      rows={3}
                    />
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'verify' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Verify a Signature</h2>
            
            <div className="space-y-4 mb-6">
              <div>
                <label htmlFor="verify-qr" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  QR Payload (Base64)
                </label>
                <textarea
                  id="verify-qr"
                  value={verifyForm.qrPayload}
                  onChange={e => setVerifyForm({...verifyForm, qrPayload: e.target.value})}
                  placeholder="Paste QR payload from signed document..."
                  rows={3}
                  className="w-full p-2 border rounded-lg font-mono text-sm"
                />
              </div>
              <div>
                <label htmlFor="verify-original" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Original Document Content
                </label>
                <textarea
                  id="verify-original"
                  value={verifyForm.originalContent}
                  onChange={e => setVerifyForm({...verifyForm, originalContent: e.target.value})}
                  placeholder="Enter original document content..."
                  rows={4}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="verify-secret" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Secret Key
                </label>
                <input
                  id="verify-secret"
                  type="password"
                  value={verifyForm.secret}
                  onChange={e => setVerifyForm({...verifyForm, secret: e.target.value})}
                  aria-label="Secret key" placeholder="Enter signing secret"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
            </div>

            <button
              onClick={handleVerify}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 mb-6"
            >
              Verify Signature
            </button>

            {verificationResult && (
              <div className={`border rounded-lg p-4 ${
                verificationResult.valid 
                  ? 'bg-green-50 border-green-200' 
                  : 'bg-red-50 border-red-200'
              }`}>
                <h3 className={`font-medium mb-2 ${
                  verificationResult.valid ? 'text-green-800' : 'text-red-800'
                }`}>
                  {verificationResult.valid ? ' Signature Verified' : '[x] Verification Failed'}
                </h3>
                <p className="text-sm">{verificationResult.message}</p>
                <p className="text-xs text-[var(--text-muted)] mt-2">
                  Verified at: {new Date(verificationResult.verifiedAt).toLocaleString()}
                </p>
                
                {verificationResult.document && verificationResult.valid && (
                  <div className="mt-4 text-sm text-green-700">
                    <p><strong>Document ID:</strong> {verificationResult.document.documentId}</p>
                    <p><strong>Signer:</strong> {verificationResult.document.signerId}</p>
                    <p><strong>Signed:</strong> {new Date(verificationResult.document.timestamp).toLocaleString()}</p>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import {
  Upload, Cloud, Loader2, CheckCircle2, XCircle, Download,
  Map as MapIcon, Box, Mountain, FileCode, ChevronRight, RefreshCw,
} from 'lucide-react'
import Link from 'next/link'
import { logger } from '@/lib/logger'

// ─── Types ──────────────────────────────────────────────────────────────────

type TaskStatus = 'uploading' | 'queued' | 'running' | 'completed' | 'failed' | 'imported'

interface DroneTask {
  id: string
  name: string
  photo_count: number
  total_size_mb: number
  status: TaskStatus
  progress: number
  error_message?: string
  orthophoto_path?: string
  pointcloud_path?: string
  dsm_path?: string
  dtm_path?: string
  contour_path?: string
  created_at: string
  processing_completed_at?: string
}

// ─── Upload Section ─────────────────────────────────────────────────────────

function UploadSection({ onTaskCreated }: { onTaskCreated: (taskId: string) => void }) {
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState(0)
  const [taskName, setTaskName] = useState(`Drone Survey ${new Date().toLocaleDateString()}`)
  const [selectedFiles, setSelectedFiles] = useState<File[]>([])
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || [])
    setSelectedFiles(prev => [...prev, ...files])
    setError(null)
  }

  const handleUpload = async () => {
    if (selectedFiles.length === 0) {
      setError('Select at least one photo')
      return
    }

    setUploading(true)
    setProgress(0)
    setError(null)

    try {
      const formData = new FormData()
      formData.append('name', taskName)
      selectedFiles.forEach(f => formData.append('photos', f))

      // Simulate progress while uploading (we can't get real progress from fetch)
      const progressInterval = setInterval(() => {
        setProgress(p => Math.min(p + 5, 90))
      }, 500)

      const res = await fetch('/api/drone/upload', {
        method: 'POST',
        body: formData,
      })

      clearInterval(progressInterval)
      setProgress(100)

      if (!res.ok) {
        const data = (await res.json()) as { error?: string }
        throw new Error(data.error || `Upload failed (${res.status})`)
      }

      const data = (await res.json()) as { taskId: string }
      onTaskCreated(data.taskId)
      setSelectedFiles([])
      if (fileInputRef.current) fileInputRef.current.value = ''
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed')
    } finally {
      setUploading(false)
      setTimeout(() => setProgress(0), 1000)
    }
  }

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6">
      <div className="flex items-center gap-3 mb-4">
        <Upload className="w-5 h-5 text-[var(--accent)]" />
        <h2 className="text-lg font-bold text-[var(--text-primary)]">1. Upload Drone Photos</h2>
      </div>

      <div className="space-y-4">
        {/* Task name */}
        <div>
          <label htmlFor="drone-survey-name" className="block text-sm text-[var(--text-muted)] mb-2">Survey Name</label>
          <input
            id="drone-survey-name"
            type="text"
            value={taskName}
            onChange={e => setTaskName(e.target.value)}
            className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)] focus:border-[var(--accent)] outline-none"
          />
        </div>

        {/* File input */}
        <div>
          <label htmlFor="drone-photos" className="block text-sm text-[var(--text-muted)] mb-2">Photos (JPG, PNG, or TIFF — max 25MB each, max 200 photos)</label>
          <div
            onClick={() => fileInputRef.current?.click()}
            className="border-2 border-dashed border-[var(--border-color)] rounded-lg p-8 text-center cursor-pointer hover:border-[var(--accent)] transition-colors"
          >
            <Upload className="w-8 h-8 text-[var(--text-muted)] mx-auto mb-2" />
            <p className="text-sm text-[var(--text-secondary)]">
              {selectedFiles.length > 0
                ? `${selectedFiles.length} photo${selectedFiles.length !== 1 ? 's' : ''} selected (${Math.round(selectedFiles.reduce((s, f) => s + f.size, 0) / 1024 / 1024)}MB)`
                : 'Click to select photos'}
            </p>
          </div>
          <input
            ref={fileInputRef}
            id="drone-photos"
            type="file"
            multiple
            accept=".jpg,.jpeg,.png,.tif,.tiff"
            onChange={handleFileSelect}
            className="hidden"
          />
        </div>

        {/* Selected files list */}
        {selectedFiles.length > 0 && (
          <div className="max-h-32 overflow-y-auto space-y-1">
            {selectedFiles.slice(0, 5).map((f, i) => (
              <div key={i} className="text-xs text-[var(--text-muted)] flex justify-between">
                <span className="truncate">{f.name}</span>
                <span className="shrink-0 ml-2">{(f.size / 1024 / 1024).toFixed(1)}MB</span>
              </div>
            ))}
            {selectedFiles.length > 5 && (
              <p className="text-xs text-[var(--text-muted)]">...and {selectedFiles.length - 5} more</p>
            )}
          </div>
        )}

        {/* Upload progress */}
        {uploading && (
          <div className="space-y-1">
            <div className="flex justify-between text-xs text-[var(--text-muted)]">
              <span>Uploading {selectedFiles.length} photos...</span>
              <span>{progress}%</span>
            </div>
            <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
              <div
                className="h-full bg-[var(--accent)] transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {error && (
          <p className="text-xs text-red-400 bg-red-500/10 rounded-lg p-2">{error}</p>
        )}

        <button
          onClick={handleUpload}
          disabled={uploading || selectedFiles.length === 0}
          className="w-full py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm flex items-center justify-center gap-2"
        >
          {uploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
          {uploading ? 'Uploading...' : `Upload ${selectedFiles.length} Photo${selectedFiles.length !== 1 ? 's' : ''}`}
        </button>
      </div>
    </div>
  )
}

// ─── Processing Section ─────────────────────────────────────────────────────

function ProcessingSection({ taskId }: { taskId: string }) {
  const [task, setTask] = useState<DroneTask | null>(null)
  const [processing, setProcessing] = useState(false)
  const [options, setOptions] = useState({
    demResolution: 5,
    orthophotoResolution: 5,
    dsm: true,
    dtm: true,
    contourResolution: 0.5,
  })

  const fetchTask = useCallback(async () => {
    const res = await fetch(`/api/drone/process?taskId=${taskId}`)
    if (res.ok) {
      const data = (await res.json()) as { task: DroneTask }
      setTask(data.task)
    }
  }, [taskId])

  useEffect(() => {
    fetchTask()

    // Poll every 5 seconds if task is running
    const interval = setInterval(() => {
      if (task && (task.status === 'queued' || task.status === 'running')) {
        fetchTask()
      }
    }, 5000)

    return () => clearInterval(interval)
  }, [fetchTask, task])

  const startProcessing = async () => {
    setProcessing(true)
    try {
      const res = await fetch('/api/drone/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ taskId, ...options }),
      })

      if (!res.ok) {
        const data = (await res.json()) as { error?: string }
        throw new Error(data.error || 'Failed to start processing')
      }

      await fetchTask()
    } catch (err) {
      logger.error(err instanceof Error ? err.message : String(err))
    } finally {
      setProcessing(false)
    }
  }

  if (!task) return <div className="animate-pulse">Loading task...</div>

  const isProcessing = task.status === 'queued' || task.status === 'running'
  const isCompleted = task.status === 'completed'
  const isFailed = task.status === 'failed'

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6">
      <div className="flex items-center gap-3 mb-4">
        <Cloud className="w-5 h-5 text-[var(--accent)]" />
        <h2 className="text-lg font-bold text-[var(--text-primary)]">2. Process Photos</h2>
      </div>

      {/* Task summary */}
      <div className="grid grid-cols-3 gap-3 mb-4 text-center">
        <div className="bg-[var(--bg-tertiary)] rounded-lg p-2">
          <p className="text-lg font-bold text-[var(--text-primary)]">{task.photo_count}</p>
          <p className="text-[10px] text-[var(--text-muted)] uppercase">Photos</p>
        </div>
        <div className="bg-[var(--bg-tertiary)] rounded-lg p-2">
          <p className="text-lg font-bold text-[var(--text-primary)]">{Math.round(task.total_size_mb)}</p>
          <p className="text-[10px] text-[var(--text-muted)] uppercase">MB</p>
        </div>
        <div className="bg-[var(--bg-tertiary)] rounded-lg p-2">
          <p className="text-lg font-bold capitalize" style={{
            color: isCompleted ? '#34d399' : isFailed ? '#ef4444' : isProcessing ? '#f59e0b' : 'var(--text-primary)'
          }}>
            {task.status}
          </p>
          <p className="text-[10px] text-[var(--text-muted)] uppercase">Status</p>
        </div>
      </div>

      {/* Processing options (only show before processing starts) */}
      {!isProcessing && !isCompleted && (
        <div className="space-y-3 mb-4">
          <p className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Processing Options</p>
          <div className="grid grid-cols-2 gap-3">
            <label className="text-xs text-[var(--text-muted)]">
              Orthophoto Resolution (cm/px)
              <input
                type="number"
                value={options.orthophotoResolution}
                onChange={e => setOptions(o => ({ ...o, orthophotoResolution: +e.target.value }))}
                className="w-full mt-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-[var(--text-primary)]"
                min={1}
                max={50}
              />
            </label>
            <label className="text-xs text-[var(--text-muted)]">
              DSM Resolution (cm/px)
              <input
                type="number"
                value={options.demResolution}
                onChange={e => setOptions(o => ({ ...o, demResolution: +e.target.value }))}
                className="w-full mt-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-[var(--text-primary)]"
                min={1}
                max={50}
              />
            </label>
            <label className="text-xs text-[var(--text-muted)]">
              Contour Interval (m)
              <input
                type="number"
                step="0.1"
                value={options.contourResolution}
                onChange={e => setOptions(o => ({ ...o, contourResolution: +e.target.value }))}
                className="w-full mt-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-[var(--text-primary)]"
                min={0.1}
                max={10}
              />
            </label>
            <div className="flex items-center gap-3 pt-4">
              <label className="flex items-center gap-1.5 text-xs text-[var(--text-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={options.dsm}
                  onChange={e => setOptions(o => ({ ...o, dsm: e.target.checked }))}
                  className="rounded"
                />
                DSM
              </label>
              <label className="flex items-center gap-1.5 text-xs text-[var(--text-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={options.dtm}
                  onChange={e => setOptions(o => ({ ...o, dtm: e.target.checked }))}
                  className="rounded"
                />
                DTM
              </label>
            </div>
          </div>
        </div>
      )}

      {/* Progress bar (when processing) */}
      {isProcessing && (
        <div className="space-y-2 mb-4">
          <div className="flex justify-between text-xs">
            <span className="text-[var(--text-muted)]">
              {task.status === 'queued' ? 'Queued for processing...' : 'Processing photos...'}
            </span>
            <span className="text-[var(--accent)] font-semibold">{task.progress}%</span>
          </div>
          <div className="h-3 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-[var(--accent)] to-amber-500 transition-all duration-500"
              style={{ width: `${task.progress}%` }}
            />
          </div>
          <p className="text-[10px] text-[var(--text-muted)]">
            Processing can take 10-60 minutes depending on photo count and resolution. This page auto-refreshes every 5 seconds.
          </p>
        </div>
      )}

      {/* Error message */}
      {isFailed && task.error_message && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4">
          <p className="text-xs text-red-400 font-semibold">Processing Failed</p>
          <p className="text-xs text-[var(--text-muted)] mt-1">{task.error_message}</p>
        </div>
      )}

      {/* Start button */}
      {!isProcessing && !isCompleted && (
        <button
          onClick={startProcessing}
          disabled={processing || task.photo_count === 0}
          className="w-full py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm flex items-center justify-center gap-2"
        >
          {processing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Cloud className="w-4 h-4" />}
          {processing ? 'Starting...' : 'Start Processing'}
        </button>
      )}

      {/* Refresh button (when processing) */}
      {isProcessing && (
        <button
          onClick={fetchTask}
          className="w-full py-2 border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors flex items-center justify-center gap-1.5"
        >
          <RefreshCw className="w-3 h-3" /> Refresh Status
        </button>
      )}
    </div>
  )
}

// ─── Results Section ────────────────────────────────────────────────────────

function ResultsSection({ taskId }: { taskId: string }) {
  const [task, setTask] = useState<DroneTask | null>(null)

  useEffect(() => {
    fetch(`/api/drone/process?taskId=${taskId}`)
      .then(r => r.ok ? r.json() : null)
      .then((data: { task?: DroneTask } | null) => { if (data?.task) setTask(data.task) })
  }, [taskId])

  if (!task || task.status !== 'completed') return null

  const outputs = [
    { label: 'Orthophoto', path: task.orthophoto_path, icon: MapIcon, href: '/tools/orthophoto-viewer', desc: 'Georeferenced aerial image' },
    { label: 'Point Cloud', path: task.pointcloud_path, icon: Box, href: '/tools/point-cloud-import', desc: '3D LAS point cloud' },
    { label: 'DSM', path: task.dsm_path, icon: Mountain, href: '/tools/contour-generator', desc: 'Digital Surface Model' },
    { label: 'DTM', path: task.dtm_path, icon: Mountain, href: '/tools/contour-generator', desc: 'Digital Terrain Model' },
    { label: 'Contours', path: task.contour_path, icon: FileCode, href: '/tools/contour-generator', desc: 'Contour lines (GeoJSON)' },
  ].filter(o => o.path)

  if (outputs.length === 0) return null

  return (
    <div className="rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-6">
      <div className="flex items-center gap-3 mb-4">
        <CheckCircle2 className="w-5 h-5 text-emerald-400" />
        <h2 className="text-lg font-bold text-[var(--text-primary)]">3. Import Results</h2>
      </div>

      <p className="text-sm text-[var(--text-secondary)] mb-4">
        Processing complete. {outputs.length} output{outputs.length !== 1 ? 's' : ''} available.
        Click any result to open it in the corresponding METARDU tool.
      </p>

      <div className="grid gap-3 sm:grid-cols-2">
        {outputs.map(output => {
          const Icon = output.icon
          return (
            <Link
              key={output.label}
              href={output.href}
              className="group flex items-center gap-3 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-3 hover:border-emerald-500/30 transition-all"
            >
              <div className="w-10 h-10 rounded-lg bg-emerald-500/10 flex items-center justify-center shrink-0">
                <Icon className="w-5 h-5 text-emerald-400" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-[var(--text-primary)]">{output.label}</p>
                <p className="text-[10px] text-[var(--text-muted)] truncate">{output.desc}</p>
              </div>
              <ChevronRight className="w-4 h-4 text-[var(--text-muted)] group-hover:text-emerald-400 transition-colors" />
            </Link>
          )
        })}
      </div>
    </div>
  )
}

// ─── Task History ───────────────────────────────────────────────────────────

function TaskHistory({ refreshKey }: { refreshKey: number }) {
  const [tasks, setTasks] = useState<DroneTask[]>([])

  useEffect(() => {
    fetch('/api/drone/tasks?limit=10')
      .then(r => r.ok ? r.json() : null)
      .then((data: { tasks?: DroneTask[] } | null) => { if (data?.tasks) setTasks(data.tasks) })
  }, [refreshKey])

  if (tasks.length === 0) return null

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6">
      <h2 className="text-lg font-bold text-[var(--text-primary)] mb-4">Recent Drone Surveys</h2>
      <div className="space-y-2">
        {tasks.map(task => (
          <div
            key={task.id}
            className="flex items-center justify-between rounded-lg border border-[var(--border-color)] p-3 hover:bg-[var(--bg-tertiary)] transition-colors"
          >
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-[var(--text-primary)] truncate">{task.name}</p>
              <p className="text-xs text-[var(--text-muted)]">
                {task.photo_count} photos · {Math.round(task.total_size_mb)}MB · {new Date(task.created_at).toLocaleDateString()}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {task.status === 'completed' && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
              {task.status === 'failed' && <XCircle className="w-4 h-4 text-red-400" />}
              {(task.status === 'queued' || task.status === 'running') && <Loader2 className="w-4 h-4 text-amber-400 animate-spin" />}
              <span className="text-xs capitalize text-[var(--text-muted)]">{task.status}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

// ─── Main Page ──────────────────────────────────────────────────────────────

export default function DronePage() {
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null)
  const [refreshKey, setRefreshKey] = useState(0)

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <PageHeader
        title="Drone Photogrammetry"
        subtitle="Upload drone photos → process to orthophoto + point cloud + contours → import to METARDU tools"
        reference="WebODM integration · Orthophoto · Point Cloud · DSM/DTM · Contours"
      />

      <div className="mt-6 space-y-6">
        {/* Info banner */}
        <div className="rounded-xl bg-[var(--accent)]/10 border border-[var(--accent)]/20 p-4 text-sm text-[var(--text-secondary)]">
          <p>
            <span className="font-semibold text-[var(--accent)]">How it works:</span>{' '}
            Upload your drone photos (JPG/PNG/TIFF), then METARDU sends them to WebODM
            for photogrammetry processing. Results (orthophoto, point cloud, DSM/DTM, contours)
            are automatically downloaded and can be opened in METARDU&apos;s existing tools.
          </p>
        </div>

        {/* Step 1: Upload */}
        <UploadSection onTaskCreated={(taskId) => {
          setActiveTaskId(taskId)
          setRefreshKey(k => k + 1)
        }} />

        {/* Step 2: Process (only show if a task is active) */}
        {activeTaskId && (
          <ProcessingSection taskId={activeTaskId} />
        )}

        {/* Step 3: Results (only show if completed) */}
        {activeTaskId && (
          <ResultsSection taskId={activeTaskId} />
        )}

        {/* Task history */}
        <TaskHistory refreshKey={refreshKey} />
      </div>
    </div>
  )
}

'use client';
import { useState, useRef, useCallback } from 'react';
import { MapLayer, GeoPDFLayer, MBTilesSession } from '@/types/field';
import { parseKML, parseKMZ } from '@/lib/field/kml';
import { uploadMBTiles } from '@/lib/field/mbtiles';
import type { MapHandle } from '@/components/field/MapViewer';
import {
  ArrowLeft,
  Plus,
  Minus,
  MapPin,
  Navigation,
  Upload,
  FileText,
  Database,
  Eye,
  EyeOff,
  Download,
  X,
  ChevronLeft,
  Layers,
} from 'lucide-react';
import Link from 'next/link';
import dynamic from 'next/dynamic';

import MapViewer from '@/components/field/MapViewer';

/* ── Non-OL imports (safe to import at module level) ──────────────── */
const GeoPDFImport = dynamic(() => import('@/components/field/GeoPDFImport'), {
  ssr: false,
  loading: () => (
    <div className="p-4 text-white/50 text-sm">Loading GeoPDF importer…</div>
  ),
});

/* ================================================================== */
/*  FIELD MAP PAGE — Full-bleed map with zero-obstruction overlays      */
/* ================================================================== */

export default function FieldMapPage() {
  /* ── State ──────────────────────────────────────────────────────── */
  const mapRef = useRef<MapHandle>(null);
  const [layers, setLayers] = useState<MapLayer[]>([]);
  const [geoPDFLayers, setGeoPDFLayers] = useState<GeoPDFLayer[]>([]);
  const [mbtilesSessions, setMBTilesSessions] = useState<MBTilesSession[]>([]);
  const [mbtilesLoading, setMBTilesLoading] = useState(false);
  const [geoPDFOpen, setGeoPDFOpen] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [gpsActive, setGpsActive] = useState(false);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);
  const [gpsLocation, setGpsLocation] = useState<{lat: number, lng: number} | null>(null);
  const [gpsWatchId, setGpsWatchId] = useState<number | null>(null);
  const [tooltip, setTooltip] = useState<string | null>(null);
  const kmlInputRef = useRef<HTMLInputElement>(null);
  const drawerTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /* ── KML / KMZ import handler ──────────────────────────────────── */
  const handleKMLImport = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const ext = file.name.split('.').pop()?.toLowerCase();
    try {
      let geojson: GeoJSON.FeatureCollection;
      if (ext === 'kml') geojson = await parseKML(await file.text());
      else if (ext === 'kmz') geojson = await parseKMZ(await file.arrayBuffer());
      else return;
      setLayers(prev => [...prev, {
        id: `layer_${Date.now()}`, name: file.name,
        type: ext as 'kml' | 'kmz', geojson, visible: true, loadedAt: Date.now(),
      }]);
    } catch (err) {
      alert(`Parse error: ${(err as Error).message}`);
    }
    // Reset input so same file can be re-imported
    e.target.value = '';
  }, []);

  /* ── MBTiles import handler ─────────────────────────────────────── */
  const handleMBTilesImport = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setMBTilesLoading(true);
    try {
      const session = await uploadMBTiles(file);
      setMBTilesSessions(prev => [...prev, session]);
    } catch (err) {
      alert(`MBTiles error: ${(err as Error).message}`);
    } finally {
      setMBTilesLoading(false);
    }
    e.target.value = '';
  }, []);

  /* ── GeoPDF layer ready callback ───────────────────────────────── */
  const handleGeoPDFReady = useCallback((layer: GeoPDFLayer) => {
    setGeoPDFLayers(prev => [...prev, layer]);
    setGeoPDFOpen(false);
  }, []);

  /* ── Layer visibility toggle ────────────────────────────────────── */
  const toggleLayer = useCallback((id: string) => {
    setLayers(prev => prev.map(l => l.id === id ? { ...l, visible: !l.visible } : l));
  }, []);

  /* ── Export handlers ───────────────────────────────────────────── */
  const exportKML = useCallback(() => {
    const visibleLayers = layers.filter(l => l.visible && l.geojson);
    if (visibleLayers.length === 0) { alert('No visible layers to export.'); return; }
    const firstLayer = visibleLayers[0]
    if (!firstLayer?.geojson) return
    const geojson = firstLayer.geojson
    const kmlContent = jsonToKML(geojson);
    const blob = new Blob([kmlContent], { type: 'application/vnd.google-earth.kml+xml' });
    downloadBlob(blob, 'metardu-export.kml');
    setDrawerOpen(false);
  }, [layers]);

  const exportCSV = useCallback(() => {
    const visibleLayers = layers.filter(l => l.visible && l.geojson);
    if (visibleLayers.length === 0) { alert('No visible layers to export.'); return; }
    const firstLayer = visibleLayers[0]
    if (!firstLayer?.geojson) return
    const features = firstLayer.geojson.features;
    const header = 'name,latitude,longitude\n';
    const rows = features.map((f: GeoJSON.Feature) => {
      const coords = f.geometry && f.geometry.type === 'Point' ? (f.geometry as GeoJSON.Point).coordinates : null;
      const props = (f.properties || {}) as Record<string, unknown>;
      const name = String(props.name || props.Name || '');
      return coords ? `${name},${coords[1]?.toFixed(8)},${coords[0]?.toFixed(8)}` : '';
    }).join('\n');
    const blob = new Blob([header + rows], { type: 'text/csv' });
    downloadBlob(blob, 'metardu-export.csv');
    setDrawerOpen(false);
  }, [layers]);

  /* ── GPS toggle ────────────────────────────────────────────────── */
  const toggleGPS = useCallback(() => {
    if (gpsActive && gpsWatchId !== null) {
      navigator.geolocation.clearWatch(gpsWatchId);
      setGpsWatchId(null);
      setGpsActive(false);
      setGpsAccuracy(null);
      return;
    }
    if (!navigator.geolocation) { alert('Geolocation not available.'); return; }
    setGpsActive(true);
    const id = navigator.geolocation.watchPosition(
      (pos) => {
        setGpsAccuracy(pos.coords.accuracy);
        setGpsLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      },
      () => { setGpsActive(false); setGpsAccuracy(null); setGpsLocation(null); },
      { enableHighAccuracy: true, maximumAge: 2000 },
    );
    setGpsWatchId(id);
  }, [gpsActive, gpsWatchId]);

  /* ── Cleanup GPS on unmount ───────────────────────────────────── */
  useState(() => {
    return () => {
      if (gpsWatchId !== null) navigator.geolocation.clearWatch(gpsWatchId);
    };
  });

  /* ── Tooltip helpers (accessible: hover + long-press fallback) ───── */
  const showTooltip = useCallback((label: string) => setTooltip(label), []);
  const hideTooltip = useCallback(() => setTooltip(null), []);

  /* ── Drawer open/close with safe timeout ───────────────────────── */
  const openDrawer = useCallback(() => {
    if (drawerTimeoutRef.current) clearTimeout(drawerTimeoutRef.current);
    setDrawerOpen(true);
  }, []);
  const closeDrawer = useCallback(() => {
    if (drawerTimeoutRef.current) clearTimeout(drawerTimeoutRef.current);
    drawerTimeoutRef.current = setTimeout(() => setDrawerOpen(false), 220);
  }, []);

  /* ── Render ───────────────────────────────────────────────────── */
  return (
    <div className="relative w-full overflow-hidden bg-[var(--bg-primary)]" style={{ height: '100dvh' }}>
      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  MAP — FULL BLEED (absolute, no padding)                    */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div className="absolute inset-0">
        <MapViewer
          ref={mapRef}
          layers={layers}
          beacons={[]}
          parcels={[]}
          geoPDFLayers={geoPDFLayers}
          mbtilesSessions={mbtilesSessions}
          gpsLocation={gpsLocation}
          gpsAccuracy={gpsAccuracy}
        />
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  TOP-LEFT — Project title bar (max 48px, semi-transparent)   */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div
        className="absolute top-0 left-0 z-10 flex items-center gap-2 px-3 text-white"
        style={{
          paddingTop: 'env(safe-area-inset-top, 0px)',
          height: 'calc(48px + env(safe-area-inset-top, 0px))',
          background: 'rgba(0,0,0,0.55)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
        }}
      >
        <Link href="/field" aria-label="Back to Field Hub">
          <ArrowLeft className="w-5 h-5 text-white/80 hover:text-white transition-colors" />
        </Link>
        <span className="text-sm font-semibold truncate max-w-[200px]">Field Map</span>
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  TOP-RIGHT — Zoom controls + Kenya reset                    */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div
        className="absolute z-10 flex flex-col items-center gap-1.5"
        style={{
          top: 'calc(16px + env(safe-area-inset-top, 0px))',
          right: 16,
        }}
      >
        {/* Zoom In */}
        <button
          onClick={() => mapRef.current?.zoomIn()}
          onMouseEnter={() => showTooltip('Zoom In')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Zoom In')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-xl bg-slate-900 text-white hover:bg-slate-800 active:scale-95 transition-all shadow-md"
          aria-label="Zoom In"
        >
          <Plus className="w-5 h-5" />
        </button>
        {/* Zoom Out */}
        <button
          onClick={() => mapRef.current?.zoomOut()}
          onMouseEnter={() => showTooltip('Zoom Out')}
          onMouseLeave={hideTooltip}
          className="w-12 h-12 flex items-center justify-center rounded-xl bg-slate-900 text-white hover:bg-slate-800 active:scale-95 transition-all shadow-md"
          aria-label="Zoom Out"
        >
          <Minus className="w-5 h-5" />
        </button>
        {/* Kenya Reset */}
        <button
          onClick={() => mapRef.current?.resetToKenya()}
          onMouseEnter={() => showTooltip('Reset to Kenya')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Reset to Kenya')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-xl bg-[#D17B47] text-white hover:bg-[#b06335] active:scale-95 transition-all font-bold text-xs shadow-md"
          aria-label="Reset to Kenya view"
        >
          KEN
        </button>
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  BOTTOM-LEFT — GPS status badge                              */}
      {/* ═══════════════════════════════════════════════════════════ */}
      {gpsActive && gpsAccuracy !== null && (
        <div
          className="absolute z-10 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-slate-900 text-white text-xs font-mono shadow-md"
          style={{
            bottom: 'calc(16px + env(safe-area-inset-bottom, 0px))',
            left: 16,
          }}
        >
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-green-400" />
          </span>
          GPS &plusmn;{gpsAccuracy.toFixed(1)}m
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  BOTTOM-RIGHT — FAB stack: Perimeter → GPS Beacon → Import   */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div
        className="absolute z-10 flex flex-col items-center gap-3"
        style={{
          bottom: 'calc(16px + env(safe-area-inset-bottom, 0px))',
          right: 16,
        }}
      >
        {/* Perimeter Walk */}
        <button
          onClick={() => {
            /* Navigate to the walk page */
            window.location.href = '/field/walk';
          }}
          onMouseEnter={() => showTooltip('Perimeter Walk')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Perimeter Walk')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-[#D17B47] text-white shadow-lg shadow-orange-900/30 hover:shadow-orange-800/40 active:scale-95 transition-all"
          aria-label="Perimeter Walk"
        >
          <MapPin className="w-5 h-5" />
        </button>
        {/* GPS Beacon */}
        <button
          onClick={toggleGPS}
          onMouseEnter={() => showTooltip(gpsActive ? 'Stop GPS' : 'GPS Beacon')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip(gpsActive ? 'Stop GPS' : 'GPS Beacon')}
          onTouchEnd={() => { hideTooltip(); }}
          className={`w-12 h-12 flex items-center justify-center rounded-full shadow-lg transition-all active:scale-95 ${
            gpsActive
              ? 'bg-green-600 text-white shadow-green-900/30'
              : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
          aria-label={gpsActive ? 'Stop GPS' : 'Start GPS'}
        >
          <Navigation className="w-5 h-5" />
        </button>
        {/* Import KML */}
        <button
          onClick={() => kmlInputRef.current?.click()}
          onMouseEnter={() => showTooltip('Import KML')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Import KML')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-slate-900 text-white hover:bg-slate-800 shadow-lg active:scale-95 transition-all"
          aria-label="Import KML"
        >
          <Upload className="w-5 h-5" />
        </button>
        {/* Hidden file input for KML */}
        <input
          ref={kmlInputRef}
          type="file"
          accept=".kml,.kmz"
          className="hidden"
          onChange={handleKMLImport}
        />
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  LEFT EDGE — Export drawer (24px tab → 240px panel)          */}
      {/* ═══════════════════════════════════════════════════════════ */}

      {/* Backdrop — only visible when drawer is open */}
      {drawerOpen && (
        <div
          className="absolute inset-0 z-20"
          style={{ backgroundColor: 'transparent' }}
          onClick={closeDrawer}
        />
      )}

      {/* Drawer panel */}
      <div
        className="absolute z-30 top-0 left-0 h-full transition-transform duration-300 ease-out"
        style={{
          transform: drawerOpen ? 'translateX(0)' : 'translateX(-240px)',
          paddingTop: 'env(safe-area-inset-top, 0px)',
          paddingBottom: 'env(safe-area-inset-bottom, 0px)',
        }}
      >
        {/* Drawer body */}
        <div
          className="h-full flex flex-col bg-slate-900 border-r border-white/[0.08] text-white"
          style={{ width: 'min(240px, 65vw)' }}
        >
          {/* Drawer header */}
          <div className="flex items-center justify-between px-3 py-2.5 border-b border-white/[0.08]">
            <span className="text-xs font-semibold uppercase tracking-wider text-white/70">Export &amp; Layers</span>
            <button
              onClick={closeDrawer}
              className="w-10 h-10 flex items-center justify-center rounded-lg text-white/50 hover:text-white hover:bg-white/[0.08] transition-colors"
              aria-label="Close drawer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Drawer content */}
          <div className="flex-1 overflow-y-auto p-3 space-y-4">
            {/* Export section */}
            <div>
              <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Export</p>
              <button
                onClick={exportKML}
                className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white transition-colors"
              >
                <Download className="w-4 h-4 text-blue-400" />
                <span>Export as KML</span>
              </button>
              <button
                onClick={exportCSV}
                className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white transition-colors mt-1"
              >
                <Download className="w-4 h-4 text-green-400" />
                <span>Export as CSV</span>
              </button>
            </div>

            {/* Import section */}
            <div>
              <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Import</p>
              <label className="flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white cursor-pointer transition-colors">
                <Upload className="w-4 h-4 text-orange-400" />
                <span>Import MBTiles</span>
                <input type="file" accept=".mbtiles" className="hidden" onChange={handleMBTilesImport} disabled={mbtilesLoading} />
              </label>
              <button
                onClick={() => { setGeoPDFOpen(true); setDrawerOpen(false); }}
                className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white transition-colors mt-1"
              >
                <FileText className="w-4 h-4 text-purple-400" />
                <span>Import GeoPDF</span>
              </button>
            </div>

            {/* Layer list */}
            {layers.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Layers ({layers.length})</p>
                <div className="space-y-1">
                  {layers.map(l => (
                    <button
                      key={l.id}
                      onClick={() => toggleLayer(l.id)}
                      className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-xs transition-colors ${
                        l.visible
                          ? 'bg-blue-500/10 text-blue-300'
                          : 'bg-white/[0.02] text-white/40'
                      }`}
                    >
                      {l.visible ? <Eye className="w-3.5 h-3.5 flex-shrink-0" /> : <EyeOff className="w-3.5 h-3.5 flex-shrink-0" />}
                      <span className="truncate">{l.name}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* MBTiles sessions */}
            {mbtilesSessions.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Tile Sessions</p>
                <div className="space-y-1">
                  {mbtilesSessions.map(s => (
                    <div key={s.key} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-orange-500/10 text-orange-300 text-xs">
                      <Database className="w-3.5 h-3.5 flex-shrink-0" />
                      <span className="truncate">{s.name}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* GeoPDF sessions */}
            {geoPDFLayers.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">GeoPDF Layers</p>
                <div className="space-y-1">
                  {geoPDFLayers.map(g => (
                    <div key={g.id} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-purple-500/10 text-purple-300 text-xs">
                      <FileText className="w-3.5 h-3.5 flex-shrink-0" />
                      <span className="truncate">{g.name}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Collapsed drawer tab — visible when drawer is closed */}
      {!drawerOpen && (
        <button
          onClick={openDrawer}
