'use client'

import { useEffect, useState, useRef } from 'react'
import type Map from 'ol/Map'

/**
 * NorthArrowOverlay — always-on north arrow that rotates inversely to map rotation.
 *
 * Surveyors rotate maps constantly in the field. "Which way is north?" should
 * never require opening a panel. This component listens to the OpenLayers view's
 * rotation change event and rotates the arrow to always point to true north.
 *
 * Uses v0.3 design tokens (sienna accent on tinted dark bg).
 */

interface NorthArrowOverlayProps {
  /** Ref to the OpenLayers map instance */
  mapInstance: React.MutableRefObject<Map | null>
}

export function NorthArrowOverlay({ mapInstance }: NorthArrowOverlayProps) {
  const [rotation, setRotation] = useState(0)
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const map = mapInstance.current
    if (!map) return

    const view = map.getView()
    if (!view) return

    // Initial rotation
    setRotation((view.getRotation() * 180) / Math.PI)
    setVisible(true)

    // Listen for rotation changes
    const onRotate = () => {
      setRotation((view.getRotation() * 180) / Math.PI)
    }
    view.on('change:rotation', onRotate)

    return () => {
      view.un('change:rotation', onRotate)
    }
  }, [mapInstance])

  if (!visible) return null

  return (
    <div
      className="flex flex-col items-center select-none pointer-events-none"
      aria-label={`North arrow, map rotation ${rotation.toFixed(1)} degrees`}
    >
      <div
        style={{ transform: `rotate(${-rotation}deg)`, transition: 'transform 100ms linear' }}
        className="flex flex-col items-center"
      >
        <svg width="36" height="48" viewBox="0 0 36 48" fill="none" xmlns="http://www.w3.org/2000/svg">
          {/* N label */}
          <text x="18" y="6" textAnchor="middle" fontSize="10" fontWeight="700" fill="var(--accent)" fontFamily="JetBrains Mono, monospace">
            N
          </text>
          {/* Arrow head — sienna filled triangle */}
          <polygon points="18,8 12,22 18,18 24,22" fill="var(--accent)" />
          {/* Arrow shaft */}
          <line x1="18" y1="18" x2="18" y2="44" stroke="var(--accent)" strokeWidth="2" />
          {/* Arrow tail — open */}
          <polygon points="18,46 14,38 18,40 22,38" fill="none" stroke="var(--text-muted)" strokeWidth="1" />
        </svg>
      </div>
      {Math.abs(rotation) > 0.5 && (
        <div className="mt-1 px-1.5 py-0.5 bg-[var(--bg-card)] border border-[var(--border-color)] font-mono text-[9px] text-[var(--text-muted)] tracking-[0.04em]">
          {rotation.toFixed(0)}°
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * SnappingOptions — Configurable snapping for precise digitizing
 *
 * QGIS-inspired snapping configuration:
 * - Snap to: vertices, edges, intersections
 * - Tolerance: adjustable in meters
 * - Enabled/disabled per layer
 * - Snap mode: vertex, segment, vertex+segment
 */

import { useState, useCallback } from 'react'
import { Magnet, Settings2, X } from 'lucide-react'

type SnapMode = 'vertex' | 'segment' | 'vertex_segment'
type SnapType = 'osm' | 'parcels' | 'beacons' | 'grid' | 'all'

interface SnappingOptionsProps {
  open: boolean
  onClose: () => void
  enabled: boolean
  onToggleEnabled: () => void
  mode?: SnapMode
  onModeChange?: (mode: SnapMode) => void
  tolerance?: number
  onToleranceChange?: (tolerance: number) => void
  snapTypes?: Set<SnapType>
  onSnapTypeToggle?: (type: SnapType) => void
}

const SNAP_MODE_LABELS: Record<SnapMode, string> = {
  vertex: 'Vertex only',
  segment: 'Segment only',
  vertex_segment: 'Vertex + Segment',
}

const SNAP_TYPE_LABELS: Record<SnapType, string> = {
  osm: 'Basemap features',
  parcels: 'Parcels',
  beacons: 'Beacons',
  grid: 'Grid intersections',
  all: 'All layers',
}

export function SnappingOptions({
  open,
  onClose,
  enabled,
  onToggleEnabled,
  mode = 'vertex_segment',
  onModeChange,
  tolerance = 0.1,
  onToleranceChange,
  snapTypes = new Set(['parcels', 'beacons']),
  onSnapTypeToggle,
}: SnappingOptionsProps) {
  const [localMode, setLocalMode] = useState(mode)
  const [localTolerance, setLocalTolerance] = useState(tolerance)
  const [localSnapTypes, setLocalSnapTypes] = useState(snapTypes)

  const handleModeChange = useCallback((newMode: SnapMode) => {
    setLocalMode(newMode)
    onModeChange?.(newMode)
  }, [onModeChange])

  const handleToleranceChange = useCallback((newTolerance: number) => {
    setLocalTolerance(newTolerance)
    onToleranceChange?.(newTolerance)
  }, [onToleranceChange])

  const handleSnapTypeToggle = useCallback((type: SnapType) => {
    setLocalSnapTypes(prev => {
      const next = new Set(prev)
      if (next.has(type)) next.delete(type)
      else next.add(type)
      onSnapTypeToggle?.(type)
      return next
    })
  }, [onSnapTypeToggle])

  if (!open) return null

  return (
    <div className="absolute top-[340px] right-3 z-30 w-72 bg-[var(--bg-secondary)]/95 backdrop-blur-2xl border border-[var(--border-color)]/[0.08] rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-right-2 duration-200">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]/[0.06]">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${enabled ? 'bg-[var(--success)]/10' : 'bg-[var(--bg-tertiary)]/10'}`}>
            <Magnet className={`w-4 h-4 ${enabled ? 'text-[var(--success)]' : 'text-[var(--text-muted)]'}`} />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">Snapping</span>
            <p className="text-[9px] text-[var(--text-muted)] uppercase tracking-wider">
              {enabled ? 'Enabled' : 'Disabled'}
            </p>
          </div>
        </div>
        <button
          onClick={onClose}
          className="w-7 h-7 flex items-center justify-center rounded-lg text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card)]/[0.06]"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="p-4 space-y-4">
        {/* Enable toggle */}
        <button
          onClick={onToggleEnabled}
          className={`w-full flex items-center justify-between p-2.5 rounded-lg border transition-colors ${
            enabled
              ? 'bg-[var(--success)]/5 border-emerald-500/30'
              : 'bg-[var(--bg-card)]/[0.02] border-[var(--border-color)]/[0.06]'
          }`}
        >
          <span className="text-xs text-[var(--text-primary)]">Enable Snapping</span>
          <div className={`w-9 h-5 rounded-full p-0.5 transition-colors ${enabled ? 'bg-[var(--success)]' : 'bg-gray-700'}`}>
            <div className={`w-4 h-4 rounded-full bg-[var(--bg-card)] transition-transform ${enabled ? 'translate-x-4' : ''}`} />
          </div>
        </button>

        {/* Snap mode */}
        <div>
          <div className="block text-[9px] text-[var(--text-muted)] uppercase tracking-wider mb-1.5">Snap Mode</div>
          <div className="grid grid-cols-3 gap-1">
            {(['vertex', 'segment', 'vertex_segment'] as SnapMode[]).map(m => (
              <button
                key={m}
                onClick={() => handleModeChange(m)}
                disabled={!enabled}
                className={`px-2 py-1.5 rounded-lg text-[9px] font-medium transition-colors disabled:opacity-30 ${
                  localMode === m
                    ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]'
                    : 'bg-[var(--bg-card)]/[0.02] border border-[var(--border-color)]/[0.06] text-[var(--text-secondary)] hover:text-[var(--text-secondary)]'
                }`}
              >
                {m === 'vertex' ? 'Vertex' : m === 'segment' ? 'Segment' : 'Both'}
              </button>
            ))}
          </div>
        </div>

        {/* Tolerance */}
        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label htmlFor="snap-tolerance" className="text-[9px] text-[var(--text-muted)] uppercase tracking-wider">Tolerance</label>
            <span className="text-[10px] text-[var(--text-secondary)] font-mono">{localTolerance.toFixed(2)} m</span>
          </div>
          <input id="snap-tolerance"
            type="range"
            min="0.01"
            max="5"
            step="0.01"
            value={localTolerance}
            onChange={e => handleToleranceChange(parseFloat(e.target.value))}
            disabled={!enabled}
            className="w-full h-1.5 accent-[#D17B47] cursor-pointer disabled:opacity-30"
          />
          <div className="flex items-center justify-between mt-0.5 text-[8px] text-[var(--text-muted)]">
            <span>1cm</span>
            <span>1m</span>
            <span>5m</span>
          </div>
        </div>

        {/* Snap to layers */}
        <div>
          <div className="block text-[9px] text-[var(--text-muted)] uppercase tracking-wider mb-1.5">Snap To</div>
          <div className="space-y-1">
            {(['parcels', 'beacons', 'grid', 'osm'] as SnapType[]).map(type => (
              <label
                key={type}
                className={`flex items-center gap-2 p-1.5 rounded-lg cursor-pointer transition-colors ${
                  enabled ? 'hover:bg-[var(--bg-card)]/[0.04]' : 'opacity-50'
                }`}
              >
                <input aria-label="Snap type"
                  type="checkbox"
                  checked={localSnapTypes.has(type)}
                  onChange={() => handleSnapTypeToggle(type)}
                  disabled={!enabled}
                  className="w-3.5 h-3.5 rounded border-[var(--border-hover)] accent-[#D17B47]"
                />
                <span className="text-[11px] text-[var(--text-secondary)]">{SNAP_TYPE_LABELS[type]}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Info */}
        <div className="flex items-start gap-1.5 p-2 rounded-lg bg-blue-500/5 border border-blue-500/10">
          <Settings2 className="w-3 h-3 text-[var(--primary-blue)] shrink-0 mt-0.5" />
          <p className="text-[9px] text-[var(--primary-blue)]/70 leading-relaxed">
            Snapping ensures precise digitizing by aligning new features to existing vertices and edges.
            Lower tolerance = more precise but harder to snap. Higher tolerance = easier but less precise.
          </p>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { logger } from '@/lib/logger'
import { transformCoordinates, getSupportedSystems, type CoordinateSystem, type TransformResult } from '@/lib/online/coordinates'
import { calculateEDMCorrection } from '@/lib/online/weather'
import { searchBenchmarks, getAvailableCountries, getBenchmarkTypes, Benchmark } from '@/lib/online/benchmarks'
import GNSSProcessor from '@/components/online/GNSSProcessor'
import CoordinateTransformer from '@/components/online/CoordinateTransformer'
import ImageryViewer from '@/components/online/ImageryViewer'

export default function OnlineServicesPage() {
  const [activeTab, setActiveTab] = useState<'gnss' | 'transform' | 'edm' | 'benchmarks' | 'imagery'>('gnss')
  const [transformResult, setTransformResult] = useState<TransformResult | null>(null)
  const [benchmarkResults, setBenchmarkResults] = useState<Benchmark[]>([])
  const [weatherResult, setWeatherResult] = useState<ReturnType<typeof calculateEDMCorrection> | null>(null)
  const [loading, setLoading] = useState(false)
  const [onlineStatus, setOnlineStatus] = useState<'online' | 'offline'>('online')

  useEffect(() => {
    const handleOnline = () => setOnlineStatus('online')
    const handleOffline = () => setOnlineStatus('offline')
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)
    setOnlineStatus(navigator.onLine ? 'online' : 'offline')
    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  const [transformInput, setTransformInput] = useState({
    latitude: '',
    longitude: '',
    easting: '',
    northing: '',
    zone: '',
    hemisphere: 'N' as 'N' | 'S',
    fromSystem: 'WGS84',
    toSystem: 'UTM'
  })

  const [benchmarkSearch, setBenchmarkSearch] = useState({
    country: '',
    type: 'ALL' as 'ALL' | 'BM' | 'CP' | 'TRIG' | 'TIDAL'
  })

  const [weatherInput, setWeatherInput] = useState({
    temperature: '25',
    pressure: '1013.25',
    humidity: '50',
    elevation: ''
  })

  const systems = getSupportedSystems()
  const countries = getAvailableCountries()
  const benchmarkTypes = getBenchmarkTypes()

  const handleTransform = async () => {
    setLoading(true)
    try {
      const result = await transformCoordinates(
        {
          latitude: transformInput.latitude ? parseFloat(transformInput.latitude) : undefined,
          longitude: transformInput.longitude ? parseFloat(transformInput.longitude) : undefined,
          easting: transformInput.easting ? parseFloat(transformInput.easting) : undefined,
          northing: transformInput.northing ? parseFloat(transformInput.northing) : undefined,
          zone: transformInput.zone ? parseInt(transformInput.zone) : undefined,
          hemisphere: transformInput.hemisphere
        },
        transformInput.fromSystem as CoordinateSystem,
        transformInput.toSystem as CoordinateSystem
      )
      setTransformResult(result)
    } catch (e) {
      logger.error('Coordinate transform error:', { error: e })
    }
    setLoading(false)
  }

  const handleBenchmarkSearch = async () => {
    setLoading(true)
    try {
      const result = await searchBenchmarks(benchmarkSearch)
      setBenchmarkResults(result.benchmarks)
    } catch (e) {
      logger.error('Benchmark search error:', { error: e })
    }
    setLoading(false)
  }

  const handleWeatherCalc = () => {
    const result = calculateEDMCorrection({
      temperature: parseFloat(weatherInput.temperature),
      pressure: parseFloat(weatherInput.pressure),
      humidity: parseFloat(weatherInput.humidity),
      elevation: weatherInput.elevation ? parseFloat(weatherInput.elevation) : undefined
    })
    setWeatherResult(result)
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="flex justify-between items-start mb-2">
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">Online Services</h1>
          <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm ${
            onlineStatus === 'online' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
          }`}>
            <span className={`w-2 h-2 rounded-full ${onlineStatus === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></span>
            {onlineStatus === 'online' ? 'Connected' : 'Offline'}
          </div>
        </div>
        <p className="text-[var(--text-muted)] mb-8">Live coordinate transformations, benchmark lookup, GNSS processing, and atmospheric corrections</p>

        <div className="flex flex-wrap gap-2 mb-6">
          {[
            { id: 'gnss', label: 'GNSS Baseline' },
            { id: 'transform', label: 'Coordinate Transform' },
            { id: 'edm', label: 'EDM Corrections' },
            { id: 'benchmarks', label: 'Benchmarks' },
            { id: 'imagery', label: 'Satellite Imagery' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as 'gnss' | 'transform' | 'edm' | 'benchmarks' | 'imagery')}
              className={`px-4 py-2 rounded-lg font-medium transition ${
                activeTab === tab.id
                  ? 'bg-sky-600 text-white'
                  : 'bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:bg-[var(--bg-tertiary)] border border-[var(--border-color)]'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {activeTab === 'gnss' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">GNSS Baseline Processing</h2>
            <p className="text-sm text-[var(--text-muted)] mb-6">
              Process GNSS baseline observations for high-precision control network adjustments
            </p>
            <GNSSProcessor />
          </div>
        )}

        {activeTab === 'imagery' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Satellite Imagery Overlay</h2>
            <p className="text-sm text-[var(--text-muted)] mb-6">
              Access Sentinel-2 satellite imagery for survey planning and verification
            </p>
            <ImageryViewer />
          </div>
        )}

        {activeTab === 'transform' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Coordinate Transformation</h2>
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="from-system" className="block text-sm font-medium text-[var(--text-muted)] mb-1">From System</label>
                <select
                  id="from-system"
                  value={transformInput.fromSystem}
                  onChange={e => setTransformInput({ ...transformInput, fromSystem: e.target.value })}
                  className="w-full p-2 border rounded-lg"
                >
                  {systems.map((s) => (
                    <option key={s.id} value={s.id}>{s.name}</option>
                  ))}
                </select>

                <div className="mt-4 space-y-3">
                  {transformInput.fromSystem === 'WGS84' ? (
                    <>
                      <div>
                        <label htmlFor="transform-latitude" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Latitude</label>
                        <input
                          id="transform-latitude"
                          type="number"
                          step="any"
                          value={transformInput.latitude}
                          onChange={e => setTransformInput({ ...transformInput, latitude: e.target.value })}
                          aria-label="Latitude" placeholder="e.g., -1.2921"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                      <div>
                        <label htmlFor="transform-longitude" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Longitude</label>
                        <input
                          id="transform-longitude"
                          type="number"
                          step="any"
                          value={transformInput.longitude}
                          onChange={e => setTransformInput({ ...transformInput, longitude: e.target.value })}
                          aria-label="Longitude" placeholder="e.g., 36.8219"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                    </>
                  ) : (
                    <>
                      <div>
                        <label htmlFor="transform-easting" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Easting (m)</label>
                        <input
                          id="transform-easting"
                          type="number"
                          step="any"
                          value={transformInput.easting}
                          onChange={e => setTransformInput({ ...transformInput, easting: e.target.value })}
                          aria-label="Easting (m)" placeholder="e.g., 250000"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                      <div>
                        <label htmlFor="transform-northing" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Northing (m)</label>
                        <input
                          id="transform-northing"
                          type="number"
                          step="any"
                          value={transformInput.northing}
                          onChange={e => setTransformInput({ ...transformInput, northing: e.target.value })}
                          aria-label="Northing (m)" placeholder="e.g., 9850000"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label htmlFor="transform-zone" className="block text-sm font-medium text-[var(--text-muted)] mb-1">UTM Zone</label>
                          <input
                            id="transform-zone"
                            type="number"
                            value={transformInput.zone}
                            onChange={e => setTransformInput({ ...transformInput, zone: e.target.value })}
                            placeholder="e.g., 37"
                            className="w-full p-2 border rounded-lg"
                          />
                        </div>
                        <div>
                          <label htmlFor="transform-hemisphere" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Hemisphere</label>
                          <select
                            id="transform-hemisphere"
                            value={transformInput.hemisphere}
                            onChange={e => setTransformInput({ ...transformInput, hemisphere: e.target.value as 'N' | 'S' })}
                            className="w-full p-2 border rounded-lg"
                          >
                            <option value="N">Northern</option>
                            <option value="S">Southern</option>
                          </select>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              </div>

              <div>
                <label htmlFor="to-system" className="block text-sm font-medium text-[var(--text-muted)] mb-1">To System</label>
                <select
                  id="to-system"
                  value={transformInput.toSystem}
                  onChange={e => setTransformInput({ ...transformInput, toSystem: e.target.value })}
                  className="w-full p-2 border rounded-lg"
                >
                  {systems.map((s) => (
                    <option key={s.id} value={s.id}>{s.name}</option>
                  ))}
                </select>

                <button
                  onClick={handleTransform}
                  disabled={loading}
                  className="mt-4 w-full bg-sky-600 text-white py-2 px-4 rounded-lg hover:bg-sky-700 disabled:opacity-50"
                >
                  {loading ? 'Transforming...' : 'Transform Coordinates'}
                </button>

                {transformResult && (
                  <div className="mt-4 p-4 bg-[var(--bg-secondary)] rounded-lg border border-[var(--border-color)]">
                    {transformResult.success ? (
                      <div>
                        <h3 className="font-medium text-green-600 mb-2">Transformation Successful</h3>
                        <p className="text-sm text-[var(--text-muted)]">Precision: {transformResult.precision}</p>
                        {transformResult.result?.latitude && (
                          <p className="text-sm">Lat: {transformResult.result.latitude.toFixed(6)}°</p>
                        )}
                        {transformResult.result?.longitude && (
                          <p className="text-sm">Lon: {transformResult.result.longitude.toFixed(6)}°</p>
                        )}
                        {transformResult.result?.easting && (
                          <p className="text-sm">E: {transformResult.result.easting.toFixed(3)} m</p>
                        )}
                        {transformResult.result?.northing && (
                          <p className="text-sm">N: {transformResult.result.northing.toFixed(3)} m</p>
                        )}
                        {transformResult.result?.zone && (
                          <p className="text-sm">Zone: {transformResult.result.zone}{transformResult.result.hemisphere}</p>
                        )}
                      </div>
                    ) : (
                      <p className="text-red-600">{transformResult.error}</p>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'benchmarks' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Benchmark Database Lookup</h2>
            <div className="grid md:grid-cols-3 gap-4 mb-6">
              <div>
                <label htmlFor="benchmark-country" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Country</label>
                <select
                  id="benchmark-country"
                  value={benchmarkSearch.country}
                  onChange={e => setBenchmarkSearch({ ...benchmarkSearch, country: e.target.value })}
                  className="w-full p-2 border rounded-lg"
                >
                  <option value="">All Countries</option>
                  {countries.map((c) => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
              <div>
                <label htmlFor="benchmark-type" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Type</label>
                <select
                  id="benchmark-type"
                  value={benchmarkSearch.type}
                  onChange={e => setBenchmarkSearch({ ...benchmarkSearch, type: e.target.value as 'ALL' | 'BM' | 'CP' | 'TRIG' | 'TIDAL' })}
                  className="w-full p-2 border rounded-lg"
                >
                  <option value="ALL">All Types</option>
                  {benchmarkTypes.map((t) => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </div>
              <div className="flex items-end">
                <button
                  onClick={handleBenchmarkSearch}
                  disabled={loading}
                  className="w-full bg-sky-600 text-white py-2 px-4 rounded-lg hover:bg-sky-700 disabled:opacity-50"
                >
                  {loading ? 'Searching...' : 'Search Benchmarks'}
                </button>
              </div>
            </div>

            {benchmarkResults.length > 0 && (
              <div className="space-y-3">
                {benchmarkResults.map((bm) => (
                  <div key={bm.id} className="p-4 border rounded-lg hover:bg-[var(--bg-secondary)]">
                    <div className="flex justify-between items-start">
                      <div>
                        <h3 className="font-medium">{bm.name}</h3>
                        <p className="text-sm text-[var(--text-muted)]">{bm.region}, {bm.country}</p>
                        <p className="text-sm">Type: {bm.type} | Datum: {bm.datum}</p>
                      </div>
                      <div className="text-right">
                        <p className="font-medium">{bm.elevation.toFixed(3)} m</p>
                        <p className="text-xs text-[var(--text-muted)]">RL</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'edm' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-semibold">EDM Atmospheric Correction</h2>
              <button
                onClick={async () => {
                  if (navigator.geolocation) {
                    navigator.geolocation.getCurrentPosition(async (pos) => {
                      const { latitude, longitude } = pos.coords
                      try {
                        const res = await fetch(`/api/weather?lat=${latitude}&lon=${longitude}`)
                        const data = (await res.json()) as { temperature?: number; pressure?: number; humidity?: number; elevation?: number }
                        if (data.temperature !== undefined) {
                          setWeatherInput({
                            ...weatherInput,
                            temperature: data.temperature.toString(),
                            pressure: data.pressure?.toString() || '1013.25',
                            humidity: data.humidity?.toString() || '50',
                            elevation: data.elevation?.toString() || ''
                          })
                        }
                      } catch (e) {
                        logger.error('Failed to fetch weather:', { error: e })
                      }
                    })
                  }
                }}
                className="text-sm px-3 py-1 bg-green-600 text-white rounded-lg hover:bg-green-700"
              >
                [Pin] Get Live Weather
              </button>
            </div>
            <div className="grid md:grid-cols-2 gap-6">
              <div className="space-y-4">
                <div>
                  <label htmlFor="weather-temperature" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Temperature (°C)</label>
                  <input id="weather-temperature"
                    type="number"
                    step="any"
                    value={weatherInput.temperature}
                    onChange={e => setWeatherInput({ ...weatherInput, temperature: e.target.value })}
                    className="w-full p-2 border rounded-lg"
                  />
                </div>
                <div>
                  <label htmlFor="weather-pressure" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Pressure (hPa)</label>
                  <input id="weather-pressure"
                    type="number"
                    step="any"
                    value={weatherInput.pressure}
                    onChange={e => setWeatherInput({ ...weatherInput, pressure: e.target.value })}
                    className="w-full p-2 border rounded-lg"
                  />
                </div>
                <div>
                  <label htmlFor="weather-humidity" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Humidity (%)</label>
                  <input id="weather-humidity"
                    type="number"
                    step="any"
                    value={weatherInput.humidity}
                    onChange={e => setWeatherInput({ ...weatherInput, humidity: e.target.value })}
                    className="w-full p-2 border rounded-lg"
                  />
                </div>
                <div>
                  <label htmlFor="weather-elevation" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Elevation (m) - Optional</label>
                  <input
                    id="weather-elevation"
                    type="number"
                    step="any"
                    value={weatherInput.elevation}
                    onChange={e => setWeatherInput({ ...weatherInput, elevation: e.target.value })}
                    aria-label="Elevation (m)" placeholder="e.g., 1500"
                    className="w-full p-2 border rounded-lg"
                  />
                </div>
                <button
                  onClick={handleWeatherCalc}
                  className="w-full bg-sky-600 text-white py-2 px-4 rounded-lg hover:bg-sky-700"
                >
                  Calculate Correction
                </button>
              </div>

              {weatherResult && (
                <div className="space-y-4">
                  <div className="p-4 bg-sky-50 rounded-lg">
                    <h3 className="font-semibold text-sky-800">Atmospheric Correction</h3>
                    <p className="text-3xl font-bold text-sky-600 mt-2">{weatherResult.edmCorrection.ppm} ppm</p>
                    <p className="text-sm text-sky-700 mt-1">{weatherResult.edmCorrection.description}</p>
                  </div>

                  <div className="p-4 border rounded-lg">
                    <h4 className="font-medium mb-2">Conditions</h4>
                    <p className="text-sm">Atmosphere: <span className="capitalize">{weatherResult.atmosphericCondition}</span></p>
                    <p className="text-sm">Temp: {weatherResult.temperature}°C</p>
                    <p className="text-sm">Pressure: {weatherResult.pressure} hPa</p>
                    <p className="text-sm">Humidity: {weatherResult.humidity}%</p>
                  </div>

                  {weatherResult.recommendations.length > 0 && (
                    <div className="p-4 bg-yellow-50 rounded-lg">
                      <h4 className="font-medium text-yellow-800 mb-2">Recommendations</h4>
                      <ul className="text-sm text-yellow-700 space-y-1">
                        {weatherResult.recommendations.map((rec: string, i: number) => (
                          <li key={`item-${i}`}>• {rec}</li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState, useCallback, useMemo, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import { createClient } from '@/lib/api-client/client';
import { SurveyType } from '@/types/project';
import { SurveyWorkflow } from '@/types/workflow';
import { nextStepIndex } from '@/lib/workflows/workflowRegistry';
import {
  getWorkflowStatus,
  getWorkflowSteps,
  type ProjectWorkflowData,
} from '@/lib/workflows/projectWorkflowEngine';
import WorkflowStepper from '@/components/workspace/WorkflowStepper';
import WorkflowStepPanel from '@/components/workspace/WorkflowStepPanel';
import EnhancedSplitLayout from '@/components/workspace/EnhancedSplitLayout';
import WorkspaceMap from '@/components/workspace/WorkspaceMap';
import ComputationLog from '@/components/workspace/ComputationLog';
import WorkflowQualityGate from '@/components/shared/WorkflowQualityGate';
import WorkflowOverviewPanel from '@/components/shared/WorkflowOverviewPanel';
import { CollaborationPanel } from '@/components/realtime/CollaborationPanel';
import { useCollaboration } from '@/lib/realtime/useCollaboration';
import { QADashboard } from '@/components/dashboard/QADashboard';
import { BatchParcelImport } from '@/components/parcels/BatchParcelImport';

interface ProjectProps {
  id: string;
  name: string;
  surveyType: SurveyType;
  workflowStep: number;
  maxUnlocked: number;
}

interface Props {
  project: ProjectProps;
  workflow: SurveyWorkflow;
}

export default function ProjectWorkspaceClient({ project, workflow }: Props) {
  const router = useRouter();
  const dbClient = createClient();
  const { data: session } = useSession();

  const [currentStep, setCurrentStep] = useState(project.workflowStep);
  const [maxUnlocked, setMaxUnlocked] = useState(project.maxUnlocked);
  const [saving, setSaving] = useState(false);

  // Workflow state machine data (fetched from API)
  const [workflowData, setWorkflowData] = useState<ProjectWorkflowData | null>(null);
  const [workflowLoading, setWorkflowLoading] = useState(true);

  // Quality gate state
  const [qualityGateTarget, setQualityGateTarget] = useState<string | null>(null);

  // Overview panel state
  const [overviewOpen, setOverviewOpen] = useState(false);

  // Collaboration state
  const [chatMessages, setChatMessages] = useState<Array<{
    id: string; userId: string; userName: string; message: string; timestamp: number;
  }>>([]);

  const userId = (session?.user as { id?: string })?.id || '';
  const userName = (session?.user as { name?: string })?.name || 'Surveyor';

  const {
    collaborators,
    isConnected,
    sendChat,
    conflictWarnings,
  } = useCollaboration({
    projectId: project.id,
    userId,
    userName,
  });

  // Handle incoming chat messages
  useEffect(() => {
    // The hook calls onChat callback — we set it via a ref pattern
    // For simplicity, we handle chat through the messages state
  }, []);

  const handleSendChat = useCallback((message: string) => {
    const newMsg = {
      id: crypto.randomUUID(),
      userId,
      userName,
      message,
      timestamp: Date.now(),
    };
    setChatMessages(prev => [...prev, newMsg]);
    sendChat(message);
  }, [userId, userName, sendChat]);

  // Fetch workflow status from API on mount
  useEffect(() => {
    let cancelled = false;
    async function fetchStatus() {
      setWorkflowLoading(true);
      try {
        const res = await fetch(`/api/project/${project.id}/workflow`);
        if (res.ok) {
          const json = (await res.json()) as {
            data?: {
              steps?: Array<{ id: string; completionPct?: number }>
            }
          };
          // The API returns the status but we need the raw data for the engine.
          // Build it from the API response + local project state.
          const data: ProjectWorkflowData = {
            id: project.id,
            name: project.name,
            surveyType: project.surveyType,
            location: null, // Not available in the current workspace props
            utmZone: null,
            hemisphere: null,
            currentStep,
            maxUnlocked,
            pointCount: 0,
            fieldbookEntryCount: 0,
            hasComputationResults: false,
            toleranceCheckPassed: null,
            toleranceAcknowledged: false,
            hasDeedPlan: false,
            hasSubmissionPackage: false,
          };

          // If the API returned status, use its computed data to infer richer data
          if (json.data?.steps) {
            // We can extract counts from the step info
            const fieldStep = json.data.steps.find((s: { id: string }) => s.id === 'field-collection');
            if (fieldStep?.completionPct === 100) {
              data.pointCount = 3; // At least 3 if complete
              data.fieldbookEntryCount = 3;
            }
            const computeStep = json.data.steps.find((s: { id: string }) => s.id === 'computation');
            if (computeStep?.completionPct === 100) {
              data.hasComputationResults = true;
            }
            const reviewStep = json.data.steps.find((s: { id: string }) => s.id === 'quality-review');
            if (reviewStep?.completionPct === 100) {
              data.toleranceCheckPassed = true;
            }
            const deedStep = json.data.steps.find((s: { id: string }) => s.id === 'map-deed-plan');
            if (deedStep?.completionPct === 100) {
              data.hasDeedPlan = true;
            }
            const subStep = json.data.steps.find((s: { id: string }) => s.id === 'submission');
            if (subStep?.completionPct === 100) {
              data.hasSubmissionPackage = true;
            }
          }

          if (!cancelled) setWorkflowData(data);
        }
      } catch {
        // API may not be available in all environments — use local fallback
        if (!cancelled) {
          setWorkflowData({
            id: project.id,
            name: project.name,
            surveyType: project.surveyType,
            location: null,
            utmZone: null,
            hemisphere: null,
            currentStep,
            maxUnlocked,
            pointCount: 0,
            fieldbookEntryCount: 0,
            hasComputationResults: false,
            toleranceCheckPassed: null,
            toleranceAcknowledged: false,
            hasDeedPlan: false,
            hasSubmissionPackage: false,
          });
        }
      } finally {
        if (!cancelled) setWorkflowLoading(false);
      }
    }
    fetchStatus();
    return () => { cancelled = true; };
  }, [project.id, project.name, project.surveyType, currentStep, maxUnlocked]);

  const workflowStatus = useMemo(() => {
    if (!workflowData) return null;
    return getWorkflowStatus(workflowData);
  }, [workflowData]);

  const handleStepChange = useCallback(async (newStep: number) => {
    // Check if the target step is unlocked
    const steps = getWorkflowSteps(project.surveyType);
    const targetStepDef = steps.find((s) => s.index === newStep);

    if (!targetStepDef) return;

    // If the step is beyond maxUnlocked, show the quality gate
    if (newStep > maxUnlocked && workflowData) {
      setQualityGateTarget(targetStepDef.id);
      return;
    }

    setSaving(true);
    const newMax = Math.max(maxUnlocked, newStep);

    await dbClient
      .from('projects')
      .update({
        workflow_step: newStep,
        workflow_max_unlocked: newMax,
      })
      .eq('id', project.id);

    setCurrentStep(newStep);
    setMaxUnlocked(newMax);
    setSaving(false);
  }, [project.id, maxUnlocked, dbClient, workflowData, project.surveyType]);

  const handleContinue = async () => {
    const next = nextStepIndex(project.surveyType, currentStep);
    if (next === null) return;

    // Check quality gate via workflow engine
    if (workflowData) {
      const steps = getWorkflowSteps(project.surveyType);
      const nextStepDef = steps.find((s) => s.index === next);
      if (nextStepDef) {
        const status = getWorkflowStatus(workflowData);
        if (!status.canAdvance && next > maxUnlocked) {
          setQualityGateTarget(nextStepDef.id);
          return;
        }
      }
    }

    await handleStepChange(next);

    const nextStepDef = workflow.steps.find((s) => s.index === next);
    if (nextStepDef?.routeSuffix) {
      router.push(`/project/${project.id}/${nextStepDef.routeSuffix}`);
    }
  };

  const handleQualityGateProceed = useCallback(() => {
    setQualityGateTarget(null);
    // User acknowledged warnings — allow the step change
    // This is handled by the quality gate component
  }, []);

  const handleQualityGateNavigate = useCallback((stepId: string) => {
    const steps = getWorkflowSteps(project.surveyType);
    const stepDef = steps.find((s) => s.id === stepId);
    if (stepDef) {
      setQualityGateTarget(null);
      setCurrentStep(stepDef.index);
      router.push(`/project/${project.id}?step=${stepDef.index}`);
    }
  }, [project.id, project.surveyType, router]);

  const handleOverviewStepClick = useCallback((stepId: string) => {
    const steps = getWorkflowSteps(project.surveyType);
    const stepDef = steps.find((s) => s.id === stepId);
    if (stepDef && stepDef.index <= maxUnlocked) {
      setCurrentStep(stepDef.index);
      if (stepDef.routeSuffix) {
        router.push(`/project/${project.id}/${stepDef.routeSuffix}`);
      }
    }
  }, [project.id, maxUnlocked, project.surveyType, router]);

  const currentStepDef = workflow.steps.find((s) => s.index === currentStep);
  const isLastStep = currentStep === workflow.steps[workflow.steps.length - 1].index;
  const nextStep = nextStepIndex(project.surveyType, currentStep);
  const nextStepDef = nextStep !== null ? workflow.steps.find((s) => s.index === nextStep) : null;

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="bg-[var(--bg-secondary)] border-b border-[var(--border-color)] px-4 py-4">
        <div className="max-w-5xl mx-auto">
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-3">
              <div>
                <h1 className="text-lg font-bold text-[var(--text-primary)]">{project.name}</h1>
                <p className="text-xs text-[var(--text-muted)]">{workflow.label}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {/* Workflow overview toggle button */}
              <button
                type="button"
                onClick={() => setOverviewOpen(!overviewOpen)}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border border-[var(--border-color)] text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors"
                title="Workflow overview"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" />
                </svg>
                Workflow
                {workflowStatus && workflowStatus.overallPct > 0 && (
                  <span className="font-mono text-[10px] text-[var(--text-muted)]">{workflowStatus.overallPct}%</span>
                )}
              </button>
              {saving && <span className="text-xs text-[var(--text-muted)]">Saving…</span>}
            </div>
          </div>
          <div className="mt-4">
            <WorkflowStepper
              projectId={project.id}
              steps={workflow.steps}
              currentStep={currentStep}
              maxUnlocked={maxUnlocked}
              onStepChange={handleStepChange}
            />
          </div>
        </div>
      </div>

      {/* UI-4 (2026-07-24): Wire EnhancedSplitLayout — brings 1,255 LOC of
          dead workspace UI (EnhancedSplitLayout + WorkspaceMap + ComputationLog)
          to life. Desktop: resizable left (workflow 55%) / right (map 45%)
          split with a collapsible computation log at the bottom + a compact
          status bar showing misclosure/precision/area/selection. Mobile:
          stacked layout. The header (WorkflowStepper) stays above; the
          collaboration/QA/batch panels stay below. */}
      <EnhancedSplitLayout
        leftPanel={
          <div className="px-4 py-6 max-w-5xl mx-auto">
            {currentStepDef && (
              <p className="text-sm text-[var(--text-muted)] mb-4">{currentStepDef.description}</p>
            )}

            {/* Blocker warnings from workflow engine */}
            {workflowStatus && workflowStatus.blockers.length > 0 && (
              <div className="mb-4 p-3 rounded-lg bg-amber-500/5 border border-amber-500/20 text-sm">
                <div className="flex items-start gap-2">
                  <svg className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
                  </svg>
                  <div>
                    <p className="text-amber-400 font-medium mb-1">Workflow Blockers</p>
                    {workflowStatus.blockers.map((b, i) => (
                      <p key={`${b}-${i}`} className="text-amber-400/80 text-xs">{b}</p>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {currentStep < 5 && (
              <WorkflowStepPanel
                projectId={project.id}
                surveyType={project.surveyType}
                stepIndex={currentStep}
                projectName={project.name}
              />
            )}

            {!isLastStep && nextStepDef && (
              <div className="mt-6 flex justify-end">
                <button
                  onClick={handleContinue}
                  disabled={saving}
                  className="px-5 py-2 bg-[var(--accent)] text-black text-sm font-medium rounded hover:bg-[var(--accent-dim)] disabled:opacity-50 transition-colors"
                >
                  Continue to {nextStepDef.label} →
                </button>
              </div>
            )}

            {currentStep === 4 && (
              <div className="mt-6 flex justify-end gap-3">
                <button
                  onClick={() => router.push(`/mobile/field?project=${project.id}`)}
                  className="px-5 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[var(--text-primary)] text-sm font-medium rounded hover:border-[var(--accent)]/40 transition-colors flex items-center gap-2"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z" />
                  </svg>
                  Field Collection
                </button>
                <button
                  onClick={() => router.push(`/project/${project.id}/submission`)}
                  className="px-5 py-2 bg-[var(--accent)] text-black text-sm font-medium rounded hover:bg-[var(--accent-dim)] transition-colors"
                >
                  Go to Submission →
                </button>
              </div>
            )}
          </div>
        }
        rightPanel={
          <WorkspaceMap projectId={project.id} projectName={project.name} />
        }
        logPanel={<ComputationLog />}
      />

      {/* Quality Gate Modal */}
      {qualityGateTarget && workflowData && (
        <WorkflowQualityGate
          project={workflowData}
          targetStepId={qualityGateTarget}
          onDismiss={() => setQualityGateTarget(null)}
          onProceedAnyway={handleQualityGateProceed}
          onNavigateToStep={handleQualityGateNavigate}
        />
      )}

      {/* Workflow Overview Panel */}
      {workflowData && (
        <WorkflowOverviewPanel
          project={workflowData}
          isOpen={overviewOpen}
          onToggle={() => setOverviewOpen(!overviewOpen)}
          onStepClick={handleOverviewStepClick}
        />
      )}

      {/* Real-time Collaboration Panel */}
      <div className="max-w-5xl mx-auto px-4 py-4">
        <CollaborationPanel
          collaborators={collaborators}
          isConnected={isConnected}
          messages={chatMessages}
          onSend={handleSendChat}
          conflictWarnings={conflictWarnings}
        />
      </div>

      {/* QA Validation Dashboard */}
      <div className="max-w-5xl mx-auto px-4 py-4">
        <QADashboard projectId={project.id} />
      </div>

      {/* Batch Parcel Import */}
      <div className="max-w-5xl mx-auto px-4 py-4">
        <BatchParcelImport projectId={project.id} />
      </div>
    </div>
  );
}

'use client';

/*
 * PERFORMANCE NOTE — OpenLayers static imports (~700KB vendor-ol chunk)
 * These 14 OL modules are intentionally imported at the top level rather than
 * dynamically imported because the webpack splitChunks config already isolates
 * them into a separate `vendor-ol` chunk.  This page is only navigated to
 * explicitly (not on the initial load path), so the OL chunk is never part of
 * the critical-path bundle.  Dynamic imports would add complexity without
 * measurable benefit since the chunk is already code-split.
 */

import { useEffect, useState, useRef } from 'react'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import Map from 'ol/Map'
import View from 'ol/View'
import TileLayer from 'ol/layer/Tile'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import XYZ from 'ol/source/XYZ'
import GeoJSON from 'ol/format/GeoJSON'
import { fromLonLat } from 'ol/proj'
import { Style, Fill, Stroke, Text } from 'ol/style'
import CircleStyle from 'ol/style/Circle'
import Overlay from 'ol/Overlay'
import { ArrowLeft, Download } from 'lucide-react'
import type Feature from 'ol/Feature'
import type { FeatureLike } from 'ol/Feature'
import { registerProjections } from '@/lib/map/projection'
import { SRID_21037 } from '@/lib/map/projection'

const STATUS_COLORS: Record<string, string> = {
  pending: '#6b7280',
  field_complete: '#3b82f6',
  computed: '#22c55e',
  plan_generated: '#f59e0b',
  submitted: '#8b5cf6',
  approved: '#10b981',
}

export default function SchemeMapPage() {
  const params = useParams()
  const projectId = params.id as string
  const mapRef = useRef<HTMLDivElement>(null)
  const mapInstance = useRef<Map | null>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [parcelCount, setParcelCount] = useState(0)

  useEffect(() => {
    if (!mapRef.current || !projectId) return

    setLoading(true)

    // Register EPSG:21037 (Arc 1960 / UTM Zone 37S) before using it for GeoJSON reprojection
    registerProjections()

    // Create map
    const vectorSource = new VectorSource()

    const map = new Map({
      target: mapRef.current,
      layers: [
        new TileLayer({
          source: new XYZ({
            url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            maxZoom: 19,
            crossOrigin: 'anonymous',
          }),
        }),
        new VectorLayer({
          source: vectorSource,
          style: (feature: FeatureLike) => {
            const props = feature.getProperties()
            const status = (props.status as string) || 'pending'
            const color = STATUS_COLORS[status] || '#6b7280'
            const geomType = feature.getGeometry()?.getType()

            if (geomType === 'Polygon') {
              return new Style({
                fill: new Fill({ color: color + '40' }), // 25% opacity
                stroke: new Stroke({ color, width: 2.5 }),
                text: new Text({
                  text: String(props.parcel_number || ''),
                  font: 'bold 12px sans-serif',
                  fill: new Fill({ color: '#ffffff' }),
                  stroke: new Stroke({ color: '#000000', width: 3 }),
                }),
              })
            }

            if (geomType === 'Point' && props.type === 'block_label') {
              return new Style({
                text: new Text({
                  text: `Block ${String(props.block_number ?? '')}\n(${String(props.parcel_count ?? '')} parcels)`,
                  font: 'bold 14px sans-serif',
                  fill: new Fill({ color: '#1e40af' }),
                  stroke: new Stroke({ color: '#ffffff', width: 4 }),
                  textAlign: 'center',
                }),
              })
            }

            return new Style({
              image: new CircleStyle({
                radius: 5,
                fill: new Fill({ color }),
                stroke: new Stroke({ color: '#000', width: 1 }),
              }),
            })
          },
        }),
      ],
      view: new View({
        center: fromLonLat([37.0, -1.3]), // Default: central Kenya
        zoom: 15,
      }),
    })

    // Popup overlay
    const overlay = new Overlay({
      element: popupRef.current || undefined,
      autoPan: true,
    })
    map.addOverlay(overlay)

    map.on('click', (evt) => {
      const feature = map.forEachFeatureAtPixel(evt.pixel, f => f)
      if (feature && popupRef.current) {
        const props = feature.getProperties()
        // VULN-002 FIX (security review 2026-08-03): block/parcel numbers and
        // LR numbers are user-entered — render with textContent, never innerHTML.
        const el = popupRef.current
        el.replaceChildren()

        const wrap = document.createElement('div')
        wrap.style.cssText = 'font-size:12px;'

        const title = document.createElement('strong')
        title.textContent = `Block ${String(props.block_number ?? '')} — Parcel ${String(props.parcel_number || '')}`
        wrap.append(title)
        wrap.append(document.createElement('br'))

        if (props.lr_number) {
          const lr = document.createElement('div')
          lr.textContent = `LR: ${String(props.lr_number)}`
          wrap.append(lr)
        }
        if (props.area_ha) {
          const area = document.createElement('div')
          area.textContent = `Area: ${Number(props.area_ha).toFixed(4)} ha`
          wrap.append(area)
        }

        const statusRow = document.createElement('div')
        const statusLabel = document.createTextNode('Status: ')
        const statusSpan = document.createElement('span')
        statusSpan.style.color = STATUS_COLORS[props.status as string] || '#999'
        statusSpan.textContent = String(props.status || 'pending')
        statusRow.append(statusLabel, statusSpan)
        wrap.append(statusRow)

        el.append(wrap)
        el.style.display = 'block'
        overlay.setPosition(evt.coordinate)
      } else if (popupRef.current) {
        popupRef.current.style.display = 'none'
      }
    })

    mapInstance.current = map

    // Fetch scheme GeoJSON
    fetch(`/api/scheme/map?project_id=${projectId}`)
      .then(res => res.json())
      .then((data: { features?: unknown[] }) => {
        if (data.features && data.features.length > 0) {
          const format = new GeoJSON()
          const features = format.readFeatures(data, {
            dataProjection: SRID_21037, // Arc 1960 / UTM Zone 37S (Kenya cadastral datum)
            featureProjection: 'EPSG:3857', // Web Mercator
          })
          vectorSource.addFeatures(features)
          setParcelCount(features.filter(f => f.getGeometry()?.getType() === 'Polygon').length)

          // Zoom to extent
          const extent = vectorSource.getExtent()
          if (extent && extent[0] !== Infinity) {
            map.getView().fit(extent, { padding: [50, 50, 50, 50], maxZoom: 18 })
          }
        }
        setLoading(false)
      })
      .catch(() => {
        setError('Failed to load scheme data')
        setLoading(false)
      })

    return () => {
      map.setTarget(undefined)
    }
  }, [projectId])

  return (
    <div className="min-h-screen bg-gray-950 text-white">
      <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800">
        <div className="flex items-center gap-4">
          <Link
            href={`/project/${projectId}/scheme`}
            className="p-2 hover:bg-gray-800 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-5 h-5 text-gray-400" />
          </Link>
          <div>
            <h1 className="text-xl font-bold">Scheme Map</h1>
            <p className="text-sm text-gray-400">
              {loading ? 'Loading parcels...' : `${parcelCount} parcels shown`}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <a
            href={`/api/scheme/export/geojson?project_id=${projectId}`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white text-sm rounded-lg transition-colors"
          >
            <Download className="w-4 h-4" />
            GeoJSON
          </a>
          <a
            href={`/api/scheme/export/dxf?project_id=${projectId}`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg transition-colors"
          >
            <Download className="w-4 h-4" />
            DXF
          </a>
        </div>
      </div>

      {error && (
        <div className="mx-6 mt-4 p-3 bg-red-900/50 border border-red-800 rounded-lg text-red-300 text-sm">
          {error}
        </div>
      )}

      <div className="relative" style={{ height: 'calc(100vh - 80px)' }}>
        <div ref={mapRef} className="w-full h-full" />

        {loading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-950/60">
            <div className="flex items-center gap-3 text-gray-300">
              <svg className="w-6 h-6 animate-spin" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
              </svg>
              Loading scheme parcels...
            </div>
          </div>
        )}

        <div
          ref={popupRef}
          className="absolute bg-gray-800 border border-gray-600 rounded-lg p-3 shadow-xl"
          style={{ display: 'none', minWidth: 200 }}
        />

        {/* Legend */}
        <div className="absolute bottom-4 right-4 bg-gray-900/90 backdrop-blur border border-gray-700 rounded-lg p-3">
          <h4 className="text-xs font-semibold text-gray-400 mb-2">STATUS LEGEND</h4>
          {Object.entries(STATUS_COLORS).map(([status, color]) => (
            <div key={status} className="flex items-center gap-2 mb-1">
              <div className="w-3 h-3 rounded-full" style={{ backgroundColor: color }} />
              <span className="text-xs text-gray-300 capitalize">{status.replace('_', ' ')}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// DXF / SVG / CSV / GeoJSON export generators for the contour generator tool.
//
// Extracted from src/app/tools/contour-generator/page.tsx — pure functions,
// no React, no hooks, so this file does not need 'use client'.

import type { ContourLine, SpotHeight } from '@/lib/engine/contours';
import { MARGIN, SVG_HEIGHT, SVG_WIDTH } from './constants';
import { elevationToColor, computeHypsometricBands, fmt } from './helpers';

type Bounds2D = { minE: number; maxE: number; minN: number; maxN: number };

export function generateDXF(contours: ContourLine[], bounds: Bounds2D): string {
  const lines: string[] = [];
  lines.push('0');
  lines.push('SECTION');
  lines.push('2');
  lines.push('HEADER');
  lines.push('0');
  lines.push('ENDSEC');
  lines.push('0');
  lines.push('SECTION');
  lines.push('2');
  lines.push('TABLES');
  lines.push('0');
  lines.push('TABLE');
  lines.push('2');
  lines.push('LAYER');
  lines.push('70');
  lines.push(String(contours.length));

  const uniqueElevations = [...new Set(contours.map(c => c.elevation))].sort((a, b) => a - b);
  for (const elev of uniqueElevations) {
    lines.push('0');
    lines.push('LAYER');
    lines.push('2');
    lines.push(`C${elev.toFixed(1)}`);
    lines.push('70');
    lines.push('0');
    lines.push('62');
    lines.push('7');
    lines.push('6');
    lines.push('CONTINUOUS');
  }

  lines.push('0');
  lines.push('ENDTAB');
  lines.push('0');
  lines.push('ENDSEC');

  lines.push('0');
  lines.push('SECTION');
  lines.push('2');
  lines.push('ENTITIES');

  for (const contour of contours) {
    const layerName = `C${contour.elevation.toFixed(1)}`;
    lines.push('0');
    lines.push('LWPOLYLINE');
    lines.push('8');
    lines.push(layerName);
    lines.push('62');
    lines.push('7');
    lines.push('90');
    lines.push(String(contour.points.length));

    if (contour.points[0].easting === contour.points[contour.points.length - 1].easting &&
        contour.points[0].northing === contour.points[contour.points.length - 1].northing) {
      lines.push('70');
      lines.push('1');
    } else {
      lines.push('70');
      lines.push('0');
    }

    for (const pt of contour.points) {
      lines.push('10');
      lines.push(fmt(pt.easting, 4));
      lines.push('20');
      lines.push(fmt(pt.northing, 4));
    }
  }

  lines.push('0');
  lines.push('ENDSEC');
  lines.push('0');
  lines.push('EOF');
  return lines.join('\n');
}

export function generateSVGExport(
  contours: ContourLine[],
  bounds: Bounds2D,
  points: SpotHeight[]
): string {
  const usableW = SVG_WIDTH - 2 * MARGIN;
  const usableH = SVG_HEIGHT - 2 * MARGIN;
  const rangeE = bounds.maxE - bounds.minE || 1;
  const rangeN = bounds.maxN - bounds.minN || 1;

  const elevations = contours.map(c => c.elevation);
  const minElev = Math.min(...elevations);
  const maxElev = Math.max(...elevations);

  function toSvgX(e: number) { return MARGIN + ((e - bounds.minE) / rangeE) * usableW; }
  function toSvgY(n: number) { return MARGIN + ((bounds.maxN - n) / rangeN) * usableH; }

  const svgLines: string[] = [];
  svgLines.push(`<?xml version="1.0" encoding="UTF-8"?>`);
  svgLines.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SVG_WIDTH} ${SVG_HEIGHT}" width="${SVG_WIDTH}" height="${SVG_HEIGHT}">`);
  svgLines.push(`<rect width="${SVG_WIDTH}" height="${SVG_HEIGHT}" fill="#1a1a2e"/>`);
  svgLines.push(`<rect x="${MARGIN}" y="${MARGIN}" width="${usableW}" height="${usableH}" fill="#0d1117" stroke="#30363d" stroke-width="1"/>`);

  // Hypsometric tint bands — discrete relief background.
  {
    const indexContours = contours.filter(c => c.isIndex).map(c => c.elevation).sort((a, b) => a - b);
    let ci = 1;
    if (indexContours.length >= 2) {
      const gaps: number[] = [];
      for (let i = 1; i < indexContours.length; i++) gaps.push(indexContours[i] - indexContours[i - 1]);
      ci = gaps.reduce((s, v) => s + v, 0) / gaps.length;
    } else {
      const sorted = contours.map(c => c.elevation).sort((a, b) => a - b);
      const gaps: number[] = [];
      for (let i = 1; i < sorted.length; i++) gaps.push(sorted[i] - sorted[i - 1]);
      ci = gaps.length ? gaps.reduce((s, v) => s + v, 0) / gaps.length : 1;
    }
    const bands = computeHypsometricBands(minElev, maxElev, ci);
    for (const band of bands) {
      const yTop = toSvgY(bounds.minN + (rangeN * (band.toElev - minElev)) / (maxElev - minElev || 1));
      const yBot = toSvgY(bounds.minN + (rangeN * (band.fromElev - minElev)) / (maxElev - minElev || 1));
      const h = Math.max(0, yBot - yTop);
      svgLines.push(`<rect x="${MARGIN}" y="${yTop.toFixed(2)}" width="${usableW}" height="${h.toFixed(2)}" fill="${band.color}" opacity="${band.isIndex ? 0.22 : 0.14}"/>`);
    }
  }

  // Contour lines
  for (const contour of contours) {
    const color = elevationToColor(contour.elevation, minElev, maxElev);
    const sw = contour.isIndex ? 2.0 : 0.8;
    const pts = contour.points.map(p => `${toSvgX(p.easting).toFixed(2)},${toSvgY(p.northing).toFixed(2)}`).join(' ');
    svgLines.push(`<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="${sw}" stroke-linejoin="round"/>`);

    if (contour.isIndex && contour.points.length > 5) {
      const midIdx = Math.floor(contour.points.length / 2);
      const midPt = contour.points[midIdx];
      const x = toSvgX(midPt.easting);
      const y = toSvgY(midPt.northing);
      svgLines.push(`<text x="${x.toFixed(2)}" y="${(y - 3).toFixed(2)}" fill="#e0e0e0" font-size="10" font-family="monospace" text-anchor="middle">${contour.elevation.toFixed(1)}</text>`);
    }
  }

  // Spot height crosses
  for (const pt of points) {
    const x = toSvgX(pt.easting);
    const y = toSvgY(pt.northing);
    svgLines.push(`<line x1="${(x - 3).toFixed(2)}" y1="${(y - 3).toFixed(2)}" x2="${(x + 3).toFixed(2)}" y2="${(y + 3).toFixed(2)}" stroke="#666" stroke-width="0.5"/>`);
    svgLines.push(`<line x1="${(x + 3).toFixed(2)}" y1="${(y - 3).toFixed(2)}" x2="${(x - 3).toFixed(2)}" y2="${(y + 3).toFixed(2)}" stroke="#666" stroke-width="0.5"/>`);
  }

  // Coordinate labels
  const numTicksE = 5;
  const numTicksN = 5;
  for (let i = 0; i <= numTicksE; i++) {
    const e = bounds.minE + (rangeE * i) / numTicksE;
    const x = toSvgX(e);
    svgLines.push(`<text x="${x.toFixed(2)}" y="${(SVG_HEIGHT - MARGIN / 3).toFixed(2)}" fill="#888" font-size="9" font-family="monospace" text-anchor="middle">${e.toFixed(1)}</text>`);
  }
  for (let i = 0; i <= numTicksN; i++) {
    const n = bounds.minN + (rangeN * i) / numTicksN;
    const y = toSvgY(n);
    svgLines.push(`<text x="${(MARGIN / 2).toFixed(2)}" y="${(y + 3).toFixed(2)}" fill="#888" font-size="9" font-family="monospace" text-anchor="middle">${n.toFixed(1)}</text>`);
  }

  // North arrow
  svgLines.push(`<g transform="translate(${SVG_WIDTH - 40}, ${MARGIN + 30})">`);
  svgLines.push(`<line x1="0" y1="20" x2="0" y2="0" stroke="#aaa" stroke-width="1.5"/>`);
  svgLines.push(`<polygon points="0,0 -4,8 4,8" fill="#aaa"/>`);
  svgLines.push(`<text x="0" y="30" fill="#aaa" font-size="10" text-anchor="middle" font-family="sans-serif">N</text>`);
  svgLines.push(`</g>`);

  // Scale bar
  const scaleBarWorldLen = rangeE / 5;
  const scaleBarSvgLen = usableW / 5;
  const sbX = MARGIN;
  const sbY = SVG_HEIGHT - 18;
  svgLines.push(`<line x1="${sbX}" y1="${sbY}" x2="${sbX + scaleBarSvgLen}" y2="${sbY}" stroke="#aaa" stroke-width="1.5"/>`);
  svgLines.push(`<line x1="${sbX}" y1="${sbY - 3}" x2="${sbX}" y2="${sbY + 3}" stroke="#aaa" stroke-width="1"/>`);
  svgLines.push(`<line x1="${(sbX + scaleBarSvgLen).toFixed(2)}" y1="${sbY - 3}" x2="${(sbX + scaleBarSvgLen).toFixed(2)}" y2="${sbY + 3}" stroke="#aaa" stroke-width="1"/>`);
  svgLines.push(`<text x="${(sbX + scaleBarSvgLen / 2).toFixed(2)}" y="${(sbY - 5).toFixed(2)}" fill="#aaa" font-size="9" text-anchor="middle" font-family="monospace">${scaleBarWorldLen.toFixed(1)} m</text>`);

  svgLines.push(`</svg>`);
  return svgLines.join('\n');
}

export function generateContourCSV(contours: ContourLine[]): string {
  const lines: string[] = [];
  lines.push('contour_id,elevation,is_index,point_index,easting,northing');
  let contourId = 0;
  for (const contour of contours) {
    contourId++;
    for (let i = 0; i < contour.points.length; i++) {
      const pt = contour.points[i];
      lines.push(
        `${contourId},${contour.elevation.toFixed(4)},${contour.isIndex ? 'true' : 'false'},${i},${pt.easting.toFixed(4)},${pt.northing.toFixed(4)}`
      );
    }
  }
  return lines.join('\n');
}

export function generateGeoJSON(contours: ContourLine[]): string {
  const features = contours.map((contour, idx) => ({
    type: 'Feature' as const,
    properties: {
      id: idx + 1,
      elevation: contour.elevation,
      is_index: contour.isIndex,
    },
    geometry: {
      type: 'MultiLineString' as const,
      coordinates: [
        contour.points.map(p => [p.easting, p.northing]),
      ],
    },
  }));
  const geojson = {
    type: 'FeatureCollection' as const,
    features,
  };
  return JSON.stringify(geojson, null, 2);
}

