// Tab 1: Import Points
//
// Extracted from src/app/tools/contour-generator/page.tsx.

import type { RefObject } from 'react';
import type { SpotHeight } from '@/lib/engine/contours';
import type { Bounds, ImportStats, ParseError } from './types';
import { fmt } from './helpers';

interface ImportTabProps {
  rawText: string;
  setRawText: (v: string) => void;
  fileName: string;
  points: SpotHeight[];
  parseErrors: ParseError[];
  importStats: ImportStats | null;
  isParsing: boolean;
  bounds: Bounds | null;
  fileInputRef: RefObject<HTMLInputElement | null>;
  handleDropZone: (e: React.DragEvent) => void;
  handleFileInput: (e: React.ChangeEvent<HTMLInputElement>) => void;
  handlePasteParse: () => void;
  handleLoadDemo: () => void;
}

export function ImportTab({
  rawText,
  setRawText,
  fileName,
  points,
  parseErrors,
  importStats,
  isParsing,
  bounds,
  fileInputRef,
  handleDropZone,
  handleFileInput,
  handlePasteParse,
  handleLoadDemo,
}: ImportTabProps) {
