          rows={10}
          placeholder={`Name,Easting,Northing,Elevation\nCP1,484500.000,9863100.000,1205.500\nCP2,484750.000,9863250.000,1182.250\nCP3,485000.000,9863400.000,1198.800\n...`}
          value={rawText}
          onChange={e => setRawText(e.target.value)}
