            </div>
            <div className="p-4 bg-[var(--bg-tertiary)] rounded">
              <span className="text-[var(--text-secondary)] text-sm block">Elevation Range</span>
              <span className="font-mono text-xl">{fmt(bounds.minZ, 1)} \u2013 {fmt(bounds.maxZ, 1)} m</span>
            </div>
          </div>

          {/* Bounding box */}
          <div className="mb-4">
