'use client';

/**
 * NTRIP / RTK Corrections Client
 *
 * AUDIT FIX (2026-07-03): Real-time GNSS correction client for receiving
 * RTK corrections from CORS networks (KENCORS, TANZACORS, etc.) via NTRIP.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { Satellite, Wifi, WifiOff, Activity, Zap } from 'lucide-react'
import { CORS_NETWORKS, RTCM_TYPE_NAMES, type RTCMMessage } from '@/lib/gnss/ntripClient'

export default function NTRIPClientPage() {
  const [network, setNetwork] = useState(CORS_NETWORKS[0].id)
  const [host, setHost] = useState(CORS_NETWORKS[0].host)
  const [port, setPort] = useState(CORS_NETWORKS[0].port)
  const [mountpoint, setMountpoint] = useState('')
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [connected, setConnected] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [messages, setMessages] = useState<RTCMMessage[]>([])
  const [messageCount, setMessageCount] = useState(0)
  const [lastMessageAt, setLastMessageAt] = useState<string | null>(null)
  const [statusMsg, setStatusMsg] = useState('')

  const eventSourceRef = useRef<EventSource | null>(null)

  useEffect(() => {
    const net = CORS_NETWORKS.find(n => n.id === network)
    if (net) { setHost(net.host); setPort(net.port) }
  }, [network])

  const connect = useCallback(() => {
    if (!host || !mountpoint) { setError('Host and mountpoint are required'); return }
    setError(null); setStatusMsg('Connecting...'); setMessages([]); setMessageCount(0)
    const params = new URLSearchParams({ host, port: String(port), mountpoint })
    if (username) params.set('user', username)
    if (password) params.set('pass', password)
    const es = new EventSource(`/api/gnss/ntrip?${params}`)
    eventSourceRef.current = es
    es.addEventListener('status', (e) => {
      const data = JSON.parse((e as MessageEvent).data as string) as { message?: string; error?: string; connected?: boolean }
      setStatusMsg(data.message || data.error || '')
      if (data.connected) { setConnected(true); setError(null) }
      else { setConnected(false); if (data.error) setError(data.error) }
    })
    es.addEventListener('rtcm', (e) => {
      const data = JSON.parse((e as MessageEvent).data as string) as { messageCount?: number; lastMessageAt?: string; type?: number; length?: number; receivedAt?: string }
      setMessageCount(data.messageCount ?? 0); setLastMessageAt(data.lastMessageAt ?? null)
      setMessages(prev => [...prev, { type: data.type ?? 0, length: data.length ?? 0, receivedAt: data.receivedAt ?? '' }].slice(-50))
    })
    es.onerror = () => { setConnected(false); setError('Connection lost'); es.close() }
  }, [host, port, mountpoint, username, password])

  const disconnect = useCallback(() => {
    if (eventSourceRef.current) { eventSourceRef.current.close(); eventSourceRef.current = null }
    setConnected(false); setStatusMsg('Disconnected')
  }, [])

  useEffect(() => { return () => { if (eventSourceRef.current) eventSourceRef.current.close() } }, [])

  const correctionAge = lastMessageAt ? Math.round((Date.now() - new Date(lastMessageAt).getTime()) / 1000) : null
  const messageTypeCounts = messages.reduce((acc, m) => { acc[m.type] = (acc[m.type] || 0) + 1; return acc }, {} as Record<number, number>)
  const selectedNetwork = CORS_NETWORKS.find(n => n.id === network)

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <PageHeader title="RTK Corrections (NTRIP)" subtitle="Real-time GNSS correction stream from CORS networks" reference="NTRIP v2 (RTCM 10410.1) | RTCM 3.3 | KENCORS" />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <h2 className="text-sm font-semibold text-white mb-4">Connection Settings</h2>
            <div className="space-y-3">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="cors-network">CORS Network</label>
                <select id="cors-network" value={network} onChange={e => setNetwork(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white">
                  {CORS_NETWORKS.map(n => <option key={n.id} value={n.id}>{n.name}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2">
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="caster-host">Caster Host</label>
                  <input id="caster-host" type="text" value={host} onChange={e => setHost(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
                </div>
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="port">Port</label>
                  <input id="port" type="number" value={port} onChange={e => setPort(parseInt(e.target.value) || 2101)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
                </div>
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="mountpoint">Mountpoint</label>
                <input id="mountpoint" type="text" value={mountpoint} onChange={e => setMountpoint(e.target.value)} placeholder="NBI0" className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="username-optional">Username (optional)</label>
                  <input id="username-optional" type="text" value={username} onChange={e => setUsername(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white" />
                </div>
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="password">Password</label>
                  <input  id="password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white" />
                </div>
              </div>
              <div className="flex gap-2 pt-2">
                {!connected ? (
                  <button onClick={connect} disabled={!host || !mountpoint} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-semibold disabled:opacity-40 hover:bg-green-700">
                    <Wifi className="w-4 h-4" /> Connect
                  </button>
                ) : (
                  <button onClick={disconnect} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700">
                    <WifiOff className="w-4 h-4" /> Disconnect
                  </button>
                )}
              </div>
            </div>
          </div>
          {selectedNetwork?.description && (
            <div className="bg-blue-500/5 border border-blue-500/15 rounded-xl p-4">
              <h3 className="text-sm font-semibold text-blue-400 mb-1">{selectedNetwork.name}</h3>
              <p className="text-xs text-[var(--text-muted)] leading-relaxed">{selectedNetwork.description}</p>
            </div>
          )}
        </div>
        <div className="space-y-4">
          <div className={`rounded-xl p-6 border ${connected ? 'bg-green-500/5 border-green-500/20' : 'bg-[var(--bg-card)] border-[var(--border-color)]'}`}>
            <div className="flex items-center gap-3 mb-4">
              {connected ? <Satellite className="w-6 h-6 text-green-400 animate-pulse" /> : <Satellite className="w-6 h-6 text-[var(--text-muted)]" />}
              <div>
                <div className="text-sm font-semibold text-white">{connected ? 'Connected' : 'Disconnected'}</div>
                <div className="text-xs text-[var(--text-muted)]">{statusMsg}</div>
              </div>
            </div>
            {error && <div className="p-3 rounded-lg bg-red-900/20 border border-red-700/40 text-red-400 text-xs mb-3">{error}</div>}
            <div className="grid grid-cols-3 gap-3">
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className="text-2xl font-bold text-white">{messageCount}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Messages</div>
              </div>
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className={`text-2xl font-bold ${correctionAge !== null && correctionAge > 10 ? 'text-red-400' : 'text-white'}`}>{correctionAge !== null ? `${correctionAge}s` : '—'}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Corr. Age</div>
              </div>
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className="text-2xl font-bold text-white">{Object.keys(messageTypeCounts).length}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Msg Types</div>
              </div>
            </div>
          </div>
          {messages.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-4">
              <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2"><Activity className="w-4 h-4 text-[var(--accent)]" />RTCM Message Types</h3>
              <div className="space-y-1 max-h-[200px] overflow-y-auto">
                {Object.entries(messageTypeCounts).sort((a, b) => b[1] - a[1]).map(([type, count]) => (
                  <div key={type} className="flex items-center justify-between text-xs">
                    <span className="font-mono text-[var(--text-muted)]">Type {type}</span>
                    <span className="text-white">{RTCM_TYPE_NAMES[parseInt(type)] || 'Unknown'}</span>
                    <span className="font-mono text-[var(--accent)]">{count}×</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'
import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { computeCurveElements, generateChainageTable, generateStakingTable, type HorizontalCurveData, type CurveElements, type ChainageTableEntry, type StakingPoint } from '@/lib/engineering/stakingTable'

export default function StakingTablePage() {
  const [ipE, setIpE] = useState(500000)
  const [ipN, setIpN] = useState(9800000)
  const [deflection, setDeflection] = useState(30)
  const [radius, setRadius] = useState(200)
  const [ipChainage, setIpChainage] = useState(1000)
  const [incomingBearing, setIncomingBearing] = useState(45)
  const [interval, setInterval] = useState(20)
  const [offsets, setOffsets] = useState('-3.5,0,3.5')
  const [computed, setComputed] = useState<{ elements: CurveElements; chainageTable: ChainageTableEntry[]; stakingTable: StakingPoint[] } | null>(null)

  const compute = () => {
    const data: HorizontalCurveData = { ipE, ipN, deflectionAngle: deflection, radius, ipChainage, incomingBearing }
    const elements = computeCurveElements(data)
    const chainageTable = generateChainageTable(data, elements, ipChainage + elements.tangent + 100)
    const offsetArr = offsets.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n))
    const stakingTable = generateStakingTable(data, elements, interval, undefined, undefined, offsetArr)
    setComputed({ elements, chainageTable, stakingTable })
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader title="Staking Table" subtitle="Batch staking + chainage schedule for setting out" reference="Route Surveying Ch.6 | RDM 1.3" />
      <div className="grid lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-easting">IP Easting</label><input id="ip-easting" type="number" value={ipE} onChange={e => setIpE(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-northing">IP Northing</label><input id="ip-northing" type="number" value={ipN} onChange={e => setIpN(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="deflection-angle">Deflection Angle (°)</label><input id="deflection-angle" type="number" step="0.1" value={deflection} onChange={e => setDeflection(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="radius-m">Radius (m)</label><input id="radius-m" type="number" value={radius} onChange={e => setRadius(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-chainage-m">IP Chainage (m)</label><input id="ip-chainage-m" type="number" value={ipChainage} onChange={e => setIpChainage(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="incoming-bearing">Incoming Bearing (°)</label><input id="incoming-bearing" type="number" step="0.1" value={incomingBearing} onChange={e => setIncomingBearing(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="stake-interval-m">Stake Interval (m)</label><input id="stake-interval-m" type="number" value={interval} onChange={e => setInterval(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="offsets-comma-sep-m">Offsets (comma-sep, m)</label><input id="offsets-comma-sep-m" type="text" value={offsets} onChange={e => setOffsets(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
          </div>
          <button onClick={compute} className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent)]/90 text-black font-semibold rounded-lg">Generate Staking Table</button>
        </div>
        <div>
          {computed ? (
            <div className="space-y-6">
              <div className="grid grid-cols-4 gap-3">
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">T (m)</div><div className="text-lg font-bold text-amber-400">{computed.elements.tangent.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">L (m)</div><div className="text-lg font-bold text-blue-400">{computed.elements.curveLength.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">E (m)</div><div className="text-lg font-bold text-green-400">{computed.elements.external.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">M (m)</div><div className="text-lg font-bold text-violet-400">{computed.elements.midOrdinate.toFixed(3)}</div></div>
              </div>
              <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-left py-2">Point</th><th className="text-left py-2">Description</th><th className="text-right py-2">Chainage</th><th className="text-right py-2">Easting</th><th className="text-right py-2">Northing</th><th className="text-right py-2">Bearing</th></tr></thead><tbody>{computed.chainageTable.map((r, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-2 font-mono text-amber-400">{r.point}</td><td className="py-2 text-zinc-300">{r.description}</td><td className="py-2 text-right font-mono text-white">{r.chainageLabel}</td><td className="py-2 text-right font-mono text-white">{r.easting.toFixed(3)}</td><td className="py-2 text-right font-mono text-white">{r.northing.toFixed(3)}</td><td className="py-2 text-right font-mono text-white">{r.bearing.toFixed(2)}°</td></tr>))}</tbody></table></div>
              <div className="overflow-x-auto"><h3 className="text-sm font-semibold text-white mb-2">Staking Table ({computed.stakingTable.length} stakes)</h3><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-right py-2">Chainage</th><th className="text-right py-2">Easting</th><th className="text-right py-2">Northing</th><th className="text-right py-2">Bearing</th><th className="text-right py-2">Segment</th></tr></thead><tbody>{computed.stakingTable.map((s, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-1.5 text-right font-mono text-amber-400">{s.chainageLabel}</td><td className="py-1.5 text-right font-mono text-white">{s.easting.toFixed(3)}</td><td className="py-1.5 text-right font-mono text-white">{s.northing.toFixed(3)}</td><td className="py-1.5 text-right font-mono text-white">{s.bearing.toFixed(2)}°</td><td className="py-1.5 text-right text-zinc-400">{s.segment}</td></tr>))}</tbody></table></div>
            </div>
          ) : <div className="p-6 bg-zinc-900 rounded-lg border border-zinc-700 text-center text-sm text-zinc-400">Enter curve data and click Generate.</div>}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { superelevationDesign, type SuperelevationInput } from '@/lib/computations/roadDesignEngine'

/**
 * AUDIT FIX (2026-07-03): Replaced the simplified inline formula
 * (e = V²/(127R), capped at 10%) with the real
 * roadDesignEngine.superelevationDesign() which uses RDM 1.3:
 *   - e_max = 8% (not 10%)
 *   - e = V²/(127R) - f  (subtracts friction factor)
 *   - Computes transition length Ls = e×w×V/(3.6×p)
 *   - Includes computation steps for transparency
 */

export default function SuperelevationPage() {
  const { t } = useLanguage()
  const [designSpeed, setDesignSpeed] = useState(60)
  const [radius, setRadius] = useState(200)
  const [numLanes, setNumLanes] = useState(2)
  const [laneWidth, setLaneWidth] = useState(3.5)
  const [roadClass, setRoadClass] = useState('DR3')

  const input: SuperelevationInput = {
    designSpeed,
    radius,
    numLanes,
    laneWidth,
    roadClass,
  }

  const result = superelevationDesign(input)

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.superelevation')}
        subtitle={t('tools.superelevationDesc')}
        reference="RDM 1.3 Section 5.3 | AASHTO Green Book 2018"
      />

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="design-speed-km-h">Design Speed (km/h)</label>
              <input id="design-speed-km-h" aria-label="Design Speed (km/h)"
                type="number"
                value={designSpeed}
                onChange={e => setDesignSpeed(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={20}
                max={120}
              />
            </div>
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="curve-radius-m">Curve Radius (m)</label>
              <input id="curve-radius-m" aria-label="Curve Radius (m)"
                type="number"
                value={radius}
                onChange={e => setRadius(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={25}
                max={5000}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="number-of-lanes">Number of Lanes</label>
              <input id="number-of-lanes" aria-label="Number of Lanes"
                type="number"
                value={numLanes}
                onChange={e => setNumLanes(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={1}
                max={6}
              />
            </div>
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="lane-width-m">Lane Width (m)</label>
              <input  id="lane-width-m" aria-label="Lane Width (m)"
                type="number"
                step="0.1"
                value={laneWidth}
                onChange={e => setLaneWidth(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={2.5}
                max={4.0}
              />
            </div>
          </div>

          {/* Results */}
          <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
            <div className="text-sm text-zinc-400 mb-1">Design Superelevation</div>
            <div className="text-3xl font-bold text-amber-400">{(result.designE * 100).toFixed(2)}%</div>              <div className="text-xs text-zinc-400 mt-1">
              Max allowable: 8% per RDM 1.3 (was 10% in old code)
            </div>
            {result.isCapped && (
              <div className="text-xs text-red-400 mt-1">
                ! Required e = {(result.requiredE * 100).toFixed(2)}% exceeds max — capped to 8%
              </div>
            )}
          </div>

          {/* Transition length */}
          <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
            <div className="text-sm text-zinc-400 mb-1">Transition Length (Ls)</div>
            <div className="text-2xl font-bold text-blue-400">{result.transitionLength.toFixed(2)}m</div>              <div className="text-xs text-zinc-400 mt-1">
              Ls = e × w × V / (3.6 × p), where w = {laneWidth}×{numLanes} = {(laneWidth * numLanes).toFixed(1)}m
            </div>
          </div>

          {/* Compliance */}
          <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
            <div className={`text-lg font-medium ${result.isCompliant ? 'text-green-400' : 'text-red-400'}`}>
              {result.isCompliant ? ' Compliant with RDM 1.3' : ' Non-compliant — radius too small for speed'}
            </div>              <div className="text-xs text-zinc-400 mt-1">
              Rate of change p = {(result.rateOfChange * 100).toFixed(2)}%/m (1% per 2.4m per RDM 1.3)
            </div>
          </div>

          {/* Computation steps */}
          {result.steps.length > 0 && (
            <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
              <h3 className="text-sm font-semibold text-white mb-3">Computation Steps</h3>
              <div className="space-y-2">
                {result.steps.map((step, i) => (
                  <div key={i} className="text-xs">
                    <div className="text-zinc-400">{step.description}</div>
                    <div className="text-zinc-400 font-mono">{step.formula}</div>
                    <div className="text-white font-mono">→ {step.value}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Reference table */}
        <div className="border border-zinc-700 rounded-lg p-4">
          <h3 className="font-medium text-white mb-4">Minimum Radius (RDM 1.3)</h3>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Speed (km/h)</th>
                <th className="text-right py-2">Min Radius (m)</th>
                <th className="text-right py-2">Max e (%)</th>
              </tr>
            </thead>
            <tbody>
              {[
                [30, 30, 8], [40, 60, 8], [50, 100, 8], [60, 150, 8],
                [70, 230, 8], [80, 320, 8], [90, 430, 8], [100, 560, 8],
              ].map(([speed, r, e]) => (
                <tr key={speed} className={`border-b border-zinc-800 ${speed === designSpeed ? 'bg-amber-900/20' : ''}`}>
                  <td className="py-2 text-zinc-400">{speed}</td>
                  <td className="py-2 text-right text-white">{r}</td>
                  <td className="py-2 text-right text-zinc-500">{e}</td>
                </tr>
              ))}
            </tbody>
          </table>            <p className="text-xs text-zinc-400 mt-3">
            Highlighted row matches current design speed. R = {radius}m
            {radius < 150 ? ' (below minimum for most speeds — increase radius)' : ' is adequate for current speed.'}
          </p>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useMemo, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'
import { useSession } from 'next-auth/react'
import { createClient } from '@/lib/api-client/client'
import SurveyReportBuilder from '@/components/surveyreport/SurveyReportBuilder'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface Project {
  id: string
  name: string
  location: string | null
}

function SurveyReportBuilderContent() {
  const params = useSearchParams()
  const projectId = params.get('projectId') || ''
  const reportId = params.get('reportId') || undefined
  const { data: session, status: sessionStatus } = useSession()
  const { t } = useLanguage()

  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState('')
  const [loading, setLoading] = useState(true)

  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])

  useEffect(() => {
    if (sessionStatus === 'loading') return
    if (!session?.user) {
      setLoading(false)
      return
    }

    async function load() {
      const { data } = await dbClient
        .from('projects')
        .select('id, name, location')
        .order('created_at', { ascending: false })
                .limit(50) as unknown as { data: Project[] | null }

      setProjects((data as Project[] | null) || [])
      setLoading(false)
    }

    load()
  }, [session, sessionStatus, dbClient])

  if (sessionStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!session?.user) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-4">
        <div className="text-center max-w-sm">
          <div className="w-16 h-16 rounded-2xl bg-[var(--accent)]/10 flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-[var(--accent)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z" />
            </svg>
          </div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-2">Sign in Required</h2>
          <p className="text-sm text-[var(--text-muted)] mb-6">
            You need to be signed in to create survey reports.
          </p>
          <a
            href="/login"
            className="inline-block px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm hover:bg-[var(--accent-dim)] transition-colors"
          >
            Sign In
          </a>
        </div>
      </div>
    )
  }

  if (!projectId) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] p-8">
        <div className="max-w-2xl mx-auto">
          <div className="mb-4">
            <MobileDesktopNotice>
              Report assembly has long forms, tables, previews, and export checks. Mobile is fine for selecting a project, but desktop is recommended before generating final documents.
            </MobileDesktopNotice>
          </div>
          <PageHeader
            title={t('tools.surveyReportBuilder')}
            subtitle={t('tools.surveyReportBuilderDesc')}
          />
          
          {projects.length === 0 ? (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-8 text-center">
              <p className="text-[var(--text-muted)] mb-4">No projects found.</p>
              <a
                href="/project/new"
                className="inline-block px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm"
              >
                Create New Project
              </a>
            </div>
          ) : (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Select Project</h2>
              <div className="space-y-2">
                {projects.map((p) => (
                  <button
                    key={p.id}
                    onClick={() => setSelectedProjectId(p.id)}
                    className={`w-full text-left px-4 py-3 rounded-lg border transition-colors ${
                      selectedProjectId === p.id
                        ? 'border-[var(--accent)] bg-[var(--accent)]/5'
                        : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
                    }`}
                  >
                    <div className="font-medium">{p.name}</div>
                    <div className="text-xs text-[var(--text-muted)]">{p.location || 'No location'}</div>
                  </button>
                ))}
              </div>
              <div className="flex justify-end mt-6">
                <a
                  href={`/tools/survey-report-builder?projectId=${selectedProjectId}`}
                  className={`px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm ${
                    !selectedProjectId ? 'opacity-40 pointer-events-none' : ''
                  }`}
                >
                  Continue →
                </a>
              </div>
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="px-4 pt-4">
        <MobileDesktopNotice>
          Report assembly has long forms, tables, previews, and export checks. Use desktop before issuing final documents.
        </MobileDesktopNotice>
      </div>
      <SurveyReportBuilder projectId={projectId} existingReportId={reportId} />
    </div>
  )
}

export default function SurveyReportBuilderPage() {
  const { t } = useLanguage()
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    }>
      <SurveyReportBuilderContent />
    </Suspense>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { tacheometrySolved } from '@/lib/engine/solution/wrappers/tacheometry'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function TacheometryCalculator() {
  const { t } = useLanguage()
  const [inputs, setInputs] = useState({
    hi: '',           // instrument height above ground (h.i.)
    upper: '',        // upper staff reading
    middle: '',       // middle staff reading
    lower: '',        // lower staff reading
    vertDeg: '',      // vertical angle degrees
    vertMin: '',      // vertical angle minutes
    vertSec: '',      // vertical angle seconds
    k: '100',         // multiplying constant
    c: '0'            // additive constant
  });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const HI = parseFloat(inputs.hi);
    const upper = parseFloat(inputs.upper);
    const middle = parseFloat(inputs.middle);
    const lower = parseFloat(inputs.lower);
    const K = parseFloat(inputs.k) || 100;
    const C = parseFloat(inputs.c) || 0;

    const deg = parseFloat(inputs.vertDeg) || 0
    const min = parseFloat(inputs.vertMin) || 0
    const sec = parseFloat(inputs.vertSec) || 0

    if (isNaN(HI) || isNaN(upper) || isNaN(middle) || isNaN(lower)) return;

    const s = tacheometrySolved({
      instrumentHeight: HI,
      upper,
      middle,
      lower,
      verticalAngle: { degrees: deg, minutes: min, seconds: sec, direction: 'N' },
      K,
      C,
    })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.tacheometry')}
        subtitle={t('tools.tacheometryDesc')}
        reference="Survey Regulations 1994 | RDM 1.1 (2025) Section 5.6 | Survey Act Cap 299"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Tacheometry Data</span></div>
          <div className="card-body space-y-4">
            <div>
              {/* h.i. = height of instrument above ground (not HPC — different context) */}
              <label className="label" htmlFor="instrument-height-above-ground-h-i-m">Instrument Height above Ground, h.i. (m)</label>
              <input id="instrument-height-above-ground-h-i-m" className="input" value={inputs.hi} onChange={e => setInputs({...inputs, hi: e.target.value})} placeholder="1.500" />
            </div>
            <div>
              <div className="label">Staff Readings (m)</div>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <label className="label text-xs" htmlFor="upper">Upper</label>
                  <input id="upper" className="input" value={inputs.upper} onChange={e => setInputs({...inputs, upper: e.target.value})} placeholder="1.850" />
                </div>
                <div>
                  <label className="label text-xs" htmlFor="middle">Middle</label>
                  <input id="middle" className="input" value={inputs.middle} onChange={e => setInputs({...inputs, middle: e.target.value})} placeholder="1.500" />
                </div>
                <div>
                  <label className="label text-xs" htmlFor="lower">Lower</label>
                  <input id="lower" className="input" value={inputs.lower} onChange={e => setInputs({...inputs, lower: e.target.value})} placeholder="1.150" />
                </div>
              </div>
            </div>
            <div>
              <div className="label">Vertical Angle (D° M&apos; S&quot;)</div>
              <div className="flex gap-2">
                <input className="input flex-1" value={inputs.vertDeg} onChange={e => setInputs({...inputs, vertDeg: e.target.value})} placeholder="05°" />
                <input className="input flex-1" value={inputs.vertMin} onChange={e => setInputs({...inputs, vertMin: e.target.value})} placeholder="30'" />
                <input className="input flex-1" value={inputs.vertSec} onChange={e => setInputs({...inputs, vertSec: e.target.value})} placeholder="00&quot;" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="multiplying-constant-k">Multiplying Constant K</label>
                <input id="multiplying-constant-k" className="input" value={inputs.k} onChange={e => setInputs({...inputs, k: e.target.value})} placeholder="100" />
              </div>
              <div>
                <label className="label" htmlFor="additive-constant-c">Additive Constant C</label>
                <input id="additive-constant-c" className="input" value={inputs.c} onChange={e => setInputs({...inputs, c: e.target.value})} placeholder="0" />
              </div>
            </div>
            {calcError && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{calcError}</div>}
            <button onClick={calculate} className="btn btn-primary w-full">{t('toolUI.calculate')}</button>
            {steps && (
              <div className="flex gap-2 mt-2">
                <button
                  onClick={() => {
                    generatePDF(
                      { title: 'Tacheometric Computation Sheet', reference: 'Survey Regulations 1994 | RDM 1.1 (2025) Section 5.6' },
                      [
                        { title: 'Observations', rows: [
                          { label: 'Instrument Height (h.i.)', value: `${inputs.hi} m` },
                          { label: 'Upper Staff Reading', value: `${inputs.upper} m` },
                          { label: 'Middle Staff Reading', value: `${inputs.middle} m` },
                          { label: 'Lower Staff Reading', value: `${inputs.lower} m` },
                          { label: 'Vertical Angle', value: `${inputs.vertDeg}° ${inputs.vertMin}' ${inputs.vertSec}"` },
                          { label: 'K (multiplying constant)', value: inputs.k },
                          { label: 'C (additive constant)', value: inputs.c },
                        ]},
                        { title: 'Computation Steps', rows: steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                      ],
                    )
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
                </button>
                <button
                  onClick={() => {
                    const csv = toCSV(
                      ['Parameter', 'Value'],
                      [
                        ['Instrument Height (m)', inputs.hi],
                        ['Upper Staff (m)', inputs.upper],
                        ['Middle Staff (m)', inputs.middle],
                        ['Lower Staff (m)', inputs.lower],
                        ['Vertical Angle', `${inputs.vertDeg}° ${inputs.vertMin}' ${inputs.vertSec}"`],
                        ['K', inputs.k],
                        ['C', inputs.c],
                        ...steps.map((s: SolutionStep) => [s.label, s.result || s.computation || '']),
                      ],
                    )
                    downloadCSV(csv, 'tacheometry-data')
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
                </button>
              </div>
            )}
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client'

import { useState, useMemo, useCallback } from 'react'
import { Mountain, Download, FileSpreadsheet, AlertCircle, CheckCircle2, Layers, Search } from 'lucide-react'
import { KENYA_TOPO_CODES } from '@/lib/topo/featureCodes'

interface TopoPoint {
  pointNumber: string; easting: number; northing: number; rl: number
  code: string; description: string
}

interface BreaklineInput {
  points: Array<{ x: number; y: number; z: number }>
  type: 'hard' | 'soft' | 'ridge' | 'valley'
}

interface ContourSanityIssue {
  severity: 'error' | 'warning'
  message: string
  suggestion?: string
}

interface ContourSanity {
  passed: boolean
  summary: string
  issues: ContourSanityIssue[]
}

export default function TopographicSurveyPage() {
  const [points, setPoints] = useState<TopoPoint[]>([])
  const [breaklines, setBreaklines] = useState<BreaklineInput[]>([])
  const [pointInput, setPointInput] = useState('')
  const [breaklineInput, setBreaklineInput] = useState('')
  const [contourInterval, setContourInterval] = useState('1.0')
  const [contours, setContours] = useState<unknown[] | null>(null)
  const [sanity, setSanity] = useState<ContourSanity | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [codeFilter, setCodeFilter] = useState('')

  // Feature code lookup
  const codeMap = useMemo(() => {
    const m = new Map<string, string>()
    for (const def of KENYA_TOPO_CODES) m.set(def.code.toUpperCase(), def.description)
    return m
  }, [])

  const filteredCodes = useMemo(() => {
    if (!codeFilter) return KENYA_TOPO_CODES.slice(0, 30)
    return KENYA_TOPO_CODES.filter(c =>
      c.code.toLowerCase().includes(codeFilter.toLowerCase()) ||
      c.description.toLowerCase().includes(codeFilter.toLowerCase())
    ).slice(0, 30)
  }, [codeFilter])

  const handleParsePoints = useCallback(() => {
    const parsed = pointInput.trim().split('\n').map(line => {
      const cols = line.split(',').map(c => c.trim())
      return {
        pointNumber: cols[0] || `PT${Date.now()}`,
        easting: parseFloat(cols[1]), northing: parseFloat(cols[2]),
        rl: parseFloat(cols[3]),
        code: cols[4] || '', description: cols[5] || codeMap.get((cols[4] || '').toUpperCase()) || '',
      }
    }).filter(p => !isNaN(p.easting) && !isNaN(p.northing) && !isNaN(p.rl))
    setPoints(parsed)
  }, [pointInput, codeMap])

  const handleParseBreaklines = useCallback(() => {
    // Format: type,x1,y1,z1,x2,y2,z2,...
    const lines = breaklineInput.trim().split('\n')
    const parsed: BreaklineInput[] = []
    for (const line of lines) {
      const cols = line.split(',').map(c => c.trim())
      const type = (cols[0] as BreaklineInput['type']) || 'hard'
      const pts: Array<{ x: number; y: number; z: number }> = []
      for (let i = 1; i < cols.length - 2; i += 3) {
        const x = parseFloat(cols[i]), y = parseFloat(cols[i + 1]), z = parseFloat(cols[i + 2])
        if (!isNaN(x) && !isNaN(y) && !isNaN(z)) pts.push({ x, y, z })
      }
      if (pts.length >= 2) parsed.push({ points: pts, type })
    }
    setBreaklines(parsed)
  }, [breaklineInput])

  const handleGenerateContours = async () => {
    if (points.length < 3) { setError('Need ≥3 points'); return }
    setLoading(true); setError(''); setContours(null); setSanity(null)
    try {
      const res = await fetch('/api/topo/generate-contours', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({ x: p.easting, y: p.northing, z: p.rl })),
          breaklines,
          interval: parseFloat(contourInterval),
        }),
      })
      if (!res.ok) { const e = (await res.json()) as { error?: string }; throw new Error(e.error || 'Failed') }
      const data = (await res.json()) as { data: { contours: unknown[]; sanity: ContourSanity } }
      setContours(data.data.contours)
      setSanity(data.data.sanity)
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed') }
    finally { setLoading(false) }
  }

  const handleExportDXF = async () => {
    if (points.length === 0) return
    try {
      const res = await fetch('/api/topo/export-dxf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({
            easting: p.easting, northing: p.northing, elevation: p.rl,
            code: p.code, pointNumber: p.pointNumber,
          })),
          projectName: 'Topographic Survey',
        }),
      })
      if (!res.ok) throw new Error('Export failed')
      const data = (await res.json()) as { content: string | ArrayBuffer; mimeType: string; filename: string }
      const blob = new Blob([data.content], { type: data.mimeType })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = data.filename; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { setError(e instanceof Error ? e.message : 'Export failed') }
  }

  const handleExportSpotHeights = async () => {
