          </div>
        </div>

        {/* Errors */}
        {computeErrors.length > 0 && (
          <div className="p-4 bg-red-900/20 border border-red-800/30 rounded-lg">
            <h4 className="text-sm font-medium text-red-400 mb-1">Computation Errors</h4>
            <ul className="text-xs text-red-300/80 space-y-0.5">
              {computeErrors.map((err, i) => <li key={`${err}-${i}`}>{err}</li>)}
            </ul>
          </div>
        )}

        {/* Warnings */}
        {computeWarnings.length > 0 && (
          <div className="p-4 bg-amber-900/20 border border-amber-800/30 rounded-lg">
            <h4 className="text-sm font-medium text-amber-400 mb-1">Warnings</h4>
            <ul className="text-xs text-amber-300/80 space-y-0.5">
              {computeWarnings.map((w, i) => <li key={`${w}-${i}`}>{w}</li>)}
            </ul>
          </div>
        )}

        {/* Results */}
        {cutVolume !== null && fillVolume !== null && netVolume !== null && (
          <>
            {/* Volume Summary Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="p-4 bg-[#8B4513]/15 border border-[#8B4513]/40 rounded-lg">
                <div className="text-xs text-[#D2691E] mb-1">Cut Volume</div>
                <div className="text-2xl font-bold font-mono text-[#D2691E]">{cutVolume.toFixed(2)} m³</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Material removed ({cutPct.toFixed(1)}%)
                </div>
              </div>
              <div className="p-4 bg-[#4169E1]/15 border border-[#4169E1]/40 rounded-lg">
                <div className="text-xs text-[#6495ED] mb-1">Fill Volume</div>
                <div className="text-2xl font-bold font-mono text-[#6495ED]">{fillVolume.toFixed(2)} m³</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Material added ({fillPct.toFixed(1)}%)
                </div>
              </div>
              <div className={`p-4 border rounded-lg ${netVolume >= 0 ? 'bg-amber-900/20 border-amber-800/30' : 'bg-blue-900/20 border-blue-800/30'}`}>
                <div className={`text-xs mb-1 ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>Net Volume</div>
                <div className={`text-2xl font-bold font-mono ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>
                  {netVolume >= 0 ? '+' : ''}{netVolume.toFixed(2)} m³
                </div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  {netVolume >= 0 ? 'Cut dominant — surplus material' : 'Fill dominant — borrow needed'}
                </div>
              </div>
              <div className="p-4 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Area Overlap</div>
                <div className="text-2xl font-bold font-mono text-[var(--text-primary)]">{overlapArea?.toFixed(2)} m²</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Grid: {gridSpacing}m spacing
                </div>
              </div>
            </div>

            {/* Cut/Fill Bar */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
              <h3 className="text-lg font-semibold mb-4">Cut / Fill Balance</h3>
              <div className="relative h-12 rounded-lg overflow-hidden flex">
                {cutPct > 0 && (
                  <div
                    className="flex items-center justify-center transition-all duration-500"
                    style={{
                      width: `${cutPct}%`,
                      backgroundColor: '#8B4513',
                      minWidth: cutVolume > 0 ? '40px' : '0',
                    }}
                  >
                    <span className="text-white text-xs font-mono font-bold drop-shadow">
                      Cut {cutPct.toFixed(0)}%
                    </span>
                  </div>
                )}
                {fillPct > 0 && (
                  <div
                    className="flex items-center justify-center transition-all duration-500"
                    style={{
                      width: `${fillPct}%`,
                      backgroundColor: '#4169E1',
                      minWidth: fillVolume > 0 ? '40px' : '0',
                    }}
                  >
                    <span className="text-white text-xs font-mono font-bold drop-shadow">
                      Fill {fillPct.toFixed(0)}%
                    </span>
                  </div>
                )}
                {total === 0 && (
                  <div className="w-full flex items-center justify-center bg-gray-600">
                    <span className="text-white text-xs">No volume</span>
                  </div>
                )}
              </div>
              <div className="flex justify-between mt-2 text-xs text-[var(--text-muted)]">
                <span className="flex items-center gap-1">
                  <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: '#8B4513' }} />
                  Cut (Survey A &gt; B)
                </span>
                <span className="flex items-center gap-1">
                  <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: '#4169E1' }} />
                  Fill (Survey B &gt; A)
                </span>
              </div>
            </div>

            {/* Additional metrics */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {fillVolume > 0 && (
                <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                  <div className="text-xs text-[var(--text-secondary)] mb-1">Cut/Fill Ratio</div>
                  <div className="text-xl font-bold font-mono text-[var(--text-primary)]">{(cutVolume / fillVolume).toFixed(3)}</div>
                  <div className="text-xs text-[var(--text-muted)] mt-0.5">
                    {Math.abs(cutVolume / fillVolume - 1) < 0.05
                      ? 'Nearly balanced — minimal import/export'
                      : cutVolume / fillVolume > 1
                        ? 'Cut surplus — export material needed'
                        : 'Fill deficit — import material needed'}
                  </div>
                </div>
              )}
              {balancePoint !== null && (
                <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                  <div className="text-xs text-[var(--text-secondary)] mb-1">Balance Point (Datum)</div>
                  <div className="text-xl font-bold font-mono text-[var(--text-primary)]">{balancePoint.toFixed(3)} m</div>
                  <div className="text-xs text-[var(--text-muted)] mt-0.5">
                    Elevation where cut = fill
                  </div>
                </div>
              )}
              <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Computation Method</div>
                <div className="text-xl font-bold font-mono text-[var(--text-primary)]">
                  {method === 'tin' ? 'TIN' : 'IDW'}
                </div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Grid spacing: {gridSpacing}m | {gridCells.length} cells evaluated
                </div>
              </div>
            </div>

            {/* Per-cell grid visualization */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold">Per-Cell Analysis Grid</h3>
                <button
                  onClick={() => setShowGrid(!showGrid)}
                  className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-xs hover:border-[var(--accent)] transition-colors"
                >
                  {showGrid ? 'Hide Grid' : 'Show Grid'}
                </button>
              </div>

              {showGrid && gridCells.length > 0 && (
                <div className="overflow-x-auto">
                  <svg
                    viewBox={`${gridBBox.minE} ${gridBBox.minN} ${gridBBox.maxE - gridBBox.minE} ${gridBBox.maxN - gridBBox.minN}`}
                    className="w-full border border-[var(--border-color)] rounded bg-[#1a1a1a]"
                    style={{ minHeight: 300, maxHeight: 600 }}
                  >
                    {gridCells.map((cell, i) => {
                      const opacity = Math.min(1, (Math.abs(cell.diff) / maxAbsDiff) * 0.85 + 0.15);
                      let color: string;
                      if (cell.type === 'cut') color = `rgba(139, 69, 19, ${opacity})`;
                      else if (cell.type === 'fill') color = `rgba(65, 105, 225, ${opacity})`;
                      else color = `rgba(128, 128, 128, 0.15)`;

                      return (
                        <g key={`${cell}-${i}`}>
                          <rect
                            x={cell.easting}
                            y={cell.northing}
                            width={gridSpacing}
                            height={gridSpacing}
                            fill={color}
                            stroke="#333"
                            strokeWidth={0.5}
                          />
                        </g>
                      );
                    })}
                    {/* Scale reference */}
                    <rect
                      x={gridBBox.minE + 2}
                      y={gridBBox.minN + 2}
                      width={10 * gridSpacing}
                      height={5 * gridSpacing}
                      fill="none"
                      stroke="#fff"
                      strokeWidth={1}
                      rx={2}
                    />
                    <text
                      x={gridBBox.minE + 2 + 5 * gridSpacing}
                      y={gridBBox.minN + 2 + 5 * gridSpacing + 4}
                      fill="#fff"
                      fontSize={gridSpacing * 2}
                      textAnchor="middle"
                    >
                      {10 * gridSpacing}m
                    </text>
                  </svg>

                  {/* Legend */}
                  <div className="flex items-center gap-6 mt-3 text-xs text-[var(--text-muted)] justify-center">
                    <div className="flex items-center gap-1.5">
                      <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: '#8B4513' }} />
                      <span>Cut (A higher)</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: '#4169E1' }} />
                      <span>Fill (B higher)</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: 'rgba(128, 128, 128, 0.15)', border: '1px solid #555' }} />
                      <span>No change</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="text-[var(--text-secondary)]">Opacity ∝ magnitude</span>
                    </div>
                  </div>

                  {/* Grid stats */}
                  <div className="grid grid-cols-3 gap-3 mt-4">
                    <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
                      <div className="text-xs text-[var(--text-muted)]">Cut Cells</div>
                      <div className="text-lg font-bold font-mono text-[#D2691E]">
                        {gridCells.filter(c => c.type === 'cut').length}
                      </div>
                    </div>
                    <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
                      <div className="text-xs text-[var(--text-muted)]">Fill Cells</div>
                      <div className="text-lg font-bold font-mono text-[#6495ED]">
                        {gridCells.filter(c => c.type === 'fill').length}
                      </div>
                    </div>
                    <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
                      <div className="text-xs text-[var(--text-muted)]">No Change</div>
                      <div className="text-lg font-bold font-mono text-[var(--text-secondary)]">
                        {gridCells.filter(c => c.type === 'none').length}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {!showGrid && gridCells.length > 0 && (
                <p className="text-sm text-[var(--text-secondary)]">
                  Click &quot;Show Grid&quot; to display {gridCells.length} color-coded cells.
                </p>
              )}

              {gridCells.length === 0 && hasComputed.current && (
                <p className="text-sm text-[var(--text-muted)]">
                  No grid cells were computed. Ensure both surveys have overlapping extents.
                </p>
              )}
            </div>
          </>
        )}

        {/* Not yet computed */}
        {cutVolume === null && computeErrors.length === 0 && (
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-12 text-center">
            <div className="text-4xl mb-3 opacity-40">[Chart]</div>
            <p className="text-[var(--text-secondary)]">
              Configure settings and click &quot;Compute Volume&quot; to see results.
            </p>
            <p className="text-sm text-[var(--text-muted)] mt-1">
              Load data for both Survey A and Survey B first.
            </p>
          </div>
        )}
      </div>
    );
  };

  const renderExport = () => {
    const canExport = cutVolume !== null && fillVolume !== null;

    return (
      <div className="space-y-6">
        <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
          <h3 className="text-lg font-semibold mb-4">Export Options</h3>

          {!canExport && (
            <p className="text-sm text-[var(--text-muted)] mb-6">
              Run the volume computation first before exporting results.
            </p>
          )}

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/* Export results CSV */}
            <div className="p-4 bg-[var(--bg-tertiary)] rounded-lg border border-[var(--border-color)]">
              <div className="flex items-center gap-2 mb-3">
                <span className="text-2xl"></span>
                <div>
                  <h4 className="font-medium text-sm">Results Summary (CSV)</h4>
                  <p className="text-xs text-[var(--text-muted)]">Volume metadata + statistics</p>
                </div>
              </div>
              <button
                onClick={exportResultsCSV}
                disabled={!canExport}
                className="w-full px-4 py-2 bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-sm hover:border-[var(--accent)] hover:text-[var(--accent)] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                Export Results CSV
              </button>
            </div>

            {/* Export grid CSV */}
            <div className="p-4 bg-[var(--bg-tertiary)] rounded-lg border border-[var(--border-color)]">
              <div className="flex items-center gap-2 mb-3">
                <span className="text-2xl">[Compass]</span>
                <div>
                  <h4 className="font-medium text-sm">Cut/Fill Grid (CSV)</h4>
                  <p className="text-xs text-[var(--text-muted)]">Per-cell easting, northing, diff, type</p>
                </div>
              </div>
              <button
                onClick={exportGridCSV}
                disabled={gridCells.length === 0}
                className="w-full px-4 py-2 bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-sm hover:border-[var(--accent)] hover:text-[var(--accent)] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                Export Grid CSV ({gridCells.length} cells)
              </button>
            </div>

            {/* Print report */}
            <div className="p-4 bg-[var(--bg-tertiary)] rounded-lg border border-[var(--border-color)]">
              <div className="flex items-center gap-2 mb-3">
                <span className="text-2xl"></span>
                <div>
                  <h4 className="font-medium text-sm">Print-Friendly Report</h4>
                  <p className="text-xs text-[var(--text-muted)]">Browser print dialog</p>
                </div>
              </div>
              <button
                onClick={handlePrint}
                disabled={!canExport}
                className="w-full px-4 py-2 bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-sm hover:border-[var(--accent)] hover:text-[var(--accent)] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                Print Report
              </button>
            </div>
          </div>
        </div>

        {/* Print preview (visible only during print) */}
        {canExport && (
          <div className="print:block hidden">
            <h1 className="text-2xl font-bold mb-4">Volume Comparison Report</h1>
            <div className="grid grid-cols-2 gap-4 mb-6 text-sm">
              <div>
                <div className="font-medium">Survey A: {surveyAPoints.length} points</div>
                {bboxA && <div>BBox: E {bboxA.minE.toFixed(1)}–{bboxA.maxE.toFixed(1)}, N {bboxA.minN.toFixed(1)}–{bboxA.maxN.toFixed(1)}</div>}
              </div>
              <div>
                <div className="font-medium">Survey B: {surveyBPoints.length} points</div>
                {bboxB && <div>BBox: E {bboxB.minE.toFixed(1)}–{bboxB.maxE.toFixed(1)}, N {bboxB.minN.toFixed(1)}–{bboxB.maxN.toFixed(1)}</div>}
              </div>
            </div>
            <div className="border-t border-b py-4 mb-4">
              <div className="grid grid-cols-3 gap-4 text-center">
                <div>
                  <div className="text-xs text-gray-500">Cut Volume</div>
                  <div className="text-xl font-bold">{cutVolume?.toFixed(2)} m³</div>
                </div>
                <div>
                  <div className="text-xs text-gray-500">Fill Volume</div>
                  <div className="text-xl font-bold">{fillVolume?.toFixed(2)} m³</div>
                </div>
                <div>
                  <div className="text-xs text-gray-500">Net Volume</div>
                  <div className="text-xl font-bold">{netVolume?.toFixed(2)} m³</div>
                </div>
              </div>
            </div>
            <div className="text-xs text-gray-500">
              Method: {method === 'tin' ? 'TIN Interpolation' : 'IDW Grid'} | Grid Spacing: {gridSpacing}m | Balance Point: {balancePoint !== null ? `${balancePoint.toFixed(3)}m` : 'N/A'}
            </div>
          </div>
        )}
      </div>
    );
  };

  // ─── Main render ────────────────────────────────────────────────────────

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.volumeComparison')}
        subtitle={t('tools.volumeComparisonDesc')}
      />

      {/* Tab bar */}
      <div className="flex gap-2 mb-6 flex-wrap">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${
              activeTab === tab.id
                ? 'bg-[var(--accent)] text-black'
                : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] hover:text-[var(--accent)] hover:border-[var(--accent)]/50'
            }`}
          >
            {tab.label}
            {tab.badge && (
              <span className={`text-xs px-1.5 py-0.5 rounded-full ${
                activeTab === tab.id
                  ? 'bg-black/20 text-black'
                  : 'bg-[var(--accent)]/10 text-[var(--accent)]'
              }`}>
                {tab.badge}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Tab content */}
      {activeTab === 'surveyA' && renderSurveyImport('A')}
      {activeTab === 'surveyB' && renderSurveyImport('B')}
      {activeTab === 'analysis' && renderAnalysis()}
      {activeTab === 'export' && renderExport()}
    </div>
  );
}

'use client';

/**
 * Integrated Topographic Survey Pipeline
 *
 * AUDIT FIX (2026-07-03): Previously a surveyor had to hop between 4-5
 * separate tool pages to produce a topographic map. This page provides
 * a single guided workflow that chains:
 *   1. Import field data (CSV / project points)
 *   2. Generate contours (TIN + marching triangles)
 *   3. Analyze slope (optional)
 *   4. Compute volumes (optional)
 *   5. Generate cross-sections (optional)
 *   6. Auto-draw topo plan (feature codes → DXF)
 *   7. Export (DXF / Shapefile / GeoJSON / KML)
 *
 * Each step links to the full-featured tool page for advanced options,
 * but the surveyor can see the whole pipeline in one place and track
 * progress.
 */

import { useState, useEffect } from 'react'
import Link from 'next/link'
import {
  Upload, Mountain, TrendingUp, Box, Scissors, FileCode, Download,
  CheckCircle2, Circle, ArrowRight, Loader2,
} from 'lucide-react'
import { PageHeader } from '@/components/shared/PageHeader'

interface PipelineStep {
  id: string
  number: number
  title: string
  description: string
  href: string
  icon: typeof Upload
  optional?: boolean
  status: string
}

const PIPELINE_STEPS: PipelineStep[] = [
  {
    id: 'import',
    number: 1,
    title: 'Import Field Data',
    description: 'Upload total station CSV, GNSS RINEX, GSI, RW5, or point cloud (LAS/PLY). Or load points from an existing project.',
    href: '/import',
    icon: Upload,
    status: 'pending' as const,
  },
  {
    id: 'contours',
    number: 2,
    title: 'Generate Contours',
    description: 'Delaunay TIN + marching-triangles contour generation. Set interval, add breaklines, export DXF/SVG/CSV/GeoJSON.',
    href: '/tools/contour-generator',
    icon: Mountain,
    status: 'pending' as const,
  },
  {
    id: 'slope',
    number: 3,
    title: 'Slope Analysis',
    description: 'IDW grid + Horn\'s method. Aspect, KENHA road classification, balance-point binary search.',
    href: '/tools/slope-analysis',
    icon: TrendingUp,
    status: 'pending' as const,
    optional: true,
  },
  {
    id: 'volumes',
    number: 4,
    title: 'Volume Computation',
    description: 'End-area, prismoidal, grid, or TIN-vs-TIN. Cut/fill volumes with mass-haul diagrams.',
    href: '/tools/volume-comparison',
    icon: Box,
    status: 'pending' as const,
    optional: true,
  },
  {
    id: 'sections',
    number: 5,
    title: 'Cross-Sections',
    description: 'TIN sampling along centerline at chainage intervals. CSV/DXF/PDF output.',
    href: '/tools/cross-sections',
    icon: Scissors,
    status: 'pending' as const,
    optional: true,
  },
  {
    id: 'drawing',
    number: 6,
    title: 'Topo Plan Drawing',
    description: 'Auto-generate DXF with Survey of Kenya feature codes, spot heights, north arrow, scale bar, title block.',
    href: '/tools/topo-drawing',
    icon: FileCode,
    status: 'pending' as const,
  },
  {
    id: 'export',
    number: 7,
    title: 'Export',
    description: 'DXF (AutoCAD/Civil 3D), Shapefile (QGIS/ArcGIS), GeoJSON, KML, LandXML.',
    href: '/tools/gis-export',
    icon: Download,
    status: 'pending' as const,
  },
]

export default function TopographicWorkflowPage() {
  const [steps, setSteps] = useState<PipelineStep[]>(PIPELINE_STEPS)
  const [projectId, setProjectId] = useState<string | null>(null)

  // Load progress from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('metardu_topo_pipeline')
    if (saved) {
      try {
        const data = JSON.parse(saved) as { steps: PipelineStep[]; projectId?: string }
        if (data.steps) {
          setSteps(prev => prev.map(s => {
            const savedStep = data.steps.find((ss: PipelineStep) => ss.id === s.id)
            return savedStep ? { ...s, status: savedStep.status } : s
          }))
        }
        if (data.projectId) setProjectId(data.projectId)
      } catch { /* ignore */ }
    }
  }, [])

  const saveProgress = (newSteps: PipelineStep[]) => {
    localStorage.setItem('metardu_topo_pipeline', JSON.stringify({ steps: newSteps, projectId }))
  }

  const toggleStepDone = (id: string) => {
    const newSteps: PipelineStep[] = steps.map(s =>
      s.id === id
        ? { ...s, status: s.status === 'done' ? 'pending' as const : 'done' as const }
        : s
    )
    setSteps(newSteps)
    saveProgress(newSteps)
  }

  const completedCount = steps.filter(s => s.status === 'done').length
  const requiredSteps = steps.filter(s => !s.optional)
  const requiredCompleted = requiredSteps.filter(s => s.status === 'done').length
  const progressPct = Math.round((completedCount / steps.length) * 100)

  return (
    <div className="max-w-5xl mx-auto px-4 md:px-6 py-8">
      <PageHeader
        title="Topographic Survey Pipeline"
        subtitle="Complete workflow: field data → contours → analysis → topo plan → export"
        reference="Survey Act Cap. 299 | RDM 1.1 | Survey Regulations 1994"
      />

      {/* Progress bar */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-[var(--text-secondary)]">
            {completedCount} of {steps.length} steps complete ({requiredCompleted}/{requiredSteps.length} required)
          </span>
          <span className="text-sm font-bold text-[var(--accent)]">{progressPct}%</span>
        </div>
        <div className="w-full bg-[var(--bg-tertiary)] rounded-full h-2.5 overflow-hidden">
          <div
            className="bg-[var(--accent)] h-2.5 rounded-full transition-all duration-500"
            style={{ width: `${progressPct}%` }}
          />
        </div>
      </div>

      {/* Pipeline steps */}
      <div className="space-y-3">
        {steps.map((step, index) => {
          const Icon = step.icon
          const isDone = step.status === 'done'
          const isLast = index === steps.length - 1

          return (
            <div key={step.id}>
              <div
                className={`flex items-start gap-4 p-4 rounded-xl border transition-all ${
                  isDone
                    ? 'bg-[var(--accent)]/5 border-[var(--accent)]/30'
                    : 'bg-[var(--bg-card)] border-[var(--border-color)] hover:border-[var(--accent)]/20'
                }`}
              >
                {/* Step number / checkmark */}
                <button
                  onClick={() => toggleStepDone(step.id)}
                  className="mt-0.5 shrink-0"
                  title={isDone ? 'Mark as not done' : 'Mark as done'}
                >
                  {isDone ? (
                    <CheckCircle2 className="w-6 h-6 text-[var(--accent)]" />
                  ) : (
                    <Circle className="w-6 h-6 text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors" />
                  )}
                </button>

                {/* Icon */}
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${
                  isDone ? 'bg-[var(--accent)]/15' : 'bg-[var(--bg-tertiary)]'
                }`}>
                  <Icon className={`w-5 h-5 ${isDone ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className={`font-semibold text-sm ${isDone ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                      {step.number}. {step.title}
                    </h3>
                    {step.optional && (
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-[var(--bg-tertiary)] text-[var(--text-muted)]">
                        optional
                      </span>
                    )}
                  </div>
                  <p className="text-xs text-[var(--text-muted)] leading-relaxed mb-2">
                    {step.description}
                  </p>
                  <Link
                    href={step.href}
                    className="inline-flex items-center gap-1 text-xs font-medium text-[var(--accent)] hover:gap-2 transition-all"
                  >
                    Open tool
                    <ArrowRight className="w-3 h-3" />
                  </Link>
                </div>
              </div>

              {/* Connector arrow */}
              {!isLast && (
                <div className="flex justify-center py-1">
                  <ArrowRight className="w-4 h-4 text-[var(--text-muted)] rotate-90" />
                </div>
              )}
            </div>
          )
        })}
      </div>

      {/* Reset button */}
      <div className="mt-6 flex justify-end">
        <button
          onClick={() => {
            const reset = steps.map(s => ({ ...s, status: 'pending' as const }))
            setSteps(reset)
            saveProgress(reset)
          }}
          className="text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
        >
          Reset progress
        </button>
      </div>

      {/* Info box */}
      <div className="mt-8 p-4 rounded-xl bg-blue-500/5 border border-blue-500/15">
        <h4 className="text-sm font-semibold text-blue-400 mb-2">How to use this pipeline</h4>
        <ol className="text-xs text-[var(--text-muted)] space-y-1 list-decimal list-inside">
          <li>Start at step 1 — import your field data (CSV, RINEX, or point cloud)</li>
          <li>Proceed through each step in order — click "Open tool" to use the full-featured tool page</li>
          <li>Mark each step as done by clicking the circle on the left</li>
          <li>Optional steps (slope, volumes, cross-sections) can be skipped for simple topo jobs</li>
          <li>Your progress is saved automatically — you can leave and come back</li>
          <li>Final export produces DXF/SHP/GeoJSON/KML for AutoCAD, Civil 3D, QGIS, or ArcGIS</li>
        </ol>
      </div>
    </div>
  )
}

import { createClient } from '@/lib/api-client/server';
import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';
import WorkingDiagramClient, { type ProjectInfo, type FieldbookEntry } from './WorkingDiagramClient';

interface Props {
  searchParams: { projectId?: string };
}

export default async function WorkingDiagramPage({ searchParams }: Props) {
  const { projectId } = searchParams;
  if (!projectId) redirect('/projects');

  const dbClient = await createClient();

  const { data: { session } } = await dbClient.auth.getSession();
  if (!session) redirect('/login');

  const { data: project } = await dbClient
    .from('projects')
    .select(`
      id, name, survey_type, lr_number, locality,
      registration_district, utm_zone, hemisphere, datum
    `)
    .eq('id', projectId)
    .eq('user_id', (session as { user?: { id?: string } } | null)?.user?.id as string)
    .single();

  if (!project) redirect('/projects');

  const { data: entries } = await dbClient
    .from('project_fieldbook_entries')
    .select('row_index, station, raw_data, bs, remark')
    .eq('project_id', projectId)
    .order('row_index', { ascending: true });

  return (
    <WorkingDiagramClient
      project={project as unknown as ProjectInfo}
      entries={(entries ?? []) as unknown as FieldbookEntry[]}
      projectId={projectId}
    />
  );
}

'use client';

import { useState, useId } from 'react'
import { Download , AlertTriangle } from 'lucide-react'
import { inverseComputation, polarComputation, intersectionComputation, resectionComputation, areaComputation, joinComputation, distanceDistanceIntersection, bearingDistanceIntersection, arcByRadiusAndChord, type InverseStep, type DistDistResult, type BearingDistResult, type ArcResult } from '@/lib/computations/cogoEngine'
import { downloadCSV, toCSV } from '@/lib/export/helpers'
import { logger } from '@/lib/logger'

type Tab = 'inverse' | 'polar' | 'intersection' | 'distDist' | 'bearingDist' | 'arcBoundary' | 'resection' | 'area' | 'join'

interface Props {
  compact?: boolean
}

function DMSField({ label, deg, min, sec, onChange }: { label: string; deg: string; min: string; sec: string; onChange: (f: 'd' | 'm' | 's', v: string) => void }) {
  const degId = useId()
  return (
    <div>
      <label htmlFor={degId} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
      <div className="flex gap-1">
        <input id={degId} value={deg} onChange={e => onChange('d', e.target.value)} type="number" min="0" max="359" placeholder="Deg"
          className="w-10 md:w-14 px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
        <input value={min} onChange={e => onChange('m', e.target.value)} type="number" min="0" max="59" aria-label={`${label} — minutes`} placeholder="Min"
          className="w-8 md:w-12 px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
        <input value={sec} onChange={e => onChange('s', e.target.value)} type="number" step="0.001" min="0" max="59.999" aria-label={`${label} — seconds`} placeholder="Sec"
          className="flex-1 min-w-[50px] px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
      </div>
    </div>
  )
}

function DMSState() {
  return { d: '', m: '', s: '' }
}

function DMSGet(d: ReturnType<typeof DMSState>) {
  return { deg: parseInt(d.d) || 0, min: parseInt(d.m) || 0, sec: parseFloat(d.s) || 0 }
}

function StepsDisplay({ steps, title }: { steps: InverseStep[]; title?: string }) {
  if (!steps || steps.length === 0) return null
  return (
    <div className="space-y-2">
      {title && <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">{title}</h3>}
      <div className="space-y-1">
        {steps.map((step, i) => (
          <div key={step.value} className="grid grid-cols-[1fr_auto_1fr] md:grid-cols-[1fr_auto_1fr_auto] gap-x-1 md:gap-x-2 text-xs font-mono py-1 border-b border-[var(--border-color)]/20">
            <span className="text-[var(--text-secondary)]">{step.description}</span>
            <span className="text-[var(--text-muted)]">=</span>
            <span className="text-[var(--text-primary)] text-right">{step.value}</span>
            <span className="hidden md:block text-[var(--text-muted)] text-right min-w-[120px] text-right">{step.formula}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function CoordField({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  const id = useId()
  return (
    <div>
      <label htmlFor={id} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
      <input id={id} value={value} onChange={e => onChange(e.target.value)} type="number" step="0.001"
        className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
    </div>
  )
}

function ResultCard({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
  return (
    <div className={`px-3 py-2 rounded border ${accent ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)] bg-[var(--bg-tertiary)]/50'}`}>
      <p className="text-xs text-[var(--text-secondary)]">{label}</p>
      <p className={`text-sm font-mono font-semibold ${accent ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>{value}</p>
    </div>
  )
}

export default function COGOCalculator({ compact = false }: Props) {
  const [activeTab, setActiveTab] = useState<Tab>('inverse')
  const [error, setError] = useState('')

  // ── INVERSE ──────────────────────────────────────────────────────────────────
  const [invE1, setInvE1] = useState('')
  const [invN1, setInvN1] = useState('')
  const [invE2, setInvE2] = useState('')
  const [invN2, setInvN2] = useState('')
  const [invL1, setInvL1] = useState('A')
  const [invL2, setInvL2] = useState('B')
  const [invResult, setInvResult] = useState<ReturnType<typeof inverseComputation> | null>(null)

  // ── POLAR ───────────────────────────────────────────────────────────────────
  const [polE1, setPolE1] = useState('')
  const [polN1, setPolN1] = useState('')
  const [polD, setPolD] = useState('')
  const [polBear, setPolBear] = useState(DMSState())
  const [polResult, setPolResult] = useState<ReturnType<typeof polarComputation> | null>(null)

  // ── INTERSECTION ─────────────────────────────────────────────────────────────
  const [intE1, setIntE1] = useState('')
  const [intN1, setIntN1] = useState('')
  const [intE2, setIntE2] = useState('')
  const [intN2, setIntN2] = useState('')
  const [intBear1, setIntBear1] = useState(DMSState())
  const [intBear2, setIntBear2] = useState(DMSState())
  const [intResult, setIntResult] = useState<ReturnType<typeof intersectionComputation> | null>(null)

  // ── RESECTION ────────────────────────────────────────────────────────────────
  const [resEA, setResEA] = useState(''); const [resNA, setResNA] = useState('')
  const [resEB, setResEB] = useState(''); const [resNB, setResNB] = useState('')
  const [resEC, setResEC] = useState(''); const [resNC, setResNC] = useState('')
  const [resAlpha, setResAlpha] = useState(DMSState())
  const [resBeta, setResBeta] = useState(DMSState())
  const [resResult, setResResult] = useState<ReturnType<typeof resectionComputation> | null>(null)

  // ── AREA ────────────────────────────────────────────────────────────────────
  const [areaText, setAreaText] = useState('')
  const [areaResult, setAreaResult] = useState<ReturnType<typeof areaComputation> | null>(null)

  // ── JOIN ────────────────────────────────────────────────────────────────────
  const [joinText, setJoinText] = useState('')
  const [joinResult, setJoinResult] = useState<ReturnType<typeof joinComputation> | null>(null)

  // ── DISTANCE-DISTANCE ──────────────────────────────────────────────────────
  const [ddE1, setDdE1] = useState(''); const [ddN1, setDdN1] = useState('')
  const [ddE2, setDdE2] = useState(''); const [ddN2, setDdN2] = useState('')
  const [ddD1, setDdD1] = useState(''); const [ddD2, setDdD2] = useState('')
  const [ddResult, setDdResult] = useState<DistDistResult | null>(null)
  const [ddSel, setDdSel] = useState(0)

  // ── BEARING-DISTANCE ───────────────────────────────────────────────────────
  const [bdE1, setBdE1] = useState(''); const [bdN1, setBdN1] = useState('')
  const [bdE2, setBdE2] = useState(''); const [bdN2, setBdN2] = useState('')
  const [bdBear, setBdBear] = useState(DMSState())
  const [bdDist, setBdDist] = useState('')
  const [bdResult, setBdResult] = useState<BearingDistResult | null>(null)
  const [bdSel, setBdSel] = useState(0)

  // ── ARC BOUNDARY ──────────────────────────────────────────────────────────
  const [arcSE, setArcSE] = useState(''); const [arcSN, setArcSN] = useState('')
  const [arcEE, setArcEE] = useState(''); const [arcEN, setArcEN] = useState('')
  const [arcR, setArcR] = useState(''); const [arcCW, setArcCW] = useState(true)
  const [arcResult, setArcResult] = useState<ArcResult | null>(null)

  // ── COMPUTE HANDLERS ────────────────────────────────────────────────────────
  const handleInverse = () => {
    setError('')
    if (!invE1 || !invN1 || !invE2 || !invN2) { setError('Enter all coordinates'); return }
    try {
      setInvResult(inverseComputation({
        e1: parseFloat(invE1), n1: parseFloat(invN1),
        e2: parseFloat(invE2), n2: parseFloat(invN2),
        label1: invL1, label2: invL2,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handlePolar = () => {
    setError('')
    if (!polE1 || !polN1 || !polD) { setError('Enter all fields'); return }
    const b = DMSGet(polBear)
    try {
      setPolResult(polarComputation({
        e1: parseFloat(polE1), n1: parseFloat(polN1),
        bearingDeg: b.deg, bearingMin: b.min, bearingSec: b.sec,
        distance: parseFloat(polD),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleIntersection = () => {
    setError('')
    const b1 = DMSGet(intBear1)
    const b2 = DMSGet(intBear2)
    try {
      setIntResult(intersectionComputation({
        e1: parseFloat(intE1), n1: parseFloat(intN1),
        e2: parseFloat(intE2), n2: parseFloat(intN2),
        bearingDeg1: b1.deg, bearingMin1: b1.min, bearingSec1: b1.sec,
        bearingDeg2: b2.deg, bearingMin2: b2.min, bearingSec2: b2.sec,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleResection = () => {
    setError('')
    const a = DMSGet(resAlpha)
    const b = DMSGet(resBeta)
    try {
      setResResult(resectionComputation({
        eA: parseFloat(resEA), nA: parseFloat(resNA),
        eB: parseFloat(resEB), nB: parseFloat(resNB),
        eC: parseFloat(resEC), nC: parseFloat(resNC),
        alphaDeg: a.deg, alphaMin: a.min, alphaSec: a.sec,
        betaDeg: b.deg, betaMin: b.min, betaSec: b.sec,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleArea = () => {
    setError('')
    const lines = areaText.trim().split('\n').filter((l) => l.trim())
    const points = lines.map((line) => {
      const parts = line.split(/[,\t]+/)
      if (parts.length < 3) return null
      return { label: parts[0].trim(), easting: parseFloat(parts[1]), northing: parseFloat(parts[2]) }
    }).filter(Boolean) as Array<{ label: string; easting: number; northing: number }>
    if (points.length < 3) { setError('At least 3 points required'); return }
    try {
      setAreaResult(areaComputation({ points }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleJoin = () => {
    setError('')
    const lines = joinText.trim().split('\n').filter((l) => l.trim())
    const points = lines.map((line) => {
      const parts = line.split(/[,\t]+/)
      if (parts.length < 3) return null
      return { label: parts[0].trim(), easting: parseFloat(parts[1]), northing: parseFloat(parts[2]) }
    }).filter(Boolean) as Array<{ label: string; easting: number; northing: number }>
    if (points.length < 2) { setError('At least 2 points required'); return }
    try {
      setJoinResult(joinComputation({ points }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleDistDist = () => {
    setError('')
    if (!ddE1 || !ddN1 || !ddE2 || !ddN2 || !ddD1 || !ddD2) { setError('Enter all fields'); return }
    try {
      setDdResult(distanceDistanceIntersection({
        e1: parseFloat(ddE1), n1: parseFloat(ddN1),
        e2: parseFloat(ddE2), n2: parseFloat(ddN2),
        distance1: parseFloat(ddD1), distance2: parseFloat(ddD2),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleBearingDist = () => {
    setError('')
    const b = DMSGet(bdBear)
    if (!bdE1 || !bdN1 || !bdE2 || !bdN2 || !bdDist) { setError('Enter all fields'); return }
    try {
      setBdResult(bearingDistanceIntersection({
        e1: parseFloat(bdE1), n1: parseFloat(bdN1),
        e2: parseFloat(bdE2), n2: parseFloat(bdN2),
        bearingDeg: b.deg, bearingMin: b.min, bearingSec: b.sec,
        distance: parseFloat(bdDist),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleArcBoundary = () => {
    setError('')
    if (!arcSE || !arcSN || !arcEE || !arcEN || !arcR) { setError('Enter all fields'); return }
    try {
      setArcResult(arcByRadiusAndChord({
        startPoint: { easting: parseFloat(arcSE), northing: parseFloat(arcSN) },
        endPoint: { easting: parseFloat(arcEE), northing: parseFloat(arcEN) },
        radius: parseFloat(arcR),
        isClockwise: arcCW,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const clearAll = () => {
    setError('')
    setInvResult(null); setPolResult(null); setIntResult(null)
    setResResult(null); setAreaResult(null); setJoinResult(null)
    setDdResult(null); setBdResult(null); setArcResult(null)
  }

  const handleExportPDF = async () => {
    try {
      const { default: jsPDF } = await import('jspdf')
      const { default: autoTable } = await import('jspdf-autotable')
      const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })

      doc.setFontSize(16)
      doc.text('METARDU — COGO Computation Report', 14, 14)
      doc.setFontSize(10)
      doc.text(`Computation Type: ${TABS.find((t) => t.id === activeTab)?.label || activeTab}`, 14, 22)
      doc.setFontSize(8)
      doc.text(`Generated: ${new Date().toLocaleString()} | Survey Act Cap. 299 | RDM 1.1 (2025)`, 14, 28)
      doc.setDrawColor(150)
      doc.line(14, 30, 196, 30)

      if (activeTab === 'inverse' && invResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value', 'Formula']],
          body: [
            ['Point 1', invL1, ''],
            ['Point 2', invL2, ''],
            ['Delta Easting', `${invResult.deltaE.toFixed(4)} m`, ''],
            ['Delta Northing', `${invResult.deltaN.toFixed(4)} m`, ''],
            ['WCB', invResult.wcbDMS, ''],
            ['Distance', `${invResult.distance.toFixed(4)} m`, ''],
            ['Reduced Bearing', invResult.reducedBearing, ''],
            ['Back Bearing', invResult.backBearingDMS, ''],
            ['Quadrant', invResult.quadrant, ''],
            ['Arithmetic Check', invResult.arithmeticCheck.passed ? 'PASS' : 'FAIL', invResult.arithmeticCheck.value.toFixed(6)],
          ],
          styles: { fontSize: 9 },
          columnStyles: { 2: { cellWidth: 60 } },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'polar' && polResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['WCB Used', polResult.wcbDMS],
            ['E2 (m)', polResult.e2.toFixed(4)],
            ['N2 (m)', polResult.n2.toFixed(4)],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'intersection' && intResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Intersection Easting E3 (m)', intResult.e3.toFixed(4)],
            ['Intersection Northing N3 (m)', intResult.n3.toFixed(4)],
            ['Distance from P1 (m)', intResult.distanceFrom1.toFixed(4)],
            ['Distance from P2 (m)', intResult.distanceFrom2.toFixed(4)],
            ['Check Difference (m)', intResult.checkDiff.toFixed(4)],
            ['Within Tolerance', intResult.isWithinTolerance ? 'PASS' : 'FLAG'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'resection' && resResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Station E (m)', resResult.eP.toFixed(4)],
            ['Station N (m)', resResult.nP.toFixed(4)],
            ['Distance to A (m)', resResult.distToA.toFixed(4)],
            ['Distance to B (m)', resResult.distToB.toFixed(4)],
            ['Distance to C (m)', resResult.distToC.toFixed(4)],
            ['Danger Circle', resResult.isDangerCircle ? 'WARNING' : 'No'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'area' && areaResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Area (m\u00B2)', areaResult.areaSqm.toFixed(4)],
            ['Area (ha)', areaResult.areaHa.toFixed(4)],
            ['Perimeter (m)', areaResult.perimeter.toFixed(4)],
            ['Centroid E (m)', areaResult.centroid.easting.toFixed(4)],
            ['Centroid N (m)', areaResult.centroid.northing.toFixed(4)],
            ['Arithmetic Check', areaResult.arithmeticCheck.passed ? 'PASS' : 'FAIL'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'join' && joinResult) {
        autoTable(doc, {
          startY: 34,
          head: [['From', 'To', 'Delta E (m)', 'Delta N (m)', 'Distance (m)', 'WCB', 'Back Bearing']],
          body: joinResult.rows.map((r) => [r.from, r.to, r.deltaE.toFixed(4), r.deltaN.toFixed(4), r.distance.toFixed(4), r.wcbDMS, r.backBearingDMS]),
          styles: { fontSize: 8 },
          headStyles: { fillColor: [34, 197, 94] },
        })
        const finalY = ((doc as unknown as { lastAutoTable?: { finalY: number } }).lastAutoTable?.finalY ?? 34) + 6
        doc.setFontSize(9)
        doc.text(`Total Perimeter: ${joinResult.totalPerimeter.toFixed(4)} m`, 14, finalY)
      } else {
        doc.setFontSize(10)
        doc.text('No computation results to export. Run a calculation first.', 14, 34)
      }

      doc.setFontSize(7)
      doc.setTextColor(120)
      doc.text('Source: Ghilani & Wolf, Elementary Surveying 16th Ed. | N.N. Basak, Surveying and Levelling | Survey Act Cap. 299 | RDM 1.1 (2025)', 14, doc.internal.pageSize.height - 8)
      doc.setTextColor(0)

      const date = new Date().toISOString().slice(0, 10)
      const tabName = TABS.find((t) => t.id === activeTab)?.label.replace(/[^a-zA-Z]/g, '_') || activeTab
      doc.save(`METARDU_COGO_${tabName}_${date}.pdf`)
    } catch (err) {
      logger.error('PDF export error:', { error: err })
      setError('Failed to export PDF. Please try again.')
    }
  }

  const handleExportCSV = () => {
    try {
      let headers: string[] = ['Parameter', 'Value']
      let rows: string[][] = []

      if (activeTab === 'inverse' && invResult) {
        headers = ['Parameter', 'Value', 'Formula']
        rows = [
          ['Point 1', invL1, ''],
          ['Point 2', invL2, ''],
          ['Delta Easting (m)', invResult.deltaE.toFixed(4), ''],
          ['Delta Northing (m)', invResult.deltaN.toFixed(4), ''],
          ['WCB', invResult.wcbDMS, ''],
          ['Distance (m)', invResult.distance.toFixed(4), ''],
          ['Reduced Bearing', invResult.reducedBearing, ''],
          ['Back Bearing', invResult.backBearingDMS, ''],
          ['Quadrant', invResult.quadrant, ''],
          ['Arithmetic Check', invResult.arithmeticCheck.passed ? 'PASS' : 'FAIL', invResult.arithmeticCheck.value.toFixed(6)],
        ]
      } else if (activeTab === 'polar' && polResult) {
        rows = [
          ['WCB Used', polResult.wcbDMS],
          ['E2 (m)', polResult.e2.toFixed(4)],
          ['N2 (m)', polResult.n2.toFixed(4)],
        ]
      } else if (activeTab === 'intersection' && intResult) {
        rows = [
          ['Intersection E3 (m)', intResult.e3.toFixed(4)],
          ['Intersection N3 (m)', intResult.n3.toFixed(4)],
          ['Distance from P1 (m)', intResult.distanceFrom1.toFixed(4)],
          ['Distance from P2 (m)', intResult.distanceFrom2.toFixed(4)],
        ]
      } else if (activeTab === 'resection' && resResult) {
        rows = [
          ['Station E (m)', resResult.eP.toFixed(4)],
          ['Station N (m)', resResult.nP.toFixed(4)],
          ['Distance to A (m)', resResult.distToA.toFixed(4)],
          ['Distance to B (m)', resResult.distToB.toFixed(4)],
          ['Distance to C (m)', resResult.distToC.toFixed(4)],
        ]
      } else if (activeTab === 'area' && areaResult) {
        rows = [
          ['Area (m²)', areaResult.areaSqm.toFixed(4)],
          ['Area (ha)', areaResult.areaHa.toFixed(4)],
          ['Perimeter (m)', areaResult.perimeter.toFixed(4)],
          ['Centroid E (m)', areaResult.centroid.easting.toFixed(4)],
          ['Centroid N (m)', areaResult.centroid.northing.toFixed(4)],
        ]
      } else if (activeTab === 'join' && joinResult) {
        headers = ['From', 'To', 'Delta E (m)', 'Delta N (m)', 'Distance (m)', 'WCB', 'Back Bearing']
        rows = joinResult.rows.map(r => [r.from, r.to, r.deltaE.toFixed(4), r.deltaN.toFixed(4), r.distance.toFixed(4), r.wcbDMS, r.backBearingDMS])
      } else {
        setError('No data to export')
        return
      }

      const csv = toCSV(headers, rows)
      const tabName = TABS.find(t => t.id === activeTab)?.label.replace(/[^a-zA-Z]/g, '_') || activeTab
      downloadCSV(csv, `METARDU_COGO_${tabName}`)
    } catch (err) {
      logger.error('CSV export error:', { error: err })
      setError('Failed to export CSV. Please try again.')
    }
  }

  const TABS: { id: Tab; label: string }[] = [
    { id: 'inverse', label: 'Distance & Bearing' },
    { id: 'polar', label: 'Radiation' },
    { id: 'intersection', label: 'Brg-Brg Intersection' },
    { id: 'distDist', label: 'Dist-Dist Intersection' },
    { id: 'bearingDist', label: 'Brg-Dist Intersection' },
    { id: 'arcBoundary', label: 'Arc Boundary' },
    { id: 'resection', label: 'Resection' },
    { id: 'area', label: 'Area by Coordinates' },
    { id: 'join', label: 'Missing Line' },
  ]

  return (
    <div className={compact ? '' : 'w-full max-w-7xl mx-auto px-3 md:px-4 py-4 md:py-8'}>
      {!compact && (
        <>
          <h1 className="text-3xl font-bold mb-2">COGO Calculator</h1>
          <p className="text-sm text-[var(--text-muted)] mb-6">
            Coordinate Geometry — Inverse, Polar, Intersection, Resection, Area, Join | Survey Act Cap 299 | RDM 1.1 (2025)
          </p>
        </>
      )}

      {/* Tab Bar */}
      <div className="flex items-center gap-1 border-b border-[var(--border-color)] mb-4 overflow-x-auto">
        {TABS.map((tab) => (
          <button key={tab.id} onClick={() => { setActiveTab(tab.id); clearAll() }}
            className={`px-4 py-2 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
              activeTab === tab.id
                ? 'border-[var(--accent)] text-[var(--accent)]'
                : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
            }`}>
            {tab.label}
          </button>
        ))}
        <div className="flex-1" />
        <button onClick={handleExportPDF}
          className="px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:text-[var(--accent)] border border-[var(--border-color)] hover:border-[var(--accent)] rounded inline-flex items-center gap-1">
          <Download className="w-3 h-3" /> PDF
        </button>
        <button onClick={handleExportCSV}
          className="px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:text-[var(--accent)] border border-[var(--border-color)] hover:border-[var(--accent)] rounded inline-flex items-center gap-1">
          <Download className="w-3 h-3" /> CSV
        </button>
        <button onClick={clearAll}
          className="px-3 py-1.5 text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)]">
          Clear
        </button>
      </div>

      {error && <div className="mb-4 p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{error}</div>}

      <div className="grid md:grid-cols-2 gap-6">
        {/* ── INPUT PANEL ── */}
        <div className="space-y-4">
          {/* INVERSE */}
          {activeTab === 'inverse' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Inverse Computation — Given two points, compute bearing and distance</h2>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Point 1 Easting (m)" value={invE1} onChange={setInvE1} />
                <CoordField label="Point 1 Northing (m)" value={invN1} onChange={setInvN1} />
                <div>
                  <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="point-1-label">Point 1 Label</label>
                  <input id="point-1-label" value={invL1} onChange={e => setInvL1(e.target.value)}
                    className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Point 2 Easting (m)" value={invE2} onChange={setInvE2} />
                <CoordField label="Point 2 Northing (m)" value={invN2} onChange={setInvN2} />
                <div>
                  <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="point-2-label">Point 2 Label</label>
                  <input id="point-2-label" value={invL2} onChange={e => setInvL2(e.target.value)}
                    className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                </div>
              </div>
              <button onClick={handleInverse} className="btn btn-primary w-full">Compute Inverse →</button>
            </div>
          )}

          {/* RADIATION */}
          {activeTab === 'polar' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Radiation — Station + bearing/dist → coordinates</h2>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Known Easting (m)" value={polE1} onChange={setPolE1} />
                <CoordField label="Known Northing (m)" value={polN1} onChange={setPolN1} />
              </div>
              <DMSField label="WCB Bearing" deg={polBear.d} min={polBear.m} sec={polBear.s}
                onChange={(f, v) => setPolBear(p => ({ ...p, [f]: v }))} />
              <CoordField label="Distance (m)" value={polD} onChange={setPolD} />
              <button onClick={handlePolar} className="btn btn-primary w-full">Compute Polar →</button>
            </div>
          )}

          {/* INTERSECTION */}
          {activeTab === 'intersection' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Bearing Intersection — Compute intersection of two bearings</h2>
              <p className="text-xs text-[var(--text-muted)]">Known Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Easting (m)" value={intE1} onChange={setIntE1} />
                <CoordField label="Northing (m)" value={intN1} onChange={setIntN1} />
              </div>
              <DMSField label="Bearing from Point 1 (DMS)" deg={intBear1.d} min={intBear1.m} sec={intBear1.s}
                onChange={(f, v) => setIntBear1(p => ({ ...p, [f]: v }))} />
              <p className="text-xs text-[var(--text-muted)]">Known Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Easting (m)" value={intE2} onChange={setIntE2} />
                <CoordField label="Northing (m)" value={intN2} onChange={setIntN2} />
              </div>
              <DMSField label="Bearing from Point 2 (DMS)" deg={intBear2.d} min={intBear2.m} sec={intBear2.s}
                onChange={(f, v) => setIntBear2(p => ({ ...p, [f]: v }))} />
              <button onClick={handleIntersection} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* RESECTION */}
          {activeTab === 'resection' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Three-Point Resection (Tienstra/Pothenot)</h2>
              <div className="grid grid-cols-3 gap-2">
                <div />
                <div className="text-xs text-center font-semibold text-[var(--text-secondary)]">Easting</div>
                <div className="text-xs text-center font-semibold text-[var(--text-secondary)]">Northing</div>
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point A</div>
                <input aria-label="Result easting A" value={resEA} onChange={e => setResEA(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing A" value={resNA} onChange={e => setResNA(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point B</div>
                <input aria-label="Result easting B" value={resEB} onChange={e => setResEB(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing B" value={resNB} onChange={e => setResNB(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point C</div>
                <input aria-label="Result easting C" value={resEC} onChange={e => setResEC(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing C" value={resNC} onChange={e => setResNC(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
              </div>
              <DMSField label="Angle α = ∠APB (DMS)" deg={resAlpha.d} min={resAlpha.m} sec={resAlpha.s}
                onChange={(f, v) => setResAlpha(p => ({ ...p, [f]: v }))} />
              <DMSField label="Angle β = ∠BPC (DMS)" deg={resBeta.d} min={resBeta.m} sec={resBeta.s}
                onChange={(f, v) => setResBeta(p => ({ ...p, [f]: v }))} />
              <button onClick={handleResection} className="btn btn-primary w-full">Compute Resection →</button>
            </div>
          )}

          {/* AREA */}
          {activeTab === 'area' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Area by Coordinates (Shoelace)</h2>
              <p className="text-xs text-[var(--text-muted)]">Enter one point per line: Label, Easting, Northing</p>
              <textarea value={areaText} onChange={e => setAreaText(e.target.value)}
                className="w-full h-48 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm font-mono"
                placeholder='Label, Easting, Northing (one point per line)' />
              <button onClick={handleArea} className="btn btn-primary w-full">Compute Area →</button>
            </div>
          )}

          {/* DISTANCE-DISTANCE */}
          {activeTab === 'distDist' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Distance-Distance Intersection — Circle-circle</h2>
              <p className="text-xs text-[var(--text-muted)]">Known Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₁ (m)" value={ddE1} onChange={setDdE1} />
                <CoordField label="N₁ (m)" value={ddN1} onChange={setDdN1} />
              </div>
              <CoordField label="Distance from P1 (m)" value={ddD1} onChange={setDdD1} />
              <p className="text-xs text-[var(--text-muted)]">Known Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₂ (m)" value={ddE2} onChange={setDdE2} />
                <CoordField label="N₂ (m)" value={ddN2} onChange={setDdN2} />
              </div>
              <CoordField label="Distance from P2 (m)" value={ddD2} onChange={setDdD2} />
              <button onClick={handleDistDist} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* BEARING-DISTANCE */}
          {activeTab === 'bearingDist' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Bearing-Distance Intersection — Ray meets circle</h2>
              <p className="text-xs text-[var(--text-muted)]">Bearing from Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₁ (m)" value={bdE1} onChange={setBdE1} />
                <CoordField label="N₁ (m)" value={bdN1} onChange={setBdN1} />
              </div>
              <DMSField label="WCB Bearing from P1" deg={bdBear.d} min={bdBear.m} sec={bdBear.s}
                onChange={(f, v) => setBdBear(p => ({ ...p, [f]: v }))} />
              <p className="text-xs text-[var(--text-muted)]">Distance from Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₂ (m)" value={bdE2} onChange={setBdE2} />
                <CoordField label="N₂ (m)" value={bdN2} onChange={setBdN2} />
              </div>
              <CoordField label="Distance from P2 (m)" value={bdDist} onChange={setBdDist} />
              <button onClick={handleBearingDist} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* ARC BOUNDARY */}
          {activeTab === 'arcBoundary' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Arc Boundary — Radius + Chord endpoints</h2>
              <p className="text-xs text-[var(--text-muted)]">Start Point</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E start (m)" value={arcSE} onChange={setArcSE} />
                <CoordField label="N start (m)" value={arcSN} onChange={setArcSN} />
              </div>
              <p className="text-xs text-[var(--text-muted)]">End Point</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E end (m)" value={arcEE} onChange={setArcEE} />
                <CoordField label="N end (m)" value={arcEN} onChange={setArcEN} />
              </div>
              <CoordField label="Radius (m)" value={arcR} onChange={setArcR} />
              <label className="flex items-center gap-2 text-sm text-[var(--text-secondary)]">
                <input type="checkbox" checked={arcCW} onChange={e => setArcCW(e.target.checked)} /> Clockwise arc
              </label>
              <button onClick={handleArcBoundary} className="btn btn-primary w-full">Compute Arc →</button>
            </div>
          )}

          {/* JOIN */}
          {activeTab === 'join' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Join Computation — Traverse summary table</h2>
              <p className="text-xs text-[var(--text-muted)]">Enter points in order: Label, Easting, Northing</p>
              <textarea value={joinText} onChange={e => setJoinText(e.target.value)}
                className="w-full h-48 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm font-mono"
                placeholder='Label, Easting, Northing (one point per line)' />
              <button onClick={handleJoin} className="btn btn-primary w-full">Compute Joins →</button>
            </div>
          )}
        </div>

        {/* ── RESULTS PANEL ── */}
        <div className="space-y-4">
          {/* INVERSE RESULTS */}
          {activeTab === 'inverse' && invResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Inverse</h2>
              <StepsDisplay steps={invResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="ΔE" value={`${invResult.deltaE.toFixed(4)} m`} />
                  <ResultCard label="ΔN" value={`${invResult.deltaN.toFixed(4)} m`} />
                  <ResultCard label="WCB" value={invResult.wcbDMS} accent />
                  <ResultCard label="Distance" value={`${invResult.distance.toFixed(4)} m`} accent />
                  <ResultCard label="Reduced Bearing θ" value={invResult.reducedBearing} />
                  <ResultCard label="Back Bearing" value={invResult.backBearingDMS} />
                  <ResultCard label="Quadrant" value={invResult.quadrant} />
                  <ResultCard label="Arithmetic Check"
                    value={`${invResult.arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (${invResult.arithmeticCheck.value.toFixed(6)})`}
                    accent={invResult.arithmeticCheck.passed} />
                </div>
              </div>
            </div>
          )}

          {/* POLAR RESULTS */}
          {activeTab === 'polar' && polResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Polar</h2>
              <StepsDisplay steps={polResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="WCB Used" value={polResult.wcbDMS} accent />
                  <ResultCard label="E₂ (m)" value={polResult.e2.toFixed(4)} accent />
                  <ResultCard label="N₂ (m)" value={polResult.n2.toFixed(4)} accent />
                </div>
              </div>
            </div>
          )}

          {/* INTERSECTION RESULTS */}
          {activeTab === 'intersection' && intResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Bearing Intersection</h2>
              <StepsDisplay steps={intResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E₃ (m)" value={intResult.e3.toFixed(4)} accent />
                  <ResultCard label="N₃ (m)" value={intResult.n3.toFixed(4)} accent />
                  <ResultCard label="Dist from P1" value={`${intResult.distanceFrom1.toFixed(4)} m`} />
                  <ResultCard label="Dist from P2" value={`${intResult.distanceFrom2.toFixed(4)} m`} />
                  <ResultCard label="Check Difference"
                    value={`${intResult.checkDiff.toFixed(4)} m  ${intResult.isWithinTolerance ? ' PASS' : '[x] FLAG'}`}
                    accent={intResult.isWithinTolerance} />
                </div>
              </div>
            </div>
          )}

          {/* RESECTION RESULTS */}
          {activeTab === 'resection' && resResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Tienstra Resection</h2>
              {resResult.isDangerCircle && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> DANGER CIRCLE WARNING — K₁+K₂+K₃ ≈ 0. Point P is approximately on the circumcircle of triangle ABC. Results may be unreliable. Consider changing observation setup.
                </div>
              )}
              <StepsDisplay steps={resResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="Eₚ (m)" value={resResult.eP.toFixed(4)} accent />
                  <ResultCard label="Nₚ (m)" value={resResult.nP.toFixed(4)} accent />
                  <ResultCard label="Dist to A" value={`${resResult.distToA.toFixed(4)} m`} />
                  <ResultCard label="Dist to B" value={`${resResult.distToB.toFixed(4)} m`} />
                  <ResultCard label="Dist to C" value={`${resResult.distToC.toFixed(4)} m`} />
                </div>
              </div>
            </div>
          )}

          {/* AREA RESULTS */}
          {activeTab === 'area' && areaResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Area by Coordinates</h2>
              {!areaResult.arithmeticCheck.passed && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  Arithmetic check failed. Difference: {areaResult.arithmeticCheck.diff.toFixed(4)} m². Recheck coordinate entries.
                </div>
              )}
              <div className="overflow-x-auto">
                <table className="w-full text-xs font-mono">
                  <thead>
                    <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">From</th>
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">To</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">E×Nₙ₊₁</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">N×Eₙ₊₁</th>
                    </tr>
                  </thead>
                  <tbody>
                    {areaResult.diagonalRows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/20">
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.from}</td>
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.to}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.posProduct.toFixed(2)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.negProduct.toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="font-semibold">
                      <td colSpan={2} className="px-2 py-1 text-[var(--text-primary)]">Σ</td>
                      <td className="px-2 py-1 text-right text-[var(--text-primary)]">{areaResult.positiveSum.toFixed(2)}</td>
                      <td className="px-2 py-1 text-right text-[var(--text-primary)]">{areaResult.negativeSum.toFixed(2)}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <ResultCard label="Area (m²)" value={areaResult.areaSqm.toFixed(4)} accent />
                <ResultCard label="Area (ha)" value={areaResult.areaHa.toFixed(4)} accent />
                <ResultCard label="Perimeter (m)" value={areaResult.perimeter.toFixed(4)} />
                <ResultCard label="Arithmetic Check"
                  value={`${areaResult.arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (${areaResult.arithmeticCheck.diff.toFixed(6)} m²)`}
                  accent={areaResult.arithmeticCheck.passed} />
                <ResultCard label="Centroid E" value={areaResult.centroid.easting.toFixed(4)} />
                <ResultCard label="Centroid N" value={areaResult.centroid.northing.toFixed(4)} />
              </div>
            </div>
          )}

          {/* JOIN RESULTS */}
          {activeTab === 'join' && joinResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Join Table</h2>
              <div className="overflow-x-auto">
                <table className="min-w-[600px] w-full text-xs font-mono">
                  <thead>
                    <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">From</th>
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">To</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">ΔE</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">ΔN</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">Dist (m)</th>
                      <th className="px-2 py-1.5 text-center text-[var(--text-secondary)]">WCB</th>
                      <th className="px-2 py-1.5 text-center text-[var(--text-secondary)]">Back Brg</th>
                    </tr>
                  </thead>
                  <tbody>
                    {joinResult.rows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/20">
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.from}</td>
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.to}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.deltaE >= 0 ? '+' : ''}{row.deltaE.toFixed(4)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.deltaN >= 0 ? '+' : ''}{row.deltaN.toFixed(4)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-primary)]">{row.distance.toFixed(4)}</td>
                        <td className="px-2 py-1 text-center text-[var(--accent)]">{row.wcbDMS}</td>
                        <td className="px-2 py-1 text-center text-[var(--text-secondary)]">{row.backBearingDMS}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="font-semibold border-t border-[var(--border-color)]">
                      <td colSpan={4} className="px-2 py-1 text-[var(--text-primary)]">Total Perimeter</td>
                      <td className="px-2 py-1 text-right text-[var(--accent)]">{joinResult.totalPerimeter.toFixed(4)}</td>
                      <td colSpan={2}></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          )}

          {/* DIST-DIST RESULTS */}
          {activeTab === 'distDist' && ddResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Distance-Distance Intersection</h2>
              {ddResult.error && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{ddResult.error}</div>}
              <StepsDisplay steps={ddResult.steps} />
              {ddResult.hasSolution && ddResult.solutions.length > 1 && (
                <div className="flex gap-2">
                  <button onClick={() => setDdSel(0)} className={`px-3 py-1.5 rounded text-sm ${ddSel === 0 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 1</button>
                  <button onClick={() => setDdSel(1)} className={`px-3 py-1.5 rounded text-sm ${ddSel === 1 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 2</button>
                </div>
              )}
              {ddResult.hasSolution && (
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E (m)" value={ddResult.solutions[ddSel]?.easting.toFixed(4) ?? '-'} accent />
                  <ResultCard label="N (m)" value={ddResult.solutions[ddSel]?.northing.toFixed(4) ?? '-'} accent />
                </div>
              )}
            </div>
          )}

          {/* BEARING-DIST RESULTS */}
          {activeTab === 'bearingDist' && bdResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Bearing-Distance Intersection</h2>
              {bdResult.error && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{bdResult.error}</div>}
              <StepsDisplay steps={bdResult.steps} />
              {bdResult.hasSolution && bdResult.solutions.length > 1 && (
                <div className="flex gap-2">
                  <button onClick={() => setBdSel(0)} className={`px-3 py-1.5 rounded text-sm ${bdSel === 0 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 1</button>
                  <button onClick={() => setBdSel(1)} className={`px-3 py-1.5 rounded text-sm ${bdSel === 1 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 2</button>
                </div>
              )}
              {bdResult.hasSolution && (
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E (m)" value={bdResult.solutions[bdSel]?.easting.toFixed(4) ?? '-'} accent />
                  <ResultCard label="N (m)" value={bdResult.solutions[bdSel]?.northing.toFixed(4) ?? '-'} accent />
                </div>
              )}
            </div>
          )}

          {/* ARC BOUNDARY RESULTS */}
          {activeTab === 'arcBoundary' && arcResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Arc Boundary</h2>
              <StepsDisplay steps={arcResult.steps} />
              <div className="grid grid-cols-2 gap-2">
                <ResultCard label="Center E (m)" value={arcResult.center.easting.toFixed(4)} />
                <ResultCard label="Center N (m)" value={arcResult.center.northing.toFixed(4)} />
                <ResultCard label="Arc Length" value={`${arcResult.arcLength.toFixed(4)} m`} accent />
                <ResultCard label="Chord Length" value={`${arcResult.chordLength.toFixed(4)} m`} />
                <ResultCard label="Subtended Angle" value={`${arcResult.subtendedAngle.toFixed(4)}°`} accent />
                <ResultCard label="Segment Area" value={`${arcResult.segmentArea.toFixed(4)} m²`} />
                <ResultCard label="Chord Bearing" value={arcResult.chordBearingDMS} />
                <ResultCard label="Arc Points" value={`${arcResult.points.length} pts`} />
              </div>
            </div>
          )}

          {!invResult && !polResult && !intResult && !resResult && !areaResult && !joinResult && !ddResult && !bdResult && !arcResult && (
            <div className="flex items-center justify-center h-64 border border-dashed border-[var(--border-color)] rounded">
              <p className="text-sm text-[var(--text-muted)]">Enter values and click Compute</p>
            </div>
          )}
        </div>
      </div>

      <div className="mt-4 text-center text-xs text-[var(--text-muted)]">
        Source: Ghilani &amp; Wolf, Elementary Surveying 16th Ed., Sections 10.3–10.7, 12.5 | N.N. Basak, Surveying and Levelling
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import type { SurveyPlanData } from '@/lib/reports/surveyPlan/types'

interface ComplianceItem {
  key: string
  label: string
  pass: boolean
}

interface ComplianceChecklistModalProps {
  isOpen: boolean
  onClose: () => void
  data: SurveyPlanData
  onExport: () => void
}

export default function ComplianceChecklistModal({
  isOpen,
  onClose,
  data,
  onExport,
}: ComplianceChecklistModalProps) {
  if (!isOpen) return null

  const p = data.project
  const parcel = data.parcel
  const pts = parcel?.boundaryPoints || []

  const items: ComplianceItem[] = [
    {
      key: 'beacons',
      label: 'Boundary beacons are present (minimum 3 corners)',
      pass: pts.length >= 3,
    },
    {
      key: 'coordinates',
      label: 'All boundary coordinates tabulated in schedule',
      pass: pts.length >= 3,
    },
    {
      key: 'area',
      label: 'Parcel area is inscribed on the plan',
      pass: (p.area_sqm || 0) > 0,
    },
    {
      key: 'north',
      label: 'North point / arrow is shown',
      pass: true,
    },
    {
      key: 'scale',
      label: 'Scale bar and numeric scale are shown',
      pass: true,
    },
    {
      key: 'boundary',
      label: 'Boundary lengths and bearings are labeled',
      pass: (p.bearingSchedule?.length || 0) >= 3,
    },
    {
      key: 'adjacent',
      label: 'Adjacent lot references are noted',
      pass: !!(p.reference || p.plan_title),
    },
    {
      key: 'surveyor',
      label: 'Surveyor name and LSK licence number are shown',
      pass: !!(p.surveyor_name && p.surveyor_licence),
    },
    {
      key: 'authentication',
      label: 'Authentication space is reserved on the plan',
      pass: true,
    },
    {
      key: 'drawing_no',
      label: 'Drawing number / plan reference is assigned',
      pass: !!p.drawing_no,
    },
    {
      key: 'datum',
      label: 'Datum set to ARC1960 (required for KeNHA submissions per RDM 1.1 §5.2)',
      pass: p.datum === 'ARC1960' || !p.datum,
    },
  ]

  const passed = items.filter((i) => i.pass).length
  const total = items.length
  const allPassed = passed === total

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={onClose} />
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-6 w-full max-w-lg max-h-[90vh] overflow-y-auto shadow-2xl">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h2 className="text-lg font-bold text-[var(--text-primary)]">
              METARDU Compliance Checklist
            </h2>
            <p className="text-xs text-[var(--text-muted)] mt-0.5">
              RDM 1.1 — Boundary Identification Plan
            </p>
          </div>
          <button
            onClick={onClose}
            className="text-[var(--text-muted)] hover:text-[var(--text-primary)] text-xl leading-none"
          >
            ×
          </button>
        </div>

        {/* Progress bar */}
        <div className="mb-4">
          <div className="flex items-center justify-between text-xs mb-1.5">
            <span className="text-[var(--text-secondary)]">
              {passed}/{total} items compliant
            </span>
            <span className={`font-semibold ${allPassed ? 'text-green-400' : 'text-amber-400'}`}>
              {allPassed ? 'READY TO EXPORT' : 'ACTION REQUIRED'}
            </span>
          </div>
          <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className={`h-full transition-all duration-300 ${allPassed ? 'bg-green-500' : 'bg-amber-500'}`}
              style={{ width: `${(passed / total) * 100}%` }}
            />
          </div>
        </div>

        {/* Checklist items */}
        <div className="space-y-2 mb-6">
          {items.map((item) => (
            <div
              key={item.key}
              className={`flex items-start gap-3 px-3 py-2.5 rounded-lg border transition-colors ${
                item.pass
                  ? 'border-green-800/40 bg-green-900/10'
                  : 'border-amber-800/40 bg-amber-900/10'
              }`}
            >
              <div className={`mt-0.5 w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0 ${
                item.pass
                  ? 'bg-green-900/50 border border-green-600'
                  : 'bg-amber-900/50 border border-amber-600'
              }`}>
                {item.pass ? (
                  <svg className="w-3 h-3 text-green-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
                  </svg>
                ) : (
                  <svg className="w-3 h-3 text-amber-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3m0 3h.01M12 3a9 9 0 100 18A9 9 0 0012 3z" />
                  </svg>
                )}
              </div>
              <span className={`text-sm flex-1 ${
                item.pass ? 'text-green-300' : 'text-amber-300'
              }`}>
                {item.label}
              </span>
            </div>
          ))}
        </div>

        {/* Warning for non-compliant items */}
        {!allPassed && (
          <div className="mb-4 p-3 bg-amber-900/20 border border-amber-700/30 rounded-lg">
            <p className="text-xs text-amber-300">
              <strong>Note:</strong> The plan can still be exported, but may not meet KeNHA submission requirements. Address the flagged items above before formal submission.
            </p>
          </div>
        )}

        {/* Actions */}
        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2.5 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded-lg text-sm font-medium transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={() => {
              onExport()
              onClose()
            }}
            disabled={false}
            className="flex-1 px-4 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg text-sm transition-colors disabled:opacity-50"
          >
            {allPassed ? 'Export Plan' : 'Export Anyway'}
          </button>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useMemo } from 'react';
import { BarChart3, AlertTriangle, Save, CheckCircle } from 'lucide-react';
import { logger } from '@/lib/logger'

interface EpochPoint {
  name: string;
  easting: number;
  northing: number;
  elevation: number;
}

interface EpochData {
  epochName: string;
  date: string;
  points: EpochPoint[];
}

interface Displacement {
  name: string;
  dE: number;
  dN: number;
  dZ: number;
  horizontal: number;
  total3D: number;
  bearing: number;
  exceedsThreshold: boolean;
}

function computeDisplacements(epoch1: EpochPoint[], epoch2: EpochPoint[]): Displacement[] {
  const map2 = new Map(epoch2.map(p => [p.name, p]));
  return epoch1.map(p1 => {
    const p2 = map2.get(p1.name);
    if (!p2) return null;
    const dE = p2.easting - p1.easting;
    const dN = p2.northing - p1.northing;
    const dZ = p2.elevation - p1.elevation;
    const horizontal = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    const bearing = (Math.atan2(dE, dN) * 180) / Math.PI;
    const bearingNorm = bearing < 0 ? bearing + 360 : bearing;
    return { name: p1.name, dE, dN, dZ, horizontal, total3D, bearing: bearingNorm, exceedsThreshold: false };
  }).filter(Boolean) as Displacement[];
}

const DEMO_EPOCH1: EpochPoint[] = [
  { name: 'P1', easting: 500000.000, northing: 9980000.000, elevation: 1520.000 },
  { name: 'P2', easting: 500010.000, northing: 9980010.000, elevation: 1518.500 },
  { name: 'P3', easting: 500025.000, northing: 9979995.000, elevation: 1522.800 },
  { name: 'P4', easting: 500015.000, northing: 9979985.000, elevation: 1515.900 },
  { name: 'P5', easting: 500035.000, northing: 9980005.000, elevation: 1519.550 },
];

const DEMO_EPOCH2: EpochPoint[] = [
  { name: 'P1', easting: 500000.005, northing: 9980000.003, elevation: 1520.008 },
  { name: 'P2', easting: 500010.012, northing: 9980009.995, elevation: 1518.502 },
  { name: 'P3', easting: 500024.995, northing: 9979995.010, elevation: 1522.805 },
  { name: 'P4', easting: 500015.008, northing: 9979985.002, elevation: 1515.895 },
  { name: 'P5', easting: 500035.003, northing: 9980005.006, elevation: 1519.558 },
];

export default function MonitoringComputePanel({ projectId }: { projectId: string }) {
  const [epochs, setEpochs] = useState<EpochData[]>([
    { epochName: 'Epoch 1', date: '2025-01-15', points: DEMO_EPOCH1 },
    { epochName: 'Epoch 2', date: '2025-06-15', points: DEMO_EPOCH2 },
  ]);
  const [compareIndex1, setCompareIndex1] = useState(0);
  const [compareIndex2, setCompareIndex2] = useState(1);
  const [threshold, setThreshold] = useState(0.010);
  const [saved, setSaved] = useState(false);

  const displacements = useMemo(() => {
    if (compareIndex1 === compareIndex2 || !epochs[compareIndex1] || !epochs[compareIndex2]) return [];
    const ds = computeDisplacements(epochs[compareIndex1].points, epochs[compareIndex2].points);
    return ds.map(d => ({ ...d, exceedsThreshold: d.total3D > threshold }));
  }, [epochs, compareIndex1, compareIndex2, threshold]);

  const alertCount = displacements.filter(d => d.exceedsThreshold).length;

  const maxDisp = displacements.length > 0 ? Math.max(...displacements.map(d => d.total3D)) : 0;
  const avgDisp = displacements.length > 0 ? displacements.reduce((s, d) => s + d.total3D, 0) / displacements.length : 0;
  const rmsH = Math.sqrt(displacements.reduce((s, d) => s + d.horizontal ** 2, 0) / (displacements.length || 1));
  const rmsV = Math.sqrt(displacements.reduce((s, d) => s + d.dZ ** 2, 0) / (displacements.length || 1));

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'monitoring', results: { displacements, rmsH, rmsV, maxDisp, avgDisp, alertCount } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { logger.error(e instanceof Error ? e.message : String(e)); }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-sm font-semibold"><BarChart3 className="w-4 h-4 inline mr-1" />Multi-Epoch Displacement Monitoring</h3>

      {/* Controls */}
      <div className="flex gap-4 items-end flex-wrap">
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="base-epoch">Base Epoch</label>
          <select id="base-epoch" value={compareIndex1} onChange={e => setCompareIndex1(Number(e.target.value))} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs">
            {epochs.map((ep, i) => <option key={`${ep}-${i}`} value={i}>{ep.epochName} ({ep.date})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="latest-epoch">Latest Epoch</label>
          <select id="latest-epoch" value={compareIndex2} onChange={e => setCompareIndex2(Number(e.target.value))} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs">
            {epochs.map((ep, i) => <option key={`${ep}-${i}`} value={i}>{ep.epochName} ({ep.date})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="alert-threshold-m">Alert Threshold (m)</label>
          <input aria-label="Alert Threshold (m)" type="number" step="0.001" value={threshold} onChange={e => setThreshold(Number(e.target.value))} className="w-24 bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs" />
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Points</div>
          <div className="text-sm font-bold text-white">{displacements.length}</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Max 3D</div>
          <div className="text-sm font-bold text-red-400">{maxDisp.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Avg 3D</div>
          <div className="text-sm font-bold text-amber-400">{avgDisp.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">RMS H</div>
          <div className="text-sm font-bold text-blue-400">{rmsH.toFixed(4)} m</div>
        </div>
        <div className={`p-2 rounded border text-center ${alertCount > 0 ? 'bg-red-500/10 border-red-500/30' : 'bg-green-500/10 border-green-500/30'}`}>
          <div className="text-xs text-zinc-500">Alerts</div>
          <div className={`text-sm font-bold ${alertCount > 0 ? 'text-red-400' : 'text-green-400'}`}>{alertCount}</div>
        </div>
      </div>

      {/* Displacement Table */}
      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Point</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dE (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dN (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dZ (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Horiz (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">3D (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Bearing</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Status</th>
            </tr>
          </thead>
          <tbody>
            {displacements.map(d => (
              <tr key={d.name} className={`border-b border-zinc-800 ${d.exceedsThreshold ? 'bg-red-500/5' : ''}`}>
                <td className="px-2 py-1 font-mono font-semibold">{d.name}</td>
                <td className="px-2 py-1 font-mono">{d.dE >= 0 ? '+' : ''}{d.dE.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.dN >= 0 ? '+' : ''}{d.dN.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.dZ >= 0 ? '+' : ''}{d.dZ.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.horizontal.toFixed(4)}</td>
                <td className={`px-2 py-1 font-mono font-semibold ${d.exceedsThreshold ? 'text-red-400' : 'text-white'}`}>{d.total3D.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.bearing.toFixed(1)}°</td>
                <td className="px-2 py-1">
                  {d.exceedsThreshold ? (
                    <span className="flex items-center gap-1 text-red-400"><AlertTriangle className="w-3 h-3" />ALERT</span>
                  ) : (
                    <span className="text-green-400">OK</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <button onClick={handleSave} disabled={saved}
        className="inline-flex items-center gap-1 px-3 py-1.5 bg-[var(--accent)] text-black text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}
        {saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState, useRef, Fragment, useId } from 'react'
import { computeCrossSection, computeEarthwork, parseEarthworkCSV, type CrossSectionInput, type CrossSectionComputed, type RoadTemplate, type EarthworkResult, type GroundShot } from '@/lib/computations/earthworksEngine'
import CrossSectionDrawing from './CrossSectionDrawing'
import EarthworkQuantitiesTable from './EarthworkQuantitiesTable'
import MassHaulDiagram from './MassHaulDiagram'
import { printEarthworksBoQ, type EarthworksBoQInput } from '@/lib/print/earthworksBoQ'
import { PrintMetaPanel, type PrintMeta } from '@/components/shared/PrintMetaPanel'

const DEFAULT_TEMPLATE: RoadTemplate = {
  carriagewayWidth: 7.0,
  shoulderWidth: 1.5,
  camber: 2.5,
  cutSlopeH: 1,
  fillSlopeH: 1.5,
}

interface SectionRow {
  id: string
  chainageKm: string
  chainageM: string
  clRL: string
  formRL: string
  leftShots: Array<{ off: string; rl: string }>
  rightShots: Array<{ off: string; rl: string }>
}

const EMPTY_ROW = (): SectionRow => ({
  id: crypto.randomUUID(),
  chainageKm: '0',
  chainageM: '0',
  clRL: '',
  formRL: '',
  leftShots: [{ off: '', rl: '' }, { off: '', rl: '' }],
  rightShots: [{ off: '', rl: '' }, { off: '', rl: '' }],
})

export default function EarthworksCalculator() {
  const uid = useId()
  const [sections, setSections] = useState<SectionRow[]>([EMPTY_ROW()])
  const [template, setTemplate] = useState<RoadTemplate>(DEFAULT_TEMPLATE)
  const [shrinkage, setShrinkage] = useState('0.85')
  const [computedSections, setComputedSections] = useState<CrossSectionComputed[]>([])
  const [earthworkResult, setEarthworkResult] = useState<EarthworkResult | null>(null)
  const [activeSection, setActiveSection] = useState(0)
  const [csvError, setCsvError] = useState('')
  const fileRef = useRef<HTMLInputElement>(null)
  const [printMeta, setPrintMeta] = useState<PrintMeta>({
    projectName: '', clientName: '', surveyorName: '', surveyorEmail: '', clientEmail: '', regNo: '', iskNo: '',
    date: new Date().toISOString().split('T')[0], instrument: '', weather: '', observer: '', submissionNo: '',
  })
  const [roadName, setRoadName] = useState('')

  function chainageToNum(row: SectionRow): number {
    return (parseFloat(row.chainageKm) || 0) * 1000 + (parseFloat(row.chainageM) || 0)
  }

  function toInput(row: SectionRow): CrossSectionInput {
    return {
      chainage: chainageToNum(row),
      centrelineRL: parseFloat(row.clRL) || 0,
      formationRL: parseFloat(row.formRL) || 0,
      leftShots: row.leftShots
        .filter((s) => s.off && s.rl)
        .map((s) => ({ offset: -(parseFloat(s.off) || 0), rl: parseFloat(s.rl) || 0 }))
        .sort((a, b) => a.offset - b.offset),
      rightShots: row.rightShots
        .filter((s) => s.off && s.rl)
        .map((s) => ({ offset: parseFloat(s.off) || 0, rl: parseFloat(s.rl) || 0 }))
        .sort((a, b) => a.offset - b.offset),
    }
  }

  function compute() {
    const inputs = sections.map(toInput).sort((a, b) => a.chainage - b.chainage)
    const computed = inputs.map((s) => computeCrossSection(s, template))
    const ew = computeEarthwork(computed, parseFloat(shrinkage) || 0.85)
    setComputedSections(computed)
    setEarthworkResult(ew)
  }

  function handlePrintBoQ() {
    if (!earthworkResult || computedSections.length === 0) return
    const inp: EarthworksBoQInput = {
      sections: computedSections,
      result: earthworkResult,
      template,
      roadName,
      startChainage: '',
      endChainage: '',
      meta: { ...printMeta, title: 'Earthworks Bill of Quantities' },
    }
    printEarthworksBoQ(inp)
  }

  function addRow() {
    setSections(prev => [...prev, EMPTY_ROW()])
  }

  function removeRow(id: string) {
    setSections(prev => prev.filter((r) => r.id !== id))
  }

  function updateRow(id: string, field: keyof SectionRow, value: unknown) {
    setSections(prev => prev.map((r) => r.id === id ? { ...r, [field]: value } : r))
  }

  function updateShot(id: string, side: 'left' | 'right', idx: number, field: 'off' | 'rl', value: string) {
    setSections(prev => prev.map((r) => {
      if (r.id !== id) return r
      const shots = [...r[(side + 'Shots') as 'leftShots' | 'rightShots']]
      shots[idx] = { ...shots[idx], [field]: value }
      return { ...r, [side + 'Shots']: shots }
    }))
  }

  function handleCSVUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    setCsvError('')
    const reader = new FileReader()
    reader.onload = ev => {
      try {
        const text = ev.target?.result as string
        const parsed = parseEarthworkCSV(text)
        if (parsed.length === 0) { setCsvError('No valid sections found in CSV'); return }
          const rows: SectionRow[] = parsed.map((s) => {
            const km = Math.floor(s.chainage / 1000)
            const m = s.chainage % 1000
            return {
              id: crypto.randomUUID(),
              chainageKm: String(km),
              chainageM: m.toFixed(3),
              clRL: s.centrelineRL.toFixed(3),
              formRL: s.formationRL.toFixed(3),
              leftShots: s.leftShots.map((sh) => ({ off: Math.abs(sh.offset).toFixed(3), rl: sh.rl.toFixed(3) })),
              rightShots: s.rightShots.map((sh) => ({ off: sh.offset.toFixed(3), rl: sh.rl.toFixed(3) })),
            }
          })
        setSections(rows)
      } catch {
        setCsvError('Failed to parse CSV. Check format.')
      }
    }
    reader.readAsText(file)
  }

  function fmtCh(ch: number) {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(3)}` : `${m.toFixed(3)}`
  }

  return (
    <div className="space-y-8">
      {/* Template Settings */}
      <div className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg p-4">
        <h3 className="text-sm font-semibold mb-3">Road Template Settings</h3>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {[
            { label: 'Carriageway Width (m)', key: 'carriagewayWidth' as keyof RoadTemplate },
            { label: 'Shoulder Width (m)', key: 'shoulderWidth' as keyof RoadTemplate },
            { label: 'Camber (%)', key: 'camber' as keyof RoadTemplate },
            { label: 'Cut Slope H:V', key: 'cutSlopeH' as keyof RoadTemplate },
            { label: 'Fill Slope H:V', key: 'fillSlopeH' as keyof RoadTemplate },
          ].map(({ label, key }) => (
            <div key={key}>
              <label htmlFor={`${uid}-tpl-${key}`} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
              <input id={`${uid}-tpl-${key}`}
                type="number"
                step="0.01"
                value={template[key] as number}
                onChange={e => setTemplate(prev => ({ ...prev, [key]: parseFloat(e.target.value) || 0 }))}
                className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
              />
            </div>
          ))}
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="shrinkage-factor">Shrinkage Factor</label>
            <input id="shrinkage-factor" type="number" step="0.01" value={shrinkage} onChange={e => setShrinkage(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
          </div>
        </div>
      </div>

      {/* Data Entry Table */}
      <div className="overflow-x-auto">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold">Cross Section Data</h3>
          <div className="flex gap-2">
            <input ref={fileRef} type="file" accept=".csv" onChange={handleCSVUpload} className="hidden" />
            <button onClick={() => fileRef.current?.click()} className="px-3 py-1.5 text-xs border border-[var(--border-color)] rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)]">
              Import CSV
            </button>
            <button onClick={addRow} className="px-3 py-1.5 text-xs bg-[var(--accent)] text-black rounded hover:opacity-90">
              + Add Section
            </button>
            <button onClick={compute} className="px-4 py-1.5 text-xs bg-[var(--accent)] text-black rounded font-medium hover:opacity-90">
              Compute All
            </button>
            {earthworkResult && (
              <button onClick={handlePrintBoQ} className="px-4 py-1.5 text-xs bg-amber-600 text-black rounded font-medium hover:bg-amber-700">
                 Print BoQ
              </button>
            )}
          </div>
        </div>
        {csvError && <p className="text-xs text-red-400 mb-2">{csvError}</p>}
        <p className="text-xs text-[var(--text-muted)] mb-2">
          Format: Chainage (km), Chainage (m), CL RL, Form RL, then L4_off, L4_rl, L3_off, L3_rl, L2_off, L2_rl, L1_off, L1_rl, R1_off, R1_rl, R2_off, R2_rl, R3_off, R3_rl, R4_off, R4_rl
        </p>
        <table className="w-full text-xs font-mono border-collapse">
          <thead>
            <tr className="bg-[var(--bg-tertiary)]">
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">Ch km</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">Ch m</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">CL RL</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">Form RL</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium" colSpan={8}>Left Shots (outer→CL)</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium" colSpan={8}>Right Shots (CL→outer)</th>
              <th className="px-2 py-2 border border-[var(--border-color)]"></th>
            </tr>
            <tr className="bg-[var(--bg-tertiary)]/50">
              <th className="border border-[var(--border-color)]"></th>
              <th className="border border-[var(--border-color)]"></th>
              <th className="border border-[var(--border-color)]"></th>
              <th className="border border-[var(--border-color)]"></th>
              {['L1 Off', 'L1 RL', 'L2 Off', 'L2 RL', 'L3 Off', 'L3 RL', 'L4 Off', 'L4 RL', 'R1 Off', 'R1 RL', 'R2 Off', 'R2 RL', 'R3 Off', 'R3 RL', 'R4 Off', 'R4 RL'].map((h, i) => (
                <th key={`${h}-${i}`} className="px-2 py-1 border border-[var(--border-color)] text-[var(--text-muted)] font-medium text-[10px]">{h}</th>
              ))}
              <th className="border border-[var(--border-color)]"></th>
            </tr>
          </thead>
          <tbody>
            {sections.map((row) => (
              <tr key={row.id} className="hover:bg-[var(--bg-tertiary)]/30">
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="Ch km" value={row.chainageKm} onChange={e => updateRow(row.id, 'chainageKm', e.target.value)} type="number" min="0" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="Ch m" value={row.chainageM} onChange={e => updateRow(row.id, 'chainageM', e.target.value)} type="number" min="0" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="CL RL" value={row.clRL} onChange={e => updateRow(row.id, 'clRL', e.target.value)} type="number" step="0.001" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="Form RL" value={row.formRL} onChange={e => updateRow(row.id, 'formRL', e.target.value)} type="number" step="0.001" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                {[0, 1, 2, 3].map((i) => (
                  <Fragment key={'ls' + i}>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.leftShots[i]?.off || ''} onChange={e => updateShot(row.id, 'left', i, 'off', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="Left offset (m)" placeholder="Off" /></td>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.leftShots[i]?.rl || ''} onChange={e => updateShot(row.id, 'left', i, 'rl', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="Left RL (m)" placeholder="RL" /></td>
                  </Fragment>
                ))}
                {[0, 1, 2, 3].map((i) => (
                  <Fragment key={'rs' + i}>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.rightShots[i]?.off || ''} onChange={e => updateShot(row.id, 'right', i, 'off', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="Right offset (m)" placeholder="Off" /></td>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.rightShots[i]?.rl || ''} onChange={e => updateShot(row.id, 'right', i, 'rl', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="Right RL (m)" placeholder="RL" /></td>
                  </Fragment>
                ))}
                <td className="px-1 py-1 border border-[var(--border-color)]/50">
                  <button onClick={() => removeRow(row.id)} className="text-red-400 hover:text-red-300 text-xs px-1">[x]</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Results */}
      {computedSections.length > 0 && (
        <>
          {/* Summary */}
          <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
            {[
              ['Total Sections', String(computedSections.length)],
              ['Total Cut (Prismoidal)', `${earthworkResult?.totalCutPrismoidal.toFixed(2) || 0} m³`],
              ['Total Fill (Prismoidal)', `${earthworkResult?.totalFillPrismoidal.toFixed(2) || 0} m³`],
              ['Adjusted Cut (× Shrinkage)', `${earthworkResult?.adjustedCut.toFixed(2) || 0} m³`],
              ['Net Balance', `${((earthworkResult?.adjustedCut || 0) - (earthworkResult?.totalFillPrismoidal || 0)).toFixed(2)} m³`],
            ].map(([label, value]) => (
              <div key={label} className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded p-3">
                <p className="text-xs text-[var(--text-muted)]">{label}</p>
                <p className="text-base font-mono text-[var(--text-primary)]">{value}</p>
              </div>
            ))}
          </div>

          {/* Print Header + Print BoQ */}
          <div className="space-y-3">
            <div className="flex items-center gap-3">
              <div className="flex-1">
                <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="road-name-description">Road Name / Description</label>
                <input id="road-name-description" value={roadName} onChange={e => setRoadName(e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
 placeholder="e.g. Kitengela Access Road — A104" />
              </div>
              <button onClick={handlePrintBoQ}
                className="px-5 py-2 bg-amber-600 text-black rounded-lg font-medium hover:bg-amber-700 text-sm whitespace-nowrap mt-5">
                 Print Earthworks BoQ
              </button>
            </div>
            <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />
          </div>

          {/* Section drawings + quantities */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div>
              <div className="flex gap-2 mb-3 overflow-x-auto pb-1">
                {computedSections.map((s, i) => (
                  <button key={`${s}-${i}`} onClick={() => setActiveSection(i)}
                    className={`px-3 py-1.5 text-xs rounded whitespace-nowrap ${i === activeSection ? 'bg-[var(--accent)] text-black' : 'border border-[var(--border-color)] text-[var(--text-muted)]'}`}>
                    {fmtCh(s.chainage)}
                  </button>
                ))}
              </div>
              {computedSections[activeSection] && (
                <CrossSectionDrawing section={computedSections[activeSection]} template={template} />
              )}
            </div>

            <div>
              <EarthworkQuantitiesTable result={earthworkResult} sections={computedSections} />
            </div>
          </div>

          {/* Mass Haul Diagram */}
          {earthworkResult && earthworkResult.massOrdinates.length > 1 && (
            <MassHaulDiagram result={earthworkResult} />
          )}
        </>
      )}
    </div>
  )
}

'use client';

import { type EarthworkResult } from '@/lib/computations/earthworksEngine'

interface Props {
  result: EarthworkResult
}

export default function MassHaulDiagram({ result }: Props) {
  const { massOrdinates, shrinkageFactor } = result

  if (massOrdinates.length < 2) return null

  const minCh = massOrdinates[0].chainage
  const maxCh = massOrdinates[massOrdinates.length - 1].chainage
  const chRange = maxCh - minCh || 1

  const maxOrd = Math.max(...massOrdinates.map((o) => o.ordinate), 0)
  const minOrd = Math.min(...massOrdinates.map((o) => o.ordinate), 0)
  const ordRange = Math.max(maxOrd - minOrd, 1)

  const svgW = 800
  const svgH = 300
  const padX = 60
  const padY = 30
  const plotW = svgW - padX * 2
  const plotH = svgH - padY * 2

  function toSvgX(ch: number): number {
    return padX + ((ch - minCh) / chRange) * plotW
  }
  function toSvgY(ord: number): number {
    return padY + ((maxOrd - ord) / ordRange) * plotH
  }

  // Build path
  const pathPts = massOrdinates.map((o, i) =>
    `${i === 0 ? 'M' : 'L'} ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)}`
  ).join(' ')

  // Balance line (zero)
  const zeroY = toSvgY(0)

  // Fill surplus (above zero)
  let surplusPath = `M ${toSvgX(minCh).toFixed(1)} ${zeroY.toFixed(1)} `
  for (const o of massOrdinates) {
    if (o.ordinate >= 0) {
      surplusPath += `L ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)} `
    }
  }
  surplusPath += `L ${toSvgX(maxCh).toFixed(1)} ${zeroY.toFixed(1)} Z`

  // Fill deficit (below zero)
  let deficitPath = `M ${toSvgX(minCh).toFixed(1)} ${zeroY.toFixed(1)} `
  for (const o of massOrdinates) {
    if (o.ordinate <= 0) {
      deficitPath += `L ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)} `
    }
  }
  deficitPath += `L ${toSvgX(maxCh).toFixed(1)} ${zeroY.toFixed(1)} Z`

  // X axis ticks
  const numTicks = Math.min(10, massOrdinates.length)
  const tickStep = chRange / numTicks
  const xTicks: number[] = []
  for (let i = 0; i <= numTicks; i++) {
    xTicks.push(minCh + (i / numTicks) * chRange)
  }

  // Y axis ticks
  const ordStep = ordRange / 5
  const yTicks: number[] = []
  for (let i = 0; i <= 5; i++) {
    yTicks.push(minOrd + i * ordStep)
  }

  const fmtCh = (ch: number) => {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(0)}` : `${m.toFixed(0)}`
  }

  const maxIdx = massOrdinates.reduce((maxI, o, i, arr) => o.ordinate > arr[maxI].ordinate ? i : maxI, 0)
  const minIdx = massOrdinates.reduce((minI, o, i, arr) => o.ordinate < arr[minI].ordinate ? i : minI, 0)
  const peakOrd = massOrdinates[maxIdx]
  const troughOrd = massOrdinates[minIdx]

  return (
    <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg overflow-hidden">
      <div className="px-3 py-2 bg-[var(--bg-tertiary)] border-b border-[var(--border-color)]">
        <h3 className="text-sm font-semibold">Mass Haul Diagram</h3>
        <p className="text-xs text-[var(--text-muted)]">
          Adjusted cut (&times; {shrinkageFactor} shrinkage) &minus; fill | Source: Ghilani &amp; Wolf Ch.26, Section 26.6
        </p>
      </div>

      <div className="p-4">
        <svg viewBox={`0 0 ${svgW} ${svgH}`} className="w-full" style={{ background: '#fafafa' }}>
          {/* Y axis */}
          <line x1={padX} y1={padY} x2={padX} y2={svgH - padY} stroke="#333" strokeWidth="1" />
          {/* X axis */}
          <line x1={padX} y1={svgH - padY} x2={svgW - padX} y2={svgH - padY} stroke="#333" strokeWidth="1" />

          {/* Balance line */}
          <line x1={padX} y1={zeroY} x2={svgW - padX} y2={zeroY} stroke="#888" strokeWidth="1" strokeDasharray="5,3" />

          {/* Surplus area */}
          <path d={surplusPath} fill="#ff660018" stroke="none" />
          {/* Deficit area */}
          <path d={deficitPath} fill="#0066ff18" stroke="none" />

          {/* Curve */}
          <path d={pathPts} fill="none" stroke="#333" strokeWidth="2" />

          {/* Peak annotation */}
          <circle cx={toSvgX(peakOrd.chainage)} cy={toSvgY(peakOrd.ordinate)} r="4" fill="#ff6600" />
          <text x={toSvgX(peakOrd.chainage) + 5} y={toSvgY(peakOrd.ordinate) - 5} fontSize="9" fill="#ff6600" fontFamily="monospace">
            Max: {peakOrd.ordinate.toFixed(1)} m&sup3;
          </text>

          {/* Trough annotation */}
          <circle cx={toSvgX(troughOrd.chainage)} cy={toSvgY(troughOrd.ordinate)} r="4" fill="#0066ff" />
          <text x={toSvgX(troughOrd.chainage) + 5} y={toSvgY(troughOrd.ordinate) + 14} fontSize="9" fill="#0066ff" fontFamily="monospace">
            Min: {troughOrd.ordinate.toFixed(1)} m&sup3;
          </text>

          {/* X axis ticks */}
          {xTicks.map((ch, i) => (
            <g key={`${ch}-${i}`}>
              <line x1={toSvgX(ch)} y1={svgH - padY} x2={toSvgX(ch)} y2={svgH - padY + 5} stroke="#333" strokeWidth="0.5" />
              <text x={toSvgX(ch)} y={svgH - padY + 15} fontSize="8" fill="#666" textAnchor="middle" fontFamily="monospace">
                {fmtCh(ch)}
              </text>
            </g>
          ))}

          {/* Y axis ticks */}
          {yTicks.map((ord, i) => (
            <g key={`${ord}-${i}`}>
              <line x1={padX - 5} y1={toSvgY(ord)} x2={padX} y2={toSvgY(ord)} stroke="#333" strokeWidth="0.5" />
              <text x={padX - 8} y={toSvgY(ord) + 3} fontSize="8" fill="#666" textAnchor="end" fontFamily="monospace">
                {ord >= 1000 ? `${(ord / 1000).toFixed(1)}k` : ord.toFixed(0)}
              </text>
            </g>
          ))}

          {/* Axis labels */}
          <text x={svgW / 2} y={svgH - 2} fontSize="9" fill="#333" textAnchor="middle" fontFamily="monospace">
            Chainage
          </text>
          <text x={12} y={svgH / 2} fontSize="9" fill="#333" textAnchor="middle" fontFamily="monospace" transform={`rotate(-90, 12, ${svgH / 2})`}>
            Mass Ordinate (m&sup3;)
          </text>
        </svg>

        <div className="mt-3 grid grid-cols-2 md:grid-cols-4 gap-3 text-xs font-mono">
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Peak Ordinate</p>
            <p className="text-orange-400 text-sm">{peakOrd.ordinate.toFixed(2)} m&sup3;</p>
            <p className="text-[var(--text-muted)] text-[10px]">at {fmtCh(peakOrd.chainage)}</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Trough Ordinate</p>
            <p className="text-blue-400 text-sm">{troughOrd.ordinate.toFixed(2)} m&sup3;</p>
            <p className="text-[var(--text-muted)] text-[10px]">at {fmtCh(troughOrd.chainage)}</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Free Haul Distance</p>
            <p className="text-[var(--text-primary)] text-sm">100 m (RDM 1.3)</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Net Balance</p>
            <p className={`text-sm ${peakOrd.ordinate - Math.abs(troughOrd.ordinate) >= 0 ? 'text-yellow-400' : 'text-blue-400'}`}>
              {(peakOrd.ordinate - Math.abs(troughOrd.ordinate)).toFixed(2)} m&sup3;
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client';

import React, { useState, useMemo, useRef } from 'react'
import type { DesignPoint, AsBuiltPoint, ToleranceBand, AsBuiltSurveyResult } from '@/lib/engineering/asBuiltSurvey'
import { compareDesignVsAsBuilt, parseAsBuiltCSV, TOLERANCE_BANDS } from '@/lib/engineering/asBuiltSurvey'

interface AsBuiltSurveyPanelProps {
  projectId?: string
  roadClass?: string
  surfaceType?: 'paved' | 'gravel' | 'earth'
  designPoints?: DesignPoint[]
  onImport?: (points: AsBuiltPoint[]) => void
}

const SURFACE_TYPES: Array<{ key: 'paved' | 'gravel' | 'earth'; label: string; tolerance: ToleranceBand }> = [
  { key: 'paved', label: 'Paved (Asphalt/Concrete)', tolerance: TOLERANCE_BANDS.paved },
  { key: 'gravel', label: 'Gravel', tolerance: TOLERANCE_BANDS.gravel },
  { key: 'earth', label: 'Earth', tolerance: TOLERANCE_BANDS.earth },
]

export default function AsBuiltSurveyPanel({ roadClass, surfaceType = 'paved', designPoints = [] }: AsBuiltSurveyPanelProps) {
  const [activeSurface, setActiveSurface] = useState<'paved' | 'gravel' | 'earth'>(surfaceType)
  const [csvInput, setCsvInput] = useState('')
  const [asBuiltPoints, setAsBuiltPoints] = useState<AsBuiltPoint[]>([])
  const [result, setResult] = useState<AsBuiltSurveyResult | null>(null)
  const [csvError, setCsvError] = useState<string | null>(null)
  const [nanWarning, setNanWarning] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const tolerance = (SURFACE_TYPES.find(s => s.key === activeSurface) ?? SURFACE_TYPES[0]).tolerance

  const handleImport = () => {
    setCsvError(null)
    const points = parseAsBuiltCSV(csvInput)
    if (points.length === 0) {
      setCsvError('Invalid CSV format. Expected: chainage, level, easting, northing (E/N optional).')
      return
    }
    setAsBuiltPoints(points)
    setNanWarning(false)
    const r = compareDesignVsAsBuilt(designPoints, points, tolerance)
    setResult(r)
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      const text = event.target?.result as string
      setCsvInput(text)
      setCsvError(null)
      const points = parseAsBuiltCSV(text)
      if (points.length === 0) {
        setCsvError('Invalid CSV format. Expected: chainage, level, easting, northing (E/N optional).')
        return
      }
      setAsBuiltPoints(points)
      setNanWarning(false)
      const r = compareDesignVsAsBuilt(designPoints, points, tolerance)
      setResult(r)
    }
    reader.readAsText(file)
    // Reset so same file can be re-uploaded
    e.target.value = ''
  }

  const handleExportCSV = () => {
    if (!result) return
    const header = 'chainage,design_level,as_built_level,deviation,tolerance,status'
    const rows = result.comparisons.map(r =>
      `${r.chainage},${r.designLevel.toFixed(4)},${r.asBuiltLevel.toFixed(4)},${r.deviation.toFixed(1)},${r.tolerance},${r.pass ? 'PASS' : 'FAIL'}`
    )
    const csvContent = [header, ...rows].join('\n')
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `as_built_survey_results_${Date.now()}.csv`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  // Generate synthetic design points for demo
  const demoDesignPoints = useMemo(() => {
    if (designPoints.length > 0) return designPoints
    return Array.from({ length: 51 }, (_, i) => ({
      chainage: i * 20,
      designLevel: 100 + Math.sin(i * 0.15) * 3,
    }))
  }, [designPoints])

  const runComparison = () => {
    if (asBuiltPoints.length < 2) return
    setNanWarning(false)
    const r = compareDesignVsAsBuilt(demoDesignPoints, asBuiltPoints, tolerance)
    // Check for NaN deviations
    const hasNan = r.comparisons.some(c => isNaN(c.deviation))
    if (hasNan) setNanWarning(true)
    setResult(r)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h3 className="text-lg font-semibold text-white">As-Built Survey Analysis</h3>
        <p className="text-sm text-zinc-400 mt-1">Compare design levels against as-built survey data</p>
      </div>

      {/* Surface Type & Tolerance */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h4 className="font-medium text-white mb-3">Surface Type & Tolerances</h4>
        <div className="grid grid-cols-3 gap-3">
          {SURFACE_TYPES.map(st => (
            <button
              key={st.key}
              onClick={() => setActiveSurface(st.key)}
              className={`p-3 rounded-lg border-2 text-left transition-colors ${
                activeSurface === st.key
                  ? 'border-blue-500 bg-blue-900/30'
                  : 'border-zinc-700 hover:border-zinc-600'
              }`}
            >
              <div className="font-medium text-sm text-white">{st.label}</div>
              <div className="text-xs text-zinc-400 mt-1">
                Level: ±{st.tolerance.level}mm | Horiz: ±{st.tolerance.horizontal}mm
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* CSV Import */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h4 className="font-medium text-white mb-3">Import As-Built Data (CSV)</h4>
        <p className="text-xs text-zinc-400 mb-2">Format: chainage, level, easting, northing (one point per line)</p>

        {/* File upload button */}
        <div className="mb-3">
          <input
            ref={fileInputRef}
            type="file"
            accept=".csv,.txt"
            onChange={handleFileUpload}
            className="hidden"
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="inline-flex items-center gap-2 px-4 py-2 bg-zinc-800 border border-zinc-600 text-zinc-300 rounded-lg text-sm font-medium hover:bg-zinc-700 hover:text-white transition-colors"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
            </svg>
            Upload CSV File
          </button>
        </div>

        {/* Textarea fallback */}
        <textarea
          className="w-full h-32 bg-zinc-800 border border-zinc-600 rounded-lg p-3 font-mono text-sm text-zinc-200 placeholder-zinc-500 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          placeholder={`0, 100.025, 123456.789, 9876543.210\n20, 100.032, 123466.521, 9876550.102\n40, 99.988, 123476.213, 9876556.834\n...`}
          value={csvInput}
          onChange={e => setCsvInput(e.target.value)}
        />

        {/* CSV error message */}
        {csvError && (
          <div className="mt-2 px-3 py-2 bg-red-900/30 border border-red-700 rounded-lg text-sm text-red-400">
            <span className="font-medium">Import Error:</span> {csvError}
          </div>
        )}

        <div className="flex gap-3 mt-3">
          <button
            onClick={handleImport}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
          >
            Import & Compare
          </button>
          {designPoints.length === 0 && (
            <button
              onClick={() => {
                const demoAB = demoDesignPoints.map(d => ({
                  chainage: d.chainage,
                  surveyedLevel: d.designLevel + (Math.random() - 0.5) * 0.06,
                  surveyedEasting: 123456.789 + d.chainage * 0.5,
                  surveyedNorthing: 9876543.21 + d.chainage * 0.7,
                }))
                setAsBuiltPoints(demoAB)
                setNanWarning(false)
                const r = compareDesignVsAsBuilt(demoDesignPoints, demoAB, tolerance)
                setResult(r)
              }}
              className="px-4 py-2 bg-zinc-700 text-zinc-200 rounded-lg text-sm font-medium hover:bg-zinc-600 transition-colors"
            >
              Load Demo Data
            </button>
          )}
        </div>
      </div>

      {/* Validation: Compare button area */}
      {asBuiltPoints.length > 0 && (
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
          <div className="flex items-center gap-4">
            <div>
              <span className="text-sm text-zinc-400">
                {asBuiltPoints.length} as-built point{asBuiltPoints.length !== 1 ? 's' : ''} loaded
              </span>
              {asBuiltPoints.length < 2 && (
                <span className="ml-2 text-xs text-amber-400">
                  — Need at least 2 points to compare
                </span>
              )}
            </div>
            <button
              onClick={runComparison}
              disabled={asBuiltPoints.length < 2}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                asBuiltPoints.length >= 2
                  ? 'bg-blue-600 text-white hover:bg-blue-700'
                  : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
              }`}
            >
              Compare
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {result && (
        <>
          {/* Summary Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className={`rounded-xl border-2 p-4 ${result.summary.isCompliant ? 'border-green-500 bg-green-900/20' : 'border-red-500 bg-red-900/20'}`}>
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Pass Rate</div>
              <div className={`text-2xl font-bold ${result.summary.isCompliant ? 'text-green-400' : 'text-red-400'}`}>
                {result.summary.passRate.toFixed(1)}%
              </div>
              <div className="text-xs text-zinc-400">{result.summary.passCount} / {result.summary.totalPoints} points</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Max Deviation</div>
              <div className="text-2xl font-bold text-white">{result.summary.maxLevelDeviation.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Tolerance: ±{tolerance.level}mm</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">RMS Error</div>
              <div className="text-2xl font-bold text-white">{result.summary.rmsError.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Root Mean Square</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Mean Deviation</div>
              <div className="text-2xl font-bold text-white">{result.summary.meanLevelDeviation.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Std Dev: {result.summary.standardDeviation.toFixed(1)}mm</div>
            </div>
          </div>

          {/* Compliance Badge */}
          <div className={`rounded-xl p-4 flex items-center gap-3 ${result.summary.certificationReady ? 'bg-green-900/20 border border-green-800' : 'bg-amber-900/20 border border-amber-800'}`}>
            {result.summary.certificationReady ? (
              <svg className="w-6 h-6 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            ) : (
              <svg className="w-6 h-6 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z" /></svg>
            )}
            <div>
              <div className={`font-medium ${result.summary.certificationReady ? 'text-green-400' : 'text-amber-400'}`}>
                {result.summary.certificationReady ? 'Certificate Ready' : 'Not Ready for Certification'}
              </div>
              {result.summary.issues.length > 0 && (
                <ul className="text-xs text-zinc-300 mt-1">
                  {result.summary.issues.map((issue, i) => <li key={`${issue}-${i}`}>• {issue}</li>)}
                </ul>
              )}
            </div>
          </div>

          {/* Deviation Profile SVG */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
            <div className="flex items-center justify-between mb-3">
              <h4 className="font-medium text-white">Deviation Profile</h4>
              <button
                onClick={handleExportCSV}
                className="inline-flex items-center gap-2 px-3 py-1.5 bg-zinc-800 border border-zinc-600 text-zinc-300 rounded-lg text-xs font-medium hover:bg-zinc-700 hover:text-white transition-colors"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                Download Results CSV
              </button>
            </div>
            {nanWarning && (
              <div className="mb-3 px-3 py-2 bg-amber-900/30 border border-amber-700 rounded-lg text-xs text-amber-400">
                <span className="font-medium">Warning:</span> Some deviation values contained NaN and were replaced with 0.
              </div>
            )}
            <DeviationProfileSvg comparisons={result.comparisons} tolerance={tolerance.level} />
          </div>

          {/* Data Table */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 overflow-hidden">
            <div className="px-6 py-4 border-b border-zinc-700 flex items-center justify-between">
              <h4 className="font-medium text-white">As-Built Comparison Table</h4>
              <span className="text-xs text-zinc-400">{result.comparisons.length} rows</span>
            </div>
            <div className="overflow-x-auto max-h-96 overflow-y-auto">
              <table className="w-full text-sm">
                <thead className="bg-zinc-800 sticky top-0">
                  <tr>
                    <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Chainage</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Design RL</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">As-Built RL</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Deviation</th>
                    <th className="px-4 py-2 text-center text-xs font-medium text-zinc-400">Tolerance</th>
                    <th className="px-4 py-2 text-center text-xs font-medium text-zinc-400">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {result.comparisons.map((row, i) => (
                    <tr key={`${row}-${i}`} className={`border-t border-zinc-800 ${row.pass ? 'bg-zinc-900' : 'bg-red-900/15'}`}>
                      <td className="px-4 py-2 font-mono text-xs text-zinc-300">{row.chainage.toFixed(0)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.designLevel.toFixed(4)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.asBuiltLevel.toFixed(4)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.deviation > 0 ? '+' : ''}{row.deviation.toFixed(1)} mm</td>
                      <td className="px-4 py-2 text-center text-xs text-zinc-400">±{row.tolerance}</td>
                      <td className="px-4 py-2 text-center">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${row.pass ? 'bg-green-900/40 text-green-400' : 'bg-red-900/40 text-red-400'}`}>
                          {row.pass ? 'PASS' : 'FAIL'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  )
}

// ─── DEVIATION PROFILE SVG ────────────────────────────────────────────────────

function DeviationProfileSvg({ comparisons, tolerance }: { comparisons: Array<{ chainage: number; deviation: number; pass: boolean }>; tolerance: number }) {
  if (comparisons.length === 0) return null

  // NaN guard: replace NaN deviations with 0
  const sanitizedComparisons = comparisons.map(c => ({
    ...c,
    deviation: isNaN(c.deviation) ? 0 : c.deviation,
  }))

  const width = 900
  const height = 200
  const margin = { top: 20, right: 20, bottom: 40, left: 60 }

  const plotW = width - margin.left - margin.right
  const plotH = height - margin.top - margin.bottom

  const maxCh = Math.max(...sanitizedComparisons.map(c => c.chainage))
  const minCh = Math.min(...sanitizedComparisons.map(c => c.chainage))
  const maxDev = Math.max(tolerance * 1.5, Math.max(...sanitizedComparisons.map(c => Math.abs(c.deviation))))

  const scaleX = (ch: number) => margin.left + ((ch - minCh) / (maxCh - minCh || 1)) * plotW
  const scaleY = (dev: number) => margin.top + plotH / 2 - (dev / maxDev) * (plotH / 2)

  const polyline = sanitizedComparisons.map(c => `${scaleX(c.chainage)},${scaleY(c.deviation)}`).join(' ')

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="w-full">
      {/* Tolerance band */}
      <rect x={margin.left} y={scaleY(tolerance)} width={plotW} height={scaleY(-tolerance) - scaleY(tolerance)} fill="rgba(34,197,94,0.15)" />
      <line x1={margin.left} y1={scaleY(0)} x2={width - margin.right} y2={scaleY(0)} stroke="#71717a" strokeWidth={1} strokeDasharray="4,2" />
      <line x1={margin.left} y1={scaleY(tolerance)} x2={width - margin.right} y2={scaleY(tolerance)} stroke="#16a34a" strokeWidth={1} strokeDasharray="4,2" />
      <line x1={margin.left} y1={scaleY(-tolerance)} x2={width - margin.right} y2={scaleY(-tolerance)} stroke="#16a34a" strokeWidth={1} strokeDasharray="4,2" />

      {/* Data line */}
      <polyline fill="none" stroke="#3b82f6" strokeWidth={1.5} points={polyline} />

      {/* Points */}
      {sanitizedComparisons.map((c, i) => (
        <circle key={`${c}-${i}`} cx={scaleX(c.chainage)} cy={scaleY(c.deviation)} r={3}
          fill={c.pass ? '#16a34a' : '#dc2626'} />
      ))}

      {/* Labels */}
      <text x={width / 2} y={height - 5} textAnchor="middle" className="text-xs" fill="#a1a1aa">Chainage (m)</text>
      <text x={10} y={height / 2} textAnchor="middle" className="text-xs" fill="#a1a1aa" transform={`rotate(-90, 10, ${height / 2})`}>Deviation (mm)</text>
      <text x={margin.left + 4} y={scaleY(tolerance) - 4} className="text-xs" fill="#16a34a">+{tolerance}</text>
      <text x={margin.left + 4} y={scaleY(-tolerance) + 12} className="text-xs" fill="#16a34a">-{tolerance}</text>
    </svg>
  )
}

'use client';

import React, { useMemo } from 'react'
import {
  computeCamberProfile,
  computeDetailedFormationLine,
  computeCutFillArea,
  parseSlopeRatio,
  determineSectionType,
  interpolateGroundAtCentre,
  formatChainage,
  type ProfilePoint,
  type RoadTemplate,
} from '@/lib/engineering/crossSectionGeometry'

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface CrossSectionProps {
  chainage: number
  groundPoints: Array<{ offset: number; level: number }>
  template: RoadTemplate
  formationLevel?: number
  cutArea?: number
  fillArea?: number
  width?: number
  height?: number
  showLabels?: boolean
}

// ─── COLOUR CONSTANTS ──────────────────────────────────────────────────────────

const COLORS = {
  groundLine: '#92400E',         // brown
  groundFill: '#FEF3C7',         // tan
  carriageway: '#374151',        // dark grey
  shoulder: '#6B7280',           // lighter grey
  cutSlope: '#92400E',           // red-brown
  fillSlope: '#1E40AF',          // blue-grey
  subgrade: '#9CA3AF',           // grey dashed
  centreLine: '#6B7280',         // grey dashed
  cutFill: '#DC2626',            // red
  gridLine: '#E5E7EB',          // light grey
  offsetMarker: '#D1D5DB',       // light grey
  labelPrimary: '#111827',       // near black
  labelSecondary: '#6B7280',     // grey
  cutLabel: '#DC2626',           // red
  fillLabel: '#2563EB',          // blue
  dimensionLine: '#4B5563',      // medium grey
  dimensionArrow: '#374151',     // dark grey
  background: '#FAFAFA',         // near white
} as const

// ─── ARROW HEAD COMPONENT ──────────────────────────────────────────────────────

function ArrowHead({
  id,
  color = COLORS.dimensionArrow,
}: {
  id: string
  color?: string
}) {
  return (
    <defs>
      <marker
        id={id}
        viewBox="0 0 10 10"
        refX="5"
        refY="5"
        markerWidth="6"
        markerHeight="6"
        orient="auto-start-reverse"
      >
        <path d="M 0 0 L 10 5 L 0 10 z" fill={color} />
      </marker>
    </defs>
  )
}

// ─── DIMENSION LINE ────────────────────────────────────────────────────────────

function DimensionLine({
  x1,
  y1,
  x2,
  y2,
  label,
  offsetDir = 15,
  id,
}: {
  x1: number
  y1: number
  x2: number
  y2: number
  label: string
  offsetDir?: number
  id: string
}) {
  const dx = x2 - x1
  const dy = y2 - y1
  const len = Math.sqrt(dx * dx + dy * dy)
  if (len < 1) return null

  // Perpendicular direction for label offset
  const nx = -dy / len
  const ny = dx / len

  const midX = (x1 + x2) / 2 + nx * offsetDir
  const midY = (y1 + y2) / 2 + ny * offsetDir

  return (
    <g>
      <line
        x1={x1 + nx * 4}
        y1={y1 + ny * 4}
        x2={x2 + nx * 4}
        y2={y2 + ny * 4}
        stroke={COLORS.dimensionLine}
        strokeWidth={0.5}
        markerStart={`url(#arrow-${id})`}
        markerEnd={`url(#arrow-${id})`}
      />
      <text
        x={midX}
        y={midY + 2.5}
        fontSize="7"
        fill={COLORS.dimensionArrow}
        textAnchor="middle"
        fontFamily="monospace"
      >
        {label}
      </text>
    </g>
  )
}

// ─── MAIN COMPONENT ────────────────────────────────────────────────────────────

export function CrossSectionRenderer({
  chainage,
  groundPoints,
  template,
  formationLevel: propFormationLevel,
  cutArea: propCutArea,
  fillArea: propFillArea,
  width = 800,
  height = 400,
  showLabels = true,
}: CrossSectionProps) {
  const sectionType = useMemo(
    () => determineSectionType(groundPoints, propFormationLevel ?? 0),
    [groundPoints, propFormationLevel]
  )

  const computedFormationLevel = useMemo(() => {
    if (propFormationLevel !== undefined) return propFormationLevel
    // Default: ground level at centre
    const gl = interpolateGroundAtCentre(groundPoints)
    return gl !== null ? gl + 0.5 : 100
  }, [propFormationLevel, groundPoints])

  const isCut = sectionType === 'cut' || sectionType === 'mixed'
  const isFill = sectionType === 'fill' || sectionType === 'mixed'

  // Compute formation line
  const formationLine = useMemo(
    () =>
      computeDetailedFormationLine(
        template,
        computedFormationLevel,
        groundPoints,
        isCut
      ),
    [template, computedFormationLevel, groundPoints, isCut]
  )

  // Compute camber profile for carriageway detail
  const camberProfile = useMemo(
    () => computeCamberProfile(template.carriagewayWidth, template.camber, computedFormationLevel),
    [template.carriagewayWidth, template.camber, computedFormationLevel]
  )

  // Compute areas
  const areas = useMemo(() => {
    if (propCutArea !== undefined && propFillArea !== undefined) {
      return { cutArea: propCutArea, fillArea: propFillArea }
    }
    const netArea = computeCutFillArea(groundPoints, formationLine)
    if (netArea >= 0) {
      return { cutArea: netArea, fillArea: 0 }
    }
    return { cutArea: 0, fillArea: -netArea }
  }, [propCutArea, propFillArea, groundPoints, formationLine])

  // Compute subgrade line
  const subgradeLevel = computedFormationLevel - template.subgradeDepth

  // Auto-scale computation
  const { viewBox, toSvgX, toSvgY } = useMemo(() => {
    const allPoints: ProfilePoint[] = [
      ...groundPoints,
      ...formationLine,
    ]

    // Also consider subgrade
    const minOffset = Math.min(...allPoints.map(p => p.offset)) - 3
    const maxOffset = Math.max(...allPoints.map(p => p.offset)) + 3
    const minLevel = Math.min(
      ...allPoints.map(p => p.level),
      subgradeLevel
    ) - 1.5
    const maxLevel = Math.max(...allPoints.map(p => p.level)) + 1.5

    const dataWidth = maxOffset - minOffset
    const dataHeight = maxLevel - minLevel

    // Add 15% padding
    const padding = 0.15
    const paddedWidth = dataWidth * (1 + padding)
    const paddedHeight = dataHeight * (1 + padding)

    const vbX = minOffset - dataWidth * padding / 2
    const vbY = minLevel - dataHeight * padding / 2

    // Maintain aspect ratio matching the SVG element
    const aspectRatio = width / height
    const dataAspect = paddedWidth / paddedHeight

    let finalVbW: number
    let finalVbH: number
    if (dataAspect > aspectRatio) {
      // Data is wider — fit width, expand height
      finalVbW = paddedWidth
      finalVbH = paddedWidth / aspectRatio
    } else {
      // Data is taller — fit height, expand width
      finalVbH = paddedHeight
      finalVbW = paddedHeight * aspectRatio
    }

    // Centre the data in the viewBox
    const centerX = vbX + dataWidth / 2
    const centerY = vbY + dataHeight / 2
    const finalVbX = centerX - finalVbW / 2
    const finalVbY = centerY - finalVbH / 2

    const scaleX = (offset: number) =>
      ((offset - finalVbX) / finalVbW) * width
    const scaleY = (level: number) =>
      height - ((level - finalVbY) / finalVbH) * height

    return {
      viewBox: `${finalVbX} ${finalVbY} ${finalVbW} ${finalVbH}`,
      toSvgX: scaleX,
      toSvgY: scaleY,
    }
  }, [groundPoints, formationLine, subgradeLevel, width, height])

  // Sorted ground points for polyline
  const sortedGround = useMemo(
    () => [...groundPoints].sort((a, b) => a.offset - b.offset),
    [groundPoints]
  )

  // Centre ground level for cut/fill depth computation
  const centreGroundLevel = interpolateGroundAtCentre(groundPoints)
  const centreDepth =
    centreGroundLevel !== null
      ? centreGroundLevel - computedFormationLevel
      : 0

  // Formation template offsets
  const halfCW = template.carriagewayWidth / 2
  const shoulderEndOffset = halfCW + template.shoulderWidth

  // Slope ratios for labels
  const activeSlopeStr = isCut ? template.cutSlope : template.fillSlope
  let activeSlopeRatio = 0
  try {
    activeSlopeRatio = parseSlopeRatio(activeSlopeStr)
  } catch {
    // fallback
  }

  // Ground polygon points for fill below ground line
  const groundFillPoints = useMemo(() => {
    if (sortedGround.length < 2) return ''
    const yBottom = toSvgY(
      Math.min(...sortedGround.map(p => p.level)) - 2
    )
    const pts = sortedGround
      .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
      .join(' ')
    // Close the polygon at the bottom
    return `${pts} ${toSvgX(sortedGround[sortedGround.length - 1].offset).toFixed(1)},${yBottom.toFixed(1)} ${toSvgX(sortedGround[0].offset).toFixed(1)},${yBottom.toFixed(1)}`
  }, [sortedGround, toSvgX, toSvgY])

  // Ground polyline points
  const groundPolyline = useMemo(
    () =>
      sortedGround
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [sortedGround, toSvgX, toSvgY]
  )

  // Formation polyline points (carriageway only)
  const carriagewayPolyline = useMemo(
    () =>
      camberProfile
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [camberProfile, toSvgX, toSvgY]
  )

  // Full formation line polyline
  const formationPolyline = useMemo(
    () =>
      formationLine
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [formationLine, toSvgX, toSvgY]
  )

  // Slope lines — separate left and right slope segments
  const leftSlopePoints = useMemo(() => {
    const leftShoulder = formationLine.find(
      p => Math.abs(p.offset - (-(halfCW + template.shoulderWidth))) < 0.01
    )
    const leftIntercept = formationLine[0]
    if (!leftShoulder || !leftIntercept) return null
    return {
      x1: toSvgX(leftShoulder.offset),
      y1: toSvgY(leftShoulder.level),
      x2: toSvgX(leftIntercept.offset),
      y2: toSvgY(leftIntercept.level),
    }
  }, [formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  const rightSlopePoints = useMemo(() => {
    const rightShoulder = formationLine.find(
      p => Math.abs(p.offset - (halfCW + template.shoulderWidth)) < 0.01
    )
    const rightIntercept = formationLine[formationLine.length - 1]
    if (!rightShoulder || !rightIntercept) return null
    return {
      x1: toSvgX(rightShoulder.offset),
      y1: toSvgY(rightShoulder.level),
      x2: toSvgX(rightIntercept.offset),
      y2: toSvgY(rightIntercept.level),
    }
  }, [formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  // Shoulder lines
  const leftShoulderLine = useMemo(() => {
    const edge = camberProfile.find(p => Math.abs(p.offset - (-halfCW)) < 0.01)
    const shoulder = formationLine.find(
      p => Math.abs(p.offset - (-(halfCW + template.shoulderWidth))) < 0.01
    )
    if (!edge || !shoulder) return null
    return {
      x1: toSvgX(edge.offset),
      y1: toSvgY(edge.level),
      x2: toSvgX(shoulder.offset),
      y2: toSvgY(shoulder.level),
    }
  }, [camberProfile, formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  const rightShoulderLine = useMemo(() => {
    const edge = camberProfile.find(p => Math.abs(p.offset - halfCW) < 0.01)
    const shoulder = formationLine.find(
      p => Math.abs(p.offset - (halfCW + template.shoulderWidth)) < 0.01
    )
    if (!edge || !shoulder) return null
    return {
      x1: toSvgX(edge.offset),
      y1: toSvgY(edge.level),
      x2: toSvgX(shoulder.offset),
      y2: toSvgY(shoulder.level),
    }
  }, [camberProfile, formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  // Centreline SVG X position
  const clX = toSvgX(0)
  const formSvgY = toSvgY(computedFormationLevel)
  const subgradeSvgY = toSvgY(subgradeLevel)

  // Section type label
  const sectionLabel = useMemo(() => {
    if (areas.cutArea > 0.01 && areas.fillArea > 0.01) {
      return 'CUT/FILL'
    }
    if (areas.cutArea > 0.01) {
      return 'CUT'
    }
    if (areas.fillArea > 0.01) {
      return 'FILL'
    }
    return 'LEVEL'
  }, [areas])

  const sectionLabelColor = useMemo(() => {
    if (areas.cutArea > 0.01 && areas.fillArea > 0.01) return '#7C3AED'
    if (areas.cutArea > 0.01) return COLORS.cutLabel
    if (areas.fillArea > 0.01) return COLORS.fillLabel
    return COLORS.labelSecondary
  }, [areas])

  return (
    <svg
      width={width}
      height={height}
      viewBox={viewBox}
      className="block"
      style={{ background: COLORS.background }}
      role="img"
      aria-label={`Cross-section at chainage ${formatChainage(chainage)}`}
    >
      {/* Arrow markers for dimensions */}
      <ArrowHead id="dim-start" />
      <ArrowHead id="dim-end" />
      <ArrowHead id="dim-v-start" />
      <ArrowHead id="dim-v-end" />

      {/* ── Grid: centreline ── */}
      <line
        x1={clX}
        y1={0}
        x2={clX}
        y2={height}
        stroke={COLORS.centreLine}
        strokeWidth={0.5}
        strokeDasharray="6,4"
      />

      {/* ── Offset markers ── */}
      {showLabels && (
        <>
          {[10, 20, 30, 40, 50].forEach(offset => {
            // Only render if within the view
            const svgXLeft = toSvgX(-offset)
            const svgXRight = toSvgX(offset)
            if (svgXLeft < 0 && svgXRight > width) return
            return (
              <g key={offset}>
                {svgXLeft > 0 && (
                  <>
                    <line
                      x1={svgXLeft}
                      y1={height - 8}
                      x2={svgXLeft}
                      y2={height - 2}
                      stroke={COLORS.offsetMarker}
                      strokeWidth={0.5}
                    />
                    <text
                      x={svgXLeft}
                      y={height - 0.5}
                      fontSize="5"
                      fill={COLORS.labelSecondary}
                      textAnchor="middle"
                      fontFamily="monospace"
                    >
                      {offset}
                    </text>
                  </>
                )}
                {svgXRight < width && (
                  <>
                    <line
                      x1={svgXRight}
                      y1={height - 8}
                      x2={svgXRight}
                      y2={height - 2}
                      stroke={COLORS.offsetMarker}
                      strokeWidth={0.5}
                    />
                    <text
                      x={svgXRight}
                      y={height - 0.5}
                      fontSize="5"
                      fill={COLORS.labelSecondary}
                      textAnchor="middle"
                      fontFamily="monospace"
                    >
                      {offset}
                    </text>
                  </>
                )}
              </g>
            )
          })}
        </>
      )}

      {/* ── Ground profile fill (below ground line) ── */}
      {groundFillPoints && (
        <polygon
          points={groundFillPoints}
          fill={COLORS.groundFill}
          stroke="none"
        />
      )}

      {/* ── Ground profile line ── */}
      <polyline
        points={groundPolyline}
        fill="none"
        stroke={COLORS.groundLine}
        strokeWidth={2}
        strokeLinejoin="round"
      />

      {/* ── Fill slope (right side if fill) ── */}
      {isFill && rightSlopePoints && (
        <line
          x1={rightSlopePoints.x1}
          y1={rightSlopePoints.y1}
          x2={rightSlopePoints.x2}
          y2={rightSlopePoints.y2}
          stroke={COLORS.fillSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}
      {isFill && leftSlopePoints && (
        <line
          x1={leftSlopePoints.x1}
          y1={leftSlopePoints.y1}
          x2={leftSlopePoints.x2}
          y2={leftSlopePoints.y2}
          stroke={COLORS.fillSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}

      {/* ── Cut slope (left side if cut) ── */}
      {isCut && leftSlopePoints && (
        <line
          x1={leftSlopePoints.x1}
          y1={leftSlopePoints.y1}
          x2={leftSlopePoints.x2}
          y2={leftSlopePoints.y2}
          stroke={COLORS.cutSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}
      {isCut && rightSlopePoints && (
        <line
          x1={rightSlopePoints.x1}
          y1={rightSlopePoints.y1}
          x2={rightSlopePoints.x2}
          y2={rightSlopePoints.y2}
          stroke={COLORS.cutSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}

      {/* ── Shoulders ── */}
      {leftShoulderLine && (
        <line
          x1={leftShoulderLine.x1}
          y1={leftShoulderLine.y1}
          x2={leftShoulderLine.x2}
          y2={leftShoulderLine.y2}
          stroke={COLORS.shoulder}
          strokeWidth={2.5}
          strokeLinecap="round"
        />
      )}
      {rightShoulderLine && (
        <line
          x1={rightShoulderLine.x1}
          y1={rightShoulderLine.y1}
          x2={rightShoulderLine.x2}
          y2={rightShoulderLine.y2}
          stroke={COLORS.shoulder}
          strokeWidth={2.5}
          strokeLinecap="round"
        />
      )}

      {/* ── Carriageway with camber ── */}
      <polyline
        points={carriagewayPolyline}
        fill="none"
        stroke={COLORS.carriageway}
        strokeWidth={3}
        strokeLinejoin="round"
        strokeLinecap="round"
      />

      {/* ── Subgrade (dashed) ── */}
      {template.subgradeDepth > 0 && (
        <line
          x1={toSvgX(-shoulderEndOffset - 2)}
          y1={subgradeSvgY}
          x2={toSvgX(shoulderEndOffset + 2)}
          y2={subgradeSvgY}
          stroke={COLORS.subgrade}
          strokeWidth={0.8}
          strokeDasharray="6,3"
        />
      )}

      {/* ── DIMENSIONS ── */}
      {showLabels && (
        <>
          {/* Carriageway width dimension */}
          <DimensionLine
            x1={toSvgX(-halfCW)}
            y1={formSvgY}
            x2={toSvgX(halfCW)}
            y2={formSvgY}
            label={`${template.carriagewayWidth.toFixed(1)}m`}
            offsetDir={12}
            id="cw"
          />

          {/* Left shoulder width dimension */}
          <DimensionLine
            x1={toSvgX(-halfCW)}
            y1={formSvgY}
            x2={toSvgX(-(halfCW + template.shoulderWidth))}
            y2={formSvgY}
            label={`${template.shoulderWidth.toFixed(1)}m`}
            offsetDir={-10}
            id="ls"
          />

          {/* Right shoulder width dimension */}
          <DimensionLine
            x1={toSvgX(halfCW)}
            y1={formSvgY}
            x2={toSvgX(halfCW + template.shoulderWidth)}
            y2={formSvgY}
            label={`${template.shoulderWidth.toFixed(1)}m`}
            offsetDir={10}
            id="rs"
          />

          {/* Cut/fill depth arrow at centreline */}
          {centreGroundLevel !== null && Math.abs(centreDepth) > 0.01 && (
            <g>
              <line
                x1={clX}
                y1={toSvgY(centreGroundLevel)}
                x2={clX}
                y2={formSvgY}
                stroke={centreDepth > 0 ? COLORS.cutLabel : COLORS.fillLabel}
                strokeWidth={0.8}
                markerStart={
                  centreDepth > 0
                    ? 'url(#dim-v-start)'
                    : 'url(#dim-v-end)'
                }
                markerEnd={
                  centreDepth > 0
                    ? 'url(#dim-v-end)'
                    : 'url(#dim-v-start)'
                }
              />
              <text
                x={clX + 6}
                y={(toSvgY(centreGroundLevel) + formSvgY) / 2 + 2.5}
                fontSize="7"
                fill={centreDepth > 0 ? COLORS.cutLabel : COLORS.fillLabel}
                fontFamily="monospace"
              >
                {Math.abs(centreDepth).toFixed(3)}m
              </text>
            </g>
          )}
        </>
      )}

      {/* ── LABELS ── */}
      {showLabels && (
        <>
          {/* Chainage label (top-left) */}
          <g>
            <rect
              x={8}
              y={8}
              width={90}
              height={18}
              rx={3}
              fill="white"
              fillOpacity={0.9}
              stroke="#E5E7EB"
              strokeWidth={0.5}
            />
            <text
              x={14}
              y={21}
              fontSize="9"
              fill={COLORS.labelPrimary}
              fontFamily="monospace"
              fontWeight="600"
            >
              CH {formatChainage(chainage)}
            </text>
          </g>

          {/* Cut/Fill area label (top-right) */}
          <g>
            <rect
              x={width - 140}
              y={8}
              width={132}
              height={18}
              rx={3}
              fill={sectionLabelColor}
              fillOpacity={0.1}
              stroke={sectionLabelColor}
              strokeWidth={0.5}
            />
            <text
              x={width - 134}
              y={21}
              fontSize="9"
              fill={sectionLabelColor}
              fontFamily="monospace"
              fontWeight="600"
            >
              {sectionLabel}{' '}
              {(sectionLabel === 'CUT' || sectionLabel === 'CUT/FILL') &&
                areas.cutArea.toFixed(2) + 'm\u00B2'}
              {sectionLabel === 'CUT/FILL' && ' / '}
              {(sectionLabel === 'FILL' || sectionLabel === 'CUT/FILL') &&
                areas.fillArea.toFixed(2) + 'm\u00B2'}
            </text>
          </g>

          {/* Formation level label */}
          <text
            x={clX + 4}
            y={formSvgY - 4}
            fontSize="6"
            fill={COLORS.labelSecondary}
            fontFamily="monospace"
          >
            FL {computedFormationLevel.toFixed(3)}
          </text>

          {/* Subgrade level label */}
          {template.subgradeDepth > 0 && (
            <text
              x={toSvgX(shoulderEndOffset + 3)}
              y={subgradeSvgY + 3}
              fontSize="6"
              fill={COLORS.labelSecondary}
              fontFamily="monospace"
            >
              SG {subgradeLevel.toFixed(3)}
            </text>
          )}

          {/* Slope ratio labels */}
          {leftSlopePoints && activeSlopeRatio > 0 && (
            <text
              x={(leftSlopePoints.x1 + leftSlopePoints.x2) / 2}
              y={Math.min(leftSlopePoints.y1, leftSlopePoints.y2) - 4}
              fontSize="6"
              fill={COLORS.labelSecondary}
              textAnchor="middle"
              fontFamily="monospace"
            >
              {activeSlopeStr}
            </text>
          )}
          {rightSlopePoints && activeSlopeRatio > 0 && (
            <text
              x={(rightSlopePoints.x1 + rightSlopePoints.x2) / 2}
              y={Math.min(rightSlopePoints.y1, rightSlopePoints.y2) - 4}
              fontSize="6"
              fill={COLORS.labelSecondary}
              textAnchor="middle"
              fontFamily="monospace"
            >
              {activeSlopeStr}
            </text>
          )}

          {/* Camber label */}
          <text
            x={clX}
            y={formSvgY + 12}
            fontSize="6"
            fill={COLORS.labelSecondary}
            textAnchor="middle"
            fontFamily="monospace"
          >
            {template.camber}% camber
          </text>

          {/* Ground level at centreline */}
          {centreGroundLevel !== null && (
            <text
              x={clX - 4}
              y={toSvgY(centreGroundLevel) - 4}
              fontSize="6"
              fill={COLORS.groundLine}
              textAnchor="end"
              fontFamily="monospace"
            >
              GL {centreGroundLevel.toFixed(3)}
            </text>
          )}

          {/* CL label */}
          <text
            x={clX}
            y={height - 12}
            fontSize="6"
            fill={COLORS.labelSecondary}
            textAnchor="middle"
            fontFamily="monospace"
            fontWeight="500"
          >
            CL
          </text>
        </>
      )}
    </svg>
  )
}

export default CrossSectionRenderer

'use client';

import { useState, useMemo } from 'react';
import { AlertTriangle } from 'lucide-react'
import { z } from 'zod';
import { horizontalCurve, logEngineeringCompute } from '@/lib/engineering/compute';
import { initialiseDXFLayers, DXF_LAYERS, TitleBlockData, TITLE_BLOCK_TEMPLATES } from '@/lib/drawing/dxfLayers';
import { getMinRadius, getMinSSD, getMinSuperelevation } from '@/lib/standards/engineering';

const HorizontalCurveInputSchema = z.object({
  R: z.number().positive().min(30).max(2000),
  deltaDeg: z.number().positive().min(1).max(180),
  chainageStart: z.number().min(0).default(0),
  designSpeed: z.number().min(20).max(120).default(60),
});

interface HorizontalCurvePanelProps {
  projectId?: string;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
  standard?: 'KRDM2017' | 'KeRRA';
  designSpeed?: number;
}

export function HorizontalCurvePanel({ projectId, projectData, surveyorProfile, standard = 'KRDM2017', designSpeed = 60 }: HorizontalCurvePanelProps) {
  const [R, setR] = useState(200);
  const [deltaDeg, setDeltaDeg] = useState(35);
  const [chainageStart, setChainageStart] = useState(1000);
  const [error, setError] = useState<string | null>(null);

  const minRadius = getMinRadius(standard, designSpeed);
  const minSSD = getMinSSD(standard, designSpeed);
  const minE = getMinSuperelevation(designSpeed, R);

  const validations = useMemo(() => {
    const issues: string[] = [];
    const passes: string[] = [];

    if (R < minRadius) {
      issues.push(`Radius ${R}m < minimum ${minRadius}m for ${designSpeed}km/h (RDM 1.1)`);
    } else {
      passes.push(`Radius ${R}m ≥ minimum ${minRadius}m `);
    }

    const ssdCheck = R >= minSSD * 0.5;
    if (!ssdCheck) {
      issues.push(`Insufficient sight distance for ${designSpeed}km/h (min SSD: ${minSSD}m)`);
    } else {
      passes.push(`Sight distance adequate (min SSD: ${minSSD}m) `);
    }

    if (minE > 7) {
      issues.push(`Required superelevation ${minE.toFixed(1)}% exceeds 7% max — consider larger radius`);
    } else {
      passes.push(`Superelevation ${minE.toFixed(1)}% within 7% limit `);
    }

    return { issues, passes };
  }, [R, designSpeed, minRadius, minSSD, minE]);

  const result = useMemo(() => {
    try {
      const input = HorizontalCurveInputSchema.parse({ R, deltaDeg, chainageStart, designSpeed });
      setError(null);
      const res = horizontalCurve(input);
      logEngineeringCompute('horizontal_curve', input, {
        T: res.T, L: res.L, LC: res.LC, M: res.M
      }, { projectId });
      return res;
    } catch (e) {
      if (e instanceof z.ZodError) {
        setError(e.errors[0]?.message);
      }
      return null;
    }
  }, [R, deltaDeg, chainageStart, projectId, designSpeed]);

  const exportDXF = async () => {
    if (!result) return;

    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseDXFLayers(drawing);
    const tb: TitleBlockData = {
      drawingTitle: TITLE_BLOCK_TEMPLATES.eng_horizontal_curve.drawingTitle,
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00'
    }
    // renderTitleBlock(drawing, 'eng_horizontal_curve', tb)

    drawing.setActiveLayer(DXF_LAYERS.CENTRELINE.name);
    
    const centerY = 100;
    const scale = 0.5;

    drawing.drawLine(
      50, centerY - result.T * scale,
      50 + result.L * scale, centerY
    );

    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
    drawing.drawText(50, centerY + 20, 0.2, 0, `TC @ ${result.chainage_TC.toFixed(3)}m`);
    drawing.drawText(50 + result.L * scale, centerY + 20, 0.2, 0, `CT @ ${result.chainage_CT.toFixed(3)}m`);
    drawing.drawText(50 + result.T * scale, centerY + 40, 0.2, 0, `IP @ ${chainageStart.toFixed(3)}m`);
    drawing.drawText(50, centerY - 30, 0.25, 0, `R=${R}m Δ=${deltaDeg}°`);
    drawing.drawText(50, centerY - 20, 0.2, 0, `T=${result.T.toFixed(3)}m L=${result.L.toFixed(3)}m`);

    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `horizontal_curve_R${R}_Delta${deltaDeg}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-lg font-semibold text-[var(--text-primary)]">Horizontal Curve Calculator</h3>
          <p className="text-sm text-[var(--text-muted)]">
            Per RDM 1.1 Volume 2, Chapter 3 — Circular Curves
          </p>
        </div>
        {result && (
          <button
            onClick={exportDXF}
            className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      {validations.issues.length > 0 && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
          <p className="text-red-400 text-sm font-semibold mb-1">Standards Violations</p>
          <ul className="text-red-400 text-xs space-y-0.5">
            {validations.issues.map((issue, i) => (
              <li key={`${issue}-${i}`}><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {issue}</li>
            ))}
          </ul>
        </div>
      )}

      {validations.passes.length > 0 && (
        <div className="p-3 bg-green-500/10 border border-green-500/30 rounded-lg">
          <ul className="text-green-400 text-xs space-y-0.5">
            {validations.passes.map((pass, i) => (
              <li key={`${pass}-${i}`}> {pass}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="radius-r-m">Radius R (m)</label>
          <input id="radius-r-m" aria-label="Radius R (m)"
            type="number"
            min={30}
            max={2000}
            value={R}
            onChange={(e) => setR(Number(e.target.value) || 50)}
            className={`w-full bg-[var(--bg-secondary)] border rounded px-3 py-2 text-sm font-mono ${R < minRadius ? 'border-red-500 text-red-400' : 'border-[var(--border-color)]'}`}
          />
          <p className="text-xs text-[var(--text-muted)] mt-0.5">Min: {minRadius}m for {designSpeed}km/h</p>
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="deflection-angle">Deflection Angle Δ (°)</label>
          <input id="deflection-angle" aria-label="Deflection Angle Δ (°)"
            type="number"
            min={1}
            max={180}
            value={deltaDeg}
            onChange={(e) => setDeltaDeg(Number(e.target.value) || 35)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="chainage-at-ip-m">Chainage at IP (m)</label>
          <input  id="chainage-at-ip-m" aria-label="Chainage at IP (m)"
            type="number"
            min={0}
            value={chainageStart}
            onChange={(e) => setChainageStart(Number(e.target.value) || 0)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
      </div>

      {result && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Tangent Length (T)</p>
              <p className="font-mono font-semibold text-orange-400">{result.T.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Curve Length (L)</p>
              <p className="font-mono font-semibold">{result.L.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Long Chord (LC)</p>
              <p className="font-mono font-semibold">{result.LC.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Mid-Ordinate (M)</p>
              <p className="font-mono font-semibold">{result.M.toFixed(3)} m</p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4 text-sm">
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Chainage TC</p>
              <p className="font-mono font-semibold">{result.chainage_TC.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Chainage CT</p>
              <p className="font-mono font-semibold">{result.chainage_CT.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">External (E)</p>
              <p className="font-mono font-semibold">{result.E?.toFixed(3) ?? '-'} m</p>
            </div>
          </div>

          <div className="overflow-x-auto border border-[var(--border-color)] rounded-lg">
            <div className="bg-[var(--bg-secondary)] px-4 py-2 border-b border-[var(--border-color)]">
              <h4 className="font-semibold text-sm">Setting Out Table (20m intervals)</h4>
            </div>
            <table className="w-full text-sm font-mono">
              <thead>
                <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                  <th className="text-left py-2 px-4">Chainage</th>
                  <th className="text-right py-2 px-4">Deflection (°)</th>
                  <th className="text-right py-2 px-4">Chord (m)</th>
                  <th className="text-right py-2 px-4">Increment (m)</th>
                </tr>
              </thead>
              <tbody>
                {result.settingOutTable.slice(0, 15).map((row, i) => (
                  <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="py-1.5 px-4">{row.chainage.toFixed(3)}</td>
                    <td className="py-1.5 px-4 text-right">{row.deflectionFromTC.toFixed(4)}°</td>
                    <td className="py-1.5 px-4 text-right">{row.chordFromTC.toFixed(4)}</td>
                    <td className="py-1.5 px-4 text-right">{row.chordIncrement.toFixed(4)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {result.settingOutTable.length > 15 && (
              <div className="px-4 py-2 text-xs text-[var(--text-muted)] text-center">
                ... and {result.settingOutTable.length - 15} more points
              </div>
            )}
          </div>
        </>
      )}

      <div className="text-xs text-[var(--text-muted)]">
        <p><strong>Reference:</strong> RDM 1.1 Equation 3.1 — T = R × tan(Δ/2)</p>
      </div>
    </div>
  );
}

'use client';

import { useState, useMemo, useCallback } from 'react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
} from '@/components/ui/card'
import { Label } from '@/components/ui/label'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Separator } from '@/components/ui/separator'
import { Progress } from '@/components/ui/progress'
import {
  ROAD_RESERVE_STANDARDS,
  getRoadReserveWidth,
  checkRoadReserveCompliance,
  estimateAcquisitionArea,
  determineAcquisitionType,
  type AcquisitionType,
} from '@/lib/engineering/roadReserve'
import {
  Ruler,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  LandPlot,
  Building2,
  ArrowRightLeft,
  Zap,
} from 'lucide-react'

// ────────────────────────────────────────────────────────────
// Props
// ────────────────────────────────────────────────────────────

interface RoadReservePanelProps {
  roadClass: string
  roadLength?: number
  existingRoadWidth?: number
}

// ────────────────────────────────────────────────────────────
// Helpers
// ────────────────────────────────────────────────────────────

const ACQUISITION_STYLES: Record<AcquisitionType, { label: string; color: string; bg: string }> = {
  full: {
    label: 'Full Acquisition',
    color: 'text-red-700 dark:text-red-400',
    bg: 'bg-red-50 dark:bg-red-950/30 border-red-200 dark:border-red-800',
  },
  partial: {
    label: 'Partial Acquisition',
    color: 'text-amber-700 dark:text-amber-400',
    bg: 'bg-amber-50 dark:bg-amber-950/30 border-amber-200 dark:border-amber-800',
  },
  wayleave: {
    label: 'Wayleave / Easement',
    color: 'text-sky-700 dark:text-sky-400',
    bg: 'bg-sky-50 dark:bg-sky-950/30 border-sky-200 dark:border-sky-800',
  },
  none: {
    label: 'No Acquisition',
    color: 'text-emerald-700 dark:text-emerald-400',
    bg: 'bg-emerald-50 dark:bg-emerald-950/30 border-emerald-200 dark:border-emerald-800',
  },
}

function formatNumber(n: number, decimals = 2): string {
  return n.toLocaleString('en-KE', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  })
}

// ────────────────────────────────────────────────────────────
// SVG Cross-Section Diagram
// ────────────────────────────────────────────────────────────

interface CrossSectionSVGProps {
  reserveWidth: number
  carriagewayWidth: number
  shoulderWidth: number
  wayleaveWidth?: number
}

function CrossSectionDiagram({
  reserveWidth,
  carriagewayWidth,
  shoulderWidth,
  wayleaveWidth,
}: CrossSectionSVGProps) {
  const svgWidth = 700
  const svgHeight = 220
  const padding = 30
  const usableWidth = svgWidth - padding * 2
  const groundY = 110
  const groundLineY = groundY + 50

  // Scale factor: reserveWidth maps to usableWidth
  const scale = usableWidth / reserveWidth
  const centreX = svgWidth / 2

  const cw = carriagewayWidth * scale
  const sw = shoulderWidth * scale
  const rw = reserveWidth * scale

  // Wayleave bands (from reserve edge inward)
  const wlW = wayleaveWidth ? wayleaveWidth * scale : 0

  return (
    <svg
      viewBox={`0 0 ${svgWidth} ${svgHeight}`}
      className="w-full h-auto rounded-lg border bg-muted/30"
      role="img"
      aria-label="Road reserve cross-section diagram"
    >
      {/* Title */}
      <text x={svgWidth / 2} y={22} textAnchor="middle" className="text-[11px] font-semibold fill-foreground">
        Road Reserve Cross-Section (Not to Scale)
      </text>

      {/* Ground fill */}
      <rect
        x={centreX - rw / 2}
        y={groundY}
        width={rw}
        height={groundLineY - groundY + 30}
        fill="#e2e8f0"
        opacity={0.5}
        rx={2}
      />

      {/* Wayleave bands (left and right) */}
      {wlW > 0 && (
        <>
          <rect
            x={centreX - rw / 2}
            y={groundY}
            width={wlW}
            height={groundLineY - groundY}
            fill="#bae6fd"
            opacity={0.5}
            rx={1}
          />
          <rect
            x={centreX + rw / 2 - wlW}
            y={groundY}
            width={wlW}
            height={groundLineY - groundY}
            fill="#bae6fd"
            opacity={0.5}
            rx={1}
          />
          {/* Wayleave label left */}
          <text x={centreX - rw / 2 + wlW / 2} y={groundLineY + 16} textAnchor="middle" className="text-[9px] fill-sky-700">
            Wayleave
          </text>
          <text x={centreX - rw / 2 + wlW / 2} y={groundLineY + 28} textAnchor="middle" className="text-[9px] fill-sky-700">
            {wayleaveWidth}m
          </text>
          {/* Wayleave label right */}
          <text x={centreX + rw / 2 - wlW / 2} y={groundLineY + 16} textAnchor="middle" className="text-[9px] fill-sky-700">
            Wayleave
          </text>
          <text x={centreX + rw / 2 - wlW / 2} y={groundLineY + 28} textAnchor="middle" className="text-[9px] fill-sky-700">
            {wayleaveWidth}m
          </text>
        </>
      )}

      {/* Left reserve area (green) */}
      <rect
        x={centreX - rw / 2 + (wlW > 0 ? wlW : 0)}
        y={groundY}
        width={rw / 2 - cw / 2 - sw + (wlW > 0 ? -wlW : 0)}
        height={groundLineY - groundY}
        fill="#bbf7d0"
        opacity={0.7}
      />
      {/* Right reserve area (green) */}
      <rect
        x={centreX + cw / 2 + sw}
        y={groundY}
        width={rw / 2 - cw / 2 - sw - (wlW > 0 ? wlW : 0)}
        height={groundLineY - groundY}
        fill="#bbf7d0"
        opacity={0.7}
      />

      {/* Left shoulder */}
      <rect
        x={centreX - cw / 2 - sw}
        y={groundY}
        width={sw}
        height={groundLineY - groundY}
        fill="#94a3b8"
        rx={1}
      />
      {/* Right shoulder */}
      <rect
        x={centreX + cw / 2}
        y={groundY}
        width={sw}
        height={groundLineY - groundY}
        fill="#94a3b8"
        rx={1}
      />

      {/* Carriageway */}
      <rect
        x={centreX - cw / 2}
        y={groundY}
        width={cw}
        height={groundLineY - groundY}
        fill="#64748b"
        rx={2}
      />

      {/* Centreline (dashed) */}
      <line
        x1={centreX}
        y1={groundY - 10}
        x2={centreX}
        y2={groundLineY + 5}
        stroke="#f59e0b"
        strokeWidth={2}
        strokeDasharray="6 4"
      />

      {/* Carriageway edge lines */}
      <line x1={centreX - cw / 2} y1={groundY} x2={centreX - cw / 2} y2={groundLineY} stroke="white" strokeWidth={2} />
      <line x1={centreX + cw / 2} y1={groundY} x2={centreX + cw / 2} y2={groundLineY} stroke="white" strokeWidth={2} />

      {/* Shoulder edge lines */}
      <line x1={centreX - cw / 2 - sw} y1={groundY} x2={centreX - cw / 2 - sw} y2={groundLineY} stroke="#cbd5e1" strokeWidth={1} strokeDasharray="4 3" />
      <line x1={centreX + cw / 2 + sw} y1={groundY} x2={centreX + cw / 2 + sw} y2={groundLineY} stroke="#cbd5e1" strokeWidth={1} strokeDasharray="4 3" />

      {/* Reserve boundary lines */}
      <line x1={centreX - rw / 2} y1={groundY - 5} x2={centreX - rw / 2} y2={groundLineY + 5} stroke="#16a34a" strokeWidth={2.5} />
      <line x1={centreX + rw / 2} y1={groundY - 5} x2={centreX + rw / 2} y2={groundLineY + 5} stroke="#16a34a" strokeWidth={2.5} />

      {/* Width dimension lines and labels */}
      {/* Reserve width — top */}
      <line x1={centreX - rw / 2} y1={groundY - 8} x2={centreX + rw / 2} y2={groundY - 8} stroke="#16a34a" strokeWidth={1} markerStart="url(#arrowStart)" markerEnd="url(#arrowEnd)" />
      <rect x={centreX - 35} y={groundY - 22} width={70} height={14} rx={2} fill="white" opacity={0.9} />
      <text x={centreX} y={groundY - 12} textAnchor="middle" className="text-[10px] font-semibold fill-green-700">
        Reserve {reserveWidth}m
      </text>

      {/* Carriageway — bottom */}
      <line x1={centreX - cw / 2} y1={groundLineY + 8} x2={centreX + cw / 2} y2={groundLineY + 8} stroke="#475569" strokeWidth={1} />
      <rect x={centreX - 40} y={groundLineY + 12} width={80} height={14} rx={2} fill="white" opacity={0.9} />
      <text x={centreX} y={groundLineY + 23} textAnchor="middle" className="text-[10px] font-medium fill-slate-600">
        Carriageway {carriagewayWidth}m
      </text>

      {/* Left shoulder label */}
      <text x={centreX - cw / 2 - sw / 2} y={groundY + (groundLineY - groundY) / 2 + 4} textAnchor="middle" className="text-[9px] fill-white font-medium">
        {shoulderWidth}m
      </text>
      {/* Right shoulder label */}
      <text x={centreX + cw / 2 + sw / 2} y={groundY + (groundLineY - groundY) / 2 + 4} textAnchor="middle" className="text-[9px] fill-white font-medium">
        {shoulderWidth}m
      </text>

      {/* Centreline label */}
      <text x={centreX} y={groundY - 2} textAnchor="middle" className="text-[8px] fill-amber-700 font-semibold">CL</text>

      {/* Legend */}
      <rect x={padding} y={svgHeight - 30} width={12} height={8} rx={1} fill="#bbf7d0" stroke="#16a34a" strokeWidth={0.5} />
      <text x={padding + 16} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Reserve</text>
      <rect x={padding + 65} y={svgHeight - 30} width={12} height={8} rx={1} fill="#94a3b8" />
      <text x={padding + 81} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Shoulder</text>
      <rect x={padding + 145} y={svgHeight - 30} width={12} height={8} rx={1} fill="#64748b" />
      <text x={padding + 161} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Carriageway</text>
      <line x1={padding + 235} y1={svgHeight - 26} x2={padding + 255} y2={svgHeight - 26} stroke="#f59e0b" strokeWidth={2} strokeDasharray="4 3" />
      <text x={padding + 259} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Centreline</text>
      {wlW > 0 && (
        <>
          <rect x={padding + 325} y={svgHeight - 30} width={12} height={8} rx={1} fill="#bae6fd" opacity={0.5} />
          <text x={padding + 341} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Wayleave</text>
        </>
      )}

      {/* Arrow markers */}
      <defs>
        <marker id="arrowStart" markerWidth="6" markerHeight="6" refX="6" refY="3" orient="auto">
          <path d="M6 0 L0 3 L6 6" fill="none" stroke="#16a34a" strokeWidth={1} />
        </marker>
        <marker id="arrowEnd" markerWidth="6" markerHeight="6" refX="0" refY="3" orient="auto">
          <path d="M0 0 L6 3 L0 6" fill="none" stroke="#16a34a" strokeWidth={1} />
        </marker>
      </defs>
    </svg>
  )
}

// ────────────────────────────────────────────────────────────
// Placeholder parcel list for future integration
// ────────────────────────────────────────────────────────────

interface PlaceholderParcel {
  id: string
  lrNo: string
  owner: string
  overlapPct: number
  hasBuilding: boolean
}

const PLACEHOLDER_PARCELS: PlaceholderParcel[] = [
  { id: '1', lrNo: 'LR 12345/456', owner: 'Kamau J.', overlapPct: 95, hasBuilding: true },
  { id: '2', lrNo: 'LR 12345/457', owner: 'Ochieng W.', overlapPct: 45, hasBuilding: false },
  { id: '3', lrNo: 'LR 12345/458', owner: 'Wanjiku M.', overlapPct: 12, hasBuilding: false },
  { id: '4', lrNo: 'LR 12345/459', owner: 'Kipruto D.', overlapPct: 62, hasBuilding: true },
  { id: '5', lrNo: 'LR 12345/460', owner: 'Hassan A.', overlapPct: 5, hasBuilding: false },
]

// ────────────────────────────────────────────────────────────
// Main Component
// ────────────────────────────────────────────────────────────

export default function RoadReservePanel({
  roadClass,
  roadLength,
  existingRoadWidth: propExistingWidth,
}: RoadReservePanelProps) {
  // ── State ──
  const standards = ROAD_RESERVE_STANDARDS[roadClass]
  const reserveInfo = getRoadReserveWidth(roadClass)

  const [proposedWidth, setProposedWidth] = useState<string>(
    String(reserveInfo.standard),
  )
  const [roadLengthInput, setRoadLengthInput] = useState<string>(
    String(roadLength ?? 1000),
  )
  const [existingWidth, setExistingWidth] = useState<string>(
    String(propExistingWidth ?? 0),
  )
  const [wayleaveWidth, setWayleaveWidth] = useState<string>('3.0')
  const [showWayleave, setShowWayleave] = useState(true)

  // ── Computed values ──
  const proposedNum = parseFloat(proposedWidth) || 0
  const roadLengthNum = parseFloat(roadLengthInput) || 0
  const existingNum = parseFloat(existingWidth) || 0
  const wayleaveNum = parseFloat(wayleaveWidth) || 0

  const compliance = useMemo(
    () => checkRoadReserveCompliance(roadClass, proposedNum),
    [roadClass, proposedNum],
  )

  const acquisition = useMemo(
    () => estimateAcquisitionArea(roadLengthNum, proposedNum, existingNum),
    [roadLengthNum, proposedNum, existingNum],
  )

  const compliancePercent = useMemo(() => {
    if (compliance.required === 0) return 0
    return Math.min(100, (proposedNum / compliance.required) * 100)
  }, [proposedNum, compliance.required])

  const handleProposedWidthChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setProposedWidth(v)
      }
    },
    [],
  )

  const handleLengthChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setRoadLengthInput(v)
      }
    },
    [],
  )

  const handleExistingWidthChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setExistingWidth(v)
      }
    },
    [],
  )

  const handleWayleaveChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setWayleaveWidth(v)
      }
    },
    [],
  )

  // ── Render ──
  if (!standards) {
    return (
      <Card>
        <CardContent className="p-6">
          <p className="text-muted-foreground text-sm">
            Select a valid road class to view road reserve information.
          </p>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      {/* ────────────────────────────────────────────────── */}
      {/* Card 1: Road Reserve Standard                     */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Ruler className="h-4 w-4 text-primary" />
            <CardTitle>Road Reserve Standard</CardTitle>
          </div>
          <CardDescription>
            Class {roadClass} — {standards.description}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Minimum Reserve</p>
              <p className="text-lg font-bold">{standards.reserveWidthMin}m</p>
            </div>
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Standard Reserve</p>
              <p className="text-lg font-bold">{standards.reserveWidthStd}m</p>
            </div>
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Carriageway</p>
              <p className="text-lg font-bold">{standards.carriagewayStd}m</p>
            </div>
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Shoulder</p>
              <p className="text-lg font-bold">{standards.shoulderStd}m</p>
            </div>
          </div>

          {/* Quick reference for all classes */}
          <details className="text-sm">
            <summary className="cursor-pointer text-muted-foreground hover:text-foreground transition-colors">
              View all road classes
            </summary>
            <div className="mt-2 rounded-lg border overflow-hidden">
              <table className="w-full text-xs">
                <thead>
                  <tr className="bg-muted/50">
                    <th className="text-left px-3 py-1.5 font-medium">Class</th>
                    <th className="text-left px-3 py-1.5 font-medium">Description</th>
                    <th className="text-right px-3 py-1.5 font-medium">Min (m)</th>
                    <th className="text-right px-3 py-1.5 font-medium">Std (m)</th>
                    <th className="text-right px-3 py-1.5 font-medium">CW (m)</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.values(ROAD_RESERVE_STANDARDS).map((s) => (
                    <tr
                      key={s.class}
                      className={
                        s.class === roadClass
                          ? 'bg-primary/5 font-semibold'
                          : 'border-t'
                      }
                    >
                      <td className="px-3 py-1.5">{s.class}</td>
                      <td className="px-3 py-1.5">{s.description}</td>
                      <td className="text-right px-3 py-1.5">{s.reserveWidthMin}</td>
                      <td className="text-right px-3 py-1.5">{s.reserveWidthStd}</td>
                      <td className="text-right px-3 py-1.5">{s.carriagewayStd}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </details>
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 2: Compliance Check                          */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-primary" />
              <CardTitle>Reserve Width Compliance</CardTitle>
            </div>
            {compliance.compliant ? (
              <Badge className="bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800">
                <CheckCircle2 className="h-3 w-3 mr-1" />
                Compliant
              </Badge>
            ) : (
              <Badge className="bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300 border-red-200 dark:border-red-800">
                <XCircle className="h-3 w-3 mr-1" />
                Non-Compliant
              </Badge>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="proposed-width">Proposed Reserve Width (m)</Label>
              <Input
                id="proposed-width"
                type="text"
                inputMode="decimal"
                value={proposedWidth}
                onChange={handleProposedWidthChange}
                placeholder={String(reserveInfo.standard)}
              />
              <p className="text-xs text-muted-foreground">
                Minimum required: <span className="font-semibold">{standards.reserveWidthMin}m</span>
                {' · '}Standard: <span className="font-semibold">{standards.reserveWidthStd}m</span>
              </p>
            </div>
            <div className="space-y-2">
              <Label>Compliance Status</Label>
              <div className="h-9 flex items-center">
                {compliance.compliant ? (
                  <div className="flex items-center gap-2 text-emerald-700 dark:text-emerald-400">
                    <CheckCircle2 className="h-5 w-5" />
                    <span className="text-sm font-medium">
                      Meets minimum ({formatNumber(proposedNum)}m ≥ {standards.reserveWidthMin}m)
                    </span>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 text-red-700 dark:text-red-400">
                    <XCircle className="h-5 w-5" />
                    <span className="text-sm font-medium">
                      Deficit of {formatNumber(compliance.deficit)}m
                    </span>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Progress bar */}
          <div className="space-y-1">
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>0m</span>
              <span>Min: {standards.reserveWidthMin}m</span>
              <span>Std: {standards.reserveWidthStd}m</span>
            </div>
            <div className="relative h-3 rounded-full bg-muted overflow-hidden">
              {/* Standard zone marker */}
              <div
                className="absolute top-0 h-full w-px bg-foreground/30 z-10"
                style={{
                  left: `${Math.min(100, (standards.reserveWidthStd / (standards.reserveWidthStd * 1.5)) * 100)}%`,
                }}
              />
              {/* Minimum zone marker */}
              <div
                className="absolute top-0 h-full w-px bg-destructive/50 z-10"
                style={{
                  left: `${Math.min(100, (standards.reserveWidthMin / (standards.reserveWidthStd * 1.5)) * 100)}%`,
                }}
              />
              {/* Fill */}
              <div
                className={`h-full rounded-full transition-all duration-300 ${
                  compliance.compliant ? 'bg-emerald-500' : 'bg-red-500'
                }`}
                style={{
                  width: `${Math.min(100, (proposedNum / (standards.reserveWidthStd * 1.5)) * 100)}%`,
                }}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 3: Cross-Section Diagram                     */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <ArrowRightLeft className="h-4 w-4 text-primary" />
            <CardTitle>Corridor Cross-Section</CardTitle>
          </div>
          <CardDescription>
            Visual representation of the road reserve, carriageway, and shoulders
          </CardDescription>
        </CardHeader>
        <CardContent>
          <CrossSectionDiagram
            reserveWidth={proposedNum || standards.reserveWidthStd}
            carriagewayWidth={standards.carriagewayStd}
            shoulderWidth={standards.shoulderStd}
            wayleaveWidth={showWayleave ? wayleaveNum : undefined}
          />
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 4: Acquisition Estimate                      */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <LandPlot className="h-4 w-4 text-primary" />
            <CardTitle>Land Acquisition Estimate</CardTitle>
          </div>
          <CardDescription>
            Estimated area required for the road reserve corridor
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="road-length">Road Length (m)</Label>
              <Input
                id="road-length"
                type="text"
                inputMode="decimal"
                value={roadLengthInput}
                onChange={handleLengthChange}
                placeholder="1000"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="existing-width">Existing Road Width (m)</Label>
              <Input
                id="existing-width"
                type="text"
                inputMode="decimal"
                value={existingWidth}
                onChange={handleExistingWidthChange}
                placeholder="0"
              />
              <p className="text-xs text-muted-foreground">
                Width of existing carriageway + shoulders already acquired
              </p>
            </div>
            <div className="space-y-2">
              <Label>Reserve Width</Label>
              <div className="h-9 flex items-center rounded-md border bg-muted/50 px-3">
                <span className="text-sm font-medium">{formatNumber(proposedNum)}m</span>
              </div>
            </div>
          </div>

          <Separator />

          {roadLengthNum > 0 && proposedNum > 0 ? (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">Total Reserve Area</p>
                <p className="text-xl font-bold">{formatNumber(acquisition.totalReserveArea)}</p>
                <p className="text-xs text-muted-foreground">sqm</p>
              </div>
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">New Acquisition</p>
                <p className="text-xl font-bold text-amber-700 dark:text-amber-400">
                  {formatNumber(acquisition.newAcquisitionArea)}
                </p>
                <p className="text-xs text-muted-foreground">sqm</p>
              </div>
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">Total Acres</p>
                <p className="text-xl font-bold">{formatNumber(acquisition.totalAcres)}</p>
                <p className="text-xs text-muted-foreground">ac</p>
              </div>
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">Total Hectares</p>
                <p className="text-xl font-bold">{formatNumber(acquisition.totalHectares)}</p>
                <p className="text-xs text-muted-foreground">ha</p>
              </div>
            </div>
          ) : (
            <p className="text-sm text-muted-foreground text-center py-4">
              Enter road length and reserve width to see acquisition estimates.
            </p>
          )}

          {existingNum > 0 && acquisition.newAcquisitionArea > 0 && (
            <div className="rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/30 p-3 flex items-start gap-2">
              <AlertTriangle className="h-4 w-4 text-amber-600 dark:text-amber-400 mt-0.5 shrink-0" />
              <p className="text-xs text-amber-800 dark:text-amber-200">
                {formatNumber(acquisition.newAcquisitionArea)} sqm of new land acquisition required beyond the
                existing {formatNumber(existingNum)}m road width.
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 5: Property Impact Summary                   */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Building2 className="h-4 w-4 text-primary" />
            <CardTitle>Property Impact Assessment</CardTitle>
          </div>
          <CardDescription>
            Affected parcels and acquisition classification
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg border overflow-hidden">
            <div className="max-h-72 overflow-y-auto custom-scrollbar">
              <table className="w-full text-sm">
                <thead className="sticky top-0 bg-muted/80 backdrop-blur-sm">
                  <tr>
                    <th className="text-left px-4 py-2.5 font-medium text-xs text-muted-foreground">LR No.</th>
                    <th className="text-left px-4 py-2.5 font-medium text-xs text-muted-foreground">Owner</th>
                    <th className="text-right px-4 py-2.5 font-medium text-xs text-muted-foreground">Overlap</th>
                    <th className="text-center px-4 py-2.5 font-medium text-xs text-muted-foreground">Structure</th>
                    <th className="text-left px-4 py-2.5 font-medium text-xs text-muted-foreground">Classification</th>
                  </tr>
                </thead>
                <tbody>
                  {PLACEHOLDER_PARCELS.map((parcel) => {
                    const acqType = determineAcquisitionType(parcel.overlapPct, parcel.hasBuilding)
                    const style = ACQUISITION_STYLES[acqType]
                    return (
                      <tr key={parcel.id} className="border-t hover:bg-muted/30 transition-colors">
                        <td className="px-4 py-2.5 font-mono text-xs">{parcel.lrNo}</td>
                        <td className="px-4 py-2.5">{parcel.owner}</td>
                        <td className="text-right px-4 py-2.5">
                          <div className="flex items-center justify-end gap-2">
                            <Progress value={parcel.overlapPct} className="w-16 h-1.5" />
                            <span className="text-xs tabular-nums w-10 text-right">
                              {parcel.overlapPct}%
                            </span>
                          </div>
                        </td>
                        <td className="text-center px-4 py-2.5">
                          {parcel.hasBuilding ? (
                            <Building2 className="h-3.5 w-3.5 inline text-muted-foreground" />
                          ) : (
                            <LandPlot className="h-3.5 w-3.5 inline text-muted-foreground/50" />
                          )}
                        </td>
                        <td className="px-4 py-2.5">
                          <span
                            className={`inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium ${style.bg} ${style.color}`}
                          >
                            {style.label}
                          </span>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          </div>
          <div className="flex flex-wrap gap-3 mt-3">
            {(
              Object.entries(ACQUISITION_STYLES) as [AcquisitionType, (typeof ACQUISITION_STYLES)[AcquisitionType]][]
            ).map(([key, style]) => (
              <div key={key} className="flex items-center gap-1.5">
                <div className={`h-2.5 w-2.5 rounded-sm border ${style.bg}`} />
                <span className="text-xs text-muted-foreground">{style.label}</span>
              </div>
            ))}
          </div>
          <p className="text-xs text-muted-foreground mt-2 italic">
            Parcel data is placeholder for future GIS integration.
          </p>
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 6: Wayleave Section                          */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Zap className="h-4 w-4 text-primary" />
              <CardTitle>Wayleave / Utility Corridor</CardTitle>
            </div>
            <label className="flex items-center gap-2 cursor-pointer">
              <input aria-label="Showwayleave"
                type="checkbox"
                checked={showWayleave}
                onChange={(e) => setShowWayleave(e.target.checked)}
                className="rounded border-input h-4 w-4"
              />
              <span className="text-xs text-muted-foreground">Show on diagram</span>
            </label>
          </div>
          <CardDescription>
            Utility wayleaves are accommodated within the road reserve corridor
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="wayleave-width">Wayleave Width (m)</Label>
              <Input
                id="wayleave-width"
                type="text"
                inputMode="decimal"
                value={wayleaveWidth}
                onChange={handleWayleaveChange}
                placeholder="3.0"
              />
            </div>
            <div className="space-y-2">
              <Label>Typical Wayleave Widths</Label>
              <div className="flex flex-wrap gap-2">
                {[
                  { label: 'Water', width: 3 },
                  { label: 'Power', width: 4 },
                  { label: 'Fibre', width: 3 },
                  { label: 'Gas', width: 6 },
                  { label: 'Sewer', width: 5 },
                ].map((w) => (
                  <button
                    key={w.label}
                    type="button"
                    onClick={() => setWayleaveWidth(String(w.width))}
                    className="inline-flex items-center gap-1 rounded-md border px-2 py-1 text-xs hover:bg-muted/50 transition-colors cursor-pointer"
                  >
                    {w.label}
                    <span className="text-muted-foreground">{w.width}m</span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="rounded-lg border border-sky-200 dark:border-sky-800 bg-sky-50 dark:bg-sky-950/30 p-3 flex items-start gap-2">
            <Zap className="h-4 w-4 text-sky-600 dark:text-sky-400 mt-0.5 shrink-0" />
            <div className="text-xs text-sky-800 dark:text-sky-200 space-y-1">
              <p>
                Wayleaves are utility easements within the road reserve. They do not require separate
                land acquisition but must be within the gazetted reserve width.
              </p>
              <p>
                Standard wayleave widths: 3–6m depending on utility type. Multiple utilities
                may share a common wayleave corridor.
              </p>
            </div>
          </div>

          {/* Wayleave vs reserve check */}
          {wayleaveNum > 0 && proposedNum > 0 && (
            <div className="text-xs">
              {wayleaveNum * 2 <= proposedNum ? (
                <div className="flex items-center gap-1.5 text-emerald-700 dark:text-emerald-400">
                  <CheckCircle2 className="h-3.5 w-3.5" />
                  <span>
                    Wayleave ({wayleaveNum}m × 2 = {formatNumber(wayleaveNum * 2)}m) fits within
                    reserve ({formatNumber(proposedNum)}m)
                  </span>
                </div>
              ) : (
                <div className="flex items-center gap-1.5 text-red-700 dark:text-red-400">
                  <XCircle className="h-3.5 w-3.5" />
                  <span>
                    Wayleave ({wayleaveNum}m × 2 = {formatNumber(wayleaveNum * 2)}m) exceeds reserve width ({formatNumber(proposedNum)}m).
                    Reserve may need widening.
                  </span>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

'use client';

import { useState, useMemo } from 'react';
import { AlertTriangle } from 'lucide-react'
import { superelevationCalc, type SuperelevationResult, logEngineeringCompute } from '@/lib/engineering/compute';
import { z } from 'zod';
import { initialiseDXFLayers, DXF_LAYERS, TitleBlockData, TITLE_BLOCK_TEMPLATES } from '@/lib/drawing/dxfLayers';

const SuperelevationInputSchema = z.object({
  R: z.number().positive().min(50).max(2000),
  V: z.number().positive().min(20).max(120),
  eMax: z.number().positive().max(0.12).default(0.07),
});

interface SuperelevationPanelProps {
  initialRadius?: number;
  initialSpeed?: number;
  projectId?: string;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
  standard?: 'KRDM2017' | 'KeRRA';
}

export default function SuperelevationPanel({ 
  initialRadius = 200, 
  initialSpeed = 80,
  projectId,
  projectData,
  surveyorProfile,
  standard = 'KRDM2017'
}: SuperelevationPanelProps) {
  const [R, setR] = useState(initialRadius);
  const [V, setV] = useState(initialSpeed);
  const [eMax, setEmax] = useState(0.07);
  const [error, setError] = useState<string | null>(null);

  const eRequired = (V * V) / (225 * R);
  const ePercent = eRequired * 100;
  const minTransition = Math.max(0.6 * (V * V) / R, 30);

  const validations = useMemo(() => {
    const issues: string[] = [];
    const passes: string[] = [];

    if (ePercent > 12) {
      issues.push(`Required e ${ePercent.toFixed(1)}% exceeds absolute max 12%`);
    } else if (ePercent > 7) {
      issues.push(`Required e ${ePercent.toFixed(1)}% exceeds KeRRA rural max 7%`);
    } else {
      passes.push(`e ${ePercent.toFixed(1)}% within 7% limit `);
    }

    if (minTransition < 30) {
      issues.push(`Transition length ${minTransition.toFixed(1)}m < absolute minimum 30m`);
    } else {
      passes.push(`Transition length ${minTransition.toFixed(1)}m ≥ 30m minimum `);
    }

    if (standard === 'KeRRA' && ePercent > 7) {
      issues.push(`KeRRA rural roads: max e = 7%. Consider larger radius or lower speed.`);
    }

    return { issues, passes };
  }, [ePercent, minTransition, standard]);

  const result: SuperelevationResult | null = useMemo(() => {
    try {
      const input = SuperelevationInputSchema.parse({ R, V, eMax });
      setError(null);
      const res = superelevationCalc(input);
      
      logEngineeringCompute('superelevation', input, res, { projectId });
      
      return res;
    } catch (e) {
      if (e instanceof z.ZodError) {
        setError(e.errors[0]?.message || 'Invalid input');
      }
      return null;
    }
  }, [R, V, eMax, projectId]);

  const exportToDXF = async () => {
    if (!result) return;
    
    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseDXFLayers(drawing);
    // Render title block via template system
    const tb: TitleBlockData = {
      drawingTitle: TITLE_BLOCK_TEMPLATES.eng_superelevation.drawingTitle,
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00'
    }
    // renderTitleBlock(drawing, 'eng_superelevation', tb);
    
    drawing.setActiveLayer(DXF_LAYERS.PROFILE.name);
    
    const width = 30;
    const e = result.eDesign / 100;
    const angleRad = Math.atan(e);
    const rise = width * Math.tan(angleRad);
    
    drawing.drawLine(0, 0, width, rise);
    drawing.drawLine(0, 0, width, 0);
    drawing.drawLine(width, rise, width, rise + 0.3);
    
    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
    drawing.drawText(1, 0.5, 0.15, 0, `R=${R}m V=${V}km/h e=${result.eDesign.toFixed(1)}%`);
    drawing.drawText(1, 1.5, 0.15, 0, `Transition: ${result.transitionLength.toFixed(1)}m`);
    
    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `superelevation_R${R}_V${V}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-lg font-semibold text-[var(--text-primary)]">Superelevation Calculation</h3>
          <p className="text-sm text-[var(--text-muted)]">
            Per RDM 1.1 Section 3.4 and KeRRA Rural Roads Design Manual
          </p>
        </div>
        {result && (
          <button
            onClick={exportToDXF}
            className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      {validations.issues.length > 0 && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
          <p className="text-red-400 text-sm font-semibold mb-1">Standards Violations</p>
          <ul className="text-red-400 text-xs space-y-0.5">
            {validations.issues.map((issue, i) => (
              <li key={`${issue}-${i}`}><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {issue}</li>
            ))}
          </ul>
        </div>
      )}

      {validations.passes.length > 0 && (
        <div className="p-3 bg-green-500/10 border border-green-500/30 rounded-lg">
          <ul className="text-green-400 text-xs space-y-0.5">
            {validations.passes.map((pass, i) => (
              <li key={`${pass}-${i}`}> {pass}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="curve-radius-r-m">Curve Radius R (m)</label>
          <input id="curve-radius-r-m" aria-label="Curve Radius R (m)"
            type="number"
            min={30}
            max={2000}
            value={R}
            onChange={(e) => setR(Number(e.target.value) || 50)}
            className={`w-full bg-[var(--bg-secondary)] border rounded px-3 py-2 text-sm font-mono ${ePercent > 7 ? 'border-red-500 text-red-400' : 'border-[var(--border-color)]'}`}
          />
          <p className="text-xs text-[var(--text-muted)] mt-0.5">e required: {ePercent.toFixed(1)}%</p>
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="design-speed-v-km-h">Design Speed V (km/h)</label>
          <input id="design-speed-v-km-h" aria-label="Design Speed V (km/h)"
            type="number"
            min={20}
            max={120}
            value={V}
            onChange={(e) => setV(Number(e.target.value) || 80)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="max-superelevation-e-max">Max Superelevation e<sub>max</sub></label>
          <select
             id="max-superelevation-e-max" value={eMax}
            onChange={(e) => setEmax(Number(e.target.value))}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          >
            <option value={0.04}>4%</option>
            <option value={0.05}>5%</option>
            <option value={0.06}>6%</option>
            <option value={0.07}>7% (KeRRA default)</option>
            <option value={0.08}>8%</option>
            <option value={0.10}>10%</option>
            <option value={0.12}>12%</option>
          </select>
          <p className="text-xs text-[var(--text-muted)] mt-0.5">Min transition: {minTransition.toFixed(1)}m</p>
        </div>
      </div>

      {/* Results Summary */}
      {result && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Design e</p>
            <p className="font-mono font-semibold text-orange-400">{result.eDesign.toFixed(2)}%</p>
          </div>
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Transition Length</p>
            <p className="font-mono font-semibold">{result.transitionLength.toFixed(1)} m</p>
          </div>
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Rate</p>
            <p className="font-mono font-semibold">{result.rate.toFixed(4)}%/m</p>
          </div>
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Max e</p>
            <p className="font-mono font-semibold">{result.eMax.toFixed(2)}%</p>
          </div>
        </div>
      )}

      {/* Transition Table */}
      {result && (
        <div>
          <h4 className="font-semibold mb-2 text-sm">Superelevation Transition Table</h4>
          <div className="overflow-x-auto">
            <table className="w-full text-sm font-mono">
              <thead>
                <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                  <th className="text-left py-2 pr-4">Offset (m)</th>
                  <th className="text-left py-2 pr-4">e Applied (%)</th>
                  <th className="text-left py-2">Progress</th>
                </tr>
              </thead>
              <tbody>
                {result.table.map((row, i) => (
                  <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="py-1.5 pr-4">{row.chainageOffset.toFixed(2)}</td>
                    <td className="py-1.5 pr-4">{row.eApplied.toFixed(2)}</td>
                    <td className="py-1.5">
                      <div className="w-24 h-2 bg-[var(--bg-secondary)] rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-orange-500 transition-all" 
                          style={{ width: `${(i / result.table.length) * 100}%` }}
                        />
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Visual Diagram - Simple SVG representation */}
      {result && (
        <div className="mt-4">
          <h4 className="font-semibold mb-2 text-sm">Transition Diagram</h4>
          <svg viewBox="0 0 400 120" className="w-full h-32 bg-[var(--bg-secondary)] rounded-lg">
            {/* Center line */}
            <line x1="20" y1="60" x2="380" y2="60" stroke="#444" strokeWidth="1" strokeDasharray="4 2" />
            
            {/* Normal crown (before transition) */}
            <line x1="20" y1="50" x2="60" y2="50" stroke="#666" strokeWidth="3" />
            
            {/* Transition curve */}
            <path 
              d={`M 60 50 Q ${60 + result.transitionLength * 0.5} 30 ${Math.min(60 + result.transitionLength, 380)} 30`}
              stroke="#e8a020"
              strokeWidth="3"
              fill="none"
            />
            
            {/* Full superelevation (after transition) */}
            <line 
              x1={Math.min(60 + result.transitionLength, 380)} 
              y1="30" 
              x2="380" 
              y2="30" 
              stroke="#e8a020" 
              strokeWidth="3" 
            />

            {/* Labels */}
            <text x="40" y="75" fill="#666" fontSize="10">Normal Crown</text>
            <text x="140" y="25" fill="#e8a020" fontSize="10">Transition</text>
            <text x="300" y="25" fill="#e8a020" fontSize="10">Full e = {result.eDesign}%</text>
          </svg>
        </div>
      )}

      {/* Formula Reference */}
      <div className="mt-4 p-3 bg-[var(--bg-secondary)] rounded-lg">
        <p className="text-xs text-[var(--text-muted)]">
          <strong>Reference:</strong> RDM 1.1 Equation 3.1 — e = V²/(225R) - 0.01
        </p>
        <p className="text-xs text-[var(--text-muted)] mt-1">
          <strong>KeRRA:</strong> Minimum transition L = 0.6V²/R (minimum 30m)
        </p>
      </div>
    </div>
  );
}

'use client'

import { useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import {
  type FeedbackCategory,
  buildFeedbackPayload,
  markFeedbackSubmitted,
  canSubmitFeedback,
  drainStoredErrors,
} from '@/lib/feedback/feedbackCollector'
import { ChangelogPanel } from '@/components/feedback/ChangelogPanel'

type Tab = 'feedback' | 'changelog'

/**
 * FeedbackWidget — floating button that opens a feedback form.
 *
 * AUDIT FIX (2026-07-05): Complete rewrite. Previously:
 *   - Used the deprecated createClient() which tried dbClient.from('feedback')
 *     but no feedback table existed → insert failed silently
 *   - Fallback was console.warn() — feedback was lost
 *   - Screenshot capture tried to import html2canvas (not installed) → always null
 *
 * Now:
 *   - POSTs to /api/feedback (real endpoint that saves to the feedback table)
 *   - Uses useSession() for the user ID (not the deprecated auth.getSession())
 *   - Sends error logs from sessionStorage as JSON
 *   - Screenshot capture removed (was always failing silently — html2canvas
 *     not installed and is too heavy to add). Users can still describe
 *     what they see in the message field.
 *   - Rate limited server-side: 5 submissions per 15 minutes per user
 */
export default function FeedbackWidget() {
  const { data: session } = useSession()
  const [isOpen, setIsOpen] = useState(false)
  const [tab, setTab] = useState<Tab>('feedback')
  const [type, setType] = useState<FeedbackCategory>('bug')
  const [message, setMessage] = useState('')
  const [email, setEmail] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const resetForm = useCallback(() => {
    setSubmitted(false)
    setMessage('')
    setEmail('')
    setError(null)
    setType('bug')
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!message.trim()) return
    if (!canSubmitFeedback()) {
      setError('Please wait 30 seconds before submitting again.')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const payload = buildFeedbackPayload(type, message, email || undefined)

      const res = await fetch('/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type,
          message,
          email: email || undefined,
          includeErrors: true,
          errors: payload.errorEntries,
        }),
      })

      if (!res.ok) {
        const data = (await res.json().catch(() => ({}))) as { error?: string }
        throw new Error(data.error || `Server returned ${res.status}`)
      }

      markFeedbackSubmitted()
      setSubmitted(true)
      setTimeout(() => {
        setIsOpen(false)
        resetForm()
      }, 2500)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to submit feedback')
    } finally {
      setLoading(false)
    }
  }

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        aria-label="Send feedback"
        // AUDIT FIX (2026-07-05): Repositioned to avoid overlap with
        // QuickCompute (bottom-20 md:bottom-6 right-4) and FieldModeToggle
        // (bottom-6 right-6). The feedback button now sits ABOVE QuickCompute
        // on both mobile and desktop:
        //   Mobile:  bottom-[168px] (above MobileNav 64px + QuickCompute 104px)
        //   Desktop: bottom-32      (above QuickCompute at bottom-6 + its height)
        className="fixed bottom-[168px] right-4 md:bottom-32 bg-[var(--accent)] text-black px-3 py-2 rounded-full shadow-lg text-xs font-semibold z-40 hover:bg-[var(--accent-dim)] transition-colors flex items-center gap-1.5"
      >
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" />
        </svg>
        Feedback
      </button>
    )
  }

  return (
    <div className="fixed bottom-[168px] right-4 left-4 sm:bottom-32 sm:left-auto bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl shadow-2xl w-[calc(100vw-2rem)] sm:w-[22rem] max-h-[70vh] z-50 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="bg-[var(--accent)] px-4 py-3 flex justify-between items-center flex-shrink-0">
        <h3 className="text-black font-bold text-sm">Feedback</h3>
        <div className="flex items-center gap-2">
          <div className="flex bg-black/10 rounded-md overflow-hidden">
            <button
              onClick={() => setTab('feedback')}
              className={`px-2.5 py-1 text-xs font-medium transition-colors ${
                tab === 'feedback' ? 'bg-black text-[var(--accent)]' : 'text-black/70 hover:text-black'
              }`}
            >
              Report
            </button>
            <button
              onClick={() => setTab('changelog')}
              className={`px-2.5 py-1 text-xs font-medium transition-colors ${
                tab === 'changelog' ? 'bg-black text-[var(--accent)]' : 'text-black/70 hover:text-black'
              }`}
            >
              What&apos;s New
            </button>
          </div>
          <button onClick={() => { setIsOpen(false); resetForm() }} className="text-black hover:text-black/60 ml-1" aria-label="Close feedback">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto min-h-0">
        {tab === 'changelog' ? (
          <ChangelogPanel />
        ) : submitted ? (
          <div className="text-center py-10 px-4">
            <div className="w-12 h-12 rounded-full bg-green-500/15 flex items-center justify-center mx-auto mb-3">
              <svg className="w-6 h-6 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
            </div>
            <p className="text-green-400 font-semibold mb-1">Thank you!</p>
            <p className="text-[var(--text-muted)] text-xs">Your feedback has been submitted and will help improve METARDU.</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-4 space-y-3">
            {/* Auth notice */}
            {!session?.user && (
              <p className="text-xs text-[var(--text-muted)] bg-[var(--bg-tertiary)] rounded-lg p-2">
                You need to be signed in to submit feedback.
              </p>
            )}

            {/* Type selector */}
            <div className="flex gap-1.5">
              {([
                { key: 'bug' as FeedbackCategory, label: 'Bug' },
                { key: 'feature' as FeedbackCategory, label: 'Feature' },
                { key: 'performance' as FeedbackCategory, label: 'Slow' },
                { key: 'general' as FeedbackCategory, label: 'Other' },
              ]).map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setType(key)}
                  className={`flex-1 py-3 rounded-lg text-[10px] font-medium transition-all ${
                    type === key
                      ? 'bg-[var(--accent)] text-black shadow-md shadow-[var(--accent)]/20'
                      : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:text-white hover:bg-[var(--border-color)]'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>

            {/* Message */}
            <div>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder={
                  type === 'bug'
                    ? 'What went wrong? Steps to reproduce...'
                    : type === 'feature'
                      ? 'What feature would you like?'
                      : type === 'performance'
                        ? 'What is slow? When does it happen?'
                        : 'How can we improve METARDU?'
                }
                rows={5}
                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm resize-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
                required
                minLength={10}
                maxLength={2000}
              />
              <p className="text-[10px] text-[var(--text-muted)] mt-1 text-right">
                {message.length}/2000
              </p>
            </div>

            {/* Email (optional) */}
            <div>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                aria-label="Email (optional — for follow-up)"

                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
              />
            </div>

            {/* Error notice */}
            {error && (
              <p className="text-xs text-red-400 bg-red-500/10 rounded-lg p-2">
                {error}
              </p>
            )}

            {/* Submit */}
            <button
              type="submit"
              disabled={loading || !message.trim() || !session?.user}
              className="w-full py-2.5 bg-[var(--accent)] text-black font-bold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm"
            >
              {loading ? 'Sending...' : 'Submit Feedback'}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

'use client';

/**
 * FieldConnectionBar — top bar showing instrument connection status
 *
 * Shows:
 *   - Connection status (disconnected/connecting/connected/streaming)
 *   - Instrument type (total station / GNSS rover)
 *   - Battery/signal strength (if available)
 *   - Fix quality (for GNSS: fixed/float/dgps/single)
 *   - Online/offline sync indicator
 *
 * Designed for field use: large text, high contrast, sunlight-readable.
 */

import { memo } from 'react'
import { Wifi, WifiOff, Bluetooth, Usb, Satellite, Battery, AlertCircle, CheckCircle, Loader2 } from 'lucide-react'
import { useInstrumentStore } from '@/stores/instrumentStore'

interface FieldConnectionBarProps {
  isOnline: boolean
  isSyncing: boolean
  pendingSyncCount: number
  onSyncClick?: () => void
}

export const FieldConnectionBar = memo(function FieldConnectionBar({
  isOnline,
  isSyncing,
  pendingSyncCount,
  onSyncClick,
}: FieldConnectionBarProps) {
  const { status, transport, device, instrumentInfo, latestPoint } = useInstrumentStore()

  const isConnected = status === 'connected' || status === 'streaming'
  const isStreaming = status === 'streaming'

  // Status colors
  const statusColor = !isConnected
    ? 'bg-[var(--error)]/10 text-[var(--error)] border-[var(--error)]/30'
    : isStreaming
      ? 'bg-[var(--success)]/10 text-[var(--success)] border-[var(--success)]/30'
      : 'bg-[var(--warning)]/10 text-[var(--warning)] border-[var(--warning)]/30'

  const TransportIcon = transport === 'web-bluetooth' ? Bluetooth : transport === 'web-serial' ? Usb : Satellite

  return (
    <div className="flex items-center gap-3 px-4 py-2.5 bg-[var(--bg-secondary)] border-b border-[var(--border-color)]">
      {/* Connection Status */}
      <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border ${statusColor}`}>
        {status === 'connecting' || status === 'reconnecting' ? (
          <Loader2 className="w-4 h-4 animate-spin" />
        ) : isConnected ? (
          <CheckCircle className="w-4 h-4" />
        ) : (
          <AlertCircle className="w-4 h-4" />
        )}
        <span className="text-sm font-medium">
          {!isConnected ? 'Disconnected' : isStreaming ? 'Streaming' : 'Connected'}
        </span>
      </div>

      {/* Transport + Device */}
      {isConnected && (
        <div className="flex items-center gap-1.5 text-sm text-[var(--text-secondary)]">
          <TransportIcon className="w-4 h-4 text-[var(--accent)]" />
          <span>{device?.name || instrumentInfo?.model || 'Instrument'}</span>
        </div>
      )}

      {/* GNSS Fix Quality */}
      {isConnected && latestPoint?.source === 'nmea' && (
        <div className="flex items-center gap-2 text-sm">
          <span className={`px-2 py-0.5 rounded font-mono text-xs ${
            (latestPoint.quality ?? 0) >= 4
              ? 'bg-[var(--success)]/20 text-[var(--success)]'
              : (latestPoint.quality ?? 0) >= 2
                ? 'bg-[var(--warning)]/20 text-[var(--warning)]'
                : 'bg-[var(--error)]/20 text-[var(--error)]'
          }`}>
            {(latestPoint.quality ?? 0) >= 4 ? 'FIXED' : (latestPoint.quality ?? 0) >= 2 ? 'FLOAT' : 'NO FIX'}
          </span>
          {latestPoint.satellites != null && (
            <span className="text-[var(--text-muted)] font-mono text-xs">
              🛰 {latestPoint.satellites}
            </span>
          )}
          {latestPoint.hdop != null && (
            <span className="text-[var(--text-muted)] font-mono text-xs">
              HDOP {latestPoint.hdop.toFixed(1)}
            </span>
          )}
        </div>
      )}

      {/* Spacer */}
      <div className="flex-1" />

      {/* Sync Status */}
      <button
        onClick={onSyncClick}
        disabled={!isOnline || isSyncing || pendingSyncCount === 0}
        className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        title={isOnline ? 'Sync now' : 'Offline — will sync when online'}
      >
        {isSyncing ? (
          <Loader2 className="w-3.5 h-3.5 animate-spin text-[var(--accent)]" />
        ) : isOnline ? (
          <Wifi className="w-3.5 h-3.5 text-[var(--success)]" />
        ) : (
          <WifiOff className="w-3.5 h-3.5 text-[var(--error)]" />
        )}
        <span className={isOnline ? 'text-[var(--text-secondary)]' : 'text-[var(--error)]'}>
          {isSyncing ? 'Syncing…' : isOnline ? 'Online' : 'Offline'}
        </span>
        {pendingSyncCount > 0 && (
          <span className="bg-[var(--accent)]/20 text-[var(--accent)] px-1.5 py-0.5 rounded-full text-[10px] font-mono font-bold">
            {pendingSyncCount}
          </span>
        )}
      </button>
    </div>
  )
})

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Instant Closure Feedback
// ──────────────────────────────────────────────────────────────────────────
// Shows real-time traverse closure as the surveyor types observations.
// No button press needed — updates on every keystroke.
//
// This is the #1 feature that saves surveyors time:
//   - Surveyor enters FL/FR angles + slope distance
//   - Closure updates instantly
//   - If it doesn't close, they know BEFORE leaving the site
//   - Saves a 6-hour round trip back to the field
// ──────────────────────────────────────────────────────────────────────────

'use client';

import { useMemo } from 'react';
import { instantClosureCheck, type ClosureFeedback } from '@/lib/survey/field-to-finish';
import { CheckCircle2, XCircle, AlertTriangle, Gauge, Ruler, TrendingUp } from 'lucide-react';

interface InstantClosureFeedbackProps {
  /** Current traverse rows from the field book */
  rows: Array<{
    bearing: string;      // DMS string like "045°30'15.0" or decimal
    slopeDist: string;    // Distance in metres
  }>;
  /** Start station coordinates */
  startE: string;
  startN: string;
  /** Close station coordinates (for link traverse) */
  closeE?: string;
  closeN?: string;
  /** Traverse mode */
  mode: 'open' | 'closed' | 'link';
  /** Survey type for precision standard */
  surveyType?: string;
  /** Translator function */
  t?: (key: string) => string;
}

export function InstantClosureFeedback({
  rows,
  startE,
  startN,
  closeE,
  closeN,
  mode,
  surveyType = 'cadastral',
  t,
}: InstantClosureFeedbackProps) {
  const feedback = useMemo((): ClosureFeedback | null => {
    // Parse observations
    const observations: Array<{ bearing: number; slopeDistance: number }> = [];

    for (const row of rows) {
      const bearing = parseBearing(row.bearing);
      const distance = parseFloat(row.slopeDist);

      if (isNaN(bearing) || isNaN(distance) || distance <= 0) continue;

      observations.push({ bearing, slopeDistance: distance });
    }

    if (observations.length < 2) return null;

    const start = {
      easting: parseFloat(startE) || 0,
      northing: parseFloat(startN) || 0,
    };

    const close = (mode === 'link' && closeE && closeN)
      ? { easting: parseFloat(closeE) || 0, northing: parseFloat(closeN) || 0 }
      : undefined;

    return instantClosureCheck(observations, start, close);
  }, [rows, startE, startN, closeE, closeN, mode]);

  if (mode === 'open') {
    return (
      <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-orange-500/10 border border-orange-500/30 text-orange-400 text-sm">
        <AlertTriangle className="w-4 h-4 shrink-0" />
        <span>Open traverse — no closure check. Use closed or link mode for cadastral work.</span>
      </div>
    );
  }

  if (!feedback) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 text-muted-foreground text-sm">
        <Gauge className="w-4 h-4 shrink-0" />
        <span>Enter at least 2 observations to see closure feedback</span>
      </div>
    );
  }

  const gradeColors = {
    excellent: { bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', text: 'text-emerald-400', icon: CheckCircle2 },
    good: { bg: 'bg-green-500/10', border: 'border-green-500/30', text: 'text-green-400', icon: CheckCircle2 },
    acceptable: { bg: 'bg-yellow-500/10', border: 'border-yellow-500/30', text: 'text-yellow-400', icon: AlertTriangle },
    poor: { bg: 'bg-orange-500/10', border: 'border-orange-500/30', text: 'text-orange-400', icon: AlertTriangle },
    unacceptable: { bg: 'bg-red-500/10', border: 'border-red-500/30', text: 'text-red-400', icon: XCircle },
  };

  const grade = gradeColors[feedback.grade] || gradeColors.unacceptable;
  const GradeIcon = grade.icon;

  return (
    <div className={`rounded-lg border ${grade.border} ${grade.bg} p-3 space-y-2`}>
      {/* Header: Grade + Ratio */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <GradeIcon className={`w-5 h-5 ${grade.text}`} />
          <span className={`font-semibold text-sm ${grade.text}`}>
            {feedback.passes ? 'PASSES' : 'FAILS'} — {surveyType}
          </span>
        </div>
        <div className={`font-mono text-lg font-bold ${grade.text}`}>
          {feedback.precisionFormatted}
        </div>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-4 gap-2 text-xs">
        <div className="flex items-center gap-1">
          <Ruler className="w-3 h-3 text-muted-foreground" />
          <div>
            <div className="text-muted-foreground">Misclosure</div>
            <div className="font-mono font-medium">{feedback.linearMisclosure.toFixed(4)} m</div>
          </div>
        </div>
        <div className="flex items-center gap-1">
          <TrendingUp className="w-3 h-3 text-muted-foreground" />
          <div>
            <div className="text-muted-foreground">Perimeter</div>
            <div className="font-mono font-medium">{feedback.perimeter.toFixed(1)} m</div>
          </div>
        </div>
        <div>
          <div className="text-muted-foreground">ΔE</div>
          <div className="font-mono font-medium">{feedback.closingErrorE.toFixed(4)} m</div>
        </div>
        <div>
          <div className="text-muted-foreground">ΔN</div>
          <div className="font-mono font-medium">{feedback.closingErrorN.toFixed(4)} m</div>
        </div>
      </div>

      {/* Message */}
      <div className={`text-xs ${grade.text} opacity-80`}>
        {feedback.message}
      </div>

      {/* Standard reference */}
      <div className="text-[10px] text-muted-foreground">
        Standard: {feedback.standard} · Kenya Survey Regulations 1994, Regulation 97
      </div>
    </div>
  );
}

// ─── Bearing Parser ──────────────────────────────────────────────────────

/**
 * Parse a bearing string that could be:
 *   - DMS: "045°30'15.0" or "045°30'15.0""
 *   - Decimal: "45.504"
 *   - With spaces: "45 30 15"
 */
function parseBearing(str: string): number {
  if (!str || str.trim() === '') return NaN;

  const cleaned = str.trim();

  // Try DMS format: 045°30'15.0"
  const dmsMatch = cleaned.match(/(\d+)[°\s]+(\d+)['\s]+([\d.]+)/);
  if (dmsMatch) {
    const d = parseInt(dmsMatch[1], 10);
    const m = parseInt(dmsMatch[2], 10);
    const s = parseFloat(dmsMatch[3]);
    return d + m / 60 + s / 3600;
  }

  // Try decimal
  const decimal = parseFloat(cleaned);
  if (!isNaN(decimal)) return decimal;

  return NaN;
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Auto Weather Panel for EDM Corrections
// ──────────────────────────────────────────────────────────────────────────
// Auto-fetches temperature, pressure, and humidity for the survey site.
// Shows current conditions and lets the surveyor override if needed.
// ──────────────────────────────────────────────────────────────────────────

'use client';

import { useState, useEffect, useCallback } from 'react';
import { CloudSun, Thermometer, Gauge, Droplets, RefreshCw, MapPin, Loader2 } from 'lucide-react';

interface WeatherData {
  temperature: number;
  pressure: number;
  humidity: number;
  source: string;
  fetchedAt: string;
}

interface WeatherPanelProps {
  /** GPS latitude (if available from device) */
  lat?: number;
  /** GPS longitude */
  lon?: number;
  /** Site elevation in metres */
  elevation?: number;
  /** Callback when weather data is available */
  onWeatherChange?: (data: { temperature: number; pressure: number; humidity: number }) => void;
  /** Translator */
  t?: (key: string) => string;
}

export function WeatherPanel({ lat, lon, elevation, onWeatherChange, t }: WeatherPanelProps) {
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [manualTemp, setManualTemp] = useState('24');
  const [manualPressure, setManualPressure] = useState('1013');
  const [manualHumidity, setManualHumidity] = useState('60');

  const fetchWeather = useCallback(async () => {
    if (!lat || !lon) return;
    setLoading(true);
    try {
      const res = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat.toFixed(4)}&longitude=${lon.toFixed(4)}&current=temperature_2m,relative_humidity_2m,surface_pressure&timezone=Africa/Nairobi`);
      const json = (await res.json()) as { current?: { temperature_2m?: number; surface_pressure?: number; relative_humidity_2m?: number } };
      const current = json.current;
      if (current) {
        const data: WeatherData = {
          temperature: current.temperature_2m ?? 24,
          pressure: current.surface_pressure ?? 1013,
          humidity: current.relative_humidity_2m ?? 60,
          source: 'open-meteo',
          fetchedAt: new Date().toISOString(),
        };
        setWeather(data);
        onWeatherChange?.(data);
      }
    } catch {
      // Fallback to defaults
      const defaults = { temperature: 24, pressure: 1013, humidity: 60, source: 'fallback', fetchedAt: new Date().toISOString() };
      setWeather(defaults);
      onWeatherChange?.(defaults);
    } finally {
      setLoading(false);
    }
  }, [lat, lon, onWeatherChange]);

  // Auto-fetch on mount if GPS coordinates available
  useEffect(() => {
    if (lat !== undefined && lon !== undefined) {
      fetchWeather();
    } else {
      // Use Kenya defaults
      const defaults = {
        temperature: elevation ? 30 - 0.0065 * elevation : 24,
        pressure: elevation ? 1013.25 * Math.pow(1 - 0.0000225577 * elevation, 5.25588) : 1013.25,
        humidity: 60,
        source: elevation ? 'elevation-estimated' : 'kenya-default',
        fetchedAt: new Date().toISOString(),
      };
      setWeather(defaults);
      onWeatherChange?.(defaults);
    }
  }, [lat, lon, elevation, fetchWeather, onWeatherChange]);

  // Notify parent when manual values change
  useEffect(() => {
    if (manualMode) {
      onWeatherChange?.({
        temperature: parseFloat(manualTemp) || 24,
        pressure: parseFloat(manualPressure) || 1013,
        humidity: parseFloat(manualHumidity) || 60,
      });
    }
  }, [manualMode, manualTemp, manualPressure, manualHumidity, onWeatherChange]);

  const activeData = manualMode
    ? { temperature: parseFloat(manualTemp) || 24, pressure: parseFloat(manualPressure) || 1013, humidity: parseFloat(manualHumidity) || 60 }
    : weather || { temperature: 24, pressure: 1013, humidity: 60 };

  return (
    <div className="border border-[var(--border-color)] rounded-lg overflow-hidden">
      <button
        onClick={() => setManualMode(!manualMode)}
        className="w-full flex items-center justify-between px-3 py-2 bg-[var(--bg-primary)]/40 text-sm font-medium hover:bg-[var(--border-color)]/30 transition-colors"
      >
        <div className="flex items-center gap-2">
          <CloudSun className="w-4 h-4 text-blue-400" />
          <span>Atmospheric Conditions</span>
          <span className="text-xs text-[var(--text-muted)] font-normal">
            ({weather?.source === 'open-meteo' ? 'Live' : weather?.source === 'elevation-estimated' ? 'Estimated' : 'Default'})
          </span>
        </div>
        <span className="text-xs text-[var(--text-muted)]">{manualMode ? 'Manual' : 'Auto'}</span>
      </button>

      <div className="p-3 space-y-2">
        <div className="grid grid-cols-3 gap-2 text-xs">
          <div className="flex items-center gap-1.5">
            <Thermometer className="w-3 h-3 text-orange-400" />
            <div>
              <div className="text-[var(--text-muted)]">Temp</div>
              {manualMode ? (
                <input
                  type="number"
                  step="0.1"
                  value={manualTemp}
                  onChange={(e) => setManualTemp(e.target.value)}
                  className="input input-sm font-mono w-16 text-xs"
                  aria-label="Temperature °C"
                />
              ) : (
                <div className="font-mono font-medium">{activeData.temperature.toFixed(1)}°C</div>
              )}
            </div>
          </div>

          <div className="flex items-center gap-1.5">
            <Gauge className="w-3 h-3 text-blue-400" />
            <div>
              <div className="text-[var(--text-muted)]">Pressure</div>
              {manualMode ? (
                <input
                  type="number"
                  step="0.1"
                  value={manualPressure}
                  onChange={(e) => setManualPressure(e.target.value)}
                  className="input input-sm font-mono w-16 text-xs"
                  aria-label="Pressure hPa"
                />
              ) : (
                <div className="font-mono font-medium">{activeData.pressure.toFixed(1)} hPa</div>
              )}
            </div>
          </div>

          <div className="flex items-center gap-1.5">
            <Droplets className="w-3 h-3 text-cyan-400" />
            <div>
              <div className="text-[var(--text-muted)]">Humidity</div>
              {manualMode ? (
                <input
                  type="number"
                  step="1"
                  value={manualHumidity}
                  onChange={(e) => setManualHumidity(e.target.value)}
                  className="input input-sm font-mono w-16 text-xs"
                  aria-label="Humidity %"
                />
              ) : (
                <div className="font-mono font-medium">{activeData.humidity.toFixed(0)}%</div>
              )}
            </div>
          </div>
        </div>

        {/* GPS + Refresh */}
        <div className="flex items-center justify-between text-[10px] text-[var(--text-muted)]">
          {lat !== undefined && lon !== undefined ? (
            <div className="flex items-center gap-1">
              <MapPin className="w-3 h-3" />
              <span>{lat.toFixed(4)}, {lon.toFixed(4)}</span>
            </div>
          ) : (
            <span>No GPS — using {elevation ? 'elevation estimate' : 'Kenya defaults'}</span>
          )}
          {lat !== undefined && (
            <button
              onClick={fetchWeather}
              disabled={loading}
              className="flex items-center gap-1 hover:text-[var(--text-secondary)] transition-colors"
            >
              {loading ? <Loader2 className="w-3 h-3 animate-spin" /> : <RefreshCw className="w-3 h-3" />}
              Refresh
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { getSupportedCRS, CoordSystem } from '@/lib/geo/transform';

interface Point { id: string; x: string; y: string; z: string; }

export default function CoordinateTransformer({ projectId }: { projectId?: string }) {
  const [fromCRS, setFromCRS] = useState<CoordSystem>('Arc1960-UTM37S');
  const [toCRS, setToCRS] = useState<CoordSystem>('WGS84');
  const [rows, setRows] = useState<Point[]>([{ id: '1', x: '', y: '', z: '' }]);
  const [results, setResults] = useState<Array<{ id: string; x: number; y: number; z?: number; warning?: string }>>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const crsList = getSupportedCRS();

  const addRow = () => setRows((r) => [...r, { id: String(r.length + 1), x: '', y: '', z: '' }]);

  const updateRow = (idx: number, field: keyof Point, value: string) =>
    setRows((r) => r.map((row, i) => i === idx ? { ...row, [field]: value } : row));

  const handleTransform = async () => {
    setLoading(true);
    setError(null);
    try {
      const points = rows
        .filter((r) => r.x && r.y)
        .map((r) => ({ id: r.id, x: parseFloat(r.x), y: parseFloat(r.y), z: r.z ? parseFloat(r.z) : undefined }));

      const res = await fetch('/api/geo/transform', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ points, fromCRS, toCRS, projectId }),
      });
      const data = (await res.json()) as { error?: string; points: Array<{ id: string; x: number; y: number; z?: number; warning?: string }> };
      if (!res.ok) throw new Error(data.error);
      setResults(data.points);
    } catch (err: unknown) {
      setError(err instanceof Error ? (err as Error).message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4 max-w-3xl">
      <h2 className="text-lg font-semibold text-gray-800">Coordinate Transform</h2>

      <div className="flex gap-4">
        <div className="flex-1">
          <label className="text-xs text-gray-500 mb-1 block" htmlFor="from">From</label>
          <select id="from" value={fromCRS} onChange={(e) => setFromCRS(e.target.value as CoordSystem)}
            className="w-full border rounded px-3 py-2 text-sm">
            {crsList.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="flex-1">
          <label className="text-xs text-gray-500 mb-1 block" htmlFor="to">To</label>
          <select  id="to" value={toCRS} onChange={(e) => setToCRS(e.target.value as CoordSystem)}
            className="w-full border rounded px-3 py-2 text-sm">
            {crsList.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      <div className="overflow-x-auto">
      <table className="w-full text-sm border-collapse min-w-[400px]">
        <thead>
          <tr className="bg-gray-50">
            <th className="border px-2 py-1 text-left">Point</th>
            <th className="border px-2 py-1 text-left">X / Easting</th>
            <th className="border px-2 py-1 text-left">Y / Northing</th>
            <th className="border px-2 py-1 text-left">Z / RL (opt)</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, idx) => (
            <tr key={`row-${row.id}-${idx}`}>
              <td className="border px-1"><input aria-label="Id" value={row.id} onChange={(e) => updateRow(idx, 'id', e.target.value)} className="w-full outline-none px-1" /></td>
              <td className="border px-1"><input value={row.x} onChange={(e) => updateRow(idx, 'x', e.target.value)} className="w-full outline-none px-1" aria-label="X coordinate" placeholder="0.000" /></td>
              <td className="border px-1"><input value={row.y} onChange={(e) => updateRow(idx, 'y', e.target.value)} className="w-full outline-none px-1" aria-label="Y coordinate" placeholder="0.000" /></td>
              <td className="border px-1"><input value={row.z} onChange={(e) => updateRow(idx, 'z', e.target.value)} className="w-full outline-none px-1" aria-label="Z coordinate (optional)" placeholder="optional" /></td>
            </tr>
          ))}
        </tbody>
      </table>
      </div>

      <div className="flex gap-2">
        <button onClick={addRow} className="px-3 py-1.5 text-sm bg-gray-100 rounded hover:bg-gray-200">+ Add Row</button>
        <button onClick={handleTransform} disabled={loading}
          className="px-4 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50">
          {loading ? 'Transforming…' : 'Transform'}
        </button>
      </div>

      {error && <p className="text-red-500 text-sm">{error}</p>}

      {results.length > 0 && (
        <div className="mt-4">
          <h3 className="text-sm font-medium text-gray-700 mb-2">Results — {toCRS}</h3>
          <div className="overflow-x-auto">
      <table className="w-full text-sm border-collapse min-w-[400px]">
            <thead>
              <tr className="bg-gray-50">
                <th className="border px-2 py-1 text-left">Point</th>
                <th className="border px-2 py-1 text-left">X</th>
                <th className="border px-2 py-1 text-left">Y</th>
                <th className="border px-2 py-1 text-left">Z</th>
              </tr>
            </thead>
            <tbody>
              {results.map((r, i) => (
                <tr key={r.id} className={r.warning ? 'bg-yellow-50' : ''}>
                  <td className="border px-2 py-1">{r.id}</td>
                  <td className="border px-2 py-1">{r.x}</td>
                  <td className="border px-2 py-1">{r.y}</td>
                  <td className="border px-2 py-1">{r.z ?? '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          </div>
        </div>
      )}
    </div>
  );
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useSession } from 'next-auth/react'
import {
  FolderKanban, Wrench, Compass, FileText,
  LayoutDashboard, Users, ShieldCheck, CreditCard,
  Settings2, Activity, ChevronLeft, BarChart3,
  Map, Building2, HelpCircle, LayoutTemplate, Boxes,
  RoadIcon, Mountain, Sparkles,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { OutdoorModeToggle } from '@/components/shared/OutdoorModeToggle'
import MetarduLogo from '@/components/MetarduLogo'

// ---------------------------------------------------------------------------
// Navigation items by role
// ---------------------------------------------------------------------------

interface NavItem {
  href: string
  label: string
  icon: React.ComponentType<{ className?: string }>
  exact?: boolean
  hash?: string
}

const userNavItems: NavItem[] = [
  { href: '/dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { href: '/cadastral-workflow', label: 'Cadastral', icon: Compass },
  { href: '/engineering-workflow', label: 'Engineering', icon: RoadIcon },
  { href: '/topographic-workflow', label: 'Topographic', icon: Mountain },
  { href: '/projects', label: 'Projects', icon: FolderKanban },
  { href: '/process', label: 'Corrections', icon: Wrench },
  { href: '/tools/all', label: 'Toolbox', icon: Boxes },
  { href: '/tools/cogo', label: 'COGO', icon: Compass },
  { href: '/map', label: 'Map', icon: Map },
  { href: '/documents', label: 'Documents', icon: FileText },
  { href: '/report-templates', label: 'Templates', icon: LayoutTemplate },
  { href: '/sectional', label: 'Sectional', icon: Building2 },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
  { href: '/assistant', label: 'Assistant', icon: Sparkles },
  { href: '/help', label: 'Help', icon: HelpCircle },
]

const adminNavItems: NavItem[] = [
  { href: '/admin', label: 'Dashboard', icon: LayoutDashboard, exact: true },
  { href: '/admin/users', label: 'Users', icon: Users },
  { href: '/admin/payments', label: 'Payments', icon: CreditCard },
  { href: '/audit-logs', label: 'Audit Logs', icon: ShieldCheck },
  { href: '/admin', label: 'System Health', icon: Settings2, hash: '#system' },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
]

// ---------------------------------------------------------------------------
// Sidebar component
// ---------------------------------------------------------------------------

interface AppSidebarProps {
  variant: 'user' | 'admin'
  className?: string
  onNavigate?: () => void
}

export default function AppSidebar({ variant, className, onNavigate }: AppSidebarProps) {
  const pathname = usePathname()
  const { data: session } = useSession()

  const navItems = variant === 'admin' ? adminNavItems : userNavItems
  const userRole = (session?.user as { role?: string })?.role ?? ''

  return (
    <aside
      className={cn(
        'h-full flex flex-col bg-[var(--bg-secondary)] border-r border-[var(--border-color)]',
        className,
      )}
    >
      {/* Logo */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-[var(--border-color)]">
        <Link
          href="/"
          onClick={onNavigate}
          className="flex items-center gap-2 no-underline"
        >
          <MetarduLogo size={28} showWordmark={true} color="var(--text-primary)" />
        </Link>
      </div>

      {/* Navigation */}
      <nav className="flex-1 p-3 space-y-0.5 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = item.exact
            ? pathname === item.href
            : item.hash
              ? pathname === item.href && typeof window !== 'undefined' && window.location.hash === item.hash
              : pathname.startsWith(item.href)

          const href = item.hash ? `${item.href}${item.hash}` : item.href

          return (
            <Link
              key={`${item.href}${item.hash ?? ''}`}
              href={href}
              onClick={onNavigate}
              className={cn(
                'flex items-center gap-3 px-3 py-2 rounded-md text-sm transition-colors no-underline',
                isActive
                  ? 'bg-[var(--accent)] text-[var(--bg-primary)] font-medium'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)]',
              )}
            >
              <item.icon className="w-4 h-4 shrink-0" />
              {item.label}
            </Link>
          )
        })}
      </nav>

      {/* Footer */}
      <div className="p-3 border-t border-[var(--border-color)] space-y-1">
        {/* Outdoor mode toggle */}
        <div className="flex items-center justify-between px-3 py-1.5">
          <span className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
            Outdoor Mode
          </span>
          <OutdoorModeToggle />
        </div>
        {/* Role badge */}
        <div className="px-3 py-1.5">
          <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
            {variant === 'admin' ? 'Admin Panel' : 'Kenya Cadastral'}
          </p>
          <p className="text-xs text-[var(--text-secondary)] capitalize">{userRole || 'Surveyor'}</p>
        </div>

        {/* Switch between admin/user dashboards */}
        {variant === 'admin' ? (
          <Link
            href="/dashboard"
            onClick={onNavigate}
            className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors no-underline"
          >
            <ChevronLeft className="w-4 h-4" />
            Back to App
          </Link>
        ) : (
          (userRole === 'super_admin' || userRole === 'admin' || userRole === 'org_admin') && (
            <Link
              href="/admin"
              onClick={onNavigate}
              className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-[var(--accent)] hover:bg-[var(--accent)]/5 transition-colors no-underline"
            >
              <ShieldCheck className="w-4 h-4" />
              Admin Panel
            </Link>
          )
        )}
      </div>
    </aside>
  )
}

'use client';

import { useState } from 'react'
import { computeLevelBook } from '@/lib/computations/traverseEngine'
import { printLevelBookSheet, type LevelBookPrintInput } from '@/lib/print/levelBookPrint'
import { PrintMetaPanel, defaultPrintMeta, type PrintMeta } from '@/components/shared/PrintMetaPanel'

interface LevelBookProps {
  projectId?: string
}

export default function LevelBook({ projectId }: LevelBookProps) {
  const [rows, setRows] = useState<Array<{
    station: string; bs: string; is: string; fs: string; distance: string; remarks: string
  }>>([
    { station: 'BM1', bs: '1.523', is: '', fs: '', distance: '', remarks: 'Benchmark' },
    { station: '1',   bs: '',      is: '', fs: '1.234', distance: '', remarks: '' },
    { station: '2',   bs: '',      is: '1.456', fs: '', distance: '', remarks: 'IS' },
    { station: '3',   bs: '',      is: '', fs: '1.789', distance: '', remarks: '' },
    { station: '4',   bs: '',      is: '1.234', fs: '', distance: '', remarks: 'IS' },
    { station: '5',   bs: '',      is: '', fs: '1.567', distance: '', remarks: '' },
  ])
  const [openingRL,   setOpeningRL]   = useState('100.000')
  const [closingRL,   setClosingRL]   = useState('')
  const [distanceKm,  setDistanceKm]  = useState('0.5')
  const [method,      setMethod]      = useState<'rise_and_fall' | 'height_of_collimation'>('rise_and_fall')
  const [result,      setResult]      = useState<ReturnType<typeof computeLevelBook> | null>(null)
  const [error,       setError]       = useState('')
  const [activeTab,   setActiveTab]   = useState<'input' | 'compute' | 'print'>('input')
  const [printMeta,   setPrintMeta]   = useState<PrintMeta>(defaultPrintMeta)

  const addRow = () => setRows(prev => [
    ...prev,
    { station: String(prev.length + 1), bs: '', is: '', fs: '', distance: '', remarks: '' }
  ])

  const removeRow = (i: number) => setRows(prev => prev.filter((_, idx) => idx !== i))

  const updateRow = (i: number, field: string, value: string) =>
    setRows(prev => prev.map((r, idx) => idx === i ? { ...r, [field]: value } : r))

  const handleCompute = () => {
    setError('')
    if (!openingRL) { setError('Enter opening benchmark RL'); return }
    const obsRows = rows.map(r => ({
      station:  r.station,
      bs:       r.bs       ? parseFloat(r.bs)       : undefined,
      is:       r.is       ? parseFloat(r.is)        : undefined,
      fs:       r.fs       ? parseFloat(r.fs)        : undefined,
      distance: r.distance ? parseFloat(r.distance)  : undefined,
      remarks:  r.remarks,
    }))
    try {
      const res = computeLevelBook({
        openingRL:  parseFloat(openingRL),
        closingRL:  closingRL ? parseFloat(closingRL) : undefined,
        distanceKm: parseFloat(distanceKm) || 0.5,
        method,
        rows: obsRows,
      })
      setResult(res)
      setActiveTab('compute')
    } catch (err: unknown) {
      setError((err as Error).message || 'Computation failed')
    }
  }

  const handlePrint = () => {
    if (!result) return
    const inp: LevelBookPrintInput = {
      result,
      meta: { ...printMeta, title: `Level Book — ${method === 'rise_and_fall' ? 'Rise & Fall' : 'Height of Collimation'}` }
    }
    printLevelBookSheet(inp)
  }

  // ── RENDER ─────────────────────────────────────────────────────────────────
  return (
    <div className="space-y-4">

      {/* Tabs + Method switch */}
      <div className="flex items-center gap-2 border-b border-[var(--border-color)] pb-2 flex-wrap">
        {(['input', 'compute', 'print'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)}
            className={`px-3 py-1.5 rounded text-sm font-medium capitalize transition-colors ${
              activeTab === tab
                ? 'bg-[var(--accent)] text-black'
                : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:bg-[var(--border-hover)]'
            }`}>
            {tab === 'input' ? 'Field Book' : tab === 'compute' ? 'Results' : 'Print'}
          </button>
        ))}
        <div className="flex-1" />
        <button
          onClick={() => { setMethod('rise_and_fall'); setResult(null) }}
          className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
            method === 'rise_and_fall'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
          }`}>
          Rise &amp; Fall
        </button>
        <button
          onClick={() => { setMethod('height_of_collimation'); setResult(null) }}
          className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
            method === 'height_of_collimation'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
          }`}>
          Height of Collimation
        </button>
      </div>

      {error && (
        <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{error}</div>
      )}

      {/* ── INPUT TAB ──────────────────────────────────────────────────────── */}
      {activeTab === 'input' && (
        <div className="space-y-4">
          {/* Setup fields */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-3 md:p-4 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)]">
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="opening-bm-rl-m">Opening BM RL (m)</label>
              <input id="opening-bm-rl-m" aria-label="Opening BM RL (m)" value={openingRL} onChange={e => setOpeningRL(e.target.value)}
                type="number" step="0.001"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="closing-bm-rl-m">Closing BM RL (m)</label>
              <input id="closing-bm-rl-m" value={closingRL} onChange={e => setClosingRL(e.target.value)}
                type="number" step="0.001" placeholder="Optional"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="total-distance-km">Total Distance (km)</label>
              <input  id="total-distance-km" aria-label="Total Distance (km)" value={distanceKm} onChange={e => setDistanceKm(e.target.value)}
                type="number" step="0.001"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
          </div>

          {/* Field book table */}
          <div className="overflow-x-auto -mx-4 px-4 sm:mx-0 sm:px-0">
            <table className="min-w-[700px] w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                  <th className="px-1.5 py-2 text-left text-[var(--text-muted)] w-8">#</th>
                  <th className="px-1.5 py-2 text-left text-[var(--text-secondary)]">Station</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">BS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">IS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">FS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">Dist (m)</th>
                  <th className="px-1.5 py-2 text-left text-[var(--text-secondary)]">Remarks</th>
                  <th className="w-6"></th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, i) => (
                  <tr key={row.station} className="border-b border-[var(--border-color)]/30">
                    <td className="px-1.5 py-1 text-[var(--text-muted)]">{i + 1}</td>
                    <td className="px-1 py-1">
                      <input value={row.station} onChange={e => updateRow(i, 'station', e.target.value)}
                        aria-label="Station" placeholder="BM1"
                        className="w-full px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.bs} onChange={e => updateRow(i, 'bs', e.target.value)}
                        type="number" step="0.001" aria-label="Backsight (m)" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.is} onChange={e => updateRow(i, 'is', e.target.value)}
                        type="number" step="0.001" aria-label="Intermediate sight (m)" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.fs} onChange={e => updateRow(i, 'fs', e.target.value)}
                        type="number" step="0.001" aria-label="Foresight (m)" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.distance} onChange={e => updateRow(i, 'distance', e.target.value)}
                        type="number" step="0.01" aria-label="Distance (m)" placeholder="0.00"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.remarks} onChange={e => updateRow(i, 'remarks', e.target.value)}
                        aria-label="Remarks" placeholder="IS / BM / CP"
                        className="w-full px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td>
                      <button onClick={() => removeRow(i)}
                        className="text-red-400 hover:text-red-300 text-lg leading-none px-1">×</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <button onClick={addRow}
            className="px-3 py-1.5 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-xs">
            + Add Row
          </button>

          <div className="flex justify-end">
            <button onClick={handleCompute}
              className="px-6 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded text-sm">
              Compute Level Book →
            </button>
          </div>
        </div>
      )}

      {/* ── RESULTS TAB ────────────────────────────────────────────────────── */}
      {activeTab === 'compute' && result && (
        <div className="space-y-4">

          {/* Closure summary cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
              <p className="text-xs text-[var(--text-secondary)]">ΣBS</p>
              <p className="text-lg font-mono">{result.sumBS.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
              <p className="text-xs text-[var(--text-secondary)]">ΣFS</p>
              <p className="text-lg font-mono">{result.sumFS.toFixed(3)} m</p>
            </div>
            <div className={`rounded p-3 ${result.arithmeticPass ? 'bg-green-900/30' : 'bg-red-900/30'}`}>
              <p className="text-xs text-[var(--text-secondary)]">Arithmetic Check</p>
              <p className={`text-lg font-semibold ${result.arithmeticPass ? 'text-green-400' : 'text-red-400'}`}>
                {result.arithmeticPass ? 'PASS' : 'FAIL'}
              </p>
            </div>
            <div className={`rounded p-3 ${result.isAcceptable ? 'bg-green-900/30' : 'bg-red-900/30'}`}>
              <p className="text-xs text-[var(--text-secondary)]">Closure (10√K mm)</p>
              <p className={`text-lg font-semibold ${result.isAcceptable ? 'text-green-400' : 'text-red-400'}`}>
                {result.isAcceptable ? 'OK' : 'FAIL'}
              </p>
            </div>
          </div>

          <p className="text-xs text-[var(--text-muted)] font-mono">{result.formula}</p>

          {/* Results table — HPC not HI */}
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/50">
                  <th className="px-2 py-2 text-left">Station</th>
                  <th className="px-2 py-2 text-right">BS</th>
                  <th className="px-2 py-2 text-right">IS</th>
                  <th className="px-2 py-2 text-right">FS</th>
                  {/* HPC = Height of Plane of Collimation — British/East African convention */}
                  <th className="px-2 py-2 text-right">HPC (m)</th>
                  {method === 'rise_and_fall' && <th className="px-2 py-2 text-right">Rise</th>}
                  {method === 'rise_and_fall' && <th className="px-2 py-2 text-right">Fall</th>}
                  <th className="px-2 py-2 text-right">RL (m)</th>
                </tr>
              </thead>
              <tbody>
                {result.rows.map((row, i) => (
                  <tr key={`item-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="px-2 py-1.5 font-mono">{row.station}</td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.bs !== undefined ? row.bs.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.is !== undefined ? row.is.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.fs !== undefined ? row.fs.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {/* row.hi is the data property (Height of Collimation value); displayed as HPC */}
                      {row.hi !== undefined ? row.hi.toFixed(3) : ''}
                    </td>
                    {method === 'rise_and_fall' && (
                      <td className="px-2 py-1.5 text-right font-mono text-green-400">
                        {row.rise !== undefined ? row.rise.toFixed(3) : ''}
                      </td>
                    )}
                    {method === 'rise_and_fall' && (
                      <td className="px-2 py-1.5 text-right font-mono text-red-400">
                        {row.fall !== undefined ? row.fall.toFixed(3) : ''}
                      </td>
                    )}
                    <td className="px-2 py-1.5 text-right font-mono font-bold text-[var(--accent)]">
                      {row.rl !== undefined ? row.rl.toFixed(3) : ''}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex justify-between">
            <button onClick={() => setActiveTab('input')}
              className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm">
              ← Back to Input
            </button>
            <button onClick={() => setActiveTab('print')}
              className="px-5 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded text-sm">
              Print Sheet →
            </button>
          </div>
        </div>
      )}

      {/* ── PRINT TAB ──────────────────────────────────────────────────────── */}
      {activeTab === 'print' && (
        <div className="space-y-4">
          {!result && (
            <div className="p-4 bg-amber-900/20 border border-amber-700 rounded text-amber-300 text-sm">
              Compute the level book first (Field Book tab) before printing.
            </div>
          )}

          <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />

          <div className="p-4 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)] text-sm space-y-1.5">
            <p className="font-semibold text-[var(--text-primary)]">The printed sheet will include:</p>
            <ul className="text-[var(--text-muted)] text-xs space-y-0.5 list-disc list-inside">
              <li>Standard 6-field document header (project · client · date · surveyor · reg/ISK · instrument)</li>
              <li>Table 1 — Field Observations (Station, BS, IS, FS, HPC, Rise, Fall, RL, Dist, Remarks)</li>
              <li>Table 2 — Arithmetic Checks &amp; Closure (ΣBS, ΣFS, ΣRise, ΣFall, 10√K misclosure)</li>
              <li>Surveyor&apos;s Certificate block — Survey Regulations 1994, Regulation 3(2)</li>
            </ul>
            <p className="text-xs text-[var(--text-muted)] font-mono mt-2">
              HPC = Height of Plane of Collimation (British/East African convention)
            </p>
          </div>

          <button
            onClick={handlePrint}
            disabled={!result}
            className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed text-black font-bold rounded text-sm">
            Print Level Book Computation Sheet
          </button>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Ruler, Square, Compass, MapPin, X, Check } from 'lucide-react';
import { useMeasurement, type MeasurementMode } from '@/hooks/useMeasurement';
import type Map from 'ol/Map';

interface MeasurementToolProps {
  map: Map | null;
}

export function MeasurementTool({ map }: MeasurementToolProps) {
  const {
    state,
    startMeasurement,
    finishAreaMeasurement,
    cancelMeasurement,
    clearMeasurement,
    getFormattedResult,
  } = useMeasurement(map);

  const [hoverTool, setHoverTool] = useState<MeasurementMode | null>(null);

  const tools: Array<{
    mode: MeasurementMode;
    icon: React.ReactNode;
    label: string;
    description: string;
  }> = [
    {
      mode: 'distance',
      icon: <Ruler className="w-5 h-5" />,
      label: 'Distance',
      description: 'Click two points to measure distance',
    },
    {
      mode: 'area',
      icon: <Square className="w-5 h-5" />,
      label: 'Area',
      description: 'Click points to draw polygon, then finish',
    },
    {
      mode: 'bearing',
      icon: <Compass className="w-5 h-5" />,
      label: 'Bearing',
      description: 'Click two points to measure bearing',
    },
    {
      mode: 'coordinate',
      icon: <MapPin className="w-5 h-5" />,
      label: 'Coordinate',
      description: 'Click to get coordinate',
    },
  ];

  const handleToolClick = (mode: MeasurementMode) => {
    if (state.isActive && state.mode !== mode) {
      cancelMeasurement();
    }
    startMeasurement(mode);
  };

  const result = getFormattedResult();

  return (
    <div className="bg-white rounded-lg shadow-lg border w-56">
      <div className="flex items-center border-b">
        {tools.map((tool) => (
          <button
            key={tool.mode}
            onClick={() => handleToolClick(tool.mode)}
            onMouseEnter={() => setHoverTool(tool.mode)}
            onMouseLeave={() => setHoverTool(null)}
            className={[
              'flex-1 p-2 flex flex-col items-center gap-1 transition-colors',
              state.mode === tool.mode && state.isActive
                ? 'bg-blue-600 text-white'
                : 'hover:bg-gray-100',
            ].join(' ')}
            title={tool.description}
          >
            {tool.icon}
            <span className="text-[10px]">{tool.label}</span>
          </button>
        ))}
      </div>

      {state.isActive && (
        <div className="px-3 py-2 bg-blue-50 text-xs text-blue-700">
          {state.mode === 'distance' && state.points.length === 0 && 'Click first point'}
          {state.mode === 'distance' && state.points.length === 1 && 'Click second point'}
          {state.mode === 'area' && state.points.length < 3 && `Click points (${state.points.length}/3 min)`}
          {state.mode === 'area' && state.points.length >= 3 && `${state.points.length} pts - Finish or add`}
          {state.mode === 'bearing' && state.points.length === 0 && 'Click first point'}
          {state.mode === 'bearing' && state.points.length === 1 && 'Click second point'}
          {state.mode === 'coordinate' && 'Click to get coordinate'}
        </div>
      )}

      {result && (
        <div className="px-4 py-3 border-t">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[10px] text-gray-500 uppercase">{result.type}</div>
              <div className="text-base font-semibold font-mono">
                {result.formatted}
              </div>
            </div>
            <button
              onClick={clearMeasurement}
              className="p-1.5 hover:bg-gray-100 rounded"
              title="Clear"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {state.points.length > 0 && (
            <div className="mt-2 text-[10px] text-gray-500">
              {state.points.map((p, i) => (
                <div key={`${p}-${i}`}>Pt {i + 1}: E {p.easting.toFixed(0)} N {p.northing.toFixed(0)}</div>
              ))}
            </div>
          )}
        </div>
      )}

      {state.isActive && !result && (
        <div className="px-4 py-2 border-t">
          {state.mode === 'area' && state.points.length >= 3 ? (
            <button
              onClick={finishAreaMeasurement}
              className="w-full py-1.5 bg-green-600 text-white text-sm rounded flex items-center justify-center gap-1"
            >
              <Check className="w-4 h-4" />
              Finish
            </button>
          ) : (
            <button
              onClick={cancelMeasurement}
              className="w-full py-1.5 text-sm text-red-600 hover:bg-red-50 rounded"
            >
              Cancel
            </button>
          )}
        </div>
      )}
    </div>
  );
}

