  useEffect(() => {
    if (typeof window === 'undefined') return
    const completed = localStorage.getItem(STORAGE_KEY)
    const skipped = localStorage.getItem('metardu:onboarding-skipped')
    const checklistDismissed = localStorage.getItem('metardu_onboarding_dismissed')
    if (!completed && !skipped && checklistDismissed) {
      // Only start the tour AFTER the checklist has been dismissed —
      // otherwise the user gets two onboarding overlays at once.
      const timer = setTimeout(() => setActive(true), 1500)
      return () => clearTimeout(timer)
    }
  }, [])

  const handleClose = useCallback(() => {
    setActive(false)
  }, [])

  const handleSkip = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, new Date().toISOString())
    localStorage.setItem('metardu:onboarding-skipped', 'true')
    // AUDIT FIX (M18, 2026-07-02): Persist to server so cross-device users
    // don't see the tour again. Fire-and-forget — localStorage is the
    // immediate source of truth; the server record prevents the tour from
    // reappearing on a new device.
    fetch('/api/user/onboarding', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'skip' }),
      credentials: 'include',
    }).catch(() => { /* silent fail — localStorage is enough */ })
    setActive(false)
  }, [])

  const handleComplete = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, new Date().toISOString())
    // AUDIT FIX (M18, 2026-07-02): Persist completion to server.
    fetch('/api/user/onboarding', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'complete' }),
      credentials: 'include',
    }).catch(() => { /* silent fail — localStorage is enough */ })
    setActive(false)
  }, [])

  const handleNext = useCallback(() => {
    const currentStep = TOUR_STEPS[step]
    if (step < TOUR_STEPS.length - 1) {
      // Navigate to the step's href if provided
      if (currentStep.href) {
        router.push(currentStep.href)
      }
      setStep(prev => prev + 1)
    } else {
      handleComplete()
    }
  }, [step, router, handleComplete])

  const handleBack = useCallback(() => {
    if (step > 0) {
      const prevStep = TOUR_STEPS[step - 1]
      if (prevStep.href) {
        router.push(prevStep.href)
      }
      setStep(prev => prev - 1)
    }
  }, [step, router])

  // Close the tour with Escape regardless of focus location
  // (handled at document level — the dialog element itself is not
  // focusable, so a local onKeyDown would only fire from child buttons)
  useEffect(() => {
    if (!active) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleSkip()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [active, handleSkip])

  if (!active) return null

  const currentStep = TOUR_STEPS[step]
  const Icon = currentStep.icon
  const isLast = step === TOUR_STEPS.length - 1
  const isFirst = step === 0

  return (
    <>
      {/* AUDIT FIX (M16, 2026-07-02): Added ARIA attributes for accessibility.
          - role="dialog" + aria-modal on the tour card (screen readers announce it as a dialog)
          - aria-labelledby pointing to the step title
          - aria-label on the close button
          - The backdrop no longer dismisses on click (prevents accidental dismissal)
            — users must click Skip or press Escape. */}

      {/* Backdrop overlay — no onClick (prevents accidental dismissal) */}
      <div
        className="fixed inset-0 z-[9990] bg-black/70 backdrop-blur-sm"
        aria-hidden="true"
      />

      {/* Tour card */}
      <div
        className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[9991] w-[440px] max-w-[calc(100vw-2rem)]"
        role="dialog"
        aria-modal="true"
        aria-labelledby="tour-title"
      >
        <div className="bg-[#0d0d14]/95 backdrop-blur-2xl border border-[#D17B47]/30 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          {/* Progress bar */}
          <div className="h-1 bg-white/[0.06]">
            <div
              className="h-full bg-[#D17B47] transition-all duration-300"
              style={{ width: `${((step + 1) / TOUR_STEPS.length) * 100}%` }}
            />
          </div>

          {/* Header */}
          <div className="flex items-center justify-between px-5 pt-4 pb-2">
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">
                Step {step + 1} of {TOUR_STEPS.length}
              </span>
            </div>
            <button
              onClick={handleSkip}
              className="w-7 h-7 flex items-center justify-center rounded-lg text-gray-400 hover:text-white hover:bg-white/[0.06] transition-colors"
              title="Skip tour"
              aria-label="Skip onboarding tour"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Content */}
          <div className="px-5 pb-5 space-y-3">
            <div className="flex items-start gap-3">
              <div className="shrink-0 w-12 h-12 rounded-xl bg-[#D17B47]/10 border border-[#D17B47]/20 flex items-center justify-center">
                <Icon className="w-6 h-6 text-[#D17B47]" />
              </div>
              <div className="flex-1 pt-1">
                <h3 id="tour-title" className="text-base font-bold text-white">{currentStep.title}</h3>
                <p className="text-xs text-gray-400 mt-1 leading-relaxed">{currentStep.description}</p>
              </div>
            </div>

            {/* Step dots */}
            <div className="flex items-center justify-center gap-1.5 pt-2">
              {TOUR_STEPS.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full transition-all duration-300 ${
                    i === step ? 'w-6 bg-[#D17B47]' : i < step ? 'w-1.5 bg-[#D17B47]/50' : 'w-1.5 bg-white/10'
                  }`}
                />
              ))}
            </div>

            {/* Actions */}
            <div className="flex items-center justify-between pt-2">
              <button
                onClick={handleSkip}
                className="text-[11px] text-gray-500 hover:text-gray-300 transition-colors"
              >
                Skip tour
              </button>
              <div className="flex items-center gap-2">
                {!isFirst && (
                  <button
                    onClick={handleBack}
                    className="flex items-center gap-1 px-3 h-8 rounded-lg bg-white/[0.04] border border-white/[0.06] text-xs text-gray-300 hover:bg-white/[0.08] transition-colors"
                  >
                    <ChevronLeft className="w-3.5 h-3.5" />
                    Back
                  </button>
                )}
                <button
                  onClick={handleNext}
                  className="flex items-center gap-1 px-4 h-8 rounded-lg bg-[#D17B47] hover:bg-[#FFB84D] text-black text-xs font-semibold transition-colors"
                >
                  {isLast ? (
                    <>
                      <Check className="w-3.5 h-3.5" />
                      Get Started
                    </>
                  ) : (
                    <>
                      Next
                      <ChevronRight className="w-3.5 h-3.5" />
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

/**
 * Hook to check if onboarding has been completed
 */
export function useOnboardingStatus() {
  const [completed, setCompleted] = useState(false)

  useEffect(() => {
    setCompleted(!!localStorage.getItem(STORAGE_KEY))
  }, [])

  return completed
}

/**
 * Reset onboarding (for testing or re-triggering)
 */
export function resetOnboarding() {
  localStorage.removeItem(STORAGE_KEY)
  localStorage.removeItem('metardu:onboarding-skipped')
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient, type BrowserSession } from '@/lib/api-client/client';
import { coordinateArea } from '@/lib/engine/area';
import { distanceBearing } from '@/lib/engine/distance';
import { logger } from '@/lib/logger'

interface Point {
  id: string;
  name: string;
  easting: number;
  northing: number;
  elevation?: number | null;
  is_control?: boolean;
  locked?: boolean;
}

interface ParcelBuilderModalProps {
  projectId: string;
  points: Point[];
  onClose: () => void;
  onParcelCreated: (parcel?: { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string }) => void;
  onDraftBoundaryChange?: (boundary: Array<{ easting: number; northing: number }> | null) => void;
}

interface BoundaryPoint {
  id: string;
  name: string;
  easting: number;
  northing: number;
}

interface BoundaryLine {
  from: string;
  to: string;
  bearing: string;
  bearingDeg: number;
  distance: number;
}

export default function ParcelBuilderModal({ projectId, points, onClose, onParcelCreated, onDraftBoundaryChange }: ParcelBuilderModalProps) {
  const [parcelName, setParcelName] = useState('');
  const [selectedPoints, setSelectedPoints] = useState<BoundaryPoint[]>([]);
  const [isSelecting, setIsSelecting] = useState(true);
  const [boundaryLines, setBoundaryLines] = useState<BoundaryLine[]>([]);
  const [areaResult, setAreaResult] = useState<{
    areaSqm: number;
    areaHa: number;
    areaAcres: number;
    perimeter: number;
  } | null>(null);
  const [saving, setSaving] = useState(false);
  const dbClient = createClient();

  const computeParcel = useCallback(() => {
    if (selectedPoints.length < 3) {
      setBoundaryLines([]);
      setAreaResult(null);
      return;
    }

    const coords = selectedPoints.map((p) => ({ easting: p.easting, northing: p.northing }));
    const areaData = coordinateArea(coords);

    const lines: BoundaryLine[] = [];
    for (let i = 0; i < selectedPoints.length; i++) {
      const from = selectedPoints[i];
      const to = selectedPoints[(i + 1) % selectedPoints.length];
      const db = distanceBearing(from, to);
      lines.push({
        from: from.name,
        to: to.name,
        bearing: db.bearingDMS,
        bearingDeg: db.bearing,
        distance: db.distance
      });
    }

    setBoundaryLines(lines);
    setAreaResult({
      areaSqm: areaData.areaSqm,
      areaHa: areaData.areaHa,
      areaAcres: areaData.areaAcres,
      perimeter: areaData.perimeter
    });
  }, [selectedPoints]);

  useEffect(() => {
    if (selectedPoints.length >= 3) {
      computeParcel();
    } else {
      setBoundaryLines([]);
      setAreaResult(null);
    }
  }, [selectedPoints, computeParcel]);

  const handlePointClick = (point: Point) => {
    if (!isSelecting) return;

    const firstPoint = selectedPoints[0]
    if (selectedPoints.length > 0 && firstPoint && firstPoint.id === point.id) {
      if (selectedPoints.length >= 3) setIsSelecting(false);
      return;
    }

    if (selectedPoints.find((p) => p.id === point.id)) return;

    setSelectedPoints([
      ...selectedPoints,
      {
        id: point.id,
        name: point.name,
        easting: point.easting,
        northing: point.northing
      }
    ]);
  };

  const handleSave = async () => {
    if (!parcelName || selectedPoints.length < 3 || !areaResult) return;

    setSaving(true);
    try {
      const { data: { session } } = await dbClient.auth.getSession();
      const user = (session as BrowserSession | null)?.user;

      const { data, error } = await dbClient.from('parcels').insert({
        project_id: projectId,
        name: parcelName,
        point_ids: selectedPoints.map((p) => p.id),
        boundary_points: selectedPoints.map((p) => ({
          name: p.name,
          easting: p.easting,
          northing: p.northing
        })),
        area_sqm: areaResult.areaSqm,
        area_ha: areaResult.areaHa,
        area_acres: areaResult.areaAcres,
        perimeter_m: areaResult.perimeter,
        created_by: user?.id
            }).select('id, name, boundary_points, created_at').single() as unknown as { data: { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string } | null; error: unknown };

      if (error) throw error;

      onParcelCreated((data ?? undefined) as { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string });
      onClose();
    } catch (err) {
      logger.error('Error saving parcel:', { error: err });
      alert('Failed to save parcel');
    } finally {
      setSaving(false);
    }
  };

  const handleReset = () => {
    setSelectedPoints([]);
    setIsSelecting(true);
    setBoundaryLines([]);
    setAreaResult(null);
    setParcelName('');
  };

  return (
    <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
      <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-[var(--border-color)] flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold text-white">Build Parcel</h2>
            <p className="text-sm text-[var(--text-secondary)]">Click points in boundary order. Click first point to close.</p>
          </div>
          <button onClick={onClose} className="text-[var(--text-secondary)] hover:text-white text-2xl">&times;</button>
        </div>

        <div className="p-6 space-y-6">
          <div className="grid md:grid-cols-2 gap-6">
            <div>
              <h3 className="font-semibold text-[var(--text-primary)] mb-3">Available Points</h3>
              <div className="bg-[var(--bg-tertiary)] rounded-lg p-3 max-h-64 overflow-y-auto">
                {points.filter((p) => !p.locked).length === 0 ? (
                  <p className="text-[var(--text-muted)] text-sm">No points available</p>
                ) : (
                  <div className="grid grid-cols-2 gap-2">
                    {points.filter((p) => !p.locked).map((point) => {
                      const isAlreadySelected = selectedPoints.some((p) => p.id === point.id)
                      const isFirst = selectedPoints.length > 0 && selectedPoints[0].id === point.id
                      const canClose = isFirst && selectedPoints.length >= 3
                      const disabled = !isSelecting || (isAlreadySelected && !canClose)

                      return (
                        <button
                          key={point.id}
                          onClick={() => handlePointClick(point)}
                          disabled={disabled}
                          className={`px-3 py-2 rounded text-sm font-mono text-left transition-colors ${
                            isAlreadySelected
                              ? canClose
                                ? 'bg-green-900/40 border border-green-700 text-green-200 hover:bg-green-900/60'
                                : 'bg-[var(--accent)] text-black'
                              : isSelecting
                                ? 'bg-gray-700 hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                                : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)] cursor-not-allowed'
                          }`}
                          title={canClose ? 'Click to close boundary' : undefined}
                        >
                          <div className="flex items-center justify-between gap-2">
                            <span>{point.name}</span>
                            {canClose ? <span className="text-xs font-sans">Close</span> : null}
                          </div>
                          <span className="text-xs text-[var(--text-secondary)] ml-1 block">
                            {point.easting.toFixed(0)}, {point.northing.toFixed(0)}
                          </span>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>

              {isSelecting && selectedPoints.length > 0 && (
                <div className="mt-4">
                  <h4 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Selected Boundary ({selectedPoints.length})</h4>
                  <div className="flex flex-wrap gap-2">
                    {selectedPoints.map((p, idx) => (
                      <span key={p.id} className="px-2 py-1 bg-[var(--accent)]/20 text-[var(--accent)] rounded text-sm">
                        {p.name}
                        {idx < selectedPoints.length - 1 && ' → '}
                      </span>
                    ))}
                  </div>
                  <div className="mt-3 flex items-center gap-2">
                    <button
                      onClick={() => {
                        if (selectedPoints.length >= 3) setIsSelecting(false)
                      }}
                      disabled={selectedPoints.length < 3}
                      className="px-3 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm disabled:opacity-50"
                    >
                      Close boundary
                    </button>
                    <span className="text-xs text-[var(--text-muted)]">
                      or click the first point again
                    </span>
                  </div>
                </div>
              )}
            </div>

            <div>
              {areaResult ? (
                <div className="bg-[var(--bg-tertiary)] rounded-xl p-6">
                  <h3 className="font-bold text-white text-lg mb-4">PARCEL SUMMARY</h3>
                  {isSelecting ? (
                    <div className="mb-3 rounded border border-amber-700/50 bg-amber-900/10 px-3 py-2 text-xs text-amber-200">
                      Preview only — close the boundary (click the first point again) to enter a name and save.
                    </div>
                  ) : null}
                  <div className="border-b border-[var(--border-color)] pb-2 mb-3">
                    <span className="text-[var(--text-secondary)] text-sm">Boundary: </span>
                    <span className="text-[var(--text-primary)]">
                      {selectedPoints.map((p) => p.name).join(' → ')}
                    </span>
                  </div>

                  <div className="overflow-x-auto">
                  <table className="w-full text-sm mb-4 min-w-[300px]">
                    <thead>
                      <tr className="border-b border-[var(--border-color)]">
                        <th className="text-left py-2 text-[var(--text-secondary)]">Line</th>
                        <th className="text-right py-2 text-[var(--text-secondary)]">Bearing</th>
                        <th className="text-right py-2 text-[var(--text-secondary)]">Distance</th>
                      </tr>
                    </thead>
                    <tbody>
                      {boundaryLines.map((line, idx) => (
                        <tr key={`${line}-${idx}`} className="border-b border-[var(--border-color)]">
                          <td className="py-2 text-[var(--text-primary)]">{line.from}→{line.to}</td>
                          <td className="py-2 text-right font-mono text-[var(--text-primary)]">{line.bearing}</td>
                          <td className="py-2 text-right font-mono text-[var(--text-primary)]">{line.distance.toFixed(3)} m</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  </div>

                  <div className="space-y-2 pt-4 border-t border-[var(--border-color)]">
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]">Area:</span>
                      <span className="font-mono text-white">{areaResult.areaSqm.toFixed(4)} m²</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]"></span>
                      <span className="font-mono text-white">{areaResult.areaHa.toFixed(6)} ha</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]"></span>
                      <span className="font-mono text-white">{areaResult.areaAcres.toFixed(4)} acres</span>
                    </div>
                    <div className="flex justify-between pt-2 border-t border-[var(--border-color)]">
                      <span className="text-[var(--text-secondary)]">Perimeter:</span>
                      <span className="font-mono text-white">{areaResult.perimeter.toFixed(3)} m</span>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="bg-[var(--bg-tertiary)]/50 rounded-xl p-6 text-center">
                  <p className="text-[var(--text-muted)]">
                    {selectedPoints.length < 3
                      ? `Select at least 3 points (${3 - selectedPoints.length} more)`
                      : 'Click the first point again to close the boundary'}
                  </p>
                </div>
              )}
            </div>
          </div>

          {!isSelecting && areaResult && (
            <div className="border-t border-[var(--border-color)] pt-6">
              <div className="max-w-md">
                <label className="label" htmlFor="parcel-name">Parcel Name</label>
                <input id="parcel-name"
                  className="input"
                  value={parcelName}
                  onChange={e => setParcelName(e.target.value)}
 placeholder="e.g., Plot A, Parcel 1"
                />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-[var(--border-color)] flex gap-3 justify-end">
          <button onClick={handleReset} className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded">
            Reset
          </button>
          <button onClick={onClose} className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded">
            Cancel
          </button>
          {!isSelecting && areaResult && (
            <button
              onClick={handleSave}
              disabled={!parcelName || saving}
              className="px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded disabled:opacity-50"
            >
              {saving ? 'Saving...' : 'Save Parcel'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client'

/**
 * BatchParcelImport — Bulk import parcels from CSV/GeoJSON
 *
 * Solves the Mwavumbo Ward problem: importing 200+ parcels with owner data.
 */

import { useState, useCallback, useRef } from 'react'
import {
  Upload, Loader2, CheckCircle2, AlertTriangle,
  Download, Table, Layers, Users,
} from 'lucide-react'
import { processWithProgress } from '@/lib/performance'

interface GeoJSONParcelProps {
  parcel_number?: string
  parcelNumber?: string
  name?: string
  owner_name?: string
  ownerName?: string
  owner?: string
  owner_id?: string
  ownerId?: string
  national_id?: string
  lr_number?: string
  lrNumber?: string
  title_deed?: string
  area_ha?: string
  area?: string
}

interface GeoJSONGeometry {
  type?: string
  coordinates?: unknown
}

interface GeoJSONFeature {
  properties?: GeoJSONParcelProps
  geometry?: GeoJSONGeometry
}

interface ParsedParcel {
  id: string
  parcelNumber: string
  ownerName?: string
  ownerId?: string
  lrNumber?: string
  areaHa?: number
  vertices: Array<{ easting: number; northing: number }>
  valid: boolean
  errors: string[]
}

interface BatchParcelImportProps {
  projectId: string
  onImport?: (parcels: ParsedParcel[]) => void
}

export function BatchParcelImport({ projectId, onImport }: BatchParcelImportProps) {
  const [parcels, setParcels] = useState<ParsedParcel[]>([])
  const [parsing, setParsing] = useState(false)
  const [importing, setImporting] = useState(false)
  const [importProgress, setImportProgress] = useState(0)
  const [dragOver, setDragOver] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [importResult, setImportResult] = useState<{ success: number; failed: number } | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const parseCSV = useCallback((text: string): ParsedParcel[] => {
    const lines = text.split('\n').filter(l => l.trim())
    if (lines.length < 2) return []

    const header = lines[0].split(',').map(h => h.trim().toLowerCase())
    const parcelsMap = new Map<string, ParsedParcel>()

    const colIdx = {
      parcelNumber: header.findIndex(h => h.includes('parcel') || h.includes('plot')),
      easting: header.findIndex(h => h.includes('easting') || h === 'e'),
      northing: header.findIndex(h => h.includes('northing') || h === 'n'),
      ownerName: header.findIndex(h => h.includes('owner') && h.includes('name')),
      ownerId: header.findIndex(h => h.includes('owner') && h.includes('id')),
      lrNumber: header.findIndex(h => h.includes('lr') || h.includes('title')),
      areaHa: header.findIndex(h => h.includes('area') || h.includes('ha')),
    }

    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(',').map(c => c.trim())
      const parcelNum = colIdx.parcelNumber >= 0 ? cols[colIdx.parcelNumber] : `PARCEL-${i}`
      const easting = colIdx.easting >= 0 ? parseFloat(cols[colIdx.easting]) : NaN
      const northing = colIdx.northing >= 0 ? parseFloat(cols[colIdx.northing]) : NaN

      if (!parcelNum || !isFinite(easting) || !isFinite(northing)) continue

      let parcelEntry = parcelsMap.get(parcelNum)
      if (!parcelEntry) {
        parcelEntry = {
          id: crypto.randomUUID(),
          parcelNumber: parcelNum,
          ownerName: colIdx.ownerName >= 0 ? cols[colIdx.ownerName] : undefined,
          ownerId: colIdx.ownerId >= 0 ? cols[colIdx.ownerId] : undefined,
          lrNumber: colIdx.lrNumber >= 0 ? cols[colIdx.lrNumber] : undefined,
          areaHa: colIdx.areaHa >= 0 ? parseFloat(cols[colIdx.areaHa]) : undefined,
          vertices: [],
          valid: true,
          errors: [],
        }
        parcelsMap.set(parcelNum, parcelEntry)
      }

      parcelEntry.vertices.push({ easting, northing })
    }

    const parcels = Array.from(parcelsMap.values())
    for (const parcel of parcels) {
      if (parcel.vertices.length < 3) {
        parcel.errors.push('Needs at least 3 vertices')
        parcel.valid = false
      }
      if (!parcel.parcelNumber) {
        parcel.errors.push('Missing parcel number')
        parcel.valid = false
      }
    }

    return parcels
  }, [])

  const parseGeoJSON = useCallback((text: string): ParsedParcel[] => {
    const geojson = JSON.parse(text) as { features?: GeoJSONFeature[] }
    if (!geojson.features || !Array.isArray(geojson.features)) return []

    return geojson.features.map((feature, idx: number) => {
      const props: GeoJSONParcelProps = feature.properties || {}
      const geom: GeoJSONGeometry = feature.geometry || {}

      let vertices: Array<{ easting: number; northing: number }> = []

      if (geom.type === 'Polygon') {
        const ring = ((geom.coordinates as number[][][]) || [])[0] || []
        const verts = ring.slice(0, -1)
        vertices = verts.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
      } else if (geom.type === 'MultiPolygon') {
        const ring = ((geom.coordinates as number[][][][]) || [])[0]?.[0] || []
        const verts = ring.slice(0, -1)
        vertices = verts.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
      }

      const errors: string[] = []
      if (vertices.length < 3) errors.push('Needs at least 3 vertices')

      return {
        id: crypto.randomUUID(),
        parcelNumber: props.parcel_number || props.parcelNumber || props.name || `PARCEL-${idx + 1}`,
        ownerName: props.owner_name || props.ownerName || props.owner,
        ownerId: props.owner_id || props.ownerId || props.national_id,
        lrNumber: props.lr_number || props.lrNumber || props.title_deed,
        areaHa: props.area_ha ? parseFloat(props.area_ha) : props.area ? parseFloat(props.area) : undefined,
        vertices,
        valid: errors.length === 0,
        errors,
      }
    })
  }, [])

  const handleFile = useCallback(async (file: File) => {
    setParsing(true)
    setError(null)
    setImportResult(null)

    try {
      const text = await file.text()
      const ext = file.name.split('.').pop()?.toLowerCase()

      let parsed: ParsedParcel[] = []
      if (ext === 'geojson' || ext === 'json') {
        parsed = parseGeoJSON(text)
      } else {
        parsed = parseCSV(text)
      }

      setParcels(parsed)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to parse file')
    } finally {
      setParsing(false)
    }
  }, [parseCSV, parseGeoJSON])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleImport = useCallback(async () => {
    if (parcels.length === 0) return
    setImporting(true)
    setImportProgress(0)
    setError(null)

    try {
      // For large imports (100+ parcels), process in chunks to avoid UI freeze
      if (parcels.length > 100) {
        const validParcels = parcels.filter(p => p.valid)
        const chunkSize = 50
        const totalChunks = Math.ceil(validParcels.length / chunkSize)

        let totalSuccess = 0
        let totalFailed = 0

        for (let i = 0; i < validParcels.length; i += chunkSize) {
          const chunk = validParcels.slice(i, i + chunkSize)
          const currentChunk = Math.floor(i / chunkSize) + 1

          setImportProgress((currentChunk / totalChunks) * 100)

          try {
            const res = await fetch(`/api/projects/${projectId}/parcels/batch`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                parcels: chunk.map(p => ({
                  parcelNumber: p.parcelNumber,
                  ownerName: p.ownerName,
                  ownerId: p.ownerId,
                  lrNumber: p.lrNumber,
                  areaHa: p.areaHa,
                  vertices: p.vertices,
                })),
              }),
            })
            if (res.ok) {
              const data = (await res.json()) as { data?: { imported?: number; failed?: number } }
              totalSuccess += data.data?.imported || chunk.length
              totalFailed += data.data?.failed || 0
            } else {
              totalFailed += chunk.length
            }
          } catch {
            totalFailed += chunk.length
          }

          // Yield to event loop so UI can update
          await new Promise(resolve => setTimeout(resolve, 0))
        }

        setImportProgress(100)
        setImportResult({ success: totalSuccess, failed: totalFailed })
        onImport?.(parcels)
      } else {
        // Small import — single request
        const res = await fetch(`/api/projects/${projectId}/parcels/batch`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            parcels: parcels.map(p => ({
              parcelNumber: p.parcelNumber,
              ownerName: p.ownerName,
              ownerId: p.ownerId,
              lrNumber: p.lrNumber,
              areaHa: p.areaHa,
              vertices: p.vertices,
            })),
          }),
        })

        if (!res.ok) {
          const data = (await res.json()) as { error?: string }
          throw new Error(data.error || 'Import failed')
        }

        const data = (await res.json()) as { data?: { imported?: number; failed?: number } }
        setImportResult({
          success: data.data?.imported || parcels.length,
          failed: data.data?.failed || 0,
        })
        setImportProgress(100)
        onImport?.(parcels)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed')
    } finally {
      setImporting(false)
    }
  }, [parcels, projectId, onImport])

  const downloadTemplate = useCallback(() => {
    const csv = `parcel_number,easting,northing,owner_name,owner_id,lr_number,area_ha
MWAVUMBO/001,534850.123,9574220.456,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534852.456,9574221.789,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534854.789,9574222.123,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534850.123,9574220.456,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/002,534860.000,9574230.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534862.000,9574231.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534864.000,9574232.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534860.000,9574230.000,Jane Smith,87654321,LR/12345/679,0.7500`
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'metardu-parcel-template.csv'
    a.click()
    URL.revokeObjectURL(url)
  }, [])

  const validCount = parcels.filter(p => p.valid).length
  const invalidCount = parcels.length - validCount

  return (
    <div className="space-y-4">
      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true) }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        className={`rounded-xl border-2 border-dashed p-8 text-center cursor-pointer transition-all ${
          dragOver ? 'border-[var(--accent)] bg-[var(--accent)]/5' : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
        }`}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv,.geojson,.json"
          onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
          className="hidden"
        />
        {parsing ? (
          <div className="flex flex-col items-center">
            <Loader2 className="w-8 h-8 text-[var(--accent)] animate-spin mb-2" />
            <p className="text-sm text-gray-400">Parsing file...</p>
          </div>
        ) : (
          <div className="flex flex-col items-center">
            <div className="w-12 h-12 rounded-xl bg-[var(--accent)]/10 flex items-center justify-center mb-3">
              <Upload className="w-6 h-6 text-[var(--accent)]" />
            </div>
            <p className="text-sm font-medium text-[var(--text-primary)]">
              Drop CSV or GeoJSON here, or click to browse
            </p>
            <p className="text-[10px] text-gray-500 mt-1">
              Supports parcel boundaries with owner data — up to 1000 parcels
            </p>
          </div>
        )}
      </div>

      <div className="flex items-center justify-between">
        <button
          onClick={downloadTemplate}
          className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200"
        >
          <Download className="w-3.5 h-3.5" />
          Download CSV Template
        </button>
        {parcels.length > 0 && (
          <button onClick={() => setParcels([])} className="text-[10px] text-gray-500 hover:text-gray-300">
            Clear
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 flex items-start gap-2">
          <AlertTriangle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
          <p className="text-xs text-red-400">{error}</p>
        </div>
      )}

      {importResult && (
        <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20 flex items-start gap-2">
          <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0 mt-0.5" />
          <div>
            <p className="text-xs text-emerald-400 font-medium">
              Import complete: {importResult.success} parcels imported
            </p>
            {importResult.failed > 0 && (
              <p className="text-[10px] text-amber-400">{importResult.failed} failed</p>
            )}
          </div>
        </div>
      )}

      {parcels.length > 0 && (
        <div className="card p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Table className="w-4 h-4 text-[var(--accent)]" />
              <span className="text-sm font-semibold text-[var(--text-primary)]">
                Preview ({parcels.length} parcels)
              </span>
            </div>
            <div className="flex items-center gap-3 text-[10px]">
              <span className="flex items-center gap-1 text-emerald-400">
                <CheckCircle2 className="w-3 h-3" />
                {validCount} valid
              </span>
              {invalidCount > 0 && (
                <span className="flex items-center gap-1 text-red-400">
                  <AlertTriangle className="w-3 h-3" />
                  {invalidCount} errors
                </span>
              )}
            </div>
          </div>

          <div className="max-h-[300px] overflow-y-auto">
            <table className="w-full">
              <thead className="sticky top-0 bg-[var(--bg-card)]">
                <tr className="border-b border-[var(--border-color)]">
                  <th className="px-2 py-2 text-left text-[9px] text-gray-500 uppercase">Parcel No.</th>
                  <th className="px-2 py-2 text-left text-[9px] text-gray-500 uppercase">Owner</th>
                  <th className="px-2 py-2 text-center text-[9px] text-gray-500 uppercase">Vertices</th>
                  <th className="px-2 py-2 text-right text-[9px] text-gray-500 uppercase">Area (ha)</th>
                  <th className="px-2 py-2 text-center text-[9px] text-gray-500 uppercase">Status</th>
                </tr>
              </thead>
              <tbody>
                {parcels.map(parcel => (
                  <tr key={parcel.id} className="border-b border-[var(--border-color)]/50">
                    <td className="px-2 py-2 text-xs font-mono text-[var(--text-primary)]">{parcel.parcelNumber}</td>
                    <td className="px-2 py-2 text-xs text-gray-400">{parcel.ownerName || '—'}</td>
                    <td className="px-2 py-2 text-xs text-center text-gray-400">{parcel.vertices.length}</td>
                    <td className="px-2 py-2 text-xs text-right font-mono text-gray-400">{parcel.areaHa ? parcel.areaHa.toFixed(4) : '—'}</td>
                    <td className="px-2 py-2 text-center">
                      {parcel.valid ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 inline" /> : <AlertTriangle className="w-3.5 h-3.5 text-red-400 inline" />}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <button
            onClick={handleImport}
            disabled={importing || validCount === 0}
            className="w-full mt-3 flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {importing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Layers className="w-4 h-4" />}
            {importing ? `${importProgress > 0 ? Math.round(importProgress) + '%' : 'Importing...'}` : `Import ${validCount} Parcels to Project`}
          </button>
        </div>
      )}

      <div className="flex items-start gap-2 p-3 rounded-lg bg-blue-500/5 border border-blue-500/10">
        <Users className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
        <div className="text-[10px] text-blue-400/70 leading-relaxed">
          <p className="font-medium mb-1">CSV Format:</p>
          <p>Each row = one vertex. Multiple rows with the same parcel_number = one parcel&apos;s vertices.</p>
          <p className="mt-1">Columns: parcel_number, easting, northing, owner_name, owner_id, lr_number, area_ha</p>
          <p className="mt-1 font-medium">GeoJSON: Polygon features with properties for owner data.</p>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * CollaborationPanel — Combined presence + chat panel for project workspaces
 *
 * Features:
 * - Online collaborators with avatars
 * - Live chat messages
 * - Send messages
 * - Conflict warnings
 * - Collapsible panel
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  MessageSquare, Send, Users, ChevronDown, ChevronUp,
  AlertTriangle, X,
} from 'lucide-react'
import { PresenceIndicator } from './PresenceIndicator'
import type { Collaborator } from '@/lib/realtime/useCollaboration'

interface ChatMessage {
  id: string
  userId: string
  userName: string
  message: string
  timestamp: number
}

interface CollaborationPanelProps {
  collaborators: Collaborator[]
  isConnected: boolean
  messages: ChatMessage[]
  onSend: (message: string) => void
  conflictWarnings?: string[]
}

export function CollaborationPanel({
  collaborators,
  isConnected,
  messages,
  onSend,
  conflictWarnings = [],
}: CollaborationPanelProps) {
  const [expanded, setExpanded] = useState(true)
  const [input, setInput] = useState('')
  const messagesEndRef = useRef<HTMLDivElement>(null)

  // Auto-scroll to bottom on new message
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleSend = useCallback(() => {
    if (!input.trim()) return
    onSend(input.trim())
    setInput('')
  }, [input, onSend])

  const handleKeyPress = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }, [handleSend])

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <Users className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div className="text-left">
            <span className="text-sm font-semibold text-[var(--text-primary)]">Team Collaboration</span>
            <p className="text-[10px] text-gray-500">
              {isConnected
                ? `${collaborators.length + 1} online`
                : 'Disconnected'}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <PresenceIndicator collaborators={collaborators} isConnected={isConnected} max={4} />
          {expanded ? <ChevronUp className="w-4 h-4 text-gray-500" /> : <ChevronDown className="w-4 h-4 text-gray-500" />}
        </div>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)]">
          {/* Conflict warnings */}
          {conflictWarnings.length > 0 && (
            <div className="p-2 bg-amber-500/5 border-b border-amber-500/10">
              {conflictWarnings.map((warning, i) => (
                <div key={`${warning}-${i}`} className="flex items-center gap-1.5 text-[10px] text-amber-400">
                  <AlertTriangle className="w-3 h-3 shrink-0" />
                  {warning}
                </div>
              ))}
            </div>
          )}

          {/* Chat messages */}
          <div className="max-h-[200px] overflow-y-auto p-3 space-y-2">
            {messages.length === 0 ? (
              <div className="text-center py-4">
                <MessageSquare className="w-6 h-6 text-gray-600 mx-auto mb-1" />
                <p className="text-[10px] text-gray-500">No messages yet</p>
                <p className="text-[9px] text-gray-600">Start a conversation with your team</p>
              </div>
            ) : (
              messages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2">
                  <div className="shrink-0 w-6 h-6 rounded-full bg-[var(--accent)]/10 flex items-center justify-center text-[9px] font-bold text-[var(--accent)]">
                    {msg.userName.split(' ').map(n => n[0]).slice(0, 2).join('').toUpperCase()}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-baseline gap-1.5">
                      <span className="text-[10px] font-medium text-[var(--text-primary)]">{msg.userName}</span>
                      <span className="text-[8px] text-gray-600">
                        {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    <p className="text-[11px] text-[var(--text-secondary)] break-words">{msg.message}</p>
                  </div>
                </div>
              ))
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <div className="border-t border-[var(--border-color)] p-2 flex items-center gap-2">
            <input aria-label="Type a message"
              type="text"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder={isConnected ? 'Type a message...' : 'Disconnected'}
              disabled={!isConnected}
              className="flex-1 h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none disabled:opacity-50"
            />
            <button
              onClick={handleSend}
              disabled={!isConnected || !input.trim()}
              aria-label="Send message"
              className="w-8 h-8 flex items-center justify-center rounded-lg bg-[var(--accent)] text-black disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[var(--accent-dim)]"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useCallback } from 'react'
import {
  Upload, X, FileSpreadsheet, AlertCircle, CheckCircle2,
  Loader2, Info
} from 'lucide-react'

interface ImportResult {
  total_rows: number
  created: number
  skipped: number
  errors: string[]
}

export default function CsvImportPanel({ projectId, blockId, blockName, onImportComplete }: {
  projectId: number | string
  blockId: number | string
  blockName: string
  onImportComplete?: () => void
}) {
  const fileRef = useRef<HTMLInputElement>(null)
  const [dragging, setDragging] = useState(false)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<ImportResult | null>(null)
  const [error, setError] = useState('')
  const [fileName, setFileName] = useState('')

  const doImport = useCallback(async (file: File) => {
    setLoading(true)
    setError('')
    setResult(null)
    setFileName(file.name)

    const formData = new FormData()
    formData.append('project_id', String(projectId))
    formData.append('block_id', String(blockId))
    formData.append('file', file)

    try {
      const res = await fetch('/api/scheme/import', {
        method: 'POST',
        body: formData,
      })
      const json = await res.json() as { error?: string; data?: ImportResult | null }
      if (!res.ok) throw new Error(json.error || 'Import failed')

      setResult(json.data ?? null)
      if ((json.data?.created ?? 0) > 0 && onImportComplete) {
        onImportComplete()
      }
    } catch (err: unknown) {
      setError((err as Error).message)
    } finally {
      setLoading(false)
    }
  }, [projectId, blockId, onImportComplete])

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) doImport(file)
  }

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragging(false)
    const file = e.dataTransfer.files?.[0]
    if (file) doImport(file)
  }, [doImport])

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setDragging(true)
  }

  const handleDragLeave = () => setDragging(false)

  // Sample CSV data for download
  const downloadSample = () => {
    const csv = `parcel_number,lr_number_proposed,area_ha,notes
1,MN/III/1001,0.0625,Northwest corner
2,MN/III/1002,0.1250,Central portion
3,MN/III/1003,0.0875,East boundary
4,MN/III/1004,0.1500,South section
5,MN/III/1005,0.1000,Road reserve
6,MN/III/1006,0.0750,Adjoining river
7,MN/III/1007,0.0500,Corner plot
8,MN/III/1008,0.2000,Large subdivision
9,MN/III/1009,0.1100,Commercial zone
10,MN/III/1010,0.0800,Public utility`
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `sample_parcels_${blockName}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="border border-[var(--border-color)] rounded-xl overflow-hidden bg-[var(--bg-card)]">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <span className="text-sm font-semibold text-[var(--text-primary)] flex items-center gap-2">
          <FileSpreadsheet className="w-4 h-4 text-blue-400" />
          Bulk Import Parcels
        </span>
        <button
          onClick={downloadSample}
          className="text-xs text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors flex items-center gap-1"
        >
          <Info className="w-3 h-3" />
          Download Sample CSV
        </button>
      </div>

      <div className="px-4 py-3 space-y-3">
        {/* Upload Zone */}
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={() => fileRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all ${
            dragging
              ? 'border-[var(--accent)] bg-[var(--accent)]/5'
              : 'border-[var(--border-color)] hover:border-[var(--accent)]/50 hover:bg-[var(--bg-secondary)]'
          }`}
        >
          <input
            ref={fileRef}
            type="file"
            accept=".csv,text/csv"
            onChange={handleFileChange}
            className="hidden"
          />
          {loading ? (
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="w-8 h-8 animate-spin text-[var(--accent)]" />
              <p className="text-sm text-[var(--text-secondary)]">Importing {fileName}...</p>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-2">
              <Upload className="w-8 h-8 text-[var(--text-muted)]" />
              <p className="text-sm text-[var(--text-secondary)]">
                Drop CSV here or <span className="text-[var(--accent)] underline">browse</span>
              </p>
              <p className="text-[10px] text-[var(--text-muted)]">
                Required columns: parcel_number | Optional: lr_number_proposed, area_ha, notes
              </p>
            </div>
          )}
        </div>

        {/* Error */}
        {error && (
          <div className="p-2.5 bg-red-900/20 border border-red-500/30 rounded-lg text-xs text-red-400 flex items-start gap-2">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {/* Result */}
        {result && (
          <div className="space-y-2">
            <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                <span className="text-sm font-medium text-emerald-400">
                  Import complete
                </span>
              </div>
              <div className="grid grid-cols-3 gap-3 text-xs">
                <div>
                  <span className="text-emerald-300 font-bold">{result.created}</span>
                  <span className="text-[var(--text-muted)]"> created</span>
                </div>
                <div>
                  <span className="text-yellow-300 font-bold">{result.skipped}</span>
                  <span className="text-[var(--text-muted)]"> skipped/updated</span>
                </div>
                <div>
                  <span className="text-[var(--text-secondary)]">{result.total_rows}</span>
                  <span className="text-[var(--text-muted)]"> total rows</span>
                </div>
              </div>
            </div>

            {result.errors.length > 0 && (
              <div className="p-2.5 bg-yellow-500/10 border border-yellow-500/20 rounded-lg">
                <p className="text-[10px] font-medium text-yellow-400 mb-1">
                  {result.errors.length} warning(s):
                </p>
                <div className="max-h-24 overflow-y-auto space-y-0.5">
                  {result.errors.map((e, i) => (
                    <p key={`${e}-${i}`} className="text-[10px] text-yellow-300/80">{e}</p>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

/**
 * AccessibilityAudit — ARIA labels and keyboard navigation for screen readers
 *
 * This component wraps children and provides:
 * - Skip links to main content
 * - ARIA live regions for dynamic updates
 * - Keyboard focus management
 * - Screen reader announcements
 *
 * Per Kenya Constitution Article 54 — persons with disabilities
 * have the right to access information.
 */

import { useEffect, useRef, useCallback, ReactNode } from 'react'

interface AccessibilityWrapperProps {
  children: ReactNode
  /** Announcements for screen readers */
  announcements?: string[]
}

export function AccessibilityWrapper({ children, announcements = [] }: AccessibilityWrapperProps) {
  const liveRegionRef = useRef<HTMLDivElement>(null)

  // Announce changes to screen readers
  useEffect(() => {
    if (liveRegionRef.current && announcements.length > 0) {
      liveRegionRef.current.textContent = announcements.join('. ')
    }
  }, [announcements])

  return (
    <>
      {children}
      {/* ARIA live region for screen reader announcements */}
      <div
        ref={liveRegionRef}
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      />
    </>
  )
}

/**
 * Hook for managing focus trap (for modals, drawers)
 */
export function useFocusTrap(isActive: boolean) {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!isActive || !containerRef.current) return

    const container = containerRef.current
    const focusableElements = container.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    )
    const firstElement = focusableElements[0]
    const lastElement = focusableElements[focusableElements.length - 1]

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault()
          lastElement?.focus()
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault()
          firstElement?.focus()
        }
      }
    }

    container.addEventListener('keydown', handleKeyDown)
    firstElement?.focus()

    return () => container.removeEventListener('keydown', handleKeyDown)
  }, [isActive])

  return containerRef
}

/**
 * Common ARIA props for interactive elements
 */
export const ARIA_PROPS = {
  // Map controls
  mapContainer: {
    role: 'application',
    'aria-label': 'Survey map — use arrow keys to pan, plus/minus to zoom',
  },
  zoomIn: {
    'aria-label': 'Zoom in',
    'aria-keyshortcuts': '+',
  },
  zoomOut: {
    'aria-label': 'Zoom out',
    'aria-keyshortcuts': '-',
  },
  // Tool dock
  toolDock: {
    role: 'toolbar',
    'aria-label': 'Survey tools',
    'aria-orientation': 'vertical',
  },
  // Fieldbook
  fieldbookTable: {
    role: 'grid',
    'aria-label': 'Field book observations',
  },
  fieldbookRow: {
    role: 'row',
  },
  fieldbookCell: {
    role: 'gridcell',
  },
  // Status
  loading: {
    'aria-live': 'polite',
    'aria-busy': 'true',
  },
  error: {
    role: 'alert',
    'aria-live': 'assertive',
  },
  // Navigation
  nav: {
    role: 'navigation',
    'aria-label': 'Main navigation',
  },
  // Buttons
  closeButton: {
    'aria-label': 'Close',
  },
  menuButton: {
    'aria-label': 'Open menu',
    'aria-expanded': false,
  },
}

/**
 * Announce a message to screen readers
 */
export function announce(message: string) {
  const liveRegion = document.createElement('div')
  liveRegion.setAttribute('aria-live', 'polite')
  liveRegion.setAttribute('aria-atomic', 'true')
  liveRegion.className = 'sr-only'
  liveRegion.textContent = message
  document.body.appendChild(liveRegion)

  setTimeout(() => {
    document.body.removeChild(liveRegion)
  }, 1000)
}

'use client';

import { useEffect, useState } from 'react';
import { Wifi, WifiOff, CloudOff, Cloud } from 'lucide-react';

/**
 * Connectivity State Indicator
 * Surveyors need to know whether data is saved locally vs. synced to server.
 * Critical for field use where connectivity is intermittent.
 */
export function ConnectivityIndicator() {
  const [isOnline, setIsOnline] = useState(true);
  const [pendingOps, setPendingOps] = useState(0);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    setIsOnline(navigator.onLine);

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Check pending sync operations periodically
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const checkPending = async () => {
      try {
        const { getPendingOperations } = await import('@/lib/offline/syncQueue');
        const ops = await getPendingOperations();
        setPendingOps(ops.length);
      } catch {
        // Offline module not available — ignore
      }
    };

    checkPending();
    const interval = setInterval(checkPending, 30000);
    return () => clearInterval(interval);
  }, []);

  if (isOnline && pendingOps === 0) {
    return (
      <div className="flex items-center gap-1.5 text-xs text-green-600">
        <Cloud className="h-3.5 w-3.5" />
        <span className="hidden sm:inline">All data synced</span>
      </div>
    );
  }

  if (isOnline && pendingOps > 0) {
    return (
      <div className="flex items-center gap-1.5 text-xs text-yellow-600">
        <Wifi className="h-3.5 w-3.5 animate-pulse" />
        <span className="hidden sm:inline">Syncing {pendingOps} item{pendingOps !== 1 ? 's' : ''}...</span>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-1.5 text-xs text-orange-600">
      <CloudOff className="h-3.5 w-3.5" />
      <span className="hidden sm:inline">Offline — data saved locally</span>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react'
import { AlertTriangle } from 'lucide-react'
import { 
  parseParcelNumber, 
  lookupRegistrationSection, 
  getUTMZoneForParcel,
  type ParsedParcelNumber 
} from '@/lib/compute/parcelNumber'
import { KENYA_COUNTIES, type RegistrationSection } from '@/lib/data/kenyaLocalities'

interface ParcelNumberInputProps {
  value: string
  onChange: (value: string, parsed: ParsedParcelNumber) => void
  onUTMZoneDetected?: (zone: number, hemisphere: 'N' | 'S') => void
  disabled?: boolean
  required?: boolean
}

export default function ParcelNumberInput({ 
  value, 
  onChange, 
  onUTMZoneDetected,
  disabled,
  required 
}: ParcelNumberInputProps) {
  const [parsed, setParsed] = useState<ParsedParcelNumber>(parseParcelNumber(value))
  const [inputMode, setInputMode] = useState<'free' | 'structured'>('free')
  
  // Structured input fields
  const [selectedCounty, setSelectedCounty] = useState('')
  const [selectedSection, setSelectedSection] = useState('')
  const [blockNumber, setBlockNumber] = useState('')
  const [parcelNumber, setParcelNumber] = useState('')

  const sections = selectedCounty 
    ? KENYA_COUNTIES.find((c) => c.code === selectedCounty)?.registrationSections || []
    : []

  const currentSection = sections.find((s) => s.code === selectedSection)

  // Parse free-text input
  useEffect(() => {
    const result = parseParcelNumber(value)
    setParsed(result)
    
    // Update structured fields if we have a match
    if (result.registrationSection) {
      const section = lookupRegistrationSection(result.registrationSection)
      if (section) {
        const county = KENYA_COUNTIES.find((c) => c.code === section.county)
        if (county) {
          setSelectedCounty(county.code)
          setSelectedSection(section.code)
          if (result.block) setBlockNumber(String(result.block))
          if (result.parcelNumber) setParcelNumber(String(result.parcelNumber))
        }
      }
    }
    
    // Auto-detect UTM zone
    if (result.registrationSection && result.isValid) {
      const { zone, hemisphere } = getUTMZoneForParcel(result.registrationSection)
      onUTMZoneDetected?.(zone, hemisphere)
    }
  }, [value, onUTMZoneDetected])

  const handleFreeTextChange = (text: string) => {
    const result = parseParcelNumber(text)
    setParsed(result)
    onChange(text, result)
    
    if (result.registrationSection && result.isValid) {
      const { zone, hemisphere } = getUTMZoneForParcel(result.registrationSection)
      onUTMZoneDetected?.(zone, hemisphere)
    }
  }

  const handleStructuredChange = useCallback(() => {
    if (!selectedSection || !parcelNumber) return
    
    let rawValue: string
    if (currentSection?.hasBlocks && blockNumber) {
      const sectionName = currentSection.name.split(' ')[0]
      rawValue = `${sectionName} BLOCK ${blockNumber}/${parcelNumber}`
    } else {
      rawValue = `${selectedSection}/${parcelNumber}`
    }
    
    const result = parseParcelNumber(rawValue)
    setParsed(result)
    onChange(rawValue, result)
    
    const { zone, hemisphere } = getUTMZoneForParcel(selectedSection)
    onUTMZoneDetected?.(zone, hemisphere)
  }, [selectedSection, blockNumber, parcelNumber, currentSection, onChange, onUTMZoneDetected])

  return (
    <div className="space-y-4">
      {/* Input mode toggle */}
      <div className="flex gap-2 text-sm">
        <button
          type="button"
          onClick={() => setInputMode('free')}
          className={`px-3 py-1 rounded ${inputMode === 'free' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Free Text
        </button>
        <button
          type="button"
          onClick={() => setInputMode('structured')}
          className={`px-3 py-1 rounded ${inputMode === 'structured' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Structured
        </button>
      </div>

      {inputMode === 'free' ? (
        <div>
          <input
            type="text"
            value={value}
            onChange={e => handleFreeTextChange(e.target.value)}
            disabled={disabled}
            required={required}
            aria-label="e.g. NAIROBI BLOCK 2/1234 or KIAMBU/456"
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
          />
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="county">County</label>
            <select id="county"
              value={selectedCounty}
              onChange={e => {
                setSelectedCounty(e.target.value)
                setSelectedSection('')
              }}
              disabled={disabled}
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            >
              <option value="">Select County</option>
              {KENYA_COUNTIES.map((c) => (
                <option key={c.code} value={c.code}>{c.name}</option>
              ))}
            </select>
          </div>
          
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="section">Section</label>
            <select id="section"
              value={selectedSection}
              onChange={e => {
                setSelectedSection(e.target.value)
                handleStructuredChange()
              }}
              disabled={disabled || !selectedCounty}
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            >
              <option value="">Select Section</option>
              {sections.map((s) => (
                <option key={s.code} value={s.code}>{s.name}</option>
              ))}
            </select>
          </div>
          
          {currentSection?.hasBlocks && (
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="block">Block</label>
              <input id="block"
                type="number"
                value={blockNumber}
                onChange={e => {
                  setBlockNumber(e.target.value)
                  handleStructuredChange()
                }}
                disabled={disabled}
 placeholder="1"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
              />
            </div>
          )}
          
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="parcel-no">Parcel No.</label>
            <input id="parcel-no"
              type="number"
              value={parcelNumber}
              onChange={e => {
                setParcelNumber(e.target.value)
                handleStructuredChange()
              }}
              disabled={disabled}
              required={required}
 placeholder="1234"
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            />
          </div>
        </div>
      )}

      {/* Validation feedback */}
      {parsed.isValid ? (
        <div className="p-3 bg-green-50 border border-green-200 rounded-lg">
          <div className="flex items-center gap-2 text-green-700 text-sm">
            <span></span>
            <span>Valid parcel number</span>
          </div>
          {parsed.formatted && (
            <div className="mt-2 text-xs space-y-1">
              <div><span className="text-[var(--text-muted)]">Canonical:</span> {parsed.formatted}</div>
              <div><span className="text-[var(--text-muted)]">Short:</span> {parsed.shortForm}</div>
              {parsed.county && (
                <div><span className="text-[var(--text-muted)]">County:</span> {parsed.county}</div>
              )}
              {parsed.registrationSection && (
                <div><span className="text-[var(--text-muted)]">Section:</span> {parsed.registrationSection}</div>
              )}
              <div className="text-[var(--accent)] font-medium mt-1">
                UTM Zone: {getUTMZoneForParcel(parsed.registrationSection || '').zone}
                {getUTMZoneForParcel(parsed.registrationSection || '').hemisphere}
              </div>
            </div>
          )}
        </div>
      ) : (
        parsed.validationErrors.length > 0 && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center gap-2 text-red-700 text-sm mb-1">
              <span><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /></span>
              <span>Invalid</span>
            </div>
            <ul className="text-xs text-red-600 space-y-1">
              {parsed.validationErrors.map((err, i) => (
                <li key={`${err}-${i}`}>{err}</li>
              ))}
            </ul>
          </div>
        )
      )}
    </div>
  )
}

'use client';

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import {
  VariableSizeList as List,
  type ListChildComponentProps,
} from 'react-window';
import { Checkbox } from '@/components/ui/checkbox';
import { Inbox } from 'lucide-react';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface ColumnDef<T> {
  key: string;
  header: string;
  width: number;
  render?: (row: T) => ReactNode;
  sortable?: boolean;
  align?: 'left' | 'center' | 'right';
}

export interface VirtualizedTableProps<T> {
  rows: T[];
  columns: ColumnDef<T>[];
  /** Fixed row height in px (default 40) */
  rowHeight?: number;
  /** Height of the entire table viewport in px (default 500) */
  tableHeight?: number;
  onRowClick?: (row: T, index: number) => void;
  /** Set of selected row *indices* */
  selectedRows?: Set<number>;
  onSelectionChange?: (selected: Set<number>) => void;
  /** Show the checkbox column (default false) */
  selectable?: boolean;
  /** Stick header row to the top (default true) */
  headerSticky?: boolean;
  /** Unique key per row — defaults to index */
  rowKey?: (row: T, index: number) => string;
  /** Custom empty-state message */
  emptyMessage?: string;
  className?: string;
  /** Accessible label for the table */
  'aria-label'?: string;
}

/* ------------------------------------------------------------------ */
/*  Fallback (non-virtualized) renderer                                */
/* ------------------------------------------------------------------ */

function FallbackTable<T>({
  rows,
  columns,
  rowHeight = 40,
  onRowClick,
  selectedRows,
  onSelectionChange,
  selectable,
  emptyMessage = 'No data',
  rowKey,
}: VirtualizedTableProps<T>) {
  const allSelected = rows.length > 0 && selectedRows && selectedRows.size === rows.length;
  const someSelected = selectedRows && selectedRows.size > 0 && !allSelected;

  const toggleAll = () => {
    if (!onSelectionChange) return;
    if (allSelected) {
      onSelectionChange(new Set());
    } else {
      onSelectionChange(new Set(rows.map((_, i) => i)));
    }
  };

  const toggleRow = (idx: number) => {
    if (!onSelectionChange || !selectedRows) return;
    const next = new Set(selectedRows);
    if (next.has(idx)) next.delete(idx);
    else next.add(idx);
    onSelectionChange(next);
  };

  const totalWidth = columns.reduce((s, c) => s + c.width, 0) + (selectable ? 48 : 0);

  return (
    <div className="overflow-x-auto rounded-lg border border-[var(--border-color)]" style={{ maxHeight: 600 }}>
      <table className="w-full text-sm" style={{ minWidth: totalWidth }}>
        <thead className="sticky top-0 z-10">
          <tr
            className="border-b border-[var(--border-color)] text-left text-xs uppercase tracking-wider text-[var(--text-muted)]"
            style={{ background: 'var(--bg-secondary)' }}
          >
            {selectable && (
              <th className="px-3 py-2 w-12" style={{ width: 48 }}>
                <Checkbox
                  checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                  onCheckedChange={toggleAll}
                  aria-label="Select all rows"
                />
              </th>
            )}
            {columns.map((col) => (
              <th
                key={col.key}
                className="px-3 py-2 font-semibold whitespace-nowrap"
                style={{
                  width: col.width,
                  minWidth: col.width,
                  textAlign: col.align ?? 'left',
                }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr>
              <td
                colSpan={columns.length + (selectable ? 1 : 0)}
                className="py-16 text-center text-[var(--text-muted)]"
              >
                <Inbox className="mx-auto mb-2 h-8 w-8 opacity-40" />
                {emptyMessage}
              </td>
            </tr>
          )}
          {rows.map((row, idx) => {
            const isSelected = selectedRows?.has(idx) ?? false;
            return (
              <tr
                key={rowKey ? rowKey(row, idx) : idx}
                className={`
                  border-b border-[var(--border-color)]/30 transition-colors
                  ${idx % 2 === 0 ? 'bg-[var(--bg-primary)]' : 'bg-[var(--bg-secondary)]'}
                  ${isSelected ? 'bg-[var(--accent-subtle)]' : ''}
                  ${onRowClick ? 'cursor-pointer hover:bg-[var(--accent-subtle)]' : ''}
                `}
                style={{ height: rowHeight }}
                onClick={() => onRowClick?.(row, idx)}
                onKeyDown={(e) => {
                  if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
                    e.preventDefault()
                    onRowClick(row, idx)
                  }
                }}
                tabIndex={onRowClick ? 0 : undefined}
              >
                {selectable && (
                  <td className="px-3 py-2 w-12" onClick={(e) => e.stopPropagation()}>
                    <Checkbox
                      checked={isSelected}
                      onCheckedChange={() => toggleRow(idx)}
                      aria-label={`Select row ${idx + 1}`}
                    />
                  </td>
                )}
                {columns.map((col) => (
                  <td
                    key={col.key}
                    className="px-3 py-2 whitespace-nowrap"
                    style={{ textAlign: col.align ?? 'left' }}
                  >
                    {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
                  </td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Virtualized Table                                                  */
/* ------------------------------------------------------------------ */

function VirtualizedTableInner<T>(props: VirtualizedTableProps<T>) {
  const {
    rows,
    columns,
    rowHeight = 40,
    tableHeight = 500,
    onRowClick,
    selectedRows = new Set(),
    onSelectionChange,
    selectable = false,
    headerSticky = true,
    rowKey,
    emptyMessage = 'No data to display',
    className,
    'aria-label': ariaLabel,
  } = props;

  const listRef = useRef<List>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  /* ---- Responsive width ---- */
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const obs = new ResizeObserver((entries) => {
      setContainerWidth(entries[0]?.contentRect.width ?? 0);
    });
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  /* ---- Derived ---- */
  const totalWidth = useMemo(
    () => columns.reduce((s, c) => s + c.width, 0) + (selectable ? 48 : 0),
    [columns, selectable],
  );
  const needsHorizontalScroll = totalWidth > containerWidth && containerWidth > 0;
  const listWidth = needsHorizontalScroll ? totalWidth : containerWidth;

  const allSelected = rows.length > 0 && selectedRows.size === rows.length;
  const someSelected = selectedRows.size > 0 && !allSelected;

  /* ---- Handlers ---- */
  const toggleAll = useCallback(() => {
    if (!onSelectionChange) return;
    if (allSelected) {
      onSelectionChange(new Set());
    } else {
      onSelectionChange(new Set(rows.map((_, i) => i)));
    }
  }, [allSelected, onSelectionChange, rows]);

  const toggleRow = useCallback(
    (idx: number) => {
      if (!onSelectionChange) return;
      const next = new Set(selectedRows);
      if (next.has(idx)) next.delete(idx);
      else next.add(idx);
      onSelectionChange(next);
    },
    [onSelectionChange, selectedRows],
  );

  /* ---- Row height estimator (constant for now, but VariableSizeList ready) ---- */
  const getRowSize = useCallback(() => rowHeight, [rowHeight]);
  const headerHeight = 42;

  /* ---- Row renderer ---- */
  const Row = useCallback(
    ({ index, style }: ListChildComponentProps) => {
      const row = rows[index];
      const isSelected = selectedRows.has(index);
      const bgClass =
        isSelected
          ? 'bg-[var(--accent-subtle)]'
          : index % 2 === 0
            ? 'bg-[var(--bg-primary)]'
            : 'bg-[var(--bg-secondary)]';

      return (
        <div
          style={{
            ...style,
            display: 'flex',
            alignItems: 'center',
            cursor: onRowClick ? 'pointer' : undefined,
          }}
          className={`
            border-b border-[var(--border-color)]/20 transition-colors
            ${bgClass}
            ${onRowClick ? 'hover:bg-[var(--accent-subtle)]' : ''}
          `}
          onClick={() => onRowClick?.(row, index)}
          onKeyDown={(e) => {
            if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault()
              onRowClick(row, index)
            }
          }}
          tabIndex={onRowClick ? 0 : undefined}
          role="row"
        >
          {selectable && (
            <div
              className="flex items-center justify-center shrink-0"
              style={{ width: 48 }}
              onClick={(e) => e.stopPropagation()}
            >
              <Checkbox
                checked={isSelected}
                onCheckedChange={() => toggleRow(index)}
                aria-label={`Select row ${index + 1}`}
              />
            </div>
          )}
          {columns.map((col) => (
            <div
              key={col.key}
              className="px-3 py-2 text-sm whitespace-nowrap overflow-hidden text-ellipsis"
              style={{
                width: col.width,
                minWidth: col.width,
                textAlign: col.align ?? 'left',
              }}
              role="cell"
            >
              {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
            </div>
          ))}
        </div>
      );
    },
    [rows, columns, selectable, selectedRows, onRowClick, toggleRow],
  );

  /* ---- Scroll-to-row ---- */
  const scrollToRow = useCallback(
    (index: number) => {
      listRef.current?.scrollToItem(index, 'center');
    },
    [],
  );

  // Expose scrollToRow via ref (imperative handle)
  React.useImperativeHandle(
    (props as VirtualizedTableProps<T> & { ref?: React.Ref<{ scrollToRow: (i: number) => void }> }).ref,
    () => ({ scrollToRow }),
    [scrollToRow],
  );

  /* ---- Empty state ---- */
  if (rows.length === 0) {
    return (
      <div
        ref={containerRef}
        className={`rounded-lg border border-[var(--border-color)] flex flex-col items-center justify-center text-[var(--text-muted)] ${className ?? ''}`}
        style={{ height: tableHeight, background: 'var(--bg-primary)' }}
      >
        <Inbox className="h-10 w-10 mb-2 opacity-40" />
        <p className="text-sm">{emptyMessage}</p>
      </div>
    );
  }

  /* ---- Render ---- */
  return (
    <div
      ref={containerRef}
      className={`rounded-lg border border-[var(--border-color)] overflow-hidden ${className ?? ''}`}
      style={{ background: 'var(--bg-primary)' }}
      role="table"
      aria-label={ariaLabel}
      aria-rowcount={rows.length + 1}
      aria-colcount={columns.length + (selectable ? 1 : 0)}
    >
      {/* Sticky header */}
      {headerSticky && (
        <div
          className="flex items-center border-b border-[var(--border-color)] text-xs uppercase tracking-wider text-[var(--text-muted)] shrink-0"
          style={{
            height: headerHeight,
            background: 'var(--bg-secondary)',
            minWidth: needsHorizontalScroll ? totalWidth : undefined,
          }}
          role="row"
        >
          {selectable && (
            <div className="flex items-center justify-center shrink-0" style={{ width: 48 }} role="columnheader">
              <Checkbox
                checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                onCheckedChange={toggleAll}
                aria-label="Select all rows"
              />
            </div>
          )}
          {columns.map((col) => (
            <div
              key={col.key}
              className="px-3 py-2 font-semibold whitespace-nowrap"
              style={{
                width: col.width,
                minWidth: col.width,
                textAlign: col.align ?? 'left',
              }}
              role="columnheader"
              aria-sort={col.sortable ? 'none' : undefined}
            >
              {col.header}
            </div>
          ))}
        </div>
      )}

      {/* Virtualized body — wrap in scroll container for horizontal scroll */}
      <div className={needsHorizontalScroll ? 'overflow-x-auto' : ''}>
        <List
          ref={listRef}
          height={tableHeight - headerHeight}
          itemCount={rows.length}
          itemSize={getRowSize}
          width={listWidth}
          overscanCount={8}
        >
          {Row}
        </List>
      </div>
    </div>
  );
}

