/**
 * VirtualizedTable wraps react-window's VariableSizeList for efficient
 * rendering of large datasets (500+ rows).
 *
 * If react-window fails to load, it falls back to a standard HTML table.
 */
export function VirtualizedTable<T>(props: VirtualizedTableProps<T>) {
  const [useVirtualized, setUseVirtualized] = useState(true);

  useEffect(() => {
    // Verify react-window is actually available at runtime
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const rw = require('react-window') as { VariableSizeList?: unknown };
      if (!rw.VariableSizeList) setUseVirtualized(false);
    } catch {
      setUseVirtualized(false);
    }
  }, []);

  if (!useVirtualized) {
    return <FallbackTable {...props} />;
  }

  return <VirtualizedTableInner {...props} />;
}

export default VirtualizedTable;

'use client'

/**
 * NLIMSExportPanel — UI for generating NLIMS/ArdhiSasa submission payloads
 *
 * Allows the surveyor to:
 * 1. Select submission type (mutation, subdivision, etc.)
 * 2. Enter surveyor info (auto-filled from profile if available)
 * 3. Select parcels to export
 * 4. Run validation
 * 5. Download the NLIMS JSON payload
 *
 * Uses the existing /api/export/nlims endpoint and lib/export/nlimsExporter.
 */

import { useState, useCallback } from 'react'
import {
  FileOutput, Download, Loader2, CheckCircle2, AlertCircle,
  Building2, MapPin, ShieldCheck,
} from 'lucide-react'
import { downloadNLIMSPayload, type NLIMSSubmissionPayload, type NLIMSValidationResult } from '@/lib/export/nlimsExporter'

interface NLIMSExportPanelProps {
  projectId: string
}

export function NLIMSExportPanel({ projectId }: NLIMSExportPanelProps) {
  const [expanded, setExpanded] = useState(false)
  const [generating, setGenerating] = useState(false)
  const [payload, setPayload] = useState<NLIMSSubmissionPayload | null>(null)
  const [validation, setValidation] = useState<NLIMSValidationResult | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Form fields
  const [submissionType, setSubmissionType] = useState<'mutation' | 'subdivision' | 'amalgamation' | 'new_registration' | 'boundary_adjustment'>('subdivision')
  const [registry, setRegistry] = useState('Nairobi')
  const [county, setCounty] = useState('Nairobi')
  const [subCounty, setSubCounty] = useState('')
  const [surveyorName, setSurveyorName] = useState('')
  const [licenseNumber, setLicenseNumber] = useState('')
  const [firm, setFirm] = useState('')

  const handleGenerate = useCallback(async () => {
    setGenerating(true)
    setError(null)
    setPayload(null)
    setValidation(null)

    try {
      const res = await fetch('/api/export/nlims', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          submissionType,
          registry,
          county,
          subCounty,
          surveyor: {
            name: surveyorName,
            licenseNumber,
            firm: firm || undefined,
          },
          resultingParcels: [], // Will be populated from project data
          beacons: [],
          // Parent parcel info would come from the project's existing parcel data
        }),
      })

      const data = (await res.json()) as {
        validation?: NLIMSValidationResult | null
        error?: string
        payload?: NLIMSSubmissionPayload | null
      }

      if (!res.ok) {
        if (data.validation) {
          setValidation(data.validation)
          setError('Validation failed — fix the errors below')
        } else {
          setError(data.error || 'Failed to generate NLIMS payload')
        }
        return
      }

      setPayload(data.payload ?? null)
      setValidation(data.validation ?? null)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Network error')
    } finally {
      setGenerating(false)
    }
  }, [submissionType, registry, county, subCounty, surveyorName, licenseNumber, firm])

  const handleDownload = useCallback(() => {
    if (!payload) return
    downloadNLIMSPayload(payload)
  }, [payload])

  return (
    <div className="mt-6 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-blue-500/10 flex items-center justify-center">
            <Building2 className="w-4 h-4 text-blue-400" />
          </div>
          <div className="text-left">
            <span className="text-sm font-semibold text-[var(--text-primary)]">NLIMS / ArdhiSasa Export</span>
            <p className="text-[10px] text-gray-500">Generate registry-ready JSON submission</p>
          </div>
        </div>
        <svg className={`w-4 h-4 text-gray-500 transition-transform ${expanded ? 'rotate-180' : ''}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M6 9l6 6 6-6" />
        </svg>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)] p-4 space-y-4">
          {/* Submission type */}
          <div>
            <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="submission-type">Submission Type</label>
            <select id="submission-type"
              value={submissionType}
              onChange={e => setSubmissionType(e.target.value as typeof submissionType)}
              className="input h-10 text-sm"
            >
              <option value="subdivision">Subdivision</option>
              <option value="mutation">Mutation</option>
              <option value="amalgamation">Amalgamation</option>
              <option value="new_registration">New Registration</option>
              <option value="boundary_adjustment">Boundary Adjustment</option>
            </select>
          </div>

          {/* Registry info */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="registry">Registry</label>
              <input id="registry"
                type="text"
                value={registry}
                onChange={e => setRegistry(e.target.value)}
                className="input h-10 text-sm"
 placeholder="Nairobi"
              />
            </div>
            <div>
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="county">County</label>
              <input id="county"
                type="text"
                value={county}
                onChange={e => setCounty(e.target.value)}
                className="input h-10 text-sm"
 placeholder="Nairobi"
              />
            </div>
          </div>

          <div>
            <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="sub-county">Sub-County</label>
            <input id="sub-county"
              type="text"
              value={subCounty}
              onChange={e => setSubCounty(e.target.value)}
              className="input h-10 text-sm"
 placeholder="Westlands"
            />
          </div>

          {/* Surveyor info */}
          <div className="pt-2 border-t border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <ShieldCheck className="w-3.5 h-3.5 text-[var(--accent)]" />
              <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">Surveyor Information</span>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="name">Name</label>
                <input id="name"
                  type="text"
                  value={surveyorName}
                  onChange={e => setSurveyorName(e.target.value)}
                  className="input h-10 text-sm"
 placeholder="John Doe"
                />
              </div>
              <div>
                <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="license-no">License No.</label>
                <input id="license-no"
                  type="text"
                  value={licenseNumber}
                  onChange={e => setLicenseNumber(e.target.value)}
                  className="input h-10 text-sm font-mono"
 placeholder="ISK/LS/2021/0452"
                />
              </div>
            </div>
            <div className="mt-2">
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="firm-optional">Firm (optional)</label>
              <input id="firm-optional"
                type="text"
                value={firm}
                onChange={e => setFirm(e.target.value)}
                className="input h-10 text-sm"
 placeholder="Doe Surveyors Ltd"
              />
            </div>
          </div>

          {/* Generate button */}
          <button
            onClick={handleGenerate}
            disabled={generating || !surveyorName || !licenseNumber}
            className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-blue-500 hover:bg-blue-600 text-white text-sm font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {generating ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileOutput className="w-4 h-4" />}
            {generating ? 'Generating...' : 'Generate NLIMS Payload'}
          </button>

          {/* Validation errors */}
          {validation && !validation.isValid && (
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20">
              <div className="flex items-center gap-1.5 mb-1.5">
                <AlertCircle className="w-3.5 h-3.5 text-red-400" />
                <span className="text-xs font-medium text-red-400">Validation Errors</span>
              </div>
              <ul className="text-[11px] text-red-400/80 space-y-0.5 list-disc list-inside">
                {validation.errors.map((e, i) => (
                  <li key={`${e}-${i}`}>{e.message}</li>
                ))}
              </ul>
              {validation.warnings.length > 0 && (
                <div className="mt-2 pt-2 border-t border-red-500/10">
                  <span className="text-[10px] text-amber-400 font-medium">Warnings:</span>
                  <ul className="text-[10px] text-amber-400/70 space-y-0.5 list-disc list-inside mt-0.5">
                    {validation.warnings.map((w, i) => (
                      <li key={`${w}-${i}`}>{w.message}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

          {/* Success + download */}
          {payload && (
            <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                <span className="text-sm font-medium text-emerald-400">Payload Generated</span>
              </div>
              <div className="text-[11px] text-gray-400 space-y-0.5 mb-3">
                <div>Submission ID: <span className="font-mono">{payload.submissionId}</span></div>
                <div>Parcels: {payload.resultingParcels.length}</div>
                <div>Beacons: {payload.beacons.length}</div>
                <div>Integrity: <span className="font-mono">{payload.integrity.hash.substring(0, 16)}...</span></div>
                {payload.areaReconciliation.parentAreaHectares != null && (
                  <div className={payload.areaReconciliation.isWithinTolerance ? 'text-emerald-400' : 'text-red-400'}>
                    Area check: {payload.areaReconciliation.sumOfPartsHectares.toFixed(4)} ha vs parent {payload.areaReconciliation.parentAreaHectares.toFixed(4)} ha
                    ({payload.areaReconciliation.isWithinTolerance ? 'OK' : 'MISMATCH'})
                  </div>
                )}
              </div>
              <button
                onClick={handleDownload}
                className="w-full flex items-center justify-center gap-2 h-9 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-semibold transition-colors"
              >
                <Download className="w-3.5 h-3.5" />
                Download NLIMS JSON
              </button>
            </div>
          )}

          {/* Error */}
          {error && !validation && (
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 flex items-start gap-2">
              <AlertCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
              <p className="text-xs text-red-400">{error}</p>
            </div>
          )}

          {/* Info note */}
          <div className="flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
            <MapPin className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
            <p className="text-[10px] text-blue-400/70 leading-relaxed">
              NLIMS payloads use Arc 1960 / UTM Zone 37S coordinates (EPSG:21037) with 3 decimal places.
              Area reconciliation tolerance: ±0.001 ha (10 m²). SHA-256 integrity hash ensures tamper detection.
            </p>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useEffect } from 'react'
import type { SurveyPlanData, PlanOptions } from '@/lib/reports/surveyPlan/types'
import { SurveyPlanRenderer } from '@/lib/reports/surveyPlan/renderer'
import { FormNo4Renderer } from '@/lib/reports/surveyPlan/formNo4Renderer'
import { SurveyPlanDataSchema } from '@/lib/validation/surveySchema'
import ComplianceChecklistModal from '@/components/ComplianceChecklistModal'
import { AlertCircle, FileCheck, Globe } from 'lucide-react'
import { sanitizeHtml } from '@/lib/security/sanitize'
import { logger } from '@/lib/logger'

interface SurveyPlanViewerProps {
  data: SurveyPlanData
  options?: PlanOptions
  className?: string
  submissionNumber?: string // For Form No. 4
}

const ZOOM_LEVELS = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 4.0]

export default function SurveyPlanViewer({ data, options, className = '', submissionNumber }: SurveyPlanViewerProps) {
  const [scale, setScale] = useState(1.0)
  const [currentSheet, setCurrentSheet] = useState(0)
  const [svgContent, setSvgContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showCompliance, setShowCompliance] = useState(false)
  const [useFormNo4, setUseFormNo4] = useState(true) // Default to Form No. 4 for Kenya
  const containerRef = useRef<HTMLDivElement>(null)
  const rendererRef = useRef<SurveyPlanRenderer | FormNo4Renderer | null>(null)

  useEffect(() => {
    setLoading(true)
    setError(null)

    try {
      // Quality Hardening: Validate data before rendering
      const validation = SurveyPlanDataSchema.safeParse(data)
      if (!validation.success) {
        logger.error('Survey plan data validation failed:', { error: validation.error })
        setError(validation.error.errors[0].message)
        return
      }

      let renderer: SurveyPlanRenderer | FormNo4Renderer
      let content: string

      // Choose renderer based on toggle and data availability
      const hasFormNo4Data = data.project.folioNumber || data.project.registerNumber || data.project.lrNumber
      
      if (useFormNo4 && hasFormNo4Data) {
        // Use Kenya Form No. 4 standard
        renderer = new FormNo4Renderer(data, { ...options, submissionNumber })
        content = (renderer as FormNo4Renderer).renderFormNo4()
      } else {
        // Use standard renderer
        renderer = new SurveyPlanRenderer(data, options)
        content = renderer.render()
      }
      
      rendererRef.current = renderer
      setSvgContent(content)
    } catch (e) {
      logger.error('Survey plan render error:', { error: e })
      setError(e instanceof Error ? e.message : 'Unknown rendering error')
      setSvgContent('')
    } finally {
      setLoading(false)
    }
  }, [data, options, useFormNo4, submissionNumber])

  const zoomIn = () => {
    const idx = ZOOM_LEVELS.findIndex(z => z > scale)
    if (idx !== -1) setScale(ZOOM_LEVELS[idx])
  }
  const zoomOut = () => {
    const idx = ZOOM_LEVELS.findLastIndex(z => z < scale)
    if (idx !== -1) setScale(ZOOM_LEVELS[idx])
  }
  const fitToWidth = () => setScale(1.0)

  const handleDownloadCSV = () => {
    if (!rendererRef.current) return
    const csv = rendererRef.current.exportToCSV()
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `${(data.project.name || 'survey-plan').replace(/\s+/g, '_')}-bearing-schedule.csv`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  const handleDownloadSVG = () => {
    if (!svgContent) return
    const blob = new Blob([svgContent], { type: 'image/svg+xml;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    const suffix = useFormNo4 ? '_FormNo4' : '_Plan'
    link.download = `${data.project.name.replace(/\s+/g, '_')}${suffix}.svg`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  const handlePrint = () => window.print()

  // Check if Form No. 4 data is available
  const hasFormNo4Data = data.project.folioNumber || data.project.registerNumber || data.project.lrNumber

  return (
    <div className={`flex flex-col h-full ${className}`}>
      <div className="flex items-center gap-2 px-3 py-2 border-b border-[var(--border)] bg-[var(--bg-secondary)] no-print">
        <button onClick={zoomOut} disabled={scale <= ZOOM_LEVELS[0]}
          className="px-2 py-1 text-sm rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30">−</button>
        <span className="text-xs font-mono min-w-[48px] text-center">{Math.round(scale * 100)}%</span>
        <button onClick={zoomIn} disabled={scale >= ZOOM_LEVELS[ZOOM_LEVELS.length - 1]}
          className="px-2 py-1 text-sm rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30">+</button>
        <button onClick={fitToWidth}
          className="px-2 py-1 text-xs rounded hover:bg-[var(--bg-tertiary)] border border-[var(--border)]">Fit</button>
        
        <div className="w-px h-6 bg-[var(--border)] mx-2" />
        
        {/* Form No. 4 Toggle */}
        {hasFormNo4Data && (
          <button
            onClick={() => setUseFormNo4(!useFormNo4)}
            className={`flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-lg font-medium transition-colors ${
              useFormNo4 
                ? 'bg-green-600 text-white hover:bg-green-700' 
                : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:bg-[var(--border)]'
            }`}
            title={useFormNo4 ? 'Using Kenya Form No. 4 standard' : 'Using standard plan format'}
          >
            <FileCheck className="w-3.5 h-3.5" />
            {useFormNo4 ? 'Form No. 4 (Kenya)' : 'Standard Plan'}
          </button>
        )}
        
        <div className="flex-1" />
        
        {svgContent && (
          <button onClick={handleDownloadSVG}
            className="px-3 py-1 text-xs rounded bg-[var(--accent)] text-black font-medium hover:opacity-80">
            Download SVG
          </button>
        )}
        <button onClick={handlePrint}
          className="px-3 py-1 text-xs rounded bg-gray-600 text-white hover:opacity-80">
          Print
        </button>
        <button onClick={handleDownloadCSV}
          className="px-3 py-1 text-xs rounded bg-green-600 text-white hover:opacity-80">
          Download CSV
        </button>
        <button onClick={() => setShowCompliance(true)}
          className="px-3 py-1 text-xs rounded bg-[var(--accent)] text-black font-semibold hover:opacity-80">
          Export Plan
        </button>
      </div>
      
      {/* Info banner for Form No. 4 */}
      {useFormNo4 && hasFormNo4Data && (
        <div className="px-3 py-1.5 bg-green-50 border-b border-green-200 flex items-center gap-2">
          <FileCheck className="w-4 h-4 text-green-600" />
          <span className="text-xs text-green-700">
            Kenya Form No. 4 Survey Plan — Compliant with Survey Act Cap. 299 and Survey Regulations 1994
          </span>
          {submissionNumber && (
            <span className="ml-auto text-xs font-mono text-green-600">
              Submission: {submissionNumber}
            </span>
          )}
        </div>
      )}
      
      {svgContent && svgContent.includes('Sheet ') && (
        (() => {
          const match = svgContent.match(/Sheet \d+ of (\d+)/)
          const total = match ? parseInt(match[1], 10) : 1
          return (
            <div className="flex items-center justify-center gap-2 px-3 py-1 border-b border-[var(--border)] bg-[var(--bg-secondary)]">
              <span className="text-xs font-mono text-[var(--text-secondary)]">Sheet {currentSheet + 1} of {total}</span>
              <button onClick={() => setCurrentSheet(Math.max(0, currentSheet - 1))} disabled={currentSheet === 0}
                className="px-2 py-0.5 text-xs rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30 border border-[var(--border)]">&lt;</button>
              <button onClick={() => setCurrentSheet(Math.min(total - 1, currentSheet + 1))} disabled={currentSheet >= total - 1}
                className="px-2 py-0.5 text-xs rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30 border border-[var(--border)]">&gt;</button>
            </div>
          )
        })()
      )}
      
      <div ref={containerRef} className="flex-1 overflow-auto bg-[#e8e8e8] p-4">
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full text-[var(--text-secondary)] gap-3">
            <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
            <div className="font-mono text-xs uppercase tracking-widest">
              {useFormNo4 ? 'Generating Form No. 4 plan...' : 'Generating plan...'}
            </div>
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center h-full max-w-md mx-auto text-center gap-4">
            <div className="p-4 rounded-full bg-red-500/10 text-red-500">
              <AlertCircle className="w-8 h-8" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-red-500 uppercase tracking-tight">Render Failed</h3>
              <p className="text-sm text-[var(--text-secondary)] mt-1">{error}</p>
            </div>
            <button
              onClick={() => {
                setUseFormNo4(false)
                setError(null)
              }}
              className="px-4 py-2 bg-[var(--bg-secondary)] border border-[var(--border)] rounded-lg text-xs font-semibold hover:bg-[var(--bg-tertiary)]"
            >
              Try Standard Format
            </button>
          </div>
        ) : svgContent ? (
          svgContent.includes('Sheet ') ? (
            <div
              className="shadow-lg mx-auto"
              style={{
                width: '1587px',
                height: '1123px',
                overflow: 'hidden',
              }}
            >
              <div
                style={{
                  transform: `translate(${-currentSheet * 1587 * scale}px, 0) scale(${scale})`,
                  transformOrigin: 'top left',
                  position: 'absolute',
                }}
                dangerouslySetInnerHTML={{ __html: sanitizeHtml(svgContent) }}
              />
            </div>
          ) : (
            <div className="shadow-lg mx-auto" style={{ transform: `scale(${scale})`, transformOrigin: 'top center', width: 'fit-content' }}
              dangerouslySetInnerHTML={{ __html: sanitizeHtml(svgContent) }} />
          )
        ) : (
          <div className="flex items-center justify-center h-full text-[var(--text-secondary)]">No plan data available</div>
        )}
      </div>

      <ComplianceChecklistModal
        isOpen={showCompliance}
        onClose={() => setShowCompliance(false)}
        data={data}
        onExport={handlePrint}
      />
    </div>
  )
}

