const CATEGORIES = ['All', 'Calculations', 'Coordinates', 'Engineering', 'Volumes', 'Documents', 'Field Books', 'Validation']

const CATEGORY_ICONS: Record<string, typeof Calculator> = {
  All: Layers,
  Calculations: Calculator,
  Coordinates: Compass,
  Engineering: Building2,
  Volumes: Mountain,
  Documents: FileText,
  'Field Books': FileText,
  Validation: Ruler,
}

export function ProcessingToolbox({ compact = false }: { compact?: boolean }) {
  const router = useRouter()
  const [query, setQuery] = useState('')
  const [activeCategory, setActiveCategory] = useState('All')
  const [favorites, setFavorites] = useState<string[]>([])
  const [recent, setRecent] = useState<string[]>([])

  // Load favorites and recent from localStorage.
  // P1-4 (2026-07-24): Unified with /tools catalog page storage keys.
  // Read from both old (metardu-tool-*) and canonical (metardu-*-tools)
  // keys for backward compat, write only to canonical.
  useEffect(() => {
    const canonicalFav = (JSON.parse(localStorage.getItem('metardu-fav-tools') || '[]') as unknown) as string[]
    const oldFav = (JSON.parse(localStorage.getItem('metardu-tool-favorites') || '[]') as unknown) as string[]
    const fav = Array.from(new Set([...(Array.isArray(canonicalFav) ? canonicalFav : []), ...(Array.isArray(oldFav) ? oldFav : [])]))

    const canonicalRec = (JSON.parse(localStorage.getItem('metardu-recent-tools') || '[]') as unknown) as string[]
    const oldRec = (JSON.parse(localStorage.getItem('metardu-tool-recent') || '[]') as unknown) as string[]
    const rec = Array.from(new Set([...(Array.isArray(canonicalRec) ? canonicalRec : []), ...(Array.isArray(oldRec) ? oldRec : [])]))

    setFavorites(fav)
    setRecent(rec)
  }, [])

  const toggleFavorite = useCallback((toolId: string) => {
    setFavorites(prev => {
      const next = prev.includes(toolId)
        ? prev.filter(id => id !== toolId)
        : [...prev, toolId]
      // Write to canonical key only
      localStorage.setItem('metardu-fav-tools', JSON.stringify(next))
      return next
    })
  }, [])

  const handleToolClick = useCallback((tool: Tool) => {
    // Add to recent
    setRecent(prev => {
      const next = [tool.id, ...prev.filter(id => id !== tool.id)].slice(0, 8)
      // Write to canonical key only
      localStorage.setItem('metardu-recent-tools', JSON.stringify(next))
      return next
    })
    router.push(tool.href)
  }, [router])

  // Filter tools
  const filteredTools = useMemo(() => {
    let result = TOOLS
    if (activeCategory !== 'All') {
      result = result.filter(t => t.category === activeCategory)
    }
    if (query.trim()) {
      const q = query.toLowerCase()
      result = result.filter(t =>
        t.name.toLowerCase().includes(q) ||
        t.description.toLowerCase().includes(q) ||
        t.keywords.some(k => k.includes(q))
      )
    }
    return result
  }, [query, activeCategory])

  // Group by category
  const grouped = useMemo(() => {
    const groups: Record<string, Tool[]> = {}
    for (const tool of filteredTools) {
      if (!groups[tool.category]) groups[tool.category] = []
      groups[tool.category].push(tool)
    }
    return groups
  }, [filteredTools])

  const recentTools = useMemo(() => {
    return recent
      .map(id => TOOLS.find(t => t.id === id))
      .filter((t): t is Tool => t !== undefined)
  }, [recent])

  const favoriteTools = useMemo(() => {
    return favorites
      .map(id => TOOLS.find(t => t.id === id))
      .filter((t): t is Tool => t !== undefined)
  }, [favorites])

  return (
    <div className={`flex flex-col ${compact ? 'h-full' : 'h-[600px]'} bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] overflow-hidden`}>
      {/* Search bar */}
      <div className="p-3 border-b border-[var(--border-color)]">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
          <input
            type="text"
            value={query}
            onChange={e => setQuery(e.target.value)}
            aria-label="Search 60+ tools..."
            className="w-full h-9 pl-9 pr-8 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
          />
          {query && (
            <button
              onClick={() => setQuery('')}
              className="absolute right-2 top-1/2 -translate-y-1/2 w-5 h-5 flex items-center justify-center rounded text-gray-500 hover:text-white"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      </div>

      {/* Category filter */}
      <div className="px-3 py-2 border-b border-[var(--border-color)] flex items-center gap-1.5 overflow-x-auto">
        {CATEGORIES.map(cat => {
          const Icon = CATEGORY_ICONS[cat]
          return (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`flex items-center gap-1 px-2.5 py-1 rounded-lg text-[10px] font-medium whitespace-nowrap transition-colors ${
                activeCategory === cat
                  ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]'
                  : 'text-gray-400 hover:text-gray-300 hover:bg-white/[0.04]'
              }`}
            >
              {Icon && <Icon className="w-3 h-3" />}
              {cat}
            </button>
          )
        })}
      </div>

      {/* Tool list */}
      <div className="flex-1 overflow-y-auto">
        {/* Recent tools */}
        {recentTools.length > 0 && !query && activeCategory === 'All' && (
          <div className="p-3 border-b border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <Clock className="w-3 h-3 text-gray-500" />
              <span className="text-[10px] font-semibold text-gray-400 uppercase tracking-wider">Recent</span>
            </div>
            <div className="space-y-1">
              {recentTools.slice(0, 4).map(tool => (
                <ToolRow
                  key={tool.id}
                  tool={tool}
                  isFavorite={favorites.includes(tool.id)}
                  onToggleFavorite={() => toggleFavorite(tool.id)}
                  onClick={() => handleToolClick(tool)}
                />
              ))}
            </div>
          </div>
        )}

        {/* Favorites */}
        {favoriteTools.length > 0 && !query && activeCategory === 'All' && (
          <div className="p-3 border-b border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <Star className="w-3 h-3 text-amber-400" />
              <span className="text-[10px] font-semibold text-gray-400 uppercase tracking-wider">Favorites</span>
            </div>
            <div className="space-y-1">
              {favoriteTools.map(tool => (
                <ToolRow
                  key={tool.id}
                  tool={tool}
                  isFavorite={true}
                  onToggleFavorite={() => toggleFavorite(tool.id)}
                  onClick={() => handleToolClick(tool)}
                />
              ))}
            </div>
          </div>
        )}

        {/* All tools grouped by category */}
        {Object.entries(grouped).map(([cat, tools]) => (
          <div key={cat} className="p-3 border-b border-[var(--border-color)]/50">
            <div className="flex items-center gap-1.5 mb-2">
              {(() => {
                const Icon = CATEGORY_ICONS[cat] || Calculator
                return <Icon className="w-3 h-3 text-gray-500" />
              })()}
              <span className="text-[10px] font-semibold text-gray-400 uppercase tracking-wider">{cat}</span>
              <span className="text-[9px] text-gray-400">({tools.length})</span>
            </div>
            <div className="space-y-1">
              {tools.map(tool => (
                <ToolRow
                  key={tool.id}
                  tool={tool}
                  isFavorite={favorites.includes(tool.id)}
                  onToggleFavorite={() => toggleFavorite(tool.id)}
                  onClick={() => handleToolClick(tool)}
                />
              ))}
            </div>
          </div>
        ))}

        {/* No results */}
        {filteredTools.length === 0 && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <Search className="w-8 h-8 text-gray-600 mb-2" />
            <p className="text-sm text-gray-500">No tools found for &quot;{query}&quot;</p>
            <p className="text-[10px] text-gray-600 mt-1">Try a different search term</p>
          </div>
        )}
      </div>
    </div>
  )
}

function ToolRow({
  tool,
  isFavorite,
  onToggleFavorite,
  onClick,
}: {
  tool: Tool
  isFavorite: boolean
  onToggleFavorite: () => void
  onClick: () => void
}) {
  const Icon = tool.icon
  return (
    <div
      onClick={onClick}
      className="group flex items-center gap-2.5 p-2 rounded-lg cursor-pointer hover:bg-white/[0.04] transition-colors"
    >
      <div className="shrink-0 w-8 h-8 rounded-lg bg-[var(--accent)]/5 border border-[var(--accent)]/10 flex items-center justify-center">
        <Icon className="w-4 h-4 text-[var(--accent)]" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-xs font-medium text-[var(--text-primary)] truncate">{tool.name}</div>
        <div className="text-[10px] text-gray-400 truncate">{tool.description}</div>
      </div>
      <button
        onClick={(e) => { e.stopPropagation(); onToggleFavorite() }}
        aria-label={isFavorite ? `Remove ${tool.name} from favorites` : `Add ${tool.name} to favorites`}
        className="shrink-0 w-6 h-6 flex items-center justify-center rounded opacity-0 group-hover:opacity-100 transition-opacity"
      >
        <Star className={`w-3.5 h-3.5 ${isFavorite ? 'fill-amber-400 text-amber-400' : 'text-gray-400 hover:text-amber-400'}`} />
      </button>
      <ChevronRight className="w-3.5 h-3.5 text-gray-400 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity" />
    </div>
  )
}

'use client';

/**
 * SpiralAlignmentTab — Tier 2 UI for the spiral-to-curve alignment engine.
 *
 * Roadmap reference: docs/ROADMAP.md → Tier 2 → "Spiral-to-curve alignment
 * engine". Renders as a 5th tab on `/tools/curves`.
 *
 * Inputs:  radius, intersection angle, spiral length, PI chainage,
 *          optional PI coordinates + approach bearing for world coords.
 * Outputs: TS/SC/CS/ST stations, T/Lc/p/k/θs, SVG plan diagram,
 *          station table, CSV export.
 */

import { useState, useMemo } from 'react';
import { PageHeader } from '@/components/shared/PageHeader';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Download, Spline, AlertTriangle, MapPin, Copy } from 'lucide-react';
import { downloadCSV } from '@/lib/export/helpers';
import {
  computeSpiralAlignment,
  stationSpiralAlignment,
  alignmentToCoordinateArray,
  spiralAlignmentToCSV,
  type SpiralAlignmentResult,
} from '@/lib/survey/curves/spiralAlignment';

export function SpiralAlignmentTab() {
  const [input, setInput] = useState({
    radius: '300',
    intersectionAngleDeg: '30',
    spiralLength: '60',
    piChainage: '1000',
    approachBearingDeg: '0',
    piEasting: '',
    piNorthing: '',
  });
  const [result, setResult] = useState<SpiralAlignmentResult | null>(null);
  const [error, setError] = useState('');

  const compute = () => {
    setError('');
    try {
      const r = computeSpiralAlignment({
        radius: Number(input.radius),
        intersectionAngleDeg: Number(input.intersectionAngleDeg),
        spiralLength: Number(input.spiralLength),
        piChainage: Number(input.piChainage),
        approachBearingDeg: input.approachBearingDeg
          ? Number(input.approachBearingDeg)
          : undefined,
        piEasting: input.piEasting ? Number(input.piEasting) : undefined,
        piNorthing: input.piNorthing ? Number(input.piNorthing) : undefined,
      });
      setResult(r);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setResult(null);
    }
  };

  const stations = useMemo(() => {
    if (!result) return [];
    return stationSpiralAlignment(result, 10);
  }, [result]);

  const exportCSV = () => {
    if (stations.length === 0) return;
    downloadCSV(spiralAlignmentToCSV(stations), `spiral-alignment-${Date.now()}.csv`);
  };

  const exportGeoJSON = () => {
    if (!result) return;
    const coords = alignmentToCoordinateArray(result, 2);
    if (coords.length < 2) return;
    const gj = {
      type: 'FeatureCollection',
      features: [
        {
          type: 'Feature' as const,
          geometry: { type: 'LineString' as const, coordinates: coords },
          properties: {
            type: 'spiral-alignment',
            radius: result.input.radius,
            intersection_angle_deg: result.input.intersectionAngleDeg,
            spiral_length: result.input.spiralLength,
            total_length: result.totalLength,
            ts_chainage: result.tsChainage,
            sc_chainage: result.scChainage,
            cs_chainage: result.csChainage,
            st_chainage: result.stChainage,
          },
        },
        // Key station points as separate Features
        ...(
          [
            ['TS', result.tsChainage, result.tsCoord],
            ['SC', result.scChainage, result.scCoord],
            ['CS', result.csChainage, result.csCoord],
            ['ST', result.stChainage, result.stCoord],
            ['PI', result.input.piChainage, result.piCoord],
          ] as const
        )
          .filter(([, , coord]) => coord !== null)
          .map(([label, chainage, coord]) => ({
            type: 'Feature' as const,
            geometry: {
              type: 'Point' as const,
              coordinates: [coord?.easting ?? 0, coord?.northing ?? 0],
            },
            properties: { label, chainage },
          })),
      ],
    };
    const blob = new Blob([JSON.stringify(gj, null, 2)], {
      type: 'application/geo+json',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `spiral-alignment-${Date.now()}.geojson`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const copyCoords = async () => {
    if (!result) return;
    const coords = alignmentToCoordinateArray(result, 2);
    if (coords.length < 2) return;
    // Format as JSON array for direct paste into OpenLayers code:
    //   new LineString([[e, n], [e, n], ...])
    const text = JSON.stringify(coords);
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // Fallback for browsers without clipboard API
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
    }
  };

  return (
    <div className="space-y-6">
      {/* Inputs */}
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-5">
        <div className="flex items-center gap-2 mb-4">
          <Spline className="w-4 h-4 text-[var(--accent)]" />
          <h3 className="font-display text-lg text-[var(--text-primary)]">
            Spiral-to-Curve Alignment
          </h3>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <Field
            label="Radius R (m)"
            value={input.radius}
            onChange={v => setInput({ ...input, radius: v })}
          />
          <Field
            label="Intersection Δ (deg)"
            value={input.intersectionAngleDeg}
            onChange={v => setInput({ ...input, intersectionAngleDeg: v })}
          />
          <Field
            label="Spiral length Ls (m)"
            value={input.spiralLength}
            onChange={v => setInput({ ...input, spiralLength: v })}
          />
          <Field
            label="PI chainage (m)"
            value={input.piChainage}
            onChange={v => setInput({ ...input, piChainage: v })}
          />
          <Field
            label="Approach bearing (deg, opt)"
            value={input.approachBearingDeg}
            onChange={v => setInput({ ...input, approachBearingDeg: v })}
          />
          <Field
            label="PI easting (opt)"
            value={input.piEasting}
            onChange={v => setInput({ ...input, piEasting: v })}
          />
          <Field
            label="PI northing (opt)"
            value={input.piNorthing}
            onChange={v => setInput({ ...input, piNorthing: v })}
          />
        </div>

        {error && (
          <div className="mt-3 bg-red-950/30 border border-red-800/50 text-red-300 text-xs p-3 rounded flex items-start gap-2">
            <AlertTriangle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0" />
            <span className="font-mono">{error}</span>
          </div>
        )}

        <Button onClick={compute} className="mt-4" size="sm">
          Compute Alignment
        </Button>
      </div>

      {/* Results */}
      {result && (
        <>
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-5">
            <h3 className="font-display text-lg text-[var(--text-primary)] mb-3">
              Key Stations & Geometry
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
              <Stat label="TS chainage" value={`${result.tsChainage.toFixed(3)} m`} />
              <Stat label="SC chainage" value={`${result.scChainage.toFixed(3)} m`} />
              <Stat label="CS chainage" value={`${result.csChainage.toFixed(3)} m`} />
              <Stat label="ST chainage" value={`${result.stChainage.toFixed(3)} m`} />
              <Stat label="Tangent T" value={`${result.T.toFixed(3)} m`} />
              <Stat label="Curve length Lc" value={`${result.Lc.toFixed(3)} m`} />
              <Stat label="Total length" value={`${result.totalLength.toFixed(3)} m`} />
              <Stat label="Spiral angle θs" value={`${((result.thetaSRad * 180) / Math.PI).toFixed(4)}°`} />
              <Stat label="Tangent shift p" value={`${result.p.toFixed(4)} m`} />
              <Stat label="Tangent extension k" value={`${result.k.toFixed(4)} m`} />
              <Stat label="Δ (rad)" value={`${result.deltaRad.toFixed(6)}`} />
              <Stat label="θs (rad)" value={`${result.thetaSRad.toFixed(6)}`} />
            </div>
          </div>

          {/* SVG plan diagram */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-5">
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-display text-lg text-[var(--text-primary)]">
                Plan Diagram
              </h3>
              <div className="flex gap-2 text-xs text-[var(--text-muted)]">
                <span className="flex items-center gap-1">
                  <span className="inline-block w-3 h-0.5 bg-[var(--accent)]" /> Alignment
                </span>
                <span className="flex items-center gap-1">
                  <span className="inline-block w-2 h-2 rounded-full bg-amber-400" /> TS/ST
                </span>
                <span className="flex items-center gap-1">
                  <span className="inline-block w-2 h-2 rounded-full bg-cyan-400" /> SC/CS
                </span>
                <span className="flex items-center gap-1">
                  <span className="inline-block w-2 h-2 rounded-full bg-red-400" /> PI
                </span>
              </div>
            </div>
            <SpiralPlanDiagram result={result} />
          </div>

          {/* Station table */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-5">
            <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
              <h3 className="font-display text-lg text-[var(--text-primary)]">
                Station Table ({stations.length} rows)
              </h3>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={copyCoords} title="Copy coordinate array for OpenLayers LineString">
                  <Copy className="w-3 h-3 mr-1" /> Coords
                </Button>
                <Button variant="outline" size="sm" onClick={exportGeoJSON} title="Download as GeoJSON FeatureCollection (LineString + key stations)">
                  <MapPin className="w-3 h-3 mr-1" /> GeoJSON
                </Button>
                <Button variant="outline" size="sm" onClick={exportCSV}>
                  <Download className="w-3 h-3 mr-1" /> CSV
                </Button>
              </div>
            </div>
            <div className="overflow-x-auto max-h-96 overflow-y-auto">
              <table className="w-full text-xs">
                <thead className="sticky top-0 bg-[var(--bg-card)]">
                  <tr className="text-[var(--text-muted)] uppercase tracking-wide border-b border-[var(--border-color)]">
                    <th className="text-right py-2 pr-3 font-medium">Chainage (m)</th>
                    <th className="text-right py-2 px-3 font-medium">Dist from TS</th>
                    <th className="text-right py-2 px-3 font-medium">Easting</th>
                    <th className="text-right py-2 px-3 font-medium">Northing</th>
                    <th className="text-right py-2 px-3 font-medium">Offset (m)</th>
                    <th className="text-right py-2 px-3 font-medium">Defl. (°)</th>
                    <th className="text-left py-2 pl-3 font-medium">Segment</th>
                  </tr>
                </thead>
                <tbody>
                  {stations.map((s, i) => (
                    <tr
                      key={i}
                      className={`border-b border-[var(--border-color)] last:border-b-0 ${
                        s.segment === 'circular'
                          ? 'bg-[var(--bg-secondary)]'
                          : s.segment === 'entry-spiral'
                            ? 'bg-cyan-950/10'
                            : s.segment === 'exit-spiral'
                              ? 'bg-amber-950/10'
                              : ''
                      }`}
                    >
                      <td className="py-1.5 pr-3 text-right font-mono">{s.chainage.toFixed(3)}</td>
                      <td className="py-1.5 px-3 text-right font-mono">{s.distanceFromTS.toFixed(3)}</td>
                      <td className="py-1.5 px-3 text-right font-mono">{s.easting.toFixed(3)}</td>
                      <td className="py-1.5 px-3 text-right font-mono">{s.northing.toFixed(3)}</td>
                      <td className="py-1.5 px-3 text-right font-mono">{s.offset.toFixed(3)}</td>
                      <td className="py-1.5 px-3 text-right font-mono">{s.deflectionDeg.toFixed(4)}</td>
                      <td className="py-1.5 pl-3">
                        <span
                          className={`text-[10px] uppercase tracking-wide ${
                            s.segment === 'circular'
                              ? 'text-[var(--accent)]'
                              : s.segment.includes('spiral')
                                ? 'text-cyan-400'
                                : 'text-[var(--text-muted)]'
                          }`}
                        >
                          {s.segment}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function Field({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <div>
      <Label className="text-xs text-[var(--text-muted)]">{label}</Label>
      <Input
        type="number"
        step="any"
        value={value}
        onChange={e => onChange(e.target.value)}
        className="mt-1 font-mono text-sm bg-[var(--bg-secondary)] border-[var(--border-color)]"
      />
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="bg-[var(--bg-secondary)] rounded p-2">
      <div className="text-[var(--text-muted)] text-[10px] uppercase tracking-wide">
        {label}
      </div>
      <div className="font-mono text-[var(--text-primary)] text-sm mt-0.5">{value}</div>
    </div>
  );
}

// ─── Plan Diagram ───────────────────────────────────────────────────────────

function SpiralPlanDiagram({ result }: { result: SpiralAlignmentResult }) {
  const WIDTH = 800;
  const HEIGHT = 400;
  const PAD = 40;

  // Get alignment coordinates (local frame if no PI)
  const coords = useMemo(
    () => alignmentToCoordinateArray(result, 2),
    [result]
  );

  if (coords.length < 2) {
    return <p className="text-xs text-[var(--text-muted)]">No coordinates to plot.</p>;
  }

  // Compute scale to fit
  const xs = coords.map(c => c[0]);
  const ys = coords.map(c => c[1]);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);
  const dx = maxX - minX || 1;
  const dy = maxY - minY || 1;
  const scale = Math.min((WIDTH - 2 * PAD) / dx, (HEIGHT - 2 * PAD) / dy);
  const offsetX = (WIDTH - dx * scale) / 2;
  const offsetY = (HEIGHT - dy * scale) / 2;

  const tx = (x: number) => offsetX + (x - minX) * scale;
  // Invert Y because SVG Y grows downward
  const ty = (y: number) => HEIGHT - offsetY - (y - minY) * scale;

  const pathD = coords
    .map((c, i) => `${i === 0 ? 'M' : 'L'} ${tx(c[0]).toFixed(1)} ${ty(c[1]).toFixed(1)}`)
    .join(' ');

  // Tangent lines (approach and departure)
  const ts = coords[0];
  const st = coords[coords.length - 1];
  // Approach tangent: extend backward from TS
  const approachDx = (coords[1][0] - ts[0]) * 5;
  const approachDy = (coords[1][1] - ts[1]) * 5;
  const approachEnd = [ts[0] - approachDx, ts[1] - approachDy];
  // Departure tangent: extend forward from ST
  const depDx = (st[0] - coords[coords.length - 2][0]) * 5;
  const depDy = (st[1] - coords[coords.length - 2][1]) * 5;
  const depStart = [st[0] + depDx, st[1] + depDy];

  // PI = intersection of tangents
  // Simplified: assume PI is somewhere "above" the alignment center
  // For visualization, just mark SC and CS
  const scIdx = Math.floor(result.spiral.spiralLength / 2); // approx index for SC
  const sc = coords[Math.min(scIdx, coords.length - 1)];
  const cs = coords[Math.max(coords.length - 1 - scIdx, 0)];

  return (
    <svg
      viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
      className="w-full h-auto"
      style={{ minWidth: 500 }}
    >
      {/* Approach tangent */}
      <line
        x1={tx(ts[0])}
        y1={ty(ts[1])}
        x2={tx(approachEnd[0])}
        y2={ty(approachEnd[1])}
        stroke="#71717a"
        strokeWidth="1"
        strokeDasharray="4,3"
        opacity="0.6"
      />
      {/* Departure tangent */}
      <line
        x1={tx(st[0])}
        y1={ty(st[1])}
        x2={tx(depStart[0])}
        y2={ty(depStart[1])}
        stroke="#71717a"
        strokeWidth="1"
        strokeDasharray="4,3"
        opacity="0.6"
      />
      {/* Alignment */}
      <path d={pathD} fill="none" stroke="var(--accent)" strokeWidth="2.5" />

      {/* TS marker */}
      <g>
        <circle cx={tx(ts[0])} cy={ty(ts[1])} r="6" fill="#fbbf24" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(ts[0])} y={ty(ts[1]) - 12} textAnchor="middle" fontSize="11" fill="#fbbf24" fontFamily="monospace">
          TS
        </text>
      </g>
      {/* SC marker */}
      <g>
        <circle cx={tx(sc[0])} cy={ty(sc[1])} r="5" fill="#22d3ee" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(sc[0])} y={ty(sc[1]) - 10} textAnchor="middle" fontSize="10" fill="#22d3ee" fontFamily="monospace">
          SC
        </text>
      </g>
      {/* CS marker */}
      <g>
        <circle cx={tx(cs[0])} cy={ty(cs[1])} r="5" fill="#22d3ee" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(cs[0])} y={ty(cs[1]) - 10} textAnchor="middle" fontSize="10" fill="#22d3ee" fontFamily="monospace">
          CS
        </text>
      </g>
      {/* ST marker */}
      <g>
        <circle cx={tx(st[0])} cy={ty(st[1])} r="6" fill="#fbbf24" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(st[0])} y={ty(st[1]) - 12} textAnchor="middle" fontSize="11" fill="#fbbf24" fontFamily="monospace">
          ST
        </text>
      </g>
    </svg>
  );
}

'use client';

/**
 * OrthophotoOverlay — renders an orthophoto image as background layer
 * on the topo canvas, under contours and spot heights.
 *
 * The surveyor uploads a GeoTIFF/PNG orthophoto from their drone
 * processing software (Pix4D, DroneDeploy, Agisoft). The image is
 * georeferenced using corner coordinates and rendered as a canvas
 * background layer.
 *
 * The topo canvas then shows:
 *   [orthophoto image] → [contour lines] → [spot heights] → [labels]
 *
 * This gives the surveyor a real-world visual reference for their
 * contour plan — they can see if contours follow the actual terrain.
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import { logger } from '@/lib/logger'

export interface OrthophotoBounds {
  minEasting: number
  maxEasting: number
  minNorthing: number
  maxNorthing: number
}

interface OrthophotoOverlayProps {
  imageUrl: string | null          // data URL or blob URL
  bounds: OrthophotoBounds | null  // geo bounds of the image
  canvasWidth: number
  canvasHeight: number
  viewBounds: OrthophotoBounds     // current view bounds
  opacity?: number                 // 0-1, default 0.6
}

export function OrthophotoOverlay({
  imageUrl,
  bounds,
  canvasWidth,
  canvasHeight,
  viewBounds,
  opacity = 0.6,
}: OrthophotoOverlayProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [imgLoaded, setImgLoaded] = useState(false)
  const imgRef = useRef<HTMLImageElement | null>(null)

  // Load image
  useEffect(() => {
    if (!imageUrl) {
      setImgLoaded(false)
      return
    }

    const img = new Image()
    img.onload = () => {
      imgRef.current = img
      setImgLoaded(true)
    }
    img.onerror = () => {
      logger.error('[OrthophotoOverlay] Failed to load image')
      setImgLoaded(false)
    }
    img.src = imageUrl
  }, [imageUrl])

  // Render to canvas
  useEffect(() => {
    if (!imgLoaded || !imgRef.current || !bounds || !canvasRef.current) return

    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    canvas.width = canvasWidth
    canvas.height = canvasHeight

    // Calculate scale: how many pixels per meter
    const viewWidthM = viewBounds.maxEasting - viewBounds.minEasting
    const viewHeightM = viewBounds.maxNorthing - viewBounds.minNorthing
    const scaleX = canvasWidth / viewWidthM
    const scaleY = canvasHeight / viewHeightM

    // Calculate image position on canvas
    const imgMinX = (bounds.minEasting - viewBounds.minEasting) * scaleX
    const imgMaxX = (bounds.maxEasting - viewBounds.minEasting) * scaleX
    // Y is inverted (canvas Y goes down, northing goes up)
    const imgMinY = canvasHeight - (bounds.maxNorthing - viewBounds.minNorthing) * scaleY
    const imgMaxY = canvasHeight - (bounds.minNorthing - viewBounds.minNorthing) * scaleY

    const destX = Math.max(0, imgMinX)
    const destY = Math.max(0, imgMinY)
    const destW = Math.min(canvasWidth, imgMaxX) - destX
    const destH = Math.min(canvasHeight, imgMaxY) - destY

    if (destW <= 0 || destH <= 0) return

    // Source crop (which part of the image is visible)
    const imgW = imgRef.current.width
    const imgH = imgRef.current.height
    const srcMinX = Math.max(0, (viewBounds.minEasting - bounds.minEasting) / (bounds.maxEasting - bounds.minEasting)) * imgW
    const srcMaxX = Math.min(1, (viewBounds.maxEasting - bounds.minEasting) / (bounds.maxEasting - bounds.minEasting)) * imgW
    const srcMinY = Math.max(0, (bounds.maxNorthing - viewBounds.maxNorthing) / (bounds.maxNorthing - bounds.minNorthing)) * imgH
    const srcMaxY = Math.min(1, (bounds.maxNorthing - viewBounds.minNorthing) / (bounds.maxNorthing - bounds.minNorthing)) * imgH

    const srcW = srcMaxX - srcMinX
    const srcH = srcMaxY - srcMinY

    if (srcW <= 0 || srcH <= 0) return

    ctx.globalAlpha = opacity
    ctx.drawImage(imgRef.current, srcMinX, srcMinY, srcW, srcH, destX, destY, destW, destH)
    ctx.globalAlpha = 1
  }, [imgLoaded, bounds, canvasWidth, canvasHeight, viewBounds, opacity])

  if (!imageUrl || !bounds) return null

  return (
    <canvas
      ref={canvasRef}
      width={canvasWidth}
      height={canvasHeight}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        pointerEvents: 'none',
      }}
    />
  )
}

/**
 * Helper: load a GeoTIFF file and extract bounds + image data.
 * ponytail: uses the browser's built-in Image API for PNG/JPEG.
 * For GeoTIFF, use a library like geotiff.js (not installed yet).
 * For now, the surveyor provides the image + bounds manually.
 */
export async function loadOrthophoto(
  file: File,
  bounds: OrthophotoBounds,
): Promise<{ url: string; bounds: OrthophotoBounds }> {
  const url = URL.createObjectURL(file)
  return { url, bounds }
}

