'use client';

import { useState, useRef, useCallback } from 'react'
import { Upload, File, AlertCircle, CheckCircle, Loader2 } from 'lucide-react'

interface UploadZoneProps {
  onUploadComplete?: (result: UploadResult) => void
  accept?: string
  maxSize?: number
}

interface UploadResult {
  success: boolean
  type: string
  confidence: number
  hasBuilding: boolean
  hasBoq: boolean
  errors: string[]
  warnings: string[]
  building?: {
    floors: number
    walls: number
    rooms: number
    doors: number
    windows: number
  }
  boq?: {
    items: number
    total: number
  }
}

export default function UploadZone({ 
  onUploadComplete,
  accept = '.dxf,.dwg,.ifc,.pdf,.jpg,.jpeg,.png,.webp,.glb,.gltf,.obj,.xlsx,.xls,.csv',
  maxSize = 100 * 1024 * 1024
}: UploadZoneProps) {
  const [isDragging, setIsDragging] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState('')
  const [result, setResult] = useState<UploadResult | null>(null)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleFile = useCallback(async (file: File) => {
    if (file.size > maxSize) {
      setError(`File too large. Max size is ${maxSize / 1024 / 1024}MB`)
      return
    }

    setUploading(true)
    setError(null)
    setResult(null)
    setProgress('Reading file...')

    try {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('enhanceWithAI', 'true')

      setProgress('Parsing...')
      
      const response = await fetch('/api/parsers/upload', {
        method: 'POST',
        body: formData,
      })

      const data = (await response.json()) as UploadResult & { error?: string }

      if (!response.ok) {
        throw new Error(data.error || 'Upload failed')
      }

      setResult(data)
      onUploadComplete?.(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed')
    } finally {
      setUploading(false)
      setProgress('')
    }
  }, [maxSize, onUploadComplete])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(true)
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
  }, [])

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) handleFile(file)
  }, [handleFile])

  const getFileIcon = (filename: string) => {
    const ext = filename.split('.').pop()?.toLowerCase()
    const colors: Record<string, string> = {
      dxf: 'text-blue-400',
      dwg: 'text-blue-500',
      ifc: 'text-purple-400',
      pdf: 'text-red-400',
      jpg: 'text-green-400',
      jpeg: 'text-green-400',
      png: 'text-green-400',
      webp: 'text-green-400',
      glb: 'text-amber-400',
      gltf: 'text-amber-400',
      obj: 'text-amber-500',
      xlsx: 'text-emerald-400',
      xls: 'text-emerald-500',
      csv: 'text-emerald-600',
    }
    return colors[ext || ''] || 'text-gray-400'
  }

  return (
    <div className="space-y-4">
      <div
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => inputRef.current?.click()}
        className={`
          border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all
          ${isDragging 
            ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
            : 'border-[var(--border-color)] hover:border-[var(--accent)] hover:bg-[var(--bg-secondary)]/50'}
        `}
      >
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          onChange={handleChange}
          className="hidden"
        />
        
        <div className="flex flex-col items-center gap-3">
          {uploading ? (
            <>
              <Loader2 className="w-10 h-10 text-[var(--accent)] animate-spin" />
              <p className="text-sm text-[var(--text-secondary)]">{progress || 'Processing...'}</p>
            </>
          ) : (
            <>
              <Upload className={`w-10 h-10 ${isDragging ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
              <div>
                <p className="text-sm font-medium text-[var(--text-primary)]">
                  Drop file here or click to upload
                </p>
                <p className="text-xs text-[var(--text-muted)] mt-1">
                  DXF, DWG, IFC, PDF, Images, 3D Models, BOQ (max 100MB)
                </p>
              </div>
            </>
          )}
        </div>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-900/20 border border-red-700/40">
          <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {result && (
        <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-secondary)]/50 p-4 space-y-3">
          <div className="flex items-center gap-2">
            {result.success ? (
              <CheckCircle className="w-5 h-5 text-green-400" />
            ) : (
              <AlertCircle className="w-5 h-5 text-yellow-400" />
            )}
            <span className="font-medium text-[var(--text-primary)]">
              {result.success ? 'Parse Complete' : 'Parse with Issues'}
            </span>
            <span className="ml-auto text-sm text-[var(--text-muted)]">
              {result.type}
            </span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-sm">
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
              <div className="text-[var(--text-muted)] text-xs">Confidence</div>
              <div className="font-medium text-[var(--text-primary)]">
                {Math.round(result.confidence * 100)}%
              </div>
            </div>
            {result.building && (
              <>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Walls</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.building.walls}</div>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Rooms</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.building.rooms}</div>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Floors</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.building.floors}</div>
                </div>
              </>
            )}
            {result.boq && (
              <>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">BOQ Items</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.boq.items}</div>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Total</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.boq.total.toLocaleString()}</div>
                </div>
              </>
            )}
          </div>

          {result.warnings.length > 0 && (
            <div className="text-xs text-[var(--text-muted)]">
              <span className="font-medium">Warnings:</span> {result.warnings.join(', ')}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client';

/**
 * VersionDiffViewer — visual comparison of two survey plan versions
 *
 * Shows side-by-side:
 * - Beacon coordinate changes (highlighted in red/green)
 * - Boundary bearing/distance changes
 * - Area changes
 * - Metadata changes (LR number, client, etc.)
 *
 * The surveyor can see exactly what changed between revisions
 * and restore a previous version with one click.
 */

import { useState, useEffect, useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { RotateCcw, GitCompare, ArrowRight, Check } from 'lucide-react'
import { logger } from '@/lib/logger'

interface VersionData {
  version: number
  createdAt: string
  createdBy: string
  data: {
    beacons?: Array<{ id: string; label: string; easting: number; northing: number }>
    boundaries?: Array<{ id: string; fromId: string; toId: string; bearing: string; distance: string }>
    area?: number
    lrNumber?: string
    clientName?: string
  }
}

interface DiffResult {
  beaconChanges: Array<{
    id: string; label: string
    oldEasting?: number; newEasting?: number
    oldNorthing?: number; newNorthing?: number
    deltaE: number; deltaN: number
    status: 'added' | 'removed' | 'moved' | 'unchanged'
  }>
  boundaryChanges: Array<{
    id: string
    oldBearing?: string; newBearing?: string
    oldDistance?: string; newDistance?: string
    status: 'added' | 'removed' | 'changed' | 'unchanged'
  }>
  metadataChanges: Array<{ field: string; oldValue: string; newValue: string }>
  areaChange: { old: number; new: number; delta: number }
}

interface VersionDiffViewerProps {
  entityType: string
  entityId: string
  onRestore?: (version: number) => void
}

export function VersionDiffViewer({ entityType, entityId, onRestore }: VersionDiffViewerProps) {
  const [versions, setVersions] = useState<VersionData[]>([])
  const [selectedOld, setSelectedOld] = useState<number | null>(null)
  const [selectedNew, setSelectedNew] = useState<number | null>(null)
  const [diff, setDiff] = useState<DiffResult | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function loadVersions() {
      try {
        const res = await fetch(`/api/versions?entity_type=${entityType}&entity_id=${entityId}&limit=50`)
        const data = (await res.json()) as { data?: VersionData[] }
        if (data.data) {
          setVersions(data.data)
          if (data.data.length >= 2) {
            setSelectedOld(data.data[data.data.length - 2].version)
            setSelectedNew(data.data[data.data.length - 1].version)
          }
        }
      } catch (err) {
        logger.error('Failed to load versions:', { error: err })
      } finally {
        setLoading(false)
      }
    }
    loadVersions()
  }, [entityType, entityId])

  useEffect(() => {
    if (selectedOld === null || selectedNew === null) return
    const oldVer = versions.find(v => v.version === selectedOld)
    const newVer = versions.find(v => v.version === selectedNew)
    if (!oldVer || !newVer) return
    setDiff(computeDiff(oldVer, newVer))
  }, [selectedOld, selectedNew, versions])

  const handleRestore = useCallback(() => {
    if (selectedOld !== null && onRestore) onRestore(selectedOld)
  }, [selectedOld, onRestore])

  if (loading) return <div className="text-sm text-gray-500 p-4">Loading version history...</div>

  if (versions.length < 2) {
    return (
      <div className="text-sm text-gray-500 p-4 text-center">
        <GitCompare className="w-8 h-8 mx-auto mb-2 opacity-30" />
        Need at least 2 versions to compare. Current: {versions.length} version(s).
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <select value={selectedOld ?? ''} onChange={(e) => setSelectedOld(Number(e.target.value))} className="bg-gray-800 text-white text-xs rounded px-2 py-1 border border-gray-700">
          {versions.map(v => <option key={v.version} value={v.version}>v{v.version} — {new Date(v.createdAt).toLocaleDateString()}</option>)}
        </select>
        <ArrowRight className="w-4 h-4 text-gray-500" />
        <select value={selectedNew ?? ''} onChange={(e) => setSelectedNew(Number(e.target.value))} className="bg-gray-800 text-white text-xs rounded px-2 py-1 border border-gray-700">
          {versions.map(v => <option key={v.version} value={v.version}>v{v.version} — {new Date(v.createdAt).toLocaleDateString()}</option>)}
        </select>
        <Button variant="outline" size="sm" onClick={handleRestore} className="text-xs ml-auto">
          <RotateCcw className="w-3 h-3 mr-1" /> Restore v{selectedOld}
        </Button>
      </div>

      {diff && (
        <div className="space-y-3">
          <div className="flex gap-2 flex-wrap">
            <Badge variant={diff.beaconChanges.filter(c => c.status !== 'unchanged').length > 0 ? 'destructive' : 'secondary'} className="text-xs">
              {diff.beaconChanges.filter(c => c.status === 'moved').length} moved beacons
            </Badge>
            <Badge variant={diff.metadataChanges.length > 0 ? 'destructive' : 'secondary'} className="text-xs">
              {diff.metadataChanges.length} metadata changes
            </Badge>
            <Badge variant="outline" className="text-xs">
              Area: {diff.areaChange.old.toFixed(4)} → {diff.areaChange.new.toFixed(4)} ha ({diff.areaChange.delta > 0 ? '+' : ''}{diff.areaChange.delta.toFixed(6)})
            </Badge>
          </div>

          {diff.beaconChanges.filter(c => c.status !== 'unchanged').length > 0 && (
            <Card className="p-3 bg-gray-900 border-gray-800">
              <h3 className="text-xs font-semibold text-gray-400 uppercase mb-2">Beacon Changes</h3>
              <table className="w-full text-xs">
                <thead><tr className="text-gray-500 border-b border-gray-700">
                  <th className="text-left py-1">Beacon</th><th className="text-right">Old E</th><th className="text-right">New E</th><th className="text-right">ΔE</th><th className="text-right">Old N</th><th className="text-right">New N</th><th className="text-right">ΔN</th><th className="text-center">Status</th>
                </tr></thead>
                <tbody>
                  {diff.beaconChanges.filter(c => c.status !== 'unchanged').map(c => (
                    <tr key={c.id} className="border-b border-gray-800">
                      <td className="py-1 font-mono">{c.label}</td>
                      <td className="text-right text-gray-500">{c.oldEasting?.toFixed(3) ?? '—'}</td>
                      <td className="text-right text-gray-300">{c.newEasting?.toFixed(3) ?? '—'}</td>
                      <td className={`text-right ${c.deltaE !== 0 ? 'text-yellow-400' : 'text-gray-600'}`}>{c.deltaE !== 0 ? `${c.deltaE > 0 ? '+' : ''}${c.deltaE.toFixed(3)}` : '—'}</td>
                      <td className="text-right text-gray-500">{c.oldNorthing?.toFixed(3) ?? '—'}</td>
                      <td className="text-right text-gray-300">{c.newNorthing?.toFixed(3) ?? '—'}</td>
                      <td className={`text-right ${c.deltaN !== 0 ? 'text-yellow-400' : 'text-gray-600'}`}>{c.deltaN !== 0 ? `${c.deltaN > 0 ? '+' : ''}${c.deltaN.toFixed(3)}` : '—'}</td>
                      <td className="text-center">{c.status === 'added' && <span className="text-green-400">+added</span>}{c.status === 'removed' && <span className="text-red-400">-removed</span>}{c.status === 'moved' && <span className="text-yellow-400">→moved</span>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </Card>
          )}

          {diff.metadataChanges.length > 0 && (
            <Card className="p-3 bg-gray-900 border-gray-800">
              <h3 className="text-xs font-semibold text-gray-400 uppercase mb-2">Metadata Changes</h3>
              <div className="space-y-1">
                {diff.metadataChanges.map((c, i) => (
                  <div key={c.field} className="flex items-center gap-2 text-xs">
                    <span className="text-gray-500 w-32">{c.field}:</span>
                    <span className="text-red-400 line-through">{c.oldValue || '—'}</span>
                    <ArrowRight className="w-3 h-3 text-gray-600" />
                    <span className="text-green-400">{c.newValue || '—'}</span>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {diff.beaconChanges.every(c => c.status === 'unchanged') && diff.metadataChanges.length === 0 && diff.areaChange.delta === 0 && (
            <div className="text-center py-8 text-gray-500 text-sm">
              <Check className="w-8 h-8 mx-auto mb-2 text-green-500" />
              No changes between these versions.
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function computeDiff(oldVer: VersionData, newVer: VersionData): DiffResult {
  const oldBeacons = oldVer.data.beacons ?? []
  const newBeacons = newVer.data.beacons ?? []
  const oldMap = new Map(oldBeacons.map(b => [b.id, b]))
  const newMap = new Map(newBeacons.map(b => [b.id, b]))
  const beaconChanges: DiffResult['beaconChanges'] = []
  const allIds = new Set([...oldMap.keys(), ...newMap.keys()])
  for (const id of allIds) {
    const old = oldMap.get(id); const nw = newMap.get(id)
    if (!old && nw) beaconChanges.push({ id, label: nw.label, newEasting: nw.easting, newNorthing: nw.northing, deltaE: 0, deltaN: 0, status: 'added' })
    else if (old && !nw) beaconChanges.push({ id, label: old.label, oldEasting: old.easting, oldNorthing: old.northing, deltaE: 0, deltaN: 0, status: 'removed' })
    else if (old && nw) {
      const dE = nw.easting - old.easting; const dN = nw.northing - old.northing
      beaconChanges.push({ id, label: nw.label, oldEasting: old.easting, newEasting: nw.easting, oldNorthing: old.northing, newNorthing: nw.northing, deltaE: dE, deltaN: dN, status: Math.abs(dE) > 0.001 || Math.abs(dN) > 0.001 ? 'moved' : 'unchanged' })
    }
  }
  const oldBoundaries = oldVer.data.boundaries ?? []
  const newBoundaries = newVer.data.boundaries ?? []
  const oldBMap = new Map(oldBoundaries.map(b => [b.id, b]))
  const newBMap = new Map(newBoundaries.map(b => [b.id, b]))
  const boundaryChanges: DiffResult['boundaryChanges'] = []
  for (const id of new Set([...oldBMap.keys(), ...newBMap.keys()])) {
    const old = oldBMap.get(id); const nw = newBMap.get(id)
    if (!old && nw) boundaryChanges.push({ id, newBearing: nw.bearing, newDistance: nw.distance, status: 'added' })
    else if (old && !nw) boundaryChanges.push({ id, oldBearing: old.bearing, oldDistance: old.distance, status: 'removed' })
    else if (old && nw) boundaryChanges.push({ id, oldBearing: old.bearing, newBearing: nw.bearing, oldDistance: old.distance, newDistance: nw.distance, status: old.bearing !== nw.bearing || old.distance !== nw.distance ? 'changed' : 'unchanged' })
  }
  const metadataChanges: DiffResult['metadataChanges'] = []
  if (oldVer.data.lrNumber !== newVer.data.lrNumber) metadataChanges.push({ field: 'LR Number', oldValue: oldVer.data.lrNumber ?? '', newValue: newVer.data.lrNumber ?? '' })
  if (oldVer.data.clientName !== newVer.data.clientName) metadataChanges.push({ field: 'Client', oldValue: oldVer.data.clientName ?? '', newValue: newVer.data.clientName ?? '' })
  return { beaconChanges, boundaryChanges, metadataChanges, areaChange: { old: oldVer.data.area ?? 0, new: newVer.data.area ?? 0, delta: (newVer.data.area ?? 0) - (oldVer.data.area ?? 0) } }
}

'use client';

/**
 * TIN3DViewer — 3D terrain visualization using Three.js
 *
 * AUDIT FIX (2026-07-03): The main map is 2D (OpenLayers). This component
 * adds a 3D perspective for TIN surfaces and point clouds — critical for
 * engineering and drone surveys where the surveyor needs to see terrain
 * shape, not just planimetric position.
 *
 * Features:
 *   - Renders a TIN surface as a 3D wireframe + filled mesh
 *   - Orbit controls (rotate, zoom, pan)
 *   - Color-coded elevation (blue=low → red=high)
 *   - Grid helper for scale reference
 *   - Auto-fit camera to data bounds
 *
 * Dependencies: three (already in package.json)
 *
 * Usage:
 *   <TIN3DViewer surface={tinSurface} />
 *   <TIN3DViewer points={spotHeights} />
 */

import { useEffect, useRef } from 'react'
import type * as THREE from 'three'
import type { TINSurface, SpotHeight } from '@/lib/engine/contours'

interface TIN3DViewerProps {
  surface?: TINSurface | null
  points?: SpotHeight[]
  width?: number
  height?: number
}

export function TIN3DViewer({ surface, points, width = 800, height = 500 }: TIN3DViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!containerRef.current || (!surface && !points)) return

    let cleanup = () => {}

    // Dynamic import Three.js (keeps the main bundle smaller)
    import('three').then((THREE) => {
      import('three/examples/jsm/controls/OrbitControls.js').then(({ OrbitControls }) => {
        const container = containerRef.current
        if (!container) return

        // ─── Scene setup ──────────────────────────────────────────────────
        const scene = new THREE.Scene()
        scene.background = new THREE.Color(0x0a0e14)

        const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 100000)
        camera.position.set(100, 100, 100)

        const renderer = new THREE.WebGLRenderer({ antialias: true })
        renderer.setSize(width, height)
        renderer.setPixelRatio(window.devicePixelRatio)
        container.innerHTML = ''
        container.appendChild(renderer.domElement)

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement)
        controls.enableDamping = true
        controls.dampingFactor = 0.1

        // ─── Compute bounds ────────────────────────────────────────────────
        const pts = surface?.points || points || []
        if (pts.length === 0) return

        const minE = Math.min(...pts.map(p => p.easting))
        const maxE = Math.max(...pts.map(p => p.easting))
        const minN = Math.min(...pts.map(p => p.northing))
        const maxN = Math.max(...pts.map(p => p.northing))
        const minZ = Math.min(...pts.map(p => p.elevation || 0))
        const maxZ = Math.max(...pts.map(p => p.elevation || 0))
        const centerE = (minE + maxE) / 2
        const centerN = (minN + maxN) / 2
        const centerZ = (minZ + maxZ) / 2
        const rangeE = maxE - minE || 1
        const rangeN = maxN - minN || 1
        const rangeZ = maxZ - minZ || 1
        const maxRange = Math.max(rangeE, rangeN)

        // ─── Color function (blue→green→yellow→red by elevation) ──────────
        const colorForElevation = (z: number): THREE.Color => {
          const t = (z - minZ) / (maxZ - minZ || 1)
          const hue = (1 - t) * 0.67  // 0.67=blue → 0=red
          return new THREE.Color().setHSL(hue, 0.8, 0.5)
        }

        // ─── Render TIN surface as mesh ────────────────────────────────────
        let geometry: THREE.BufferGeometry | undefined
        if (surface && surface.triangles.length > 0) {
          geometry = new THREE.BufferGeometry()
          const vertices: number[] = []
          const colors: number[] = []

          for (const tri of surface.triangles) {
            for (const p of [tri.p1, tri.p2, tri.p3]) {
              vertices.push(
                p.easting - centerE,
                p.elevation - centerZ,
                p.northing - centerN,
              )
              const c = colorForElevation(p.elevation || 0)
              colors.push(c.r, c.g, c.b)
            }
          }

          geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3))
          geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
          geometry.computeVertexNormals()

          const material = new THREE.MeshBasicMaterial({
            vertexColors: true,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.7,
          })
          scene.add(new THREE.Mesh(geometry, material))

          // Wireframe overlay
          const wireframe = new THREE.LineSegments(
            new THREE.WireframeGeometry(geometry),
            new THREE.LineBasicMaterial({ color: 0x333333, linewidth: 1 })
          )
          scene.add(wireframe)
        }

        // ─── Render points (if no TIN, or as overlay) ─────────────────────
        if (points && points.length > 0 && !surface) {
          const pointGeom = new THREE.BufferGeometry()
          const pointVerts: number[] = []
          const pointColors: number[] = []

          for (const p of points) {
            pointVerts.push(p.easting - centerE, (p.elevation || 0) - centerZ, p.northing - centerN)
            const c = colorForElevation(p.elevation || 0)
            pointColors.push(c.r, c.g, c.b)
          }

          pointGeom.setAttribute('position', new THREE.Float32BufferAttribute(pointVerts, 3))
          pointGeom.setAttribute('color', new THREE.Float32BufferAttribute(pointColors, 3))

          scene.add(new THREE.Points(pointGeom, new THREE.PointsMaterial({
            size: maxRange * 0.003,
            vertexColors: true,
            sizeAttenuation: true,
          })))
        }

        // ─── Grid helper ───────────────────────────────────────────────────
        const gridSize = Math.ceil(maxRange * 1.2)
        const grid = new THREE.GridHelper(gridSize, 10, 0x444444, 0x222222)
        grid.rotation.x = Math.PI / 2
        scene.add(grid)

        // ─── Camera position (auto-fit) ────────────────────────────────────
        const dist = maxRange * 1.5
        camera.position.set(dist, dist * 0.7, dist)
        camera.lookAt(0, 0, 0)
        controls.target.set(0, 0, 0)
        controls.update()

        // ─── Animate ───────────────────────────────────────────────────────
        let frameId = 0
        const animate = () => {
          frameId = requestAnimationFrame(animate)
          controls.update()
          renderer.render(scene, camera)
        }
        animate()

        // ─── Cleanup ───────────────────────────────────────────────────────
        cleanup = () => {
          cancelAnimationFrame(frameId)
          controls.dispose()
          renderer.dispose()
          geometry?.dispose?.()
          if (container.contains(renderer.domElement)) {
            container.removeChild(renderer.domElement)
          }
        }
      })
    }).catch(() => {
      if (containerRef.current) {
        containerRef.current.innerHTML = '<div class="p-8 text-center text-zinc-500 text-sm">3D viewer requires Three.js. Run <code class="bg-zinc-800 px-1 rounded">npm install</code> to install dependencies.</div>'
      }
    })

    return () => cleanup()
  }, [surface, points, width, height])

  return (
    <div className="relative">
      <div ref={containerRef} className="rounded-lg overflow-hidden border border-[var(--border-color)]" style={{ width, height }} />
      <div className="absolute bottom-2 left-2 text-[10px] text-zinc-500 bg-black/50 px-2 py-1 rounded">
        Drag: rotate · Scroll: zoom · Right-drag: pan
      </div>
    </div>
  )
}

'use client';

import { useEffect, useState } from 'react';
import { Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { runTraverseComputation, TraverseComputationResult } from '@/lib/compute/traverseRunner';
import { FieldBookRow } from '@/types/fieldbook';

export default function CadastralComputeIntegration({ projectId }: { projectId: string }) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TraverseComputationResult | null>(null);
  const [rows, setRows] = useState<FieldBookRow[]>([]);

  useEffect(() => {
    async function loadAndCompute() {
      try {
        setLoading(true);
        const res = await fetch(`/api/project/${projectId}/fieldbook`);
        if (!res.ok) throw new Error('Failed to fetch field book data');
        const json = (await res.json()) as { data: Array<{ station?: string; raw_data?: { station?: string; distance?: number; bearing?: number } }> };
        
        if (!json.data || json.data.length === 0) {
          setError('No field book data found. Please complete Step 2 first.');
          setLoading(false);
          return;
        }

        const rawRows = json.data.map((r) => ({
          ...r.raw_data,
          station: r.station || r.raw_data?.station,
          distance: r.raw_data?.distance,
          bearing: r.raw_data?.bearing,
        })) as unknown as FieldBookRow[];
        
        setRows(rawRows);

        // Attempt computation
        try {
          const computation = runTraverseComputation({
            rows: rawRows,
            startPoint: { name: 'ST1', easting: 250000, northing: 9800000 },
            surveyType: 'cadastral',
            method: 'bowditch'
          });
          setResult(computation);

          // Save computation to project boundary_data for the Map
          const { createClient } = await import('@/lib/api-client/client');
          const dbClient = createClient();
          
          const adjustedStations = computation.adjustedStations.legs.map((leg) => ({
            pointName: leg.to,
            originalEasting: leg.adjEasting - leg.correctionE,
            originalNorthing: leg.adjNorthing - leg.correctionN,
            adjustedEasting: leg.adjEasting,
            adjustedNorthing: leg.adjNorthing,
          }));

          // Ensure the start point is included
          adjustedStations.unshift({
             pointName: 'ST1',
             originalEasting: 250000,
             originalNorthing: 9800000,
             adjustedEasting: 250000,
             adjustedNorthing: 9800000,
          });

          await dbClient
            .from('projects')
            .update({ boundary_data: { adjustedStations } })
            .eq('id', projectId);

        } catch (compErr: unknown) {
          setError(compErr instanceof Error ? compErr.message : 'Failed to compute traverse from field book data. Ensure distances and bearings are entered correctly.');
        }

      } catch (err: unknown) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    }

    loadAndCompute();
  }, [projectId]);

  if (loading) {
    return (
      <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] p-8 text-center">
        <Loader2 className="w-6 h-6 animate-spin mx-auto text-[var(--accent)] mb-3" />
        <p className="text-sm text-[var(--text-muted)]">Loading Field Book & Running Computations...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 p-5">
        <div className="flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
          <div>
            <h3 className="font-semibold text-amber-500 mb-1">Computation Warning</h3>
            <p className="text-sm text-amber-500/80">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  if (!result) return null;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg">
          <div className="text-[10px] text-[var(--text-muted)]">Precision Grade</div>
          <div className="text-sm font-bold text-[var(--text-primary)] uppercase">{result.adjustedStations.precisionGrade}</div>
        </div>
        <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg">
          <div className="text-[10px] text-[var(--text-muted)]">Precision Ratio</div>
          <div className="text-sm font-bold text-[var(--text-primary)]">1 : {Math.round(1 / result.adjustedStations.precisionRatio)}</div>
        </div>
        <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg">
          <div className="text-[10px] text-[var(--text-muted)]">Linear Misclosure</div>
          <div className="text-sm font-bold text-[var(--text-primary)]">{result.linearMisclosure.toFixed(4)} m</div>
        </div>
        <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
          <div className="text-[10px] text-emerald-400">Computed Area</div>
          <div className="text-sm font-bold text-emerald-400">{(result.adjustedAreaM2 / 10000).toFixed(6)} ha</div>
        </div>
      </div>

      <div className="border border-[var(--border-color)] rounded-xl overflow-hidden bg-[var(--bg-card)]">
        <div className="px-4 py-3 border-b border-[var(--border-color)] bg-[var(--bg-secondary)]">
          <h4 className="text-sm font-semibold text-[var(--text-primary)]">Table 1 — Bowditch Adjusted Coordinates</h4>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="text-left text-[10px] text-[var(--text-muted)] border-b border-[var(--border-color)]">
                <th className="px-3 py-2">Station</th>
                <th className="px-3 py-2 text-right">Raw Easting (m)</th>
                <th className="px-3 py-2 text-right">Raw Northing (m)</th>
                <th className="px-3 py-2 text-right">Adj Easting (m)</th>
                <th className="px-3 py-2 text-right">Adj Northing (m)</th>
              </tr>
            </thead>
            <tbody>
              {result.adjustedStations.legs.map((c, i) => (
                <tr key={`${c}-${i}`} className="border-b border-[var(--border-color)]/30 hover:bg-[var(--bg-secondary)]">
                  <td className="px-3 py-2 font-mono text-[var(--accent)]">{c.to}</td>
                  <td className="px-3 py-2 font-mono text-right text-[var(--text-muted)]">{(c.adjEasting - c.correctionE).toFixed(4)}</td>
                  <td className="px-3 py-2 font-mono text-right text-[var(--text-muted)]">{(c.adjNorthing - c.correctionN).toFixed(4)}</td>
                  <td className="px-3 py-2 font-mono text-right font-semibold">{c.adjEasting.toFixed(4)}</td>
                  <td className="px-3 py-2 font-mono text-right font-semibold">{c.adjNorthing.toFixed(4)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      
      <div className="flex items-center gap-2 text-xs text-emerald-400 bg-emerald-500/10 p-3 rounded-lg border border-emerald-500/20">
        <CheckCircle2 className="w-4 h-4" />
        Traverse automatically computed from Step 2 (Field Book). Area updated.
      </div>
    </div>
  );
}

'use client';

import React, { useRef, useEffect, useState, useCallback, memo } from 'react';
import {
  ChevronUp,
  ChevronDown,
  Trash2,
  Activity,
  Loader2,
  AlertCircle,
  CheckCircle2,
  AlertTriangle,
  Info,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import {
  useWorkspaceBridge,
  type ComputationLogEntry,
} from '@/hooks/useWorkspaceBridge';

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

/** Color tokens mapped from log level to Tailwind utilities */
const LEVEL_STYLES: Record<
  ComputationLogEntry['level'],
  { dot: string; text: string; border: string; badge: string }
> = {
  info: {
    dot: 'bg-sky-400',
    text: 'text-sky-300',
    border: 'border-sky-500/20',
    badge: 'bg-sky-500/10 text-sky-400',
  },
  success: {
    dot: 'bg-emerald-400',
    text: 'text-emerald-300',
    border: 'border-emerald-500/20',
    badge: 'bg-emerald-500/10 text-emerald-400',
  },
  warning: {
    dot: 'bg-amber-400',
    text: 'text-amber-300',
    border: 'border-amber-500/20',
    badge: 'bg-amber-500/10 text-amber-400',
  },
  error: {
    dot: 'bg-red-400',
    text: 'text-red-300',
    border: 'border-red-500/20',
    badge: 'bg-red-500/10 text-red-400',
  },
};

const PHASE_STYLES: Record<
  ComputationLogEntry['phase'],
  { badge: string }
> = {
  input: { badge: 'bg-violet-500/10 text-violet-400' },
  compute: { badge: 'bg-cyan-500/10 text-cyan-400' },
  adjustment: { badge: 'bg-orange-500/10 text-orange-400' },
  output: { badge: 'bg-emerald-500/10 text-emerald-400' },
};

function formatTime(d: Date): string {
  return d.toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
}

/* ------------------------------------------------------------------ */
/*  Single log entry (memoised)                                        */
/* ------------------------------------------------------------------ */

interface LogEntryRowProps {
  entry: ComputationLogEntry;
}

const LogEntryRow = memo(function LogEntryRow({ entry }: LogEntryRowProps) {
  const [expanded, setExpanded] = useState(false);
  const levelStyle = LEVEL_STYLES[entry.level];
  const phaseStyle = PHASE_STYLES[entry.phase];

  return (
    <div
      className={cn(
        'group flex items-start gap-2 px-3 py-1.5 border-l-2 transition-colors',
        levelStyle.border,
        'hover:bg-[var(--bg-tertiary)]',
      )}
    >
      {/* Timestamp */}
      <span className="flex-shrink-0 text-xs font-mono text-[var(--text-muted)] pt-0.5 select-none w-16">
        {formatTime(entry.timestamp)}
      </span>

      {/* Level dot */}
      <span
        className={cn('flex-shrink-0 w-1.5 h-1.5 rounded-full mt-1.5', levelStyle.dot)}
        title={entry.level}
      />

      {/* Phase badge */}
      <span
        className={cn(
          'flex-shrink-0 text-[9px] font-semibold uppercase tracking-wider px-1.5 py-0.5 rounded',
          phaseStyle.badge,
        )}
      >
        {entry.phase}
      </span>

      {/* Message */}
      <span
        className={cn('flex-1 text-xs leading-relaxed min-w-0', levelStyle.text)}
      >
        {entry.message}
      </span>

      {/* Expand toggle for detail */}
      {entry.detail && (
        <button
          onClick={() => setExpanded((v) => !v)}
          className="flex-shrink-0 p-0.5 rounded hover:bg-[var(--bg-card)] text-[var(--text-muted)] hover:text-[var(--text-secondary)] transition-colors opacity-0 group-hover:opacity-100"
          aria-label={expanded ? 'Hide detail' : 'Show detail'}
        >
          {expanded ? (
            <ChevronUp className="w-3 h-3" />
          ) : (
            <ChevronDown className="w-3 h-3" />
          )}
        </button>
      )}
    </div>
  );
});

/* ------------------------------------------------------------------ */
/*  Computation Log Component                                          */
/* ------------------------------------------------------------------ */

export default function ComputationLog() {
  const { computationLogs, isComputing, clearLogs } = useWorkspaceBridge();
  const scrollRef = useRef<HTMLDivElement>(null);
  const [collapsed, setCollapsed] = useState(false);

  // Auto-scroll to bottom on new entries
  useEffect(() => {
    if (!collapsed && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [computationLogs.length, collapsed]);

  const handleClear = useCallback(() => {
    clearLogs();
  }, [clearLogs]);

  const toggleCollapse = useCallback(() => {
    setCollapsed((v) => !v);
  }, []);

  return (
    <div
      className={cn(
        'flex flex-col overflow-hidden bg-[var(--bg-secondary)] transition-all duration-200',
        collapsed ? 'h-8' : 'h-full',
      )}
    >
      {/* ---- Header bar ---- */}
      <div className="flex items-center justify-between flex-shrink-0 h-8 px-3 border-b border-[var(--border-color)] bg-[var(--bg-card)]">
        <div className="flex items-center gap-2.5 min-w-0">
          {/* Computing pulse indicator */}
          {isComputing && (
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[var(--accent)] opacity-75" />
              <span className="relative inline-flex rounded-full h-2 w-2 bg-[var(--accent)]" />
            </span>
          )}

          <span className="text-xs font-semibold text-[var(--text-primary)] tracking-tight">
            Computation Log
          </span>

          {/* Entry count badge */}
          {computationLogs.length > 0 && (
            <span className="text-xs font-medium tabular-nums bg-[var(--bg-tertiary)] text-[var(--text-secondary)] px-1.5 py-0.5 rounded">
              {computationLogs.length}
            </span>
          )}

          {/* Level summary icons */}
          {computationLogs.length > 0 && (
            <div className="flex items-center gap-1 ml-1">
              {computationLogs.some((e) => e.level === 'error') && (
                <AlertCircle className="w-3 h-3 text-red-400" />
              )}
              {computationLogs.some(
                (e) => e.level === 'warning' && !computationLogs.some((l) => l.level === 'error'),
              ) && (
                <AlertTriangle className="w-3 h-3 text-amber-400" />
              )}
              {computationLogs.every(
                (e) => e.level === 'info' || e.level === 'success',
              ) && (
                <CheckCircle2 className="w-3 h-3 text-emerald-400" />
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-1 flex-shrink-0">
          {/* Clear button */}
          {computationLogs.length > 0 && (
            <button
              onClick={handleClear}
              className="flex items-center gap-1 px-2 py-1.5 rounded text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors min-h-[36px]"
              title="Clear all logs"
            >
              <Trash2 className="w-3 h-3" />
              <span>Clear</span>
            </button>
          )}

          {/* Collapse toggle */}
          <button
            onClick={toggleCollapse}
            aria-label={collapsed ? 'Expand log' : 'Collapse log'}
            className="flex-shrink-0 p-2 min-w-[36px] min-h-[36px] flex items-center justify-center rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-[var(--text-secondary)] transition-colors"
          >
            {collapsed ? (
              <ChevronUp className="w-3.5 h-3.5" />
            ) : (
              <ChevronDown className="w-3.5 h-3.5" />
            )}
          </button>
        </div>
      </div>

      {/* ---- Log list (hidden when collapsed) ---- */}
      {!collapsed && (
        <div
          ref={scrollRef}
          className="flex-1 overflow-y-auto min-h-0 custom-scrollbar"
        >
          {computationLogs.length === 0 ? (
            /* Empty state */
            <div className="flex flex-col items-center justify-center h-full py-6 text-center select-none">
              <Info className="w-5 h-5 text-[var(--text-muted)] mb-2" />
              <p className="text-xs text-[var(--text-muted)]">
                No computation entries yet.
              </p>
              <p className="text-xs text-[var(--text-muted)] mt-0.5 opacity-70">
                Run a computation to see results here.
              </p>
            </div>
          ) : (
            <div className="divide-y divide-[var(--border-color)]/50">
              {computationLogs.map((entry) => (
                <LogEntryRow key={entry.id} entry={entry} />
              ))}
            </div>
          )}

          {/* Computing overlay */}
          {isComputing && (
            <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-[var(--bg-secondary)] to-transparent flex items-center justify-center pointer-events-none">
              <Loader2 className="w-3.5 h-3.5 text-[var(--accent)] animate-spin" />
              <span className="text-xs text-[var(--accent)] ml-1.5 font-medium">
                Computing…
              </span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { createClient } from '@/lib/api-client/client';
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint';
import { SurveyType } from '@/types/project';
import { FieldBookColumn, FieldBookRow } from '@/types/fieldbook';
import { getFieldBookTemplate } from '@/lib/workflows/fieldBookTemplates';
import { applyAutoCalculations, validateFieldBook, FieldBookWarning } from '@/lib/workflows/autoCalculate';
import { runLevelingComputation, getLevelingClosureStatus } from '@/lib/compute/levelingRunner';
import { runBowditchAdjustment, getTraversePrecisionStatus } from '@/lib/compute/traverseRunner';
import { computeCutFillVolume, getCutFillSummary } from '@/lib/compute/volumeRunner';

interface Props {
  projectId: string;
  surveyType: SurveyType;
  initialRows?: FieldBookRow[];
  openingRL?: number;
  closingRL?: number;
  startPoint?: { name: string; easting: number; northing: number };
}

const FIXED_COLUMNS = new Set([
  'station', 'bs', 'is', 'fs', 'rl', 'instrument_height', 'remark',
]);

function emptyRow(columns: FieldBookColumn[]): FieldBookRow {
  return Object.fromEntries(columns.map((c) => [c.key, '']));
}

function rowToDbRecord(
  row: FieldBookRow,
  rowIndex: number,
  projectId: string,
  surveyType: string,
  columns: FieldBookColumn[]
) {
  const fixed: Record<string, unknown> = {
    project_id: projectId,
    row_index: rowIndex,
    survey_type: surveyType,
    updated_at: new Date().toISOString(),
  };

  const rawData: Record<string, unknown> = {};

  for (const col of columns) {
    const value = row[col.key] ?? null;
    const targetColumn = col.fixedColumn ?? (FIXED_COLUMNS.has(col.key) ? col.key : null);

    if (targetColumn) {
      if (['bs', 'is', 'fs', 'rl', 'instrument_height'].includes(targetColumn)) {
        fixed[targetColumn] = value !== '' && value !== null ? Number(value) : null;
      } else {
        fixed[targetColumn] = value !== '' ? value : null;
      }
    } else {
      rawData[col.key] = value !== '' ? value : null;
    }
  }

  fixed['raw_data'] = rawData;
  return fixed;
}

export default function DynamicFieldBook({ projectId, surveyType, initialRows = [], openingRL, closingRL, startPoint }: Props) {
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({ title: 'Field Book' });
  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), []);
  const template = getFieldBookTemplate(surveyType);

  const [rows, setRows] = useState<FieldBookRow[]>(
    initialRows.length > 0 ? initialRows : [emptyRow(template.columns)]
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [computeResult, setComputeResult] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<FieldBookWarning[]>([]);
  const [deleteConfirm, setDeleteConfirm] = useState<number | null>(null);

  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const rowsRef = useRef(rows);
  rowsRef.current = rows;

  const addRow = () => setRows((prev) => [...prev, emptyRow(template.columns)]);

  const removeRow = (idx: number) => {
    if (deleteConfirm === idx) {
      setRows((prev) => prev.filter((_, i) => i !== idx));
      setDeleteConfirm(null);
    } else {
      setDeleteConfirm(idx);
      setTimeout(() => setDeleteConfirm(null), 3000);
    }
  };

  const updateCell = useCallback((rowIdx: number, key: string, value: string) => {
    setRows((prev) => {
      const updated = prev.map((row, i) => (i === rowIdx ? { ...row, [key]: value } : row));
      const recalculated = applyAutoCalculations(surveyType, updated, rowIdx);
      const newWarnings = validateFieldBook(surveyType, recalculated);
      setWarnings(newWarnings);
      return recalculated;
    });

    if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
    saveTimeoutRef.current = setTimeout(async () => {
      setSaving(true);
      const records = rowsRef.current.map((row: FieldBookRow, idx: number) =>
        rowToDbRecord(row, idx, projectId, surveyType, template.columns)
      );
      const { error: dbError } = await dbClient
        .from('project_fieldbook_entries')
        .upsert(records, { onConflict: 'project_id,row_index' });
      if (!dbError) setLastSaved(new Date());
      setSaving(false);
    }, 500);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [surveyType, projectId, template.columns, dbClient]);

  const handleCompute = useCallback(() => {
    try {
      if (surveyType === 'engineering') {
        if (openingRL) {
          const result = runLevelingComputation({
            rows,
            openingRL,
            closingRL: closingRL ? Number(closingRL) : undefined,
            method: 'rise_and_fall',
          });
          const status = getLevelingClosureStatus(result);
          setComputeResult(status.message);
        } else {
          setComputeResult('Please provide opening RL in project settings');
        }
      } else if (surveyType === 'cadastral') {
        if (startPoint) {
          const result = runBowditchAdjustment({
            rows,
            startPoint,
          });
          const status = getTraversePrecisionStatus(result);
          setComputeResult(status.message);
        } else {
          setComputeResult('Please provide start point coordinates in project settings');
        }
      } else if (surveyType === 'topographic') {
        const sections = rows
          .filter((r) => r.chainage && r.area)
          .map((r) => ({ chainage: Number(r.chainage), area: Number(r.area) }))
          .sort((a, b) => a.chainage - b.chainage);
        
        if (sections.length >= 2) {
          const result = computeCutFillVolume(sections);
          const summary = getCutFillSummary(result);
          setComputeResult(`Cut: ${summary.cut} | Fill: ${summary.fill} | Net: ${summary.net}`);
        } else {
          setComputeResult('Need at least 2 rows with chainage and area for volume calculation');
        }
      } else if (surveyType === 'geodetic') {
        setComputeResult('Geodetic baseline processing — enter control points and observed baselines to compute adjustments');
      } else if (surveyType === 'drone') {
        setComputeResult('Drone survey processing — import ground control points and process aerial imagery');
      } else if (surveyType === 'deformation') {
        const epochs = new Set(rows.map((r) => r.epoch).filter(Boolean));
        if (epochs.size < 2) {
          setComputeResult('Minimum 2 epochs required for comparison');
        } else {
          setComputeResult('Deformation epoch comparison — enter coordinates for each monitoring epoch');
        }
      }
    } catch (e) {
      setComputeResult(`Error: ${e instanceof Error ? e.message : 'Unknown error'}`);
    }
  }, [rows, surveyType, openingRL, closingRL, startPoint]);

  const handleSave = async () => {
    setSaving(true);
    setError(null);

    const records = rows.map((row: FieldBookRow, idx: number) =>
      rowToDbRecord(row, idx, projectId, surveyType, template.columns)
    );

    const { error: dbError } = await dbClient
      .from('project_fieldbook_entries')
      .upsert(records, { onConflict: 'project_id,row_index' });

    if (dbError) {
      setError('Save failed: ' + dbError.message);
    } else {
      setLastSaved(new Date());
    }
    setSaving(false);
  };

  const renderCell = (col: FieldBookColumn, row: FieldBookRow, rowIdx: number) => {
    const value = String(row[col.key] ?? '');
    const base = 'w-full text-sm outline-none bg-transparent px-1 py-0.5';

    if (col.type === 'select' && col.options) {
      return (
        <select
          value={value}
          onChange={(e) => updateCell(rowIdx, col.key, e.target.value)}
          className={base}
        >
          <option value="">—</option>
          {col.options.map((o) => (
            <option key={o} value={o}>{o}</option>
          ))}
        </select>
      );
    }

    return (
      <input aria-label={col.label}
        type={col.type === 'number' ? 'number' : col.type === 'date' ? 'date' : 'text'}
        value={value}
        placeholder={col.placeholder ?? ''}
        step={col.type === 'number' ? 'any' : undefined}
        onChange={(e) => updateCell(rowIdx, col.key, e.target.value)}
        className={base}
      />
    );
  };

  const requiredKeys = template.columns.filter((c) => c.required).map((c) => c.key);
  const hasEmptyRequired = rows.some((row) => requiredKeys.some((k) => !row[k]));

  const getComputeButtonLabel = () => {
    switch (surveyType) {
      case 'cadastral': return 'Adjust Traverse (Bowditch)';
      case 'engineering': return 'Reduce Levels';
      case 'topographic': return 'Generate DTM';
      case 'geodetic': return 'Process Baselines';
      case 'drone': return 'Process GCPs';
      case 'deformation': return 'Compare Epochs';
      default: return 'Compute';
    }
  };

  return (
    <div className="rounded-lg border border-gray-200 bg-white overflow-hidden">
      <PrintHeader title="Field Book" />
      <div className="px-4 py-3 border-b border-gray-100 flex items-start justify-between gap-4">
        <div>
          <h3 className="font-semibold text-gray-900 text-sm">{template.title}</h3>
          <p className="text-xs text-gray-500 mt-0.5">{template.description}</p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0 no-print print-hide">
          {lastSaved && <span className="text-xs text-green-600">Saved {lastSaved.toLocaleTimeString()}</span>}
          <button onClick={handleCompute} disabled={saving} className="px-3 py-1.5 text-xs bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50">
            {getComputeButtonLabel()}
          </button>
          <button onClick={handleSave} disabled={saving} className="px-3 py-1.5 text-xs bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50">
            {saving ? 'Saving…' : 'Save'}
          </button>
          <PrintButton
            print={print}
            isPrinting={isPrinting}
            paperSize={paperSize}
            setPaperSize={setPaperSize}
            orientation={orientation}
            setOrientation={setOrientation}
            printTitle="Field Book"
            compact
          />
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse min-w-max">
          <thead>
            <tr className="bg-gray-50 border-b border-gray-200">
              <th className="w-8 px-2 py-1.5 text-left text-xs font-medium text-gray-500">#</th>
              {template.columns.map((col) => (
                <th key={col.key} className={`px-2 py-1.5 text-left text-xs font-medium text-gray-600 w-${col.width ?? '28'}`}>
                  {col.label}{col.required && <span className="text-red-400 ml-0.5">*</span>}
                </th>
              ))}
              <th className="w-8" />
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIdx) => (
              <tr key={rowIdx} className="border-b border-gray-100 hover:bg-gray-50">
                <td className="px-2 py-1 text-xs text-gray-400 text-right select-none">{rowIdx + 1}</td>
                {template.columns.map((col) => (
                  <td key={col.key} className={`border-l border-gray-100 px-1 py-0.5 ${col.required && !row[col.key] ? 'bg-red-50' : ''}`}>
                    {renderCell(col, row, rowIdx)}
                  </td>
                ))}
                <td className="border-l border-gray-100 px-1 py-0.5 text-center">
                  <button
                    onClick={() => removeRow(rowIdx)}
                    disabled={rows.length === 1}
                    className={`text-xs ${deleteConfirm === rowIdx ? 'text-red-600 font-medium' : 'text-gray-300 hover:text-red-400'} disabled:opacity-0`}
                    title={deleteConfirm === rowIdx ? 'Click again to confirm' : 'Delete row'}
                  >
                    {deleteConfirm === rowIdx ? '' : '[x]'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="px-4 py-2 border-t border-gray-100 flex items-center justify-between">
        <button onClick={addRow} className="text-xs text-blue-600 hover:text-blue-800 font-medium">+ Add Row</button>
        <div className="flex items-center gap-3">
          {hasEmptyRequired && <span className="text-xs text-amber-600">Required fields (*) must be filled.</span>}
          <span className="text-xs text-gray-400">{rows.length} row{rows.length !== 1 ? 's' : ''}</span>
        </div>
      </div>

      {warnings.length > 0 && (
        <div className="px-4 py-2 bg-amber-50 border-t border-amber-100 flex flex-wrap gap-2">
          {warnings.map((w, idx) => (
            <span
              key={`${w}-${idx}`}
              className={`inline-flex items-center px-2 py-0.5 rounded text-xs ${
                w.severity === 'error' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
              }`}
            >
              {w.rowIndex !== undefined && <span className="mr-1">Row {w.rowIndex + 1}:</span>}
              {w.message}
            </span>
          ))}
        </div>
      )}

      {error && <div className="px-4 py-2 bg-red-50 border-t border-red-100 text-xs text-red-600">{error}</div>}
      {computeResult && (
        <div className={`px-4 py-2 border-t text-xs ${computeResult.startsWith('Error') ? 'bg-red-50 border-red-100 text-red-600' : 'bg-green-50 border-green-100 text-green-700'}`}>
          {computeResult}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';

interface SectionPoint {
  chainage: number;
  rl: number;
  remark?: string;
}

interface Props {
  projectId: string;
  points?: SectionPoint[];
}

export default function LongitudinalSection({ projectId, points = [] }: Props) {
  const [data, setData] = useState<SectionPoint[]>(points);

  const addRow = () =>
    setData((prev) => [...prev, { chainage: 0, rl: 0, remark: '' }]);

  const updateRow = (
    idx: number,
    field: keyof SectionPoint,
    value: string
  ) => {
    setData((prev) =>
      prev.map((row, i) =>
        i === idx ? { ...row, [field]: field === 'remark' ? value : parseFloat(value) || 0 } : row
      )
    );
  };

  return (
    <div className="rounded-lg border border-gray-200 p-4 bg-white">
      <h3 className="font-semibold text-gray-800 mb-3">Longitudinal Section</h3>
      <div className="overflow-x-auto">
      <table className="w-full text-sm border-collapse min-w-[320px]">
        <thead>
          <tr className="bg-gray-50">
            <th className="border px-2 py-1 text-left">Chainage (m)</th>
            <th className="border px-2 py-1 text-left">RL (m)</th>
            <th className="border px-2 py-1 text-left">Remark</th>
          </tr>
        </thead>
        <tbody>
          {data.map((row, idx) => (
            <tr key={`lsec-${idx}`}>
              <td className="border px-1 py-1">
                <input aria-label="Chainage"
                  type="number"
                  value={row.chainage}
                  onChange={(e) => updateRow(idx, 'chainage', e.target.value)}
                  className="w-full outline-none"
                />
              </td>
              <td className="border px-1 py-1">
                <input aria-label="Rl"
                  type="number"
                  value={row.rl}
                  onChange={(e) => updateRow(idx, 'rl', e.target.value)}
                  className="w-full outline-none"
                />
              </td>
              <td className="border px-1 py-1">
                <input aria-label="Remark"
                  type="text"
                  value={row.remark ?? ''}
                  onChange={(e) => updateRow(idx, 'remark', e.target.value)}
                  className="w-full outline-none"
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      </div>
      <button
        onClick={addRow}
        className="mt-2 px-3 py-1 text-sm bg-gray-100 hover:bg-gray-200 rounded"
      >
        + Add Row
      </button>
    </div>
  );
}

