/**
 * Self-check for the API client.
 * ponytail: one runnable check, the smallest thing that fails if logic breaks.
 * Run:  npx tsx src/lib/api/__tests__/client.selfcheck.ts
 */

import { api, apiGet, apiPost, apiDelete, apiInvalidate, apiInvalidateAll, ApiError } from '../client'
import { z } from 'zod'
import assert from 'node:assert'

const ProjectSchema = z.object({ id: z.string(), name: z.string() })
type Project = z.infer<typeof ProjectSchema>

const origFetch = globalThis.fetch

function installMock(opts: { status: number; body: unknown; headers?: Record<string, string> }) {
  globalThis.fetch = (async (_input: RequestInfo | URL, _init?: RequestInit) => {
    // ponytail: 204 No Content MUST NOT have a body per HTTP spec
    if (opts.status === 204) {
      return new Response(null, {
        status: 204,
        headers: { 'Content-Type': 'application/json', ...opts.headers },
      })
    }
    return new Response(JSON.stringify(opts.body), {
      status: opts.status,
      headers: { 'Content-Type': 'application/json', ...opts.headers },
    })
  }) as typeof fetch
}

function restoreFetch() { globalThis.fetch = origFetch }

let pass = 0
let fail = 0
async function check(name: string, fn: () => void | Promise<void>) {
  try {
    const r = fn()
    if (r instanceof Promise) await r
    pass++
    console.log(`   ${name}`)
  } catch (err) {
    fail++
    console.error(`   ${name}: ${(err as Error).message}`)
  }
}

async function main() {
  console.log('API client self-check\n')

  await check('200 OK with valid schema returns parsed body', async () => {
    installMock({ status: 200, body: { id: 'p1', name: 'FR 583' } })
    const result = await api('/api/projects/p1', ProjectSchema)
    assert.equal(result.id, 'p1')
    assert.equal(result.name, 'FR 583')
    restoreFetch()
  })

  await check('204 No Content returns undefined', async () => {
    installMock({ status: 204, body: null })
    const result = await api<null | undefined>('/api/projects/p1', z.null().optional())
    assert.equal(result, undefined)
    restoreFetch()
  })

  await check('401 throws ApiError with code UNAUTHORIZED', async () => {
    installMock({ status: 401, body: { error: 'Authentication required', code: 'UNAUTHORIZED' } })
    await assert.rejects(
      () => api('/api/projects/p1', ProjectSchema),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.status, 401)
        assert.equal(err.code, 'UNAUTHORIZED')
        assert.equal(err.isUnauthorized, true)
        return true
      },
    )
    restoreFetch()
  })

  await check('400 VALIDATION_ERROR includes issues array', async () => {
    installMock({
      status: 400,
      body: { error: 'Validation failed', code: 'VALIDATION_ERROR',
              issues: [{ path: ['name'], message: 'Required' }] },
    })
    await assert.rejects(
      () => api('/api/projects', ProjectSchema, { method: 'POST', body: {} as BodyInit }),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.code, 'VALIDATION_ERROR')
        assert.ok(err.issues && err.issues.length > 0)
        assert.equal(err.isValidation, true)
        return true
      },
    )
    restoreFetch()
  })

  await check('Response schema mismatch throws ApiError', async () => {
    installMock({ status: 200, body: { id: 'p1' } })
    await assert.rejects(
      () => api('/api/projects/p1', ProjectSchema),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.code, 'INTERNAL_ERROR')
        assert.match(err.message, /schema mismatch/)
        return true
      },
    )
    restoreFetch()
  })

  await check('apiGet caches responses within TTL', async () => {
    let callCount = 0
    globalThis.fetch = (async () => {
      callCount++
      return new Response(JSON.stringify({ id: 'p1', name: `call-${callCount}` }), {
        status: 200, headers: { 'Content-Type': 'application/json' },
      })
    }) as typeof fetch
    apiInvalidateAll()
    const r1 = await apiGet('/api/projects/p1', ProjectSchema, { ttlMs: 5000 })
    const r2 = await apiGet('/api/projects/p1', ProjectSchema, { ttlMs: 5000 })
    assert.equal(callCount, 1)
    assert.deepEqual(r1, r2)
    restoreFetch()
  })

  await check('apiInvalidate forces next apiGet to re-fetch', async () => {
    let callCount = 0
    globalThis.fetch = (async () => {
      callCount++
      return new Response(JSON.stringify({ id: 'p1', name: 'X' }), {
        status: 200, headers: { 'Content-Type': 'application/json' },
      })
    }) as typeof fetch
    apiInvalidateAll()
    await apiGet('/api/projects/p2', ProjectSchema, { ttlMs: 5000 })
    apiInvalidate('/api/projects/p2')
    await apiGet('/api/projects/p2', ProjectSchema, { ttlMs: 5000 })
    assert.equal(callCount, 2)
    restoreFetch()
  })

  await check('apiPost sends JSON body with Content-Type header', async () => {
    let capturedInit: RequestInit | undefined
    globalThis.fetch = (async (_input, init) => {
      capturedInit = init
      return new Response(JSON.stringify({ id: 'p2', name: 'new' }), {
        status: 201, headers: { 'Content-Type': 'application/json' },
      })
    }) as typeof fetch
    await apiPost('/api/projects', ProjectSchema, { name: 'new' })
    assert.equal(capturedInit?.method, 'POST')
    assert.equal((capturedInit?.headers as Record<string, string>)?.['Content-Type'], 'application/json')
    assert.equal(capturedInit?.body, JSON.stringify({ name: 'new' }))
    restoreFetch()
  })

  await check('apiDelete without schema accepts 204', async () => {
    installMock({ status: 204, body: null })
    await apiDelete('/api/projects/p3')
    restoreFetch()
  })

  await check('Server with no code field falls back to status-based guess', async () => {
    installMock({ status: 404, body: { error: 'Not found' } })
    await assert.rejects(
      () => api('/api/projects/missing', ProjectSchema),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.code, 'NOT_FOUND')
        assert.equal(err.isNotFound, true)
        return true
      },
    )
    restoreFetch()
  })

  console.log(`\n${pass} passed, ${fail} failed`)
  if (fail > 0) process.exit(1)
}

main().catch((err) => { console.error('Self-check crashed:', err); process.exit(1) })

/**
 * Tests for the Audit Chain — tamper-evident append-only log.
 *
 * Coverage:
 *   - Pure functions: computeEntryHash, canonicalJSON
 *   - Hash determinism (same input → same hash)
 *   - Hash sensitivity (any field change → different hash)
 *   - Chain linking (each entry's hash includes the previous)
 *   - Tamper detection (modified entry → verification fails)
 *   - Broken link detection (inserted/deleted entry → verification fails)
 *   - Canonical JSON key ordering (insertion order doesn't matter)
 *
 * The DB-dependent functions (appendAuditEntry, verifyChain, queryAuditEntries)
 * require a live PostgreSQL instance and are not unit-tested here.
 * They're covered by integration tests in the e2e suite.
 */

import {
  computeEntryHash,
  canonicalJSON,
  type AuditPayload,
} from '../auditHash'

// ─── Helpers ────────────────────────────────────────────────────────────

const baseParams = {
  previousHash: null,
  sequence: 1,
  projectId: 'proj-1',
  userId: 'user-1',
  entityType: 'control_point' as const,
  entityId: 'CP1',
  action: 'update' as const,
  payload: {
    old: { easting: 250000, northing: 9945000 },
    new: { easting: 250050, northing: 9945050 },
    reason: 'Helmert recalibration',
  },
  createdAt: '2026-07-01T12:00:00.000Z',
}

// ─── Hash determinism ──────────────────────────────────────────────────

describe('computeEntryHash', () => {
  it('produces a 64-character hex string', async () => {
    const hash = await computeEntryHash(baseParams)
    expect(hash).toMatch(/^[0-9a-f]{64}$/)
  })

  it('is deterministic — same input always produces the same hash', async () => {
    const hash1 = await computeEntryHash(baseParams)
    const hash2 = await computeEntryHash(baseParams)
    expect(hash1).toBe(hash2)
  })

  it('produces different hashes for different previousHash', async () => {
    const hash1 = await computeEntryHash(baseParams)
    const hash2 = await computeEntryHash({
      ...baseParams,
      previousHash: 'abc123',
    })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different sequence numbers', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, sequence: 1 })
    const hash2 = await computeEntryHash({ ...baseParams, sequence: 2 })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different entity ids', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, entityId: 'CP1' })
    const hash2 = await computeEntryHash({ ...baseParams, entityId: 'CP2' })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different actions', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, action: 'create' })
    const hash2 = await computeEntryHash({ ...baseParams, action: 'update' })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different payloads', async () => {
    const hash1 = await computeEntryHash({
      ...baseParams,
      payload: { ...baseParams.payload, reason: 'reason A' },
    })
    const hash2 = await computeEntryHash({
      ...baseParams,
      payload: { ...baseParams.payload, reason: 'reason B' },
    })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different timestamps', async () => {
    const hash1 = await computeEntryHash({
      ...baseParams,
      createdAt: '2026-07-01T12:00:00.000Z',
    })
    const hash2 = await computeEntryHash({
      ...baseParams,
      createdAt: '2026-07-01T12:00:01.000Z',
    })
    expect(hash1).not.toBe(hash2)
  })

  it('treats null and empty string previousHash the same (genesis entry)', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, previousHash: null })
    const hash2 = await computeEntryHash({ ...baseParams, previousHash: '' })
    // Both produce the same hash because null ?? '' = '' in the canonical form
    expect(hash1).toBe(hash2)
  })

  it('treats null and undefined projectId the same', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, projectId: null })
    const hash2 = await computeEntryHash({ ...baseParams, projectId: undefined as unknown as null })
    // undefined coalesces to '' via ??, null also coalesces to ''
    expect(hash1).toBe(hash2)
  })
})

// ─── Canonical JSON ────────────────────────────────────────────────────

describe('canonical JSON serialization (via hash behavior)', () => {
  it('produces the same hash regardless of payload key insertion order', async () => {
    // Same object, different key order — should produce same hash
    const payload1: AuditPayload = {
      old: { e: 1, n: 2 },
      new: { e: 3, n: 4 },
      reason: 'test',
    }
    const payload2: AuditPayload = {
      reason: 'test',
      new: { n: 4, e: 3 },
      old: { n: 2, e: 1 },
    }

    const hash1 = await computeEntryHash({ ...baseParams, payload: payload1 })
    const hash2 = await computeEntryHash({ ...baseParams, payload: payload2 })
    expect(hash1).toBe(hash2)
  })

  it('produces different hashes for nested object value changes', async () => {
    const payload1: AuditPayload = {
      old: { easting: 250000 },
      new: { easting: 250050 },
    }
    const payload2: AuditPayload = {
      old: { easting: 250000 },
      new: { easting: 250051 }, // 1mm difference
    }
    const hash1 = await computeEntryHash({ ...baseParams, payload: payload1 })
    const hash2 = await computeEntryHash({ ...baseParams, payload: payload2 })
    expect(hash1).not.toBe(hash2)
  })

  it('handles arrays in payload correctly', async () => {
    const payload1: AuditPayload = {
      new: { stations: [{ name: 'A' }, { name: 'B' }] },
    }
    const payload2: AuditPayload = {
      new: { stations: [{ name: 'B' }, { name: 'A' }] }, // different order
    }
    const hash1 = await computeEntryHash({ ...baseParams, payload: payload1 })
    const hash2 = await computeEntryHash({ ...baseParams, payload: payload2 })
    // Array order matters — these should be different
    expect(hash1).not.toBe(hash2)
  })

  it('handles empty payload', async () => {
    const hash = await computeEntryHash({ ...baseParams, payload: {} })
    expect(hash).toMatch(/^[0-9a-f]{64}$/)
  })

  it('handles null values in payload', async () => {
    const hash = await computeEntryHash({
      ...baseParams,
      payload: { old: null, new: { v: 1 } },
    })
    expect(hash).toMatch(/^[0-9a-f]{64}$/)
  })
})

// ─── Chain linking simulation ──────────────────────────────────────────

describe('chain linking (simulated)', () => {
  it('each entry in a chain includes the previous entry\'s hash', async () => {
    // Simulate a 3-entry chain
    const entry1Hash = await computeEntryHash({
      ...baseParams,
      previousHash: null,
      sequence: 1,
    })

    const entry2Hash = await computeEntryHash({
      ...baseParams,
      previousHash: entry1Hash,
      sequence: 2,
      entityId: 'CP2',
    })

    const entry3Hash = await computeEntryHash({
      ...baseParams,
      previousHash: entry2Hash,
      sequence: 3,
      entityId: 'CP3',
    })

    // All three should be distinct
    expect(entry1Hash).not.toBe(entry2Hash)
    expect(entry2Hash).not.toBe(entry3Hash)
    expect(entry1Hash).not.toBe(entry3Hash)

    // Each should be a valid hash
    expect(entry1Hash).toMatch(/^[0-9a-f]{64}$/)
    expect(entry2Hash).toMatch(/^[0-9a-f]{64}$/)
    expect(entry3Hash).toMatch(/^[0-9a-f]{64}$/)
  })

  it('tampering with a middle entry breaks the chain at the next entry', async () => {
    // Build a 3-entry chain
    const entry1Hash = await computeEntryHash({
      ...baseParams,
      previousHash: null,
      sequence: 1,
    })

    const entry2OriginalHash = await computeEntryHash({
      ...baseParams,
      previousHash: entry1Hash,
      sequence: 2,
      entityId: 'CP2',
    })

    const entry3Hash = await computeEntryHash({
      ...baseParams,
      previousHash: entry2OriginalHash,
      sequence: 3,
      entityId: 'CP3',
    })

    // Now simulate tampering: entry 2's payload is changed after insert,
    // producing a different hash
    const entry2TamperedHash = await computeEntryHash({
      ...baseParams,
      previousHash: entry1Hash,
      sequence: 2,
      entityId: 'CP2',
      payload: { ...baseParams.payload, reason: 'FABRICATED REASON' },
    })

    // The tampered hash is different from the original
    expect(entry2TamperedHash).not.toBe(entry2OriginalHash)

    // Entry 3's stored previousHash (entry2OriginalHash) no longer matches
    // entry 2's actual hash (entry2TamperedHash) — chain is broken.
    // verifyChain() would flag this as a brokenLink at entry 3.
    expect(entry3Hash).not.toBe(entry2TamperedHash)
    // (In a real verification, we'd compare entry3.previousHash against
    // entry2.entryHash and detect the mismatch.)
  })

  it('inserting an entry mid-chain breaks the link at the next entry', async () => {
    // Original chain: entry1 → entry2 → entry3
    const entry1Hash = await computeEntryHash({
      ...baseParams,
      previousHash: null,
      sequence: 1,
    })
    const entry2Hash = await computeEntryHash({
      ...baseParams,
      previousHash: entry1Hash,
      sequence: 2,
      entityId: 'CP2',
    })
    const entry3Hash = await computeEntryHash({
      ...baseParams,
      previousHash: entry2Hash,
      sequence: 3,
      entityId: 'CP3',
    })

    // Simulate insertion of a fake entry between 2 and 3.
    // The fake entry claims previousHash = entry2Hash (correct link to entry 2).
    const fakeEntryHash = await computeEntryHash({
      ...baseParams,
      previousHash: entry2Hash,
      sequence: 4, // gets a new sequence number
      entityId: 'CP-FAKE',
    })

    // But entry 3's stored previousHash is still entry2Hash, not fakeEntryHash.
    // verifyChain() walks by sequence and would see:
    //   entry 3 (seq 3) has previousHash = entry2Hash
    //   but the entry at seq 2 is entry 2 with entryHash = entry2Hash ← matches
    //   however, the fake entry at seq 4 sits between entry 3 and the next real entry
    // The fake entry's previousHash (entry2Hash) doesn't match entry 3's entryHash
    // (entry3Hash) — so the link from entry 3 to the fake entry is broken.
    expect(fakeEntryHash).not.toBe(entry3Hash)
    // (Real verification would detect this when walking seq 3 → seq 4.)
  })
})

// ─── Type safety ───────────────────────────────────────────────────────

describe('type safety', () => {
  it('accepts all valid AuditEntityType values', async () => {
    const types = [
      'control_point', 'traverse', 'leveling', 'parcel', 'alignment',
      'surface', 'volume', 'transformation', 'document', 'system', 'custom',
    ] as const

    for (const entityType of types) {
      const hash = await computeEntryHash({ ...baseParams, entityType })
      expect(hash).toMatch(/^[0-9a-f]{64}$/)
    }
  })

  it('accepts all valid AuditAction values', async () => {
    const actions = [
      'create', 'update', 'delete', 'adjust', 'generate', 'submit',
      'lock', 'unlock', 'sign', 'validate', 'import', 'export', 'custom',
    ] as const

    for (const action of actions) {
      const hash = await computeEntryHash({ ...baseParams, action })
      expect(hash).toMatch(/^[0-9a-f]{64}$/)
    }
  })
})

import NextAuth, { AuthOptions } from 'next-auth'
import CredentialsProvider from 'next-auth/providers/credentials'
import GoogleProvider from 'next-auth/providers/google'
import AzureADProvider from 'next-auth/providers/azure-ad'
import bcrypt from 'bcryptjs'
import { db } from '@/lib/db'
import { checkLoginAllowed, recordFailedLogin, recordSuccessfulLogin, getFailedAttemptCount } from '@/lib/security/loginLimiter'
import { logger } from '@/lib/logger'

/** Sentinel password hash for OAuth-only users (no password login possible) */
const OAUTH_NO_PASSWORD = 'OAUTH_NO_PASSWORD'

// ─── Row types ───────────────────────────────────────────────────────────────
interface AuthUserRow {
  id: string
  email: string
  password_hash: string
  full_name: string | null
  isk_number: string | null
  verified_isk: boolean
  role: string | null
  provider: string | null
  oauth_avatar_url: string | null
}

interface NewUserRow {
  id: string
  email: string
  full_name: string | null
  role: string
  provider: string | null
}

/**
 * Find or create a user record when they sign in via OAuth for the first time.
 *
 * - If a user with the same email already exists, link the OAuth account
 *   by updating the provider info (but keep their existing role/password).
 * - If no user exists, create a new record with role='user' and the
 *   OAUTH_NO_PASSWORD sentinel so that password login is impossible.
 */
async function findOrCreateOAuthUser(params: {
  email: string
  name?: string | null
  image?: string | null
  provider: string
  providerAccountId: string
}): Promise<{
  id: string
  email: string
  name: string
  role: string
  isk_number: string
  verified_isk: boolean
  provider: string
  image?: string | null
}> {
  const { email, name, image, provider, providerAccountId } = params
  const normalisedEmail = email.toLowerCase().trim()

  // Try to find existing user by email
  const { rows } = await db.query<AuthUserRow>(
    'SELECT id, email, password_hash, full_name, isk_number, verified_isk, role, provider, oauth_avatar_url FROM users WHERE email = $1 LIMIT 1',
    [normalisedEmail]
  )

  if (rows.length > 0) {
    // ── Existing user — link OAuth account ──
    const user = rows[0]

    // Determine role (reuse the same hierarchy logic as credentials)
    let role = user.role || 'user'
    // SECURITY: Platform owner email MUST be set via env var.
    // Previously hardcoded 'mohameddosho20@gmail.com' as default —
    // anyone controlling that Google account would get permanent
    // super_admin. Now: if env var is unset, no one gets super_admin
    // via this path (must be granted manually in DB).
    const platformOwnerEmail = process.env.PLATFORM_OWNER_EMAIL?.toLowerCase()
    if (platformOwnerEmail && user.email.toLowerCase() === platformOwnerEmail) {
      role = 'super_admin'
    }
    const adminEmails = (process.env.ADMIN_EMAILS || '').split(',').map((e: string) => e.trim().toLowerCase()).filter(Boolean)
    if (adminEmails.includes(user.email.toLowerCase())) {
      role = 'super_admin'
    }

    // Update provider info and avatar (don't override password_hash or role)
    await db.query(
      `UPDATE users SET
         provider = COALESCE(provider, $1),
         oauth_provider_id = COALESCE(oauth_provider_id, $2),
         oauth_avatar_url = COALESCE(oauth_avatar_url, $3),
         updated_at = NOW()
       WHERE id = $4`,
      [provider, providerAccountId, image || null, user.id]
    )

    // Ensure surveyor_profile exists
    try {
      await db.query(
        `INSERT INTO surveyor_profiles (id, user_id, role, is_suspended)
         VALUES (gen_random_uuid(), $1, $2, false)
         ON CONFLICT (user_id) DO NOTHING`,
        [user.id, role]
      )
    } catch {
      // Non-critical
    }

    return {
      id: user.id,
      email: user.email,
      name: user.full_name || name || user.email.split('@')[0],
      role,
      isk_number: user.isk_number || '',
      verified_isk: user.verified_isk || false,
      provider: user.provider || provider,
      image: image || user.oauth_avatar_url || null,
    }
  }

  // ── New user — create record ──
  const displayName = name || normalisedEmail.split('@')[0]
  const insertResult = await db.query<NewUserRow>(
    `INSERT INTO users (email, password_hash, full_name, role, provider, oauth_provider_id, oauth_avatar_url)
     VALUES ($1, $2, $3, 'user', $4, $5, $6)
     RETURNING id, email, full_name, role, provider`,
    [normalisedEmail, OAUTH_NO_PASSWORD, displayName, provider, providerAccountId, image || null]
  )

  const newUser = insertResult.rows[0]

  // Create surveyor_profile for the new user
  try {
    await db.query(
      `INSERT INTO surveyor_profiles (id, user_id, role, is_suspended)
       VALUES (gen_random_uuid(), $1, 'user', false)
       ON CONFLICT (user_id) DO NOTHING`,
      [newUser.id]
    )
  } catch {
    // Non-critical
  }

  // Create profile entry
  try {
    await db.query(
      `INSERT INTO profiles (id, full_name, avatar_url)
       VALUES ($1, $2, $3)
       ON CONFLICT (id) DO NOTHING`,
      [newUser.id, displayName, image || null]
    )
  } catch {
    // Non-critical
  }

  return {
    id: newUser.id,
    email: newUser.email,
    name: newUser.full_name || displayName,
    role: 'user',
    isk_number: '',
    verified_isk: false,
    provider,
    image: image || null,
  }
}

export const authOptions: AuthOptions = {
  providers: [
    // ── Credentials (email + password) ──────────────────────────────────────
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
      },
      async authorize(credentials, req) {
        if (!credentials?.email || !credentials?.password) return null

        // Get client IP from the request
        // Note: In NextAuth v4, req can be a Request or an IncomingMessage
        // headers may be a Headers object (with .get()) or a plain object (with direct access)
        let forwarded = ''
        try {
          const headers = req?.headers
          if (headers && typeof (headers as Record<string, unknown>).get === 'function') {
            forwarded = (headers as { get: (n: string) => string | null }).get('x-forwarded-for') || ''
          } else if (headers) {
            forwarded = (headers as Record<string, string>)['x-forwarded-for'] || ''
          }
        } catch {
          forwarded = ''
        }
        const clientIp = forwarded.split(',')[0]?.trim() || 'unknown'

        // Check brute-force lockout BEFORE checking credentials
        const loginCheck = await checkLoginAllowed(credentials.email, clientIp)
        if (!loginCheck.allowed) {
          logger.warn(`[auth] Login blocked for ${credentials.email} from ${clientIp}: ${loginCheck.reason}`)
          return null
        }

        try {
          const { rows } = await db.query<Omit<AuthUserRow, 'oauth_avatar_url'>>(
            'SELECT id, email, password_hash, full_name, isk_number, verified_isk, role, provider FROM users WHERE email = $1 LIMIT 1',
            [credentials.email.toLowerCase().trim()]
          )

          if (rows.length === 0) {
            await recordFailedLogin(credentials.email, clientIp)
            return null
          }

          const user = rows[0]

          // Block password login for OAuth-only accounts
          if (user.password_hash === OAUTH_NO_PASSWORD) {
            logger.warn(`[auth] Password login attempted on OAuth-only account: ${user.email}`)
            await recordFailedLogin(credentials.email, clientIp)
            return null
          }

          const valid = await bcrypt.compare(credentials.password, user.password_hash)
          if (!valid) {
            await recordFailedLogin(credentials.email, clientIp)
            const remaining = 5 - await getFailedAttemptCount(credentials.email, clientIp)
            if (remaining <= 2 && remaining > 0) {
              logger.warn(`[auth] ${remaining} attempts remaining for ${credentials.email} from ${clientIp}`)
            }
            return null
          }

          // Check if account is suspended
          try {
            const { rows: profileRows } = await db.query<{ is_suspended: boolean; suspension_reason: string | null }>(
              'SELECT is_suspended, suspension_reason FROM surveyor_profiles WHERE user_id = $1 LIMIT 1',
              [user.id]
            )
            if (profileRows.length > 0 && profileRows[0].is_suspended) {
              logger.warn(`[auth] Suspended account login attempt: ${user.email}`)
              return null
            }
          } catch {
            // surveyor_profiles may not exist yet — allow login anyway
          }

          // Successful login — clear failure count
          await recordSuccessfulLogin(credentials.email, clientIp)

          // Determine role — priority: hardcoded owner > ADMIN_EMAILS > users.role > surveyor_profiles.role > 'surveyor'
          let role = user.role || 'surveyor'

          // Platform owner always gets super_admin regardless of env var or DB state
          // SECURITY: env var required — see comment above
          const platformOwnerEmail = process.env.PLATFORM_OWNER_EMAIL?.toLowerCase()
          if (platformOwnerEmail && user.email.toLowerCase() === platformOwnerEmail) {
            role = 'super_admin'
          }

          const adminEmails = (process.env.ADMIN_EMAILS || '').split(',').map((e: string) => e.trim().toLowerCase()).filter(Boolean)
          if (adminEmails.includes(user.email.toLowerCase())) {
            role = 'super_admin'
          } else if (!role || role === 'user') {
            // Fallback: check surveyor_profiles table
            try {
              const { rows: profileRows } = await db.query<{ role: string | null }>(
                'SELECT role FROM surveyor_profiles WHERE user_id = $1 LIMIT 1',
                [user.id]
              )
              if (profileRows.length > 0 && profileRows[0].role) {
                role = profileRows[0].role
              }
            } catch {
              // Table may not exist — keep default
            }

            // Ensure the user has a surveyor_profile (auto-create if missing)
            try {
              await db.query(
                `INSERT INTO surveyor_profiles (id, user_id, role, is_suspended)
                 VALUES (gen_random_uuid(), $1, $2, false)
                 ON CONFLICT (user_id) DO NOTHING`,
                [user.id, role]
              )
            } catch {
              // Non-critical — continue login
            }
          }

          return {
            id: user.id,
            email: user.email,
            name: user.full_name || user.email.split('@')[0],
            isk_number: user.isk_number || '',
            verified_isk: user.verified_isk || false,
            role,
            provider: user.provider || 'credentials',
          }
        } catch (err) {
          logger.error('[auth] Login DB error:', { error: err })
          return null
        }
      },
    }),

    // ── Google OAuth ────────────────────────────────────────────────────────
    // SECURITY FIX (ByteByteGo audit): allowDangerousEmailAccountLinking was true,
    // which let an attacker register a Google account with a victim's email and
    // gain access. Now false — OAuth accounts must be explicitly linked.
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID || '',
      clientSecret: process.env.GOOGLE_CLIENT_SECRET || '',
      allowDangerousEmailAccountLinking: false,
    }),

    // ── Microsoft / Azure AD OAuth ──────────────────────────────────────────
    AzureADProvider({
      clientId: process.env.AZURE_AD_CLIENT_ID || '',
      clientSecret: process.env.AZURE_AD_CLIENT_SECRET || '',
      tenantId: 'common', // Allow both work/school and personal Microsoft accounts
      allowDangerousEmailAccountLinking: false,
    }),
  ],
  callbacks: {
    /**
     * signIn callback — controls whether a sign-in is allowed.
     * For OAuth providers, we verify the email is present (OAuth providers
     * guarantee email verification). We also create/link the user record.
     */
    async signIn({ user, account, profile }) {
      // Credentials provider handles its own auth in authorize() — always allow
      if (account?.provider === 'credentials') {
        return true
      }

      // OAuth providers (google, azure-ad)
      if (account?.provider === 'google' || account?.provider === 'azure-ad') {
        // OAuth providers guarantee email_verified, but double-check
        if (!user.email) {
          logger.warn(`[auth] OAuth sign-in rejected: no email from ${account.provider}`)
          return false
        }

        // Google specifically provides email_verified in the profile
        const googleProfile = profile as Record<string, unknown> | undefined
        if (account.provider === 'google' && googleProfile?.email_verified === false) {
          logger.warn(`[auth] Google OAuth sign-in rejected: email not verified for ${user.email}`)
          return false
        }

        // Azure AD: for work/school accounts email is always verified.
        // For personal Microsoft accounts (tenantId === '9188040d-6c67-4c5b-b112-36a304b66dad'),
        // email may not be verified — but we accept them since they've authenticated.
        // If you want stricter verification, check profile?.email_verified here too.

        try {
          const oauthUser = await findOrCreateOAuthUser({
            email: user.email,
            name: user.name,
            image: user.image,
            provider: account.provider,
            providerAccountId: account.providerAccountId,
          })

          // Attach DB fields to the user object so jwt callback can access them
          user.id = oauthUser.id
          user.name = oauthUser.name
          user.role = oauthUser.role
          user.isk_number = oauthUser.isk_number
          user.verified_isk = oauthUser.verified_isk
          user.provider = oauthUser.provider
          user.image = oauthUser.image

          // Check if account is suspended
          try {
            const { rows: profileRows } = await db.query<{ is_suspended: boolean }>(
              'SELECT is_suspended FROM surveyor_profiles WHERE user_id = $1 LIMIT 1',
              [oauthUser.id]
            )
            if (profileRows.length > 0 && profileRows[0].is_suspended) {
              logger.warn(`[auth] Suspended OAuth account login attempt: ${user.email}`)
              return false
            }
          } catch {
            // surveyor_profiles may not exist — allow sign-in
          }

          return true
        } catch (err) {
          logger.error('[auth] OAuth user creation/linking error:', { error: err })
          return false
        }
      }

      // Unknown provider — reject
      logger.warn(`[auth] Unknown provider: ${account?.provider}`)
      return false
    },

    async jwt({ token, user, account }) {
      // On first sign-in, `user` is populated from the provider/authorize()
      if (user) {
        token.id = user.id
        token.email = user.email
        token.name = user.name || user.email?.split('@')[0] || ''
        token.isk_number = user.isk_number || ''
        token.verified_isk = user.verified_isk || false
        token.role = (user as { role?: string }).role || 'user'
        token.provider = (user as { provider?: string }).provider || account?.provider || 'credentials'
      }
      return token
    },

    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id as string
        session.user.email = token.email as string
        session.user.name = token.name as string
        session.user.isk_number = token.isk_number as string
        session.user.verified_isk = token.verified_isk as boolean
        session.user.role = token.role as string
        session.user.provider = token.provider as string
      }
      return session
    },
  },
  pages: {
    signIn: '/login',
  },
  session: {
    strategy: 'jwt',
    maxAge: 7 * 24 * 60 * 60, // 7 days (reduced from 30 for security)
  },
  secret: (() => {
    const s = process.env.AUTH_SECRET || process.env.NEXTAUTH_SECRET
    if (!s) {
      // During build, provide a dummy value — the app won't actually run
      if (process.env.NEXT_PHASE === 'phase-production-build') {
        logger.warn('[auth] AUTH_SECRET not set during build — using dummy. Set it before running the app.')
        return 'build-time-dummy-secret-do-not-use-in-production'
      }
      // Fail hard at runtime — never use a dummy secret in production
      throw new Error('AUTH_SECRET is not set. Run: openssl rand -base64 32')
    }
    return s
  })(),
}

/**
 * Redis Cache Layer for METARDU
 * Enterprise-grade caching for API responses and session data
 */

import { createClient } from 'redis'
import { logger } from '@/lib/logger'

const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379'
const IS_NEXT_BUILD = process.env.NEXT_PHASE === 'phase-production-build'

class RedisCache {
  private client: ReturnType<typeof createClient> | null = null
  private isConnected = false
  private connectionAttempted = false
  private disabled = false

  async connect(): Promise<void> {
    if (this.isConnected || this.disabled || IS_NEXT_BUILD) return

    try {
      this.connectionAttempted = true
      this.client = createClient({
        url: REDIS_URL,
        socket: {
          reconnectStrategy: false,
        },
      })
      this.client.on('error', () => {
        this.disabled = true
      })
      await this.client.connect()
      this.isConnected = true
    } catch (error) {
      this.disabled = true
      this.client = null
      if (process.env.NODE_ENV !== 'production') {
        logger.warn('[Redis] Cache disabled; Redis is not reachable.')
      }
    }
  }

  async get<T>(key: string): Promise<T | null> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return null

    try {
      const value = await this.client.get(key)
      return value ? JSON.parse(value as string) as T : null
    } catch {
      return null
    }
  }

  async set<T>(key: string, value: T, ttlSeconds = 300): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      await this.client.setEx(key, ttlSeconds, JSON.stringify(value))
    } catch {
      // Silently fail - app continues working
    }
  }

  async del(key: string): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      await this.client.del(key)
    } catch {
      // Silently fail
    }
  }

  async delPattern(pattern: string): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      // ByteByteGo audit fix: use SCAN instead of KEYS to avoid blocking Redis
      // in production. KEYS * scans the entire keyspace and blocks the event loop.
      // SCAN is non-blocking and returns { cursor, keys } for iteration.
      let cursor = '0'
      do {
        const result = await this.client.scan(cursor, { MATCH: pattern, COUNT: 100 })
        cursor = result.cursor
        const keys = result.keys
        if (keys.length > 0) {
          await this.client.del(keys)
        }
      } while (cursor !== '0')
    } catch {
      // Silently fail
    }
  }

  async getOrSet<T>(key: string, factory: () => Promise<T>, ttlSeconds = 300): Promise<T> {
    const cached = await this.get<T>(key)
    if (cached) return cached

    const value = await factory()
    await this.set(key, value, ttlSeconds)
    return value
  }

  async increment(key: string, amount = 1): Promise<number> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return 0

    try {
      return await this.client.incrBy(key, amount) as number
    } catch {
      return 0
    }
  }

  async expire(key: string, seconds: number): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      await this.client.expire(key, seconds)
    } catch {
      // Silently fail
    }
  }

  // Cache keys generators
  static keys = {
    project: (id: string) => `project:${id}`,
    projectList: (userId: string) => `projects:list:${userId}`,
    surveyPoints: (projectId: string) => `survey_points:${projectId}`,
    submissions: (projectId: string) => `submissions:${projectId}`,
    surveyTool: (tool: string, params: string) => `tool:${tool}:${params}`,
    userSession: (sessionId: string) => `session:${sessionId}`,
    rateLimit: (key: string) => `ratelimit:${key}`,
  }
}

// Singleton instance
const redisCache = new RedisCache()
export default redisCache
export { RedisCache }

// Helper for API route caching
export function withCache<T>(
  fn: () => Promise<T>,
  key: string,
  ttlSeconds = 300
): Promise<T> {
  return redisCache.getOrSet(key, fn, ttlSeconds)
}

// Cache middleware for Next.js API routes
export async function cacheMiddleware(
  request: Request,
  cacheKey: string,
  ttlSeconds = 60
): Promise<Response | null> {
  // Only cache GET requests
  if (request.method !== 'GET') return null

  const cached = await redisCache.get<ResponseCache>(cacheKey)
  if (cached) {
    return new Response(JSON.stringify(cached.data), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'X-Cache': 'HIT',
        'X-Cache-TTL': ttlSeconds.toString(),
      },
    })
  }

  return null
}

interface ResponseCache {
  data: unknown
  timestamp: number
}

// ============================================================
// METARDU — Cross-Section / Longitudinal Profile PDF Generator
// Professional A3 Landscape output for Kenya surveying
// Survey Act Cap 299, Survey Regulations L.N. 168/1994
//
// Generates longitudinal and cross-section profiles used in
// road design, canal construction, and terrain analysis.
//
// A3 Landscape (420 mm × 297 mm)
// No external charting library — uses jsPDF drawing primitives.
//
// Usage:
//   import { generateCrossSectionPdf, CrossSectionData } from './crossSectionPdf'
//   const pdf = generateCrossSectionPdf(data)
//   // pdf is a Uint8Array
// ============================================================

import jsPDF from 'jspdf'

// ============================================================
// EXPORTED INTERFACES
// ============================================================

export interface CrossSectionPoint {
  /** Distance along the alignment in metres */
  chainage: number
  /** Ground level in metres */
  elevation: number
  /** Design / formation level (for road profiles) */
  designLevel?: number
  /** Existing ground level (when different from elevation) */
  existingLevel?: number
}

export interface CrossSectionData {
  // ── Document metadata ──────────────────────────────────────
  documentNumber: string
  projectName: string
  projectNumber: string

  // ── Profile settings ──────────────────────────────────────
  profileType: 'LONGITUDINAL' | 'CROSS_SECTION'
  /** e.g. "Chainage 0+000 to 0+500 — Road A" */
  title: string

  // ── Scale ─────────────────────────────────────────────────
  /** e.g. 1:1000 */
  horizontalScale: number
  /** e.g. 1:100 */
  verticalScale: number
  /** computed as hScale / vScale, e.g. 10 */
  verticalExaggeration: number

  // ── Datum ─────────────────────────────────────────────────
  /** e.g. "MSL (Mean Sea Level)" */
  datum: string

  // ── Profile data ──────────────────────────────────────────
  points: CrossSectionPoint[]

  // ── Grid settings ─────────────────────────────────────────
  /** e.g. 50 (every 50 m) */
  majorGridInterval: number
  /** e.g. 10 */
  minorGridInterval: number
  /** 20m interval per RDM 1.1 Section 5.6.2 — set to 20 for road surveys */
  crossSectionInterval?: number

  // ── Surveyor info ─────────────────────────────────────────
  surveyorName: string
  iskNumber: string
  firmName: string
  surveyDate: string

  // ── Optional design parameters ────────────────────────────
  showDesignLevel?: boolean
  /** e.g. "Camber 2.5%, Super Elevation 3%" */
  designDescription?: string
  /** formation width in metres */
  formationWidth?: number

  // ── Notes ─────────────────────────────────────────────────
  notes?: string
}

// ============================================================
// INTERNAL TYPES & CONSTANTS
// ============================================================

type RGB = [number, number, number]

/** A3 landscape */
const PW = 420
const PH = 297

/** METARDU navy — matches CLA forms and other PDF generators */
const NAVY: RGB = [27, 58, 92]
const WHITE: RGB = [255, 255, 255]
const BLACK: RGB = [0, 0, 0]
const DKGRAY: RGB = [90, 90, 90]
const GRAY: RGB = [170, 170, 170]
const LTGRAY: RGB = [215, 215, 215]
const VLTGRAY: RGB = [240, 240, 240]

const GROUND_CLR: RGB = [0, 90, 30]
const DESIGN_CLR: RGB = [190, 15, 15]
const CUT_SHADE: RGB = [255, 205, 205]
const FILL_SHADE: RGB = [205, 222, 255]
const TBL_ALT: RGB = [243, 246, 250]
const BORDER: RGB = [195, 200, 208]

// ============================================================
// HELPER FUNCTIONS
// ============================================================

/** Format a chainage in metres as "0+000" (km+m padded). */
function fmtChainage(metres: number): string {
  const sign = metres < 0 ? '-' : ''
  const abs = Math.abs(metres)
  const km = Math.floor(abs / 1000)
  const rem = Math.round(abs % 1000)
  return `${sign}${km}+${String(rem).padStart(3, '0')}`
}

/** Return a "nice" round interval for grid lines. */
function niceInterval(range: number, targetLines = 6): number {
  if (range <= 0) return 1
  const rough = range / targetLines
  const mag = Math.pow(10, Math.floor(Math.log10(rough)))
  const res = rough / mag
  const n = res <= 1.5 ? 1 : res <= 3.5 ? 2 : res <= 7.5 ? 5 : 10
  return n * mag
}

/** Grade (%) between two consecutive survey points. */
function gradeBetween(
  a: CrossSectionPoint,
  b: CrossSectionPoint,
): number {
  const d = b.chainage - a.chainage
  if (d === 0) return 0
  return ((b.elevation - a.elevation) / d) * 100
}

/** Decimal precision for elevation labels based on grid interval. */
function elevPrecision(interval: number): number {
  if (interval < 0.5) return 2
  if (interval < 5) return 1
  return 0
}

// ============================================================
// DRAWING AREA LAYOUT
// ============================================================

interface DrawingArea {
  /** Left edge (mm) — space for elevation labels */
  l: number
  /** Top edge (mm) */
  t: number
  /** Width (mm) */
  w: number
  /** Height (mm) */
  h: number
}

// ============================================================
// MAIN EXPORT
// ============================================================

export function generateCrossSectionPdf(
  data: CrossSectionData,
): Uint8Array {
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3',
  })

  // ── 1. Process & sort data ───────────────────────────────
  const pts = [...data.points].sort((a, b) => a.chainage - b.chainage)

  if (pts.length === 0) {
    doc.setFontSize(12)
    doc.setFont('helvetica', 'italic')
    doc.text(
      'No survey data provided.',
      PW / 2,
      PH / 2,
      { align: 'center' },
    )
    return doc.output('arraybuffer') as unknown as Uint8Array
  }

  const cMin = pts[0].chainage
  const cMax = pts[pts.length - 1].chainage
  const cRange = Math.max(cMax - cMin, 1)

  // Gather every elevation value (ground + design + existing) for range
  const allElevs = pts.flatMap(
    (p) =>
      [p.elevation, p.designLevel, p.existingLevel].filter(
        (v): v is number => v != null,
      ),
  )
  const eMin = Math.min(...allElevs)
  const eMax = Math.max(...allElevs)
  const eRange = Math.max(eMax - eMin, 0.1)

  // Add 12 % vertical padding
  const ePad = Math.max(eRange * 0.12, 0.5)
  const eEffMin = eMin - ePad
  const eEffMax = eMax + ePad
  const eEffRange = eEffMax - eEffMin

  // ── 2. Drawing area geometry ─────────────────────────────
  const DA: DrawingArea = { l: 38, t: 46, w: 335, h: 120 }
  const DA_B = DA.t + DA.h

  // ── 3. Coordinate mapping ────────────────────────────────
  const cToX = (c: number): number =>
    DA.l + ((c - cMin) / cRange) * DA.w
  const eToY = (e: number): number =>
    DA_B - ((e - eEffMin) / eEffRange) * DA.h

  // ── 4. Grid intervals ────────────────────────────────────
  const cMajor = data.majorGridInterval
  const cMinor = data.minorGridInterval
  const eMajInt = niceInterval(eEffRange, 6)
  const eMinInt = eMajInt / 5

  // ==========================================================
  // HEADER BLOCK
  // ==========================================================
  drawHeader(doc, data)

  // ==========================================================
  // MINOR GRID
  // ==========================================================
  drawMinorGrid(doc, DA, cToX, eToY, cMin, cMax, eEffMin, eEffMax, cMajor, cMinor, eMajInt, eMinInt)

  // ==========================================================
  // MAJOR GRID
  // ==========================================================
  drawMajorGrid(doc, DA, cToX, eToY, cMin, cMax, eEffMin, eEffMax, cMajor, cMinor, eMajInt, eMinInt)

  // ==========================================================
  // DRAWING AREA BORDER
  // ==========================================================
  doc.setDrawColor(...BLACK)
  doc.setLineWidth(0.5)
  doc.rect(DA.l, DA.t, DA.w, DA.h)

  // ==========================================================
  // AXIS TITLES
  // ==========================================================
  drawAxisTitles(doc, DA)

  // ==========================================================
  // CUT / FILL SHADING (drawn BEFORE lines so lines sit on top)
  // ==========================================================
  if (data.showDesignLevel) {
    drawCutFillShading(doc, pts, cToX, eToY)
  }

  // ==========================================================
  // GROUND PROFILE LINE
  // ==========================================================
  drawGroundProfile(doc, pts, cToX, eToY)

  // ==========================================================
  // DESIGN LINE
  // ==========================================================
  if (data.showDesignLevel) {
    drawDesignLine(doc, pts, cToX, eToY)
  }

  // ==========================================================
  // SURVEY POINT MARKERS
  // ==========================================================
  drawSurveyMarkers(doc, pts, cToX, eToY)

  // ==========================================================
  // KEY ELEVATION LABELS
  // ==========================================================
  drawKeyLabels(doc, pts, cToX, eToY)

  // ==========================================================
  // LEGEND
  // ==========================================================
  if (data.showDesignLevel) {
    drawLegend(doc, DA)
  }

  // ==========================================================
  // LEVEL TABLE
  // ==========================================================
  const tblX = DA.l
  const tblW = DA.w
  const colW = tblW / 5
  const tblStartY = DA_B + 12
  const tblHeadH = 7
  const tblRowH = 5.2

  // How many rows fit on page 1 before summary / cert / footer?
  const fixedBlock = 42 // summary + cert + footer + gaps
  const maxRowsP1 = Math.max(
    1,
    Math.floor((PH - tblStartY - tblHeadH - fixedBlock) / tblRowH),
  )
  const showRowsP1 = Math.min(pts.length, maxRowsP1)
  const needMorePages = pts.length > showRowsP1

  drawTableHeader(doc, tblX, tblStartY, colW, tblHeadH)
  drawTableRows(
    doc,
    pts,
    data,
    tblX,
    tblStartY + tblHeadH,
    colW,
    tblRowH,
    0,
    showRowsP1,
  )
  drawTableBorder(
    doc,
    tblX,
    tblStartY,
    colW,
    tblHeadH,
    showRowsP1,
    tblRowH,
  )

  if (needMorePages) {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(5.5)
    doc.setTextColor(...DKGRAY)
    doc.text(
      `\u2026 ${pts.length - showRowsP1} more row(s) on subsequent page(s)`,
      tblX + tblW,
      tblStartY + tblHeadH + showRowsP1 * tblRowH + 3,
      { align: 'right' },
    )
  }

  // ==========================================================
  // CONTINUATION PAGES (table only)
  // ==========================================================
  let contPageNum = 2
  let remIdx = showRowsP1
  while (remIdx < pts.length) {
    doc.addPage([PW, PH], 'landscape')
    const contHeaderY = 10

    // Mini header bar
    doc.setFillColor(...NAVY)
    doc.rect(0, 0, PW, 16, 'F')
    doc.setTextColor(...WHITE)
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.text(
      `${data.title} \u2014 Level Table (continued)`,
      PW / 2,
      7,
      { align: 'center' },
    )
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(6)
    doc.text(`Page ${contPageNum}`, PW - 12, 7, { align: 'right' })

    const contTableY = 20
    const contMaxRows = Math.floor((PH - contTableY - 20) / tblRowH)
    const contRows = Math.min(contMaxRows, pts.length - remIdx)

    drawTableHeader(doc, tblX, contTableY, colW, tblHeadH)
    drawTableRows(
      doc,
      pts,
      data,
      tblX,
      contTableY + tblHeadH,
      colW,
      tblRowH,
      remIdx,
      contRows,
    )
    drawTableBorder(
      doc,
      tblX,
      contTableY,
      colW,
      tblHeadH,
      contRows,
      tblRowH,
    )

    // Footer on continuation page
    doc.setFontSize(5.5)
    doc.setTextColor(...GRAY)
    doc.setFont('helvetica', 'italic')
    doc.text(
      'Generated by METARDU',
      PW / 2,
      PH - 5,
      { align: 'center' },
    )

    remIdx += contRows
    contPageNum++
  }

  // ==========================================================
  // SUMMARY STATISTICS (on page 1)
  // ==========================================================
  doc.setPage(1)
  const sumY =
    tblStartY + tblHeadH + showRowsP1 * tblRowH + (needMorePages ? 6 : 3)
  drawSummary(doc, data, pts, sumY, tblX, tblW)

  // ==========================================================
  // CERTIFICATION BLOCK (on page 1)
  // ==========================================================
  const certY = sumY + 22
  drawCertification(doc, data, certY, tblX, tblW)

  // ==========================================================
  // NOTES (if provided)
  // ==========================================================
  if (data.notes) {
    const notesY = certY + 28
    if (notesY < PH - 12) {
      doc.setFont('helvetica', 'italic')
      doc.setFontSize(6)
      doc.setTextColor(...DKGRAY)
      doc.text(`Notes: ${data.notes}`, tblX + 3, notesY)
    }
  }

  // ==========================================================
  // FOOTER — page numbers + watermark on every page
  // ==========================================================
  const totalPages = doc.getNumberOfPages()
  for (let p = 1; p <= totalPages; p++) {
    doc.setPage(p)

    const fy = PH - 8

    // Separator line
    doc.setDrawColor(...GRAY)
    doc.setLineWidth(0.2)
    doc.line(10, fy - 1.5, PW - 10, fy - 1.5)

    // Watermark
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(6)
    doc.setTextColor(150, 150, 150)
    doc.text(
      'Generated by METARDU \u2014 Land Surveying Platform',
      PW / 2,
      fy + 1.5,
      { align: 'center' },
    )

    // Page number
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.setTextColor(...DKGRAY)
    doc.text(`Page ${p} of ${totalPages}`, PW - 12, fy + 1.5, {
      align: 'right',
    })
  }

  // Reset state
  doc.setTextColor(0, 0, 0)

  return doc.output('arraybuffer') as unknown as Uint8Array
}

// ============================================================
// DRAWING SUB-ROUTINES
// ============================================================

// ────────────────────────────────────────────────────────────
// HEADER
// ────────────────────────────────────────────────────────────

function drawHeader(doc: jsPDF, data: CrossSectionData): void {
  // Navy background bar
  doc.setFillColor(...NAVY)
  doc.rect(0, 0, PW, 40, 'F')

  // Title line
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(11)
  doc.setTextColor(...WHITE)
  doc.text(
    'REPUBLIC OF KENYA \u2014 MINISTRY OF LANDS, HOUSING & URBAN DEVELOPMENT',
    PW / 2,
    8,
    { align: 'center' },
  )

  // Thin rule
  doc.setDrawColor(...WHITE)
  doc.setLineWidth(0.25)
  doc.line(10, 11, PW - 10, 11)

  // Project info row 1
  doc.setFontSize(7.5)
  doc.setFont('helvetica', 'normal')
  doc.text(`Project: ${data.projectName}`, 12, 16)
  doc.text(`Doc#: ${data.documentNumber}`, PW - 12, 16, { align: 'right' })

  // Project info row 2
  doc.text(`Project No: ${data.projectNumber}`, 12, 21)
  doc.text(`Date: ${data.surveyDate}`, PW - 12, 21, { align: 'right' })

  // Profile title (centred, bold)
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(10)
  doc.text(data.title, PW / 2, 27, { align: 'center' })

  // Scale / datum line
  doc.setFontSize(7)
  doc.setFont('helvetica', 'normal')
  const scaleLine = [
    `H: 1:${data.horizontalScale}`,
    `V: 1:${data.verticalScale}`,
    `V.Exag: ${data.verticalExaggeration}\u00d7`,
    `Datum: ${data.datum}`,
    `Type: ${data.profileType.replace('_', ' ')}`,
  ].join('    |    ')
  doc.text(scaleLine, PW / 2, 33, { align: 'center' })

  // Design description (if any)
  if (data.designDescription) {
    doc.setFontSize(6.5)
    doc.setFont('helvetica', 'italic')
    doc.text(`Design: ${data.designDescription}`, PW / 2, 37, {
      align: 'center',
    })
  }
}

// ────────────────────────────────────────────────────────────
// MINOR GRID (dashed, lighter)
// ────────────────────────────────────────────────────────────

function drawMinorGrid(
  doc: jsPDF,
  DA: DrawingArea,
  cToX: (c: number) => number,
  eToY: (e: number) => number,
  cMin: number,
  cMax: number,
  eEffMin: number,
  eEffMax: number,
  cMajor: number,
  cMinor: number,
  eMajInt: number,
  eMinInt: number,
): void {
  doc.setDrawColor(...LTGRAY)
  doc.setLineWidth(0.08)

  // Chainage minor grid (skip lines that coincide with major)
  const cStart = Math.ceil(cMin / cMinor) * cMinor
  for (let c = cStart; c <= cMax; c += cMinor) {
    if (cMajor > 0 && Math.abs(c % cMajor) < 0.001) continue
    const x = cToX(c)
    if (x < DA.l || x > DA.l + DA.w) continue
    doc.line(x, DA.t, x, DA.t + DA.h)
  }

  // Elevation minor grid
  const eStart = Math.ceil(eEffMin / eMinInt) * eMinInt
  for (let e = eStart; e <= eEffMax; e += eMinInt) {
    if (eMajInt > 0 && Math.abs(e % eMajInt) < 0.0001) continue
    const y = eToY(e)
    if (y < DA.t || y > DA.t + DA.h) continue
    doc.line(DA.l, y, DA.l + DA.w, y)
  }
}

// ────────────────────────────────────────────────────────────
// MAJOR GRID (solid, darker)
// ────────────────────────────────────────────────────────────

function drawMajorGrid(
  doc: jsPDF,
  DA: DrawingArea,
  cToX: (c: number) => number,
  eToY: (e: number) => number,
  cMin: number,
  cMax: number,
  eEffMin: number,
  eEffMax: number,
  cMajor: number,
  cMinor: number,
  eMajInt: number,
  eMinInt: number,
): void {
  doc.setDrawColor(...GRAY)
  doc.setLineWidth(0.2)

  const prec = elevPrecision(eMajInt)

  // Chainage major grid + labels
  const cStart = Math.ceil(cMin / cMajor) * cMajor
  for (let c = cStart; c <= cMax; c += cMajor) {
    const x = cToX(c)
    if (x < DA.l || x > DA.l + DA.w) continue
    doc.line(x, DA.t, x, DA.t + DA.h)

    // Tick mark below drawing area
    doc.setDrawColor(...BLACK)
    doc.setLineWidth(0.2)
    doc.line(x, DA.t + DA.h, x, DA.t + DA.h + 2)

    // Label
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(6)
    doc.setTextColor(...DKGRAY)
    doc.text(fmtChainage(c), x, DA.t + DA.h + 4, { align: 'center' })

    // Minor ticks between major
    doc.setDrawColor(...LTGRAY)
    doc.setLineWidth(0.1)
    const minorCount = cMajor / cMinor
    for (let m = 1; m < minorCount; m++) {
      const mc = c + m * cMinor
      const mx = cToX(mc)
      if (mx >= DA.l && mx <= DA.l + DA.w) {
        doc.line(mx, DA.t + DA.h, mx, DA.t + DA.h + 1)
      }
    }
  }

  // Elevation major grid + labels
  doc.setDrawColor(...GRAY)
  doc.setLineWidth(0.2)
  const eStart = Math.ceil(eEffMin / eMajInt) * eMajInt
  for (let e = eStart; e <= eEffMax; e += eMajInt) {
    const y = eToY(e)
    if (y < DA.t || y > DA.t + DA.h) continue
    doc.line(DA.l, y, DA.l + DA.w, y)

    // Tick mark to the left of drawing area
    doc.setDrawColor(...BLACK)
    doc.setLineWidth(0.2)
    doc.line(DA.l - 2, y, DA.l, y)

    // Label
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(6)
    doc.setTextColor(...DKGRAY)
    doc.text(e.toFixed(prec), DA.l - 3, y + 2, { align: 'right' })

    // Minor ticks
    doc.setDrawColor(...LTGRAY)
    doc.setLineWidth(0.1)
    for (let m = 1; m < 5; m++) {
      const me = e + m * eMinInt
      const my = eToY(me)
      if (my >= DA.t && my <= DA.t + DA.h) {
        doc.line(DA.l - 1, my, DA.l, my)
      }
    }
  }
}

// ────────────────────────────────────────────────────────────
// AXIS TITLES
// ────────────────────────────────────────────────────────────

function drawAxisTitles(doc: jsPDF, DA: DrawingArea): void {
  doc.setTextColor(...BLACK)
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(7)

  // X-axis title (chainage)
  doc.text('CHAINAGE (m)', DA.l + DA.w / 2, DA.t + DA.h + 9, {
    align: 'center',
  })

  // Y-axis title (elevation) — rotated
  doc.text('ELEVATION (m)', DA.l - 9, DA.t + DA.h / 2, {
    align: 'center',
    angle: 90,
  })
}

// ────────────────────────────────────────────────────────────
// CUT / FILL SHADING
// ────────────────────────────────────────────────────────────

function drawCutFillShading(
  doc: jsPDF,
  pts: CrossSectionPoint[],
  cToX: (c: number) => number,
  eToY: (e: number) => number,
): void {
  for (let i = 0; i < pts.length - 1; i++) {
    const p1 = pts[i]
    const p2 = pts[i + 1]
    if (p1.designLevel == null || p2.designLevel == null) continue

    const x1 = cToX(p1.chainage)
    const x2 = cToX(p2.chainage)
    const yg1 = eToY(p1.elevation)
    const yg2 = eToY(p2.elevation)
    const yd1 = eToY(p1.designLevel)
    const yd2 = eToY(p2.designLevel)

    // Average cut/fill for this segment
    const avg =
      (p1.elevation - p1.designLevel + p2.elevation - p2.designLevel) / 2

    const color: RGB =
      avg > 0.005 ? CUT_SHADE : avg < -0.005 ? FILL_SHADE : VLTGRAY

    doc.setFillColor(...color)

    // Draw as two triangles (a quad split along one diagonal)
    doc.triangle(x1, yg1, x2, yg2, x2, yd2, 'F')
    doc.triangle(x1, yg1, x2, yd2, x1, yd1, 'F')
  }
}

// ────────────────────────────────────────────────────────────
// GROUND PROFILE LINE
// ────────────────────────────────────────────────────────────

function drawGroundProfile(
  doc: jsPDF,
  pts: CrossSectionPoint[],
  cToX: (c: number) => number,
  eToY: (e: number) => number,
): void {
  doc.setDrawColor(...GROUND_CLR)
  doc.setLineWidth(0.7)
  doc.setLineDashPattern([], 0)

  for (let i = 0; i < pts.length - 1; i++) {
    const x1 = cToX(pts[i].chainage)
    const y1 = eToY(pts[i].elevation)
    const x2 = cToX(pts[i + 1].chainage)
    const y2 = eToY(pts[i + 1].elevation)
    doc.line(x1, y1, x2, y2)
  }
}

// ────────────────────────────────────────────────────────────
// DESIGN LINE
// ────────────────────────────────────────────────────────────

function drawDesignLine(
  doc: jsPDF,
  pts: CrossSectionPoint[],
  cToX: (c: number) => number,
  eToY: (e: number) => number,
): void {
  const designPts = pts.filter((p): p is CrossSectionPoint & { designLevel: number } => p.designLevel != null)
  if (designPts.length < 2) return

  doc.setDrawColor(...DESIGN_CLR)
  doc.setLineWidth(0.5)
  doc.setLineDashPattern([3, 2], 0)

  for (let i = 0; i < designPts.length - 1; i++) {
    const x1 = cToX(designPts[i].chainage)
    const y1 = eToY(designPts[i].designLevel)
    const x2 = cToX(designPts[i + 1].chainage)
    const y2 = eToY(designPts[i + 1].designLevel)
    doc.line(x1, y1, x2, y2)
  }

  // Reset dash
  doc.setLineDashPattern([], 0)
}

// ────────────────────────────────────────────────────────────
// SURVEY POINT MARKERS
// ────────────────────────────────────────────────────────────

function drawSurveyMarkers(
  doc: jsPDF,
  pts: CrossSectionPoint[],
  cToX: (c: number) => number,
  eToY: (e: number) => number,
): void {
  pts.forEach((p) => {
    const x = cToX(p.chainage)
    const y = eToY(p.elevation)

    // Filled circle
    doc.setFillColor(...GROUND_CLR)
    doc.circle(x, y, 1.4, 'F')

    // Thin border
    doc.setDrawColor(...BLACK)
    doc.setLineWidth(0.12)
    doc.circle(x, y, 1.4, 'S')
  })
}

// ────────────────────────────────────────────────────────────
// KEY ELEVATION LABELS (highest, lowest, grade-change points)
// ────────────────────────────────────────────────────────────

function drawKeyLabels(
  doc: jsPDF,
  pts: CrossSectionPoint[],
  cToX: (c: number) => number,
  eToY: (e: number) => number,
): void {
  if (pts.length < 2) return

  const labelled = new Set<CrossSectionPoint>()

  // Highest and lowest
  const highest = pts.reduce((a, b) =>
    a.elevation > b.elevation ? a : b,
  )
  const lowest = pts.reduce((a, b) =>
    a.elevation < b.elevation ? a : b,
  )
  labelled.add(highest)
  labelled.add(lowest)

  // Points with significant grade change (> 1 % between neighbours)
  for (let i = 1; i < pts.length - 1; i++) {
    const g1 = gradeBetween(pts[i - 1], pts[i])
    const g2 = gradeBetween(pts[i], pts[i + 1])
    if (Math.abs(g2 - g1) > 1) labelled.add(pts[i])
  }

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(5)

  labelled.forEach((p) => {
    const x = cToX(p.chainage)
    const y = eToY(p.elevation)
    const label = p.elevation.toFixed(2)
    const tw = doc.getTextWidth(label)

    // Background pill
    doc.setFillColor(255, 255, 255)
    doc.setDrawColor(200, 200, 200)
    doc.setLineWidth(0.12)
    doc.roundedRect(x - tw / 2 - 0.8, y - 8, tw + 1.6, 4.2, 0.6, 0.6, 'FD')

    // Text
    doc.setTextColor(...BLACK)
    doc.text(label, x, y - 5, { align: 'center' })
  })
}

