/**
 * Machine Control Export
 *
 * AUDIT FIX (2026-07-03): Generates files for machine control systems
 * (Leica, Trimble, Topcon) that need 3D surface models + alignment
 * definitions for automated grading/excavation.
 *
 * Outputs:
 *   1. 3D DXF TIN surface (3DFACE entities with Z) — for importing
 *      design surfaces into machine control displays
 *   2. LandXML alignment (horizontal + vertical) — for Leica iCON /
 *      Trimble Business Center / Topcon 3D-MC
 *   3. Stakeout CSV (chainage, offset, easting, northing, design RL)
 *      — for robotic total station stakeout
 *
 * References:
 *   - Leica iCON: supports DXF 3DFACE + LandXML 1.2
 *   - Trimble 3D-MC: supports DXF + LandXML + proprietary .ttm
 *   - Topcon 3D-MC: supports DXF + LandXML
 */

import type { SpotHeight, TINSurface } from '@/lib/engine/contours'

export interface AlignmentPoint {
  chainage: number
  easting: number
  northing: number
  elevation: number
}

export interface MachineControlExport {
  dxf3D: string
  landXML: string
  stakeoutCSV: string
}

/**
 * Generate a 3D DXF TIN surface using 3DFACE entities.
 * Each triangle becomes a 3DFACE with four points (the 4th = 3rd for a triangle).
 */
export function generate3DDXFFromTIN(surface: TINSurface, layerName: string = 'DESIGN_SURFACE'): string {
  const lines: string[] = []

  // DXF header
  lines.push('0', 'SECTION')
  lines.push('2', 'HEADER')
  lines.push('9', '$ACADVER', '1', 'AC1015')
  lines.push('0', 'ENDSEC')

  // Tables section
  lines.push('0', 'SECTION', '2', 'TABLES')
  lines.push('0', 'TABLE', '2', 'LAYER', '70', '1')
  lines.push('0', 'LAYER', '2', layerName, '70', '0', '62', '3')
  lines.push('0', 'ENDTAB', '0', 'ENDSEC')

  // Entities section
  lines.push('0', 'SECTION', '2', 'ENTITIES')

  for (const tri of surface.triangles) {
    const p1 = tri.p1
    const p2 = tri.p2
    const p3 = tri.p3

    lines.push(
      '0', '3DFACE',
      '8', layerName,
      '10', p1.easting.toFixed(3),
      '20', p1.northing.toFixed(3),
      '30', (p1.elevation || 0).toFixed(3),
      '11', p2.easting.toFixed(3),
      '21', p2.northing.toFixed(3),
      '31', (p2.elevation || 0).toFixed(3),
      '12', p3.easting.toFixed(3),
      '22', p3.northing.toFixed(3),
      '32', (p3.elevation || 0).toFixed(3),
      '13', p3.easting.toFixed(3),  // 4th point = 3rd (triangle)
      '23', p3.northing.toFixed(3),
      '33', (p3.elevation || 0).toFixed(3),
    )
  }

  lines.push('0', 'ENDSEC')
  lines.push('0', 'EOF')

  return lines.join('\n')
}

/**
 * Generate a LandXML alignment file with horizontal + vertical curves.
 * Compatible with Leica iCON, Trimble Business Center, Topcon 3D-MC.
 */
export function generateAlignmentLandXML(
  alignmentName: string,
  horizontalPoints: AlignmentPoint[],
  verticalPoints: AlignmentPoint[],
  projectName: string,
): string {
  const now = new Date().toISOString()
  const lines: string[] = []

  lines.push('<?xml version="1.0" encoding="UTF-8"?>')
  lines.push(`<LandXML xmlns="http://www.landxml.org/schema/LandXML-1.2" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://www.landxml.org/schema/LandXML-1.2 http://www.landxml.org/schema/LandXML-1.2/LandXML-1.2.xsd" version="1.2" date="${now}" time="${now}" readOnly="false" language="English">`)

  // Project info
  lines.push('  <Units>', '    <Metric linearUnit="meter" areaUnit="squareMeter" volumeUnit="cubicMeter" directionUnit="decimalDegrees" temperatureUnit="celsius" pressureUnit="milliBar" diameterUnit="millimeter" angularUnit="decimalDegrees" latitudeUnit="decimalDegrees"/>', '  </Units>')
  lines.push(`  <Application name="METARDU" manufacturer="METARDU" version="1.0" manufacturerURL="https://metardu.space" timeStamp="${now}"/>`)

  // Alignments
  lines.push('  <Alignments name="' + projectName + '">')
  lines.push(`    <Alignment name="${alignmentName}" length="${horizontalPoints[horizontalPoints.length - 1]?.chainage || 0}" staStart="${horizontalPoints[0]?.chainage || 0}">`)

  // Horizontal alignment
  lines.push('      <CoordGeom>')
  for (let i = 0; i < horizontalPoints.length - 1; i++) {
    const p1 = horizontalPoints[i]
    const p2 = horizontalPoints[i + 1]
    lines.push('        <Line>')
    lines.push(`          <Start>${p1.northing.toFixed(4)} ${p1.easting.toFixed(4)}</Start>`)
    lines.push(`          <End>${p2.northing.toFixed(4)} ${p2.easting.toFixed(4)}</End>`)
    lines.push('        </Line>')
  }
  lines.push('      </CoordGeom>')

  // Vertical alignment (profile)
  if (verticalPoints.length > 1) {
    lines.push('      <Profile>')
    lines.push(`        <ProfAlign name="${alignmentName}_Vertical">`)
    for (const p of verticalPoints) {
      lines.push(`          <PVI>${p.chainage.toFixed(3)} ${p.elevation.toFixed(4)}</PVI>`)
    }
    lines.push('        </ProfAlign>')
    lines.push('      </Profile>')
  }

  lines.push('    </Alignment>')
  lines.push('  </Alignments>')

  // Stakeout points as CgPoints
  if (horizontalPoints.length > 0) {
    lines.push('  <CgPoints>')
    for (const p of horizontalPoints) {
      lines.push(`    <CgPoints>`)
      lines.push(`      <CgPoint name="CH${p.chainage.toFixed(0)}">${p.northing.toFixed(4)} ${p.easting.toFixed(4)} ${p.elevation.toFixed(4)}</CgPoint>`)
      lines.push(`    </CgPoints>`)
    }
    lines.push('  </CgPoints>')
  }

  lines.push('</LandXML>')

  return lines.join('\n')
}

/**
 * Generate a stakeout CSV for robotic total stations.
 * Format: point_name, easting, northing, design_elevation, chainage, offset
 */
export function generateStakeoutCSV(
  alignmentPoints: AlignmentPoint[],
  offset: number = 0,
  interval: number = 20,
): string {
  const lines = ['point_name,easting,northing,design_elevation,chainage,offset']

  // Generate stakeout points at regular intervals
  let currentChainage = alignmentPoints[0]?.chainage || 0
  const endChainage = alignmentPoints[alignmentPoints.length - 1]?.chainage || 0

  while (currentChainage <= endChainage) {
    // Interpolate position at this chainage
    const point = interpolateAlignmentPoint(alignmentPoints, currentChainage)

    if (point) {
      // Apply offset (perpendicular to the alignment direction)
      let offsetE = point.easting
      let offsetN = point.northing

      if (offset !== 0) {
        // Find the bearing at this chainage
        const nextPoint = interpolateAlignmentPoint(alignmentPoints, currentChainage + 1)
        if (nextPoint) {
          const dE = nextPoint.easting - point.easting
          const dN = nextPoint.northing - point.northing
          const len = Math.sqrt(dE * dE + dN * dN)
          if (len > 0) {
            // Perpendicular direction (90° clockwise = right side)
            const perpE = dN / len
            const perpN = -dE / len
            offsetE = point.easting + perpE * offset
            offsetN = point.northing + perpN * offset
          }
        }
      }

      const name = `CH${String(Math.round(currentChainage)).padStart(4, '0')}${offset > 0 ? '_R' : offset < 0 ? '_L' : ''}`
      lines.push(`${name},${offsetE.toFixed(3)},${offsetN.toFixed(3)},${point.elevation.toFixed(3)},${currentChainage.toFixed(3)},${offset.toFixed(3)}`)
    }

    currentChainage += interval
  }

  return lines.join('\n')
}

/**
 * Interpolate a point on the alignment at a given chainage.
 */
function interpolateAlignmentPoint(points: AlignmentPoint[], chainage: number): AlignmentPoint | null {
  if (points.length === 0) return null
  if (chainage <= points[0].chainage) return points[0]
  if (chainage >= points[points.length - 1].chainage) return points[points.length - 1]

  for (let i = 0; i < points.length - 1; i++) {
    if (chainage >= points[i].chainage && chainage <= points[i + 1].chainage) {
      const t = (chainage - points[i].chainage) / (points[i + 1].chainage - points[i].chainage)
      return {
        chainage,
        easting: points[i].easting + t * (points[i + 1].easting - points[i].easting),
        northing: points[i].northing + t * (points[i + 1].northing - points[i].northing),
        elevation: points[i].elevation + t * (points[i + 1].elevation - points[i].elevation),
      }
    }
  }

  return null
}

/**
 * Generate all machine control export files in one call.
 */
export function generateMachineControlExport(
  surface: TINSurface,
  horizontalPoints: AlignmentPoint[],
  verticalPoints: AlignmentPoint[],
  projectName: string,
  alignmentName: string = 'MAIN',
  offset: number = 0,
  interval: number = 20,
): MachineControlExport {
  return {
    dxf3D: generate3DDXFFromTIN(surface),
    landXML: generateAlignmentLandXML(alignmentName, horizontalPoints, verticalPoints, projectName),
    stakeoutCSV: generateStakeoutCSV(horizontalPoints, offset, interval),
  }
}

/**
 * METARDU Topographic Auto-Draw DXF Export
 * Phase B3 — Topo Auto-Draw
 *
 * Takes feature-coded points and auto-generates a DXF plan with:
 * - Layers mapped from the feature code library
 * - Polylines joining sequential points of the same code
 * - Point symbols (blocks or basic CAD entities)
 * - Point labels (elevation / point number)
 */

import Drawing from 'dxf-writer'
import { KENYA_TOPO_CODES, FeatureCodeDef } from '@/lib/topo/featureCodes'
import { initialiseSokDXFLayers, DXF_LAYERS } from '@/lib/drawing/dxfLayers'

export interface TopoPoint {
  easting: number
  northing: number
  elevation?: number
  code?: string
  pointNumber?: string
}

export interface TopoAutoDrawOptions {
  projectName?: string
  drawElevations?: boolean
  drawPointNumbers?: boolean
  defaultLayer?: string
}

export function generateTopoDXF(
  points: TopoPoint[],
  options?: TopoAutoDrawOptions
): string {
  if (!points || points.length === 0) return ''

  const drawing = new Drawing()
  initialiseSokDXFLayers(drawing)
  drawing.setUnits('Meters')

  // Register linetypes
  drawing.addLineType('DASHED', 'Dashed', [-5.0, 2.5])
  drawing.addLineType('CENTER', 'Center', [10.0, -2.5, 2.5, -2.5])
  drawing.addLineType('DOTTED', 'Dotted', [0, -2.5])

  // Build code lookup map
  const codeMap = new Map<string, FeatureCodeDef>()
  for (const def of KENYA_TOPO_CODES) {
    codeMap.set(def.code.toUpperCase(), def)
  }

  // Register layers dynamically based on codes present
  const usedCodes = new Set<string>()
  for (const pt of points) {
    if (pt.code) {
      const baseCode = pt.code.split(/\s+/)[0].toUpperCase()
      usedCodes.add(baseCode)
    }
  }

  const registeredLayers = new Set<string>()
  for (const code of Array.from(usedCodes)) {
    const def = codeMap.get(code)
    if (def && !registeredLayers.has(def.dxfLayer)) {
      drawing.addLayer(def.dxfLayer, def.color, def.lineType)
      registeredLayers.add(def.dxfLayer)
    }
  }

  // Group points by code for polyline generation
  // Format: MAP<code, Array<Array<TopoPoint>>>
  // Some field practices use string suffixes (e.g., RD1, RD2) to separate multiple strings of the same code.
  const lineStrings = new Map<string, TopoPoint[]>()
  
  for (const pt of points) {
    if (!pt.code) continue

    // The raw code might be "RD 1" or "RD1"
    const parts = pt.code.trim().split(/\s+/)
    const rawCode = parts[0].toUpperCase()
    
    // Attempt to extract base code (e.g., RD from RD1)
    const match = rawCode.match(/^([A-Z-]+)(\d*)$/)
    const baseCode = match ? match[1] : rawCode
    const stringId = rawCode // unique identifier for the string, e.g., RD1

    const def = codeMap.get(baseCode)
    if (!def) {
      // Fallback: draw as point on default layer
      drawPoint(drawing, pt, options?.defaultLayer ?? 'TOPO-UNKNOWN')
      continue
    }

    if (def.joinLines) {
      const arr = lineStrings.get(stringId) ?? []
      arr.push(pt)
      lineStrings.set(stringId, arr)
    } else {
      drawFeaturePoint(drawing, pt, def, options)
    }
  }

  // Draw Polylines
  for (const [stringId, pts] of Array.from(lineStrings.entries())) {
    const match = stringId.match(/^([A-Z-]+)(\d*)$/)
    const baseCode = match ? match[1] : stringId
    const def = codeMap.get(baseCode)
    if (!def) continue

    drawing.setActiveLayer(def.dxfLayer)
    
    // Draw lines
    for (let i = 0; i < pts.length - 1; i++) {
      const p1 = pts[i]
      const p2 = pts[i + 1]
      drawing.drawLine(p1.easting, p1.northing, p2.easting, p2.northing)
    }

    // Draw individual symbols/labels if needed
    for (const pt of pts) {
      drawFeaturePoint(drawing, pt, def, options, false) // false = don't set layer again
    }
  }

  return drawing.toDxfString()
}

function drawFeaturePoint(
  drawing: Drawing,
  pt: TopoPoint,
  def: FeatureCodeDef,
  options?: TopoAutoDrawOptions,
  setLayer: boolean = true
) {
  if (setLayer) {
    drawing.setActiveLayer(def.dxfLayer)
  }

  const sSize = 1.0 // symbol size
  
  // Draw Symbol
  if (def.symbol === 'circle') {
    drawing.drawCircle(pt.easting, pt.northing, sSize / 2)
  } else if (def.symbol === 'square') {
    const r = sSize / 2
    drawing.drawLine(pt.easting - r, pt.northing - r, pt.easting + r, pt.northing - r)
    drawing.drawLine(pt.easting + r, pt.northing - r, pt.easting + r, pt.northing + r)
    drawing.drawLine(pt.easting + r, pt.northing + r, pt.easting - r, pt.northing + r)
    drawing.drawLine(pt.easting - r, pt.northing + r, pt.easting - r, pt.northing - r)
  } else if (def.symbol === 'cross') {
    const r = sSize / 2
    drawing.drawLine(pt.easting - r, pt.northing, pt.easting + r, pt.northing)
    drawing.drawLine(pt.easting, pt.northing - r, pt.easting, pt.northing + r)
  } else if (def.symbol === 'triangle') {
    const r = sSize / 2
    drawing.drawLine(pt.easting - r, pt.northing - r, pt.easting + r, pt.northing - r)
    drawing.drawLine(pt.easting + r, pt.northing - r, pt.easting, pt.northing + r)
    drawing.drawLine(pt.easting, pt.northing + r, pt.easting - r, pt.northing - r)
  } else {
    // just a small tick
    drawing.drawPoint(pt.easting, pt.northing)
  }

  // Draw Labels
  if (def.pointLabel || options?.drawElevations || options?.drawPointNumbers) {
    let label = ''
    if ((def.pointLabel || options?.drawElevations) && pt.elevation !== undefined) {
      label += pt.elevation.toFixed(2)
    }
    if ((def.pointLabel || options?.drawPointNumbers) && pt.pointNumber) {
      label += (label ? ' / ' : '') + pt.pointNumber
    }

    if (label) {
      // Put labels on a generic ANNOTATIONS layer to keep them manageable, or the same layer
      // For now we keep them on the feature layer but shifted slightly
      drawing.drawText(pt.easting + 1, pt.northing + 1, 1.0, 0, label)
    }
  }
}

function drawPoint(drawing: Drawing, pt: TopoPoint, layerName: string) {
  drawing.setActiveLayer(layerName)
  drawing.drawPoint(pt.easting, pt.northing)
  drawing.drawText(pt.easting + 1, pt.northing + 1, 1.0, 0, pt.code ?? '?')
}

import { FieldProject, FieldExportOptions } from '@/types/field';

export function projectToGeoJSON(project: FieldProject): GeoJSON.FeatureCollection {
  const features: GeoJSON.Feature[] = [];

  project.beacons.forEach(b => {
    features.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [b.coordinate.lng, b.coordinate.lat] },
      properties: {
        label: b.label,
        beaconType: b.beaconType,
        notes: b.notes ?? '',
        capturedAt: new Date(b.capturedAt).toISOString(),
      },
    });
  });

  project.parcels.forEach(p => {
    if (p.walkPoints.length < 3) return;
    const coords = p.walkPoints.map(wp => [wp.coordinate.lng, wp.coordinate.lat]);
    coords.push(coords[0]); // close ring
    features.push({
      type: 'Feature',
      geometry: { type: 'Polygon', coordinates: [coords] },
      properties: {
        label: p.label,
        areaM2: p.computedAreaM2,
        areaHa: p.computedAreaM2 ? (p.computedAreaM2 / 10000).toFixed(4) : null,
        perimeterM: p.computedPerimeterM,
      },
    });
  });

  return { type: 'FeatureCollection', features };
}

function escapeXml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

export function exportToKML(project: FieldProject): string {
  const lines: string[] = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<kml xmlns="http://www.opengis.net/kml/2.2">',
    '<Document>',
    `  <name>${escapeXml(project.name)}</name>`,
    '  <description>Field data exported from Metardu</description>',
    '',
    '  <!-- Beacon Styles -->',
    '  <Style id="beaconStyle">',
    '    <IconStyle><color>ff00aaff</color><scale>1.2</scale>',
    '      <Icon><href>http://maps.google.com/mapfiles/kml/paddle/ylw-circle.png</href></Icon>',
    '    </IconStyle>',
    '    <LabelStyle><color>ff00aaff</color><scale>0.9</scale></LabelStyle>',
    '  </Style>',
    '  <Style id="parcelStyle">',
    '    <LineStyle><color>ff00cc44</color><width>2</width></LineStyle>',
    '    <PolyStyle><color>4400cc44</color></PolyStyle>',
    '  </Style>',
    '',
  ];

  // Beacons folder
  if (project.beacons.length > 0) {
    lines.push('  <Folder>');
    lines.push('    <name>Beacons</name>');
    project.beacons.forEach(b => {
      lines.push('    <Placemark>');
      lines.push(`      <name>${escapeXml(b.label)}</name>`);
      lines.push(`      <description>Type: ${b.beaconType}${b.notes ? '\n' + escapeXml(b.notes) : ''}\nAccuracy: ±${b.coordinate.accuracy?.toFixed(1) ?? '?'}m\nCaptured: ${new Date(b.capturedAt).toISOString()}</description>`);
      lines.push('      <styleUrl>#beaconStyle</styleUrl>');
      lines.push(`      <Point><coordinates>${b.coordinate.lng},${b.coordinate.lat},${b.coordinate.altitude ?? 0}</coordinates></Point>`);
      lines.push('    </Placemark>');
    });
    lines.push('  </Folder>');
  }

  // Parcels folder
  if (project.parcels.length > 0) {
    lines.push('  <Folder>');
    lines.push('    <name>Parcels</name>');
    project.parcels.forEach(p => {
      if (p.walkPoints.length < 3) return;
      const coordStr = p.walkPoints
        .map(wp => `${wp.coordinate.lng},${wp.coordinate.lat},${wp.coordinate.altitude ?? 0}`)
        .join(' ');
      // Close the ring
      const first = p.walkPoints[0];
      const closed = coordStr + ` ${first.coordinate.lng},${first.coordinate.lat},${first.coordinate.altitude ?? 0}`;

      lines.push('    <Placemark>');
      lines.push(`      <name>${escapeXml(p.label)}</name>`);
      lines.push(`      <description>Area: ${p.computedAreaM2 ? (p.computedAreaM2 / 10000).toFixed(4) + ' ha' : 'N/A'}\nPerimeter: ${p.computedPerimeterM?.toFixed(1) ?? 'N/A'} m\nPoints: ${p.walkPoints.length}</description>`);
      lines.push('      <styleUrl>#parcelStyle</styleUrl>');
      lines.push('      <Polygon>');
      lines.push('        <outerBoundaryIs><LinearRing>');
      lines.push(`          <coordinates>${closed}</coordinates>`);
      lines.push('        </LinearRing></outerBoundaryIs>');
      lines.push('      </Polygon>');
      lines.push('    </Placemark>');
    });
    lines.push('  </Folder>');
  }

  lines.push('</Document>');
  lines.push('</kml>');
  return lines.join('\n');
}

export function exportToCSV(project: FieldProject): string {
  const rows: string[] = ['Label,Latitude,Longitude,Altitude,Accuracy,Type,Notes,CapturedAt'];
  project.beacons.forEach(b => {
    rows.push([
      b.label,
      b.coordinate.lat.toFixed(8),
      b.coordinate.lng.toFixed(8),
      b.coordinate.altitude?.toFixed(3) ?? '',
      b.coordinate.accuracy?.toFixed(2) ?? '',
      b.beaconType,
      `"${(b.notes ?? '').replace(/"/g, '""')}"`,
      new Date(b.capturedAt).toISOString(),
    ].join(','));
  });
  return rows.join('\n');
}

export function downloadBlob(content: string, filename: string, mime: string): void {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/**
 * Field Session Manager — orchestrates the field data collection workflow
 *
 * Ties together: instrumentStore (connection) + fieldBookDB (persistence)
 * + liveToleranceChecker (QC) + syncQueue (sync) + stakeout (navigation)
 *
 * Works offline-first: all measurements saved locally, synced when online.
 */

import { useInstrumentStore } from '@/stores/instrumentStore'
import { checkTolerance, type ToleranceCheckResult } from '@/lib/survey/liveToleranceChecker'

// ─── Types ──────────────────────────────────────────────────────────────────

export type SurveyType = 'cadastral' | 'engineering' | 'topographic' | 'control' | 'leveling'
export type InstrumentType = 'total_station' | 'gnss_rover' | 'gnss_static' | 'level'
export type MeasurementMode = 'traverse' | 'radiation' | 'stakeout' | 'leveling' | 'walk'

export interface StationSetup {
  stationName: string
  instrumentHeight: number
  targetHeight: number
  backsightStation?: string
  backsightBearing?: { deg: number; min: number; sec: number }
  temperature?: number
  pressure?: number
  isControlPoint: boolean
  easting?: number
  northing?: number
  elevation?: number
}

export interface FieldMeasurement {
  id: string
  timestamp: number
  pointId: string
  stationFrom: string
  stationTo?: string
  // GNSS observations (from StreamedPoint)
  latitude?: number
  longitude?: number
  elevation?: number
  fixQuality?: string
  satellites?: number
  hdop?: number
  // Total station observations (from GSI parser — future)
  slopeDistance?: number
  horizontalAngle?: { deg: number; min: number; sec: number }
  verticalAngle?: { deg: number; min: number; sec: number }
  // Reduced coordinates
  easting?: number
  northing?: number
  // Metadata
  instrumentType: InstrumentType
  mode: MeasurementMode
  notes?: string
  synced: boolean
}

export interface FieldSessionState {
  projectId: string
  surveyType: SurveyType
  setup: StationSetup | null
  measurements: FieldMeasurement[]
  stakeoutTarget: { easting: number; northing: number; elevation: number } | null
  toleranceStatus: ToleranceCheckResult | null
  isOnline: boolean
  isSyncing: boolean
  pendingSyncCount: number
  lastSyncAt: number | null
}

// ─── Field Session Class ────────────────────────────────────────────────────

class FieldSession {
  private state: FieldSessionState
  private listeners: Set<(state: FieldSessionState) => void> = new Set()

  constructor(projectId: string, surveyType: SurveyType) {
    this.state = {
      projectId,
      surveyType,
      setup: null,
      measurements: [],
      stakeoutTarget: null,
      toleranceStatus: null,
      isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
      isSyncing: false,
      pendingSyncCount: 0,
      lastSyncAt: null,
    }
  }

  subscribe = (listener: (state: FieldSessionState) => void): (() => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  getSnapshot = (): FieldSessionState => this.state

  private setState(updates: Partial<FieldSessionState>) {
    this.state = { ...this.state, ...updates }
    this.listeners.forEach(l => l(this.state))
  }

  // ─── Station Setup ────────────────────────────────────────────────────────

  setupStation(setup: StationSetup) {
    this.setState({ setup })
  }

  isReady(): boolean {
    return this.state.setup !== null
  }

  // ─── Measurement Capture ──────────────────────────────────────────────────

  /**
   * Capture a measurement from the connected instrument.
   * Reads the latest reading from the instrument store and saves it.
   */
  async captureMeasurement(params: {
    pointId: string
    stationTo?: string
    targetHeight?: number
    notes?: string
  }): Promise<FieldMeasurement | null> {
    if (!this.state.setup) {
      return null
    }

    const instrumentStore = useInstrumentStore.getState()
    const latestPoint = instrumentStore.latestPoint

    if (!latestPoint) {
      return null
    }

    // Determine instrument type from the reading source
    const instrumentType: InstrumentType = latestPoint.source === 'nmea'
      ? 'gnss_rover'
      : latestPoint.source === 'gsi'
        ? 'total_station'
        : 'gnss_rover'

    // Build the measurement from the StreamedPoint
    const measurement: FieldMeasurement = {
      id: `obs-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: Date.now(),
      pointId: params.pointId,
      stationFrom: this.state.setup.stationName,
      stationTo: params.stationTo,
      // GNSS fields (from StreamedPoint)
      latitude: latestPoint.latitude,
      longitude: latestPoint.longitude,
      elevation: latestPoint.elevation ?? undefined,
      fixQuality: latestPoint.quality != null
        ? (latestPoint.quality >= 4 ? 'fixed' : latestPoint.quality >= 2 ? 'float' : 'single')
        : undefined,
      satellites: latestPoint.satellites,
      hdop: latestPoint.hdop,
      // Reduced coordinates (StreamedPoint has easting/northing)
      easting: latestPoint.easting,
      northing: latestPoint.northing,
      // Metadata
      instrumentType,
      mode: this.state.surveyType === 'leveling' ? 'leveling' : 'traverse',
      notes: params.notes,
      synced: false,
    }

    // Save to IndexedDB (offline-first)
    try {
      const { saveObservation } = await import('@/lib/offline/fieldBookDB')
      await saveObservation({
        id: measurement.id,
        projectId: this.state.projectId,
        surveyType: measurement.mode as 'traverse' | 'leveling' | 'topo' | 'gnss' | 'hydro' | 'mining',
        station: measurement.stationFrom,
        backsight: this.state.setup.backsightStation,
        foresight: measurement.stationTo,
        // GNSS fields
        latitude: measurement.latitude,
        longitude: measurement.longitude,
        // Coordinates
        easting: measurement.easting,
        northing: measurement.northing,
        elevation: measurement.elevation,
        // Metadata
        notes: measurement.notes,
        createdAt: new Date(measurement.timestamp).toISOString(),
        syncedAt: null,
      })
    } catch {
      /* ignore offline save error */
    }

    // Add to session state
    const measurements = [...this.state.measurements, measurement]
    this.setState({ measurements, pendingSyncCount: this.state.pendingSyncCount + 1 })

    // Trigger haptic feedback (mobile)
    this.hapticFeedback()

    return measurement
  }

  /**
   * Trigger haptic feedback on measurement capture.
   */
  private hapticFeedback() {
    if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
      navigator.vibrate(50)
    }
  }

  // ─── Stakeout ─────────────────────────────────────────────────────────────

  activateStakeout(target: { easting: number; northing: number; elevation: number }) {
    this.setState({ stakeoutTarget: target })
  }

  deactivateStakeout() {
    this.setState({ stakeoutTarget: null })
  }

  // ─── Sync ─────────────────────────────────────────────────────────────────

  async syncNow(): Promise<{ synced: number; failed: number }> {
    if (this.state.isSyncing) return { synced: 0, failed: 0 }

    this.setState({ isSyncing: true })

    try {
      const { syncObservations } = await import('@/lib/offline/fieldBookDB')
      const result = await syncObservations()

      const syncedCount = result.synced || 0
      const failedCount = result.failed || 0

      // Mark synced measurements
      const measurements = this.state.measurements.map(m => ({
        ...m,
        synced: m.synced || (syncedCount > 0 && !this.state.measurements.find(x => x.id === m.id && !x.synced)),
      }))

      this.setState({
        isSyncing: false,
        measurements,
        pendingSyncCount: Math.max(0, this.state.pendingSyncCount - syncedCount),
        lastSyncAt: Date.now(),
        isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
      })

      return { synced: syncedCount, failed: failedCount }
    } catch {
      this.setState({ isSyncing: false })
      return { synced: 0, failed: this.state.pendingSyncCount }
    }
  }

  /**
   * Load existing measurements from IndexedDB (for session resume).
   */
  async loadMeasurements() {
    try {
      const { getObservations } = await import('@/lib/offline/fieldBookDB')
      const observations = await getObservations(this.state.projectId)
      const measurements: FieldMeasurement[] = observations.map((obs) => ({
        id: obs.id,
        timestamp: new Date(obs.createdAt).getTime(),
        pointId: '',
        stationFrom: obs.station || '',
        stationTo: obs.foresight || undefined,
        latitude: obs.latitude,
        longitude: obs.longitude,
        elevation: obs.elevation ?? undefined,
        easting: obs.easting,
        northing: obs.northing,
        instrumentType: obs.latitude ? 'gnss_rover' : 'total_station',
        mode: (obs.surveyType as MeasurementMode) || 'traverse',
        notes: obs.notes,
        synced: obs.syncedAt != null,
      }))
      this.setState({
        measurements,
        pendingSyncCount: measurements.filter(m => !m.synced).length,
      })
    } catch {
      /* ignore load error */
    }
  }

  /**
   * Clear all measurements.
   */
  clearMeasurements() {
    this.setState({ measurements: [], pendingSyncCount: 0, toleranceStatus: null })
  }
}

// ─── Session Registry ───────────────────────────────────────────────────────

const sessions = new Map<string, FieldSession>()

export function getFieldSession(projectId: string, surveyType: SurveyType = 'cadastral'): FieldSession {
  const key = `${projectId}:${surveyType}`
  let session = sessions.get(key)
  if (!session) {
    session = new FieldSession(projectId, surveyType)
    sessions.set(key, session)
  }
  return session
}

// ─── React Hook ─────────────────────────────────────────────────────────────

export function useFieldSession(options: {
  projectId: string
  surveyType?: SurveyType
}): FieldSession {
  const { projectId, surveyType = 'cadastral' } = options
  return getFieldSession(projectId, surveyType)
}

import JSZip from 'jszip';
import db from '@/lib/db';
import { computeDeedPlanGeometry, loadPreAdjustedFromDB } from './deedPlanGeometry';

export async function generateBoundaryShapefile(
  projectId: string
): Promise<Buffer> {
  const projectRes = await db.query<{ name: string; utm_zone: number | null; hemisphere: string | null }>(
    'SELECT name, utm_zone, hemisphere FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  if (!project) throw new Error('Project not found');

  // Use Bowditch-adjusted coordinates from traverse engine — single source of truth
  const preAdjusted = await loadPreAdjustedFromDB(projectId);
  const geom = await computeDeedPlanGeometry(projectId, {
    preAdjustedCoordinates: preAdjusted?.stations,
    preAdjustedClosure: preAdjusted?.closure,
  });

  const beacons = geom.stations.map((s, i) => ({
    name: s.station,
    e: s.easting,
    n: s.northing,
    beaconNo: s.beaconNo,
  }));

  const zip = new JSZip();

  const geoJson = {
    type: 'FeatureCollection',
    features: [{
      type: 'Feature',
      geometry: {
        type: 'Polygon',
        coordinates: [beacons.map((b) => [b.e, b.n]).concat([[beacons[0].e, beacons[0].n]])]
      },
      properties: {
        project: project.name,
        area_m2: geom.areaM2,
        area_ha: geom.areaHa,
        surveyed_date: new Date().toISOString().split('T')[0],
        rdm_compliant: true
      }
    }]
  };

  zip.file(`${project.name}_Boundary.geojson`, JSON.stringify(geoJson, null, 2));

  const zone = project.utm_zone || 37;
  const hemisphere = project.hemisphere || 'S';
  const prjContent = `PROJCS["Arc 1960 / UTM zone ${zone}${hemisphere}",GEOGCS["Arc 1960",DATUM["Arc_1960",SPHEROID["Clarke_1880_RGS",6378249.145,293.465]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]],PROJECTION["Transverse_Mercator"],PARAMETER["latitude_of_origin",0],PARAMETER["central_meridian",${zone * 6 - 183}],PARAMETER["scale_factor",0.9996],PARAMETER["false_easting",500000],PARAMETER["false_northing",${hemisphere === 'S' ? 10000000 : 0}],UNIT["metre",1]]`;

  zip.file(`${project.name}_Boundary.prj`, prjContent);

  const blob = await zip.generateAsync({ type: 'nodebuffer' });
  return Buffer.from(blob);
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { addPageFooter } from './pdfTitleBlock';
import { shoelaceArea as computePolygonArea } from '@/lib/engine/area';

// ---------------------------------------------------------------------------
// Input interface
// ---------------------------------------------------------------------------

export interface FormC22Input {
  projectName: string;
  lrNumber: string;
  parcelNumber: string;
  county: string;
  division: string;
  district: string;
  locality: string;
  surveyType: string;
  surveyorName: string;
  iskNumber: string;
  firmName: string;
  referenceNumber: string;
  revision: string;
  stations: Array<{
    label: string;
    observedBearing: number; // degrees
    observedDistance: number; // metres
    easting: number;
    northing: number;
    adjustedEasting: number;
    adjustedNorthing: number;
    departureRaw: number;
    latitudeRaw: number;
    departureCorrection: number;
    latitudeCorrection: number;
  }>;
  angularMisclosureSec: number;
  angularToleranceSec: number;
  linearMisclosureM: number;
  perimeterM: number;
  precisionRatio: number;
  areaM2: number;
  areaHa: number;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Convert decimal degrees to DMS string e.g. 45°30'15.2" */
function decimalToDMS(deg: number): string {
  const absolute = Math.abs(deg);
  const d = Math.floor(absolute);
  const minFloat = (absolute - d) * 60;
  const m = Math.floor(minFloat);
  const s = (minFloat - m) * 60;
  return `${d}°${String(m).padStart(2, '0')}'${s.toFixed(1)}"`;
}

/** Convert decimal degrees to WCB (Whole Circle Bearing) quadrant string e.g. N 45°30'15.2" E */
function decimalToWCB(deg: number): string {
  const normalised = ((deg % 360) + 360) % 360;
  if (normalised <= 90) {
    return `N ${decimalToDMS(normalised)} E`;
  } else if (normalised <= 180) {
    return `S ${decimalToDMS(180 - normalised)} E`;
  } else if (normalised <= 270) {
    return `S ${decimalToDMS(normalised - 180)} W`;
  } else {
    return `N ${decimalToDMS(360 - normalised)} W`;
  }
}

// computeShoelaceArea removed — now uses canonical shoelaceArea from @/lib/engine/area
// Call sites map adjustedEasting/adjustedNorthing → easting/northing.

/** Format a precision ratio like "1:12500" */
function formatPrecisionRatio(ratio: number): string {
  if (ratio <= 0 || !isFinite(ratio)) return '—';
  return `1:${Math.round(ratio).toLocaleString()}`;
}

// ---------------------------------------------------------------------------
// Page dimensions — A3 landscape
// ---------------------------------------------------------------------------

const PAGE_W = 420;
const PAGE_H = 297;
const MARGIN = 10;
const CONTENT_W = PAGE_W - MARGIN * 2;

// ---------------------------------------------------------------------------
// Main generator
// ---------------------------------------------------------------------------

export function generateFormC22Pdf(input: FormC22Input): Buffer {
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3',
  });

  const today = new Date().toLocaleDateString('en-KE', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });

  // Track pages for numbering — we add footer at the end for all pages
  let currentPage = 1;
  const totalPages = estimateTotalPages(input.stations.length);

  // =========================================================================
  // PAGE 1 — Header + Info + Tables 1 & 2
  // =========================================================================
  drawPageHeader(doc, input, today);
  drawProjectInfoBlock(doc, input, today);
  drawSurveyorInfoBlock(doc, input);

  let y = 56;

  // --- Table 1: Observed Bearings and Distances ---
  y = drawObservedBearingsTable(doc, input, y);
  y += 4;

  // --- Table 2: Traverse Adjustment ---
  y = drawTraverseAdjustmentTable(doc, input, y);
  y += 4;

  // Check if we need a new page for Table 3 & 4
  if (y > PAGE_H - 100) {
    addPageFooter(doc, currentPage, totalPages, input.projectName);
    doc.addPage();
    currentPage++;
    y = MARGIN;
  }

  // --- Table 3: Area Computation ---
  y = drawAreaComputationTable(doc, input, y);
  y += 4;

  // --- Table 4: Closure Summary ---
  y = drawClosureSummaryTable(doc, input, y);
  y += 6;

  // Check if we need a new page for certificate
  if (y > PAGE_H - 70) {
    addPageFooter(doc, currentPage, totalPages, input.projectName);
    doc.addPage();
    currentPage++;
    y = MARGIN;
  }

  // --- Surveyor's Certificate ---
  drawSurveyorCertificate(doc, input, y, today);

  // --- Professional Disclaimer ---
  drawDisclaimer(doc);

  // Finalize page footers on all pages
  const actualTotal = doc.getNumberOfPages();
  for (let p = 1; p <= actualTotal; p++) {
    doc.setPage(p);
    // Remove any previously drawn footer on this page by overwriting with white
    // Actually, addPageFooter draws a line + text; we just call it for every page
    addPageFooter(doc, p, actualTotal, input.projectName);
  }

  return Buffer.from(doc.output('arraybuffer'));
}

// ---------------------------------------------------------------------------
// Estimate page count
// ---------------------------------------------------------------------------

function estimateTotalPages(stationCount: number): number {
  // Rough heuristic: up to ~15 stations fit on 1 page, more needs 2
  if (stationCount <= 15) return 1;
  if (stationCount <= 30) return 2;
  return 3;
}

// ---------------------------------------------------------------------------
// Draw the Republic of Kenya / DoLS header
// ---------------------------------------------------------------------------

function drawPageHeader(doc: jsPDF, input: FormC22Input, _today: string): void {
  const cx = PAGE_W / 2;

  doc.setDrawColor(0, 0, 0);
  doc.setLineWidth(1.0);
  doc.rect(MARGIN, MARGIN, CONTENT_W, 36);

  // Double border effect
  doc.setLineWidth(0.3);
  doc.rect(MARGIN + 1.5, MARGIN + 1.5, CONTENT_W - 3, 33);

  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('REPUBLIC OF KENYA', cx, MARGIN + 10, { align: 'center' });

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(40, 40, 40);
  doc.text('DEPARTMENT OF LAND SERVICES', cx, MARGIN + 17, { align: 'center' });

  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('FORM NO. C22 — COMPUTATION SHEET', cx, MARGIN + 26, { align: 'center' });

  doc.setFontSize(7);
  doc.setFont('helvetica', 'italic');
  doc.setTextColor(80, 80, 80);
  doc.text(
    'Survey Act Cap 299 — Survey Regulations 1994 — Arc 1960 / UTM Zone 37S (EPSG:21037)',
    cx,
    MARGIN + 33,
    { align: 'center' }
  );
}

