/**
 * Cassini ↔ UTM — Projection Primitives
 *
 * Low-level projection functions (Cassini-Soldner and Transverse Mercator,
 * forward and inverse) plus the meridional-arc / footpoint-latitude helpers.
 *
 * Shared by:
 *   - exact.ts (the public exact-chain functions)
 *   - datum.ts (for deriveMolodenskyParams, which needs cassiniInverse + tmInverse + tmForward)
 *
 * Reference: Snyder, "Map Projections — A Working Manual" (USGS PP 1395)
 */

import type { EllipsoidParams } from './datum'

// ─── Meridional Arc ────────────────────────────────────────────────────────────

export function meridionalArc(phi: number, ell: EllipsoidParams): number {
  const { a, A0, A2, A4, A6 } = ell
  return a * (A0 * phi - A2 * Math.sin(2 * phi) + A4 * Math.sin(4 * phi) - A6 * Math.sin(6 * phi))
}

// ─── Footpoint Latitude ───────────────────────────────────────────────────────

export function footpointLatitude(M: number, ell: EllipsoidParams): number {
  const { a, e2 } = ell
  const oneMinusE2 = 1 - e2

  let phi = M / (a * ell.A0)

  for (let i = 0; i < 50; i++) {
    const sinPhi = Math.sin(phi)
    const sin2Phi = sinPhi * sinPhi
    const M1 = meridionalArc(phi, ell)
    const dM = M - M1
    const denominator = a * oneMinusE2 / Math.pow(1 - e2 * sin2Phi, 1.5)
    const dPhi = dM / denominator
    phi += dPhi
    if (Math.abs(dPhi) < 1e-12) break
  }

  return phi
}

// ─── Inverse Cassini-Soldner ───────────────────────────────────────────────────

export function cassiniInverse(
  E_m: number,
  N_m: number,
  ell: EllipsoidParams,
  lon0: number = 37 * Math.PI / 180,
): { lat: number; lon: number } {
  const { a, e2, ep2 } = ell
  const oneMinusE2 = 1 - e2

  const phi1 = footpointLatitude(N_m, ell)

  const sinPhi1 = Math.sin(phi1)
  const cosPhi1 = Math.cos(phi1)
  const tanPhi1 = sinPhi1 / cosPhi1
  const sin2Phi1 = sinPhi1 * sinPhi1
  const tan2Phi1 = tanPhi1 * tanPhi1

  const C1 = 1 - e2 * sin2Phi1
  const N1 = a / Math.sqrt(C1)
  const R1 = a * oneMinusE2 / Math.pow(C1, 1.5)

  const D = E_m / N1
  const D2 = D * D
  const D3 = D2 * D
  const D4 = D3 * D
  const D5 = D4 * D
  const D6 = D5 * D

  const coef1 = (N1 * tanPhi1) / R1
  const phi = phi1 - coef1 * (
    D2 / 2
    - (5 + 3 * tan2Phi1 + 10 * C1 - 4 * C1 * C1 - 9 * ep2) * D4 / 24
    + (61 + 90 * tan2Phi1 + 298 * C1 + 45 * tan2Phi1 * tan2Phi1
       - 252 * ep2 - 3 * C1 * C1) * D6 / 720
  )

  const lon = lon0 + (
    D
    - (1 + 2 * tan2Phi1 + C1) * D3 / 6
    + (5 - 2 * C1 + 28 * tan2Phi1 - 3 * C1 * C1 + 8 * ep2 + 24 * tan2Phi1 * tan2Phi1) * D5 / 120
  ) / cosPhi1

  return { lat: phi, lon }
}

// ─── Forward Transverse Mercator ───────────────────────────────────────────────

export function tmForward(
  lat: number,
  lon: number,
  ell: EllipsoidParams,
  lon0: number,
  k0: number,
  FE: number,
  FN: number,
): { E: number; N: number } {
  const { a, e2, ep2 } = ell

  const sinLat = Math.sin(lat)
  const cosLat = Math.cos(lat)
  const tanLat = sinLat / cosLat
  const sin2Lat = sinLat * sinLat
  const tan2Lat = tanLat * tanLat

  const dlon = lon - lon0

  const N = a / Math.sqrt(1 - e2 * sin2Lat)
  const T = tan2Lat
  const C = ep2 * cosLat * cosLat
  const A = dlon * cosLat
  const A2 = A * A
  const A3 = A2 * A
  const A4 = A3 * A
  const A5 = A4 * A
  const A6 = A5 * A

  const M = meridionalArc(lat, ell)

  const E = k0 * N * (
    A
    + (1 - T + C) * A3 / 6
    + (5 - 18 * T + T * T + 72 * C - 58 * ep2) * A5 / 120
  ) + FE

  const Nout = k0 * (
    M
    + N * tanLat * (
      A2 / 2
      + (5 - T + 9 * C + 4 * C * C) * A4 / 24
      + (61 - 58 * T + T * T + 600 * C - 330 * ep2) * A6 / 720
    )
  ) + FN

  return { E, N: Nout }
}

// ─── Inverse Transverse Mercator ─────────────────────────────────────────────

export function tmInverse(
  E: number,
  N: number,
  ell: EllipsoidParams,
  lon0: number,
  k0: number,
  FE: number,
  FN: number,
): { lat: number; lon: number } {
  const { a, e2, ep2 } = ell
  const oneMinusE2 = 1 - e2

  const E1 = E - FE
  const N1 = N - FN

  const M1 = N1 / k0
  const mu1 = footpointLatitude(M1, ell)

  const sinMu1 = Math.sin(mu1)
  const cosMu1 = Math.cos(mu1)
  const tanMu1 = sinMu1 / cosMu1
  const sin2Mu1 = sinMu1 * sinMu1
  const tan2Mu1 = tanMu1 * tanMu1

  const C1 = ep2 * cosMu1 * cosMu1
  const R1 = a * oneMinusE2 / Math.pow(1 - e2 * sin2Mu1, 1.5)
  const N1r = a / Math.sqrt(1 - e2 * sin2Mu1)
  const T1 = tan2Mu1

  const D = E1 / (N1r * k0)
  const D2 = D * D
  const D3 = D2 * D
  const D4 = D3 * D
  const D5 = D4 * D
  const D6 = D5 * D

  const lat = mu1 - (N1r * tanMu1 / R1) * (
    D2 / 2
    - (5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * ep2) * D4 / 24
    + (61 + 90 * T1 + 298 * C1 + 45 * T1 * T1
       - 252 * ep2 - 3 * C1 * C1) * D6 / 720
  )

  const cosLat = Math.cos(lat)
  const lon = lon0 + (
    D
    - (1 + 2 * T1 + C1) * D3 / 6
    + (5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * ep2 + 24 * T1 * T1) * D5 / 120
  ) / cosLat

  return { lat, lon }
}

// ─── Forward Cassini-Soldner ────────────────────────────────────────────────

export function cassiniForward(
  lat: number,
  lon: number,
  ell: EllipsoidParams,
  lon0: number = 37 * Math.PI / 180,
): { E_m: number; N_m: number } {
  const { a, e2, ep2 } = ell
  const oneMinusE2 = 1 - e2

  const sinLat = Math.sin(lat)
  const cosLat = Math.cos(lat)
  const tanLat = sinLat / cosLat
  const sin2Lat = sinLat * sinLat
  const tan2Lat = tanLat * tanLat

  const dlon = lon - lon0

  const N1 = a / Math.sqrt(1 - e2 * sin2Lat)
  const T1 = tan2Lat
  const C1 = ep2 * cosLat * cosLat
  const R1 = a * oneMinusE2 / Math.pow(1 - e2 * sin2Lat, 1.5)

  const A = cosLat * dlon
  const A2 = A * A
  const A3 = A2 * A
  const A4 = A3 * A
  const A5 = A4 * A

  const M = meridionalArc(lat, ell)

  const E_m = N1 * (
    A
    - (1 - T1 + C1) * A3 / 6
    + (5 - 18 * T1 + T1 * T1 + 72 * C1 - 58 * ep2) * A5 / 120
  )

  const N_m = M + N1 * tanLat * (A2 / 2 + (5 - T1 + 9 * C1 + 4 * C1 * C1) * A4 / 24)

  return { E_m, N_m }
}

/**
 * National Topo Sheet Data — Derived from National Survey XLS corner coordinates
 * ═════════════════════════════════════════════════════════════════════════════════
 *
 * Loads the 264-sheet corner coordinate data from national_sheet_corners.json,
 * converts each sheet's 4 corners into CommonPoint[] format, computes Helmert
 * 4-params via computeHelmert4Params(), and estimates accuracy.
 *
 * Sheets with null Cassini coordinates (UTM-only) are skipped.
 * Sheets with all-zero or identical corners are skipped.
 *
 * Source: Survey of Kenya "UTM_Cassini_Cassini_UTM national.xls"
 * Extracted: 2026-06-02
 */

// ponytail: moved to data/cassini/ to keep src/ lean (was 388k LOC of JSON in src/lib/geo/)
import nationalSheetCornersData from '../../../data/cassini/national_sheet_corners.json'
import type { TopoSheetParams, CommonPoint } from './cassini'
import { computeHelmert4Params, estimateSheetAccuracy, computeABCoefficients } from './cassini'
import { logger } from '@/lib/logger'

// ─── Type Definitions for the JSON structure ──────────────────────────────

interface SheetCorner {
  id: string
  utmE: number
  utmN: number
  cassE: number | null
  cassN: number | null
}

interface SheetData {
  corners: SheetCorner[]
}

/** Guard: every sheet corner must carry its Cassini coordinates. */
function cassOf(c: SheetCorner): { cassE: number; cassN: number } {
  if (c.cassE === null || c.cassN === null) {
    throw new Error(`Sheet corner ${c.id} missing Cassini coordinates`)
  }
  return { cassE: c.cassE, cassN: c.cassN }
}

interface NationalSheetCornersJSON {
  metadata: {
    source: string
    description: string
    sheet_count: number
    subsheet_count: number
    utm_to_cassini_sheet_count: number
    empty_placeholder_sheets: string[]
    extracted_date: string
    corner_order: string
    units: {
      cassE: string
      cassN: string
      utmE: string
      utmN: string
    }
    notes: string[]
  }
  sheets: Record<string, SheetData>
}

// ─── Helper Functions ────────────────────────────────────────────────────

/**
 * Check if a sheet has valid Cassini coordinates on all 4 corners.
 * Sheets with any null, zero, or suspicious cassE/cassN are rejected.
 */
function hasValidCassiniCoords(sheet: SheetData): boolean {
  if (!sheet.corners || sheet.corners.length !== 4) return false
  return sheet.corners.every(
    (c) =>
      c.cassE !== null &&
      c.cassN !== null &&
      isFinite(c.cassE) &&
      isFinite(c.cassN) &&
      !(c.cassE === 0 && c.cassN === 0),
  )
}

/**
 * Check if corners contain duplicates (all 4 corners identical or nearly so).
 * This catches placeholder/empty sheets in the XLS.
 */
function hasDuplicateCorners(sheet: SheetData): boolean {
  const corners = sheet.corners
  if (corners.length < 4) return true

  // Compare first corner with the rest — if all are within 1 unit, it's a duplicate
  const ref = corners[0]
  const rc = cassOf(ref)
  return corners.every((c) => {
    const cc = cassOf(c)
    return (
      Math.abs(c.utmE - ref.utmE) < 1 &&
      Math.abs(c.utmN - ref.utmN) < 1 &&
      Math.abs(cc.cassE - rc.cassE) < 1 &&
      Math.abs(cc.cassN - rc.cassN) < 1
    )
  })
}

/**
 * Convert sheet corners to CommonPoint[] format for the Helmert solver.
 *
 * The JSON stores corners as NW, NE, SE, SW (clockwise from top-left).
 * We label them C1-C4 in that order.
 */
function cornersToCommonPoints(sheet: SheetData): CommonPoint[] {
  const labels = ['C1', 'C2', 'C3', 'C4']
  return sheet.corners.map((c, i) => {
    const { cassN, cassE } = cassOf(c)
    return {
      station: labels[i],
      cassN,
      cassE,
      utmN: c.utmN,
      utmE: c.utmE,
    }
  })
}

/**
 * Normalize a sheet ID: the XLS uses "/" (e.g., "102/1") which is our canonical format.
 * No normalization needed currently, but this is a hook for future changes.
 */
function normalizeSheetId(id: string): string {
  return id
}

// ─── Build the NATIONAL_SHEETS array ──────────────────────────────────────

const raw = nationalSheetCornersData as unknown as NationalSheetCornersJSON
const emptyPlaceholders = new Set(raw.metadata.empty_placeholder_sheets)

const _NATIONAL_SHEETS: TopoSheetParams[] = []

const sheetEntries = Object.entries(raw.sheets)

for (const [sheetId, sheetData] of sheetEntries) {
  // Skip known empty placeholders
  if (emptyPlaceholders.has(sheetId)) continue

  // Skip UTM-only sheets (no Cassini coordinates)
  if (!hasValidCassiniCoords(sheetData)) continue

  // Skip sheets with degenerate corners
  if (hasDuplicateCorners(sheetData)) continue

  const commonPoints = cornersToCommonPoints(sheetData)
  const id = normalizeSheetId(sheetId)

  try {
    // Compute Helmert 4 params from the 4 corner common points
    const helmert = computeHelmert4Params(commonPoints)

    const params: TopoSheetParams = {
      id,
      name: `Sheet ${id}`,
      description: `Kenya national topo sheet ${id}. Helmert 4-param from 4 sheet corners (National XLS).`,
      P: helmert.P,
      Q: helmert.Q,
      Cx: helmert.Cx,
      Cy: helmert.Cy,
      commonPoints,
    }

    // Compute A/B polynomial coefficients from corner residuals
    const ab = computeABCoefficients(params)
    if (ab !== null) {
      params.A = ab.A
      params.B = ab.B
    }

    _NATIONAL_SHEETS.push(params)
  } catch (err) {
    // Singular matrix or other computation error — skip this sheet
    // This can happen for sheets with collinear control points
    logger.warn(
      `[national_sheets] Skipping sheet ${id}: ${err instanceof Error ? err.message : String(err)}`,
    )
  }
}

/**
 * All national topographic sheet parameters derived from the National XLS corner data.
 * Sorted by sheet ID for easy lookup.
 */
export const NATIONAL_SHEETS: TopoSheetParams[] = _NATIONAL_SHEETS.sort((a, b) =>
  a.id.localeCompare(b.id, undefined, { numeric: true }),
)

/**
 * Map of sheet ID → params for O(1) lookup.
 */
const NATIONAL_SHEETS_MAP = new Map<string, TopoSheetParams>(
  NATIONAL_SHEETS.map((s) => [s.id, s]),
)

/**
 * Look up a national sheet by its ID (e.g., "102/1").
 * Returns undefined if the sheet is not found or was skipped (UTM-only).
 */
export function getNationalSheet(id: string): TopoSheetParams | undefined {
  return NATIONAL_SHEETS_MAP.get(normalizeSheetId(id))
}

/**
 * Get the total count of sheets in the national dataset (including skipped ones).
 */
export function getNationalSheetCount(): number {
  return Object.keys(raw.sheets).length
}

/**
 * Get statistics about the national sheet processing.
 */
export function getNationalSheetStats(): {
  totalInXLS: number
  emptyPlaceholders: number
  utmOnlySkipped: number
  degenerateSkipped: number
  computeErrors: number
  successfullyProcessed: number
} {
  const totalInXLS = Object.keys(raw.sheets).length
  const emptyCount = emptyPlaceholders.size
  let utmOnlyCount = 0
  let degenerateCount = 0
  let errorCount = 0

  for (const [sheetId, sheetData] of sheetEntries) {
    if (emptyPlaceholders.has(sheetId)) continue
    if (!hasValidCassiniCoords(sheetData)) {
      utmOnlyCount++
      continue
    }
    if (hasDuplicateCorners(sheetData)) {
      degenerateCount++
      continue
    }
    try {
      computeHelmert4Params(cornersToCommonPoints(sheetData))
    } catch {
      errorCount++
    }
  }

  return {
    totalInXLS,
    emptyPlaceholders: emptyCount,
    utmOnlySkipped: utmOnlyCount,
    degenerateSkipped: degenerateCount,
    computeErrors: errorCount,
    successfullyProcessed: NATIONAL_SHEETS.length,
  }
}

/**
 * Calculation standard: N.N. Basak — Surveying and Levelling
 * Source: N.N. Basak, Surveying and Levelling, Chapter 3
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 7 (UTM)
 * Source: EPSG Guidance Note 7-2 — Standard Redfearn formula for UTM
 * Source: USACE EM 1110-1-1005 §5-2
 * - No intermediate rounding
 * - Full floating point precision throughout
 * - Round only at final display layer
 * - Bearings: WCB 0-360° clockwise from North
 */

// METARDU Engine - Coordinate conversions

import { LatLon, UTMCoord, DMS } from '@/lib/engine/types';
import { decimalToDMS } from '@/lib/engine/angles';
import { getUTMZoneFromLatLng } from './utmZones';

// WGS84 ellipsoid
const WGS84_A = 6378137.0;
const WGS84_F = 1 / 298.257223563;
const WGS84_E2 = 2 * WGS84_F - WGS84_F * WGS84_F;
const WGS84_EP2 = WGS84_E2 / (1 - WGS84_E2); // e'^2

function normalizeLongitudeDeg(lon: number) {
  let x = lon
  while (x < -180) x += 360
  while (x >= 180) x -= 360
  return x
}

export function geographicToUTM(lat: number, lon: number, zone?: number): UTMCoord {
  const normalizedLon = normalizeLongitudeDeg(lon)

  const latRad = (lat * Math.PI) / 180;
  const lonRad = (normalizedLon * Math.PI) / 180;

  const computedZone = zone ?? getUTMZoneFromLatLng(lat, normalizedLon).zone
  const lonOrigin = (computedZone - 1) * 6 - 180 + 3;
  const lonOriginRad = (lonOrigin * Math.PI) / 180;

  const k0 = 0.9996;

  const sinLat = Math.sin(latRad)
  const cosLat = Math.cos(latRad)
  const tanLat = Math.tan(latRad)

  const N = WGS84_A / Math.sqrt(1 - WGS84_E2 * sinLat * sinLat);
  const T = tanLat * tanLat;
  const C = WGS84_EP2 * cosLat * cosLat;
  const A = cosLat * (lonRad - lonOriginRad);

  const e4 = WGS84_E2 * WGS84_E2
  const e6 = e4 * WGS84_E2

  // Source: EPSG Guidance Note 7-2 — Redfearn formula, M series expansion
  // Source: Ghilani & Wolf, Chapter 7 — Meridian distance M
  const M = WGS84_A * (
    (1 - WGS84_E2 / 4 - (3 * e4) / 64 - (5 * e6) / 256) * latRad
    - ((3 * WGS84_E2) / 8 + (3 * e4) / 32 + (45 * e6) / 1024) * Math.sin(2 * latRad)
    + ((15 * e4) / 256 + (45 * e6) / 1024) * Math.sin(4 * latRad)
    - ((35 * e6) / 3072) * Math.sin(6 * latRad)
  )

  // Source: EPSG Guidance Note 7-2 — Easting coordinate E = k₀N(A + ...)
  const easting = k0 * N * (
    A
    + ((1 - T + C) * Math.pow(A, 3)) / 6
    + ((5 - 18 * T + T * T + 72 * C - 58 * WGS84_EP2) * Math.pow(A, 5)) / 120
  ) + 500000

  // Source: EPSG Guidance Note 7-2 — Northing coordinate N = k₀(M + N·tan·φ·(...))
  let northing = k0 * (M + N * tanLat * (
    (A * A) / 2
    + ((5 - T + 9 * C + 4 * C * C) * Math.pow(A, 4)) / 24
    + ((61 - 58 * T + T * T + 600 * C - 330 * WGS84_EP2) * Math.pow(A, 6)) / 720
  ))

  const hemisphere: 'N' | 'S' = lat >= 0 ? 'N' : 'S';
  if (hemisphere === 'S') northing += 10000000;

  return { easting, northing, zone: computedZone, hemisphere };
}

function utmToGeographicApprox(easting: number, northing: number, zone: number, hemisphere: 'N' | 'S'): LatLon {
  const k0 = 0.9996;
  const e1 = (1 - Math.sqrt(1 - WGS84_E2)) / (1 + Math.sqrt(1 - WGS84_E2));

  let y = northing;
  if (hemisphere === 'S') y -= 10000000;

  const x = easting - 500000;

  const lonOrigin = (zone - 1) * 6 - 180 + 3;
  const lonOriginRad = (lonOrigin * Math.PI) / 180;

  const e4 = WGS84_E2 * WGS84_E2
  const e6 = e4 * WGS84_E2

  const M = y / k0;
  const mu = M / (WGS84_A * (1 - WGS84_E2 / 4 - (3 * e4) / 64 - (5 * e6) / 256));

  const phi1 =
    mu +
    (3 * e1 / 2 - 27 * Math.pow(e1, 3) / 32) * Math.sin(2 * mu) +
    (21 * e1 * e1 / 16 - 55 * Math.pow(e1, 4) / 32) * Math.sin(4 * mu) +
    (151 * Math.pow(e1, 3) / 96) * Math.sin(6 * mu) +
    (1097 * Math.pow(e1, 4) / 512) * Math.sin(8 * mu);

  const sin1 = Math.sin(phi1)
  const cos1 = Math.cos(phi1)
  const tan1 = Math.tan(phi1)

  const N1 = WGS84_A / Math.sqrt(1 - WGS84_E2 * sin1 * sin1);
  const T1 = tan1 * tan1;
  const C1 = WGS84_EP2 * cos1 * cos1;
  const R1 = (WGS84_A * (1 - WGS84_E2)) / Math.pow(1 - WGS84_E2 * sin1 * sin1, 1.5);
  const D = x / (N1 * k0);

  const lat =
    phi1 -
    (N1 * tan1 / R1) *
      (D * D / 2 -
        (5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * WGS84_EP2) * Math.pow(D, 4) / 24 +
        (61 + 90 * T1 + 298 * C1 + 45 * T1 * T1 - 252 * WGS84_EP2 - 3 * C1 * C1) * Math.pow(D, 6) / 720);

  const lon =
    lonOriginRad +
    (D -
      (1 + 2 * T1 + C1) * Math.pow(D, 3) / 6 +
      (5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * WGS84_EP2 + 24 * T1 * T1) * Math.pow(D, 5) / 120) /
      cos1;

  return { lat: (lat * 180) / Math.PI, lon: (lon * 180) / Math.PI };
}

export function utmToGeographic(easting: number, northing: number, zone: number, hemisphere: 'N' | 'S'): LatLon {
  const initial = utmToGeographicApprox(easting, northing, zone, hemisphere)

  // Refine with Newton iterations to improve round-trip (UTM -> lat/lon -> UTM) accuracy.
  // This targets the Basak requirement: round-trip < 1 mm across the valid UTM latitude band.
  let lat = initial.lat
  let lon = initial.lon

  const maxIterations = 8
  const targetMeters = 0.0005 // 0.5 mm

  for (let iteration = 0; iteration < maxIterations; iteration++) {
    const predicted = geographicToUTM(lat, lon, zone)
    const dE = easting - predicted.easting
    const dN = northing - predicted.northing

    if (Math.hypot(dE, dN) <= targetMeters) break

    // Numerical Jacobian (meters per degree)
    const deltaDeg = 1e-8

    const predictedLatPlus = geographicToUTM(lat + deltaDeg, lon, zone)
    const predictedLatMinus = geographicToUTM(lat - deltaDeg, lon, zone)

    const predictedLonPlus = geographicToUTM(lat, lon + deltaDeg, zone)
    const predictedLonMinus = geographicToUTM(lat, lon - deltaDeg, zone)

    const dEdLat = (predictedLatPlus.easting - predictedLatMinus.easting) / (2 * deltaDeg)
    const dNdLat = (predictedLatPlus.northing - predictedLatMinus.northing) / (2 * deltaDeg)

    const dEdLon = (predictedLonPlus.easting - predictedLonMinus.easting) / (2 * deltaDeg)
    const dNdLon = (predictedLonPlus.northing - predictedLonMinus.northing) / (2 * deltaDeg)

    const det = dEdLat * dNdLon - dEdLon * dNdLat

    if (!Number.isFinite(det) || Math.abs(det) < 1e-12) {
      // Fallback: if Jacobian is singular (should be rare), return the approximation.
      return initial
    }

    // Solve J * [dLat, dLon] = [dE, dN]
    const dLat = (dE * dNdLon - dEdLon * dN) / det
    const dLon = (dEdLat * dN - dE * dNdLat) / det

    lat += dLat
    lon += dLon

    if (hemisphere === 'S' && lat > 0) lat = -Math.abs(lat)
    if (hemisphere === 'N' && lat < 0) lat = Math.abs(lat)

    lon = normalizeLongitudeDeg(lon)
  }

  return { lat, lon }
}

/** Convert a whole-circle bearing (degrees) + distance to coordinate deltas. */
export function bearingDistanceToDelta(bearingDeg: number, distance: number): { deltaE: number; deltaN: number } {
  const rad = (bearingDeg * Math.PI) / 180;
  return {
    deltaE: distance * Math.sin(rad),
    deltaN: distance * Math.cos(rad),
  };
}

export function latLonToString(lat: number, lon: number): string {
  const latDMS = decimalToDMS(lat, true);
  const lonDMS = decimalToDMS(lon, false);
  return `${latDMS.degrees}° ${latDMS.minutes}' ${latDMS.seconds.toFixed(3)}" ${latDMS.direction}, ${lonDMS.degrees}° ${lonDMS.minutes}' ${lonDMS.seconds.toFixed(3)}" ${lonDMS.direction}`;
}

/**
 * @module geodesicArea
 *
 * Geodesic Area & Distance Computation using ol/sphere
 *
 * Computes TRUE ellipsoidal surface area accounting for Earth's curvature.
 * This is critical for cadastral compliance — planar (Shoelace) area
 * calculations in Web Mercator (EPSG:3857) produce massive errors
 * that fail registry audits.
 *
 * Uses OpenLayers' ol/sphere module which implements:
 * - Karney's algorithm for geodesic polygon area (2013)
 * - Vincenty's formula for geodesic distance (1975)
 *
 * Reference: "Geodesics on an ellipsoid" by Charles Karney (2013)
 *            Survey Act Cap 299 — area must be in hectares to 4 decimal places
 */

import { getArea, getLength } from 'ol/sphere'
import type { Geometry, Polygon, LineString } from 'ol/geom'
import type { ProjectionLike } from 'ol/proj'

export interface GeodesicMetrics {
  /** True surface area in square meters */
  areaSqM: number
  /** Area in hectares (4 decimal places) */
  areaHectares: number
  /** Area in acres (for reference) */
  areaAcres: number
  /** True geodesic perimeter in meters */
  perimeterM: number
  /** Number of vertices */
  vertexCount: number
  /** Whether the computation used geodesic (true) or planar (false) method */
  isGeodesic: boolean
  /** Estimated error in m² (based on coordinate precision) */
  estimatedErrorSqM: number
}

/**
 * Compute geodesic area and perimeter of a polygon.
 *
 * This uses ol/sphere.getArea() which computes the true ellipsoidal
 * surface area, correcting for projection distortion.
 *
 * @param geometry - OpenLayers Polygon geometry
 * @param projection - Map projection (default: EPSG:3857 Web Mercator)
 * @returns Geodesic metrics with area in m², ha, and acres
 */
export function calculateGeodesicArea(
  geometry: Polygon,
  projection: ProjectionLike = 'EPSG:3857',
): GeodesicMetrics {
  // ol/sphere.getArea automatically handles projection transformation
  const areaSqM = getArea(geometry, { projection })

  // Geodesic perimeter
  const perimeterM = getLength(geometry, { projection })

  // Vertex count
  const coords = geometry.getCoordinates()
  const ring = coords[0] || []
  const vertexCount = ring.length > 0 ? ring.length - 1 : 0 // exclude closing point

  // Error estimate: for geodesic computation, error is minimal
  // Based on coordinate precision (typically 1mm = 0.001m)
  const estimatedErrorSqM = (0.001 * perimeterM) / 2

  return {
    areaSqM,
    areaHectares: parseFloat((areaSqM / 10000).toFixed(4)),
    areaAcres: parseFloat((areaSqM / 4046.86).toFixed(4)),
    perimeterM,
    vertexCount,
    isGeodesic: true,
    estimatedErrorSqM,
  }
}

/**
 * Compute geodesic length of a LineString.
 *
 * @param geometry - OpenLayers LineString geometry
 * @param projection - Map projection
 */
export function calculateGeodesicLength(
  geometry: LineString,
  projection: ProjectionLike = 'EPSG:3857',
): { lengthM: number; vertexCount: number } {
  const lengthM = getLength(geometry, { projection })
  const coords = geometry.getCoordinates()
  return {
    lengthM,
    vertexCount: coords.length,
  }
}

/**
 * Compare planar (Shoelace) vs geodesic area to show the distortion error.
 *
 * This is useful for QA/QC — if the difference is > 0.001 ha,
 * the planar calculation would fail registry audit.
 *
 * @param geometry - OpenLayers Polygon geometry
 * @param projection - Map projection
 */
export function compareAreaMethods(
  geometry: Polygon,
  projection: ProjectionLike = 'EPSG:3857',
): {
  geodesic: GeodesicMetrics
  planar: { areaSqM: number; areaHectares: number }
  differenceSqM: number
  differenceHa: number
  distortionPercent: number
  registryCompliant: boolean
} {
  const geodesic = calculateGeodesicArea(geometry, projection)

  // Planar area (Shoelace in projected coordinates)
  const planarAreaSqM = geometry.getArea()

  const differenceSqM = Math.abs(geodesic.areaSqM - planarAreaSqM)
  const differenceHa = differenceSqM / 10000
  const distortionPercent = geodesic.areaSqM > 0
    ? (differenceSqM / geodesic.areaSqM) * 100
    : 0

  return {
    geodesic,
    planar: {
      areaSqM: planarAreaSqM,
      areaHectares: parseFloat((planarAreaSqM / 10000).toFixed(4)),
    },
    differenceSqM,
    differenceHa: parseFloat(differenceHa.toFixed(6)),
    distortionPercent: parseFloat(distortionPercent.toFixed(4)),
    registryCompliant: differenceHa <= 0.001, // tolerance: 10 m²
  }
}

/**
 * Format area for Kenya statutory documents.
 *
 * Per Survey Act Cap 299:
 * - Areas < 1 ha: show in m² with 2 decimal places
 * - Areas ≥ 1 ha: show in hectares with 4 decimal places
 * - Always show both for reference
 */
export function formatAreaForStatutory(areaSqM: number): {
  primary: string
  secondary: string
  full: string
} {
  const ha = areaSqM / 10000

  if (ha < 1) {
    return {
      primary: `${areaSqM.toFixed(2)} m²`,
      secondary: `${ha.toFixed(4)} ha`,
      full: `${areaSqM.toFixed(2)} m² (${ha.toFixed(4)} ha)`,
    }
  }

  return {
    primary: `${ha.toFixed(4)} ha`,
    secondary: `${areaSqM.toFixed(2)} m²`,
    full: `${ha.toFixed(4)} ha (${areaSqM.toFixed(2)} m²)`,
  }
}

/**
 * Combined Scale Factor (CSF) Engine — v0.3
 *
 * Solves the grid-vs-ground area discrepancy that is a legal timebomb in Kenya.
 * Nairobi is at ~1,600m elevation. UTM Zone 37S central meridian is at 39°E.
 * A 100ha parcel can have a 0.3-0.5ha discrepancy between grid area and
 * physical ground area. The deed plan must state the correct area.
 *
 * CSF = k × Fh
 *   k  = Grid Scale Factor (UTM projection distortion at the given longitude)
 *   Fh = Elevation Factor (height above ellipsoid / Earth radius)
 *
 * Ground Area = Grid Area / CSF²
 *
 * Sources:
 * - UTM grid scale factor: k = 0.9996 / cosh(asinh(tan(φ)) - atanh(e·sin(φ))·e) ... simplified
 *   For practical purposes, k ≈ 0.9996 + (x_offset / R)² / 2 where x_offset is
 *   distance from central meridian in metres.
 * - Elevation factor: Fh = R / (R + h) where R = 6,371,000m, h = ellipsoidal height
 *
 * For Kenya UTM zones:
 *   Zone 36S: central meridian = 33°E
 *   Zone 37S: central meridian = 39°E
 */

import { shoelaceArea } from '@/lib/engine/area'

// ─── Constants ──────────────────────────────────────────────────────────────

const EARTH_RADIUS_M = 6_371_000 // Mean Earth radius (spherical approximation)
const UTM_SCALE_AT_CENTRAL_MERIDIAN = 0.9996 // Standard UTM scale factor

// ─── Types ──────────────────────────────────────────────────────────────────

export interface ScaleFactorInput {
  /** Latitude in decimal degrees */
  latitude: number
  /** Longitude in decimal degrees */
  longitude: number
  /** UTM zone (36 or 37 for Kenya) */
  utmZone: number
  /** Ellipsoidal height in metres (from GNSS, NOT orthometric) */
  ellipsoidalHeight: number
}

export interface ScaleFactorResult {
  /** Grid scale factor (UTM projection distortion) */
  gridScaleFactor: number
  /** Elevation factor (height above ellipsoid) */
  elevationFactor: number
  /** Combined scale factor = grid × elevation */
  combinedScaleFactor: number
  /** Distance from central meridian in metres */
  distanceFromCentralMeridian: number
  /** Central meridian longitude in degrees */
  centralMeridian: number
  /** Scale factor as a ratio (e.g., 1:1.0004) */
  scaleRatio: string
  /** Percentage distortion */
  percentDistortion: number
}

export interface AreaConversionResult {
  /** Area computed from grid coordinates (shoelace formula) */
  gridAreaSqM: number
  /** Area converted to ground (physical surface) */
  groundAreaSqM: number
  /** Area in hectares (ground) */
  groundAreaHa: number
  /** Area in acres (ground) */
  groundAreaAcres: number
  /** The CSF used for conversion */
  csf: number
  /** Difference in m² */
  differenceSqM: number
  /** Difference in hectares */
  differenceHa: number
  /** Percentage difference */
  percentDifference: number
}

// ─── Scale factor computation ───────────────────────────────────────────────

/**
 * Compute the Combined Scale Factor for a point at a given location and elevation.
 *
 * @param input Location + elevation
 * @returns Scale factor breakdown
 */
export function computeCombinedScaleFactor(input: ScaleFactorInput): ScaleFactorResult {
  const { latitude, longitude, utmZone, ellipsoidalHeight } = input

  // AUDIT FIX (M5, 2026-07-02): Replaced spherical approximation with
  // the rigorous ellipsoidal point scale factor formula. The old code
  // used EARTH_RADIUS_M = 6,371,000 (mean sphere) and
  // mPerDegLon = 111,320 × cos(φ) — both spherical approximations that
  // introduce ~0.1-0.3 ppm error at Nairobi distances. The rigorous
  // formula uses the ellipsoidal meridional and prime-vertical radii.

  // WGS84 / Arc 1960 ellipsoid parameters (Clarke 1880 for Arc 1960
  // is very close to WGS84 for scale factor purposes — the difference
  // is sub-ppm at Kenya latitudes)
  const a = 6_378_137.0           // Semi-major axis (metres)
  const f = 1 / 298.257223563     // Inverse flattening (WGS84)
  const e2 = 2 * f - f * f        // First eccentricity squared
  const ePrime2 = e2 / (1 - e2)   // Second eccentricity squared

  const latRad = (latitude * Math.PI) / 180
  const sinLat = Math.sin(latRad)
  const cosLat = Math.cos(latRad)
  const sinLat2 = sinLat * sinLat
  const cosLat2 = cosLat * cosLat

  // Radii of curvature (ellipsoidal)
  // ρ = a(1-e²) / (1-e²sin²φ)^(3/2)  — meridional radius
  // ν = a / √(1-e²sin²φ)              — prime vertical radius
  // Rm = √(ρ·ν)                        — geometric mean radius
  const oneMinusE2Sin2 = 1 - e2 * sinLat2
  const rho = (a * (1 - e2)) / Math.pow(oneMinusE2Sin2, 1.5)
  const nu = a / Math.sqrt(oneMinusE2Sin2)
  const Rm = Math.sqrt(rho * nu)

  // Central meridian for this UTM zone
  const centralMeridian = utmZone * 6 - 183 // Zone 36 → 33°, Zone 37 → 39°

  // Distance from central meridian in metres — use the ellipsoidal
  // prime-vertical radius (not the spherical 111,320 m/°):
  // dE = (λ - λ₀) × ν × cos(φ)   (in radians)
  const lonDiffRad = ((longitude - centralMeridian) * Math.PI) / 180
  const distanceFromCM = Math.abs(lonDiffRad * nu * cosLat)

  // Grid scale factor (UTM projection) — rigorous 2nd-order formula:
  // k = k₀ × (1 + E'²/(2Rm²) × (1 + e'²cos²φ) + E'⁴/(24Rm⁴))
  // where E' is the distance from the central meridian
  const Eprime2 = distanceFromCM * distanceFromCM
  const Eprime4 = Eprime2 * Eprime2
  const Rm2 = Rm * Rm
  const Rm4 = Rm2 * Rm2

  const gridScaleFactor = UTM_SCALE_AT_CENTRAL_MERIDIAN * (
    1 +
    (Eprime2 / (2 * Rm2)) * (1 + ePrime2 * cosLat2) +
    (Eprime4 / (24 * Rm4))
  )

  // Elevation factor — use the ellipsoidal prime-vertical radius (not
  // the mean Earth radius). At 1800m elevation (Nairobi), this gives
  // Fh = ν / (ν + h) ≈ 0.99972 (vs 0.99972 for spherical — the
  // difference is sub-ppm at this elevation, but it's the correct formula).
  const elevationFactor = nu / (nu + ellipsoidalHeight)

  // Combined scale factor
  const combinedScaleFactor = gridScaleFactor * elevationFactor

  // Scale ratio (e.g., 1:1.0004 → "1 : 1.0004")
  const scaleRatio = `1 : ${combinedScaleFactor.toFixed(6)}`

  // Percentage distortion
  const percentDistortion = ((combinedScaleFactor - 1) * 100)

  return {
    gridScaleFactor,
    elevationFactor,
    combinedScaleFactor,
    distanceFromCentralMeridian: distanceFromCM,
    centralMeridian,
    scaleRatio,
    percentDistortion,
  }
}

// ─── Area conversion ────────────────────────────────────────────────────────

/**
 * Convert grid area (from UTM coordinates) to ground area (physical surface).
 *
 * Ground Area = Grid Area / CSF²
 *
 * This is the critical calculation for deed plan accuracy. The grid area
 * from the shoelace formula on UTM coordinates is NOT the physical area
 * on the ground. At Nairobi (1,600m, Zone 37S), the difference can be
 * 0.3-0.5 hectares on a 100ha parcel.
 *
 * @param gridAreaSqM Area from coordinate shoelace formula (m²)
 * @param csf Combined scale factor
 * @returns Ground area + difference
 */
export function convertGridAreaToGround(
  gridAreaSqM: number,
  csf: number,
): AreaConversionResult {
  const groundAreaSqM = gridAreaSqM / (csf * csf)
  const groundAreaHa = groundAreaSqM / 10_000
  const groundAreaAcres = groundAreaSqM / 4_046.86

  const differenceSqM = groundAreaSqM - gridAreaSqM
  const differenceHa = differenceSqM / 10_000
  const percentDifference = gridAreaSqM > 0 ? ((differenceSqM / gridAreaSqM) * 100) : 0

  return {
    gridAreaSqM,
    groundAreaSqM,
    groundAreaHa,
    groundAreaAcres,
    csf,
    differenceSqM,
    differenceHa,
    percentDifference,
  }
}

// ─── Convenience: compute area with scale factor ────────────────────────────

/**
 * Compute the shoelace area of a polygon, then apply the combined scale factor
 * to get the true ground area.
 *
 * @param coords Array of [easting, northing] UTM coordinates
 * @param csf Combined scale factor
 * @returns Both grid and ground area
 */
export function computeAreaWithScaleFactor(
  coords: [number, number][],
  csf: number,
): AreaConversionResult {
  const gridAreaSqM = shoelaceArea(coords.map(([e, n]) => ({ easting: e, northing: n })))
  return convertGridAreaToGround(gridAreaSqM, csf)
}

// computeShoelaceArea removed — now uses canonical shoelaceArea from @/lib/engine/area

// ─── Kenya-specific presets ─────────────────────────────────────────────────

export const KENYA_LOCATIONS = [
