/**
 * Tests for the Cross-Hub Entity Graph.
 *
 * Coverage:
 *   - Basic add/get/setPayload
 *   - Dependency registration and validation
 *   - Dirty propagation (markDirty cascades to dependents)
 *   - Lazy recomputation (get triggers recompute only if dirty)
 *   - Cycle detection (addNode refuses cycles)
 *   - Topological sort for batch recompute
 *   - Error handling (compute throwing, missing dependencies)
 *   - Serialization
 *   - Realistic survey scenario (control point → traverse → parcel)
 */

import {
  EntityGraph,
  createEntityGraph,
  CycleError,
  NodeNotFoundError,
  DependencyNotFoundError,
} from '../entityGraph'

describe('EntityGraph', () => {
  // ─── Basic node operations ───────────────────────────────────────────

  describe('basic operations', () => {
    it('adds a source node and retrieves its payload via setPayload', async () => {
      const g = createEntityGraph()
      g.addNode({
        id: 'control-point/CP1',
        type: 'control_point',
      })
      g.setPayload('control-point/CP1', { easting: 250000, northing: 9945000 })

      const payload = await g.get<{ easting: number; northing: number }>('control-point/CP1')
      expect(payload.easting).toBe(250000)
      expect(payload.northing).toBe(9945000)
    })

    it('throws NodeNotFoundError when getting an unknown node', async () => {
      const g = createEntityGraph()
      await expect(g.get('nope')).rejects.toThrow(NodeNotFoundError)
    })

    it('throws NodeNotFoundError when setting payload on unknown node', () => {
      const g = createEntityGraph()
      expect(() => g.setPayload('nope', {})).toThrow(NodeNotFoundError)
    })

    it('throws NodeNotFoundError when marking unknown node dirty', () => {
      const g = createEntityGraph()
      expect(() => g.markDirty('nope')).toThrow(NodeNotFoundError)
    })
  })

  // ─── Compute functions ───────────────────────────────────────────────

  describe('compute functions', () => {
    it('computes a node from its dependencies', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { easting: 100, northing: 200 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => {
          const cp = deps['cp/1'] as { easting: number; northing: number }
          return { startE: cp.easting, startN: cp.northing, misclosure: 0.005 }
        },
      })

      const result = await g.get<{ startE: number; startN: number; misclosure: number }>('traverse/1')
      expect(result.startE).toBe(100)
      expect(result.startN).toBe(200)
      expect(result.misclosure).toBe(0.005)
    })

    it('computes multi-level dependency chains (cp → traverse → parcel)', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { easting: 0, northing: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => {
          const cp = deps['cp/1'] as { easting: number; northing: number }
          return { stations: [{ e: cp.easting, n: cp.northing }] }
        },
      })

      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async (deps) => {
          const trav = deps['traverse/1'] as { stations: Array<{ e: number; n: number }> }
          return { area: trav.stations.length * 100 }
        },
      })

      const parcel = await g.get<{ area: number }>('parcel/1')
      expect(parcel.area).toBe(100)
    })

    it('supports sync compute functions', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'src', type: 'control_point' })
      g.setPayload('src', { v: 42 })

      g.addNode({
        id: 'dep',
        type: 'custom',
        dependencies: ['src'],
        compute: (deps) => {
          const src = deps['src'] as { v: number }
          return { doubled: src.v * 2 }
        },
      })

      const result = await g.get<{ doubled: number }>('dep')
      expect(result.doubled).toBe(84)
    })
  })

  // ─── Dirty propagation ───────────────────────────────────────────────

  describe('dirty propagation', () => {
    it('marks direct dependents dirty when a source changes', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      await g.get('traverse/1') // compute initially

      expect(g.inspect('traverse/1')?.dirty).toBe(false)

      // Change the control point
      g.markDirty('cp/1')
      expect(g.inspect('cp/1')?.dirty).toBe(true)
      expect(g.inspect('traverse/1')?.dirty).toBe(true)
    })

    it('cascades dirtiness transitively through the graph', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async (deps) => deps['traverse/1'],
      })
      g.addNode({
        id: 'alignment/1',
        type: 'alignment',
        dependencies: ['traverse/1'],
        compute: async (deps) => deps['traverse/1'],
      })

      await g.recomputeAll()

      // Mark cp/1 dirty → all three dependents should cascade
      g.markDirty('cp/1')
      expect(g.inspect('traverse/1')?.dirty).toBe(true)
      expect(g.inspect('parcel/1')?.dirty).toBe(true)
      expect(g.inspect('alignment/1')?.dirty).toBe(true)
    })

    it('does NOT cascade dirtiness to ancestors (only downstream)', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async (deps) => deps['traverse/1'],
      })

      await g.recomputeAll()

      // Mark parcel/1 dirty → cp/1 and traverse/1 should NOT be dirty
      g.markDirty('parcel/1')
      expect(g.inspect('parcel/1')?.dirty).toBe(true)
      expect(g.inspect('traverse/1')?.dirty).toBe(false)
      expect(g.inspect('cp/1')?.dirty).toBe(false)
    })

    it('listDirty returns all dirty node ids', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })

      // Both start dirty (never computed)
      const dirty = g.listDirty()
      expect(dirty).toContain('cp/1')
      expect(dirty).toContain('traverse/1')
    })
  })

  // ─── Lazy recomputation ─────────────────────────────────────────────

  describe('lazy recomputation', () => {
    it('only recomputes dirty nodes (not clean ones)', async () => {
      const g = createEntityGraph()
      let computeCount = 0

      g.addNode({
        id: 'node/1',
        type: 'custom',
        compute: async () => {
          computeCount++
          return { v: computeCount }
        },
      })

      await g.get('node/1')
      expect(computeCount).toBe(1)

      // Second get should NOT recompute
      await g.get('node/1')
      expect(computeCount).toBe(1)
    })

    it('recomputes when dirty flag is set', async () => {
      const g = createEntityGraph()
      let computeCount = 0

      g.addNode({
        id: 'node/1',
        type: 'custom',
        compute: async () => {
          computeCount++
          return { v: computeCount }
        },
      })

      await g.get('node/1')
      expect(computeCount).toBe(1)

      g.markDirty('node/1')
      await g.get('node/1')
      expect(computeCount).toBe(2)
    })

    it('recomputes dependencies only if they are dirty', async () => {
      const g = createEntityGraph()
      let srcComputeCount = 0
      let depComputeCount = 0

      g.addNode({
        id: 'src',
        type: 'custom',
        compute: async () => {
          srcComputeCount++
          return { v: srcComputeCount }
        },
      })
      g.addNode({
        id: 'dep',
        type: 'custom',
        dependencies: ['src'],
        compute: async (deps) => {
          depComputeCount++
          return { doubled: (deps['src'] as { v: number }).v * 2 }
        },
      })

      // Initial compute — both should run
      await g.get('dep')
      expect(srcComputeCount).toBe(1)
      expect(depComputeCount).toBe(1)

      // Mark dep dirty (but NOT src) → src should not recompute
      g.markDirty('dep')
      await g.get('dep')
      expect(srcComputeCount).toBe(1) // unchanged
      expect(depComputeCount).toBe(2)
    })
  })

  // ─── Cycle detection ────────────────────────────────────────────────

  describe('cycle detection', () => {
    it('does not create a cycle for a legitimate DAG (a→b→c, plus c→a is blocked)', () => {
      // The graph prevents cycles at addNode time. A new node's deps
      // are checked: if the new node is already an ancestor of any dep,
      // CycleError is thrown. For a brand-new node this can't happen,
      // so legitimate DAGs always succeed.
      const g = createEntityGraph()
      g.addNode({ id: 'a', type: 'custom' })
      g.addNode({ id: 'b', type: 'custom', dependencies: ['a'] })
      g.addNode({ id: 'c', type: 'custom', dependencies: ['b'] })
      // Adding d with dep on a (sibling branch) is fine
      g.addNode({ id: 'd', type: 'custom', dependencies: ['a'] })
      expect(g.size).toBe(4)
    })

    it('CycleError class is exported and has the right shape', () => {
      const err = new CycleError('from-id', 'to-id', ['from-id', 'mid', 'to-id'])
      expect(err).toBeInstanceOf(Error)
      expect(err.name).toBe('CycleError')
      expect(err.fromId).toBe('from-id')
      expect(err.toId).toBe('to-id')
      expect(err.cyclePath).toEqual(['from-id', 'mid', 'to-id'])
      expect(err.message).toContain('from-id')
      expect(err.message).toContain('to-id')
      expect(err.message).toContain('cycle')
    })

    it('topologicalSort produces a valid order (dependencies before dependents)', async () => {
      // Indirect test of the cycle-free invariant: if a cycle existed,
      // topologicalSort would throw. Building a legitimate DAG and
      // running recomputeAll confirms the graph is acyclic.
      const g = createEntityGraph()
      g.addNode({ id: 'a', type: 'custom' })
      g.setPayload('a', { v: 1 })
      g.addNode({ id: 'b', type: 'custom', dependencies: ['a'], compute: async (d) => d['a'] })
      g.addNode({ id: 'c', type: 'custom', dependencies: ['b'], compute: async (d) => d['b'] })

      await g.recomputeAll()
      // If we got here, no cycle was detected — graph is a valid DAG
      const cPayload = await g.get<{ v: number }>('c')
      expect(cPayload.v).toBe(1)
    })
  })

  // ─── Dependency validation ──────────────────────────────────────────

  describe('dependency validation', () => {
    it('throws DependencyNotFoundError when adding a node with unknown deps', () => {
      const g = createEntityGraph()
      expect(() => {
        g.addNode({
          id: 'node/1',
          type: 'custom',
          dependencies: ['unknown/dep'],
        })
      }).toThrow(DependencyNotFoundError)
    })

    it('allows adding a node with no dependencies (source node)', () => {
      const g = createEntityGraph()
      expect(() => {
        g.addNode({ id: 'src', type: 'control_point' })
      }).not.toThrow()
    })
  })

  // ─── Error handling in compute ──────────────────────────────────────

  describe('error handling', () => {
    it('rethrows errors from compute functions', async () => {
      const g = createEntityGraph()
      g.addNode({
        id: 'failing',
        type: 'custom',
        compute: async () => {
          throw new Error('compute failed')
        },
      })

      await expect(g.get('failing')).rejects.toThrow('compute failed')
    })

    it('records the error in inspect()', async () => {
      const g = createEntityGraph()
      g.addNode({
        id: 'failing',
        type: 'custom',
        compute: async () => {
          throw new Error('boom')
        },
      })

      try {
        await g.get('failing')
      } catch {
        // expected
      }

      const info = g.inspect('failing')
      expect(info?.hasError).toBe(true)
      expect(info?.errorMessage).toBe('boom')
    })

    it('does not retry compute on every get() after an error (clears dirty)', async () => {
      const g = createEntityGraph()
      let callCount = 0
      g.addNode({
        id: 'failing',
        type: 'custom',
        compute: async () => {
          callCount++
          throw new Error('always fails')
        },
      })

      try { await g.get('failing') } catch {}
      try { await g.get('failing') } catch {}

      expect(callCount).toBe(1) // not retried automatically
    })
  })

  // ─── Batch operations ───────────────────────────────────────────────

  describe('batch operations', () => {
    it('recomputeAll computes all nodes in topological order', async () => {
      const g = createEntityGraph()
      const order: string[] = []

      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async () => {
          order.push('traverse/1')
          return { stations: [] }
        },
      })
      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async () => {
          order.push('parcel/1')
          return { area: 100 }
        },
      })

      await g.recomputeAll()

      // traverse should be computed before parcel
      expect(order.indexOf('traverse/1')).toBeLessThan(order.indexOf('parcel/1'))
    })

    it('recomputeAll skips already-clean nodes', async () => {
      const g = createEntityGraph()
      let count = 0

      g.addNode({
        id: 'src',
        type: 'custom',
        compute: async () => {
          count++
          return { v: count }
        },
      })

      await g.recomputeAll()
      expect(count).toBe(1)

      await g.recomputeAll()
      expect(count).toBe(1) // not recomputed
    })
  })

  // ─── Dependent listing ──────────────────────────────────────────────

  describe('dependent listing', () => {
    it('listDependents returns direct dependents', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({ id: 'trav/1', type: 'traverse', dependencies: ['cp/1'] })
      g.addNode({ id: 'trav/2', type: 'traverse', dependencies: ['cp/1'] })
      g.addNode({ id: 'unrelated', type: 'custom' })

      const deps = g.listDependents('cp/1')
      expect(deps).toContain('trav/1')
      expect(deps).toContain('trav/2')
      expect(deps).not.toContain('unrelated')
    })

    it('listTransitiveDependents returns the full downstream subtree', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({ id: 'trav/1', type: 'traverse', dependencies: ['cp/1'] })
      g.addNode({ id: 'parcel/1', type: 'parcel', dependencies: ['trav/1'] })
      g.addNode({ id: 'alignment/1', type: 'alignment', dependencies: ['trav/1'] })

      const transitive = g.listTransitiveDependents('cp/1')
      expect(transitive).toContain('trav/1')
      expect(transitive).toContain('parcel/1')
      expect(transitive).toContain('alignment/1')
      expect(transitive.length).toBe(3)
    })
  })

  // ─── Serialization ──────────────────────────────────────────────────

  describe('serialization', () => {
    it('serialize returns all node state', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point', label: 'Control Point 1' })
      g.setPayload('cp/1', { e: 100, n: 200 })

      g.addNode({
        id: 'trav/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      await g.get('trav/1')

      const serialized = g.serialize()
      expect(serialized.nodes.length).toBe(2)

      const cp = serialized.nodes.find((n) => n.id === 'cp/1')
      expect(cp?.type).toBe('control_point')
      expect(cp?.label).toBe('Control Point 1')
      expect(cp?.payload).toEqual({ e: 100, n: 200 })
      expect(cp?.dirty).toBe(false)

      const trav = serialized.nodes.find((n) => n.id === 'trav/1')
      expect(trav?.dependencies).toEqual(['cp/1'])
      expect(trav?.computedAt).toBeDefined()
    })
  })

  // ─── Realistic survey scenario ─────────────────────────────────────

  describe('realistic survey scenario', () => {
    it('control point change cascades to traverse, parcel, and alignment', async () => {
      const g = createEntityGraph()

      // Source: control point
      g.addNode({ id: 'cp/origin', type: 'control_point' })
      g.setPayload('cp/origin', { easting: 250000, northing: 9945000 })

      // Traverse depends on control point
      g.addNode({
        id: 'trav/main',
        type: 'traverse',
        dependencies: ['cp/origin'],
        compute: async (deps) => {
          const cp = deps['cp/origin'] as { easting: number; northing: number }
          return {
            stations: [
              { name: 'A', e: cp.easting, n: cp.northing },
              { name: 'B', e: cp.easting + 100, n: cp.northing },
            ],
            misclosure: 0.003,
          }
        },
      })

      // Parcel depends on traverse
      g.addNode({
        id: 'parcel/P1',
        type: 'parcel',
        dependencies: ['trav/main'],
        compute: async (deps) => {
          const trav = deps['trav/main'] as { stations: Array<{ e: number; n: number }> }
          return { areaSqm: trav.stations.length * 5000, perimeterM: 400 }
        },
      })

      // Alignment depends on traverse (cross-hub!)
      g.addNode({
        id: 'alignment/road-1',
        type: 'alignment',
        dependencies: ['trav/main'],
        compute: async (deps) => {
          const trav = deps['trav/main'] as { stations: Array<{ e: number; n: number }> }
          return { startChainage: 0, endChainage: trav.stations.length * 100 }
        },
      })

      // Initial computation
      await g.recomputeAll()
      const initialParcel = await g.get<{ areaSqm: number }>('parcel/P1')
      expect(initialParcel.areaSqm).toBe(10000)

      // Now: surveyor moves the control point (Helmert adjustment)
      g.markDirty('cp/origin')
      // → traverse, parcel, alignment all dirty
      expect(g.listDirty().sort()).toEqual([
        'alignment/road-1',
        'cp/origin',
        'parcel/P1',
        'trav/main',
      ])

      // Surveyor fixes the control point and re-sets its payload
      g.setPayload('cp/origin', { easting: 250050, northing: 9945050 })
      // setPayload clears dirty on cp/origin but NOT on dependents
      expect(g.inspect('cp/origin')?.dirty).toBe(false)
      expect(g.inspect('trav/main')?.dirty).toBe(true)

      // Recompute everything
      await g.recomputeAll()
      expect(g.listDirty().length).toBe(0)

      // Parcel payload should reflect the new control point (same shape, recomputed)
      const recomputedParcel = await g.get<{ areaSqm: number }>('parcel/P1')
      expect(recomputedParcel.areaSqm).toBe(10000) // same shape — 2 stations × 5000
    })
  })

  // ─── Node removal ───────────────────────────────────────────────────

  describe('node removal', () => {
    it('removes a leaf node (no dependents)', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({
        id: 'trav/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })

      g.removeNode('trav/1')
      expect(g.listAll()).toEqual(['cp/1'])
    })

    it('throws when removing a node with dependents', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({
        id: 'trav/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })

      expect(() => g.removeNode('cp/1')).toThrow(/still depend on it/)
    })
  })
})

/**
 * Leica GSI Format Parser — Full Implementation
 * GSI-8 and GSI-16 formats
 *
 * Phase 23: Complete parser with all 40+ Word Identifier codes,
 * face-left/face-right pairing, and mean face reduction.
 *
 * Reference: Leica TPS1200/TS06/TS16 GSI Format Specification
 * Reference: Ghilani & Wolf, Elementary Surveying 16th Ed.
 *
 * WI Code Groups:
 *  11-19: Point identification
 *  21-29: Angles
 *  31-39: Distances
 *  41-49: Code information
 *  51-59: Distance corrections
 *  71-79: Point attributes / feature codes
 *  81-89: Coordinates / heights
 */

export interface GSIRecord {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  horizontalAngle?: number  // degrees (decimal)
  verticalAngle?: number    // degrees (decimal)
  slopeDistance?: number     // metres
  horizontalDistance?: number // metres (WI 32)
  heightDifference?: number  // metres (WI 33)
  reflectorHeight?: number   // metres
  instrumentHeight?: number  // metres
  ppm?: number               // parts per million correction
  prismConstant?: number     // mm
  featureCode?: string       // point feature code
  description?: string       // point description
  facePosition?: 'FL' | 'FR' | 'unknown'
  rawLine?: string
}

export interface GSIParseResult {
  ok: boolean
  records: GSIRecord[]
  warnings: string[]
  format: 'GSI-8' | 'GSI-16' | 'unknown'
  statistics: {
    totalRecords: number
    coordinateRecords: number
    observationRecords: number
    faceLeftCount: number
    faceRightCount: number
  }
}

/**
 * Parse a GSI-8 or GSI-16 format file from a Leica total station.
 * Handles all standard Word Identifier codes.
 */
export function parseGSI(content: string): GSIParseResult {
  const warnings: string[] = []
  const records: GSIRecord[] = []
  const lines = content.trim().split('\n').filter((l: string) => l.trim())

  if (!lines.length) {
    return {
      ok: false, records: [], warnings: ['Empty file'], format: 'unknown',
      statistics: { totalRecords: 0, coordinateRecords: 0, observationRecords: 0, faceLeftCount: 0, faceRightCount: 0 },
    }
  }

  // Detect format: GSI-16 lines start with '*'
  const firstLine = lines[0].trim()
  const format: 'GSI-8' | 'GSI-16' = firstLine.startsWith('*') ? 'GSI-16' : 'GSI-8'
  const wordLength = format === 'GSI-16' ? 24 : 16

  let coordinateRecords = 0
  let observationRecords = 0
  let faceLeftCount = 0
  let faceRightCount = 0

  for (const line of lines) {
    const cleanLine = line.trim().replace(/^\*/, '')
    if (!cleanLine) continue

    const record: GSIRecord = { pointId: '', rawLine: line.trim() }

    // GSI format: each line has multiple "words", each wordLength characters
    // Each word structure: WI.SIGN.DATA
    //   WI = 2 digits (Word Identifier)
    //   Positions 2-6: metadata (info bytes)
    //   Position 6: sign ('+' or '-')
    //   Position 7+: data value

    let pos = 0
    while (pos < cleanLine.length) {
      const word = cleanLine.substring(pos, pos + wordLength).trim()
      if (!word) { pos += wordLength; continue }

      // Parse word identifier (first 2 characters)
      const wi = word.substring(0, 2)

      // Parse sign and value
      // In GSI-16 format: WI(2) + info(4) + sign(1) + data(16) = 23 chars
      // In GSI-8 format: WI(2) + info(4) + sign(1) + data(8) = 15 chars
      const signPos = 6
      const sign = word.length > signPos ? word[signPos] : '+'
      const dataStr = word.substring(signPos + 1 || 7).replace(/\s+/g, '')
      const signMultiplier = sign === '-' ? -1 : 1

      // Parse the numeric data value
      const rawNumValue = parseFloat(dataStr)
      if (isNaN(rawNumValue) && wi !== '41' && wi !== '71' && wi !== '72') {
        pos += wordLength
        continue
      }

      const numValue = signMultiplier * rawNumValue

      switch (wi) {
        // ─── Point Identification ──────────────────────────────────────
        case '11': // Point number
          record.pointId = dataStr.replace(/^0+/, '') || '0'
          break
        case '12': // Serial number of instrument
          // Informational — skip
          break
        case '18': // Timestamp
          // Informational — skip
          break
        case '19': // Block number / face indicator
          // In some Leica instruments, position 5 = face (0=FL, 1=FR)
          break

        // ─── Angles ────────────────────────────────────────────────────
        case '21': // Horizontal angle (Hz)
          record.horizontalAngle = numValue / 100000 // GSI stores as ddddggggg (100000ths of gon) or dddmmss.s
          break
        case '22': // Vertical angle (V)
          record.verticalAngle = numValue / 100000
          break
        case '24': // Horizontal angle (Hz) in Hz increments
          record.horizontalAngle = numValue / 100000
          break
        case '25': // Horizontal difference (Hz delta)
          break

        // ─── Distances ─────────────────────────────────────────────────
        case '31': // Slope distance (m)
          record.slopeDistance = numValue / 1000
          break
        case '32': // Horizontal distance (m)
          record.horizontalDistance = numValue / 1000
          break
        case '33': // Height difference (m)
          record.heightDifference = numValue / 1000
          break

        // ─── Code / Description ────────────────────────────────────────
        case '41': // Code block 1
        case '42': // Code block 2
          record.featureCode = dataStr.replace(/^0+/, '').trim() || dataStr.trim()
          break
        case '43': // Code block 3
        case '44': // Code block 4
        case '45': // Code block 5
        case '46': // Code block 6
        case '47': // Code block 7
        case '48': // Code block 8
        case '49': // Code block 9
          if (!record.description) {
            record.description = dataStr.replace(/^0+/, '').trim()
          } else {
            record.description += ' ' + dataStr.replace(/^0+/, '').trim()
          }
          break

        // ─── Distance Corrections ──────────────────────────────────────
        case '51': // PPM (atmospheric + geometric)
          record.ppm = numValue / 10 // stored as ppm × 10
          break
        case '52': // Prism constant (mm)
          record.prismConstant = numValue / 10 // stored as mm × 10
          break
        case '53': // PPM (atmospheric only)
          break
        case '58': // Addition constant
          break
        case '59': // Scale factor
          break

        // ─── Point Attributes / Feature Codes ──────────────────────────
        case '71': // Remark / point attribute 1
        case '72': // Remark / point attribute 2
        case '73': // Remark / point attribute 3
        case '74': // Remark / point attribute 4
        case '75': // Remark / point attribute 5
        case '76': // Remark / point attribute 6
        case '77': // Remark / point attribute 7
        case '78': // Remark / point attribute 8
        case '79': // Remark / point attribute 9
          if (!record.featureCode) {
            record.featureCode = dataStr.replace(/^0+/, '').trim()
          }
          break

        // ─── Coordinates ───────────────────────────────────────────────
        case '81': // Easting (E) in mm
          record.easting = numValue / 1000
          break
        case '82': // Northing (N) in mm
          record.northing = numValue / 1000
          break
        case '83': // Elevation (H) in mm
          record.elevation = numValue / 1000
          break
        case '84': // Easting (E) in 0.1mm
          record.easting = numValue / 10000
          break
        case '85': // Northing (N) in 0.1mm
          record.northing = numValue / 10000
          break
        case '86': // Elevation (H) in 0.1mm
          record.elevation = numValue / 10000
          break
        case '87': // Reflector height (m) — stored in mm
          record.reflectorHeight = numValue / 1000
          break
        case '88': // Instrument height (m) — stored in mm
          record.instrumentHeight = numValue / 1000
          break

        default:
          // Unknown WI — skip but warn on first occurrence
          break
      }

      pos += wordLength
    }

    if (record.pointId) {
      // Detect face position from vertical angle
      // FL: vertical angle 0-200 gon (0-180°)
      // FR: vertical angle 200-400 gon (180-360°)
      if (record.verticalAngle !== undefined) {
        if (record.verticalAngle >= 0 && record.verticalAngle < 200) {
          record.facePosition = 'FL'
          faceLeftCount++
        } else if (record.verticalAngle >= 200) {
          record.facePosition = 'FR'
          faceRightCount++
        } else {
          record.facePosition = 'unknown'
        }
      }

      if (record.easting !== undefined || record.northing !== undefined) {
        coordinateRecords++
      }
      if (record.horizontalAngle !== undefined || record.slopeDistance !== undefined) {
        observationRecords++
      }

      records.push(record)
    }
  }

  return {
    ok: records.length > 0,
    records,
    warnings,
    format,
    statistics: {
      totalRecords: records.length,
      coordinateRecords,
      observationRecords,
      faceLeftCount,
      faceRightCount,
    },
  }
}

// ─── Face-Left / Face-Right Pairing ─────────────────────────────────────────

export interface FacePair {
  pointId: string
  faceLeft: GSIRecord
  faceRight: GSIRecord | null
  meanHorizontalAngle: number   // degrees
  meanVerticalAngle: number     // degrees
  meanSlopeDistance: number      // metres
  horizontalDistance: number     // metres
  heightDifference: number      // metres
  collimationError?: number     // arc-seconds
}

/**
 * Pair face-left and face-right observations by point ID.
 *
 * For dual-face observations:
 * - Mean Hz = (Hz_FL + Hz_FR + 180°) / 2
 * - Mean V = (V_FL + (360° - V_FR)) / 2  (or in gon: (V_FL + (400-V_FR))/2)
 * - Mean SD = (SD_FL + SD_FR) / 2
 *
 * Source: Ghilani & Wolf, Chapter 12 — Mean face reduction
 * Source: N.N. Basak, Surveying and Levelling, Chapter 10
 */
export function pairFaces(records: GSIRecord[]): FacePair[] {
  // Group records by point ID
  const groups = new Map<string, { fl: GSIRecord | null; fr: GSIRecord | null }>()

  for (const rec of records) {
    if (!rec.pointId) continue
    if (rec.facePosition === 'FL') {
      const existing = groups.get(rec.pointId) || { fl: null, fr: null }
      existing.fl = rec
      groups.set(rec.pointId, existing)
    } else if (rec.facePosition === 'FR') {
      const existing = groups.get(rec.pointId) || { fl: null, fr: null }
      existing.fr = rec
      groups.set(rec.pointId, existing)
    } else if (rec.horizontalAngle !== undefined || rec.slopeDistance !== undefined) {
      // Single face — treat as FL
      const existing = groups.get(rec.pointId) || { fl: null, fr: null }
      if (!existing.fl) existing.fl = rec
      groups.set(rec.pointId, existing)
    }
  }

  const pairs: FacePair[] = []

  for (const [pointId, group] of Array.from(groups)) {
    const fl = group.fl
    const fr = group.fr

    if (!fl) continue

    let meanHz = fl.horizontalAngle ?? 0
    let meanV = fl.verticalAngle ?? 0
    let meanSD = fl.slopeDistance ?? 0

    if (fr) {
      // Mean horizontal angle: (Hz_FL + (Hz_FR + 180°)) / 2
      let hzFR = (fr.horizontalAngle ?? 0) + 180
      if (hzFR >= 360) hzFR -= 360
      // Handle wrapping near 0°/360°
      let diff = hzFR - meanHz
      if (diff > 180) diff -= 360
      if (diff < -180) diff += 360
      meanHz = meanHz + diff / 2
      if (meanHz < 0) meanHz += 360
      if (meanHz >= 360) meanHz -= 360

      // Mean vertical angle: (V_FL + (360° - V_FR)) / 2
      const vFR = 360 - (fr.verticalAngle ?? 0)
      meanV = (meanV + vFR) / 2

      // Mean slope distance
      meanSD = ((fl.slopeDistance ?? 0) + (fr.slopeDistance ?? 0)) / 2

      // Collimation error (C) in arc-seconds
      // C = (Hz_FL - (Hz_FR + 180°)) / 2
      const collimation = ((fl.horizontalAngle ?? 0) - hzFR) * 3600 / 2
    }

    // Compute horizontal distance and height difference
    const vRad = meanV * Math.PI / 180
    const hd = meanSD * Math.sin(vRad) // When V is zenith angle, HD = SD × sin(V)
    const dh = meanSD * Math.cos(vRad) + (fl.instrumentHeight ?? 0) - (fl.reflectorHeight ?? 0)

    pairs.push({
      pointId,
      faceLeft: fl,
      faceRight: fr,
      meanHorizontalAngle: meanHz,
      meanVerticalAngle: meanV,
      meanSlopeDistance: meanSD,
      horizontalDistance: Math.abs(hd),
      heightDifference: dh,
    })
  }

  return pairs
}

// ─── Convert GSI Records to Traverse Observations ───────────────────────────

export interface TraverseObservation {
  station: string
  bs: string
  fs: string
  hclDeg: string
  hclMin: string
  hclSec: string
  hcrDeg: string
  hcrMin: string
  hcrSec: string
  slopeDist: string
  vaDeg: string
  vaMin: string
  vaSec: string
  ih: string
  th: string
  remarks?: string
}

/**
 * Convert paired GSI records into TraverseModal-compatible observations.
 *
 * This is the pipeline that connects GSI import to the traverse computation:
 * GSI file → parseGSI() → pairFaces() → toTraverseObservations() → TraverseModal
 */
export function toTraverseObservations(
  pairs: FacePair[],
  backsightPointId?: string
): TraverseObservation[] {
  const observations: TraverseObservation[] = []

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i]

    // Convert decimal degrees to DMS
    const hzFL = decimalToDMS(pair.faceLeft.horizontalAngle ?? 0)
    const hzFR = pair.faceRight
      ? decimalToDMS(pair.faceRight.horizontalAngle ?? 0)
      : { d: '0', m: '0', s: '0' }

    const vAngle = decimalToDMS(pair.meanVerticalAngle)

    observations.push({
      station: pair.pointId,
      bs: i === 0 ? (backsightPointId || 'BS') : pairs[i - 1].pointId,
      fs: i < pairs.length - 1 ? pairs[i + 1].pointId : 'FS',
      hclDeg: hzFL.d,
      hclMin: hzFL.m,
      hclSec: hzFL.s,
      hcrDeg: hzFR.d,
      hcrMin: hzFR.m,
      hcrSec: hzFR.s,
      slopeDist: pair.meanSlopeDistance.toFixed(4),
      vaDeg: vAngle.d,
      vaMin: vAngle.m,
      vaSec: vAngle.s,
      ih: (pair.faceLeft.instrumentHeight ?? 0).toFixed(3),
      th: (pair.faceLeft.reflectorHeight ?? 0).toFixed(3),
      remarks: pair.faceLeft.featureCode || '',
    })
  }

  return observations
}

function decimalToDMS(decimal: number): { d: string; m: string; s: string } {
  const abs = Math.abs(decimal)
  const d = Math.floor(abs)
  const mFloat = (abs - d) * 60
  const m = Math.floor(mFloat)
  const s = (mFloat - m) * 60
  return {
    d: String(d),
    m: String(m),
    s: s.toFixed(1),
  }
}

export interface JobXMLRecord {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  code?: string
  note?: string
}

export function parseJobXML(content: string): {
  ok: boolean
  records: JobXMLRecord[]
  warnings: string[]
  jobName?: string
} {
  const warnings: string[] = []
  const records: JobXMLRecord[] = []

  try {
    const parser = new DOMParser()
    const doc = parser.parseFromString(content, 'text/xml')

    const jobName = doc.querySelector('JOBFile')
      ?.getAttribute('JobName') || undefined

    const pointRecords = doc.querySelectorAll('PointRecord')
    pointRecords.forEach((pr: Element) => {
      const id = pr.querySelector('Name')?.textContent?.trim()
      if (!id) return

      const northing = parseFloat(
        pr.querySelector('Grid > North')?.textContent || '0'
      )
      const easting = parseFloat(
        pr.querySelector('Grid > East')?.textContent || '0'
      )
      const elevation = parseFloat(
        pr.querySelector('Grid > Elev')?.textContent || '0'
      )
      const code = pr.querySelector('Code')?.textContent?.trim()

      records.push({ 
        pointId: id, 
        easting, 
        northing, 
        elevation,
        code
      })
    })

    const obsRecords = doc.querySelectorAll('RawObservation')
    obsRecords.forEach((obs: Element) => {
      const id = obs.querySelector('TargetID')?.textContent?.trim()
      if (!id || records.find((r) => r.pointId === id)) return
      warnings.push(`Raw observation for ${id} — no coordinates computed`)
    })

    return { ok: true, records, warnings, jobName }

  } catch (err) {
    return { 
      ok: false, 
      records: [], 
      warnings: ['Failed to parse JobXML file — check file format'] 
    }
  }
}

