/**
 * Marketplace API Client
 *
 * Replaces the localStorage-based instruments.ts with real API calls.
 * All data now persists to the instrument_listings table (migration 033).
 */

import type { InstrumentListing, ListingType, InstrumentCategory, Condition, Currency } from './instruments'

export interface ListingFilters {
  type?: ListingType
  category?: InstrumentCategory
  condition?: Condition
  q?: string
}

export async function fetchListings(filters?: ListingFilters): Promise<InstrumentListing[]> {
  const params = new URLSearchParams()
  if (filters?.type) params.set('type', filters.type)
  if (filters?.category) params.set('category', filters.category)
  if (filters?.condition) params.set('condition', filters.condition)
  if (filters?.q) params.set('q', filters.q)

  const res = await fetch(`/api/marketplace/listings?${params}`)
  if (!res.ok) return []
  const json = (await res.json()) as { data?: InstrumentListing[] }
  return json.data || []
}

export async function createListing(data: {
  type: string
  category: string
  title: string
  brand?: string
  model?: string
  condition: string
  year?: number
  description?: string
  price: number
  currency?: string
  rentPeriod?: string
  location?: string
  country?: string
  sellerName?: string
  sellerContact?: string
  images?: string[]
}): Promise<InstrumentListing | null> {
  const res = await fetch('/api/marketplace/listings', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
    credentials: 'include',
  })
  if (!res.ok) return null
  const json = (await res.json()) as { data?: InstrumentListing }
  return json.data || null
}

export async function deleteListing(id: string): Promise<boolean> {
  const res = await fetch(`/api/marketplace/listings/${id}`, {
    method: 'DELETE',
    credentials: 'include',
  })
  return res.ok
}

export async function sendInquiry(listingId: string, data: {
  message: string
  contactEmail?: string
  contactPhone?: string
}): Promise<boolean> {
  const res = await fetch('/api/marketplace/inquiries', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ listingId, ...data }),
    credentials: 'include',
  })
  return res.ok
}

export async function fetchInquiries(listingId: string): Promise<unknown[]> {
  const res = await fetch(`/api/marketplace/inquiries?listingId=${listingId}`, {
    credentials: 'include',
  })
  if (!res.ok) return []
  const json = (await res.json()) as { data?: unknown[] }
  return json.data || []
}

/* eslint-disable no-console */
type LogLevel = 'debug' | 'info' | 'warn' | 'error'

interface LogEntry {
  level: LogLevel
  message: string
  timestamp: string
  context?: Record<string, unknown>
  userId?: string
  error?: string
}

const LOG_ENDPOINT = process.env.NEXT_PUBLIC_LOG_ENDPOINT

class Logger {
  private logs: LogEntry[] = []
  private maxLogs = 100

  private createEntry(level: LogLevel, message: string, context?: Record<string, unknown>, userId?: string): LogEntry {
    const entry: LogEntry = {
      level,
      message,
      timestamp: new Date().toISOString(),
      context,
      userId
    }

    if (level === 'error' && context?.error) {
      entry.error = String(context.error)
    }

    return entry
  }

  private addEntry(entry: LogEntry) {
    this.logs.push(entry)
    if (this.logs.length > this.maxLogs) {
      this.logs.shift()
    }
  }

  public log(level: LogLevel, message: string, context?: Record<string, unknown>, userId?: string) {
    const entry = this.createEntry(level, message, context, userId)
    this.addEntry(entry)

    if (LOG_ENDPOINT && process.env.NODE_ENV === 'production') {
      this.sendToEndpoint(entry)
    }

    const prefix = `[${level.toUpperCase()}]`
    const msg = `${prefix} ${message}`
    switch (level) {
      case 'debug':
        break
      case 'info':
        console.info(msg, context || '')
        break
      case 'warn':
        console.warn(msg, context || '')
        break
      case 'error':
        console.error(msg, context || '')
        break
    }
  }

  private async sendToEndpoint(entry: LogEntry) {
    if (!LOG_ENDPOINT) return
    try {
      await fetch(LOG_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(entry),
        signal: AbortSignal.timeout(5000)
      })
    } catch {
      // Silently fail
    }
  }

  debug(message: string, context?: Record<string, unknown>) {
    this.log('debug', message, context)
  }

  info(message: string, context?: Record<string, unknown>) {
    this.log('info', message, context)
  }

  warn(message: string, context?: Record<string, unknown>) {
    this.log('warn', message, context)
  }

  error(message: string, context?: Record<string, unknown>) {
    this.log('error', message, context)
  }

  getLogs(): LogEntry[] {
    return [...this.logs]
  }

  clearLogs() {
    this.logs = []
  }
}

export const logger = new Logger()

export function logApiRequest(
  method: string,
  path: string,
  statusCode: number,
  duration: number,
  userId?: string
) {
  const level: LogLevel = statusCode >= 500 ? 'error' : statusCode >= 400 ? 'warn' : 'info'
  
  logger.log(level, `${method} ${path}`, {
    statusCode,
    duration,
    userId
  })
}

export function logUserAction(
  action: string,
  details: Record<string, unknown>,
  userId?: string
) {
  logger.info(`User action: ${action}`, details)
}

export function logError(
  error: Error | unknown,
  context?: Record<string, unknown>
) {
  logger.error('Error occurred', {
    error: error instanceof Error ? error.message : String(error),
    stack: error instanceof Error ? error.stack : undefined,
    ...context
  })
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Middleware Metrics Tracker
// ──────────────────────────────────────────────────────────────────────────
// Integrates with Next.js middleware to track HTTP request metrics.
//
// Usage — add to your existing middleware.ts:
//
//   import { withMetrics } from '@/lib/monitoring/middleware-tracker';
//
//   export async function middleware(request: NextRequest) {
//     return withMetrics(request, async () => {
//       // ... your existing middleware logic ...
//       return NextResponse.next();
//     });
//   }
// ──────────────────────────────────────────────────────────────────────────

import { NextRequest, NextResponse } from 'next/server';
import {
  httpRequestsTotal,
  httpRequestDuration,
  httpActiveRequests,
  httpRequestSize,
  httpResponseSize,
} from './metrics';

/**
 * Wrap a middleware handler with Prometheus metrics tracking.
 *
 * @param request - The incoming Next.js request
 * @param handler - Your middleware logic (must return a NextResponse)
 * @returns The response from the handler, with metrics recorded
 */
export async function withMetrics(
  request: NextRequest,
  handler: () => Promise<NextResponse>,
): Promise<NextResponse> {
  const method = request.method;
  const pathname = request.nextUrl.pathname;

  // Normalize path to avoid high cardinality labels
  // e.g., /projects/abc123 → /projects/[id]
  const normalizedPath = normalizePath(pathname);

  // Skip metrics for static assets and the metrics endpoint itself
  if (shouldSkipMetrics(pathname)) {
    return handler();
  }

  httpActiveRequests.inc();

  // Track request body size
  const contentLength = request.headers.get('content-length');
  if (contentLength) {
    httpRequestSize.observe({ method, path: normalizedPath }, parseInt(contentLength, 10));
  }

  const startTime = performance.now();

  try {
    const response = await handler();

    const duration = (performance.now() - startTime) / 1000;
    const statusCode = String(response.status);

    httpRequestsTotal.inc({ method, path: normalizedPath, status_code: statusCode });
    httpRequestDuration.observe({ method, path: normalizedPath, status_code: statusCode }, duration);

    // Track response size if available
    const responseContentLength = response.headers.get('content-length');
    if (responseContentLength) {
      httpResponseSize.observe({ method, path: normalizedPath }, parseInt(responseContentLength, 10));
    }

    return response;
  } catch (err) {
    const duration = (performance.now() - startTime) / 1000;

    httpRequestsTotal.inc({ method, path: normalizedPath, status_code: '500' });
    httpRequestDuration.observe({ method, path: normalizedPath, status_code: '500' }, duration);

    throw err;
  } finally {
    httpActiveRequests.dec();
  }
}

// ─── Path Normalization ──────────────────────────────────────────────────

/**
 * Normalize dynamic route segments to avoid high cardinality.
 *
 * Examples:
 *   /projects/abc123       → /projects/[id]
 *   /projects/abc123/edit  → /projects/[id]/edit
 *   /api/survey/audit?id=x → /api/survey/audit
 *   /users/123/profile     → /users/[id]/profile
 */
export function normalizePath(pathname: string): string {
  // Skip static assets
  if (
    pathname.startsWith('/_next/') ||
    pathname.startsWith('/favicon') ||
    pathname.match(/\.(js|css|png|jpg|jpeg|gif|svg|ico|woff2?|ttf|eot)$/)
  ) {
    return '/_next/static';
  }

  // Normalize dynamic segments
  const segments = pathname.split('/').filter(Boolean);
  const normalized = segments.map((segment, index) => {
    // UUID pattern
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(segment)) {
      return '[id]';
    }
    // CUID pattern (starts with 'c')
    if (/^c[a-z0-9]{24,}$/i.test(segment)) {
      return '[id]';
    }
    // Pure numeric
    if (/^\d+$/.test(segment)) {
      return '[id]';
    }
    // Looks like a hash or encoded ID (long alphanumeric)
    if (segment.length > 20 && /^[a-zA-Z0-9_-]+$/.test(segment)) {
      return '[id]';
    }
    return segment;
  });

  return '/' + normalized.join('/');
}

// ─── Skip Conditions ─────────────────────────────────────────────────────

function shouldSkipMetrics(pathname: string): boolean {
  return (
    pathname === '/api/public/metrics' ||    // Don't track the metrics endpoint itself
    pathname.startsWith('/_next/') ||         // Static assets
    pathname.startsWith('/favicon') ||
    pathname.match(/\.(js|css|png|jpg|jpeg|gif|svg|ico|woff2?|ttf|eot)$/) !== null
  );
}

/**
 * Distributed Tracing — OpenTelemetry-style trace context propagation
 *
 * ByteByteGo audit fix: Add distributed tracing between Next.js and Python worker.
 *
 * WHAT THIS DOES
 * --------------
 * 1. Generates a trace ID for every incoming request (if not from upstream)
 * 2. Propagates the trace ID to the Python worker via X-Trace-Id header
 * 3. Propagates the trace ID to outbound fetch calls (Stripe, M-Pesa, etc.)
 * 4. The Python worker logs the trace ID, enabling end-to-end request tracing
 * 5. Sentry is configured with the same trace ID for cross-referencing
 *
 * This implements the W3C Trace Context standard (traceparent header):
 *   traceparent: 00-{trace-id}-{span-id}-{flags}
 *
 * USAGE
 * -----
 * // In API routes:
 * import { getTraceContext, traceFetch } from '@/lib/monitoring/tracing'
 * const trace = getTraceContext(request)
 * const response = await traceFetch('https://api.stripe.com/...', { ... }, trace)
 *
 * // In Python worker calls:
 * const response = await traceFetch(`${PYTHON_WORKER_URL}/osm/features`, { ... }, trace)
 */

import { randomUUID } from 'crypto'
import type { NextRequest } from 'next/server'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface TraceContext {
  traceId: string
  spanId: string
  parentSpanId?: string
  sampled: boolean
}

// ─── Trace Context Extraction & Generation ──────────────────────────────────

/**
 * Extract trace context from an incoming request.
 *
 * Checks for W3C traceparent header first, then falls back to X-Trace-Id.
 * If no trace context is found, generates a new one.
 */
export function getTraceContext(request?: NextRequest | Request): TraceContext {
  // Try W3C traceparent header first
  const traceparent = request?.headers.get('traceparent')
  if (traceparent) {
    const parts = traceparent.split('-')
    if (parts.length === 4 && parts[0] === '00') {
      return {
        traceId: parts[1],
        spanId: randomUUID().replace(/-/g, '').slice(0, 16),
        parentSpanId: parts[2],
        sampled: parts[3] === '01',
      }
    }
  }

  // Fall back to X-Trace-Id (simpler, used by our Python worker)
  const existingTraceId = request?.headers.get('x-trace-id')
  if (existingTraceId) {
    return {
      traceId: existingTraceId,
      spanId: randomUUID().replace(/-/g, '').slice(0, 16),
      sampled: true,
    }
  }

  // Generate new trace context
  return {
    traceId: randomUUID().replace(/-/g, ''),
    spanId: randomUUID().replace(/-/g, '').slice(0, 16),
    sampled: true,
  }
}

/**
 * Format a traceparent header for outbound requests.
 */
export function formatTraceparent(trace: TraceContext): string {
  return `00-${trace.traceId}-${trace.spanId}-${trace.sampled ? '01' : '00'}`
}

/**
 * Get trace headers to add to outbound requests.
 */
export function getTraceHeaders(trace: TraceContext): Record<string, string> {
  return {
    'traceparent': formatTraceparent(trace),
    'x-trace-id': trace.traceId,
    'x-span-id': trace.spanId,
  }
}

// ─── Traced Fetch Wrapper ───────────────────────────────────────────────────

/**
 * Fetch with trace context propagation.
 *
 * Automatically adds traceparent and X-Trace-Id headers to outbound requests.
 * If no trace context is provided, generates a new one (root span).
 *
 * Usage:
 *   const trace = getTraceContext(request)
 *   const res = await traceFetch('https://api.stripe.com/...', { method: 'POST', ... }, trace)
 */
export async function traceFetch(
  url: string,
  options: RequestInit = {},
  trace?: TraceContext,
): Promise<Response> {
  const ctx = trace || getTraceContext()

  const headers = new Headers(options.headers)
  const traceHeaders = getTraceHeaders(ctx)
  for (const [key, value] of Object.entries(traceHeaders)) {
    headers.set(key, value)
  }

  const startTime = performance.now()

  try {
    const response = await fetch(url, { ...options, headers })

    // Record metrics for this outbound call
    const duration = performance.now() - startTime
    recordOutboundSpan(url, ctx, response.status, duration)

    return response
  } catch (err) {
    const duration = performance.now() - startTime
    recordOutboundSpan(url, ctx, 0, duration, err instanceof Error ? err.message : 'Unknown')
    throw err
  }
}

// ─── Span Recording (for /metrics endpoint) ─────────────────────────────────

interface SpanRecord {
  url: string
  traceId: string
  spanId: string
  status: number
  durationMs: number
  error?: string
  timestamp: number
}

const recentSpans: SpanRecord[] = []
const MAX_SPANS = 1000

function recordOutboundSpan(
  url: string,
  trace: TraceContext,
  status: number,
  durationMs: number,
  error?: string,
) {
  recentSpans.push({
    url: url.substring(0, 200),  // truncate long URLs
    traceId: trace.traceId,
    spanId: trace.spanId,
    status,
    durationMs,
    error,
    timestamp: Date.now(),
  })

  if (recentSpans.length > MAX_SPANS) {
    recentSpans.shift()
  }
}

/**
 * Get recent outbound spans (for debugging / /metrics endpoint).
 */
export function getRecentSpans(): SpanRecord[] {
  return [...recentSpans].reverse()  // most recent first
}

/**
 * Get span statistics for /metrics endpoint.
 */
export function getSpanStats(): {
  totalSpans: number
  errorSpans: number
  avgDurationMs: number
  p90DurationMs: number
  p99DurationMs: number
} {
  if (recentSpans.length === 0) {
    return { totalSpans: 0, errorSpans: 0, avgDurationMs: 0, p90DurationMs: 0, p99DurationMs: 0 }
  }

  const durations = recentSpans.map(s => s.durationMs).sort((a, b) => a - b)
  const errors = recentSpans.filter(s => s.status >= 400 || s.error).length
  const avg = durations.reduce((s, v) => s + v, 0) / durations.length
  const p90 = durations[Math.floor(durations.length * 0.9)]
  const p99 = durations[Math.floor(durations.length * 0.99)]

  return {
    totalSpans: recentSpans.length,
    errorSpans: errors,
    avgDurationMs: Math.round(avg),
    p90DurationMs: Math.round(p90),
    p99DurationMs: Math.round(p99),
  }
}

// ─── Sentry Integration ─────────────────────────────────────────────────────

/**
 * Set the trace context on Sentry for cross-referencing.
 */
export function setSentryTraceContext(trace: TraceContext) {
  try {
    import('@/lib/monitoring/sentry').then(({ setUser, addBreadcrumb }) => {
      addBreadcrumb({
        category: 'trace',
        message: `Trace ${trace.traceId}`,
        level: 'info',
        data: { traceId: trace.traceId, spanId: trace.spanId },
      })
    }).catch(() => {})
  } catch {}
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Offline IndexedDB Database Layer
// ──────────────────────────────────────────────────────────────────────────
// Provides persistent offline storage for field book data when surveyors
// work in areas without connectivity (rural Kenya, underground mines, etc).
//
// Stores: observations, stations, measurements, project snapshots
// Syncs: queued entries pushed to server when back online
// ──────────────────────────────────────────────────────────────────────────

import { openDB, IDBPDatabase, DBSchema } from 'idb';

// ─── Schema Definition ───────────────────────────────────────────────────

export interface OfflineObservation {
  id: string;
  surveyId: string;
  projectId: string;
  fromStationId: string;
  toStationId: string;
  rawHorizontalAngle: number | null;
  rawVerticalAngle: number | null;
  rawSlopeDistance: number | null;
  temperature: number | null;
  pressure: number | null;
  humidity: number | null;
  instrumentHeight: number | null;
  targetHeight: number | null;
  edmConstant: number | null;
  ppmSetting: number | null;
  observationDate: string | null;
  createdAt: number;       // epoch ms — when recorded offline
  updatedAt: number;
  synced: boolean;
  syncAttempts: number;
  lastSyncError: string | null;
}

export interface OfflineStation {
  id: string;
  surveyId: string;
  projectId: string;
  name: string;
  type: 'TRAVERSE' | 'CONTROL' | 'BEACON' | 'BENCHMARK';
  order: number;
  createdAt: number;
  synced: boolean;
}

export interface OfflineProjectSnapshot {
  projectId: string;
  data: unknown;
  cachedAt: number;
  expiresAt: number;
}

export interface OfflineMediaAttachment {
