  type: 'beacon_photo' | 'field_sketch' | 'gnss_log';
  blob: Blob;
  filename: string;
  mimeType: string;
  createdAt: number;
  synced: boolean;
}

export interface SyncQueueEntry {
  id: string;
  operation: 'create' | 'update' | 'delete';
  entity: 'observation' | 'station' | 'media';
  entityId: string;
  payload: unknown;
  createdAt: number;
  attempts: number;
  lastError: string | null;
  priority: number; // lower = higher priority
}

interface MetarduOfflineDB extends DBSchema {
  observations: {
    key: string;
    value: OfflineObservation;
    indexes: {
      'by-survey': string;
      'by-project': string;
      'by-synced': number;
      'by-created': number;
    };
  };
  stations: {
    key: string;
    value: OfflineStation;
    indexes: {
      'by-survey': string;
      'by-synced': number;
    };
  };
  cache: {
    key: string;
    value: OfflineProjectSnapshot;
    indexes: {
      'by-expiry': number;
    };
  };
  media: {
    key: string;
    value: OfflineMediaAttachment;
    indexes: {
      'by-observation': string;
      'by-synced': number;
    };
  };
  syncQueue: {
    key: string;
    value: SyncQueueEntry;
    indexes: {
      'by-priority': [number, number]; // [priority, createdAt]
      'by-entity': string;
    };
  };
  meta: {
    key: string;
    value: { key: string; value: unknown };
  };
}

// ─── Database Singleton ──────────────────────────────────────────────────

const DB_NAME = 'metardu-offline';
const DB_VERSION = 2;

let dbInstance: IDBPDatabase<MetarduOfflineDB> | null = null;

export async function getOfflineDB(): Promise<IDBPDatabase<MetarduOfflineDB>> {
  if (dbInstance) return dbInstance;

  dbInstance = await openDB<MetarduOfflineDB>(DB_NAME, DB_VERSION, {
    upgrade(db, oldVersion, newVersion) {
      // ── Version 1: Core stores ──
      if (oldVersion < 1) {
        const obsStore = db.createObjectStore('observations', { keyPath: 'id' });
        obsStore.createIndex('by-survey', 'surveyId');
        obsStore.createIndex('by-project', 'projectId');
        obsStore.createIndex('by-synced', 'synced');
        obsStore.createIndex('by-created', 'createdAt');

        const stationStore = db.createObjectStore('stations', { keyPath: 'id' });
        stationStore.createIndex('by-survey', 'surveyId');
        stationStore.createIndex('by-synced', 'synced');

        const cacheStore = db.createObjectStore('cache', { keyPath: 'projectId' });
        cacheStore.createIndex('by-expiry', 'expiresAt');

        const syncStore = db.createObjectStore('syncQueue', { keyPath: 'id' });
        syncStore.createIndex('by-priority', ['priority', 'createdAt']);
        syncStore.createIndex('by-entity', 'entity');

        db.createObjectStore('meta', { keyPath: 'key' });
      }

      // ── Version 2: Media attachments ──
      if (oldVersion < 2) {
        if (!db.objectStoreNames.contains('media')) {
          const mediaStore = db.createObjectStore('media', { keyPath: 'id' });
          mediaStore.createIndex('by-observation', 'observationId');
          mediaStore.createIndex('by-synced', 'synced');
        }
      }
    },
  });

  return dbInstance;
}

// ─── Cleanup Utilities ───────────────────────────────────────────────────

/**
 * Purge expired cache entries and already-synced data older than maxAgeDays.
 */
export async function purgeStaleData(maxAgeDays: number = 30): Promise<{
  purgedObservations: number;
  purgedCache: number;
  purgedMedia: number;
}> {
  const db = await getOfflineDB();
  const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000;
  let purgedObservations = 0;
  let purgedCache = 0;
  let purgedMedia = 0;

  // Purge synced observations older than cutoff
  const tx = db.transaction(['observations', 'cache', 'media'], 'readwrite');

  const syncedObs = await tx.objectStore('observations').index('by-synced').getAll(IDBKeyRange.bound(0, 1));
  for (const obs of syncedObs) {
    if (obs.synced && obs.createdAt < cutoff) {
      await tx.objectStore('observations').delete(obs.id);
      purgedObservations++;
    }
  }

  // Purge expired cache
  const allCache = await tx.objectStore('cache').index('by-expiry').getAll();
  for (const entry of allCache) {
    if (entry.expiresAt < Date.now()) {
      await tx.objectStore('cache').delete(entry.projectId);
      purgedCache++;
    }
  }

  // Purge synced media older than cutoff
  const syncedMedia = await tx.objectStore('media').index('by-synced').getAll(IDBKeyRange.bound(0, 1));
  for (const m of syncedMedia) {
    if (m.synced && m.createdAt < cutoff) {
      await tx.objectStore('media').delete(m.id);
      purgedMedia++;
    }
  }

  await tx.done;

  return { purgedObservations, purgedCache, purgedMedia };
}

/**
 * Get storage usage estimate (navigator.storage API).
 */
export async function getStorageEstimate(): Promise<{
  usageMB: number;
  quotaMB: number;
  percentUsed: number;
} | null> {
  if (!navigator.storage?.estimate) return null;
  const { usage = 0, quota = 0 } = await navigator.storage.estimate();
  return {
    usageMB: Math.round(usage / 1024 / 1024 * 100) / 100,
    quotaMB: Math.round(quota / 1024 / 1024),
    percentUsed: quota > 0 ? Math.round((usage / quota) * 10000) / 100 : 0,
  };
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Offline Sync Manager
// ──────────────────────────────────────────────────────────────────────────
// Handles:
//   - Queueing field data for offline storage
//   - Background sync when connectivity returns
//   - Conflict detection and resolution
//   - Retry with exponential backoff
//   - Sync status events for UI updates
//
// Usage:
//   const sync = getSyncManager();
//   await sync.saveObservation(observation);  // saves locally + queues sync
//   sync.forceSyncNow();                      // manual sync trigger
//   sync.onStatusChange((status) => { ... }); // listen for status
// ──────────────────────────────────────────────────────────────────────────

import {
  getOfflineDB,
  OfflineObservation,
  OfflineStation,
  SyncQueueEntry,
  type OfflineMediaAttachment,
} from './db';
import { logger } from '@/lib/logger'

// ─── Types ───────────────────────────────────────────────────────────────

export type SyncStatus = 'idle' | 'syncing' | 'error' | 'offline';

export interface SyncState {
  status: SyncStatus;
  pendingCount: number;
  lastSyncAt: number | null;
  lastError: string | null;
  isOnline: boolean;
}

export interface SyncResult {
  synced: number;
  failed: number;
  conflicts: number;
  duration: number;
}

type StatusListener = (state: SyncState) => void;

// ─── Constants ───────────────────────────────────────────────────────────

const MAX_RETRY_ATTEMPTS = 5;
const BASE_RETRY_DELAY_MS = 1000;
const SYNC_DEBOUNCE_MS = 3000;
const BATCH_SIZE = 20;

// ─── Sync Manager Singleton ──────────────────────────────────────────────

class SyncManager {
  private state: SyncState = {
    status: 'idle',
    pendingCount: 0,
    lastSyncAt: null,
    lastError: null,
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
  };

  private listeners: Set<StatusListener> = new Set();
  private syncTimer: ReturnType<typeof setTimeout> | null = null;
  private isSyncing = false;

  constructor() {
    if (typeof window !== 'undefined') {
      // Listen for online/offline events
      window.addEventListener('online', () => this.handleOnline());
      window.addEventListener('offline', () => this.handleOffline());

      // Listen for visibility change (sync when user returns to tab)
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible' && this.state.isOnline) {
          this.scheduleSync();
        }
      });

      // Initial pending count
      this.refreshPendingCount();
    }
  }

  // ─── Public API: Save Data ───────────────────────────────────────────

  /**
   * Save an observation locally and queue for sync.
   */
  async saveObservation(obs: Omit<OfflineObservation, 'synced' | 'syncAttempts' | 'lastSyncError' | 'createdAt' | 'updatedAt'>): Promise<string> {
    const db = await getOfflineDB();
    const now = Date.now();

    const record: OfflineObservation = {
      ...obs,
      createdAt: now,
      updatedAt: now,
      synced: false,
      syncAttempts: 0,
      lastSyncError: null,
    };

    await db.put('observations', record);

    // Queue sync entry
    await this.enqueue({
      operation: 'create',
      entity: 'observation',
      entityId: record.id,
      payload: record,
      priority: 1,
    });

    this.scheduleSync();
    await this.refreshPendingCount();

    return record.id;
  }

  /**
   * Update an existing observation locally and queue for sync.
   */
  async updateObservation(id: string, updates: Partial<OfflineObservation>): Promise<void> {
    const db = await getOfflineDB();
    const existing = await db.get('observations', id);
    if (!existing) throw new Error(`Observation ${id} not found in offline store`);

    const updated: OfflineObservation = {
      ...existing,
      ...updates,
      id, // ensure id is not overwritten
      updatedAt: Date.now(),
      synced: false,
      syncAttempts: 0,
      lastSyncError: null,
    };

    await db.put('observations', updated);

    await this.enqueue({
      operation: 'update',
      entity: 'observation',
      entityId: id,
      payload: updated,
      priority: 1,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  /**
   * Save a station locally and queue for sync.
   */
  async saveStation(station: Omit<OfflineStation, 'synced' | 'createdAt'>): Promise<void> {
    const db = await getOfflineDB();
    const record: OfflineStation = {
      ...station,
      createdAt: Date.now(),
      synced: false,
    };

    await db.put('stations', record);

    await this.enqueue({
      operation: 'create',
      entity: 'station',
      entityId: record.id,
      payload: record,
      priority: 2,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  /**
   * Save a media attachment (photo, sketch) for later sync.
   */
  async saveMedia(media: Omit<OfflineMediaAttachment, 'synced' | 'createdAt'>): Promise<void> {
    const db = await getOfflineDB();
    const record: OfflineMediaAttachment = {
      ...media,
      createdAt: Date.now(),
      synced: false,
    };

    await db.put('media', record);

    await this.enqueue({
      operation: 'create',
      entity: 'media',
      entityId: record.id,
      payload: { ...record, blob: undefined }, // Don't queue blob in sync entry
      priority: 3,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  // ─── Public API: Read Data ───────────────────────────────────────────

  /**
   * Get all unsynced observations for a survey.
   */
  async getUnsyncedObservations(surveyId: string): Promise<OfflineObservation[]> {
    const db = await getOfflineDB();
    const all = await db.getAllFromIndex('observations', 'by-survey', surveyId);
    return all.filter((obs) => !obs.synced);
  }

  /**
   * Get all observations for a survey (both synced and unsynced).
   */
  async getAllObservations(surveyId: string): Promise<OfflineObservation[]> {
    const db = await getOfflineDB();
    return db.getAllFromIndex('observations', 'by-survey', surveyId);
  }

  /**
   * Get a single observation by id.
   */
  async getObservation(id: string): Promise<OfflineObservation | undefined> {
    const db = await getOfflineDB();
    return db.get('observations', id);
  }

  /**
   * Delete an observation locally.
   */
  async deleteObservation(id: string): Promise<void> {
    const db = await getOfflineDB();
    await db.delete('observations', id);

    await this.enqueue({
      operation: 'delete',
      entity: 'observation',
      entityId: id,
      payload: { id },
      priority: 1,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  /**
   * Get the count of pending (unsynced) items.
   */
  async getPendingCount(): Promise<number> {
    const db = await getOfflineDB();
    const queue = await db.getAll('syncQueue');
    return queue.length;
  }

  // ─── Public API: Sync Control ────────────────────────────────────────

  /**
   * Force an immediate sync attempt.
   */
  async forceSyncNow(): Promise<SyncResult> {
    if (this.syncTimer) {
      clearTimeout(this.syncTimer);
      this.syncTimer = null;
    }
    return this.executeSync();
  }

  /**
   * Get current sync state.
   */
  getState(): SyncState {
    return { ...this.state };
  }

  /**
   * Subscribe to sync status changes.
   */
  onStatusChange(listener: StatusListener): () => void {
    this.listeners.add(listener);
    // Emit current state immediately
    listener(this.state);
    return () => this.listeners.delete(listener);
  }

  // ─── Internal: Sync Execution ────────────────────────────────────────

  private async executeSync(): Promise<SyncResult> {
    if (this.isSyncing) {
      return { synced: 0, failed: 0, conflicts: 0, duration: 0 };
    }

    if (!this.state.isOnline) {
      this.updateState({ status: 'offline' });
      return { synced: 0, failed: 0, conflicts: 0, duration: 0 };
    }

    this.isSyncing = true;
    this.updateState({ status: 'syncing', lastError: null });

    const startTime = performance.now();
    let synced = 0;
    let failed = 0;
    let conflicts = 0;

    try {
      const db = await getOfflineDB();

      // Get sync queue sorted by priority
      const queue = await db.getAllFromIndex('syncQueue', 'by-priority');

      // Process in batches
      for (let i = 0; i < queue.length; i += BATCH_SIZE) {
        const batch = queue.slice(i, i + BATCH_SIZE);

        for (const entry of batch) {
          try {
            const result = await this.syncEntry(entry);

            if (result === 'conflict') {
              conflicts++;
              // Keep in queue but mark conflict
              await db.put('syncQueue', {
                ...entry,
                attempts: entry.attempts + 1,
                lastError: 'CONFLICT: Server version differs',
              });
            } else {
              // Success — remove from queue
              await db.delete('syncQueue', entry.id);
              synced++;
            }
          } catch (err) {
            const attempts = entry.attempts + 1;
            const errorMsg = err instanceof Error ? err.message : String(err);

            if (attempts >= MAX_RETRY_ATTEMPTS) {
              // Max retries reached — remove from queue, mark as failed
              await db.delete('syncQueue', entry.id);
              await this.markEntitySyncFailed(entry.entity, entry.entityId, errorMsg);
              failed++;
            } else {
              // Update retry count
              await db.put('syncQueue', {
                ...entry,
                attempts,
                lastError: errorMsg,
              });
              failed++;
            }
          }
        }
      }

      const duration = Math.round(performance.now() - startTime);
      const pendingCount = await this.getPendingCount();

      this.updateState({
        status: 'idle',
        pendingCount,
        lastSyncAt: Date.now(),
        lastError: null,
      });

      return { synced, failed, conflicts, duration };
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      this.updateState({
        status: 'error',
        lastError: errorMsg,
      });
      return { synced, failed, conflicts, duration: Math.round(performance.now() - startTime) };
    } finally {
      this.isSyncing = false;
    }
  }

  /**
   * Sync a single queue entry to the server.
   */
  private async syncEntry(entry: SyncQueueEntry): Promise<'ok' | 'conflict'> {
    const endpoint = this.getEndpoint(entry.entity);
    const method = entry.operation === 'delete' ? 'DELETE' : entry.operation === 'update' ? 'PUT' : 'POST';

    const res = await fetch(endpoint, {
      method,
      headers: {
        'Content-Type': 'application/json',
        'X-Sync-Source': 'offline',
        'X-Sync-Entry-Id': entry.id,
      },
      body: JSON.stringify(entry.payload),
    });

    if (res.status === 409) {
      return 'conflict';
    }

    if (!res.ok) {
      throw new Error(`Sync failed: ${res.status} ${res.statusText}`);
    }

    // Mark entity as synced in local DB
    await this.markEntitySynced(entry.entity, entry.entityId);

    return 'ok';
  }

  private getEndpoint(entity: SyncQueueEntry['entity']): string {
    switch (entity) {
      case 'observation':
        return '/api/sync/observations';
      case 'station':
        return '/api/sync/stations';
      case 'media':
        return '/api/sync/media';
      default:
        throw new Error(`Unknown entity type: ${entity}`);
    }
  }

  private async markEntitySynced(entity: SyncQueueEntry['entity'], entityId: string): Promise<void> {
    const db = await getOfflineDB();

    if (entity === 'observation') {
      const obs = await db.get('observations', entityId);
      if (obs) {
        await db.put('observations', { ...obs, synced: true, lastSyncError: null });
      }
    } else if (entity === 'station') {
      const station = await db.get('stations', entityId);
      if (station) {
        await db.put('stations', { ...station, synced: true });
      }
    } else if (entity === 'media') {
      const media = await db.get('media', entityId);
      if (media) {
        await db.put('media', { ...media, synced: true });
      }
    }
  }

  private async markEntitySyncFailed(entity: SyncQueueEntry['entity'], entityId: string, error: string): Promise<void> {
    const db = await getOfflineDB();

    if (entity === 'observation') {
      const obs = await db.get('observations', entityId);
      if (obs) {
        await db.put('observations', { ...obs, lastSyncError: error });
      }
    }
  }

  // ─── Internal: Queue Management ──────────────────────────────────────

  private async enqueue(entry: Omit<SyncQueueEntry, 'id' | 'createdAt' | 'attempts' | 'lastError'>): Promise<void> {
    const db = await getOfflineDB();
    const record: SyncQueueEntry = {
      ...entry,
      id: `sync_${entry.entity}_${entry.entityId}_${Date.now()}`,
      createdAt: Date.now(),
      attempts: 0,
      lastError: null,
    };
    await db.put('syncQueue', record);
  }

  // ─── Internal: Connectivity ──────────────────────────────────────────

  private handleOnline(): void {
    this.updateState({ isOnline: true, status: 'idle' });
    this.scheduleSync();
  }

  private handleOffline(): void {
    this.updateState({ isOnline: false, status: 'offline' });
    if (this.syncTimer) {
      clearTimeout(this.syncTimer);
      this.syncTimer = null;
    }
  }

  private scheduleSync(): void {
    if (this.syncTimer) {
      clearTimeout(this.syncTimer);
    }
    this.syncTimer = setTimeout(() => {
      this.executeSync();
    }, SYNC_DEBOUNCE_MS);
  }

  // ─── Internal: State Management ──────────────────────────────────────

  private updateState(partial: Partial<SyncState>): void {
    this.state = { ...this.state, ...partial };
    for (const listener of this.listeners) {
      try {
        listener(this.state);
      } catch (err) {
        logger.error('[SyncManager] Listener error:', { error: err });
      }
    }
  }

  private async refreshPendingCount(): Promise<void> {
    try {
      const count = await this.getPendingCount();
      this.updateState({ pendingCount: count });
    } catch {
      // DB might not be available during SSR
    }
  }
}

// ─── Singleton Export ────────────────────────────────────────────────────

let instance: SyncManager | null = null;

export function getSyncManager(): SyncManager {
  if (!instance) {
    instance = new SyncManager();
  }
  return instance;
}

import { useState, useEffect, useCallback } from 'react'
import type { MapExtent } from '@/app/map/MapReactContext'
import { logger } from '@/lib/logger'

interface TileCacheStats {
  cached: number
  total: number
  size: number
}

interface BoundingBox {
  north: number
  south: number
  east: number
  west: number
}

const TILE_SIZE = 256
const DEFAULT_ZOOM_RANGE = [1, 18]

export function useTileCache() {
  const [isOnline, setIsOnline] = useState(true)
  const [cacheStats, setCacheStats] = useState<TileCacheStats>({
    cached: 0,
    total: 0,
    size: 0
  })

  useEffect(() => {
    setIsOnline(navigator.onLine)
    
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)
    
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)
    
    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  const getTileIndexDB = useCallback(async () => {
    return new Promise<IDBDatabase>((resolve, reject) => {
      const request = indexedDB.open('METARDUTileCache', 1)
      
      request.onerror = () => reject(request.error)
      request.onsuccess = () => resolve(request.result)
      
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result
        if (!db.objectStoreNames.contains('tiles')) {
          db.createObjectStore('tiles', { keyPath: 'url' })
        }
        if (!db.objectStoreNames.contains('metadata')) {
          db.createObjectStore('metadata', { keyPath: 'key' })
        }
      }
    })
  }, [])

  const cacheTile = useCallback(async (url: string, blob: Blob) => {
    try {
      const db = await getTileIndexDB()
      const tx = db.transaction('tiles', 'readwrite')
      const store = tx.objectStore('tiles')
      
      await new Promise((resolve, reject) => {
        const request = store.put({ url, blob, timestamp: Date.now() })
        request.onsuccess = resolve
        request.onerror = () => reject(request.error)
      })
    } catch (error) {
      logger.error('Failed to cache tile:', { error: error })
    }
  }, [getTileIndexDB])

  const getCachedTile = useCallback(async (url: string): Promise<Blob | null> => {
    try {
      const db = await getTileIndexDB()
      const tx = db.transaction('tiles', 'readonly')
      const store = tx.objectStore('tiles')
      
      return new Promise((resolve) => {
        const request = store.get(url)
        request.onsuccess = () => {
          if (request.result) {
            resolve((request.result as { blob: Blob }).blob)
          } else {
            resolve(null)
          }
        }
        request.onerror = () => resolve(null)
      })
    } catch {
      return null
    }
  }, [getTileIndexDB])

  const getTileUrl = useCallback((server: string, z: number, x: number, y: number): string => {
    return server
      .replace('{z}', z.toString())
      .replace('{x}', x.toString())
      .replace('{y}', y.toString())
  }, [])

  const preCacheArea = useCallback(async (
    bounds: BoundingBox,
    zoomRange: number[] = DEFAULT_ZOOM_RANGE,
    tileServers: string[] = [
      'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
      'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'
    ]
  ) => {
    if (!isOnline) return
    
    const cached: string[] = []
    
    for (let z = zoomRange[0]; z <= zoomRange[1]; z++) {
      const minX = Math.floor((bounds.west + 180) / 360 * Math.pow(2, z))
      const maxX = Math.floor((bounds.east + 180) / 360 * Math.pow(2, z))
      const minY = Math.floor((90 - bounds.north) / 180 * Math.pow(2, z))
      const maxY = Math.floor((90 - bounds.south) / 180 * Math.pow(2, z))
      
      for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
          for (const server of tileServers) {
            const url = getTileUrl(server, z, x, y)
            
            const existing = await getCachedTile(url)
            if (!existing) {
              try {
                const response = await fetch(url, { mode: 'cors' })
                if (response.ok) {
                  const blob = await response.blob()
                  await cacheTile(url, blob)
                  cached.push(url)
                }
              } catch {
                // Skip failed tiles
              }
            }
          }
        }
      }
    }
    
    return cached.length
  }, [isOnline, getTileUrl, getCachedTile, cacheTile])

  const clearCache = useCallback(async () => {
    try {
      const db = await getTileIndexDB()
      const tx = db.transaction('tiles', 'readwrite')
      const store = tx.objectStore('tiles')
      
      await new Promise((resolve, reject) => {
        const request = store.clear()
        request.onsuccess = resolve
        request.onerror = () => reject(request.error)
      })
      
      setCacheStats({ cached: 0, total: 0, size: 0 })
    } catch (error) {
      logger.error('Failed to clear cache:', { error: error })
    }
  }, [getTileIndexDB])

  const getCacheSize = useCallback(async () => {
    try {
      const db = await getTileIndexDB()
      const tx = db.transaction('tiles', 'readonly')
      const store = tx.objectStore('tiles')
      
      return new Promise((resolve) => {
        const request = store.count()
        request.onsuccess = () => {
          setCacheStats(prev => ({ ...prev, cached: request.result }))
          resolve(request.result)
        }
        request.onerror = () => resolve(0)
      })
    } catch {
      return 0
    }
  }, [getTileIndexDB])

  useEffect(() => {
    getCacheSize()
  }, [getCacheSize])

  return {
    isOnline,
    cacheStats,
    preCacheArea,
    clearCache,
    getCacheSize,
    getCachedTile,
    cacheTile
  }
}

export function calculateTileBounds(
  north: number,
  south: number,
  east: number,
  west: number,
  zoom: number
): { minX: number; maxX: number; minY: number; maxY: number } {
  const minX = Math.floor((west + 180) / 360 * Math.pow(2, zoom))
  const maxX = Math.floor((east + 180) / 360 * Math.pow(2, zoom))
  const minY = Math.floor((90 - north) / 180 * Math.pow(2, zoom))
  const maxY = Math.floor((90 - south) / 180 * Math.pow(2, zoom))
  
  return { minX, maxX, minY, maxY }
}

/** Count the total tiles for a bounding box across a zoom range.
 *  Accepts the shared MapExtent shape (minLat, maxLat, minLon, maxLon). */
export function calculateTileCount(
  bounds: MapExtent,
  minZoom: number,
  maxZoom: number
): { total: number } {
  let total = 0
  for (let z = minZoom; z <= maxZoom; z++) {
    const tileBounds = calculateTileBounds(bounds.maxLat, bounds.minLat, bounds.maxLon, bounds.minLon, z)
    total += (tileBounds.maxX - tileBounds.minX + 1) * (tileBounds.maxY - tileBounds.minY + 1)
  }
  return { total }
}

/** Estimate storage in bytes for a given number of tiles.
 *  The second argument is the source type (string), used to vary average tile size. */
export function estimateStorageSize(tileCount: number, sourceType?: string): number {
  const avgTileBytes = sourceType === 'satellite' ? 40000 : 15000
  return tileCount * avgTileBytes
}

/** Download progress callback type — matches what the UI component expects */
export interface DownloadProgress {
  total: number
  downloaded: number
  skipped: number
  failed: number
  bytesDownloaded: number
  currentZoom: number
  percent: number
}

/** Download tiles for a bounding box range.
 *  Accepts the shared MapExtent shape (minLat, maxLat, minLon, maxLon).
 *  Returns a DownloadProgress-shaped result so callers can feed it directly to setState.
 *
 *  Real implementation: fetches tiles from the tile server, stores as blobs in IndexedDB.
 */
export async function downloadTilesForBounds(
  sourceId: string,
  url: string,
  bounds: MapExtent,
  minZoom: number,
  maxZoom: number,
  _type: string,
  onProgress: (progress: DownloadProgress) => void,
  signal?: AbortSignal,
): Promise<DownloadProgress> {
  const { total } = calculateTileCount(bounds, minZoom, maxZoom)
  let downloaded = 0
  let skipped = 0
  let failed = 0
  let bytesDownloaded = 0

  // Open IndexedDB
  let db: IDBDatabase
  try {
    db = await new Promise<IDBDatabase>((resolve, reject) => {
      const req = indexedDB.open('METARDUTileCache', 1)
      req.onerror = () => reject(req.error)
      req.onsuccess = () => resolve(req.result)
      req.onupgradeneeded = (event) => {
        const d = (event.target as IDBOpenDBRequest).result
        if (!d.objectStoreNames.contains('tiles')) d.createObjectStore('tiles', { keyPath: 'url' })
        if (!d.objectStoreNames.contains('metadata')) d.createObjectStore('metadata', { keyPath: 'key' })
      }
    })
  } catch {
    return { total, downloaded: 0, skipped: 0, failed: total, bytesDownloaded: 0, currentZoom: minZoom, percent: 0 }
  }

  // Helper: cache a tile
  const cacheTile = async (tileUrl: string, blob: Blob) => {
    return new Promise<void>((resolve) => {
      const tx = db.transaction('tiles', 'readwrite')
      const store = tx.objectStore('tiles')
      const req = store.put({ url: tileUrl, blob, timestamp: Date.now(), sourceId })
      req.onsuccess = () => resolve()
      req.onerror = () => resolve()
    })
  }

  // Helper: check if tile is already cached
  const isCached = async (tileUrl: string): Promise<boolean> => {
    return new Promise<boolean>((resolve) => {
      const tx = db.transaction('tiles', 'readonly')
      const store = tx.objectStore('tiles')
      const req = store.get(tileUrl)
      req.onsuccess = () => resolve(!!req.result)
      req.onerror = () => resolve(false)
    })
  }

  for (let z = minZoom; z <= maxZoom; z++) {
    const tileBounds = calculateTileBounds(bounds.maxLat, bounds.minLat, bounds.maxLon, bounds.minLon, z)

    for (let x = tileBounds.minX; x <= tileBounds.maxX; x++) {
      for (let y = tileBounds.minY; y <= tileBounds.maxY; y++) {
        if (signal?.aborted) {
          return { total, downloaded, skipped, failed, bytesDownloaded, currentZoom: z, percent: Math.round(((downloaded + skipped) / total) * 100) }
        }

        const tileUrl = url
          .replace('{z}', String(z))
          .replace('{x}', String(x))
          .replace('{y}', String(y))
          .replace('{s}', ['a', 'b', 'c'][Math.abs(x + y) % 3])

        // Check cache first
        if (await isCached(tileUrl)) {
          skipped++
        } else {
          try {
            const response = await fetch(tileUrl, { mode: 'cors', signal })
            if (response.ok) {
              const blob = await response.blob()
              await cacheTile(tileUrl, blob)
              bytesDownloaded += blob.size
              downloaded++
            } else {
              failed++
            }
          } catch {
            failed++
          }
        }

        // Report progress every 10 tiles
        if ((downloaded + skipped + failed) % 10 === 0) {
          onProgress({
            total,
            downloaded,
            skipped,
            failed,
            bytesDownloaded,
            currentZoom: z,
            percent: Math.round(((downloaded + skipped) / total) * 100),
          })
        }
      }
    }
  }

  const finalProgress: DownloadProgress = {
    total,
    downloaded,
    skipped,
    failed,
    bytesDownloaded,
    currentZoom: maxZoom,
    percent: Math.round(((downloaded + skipped) / total) * 100),
  }
  onProgress(finalProgress)
  return finalProgress
}

/** Information about a cached tile source — matches what the UI manager expects */
export interface CachedSourceInfo {
  sourceId: string
  stats: {
    count: number
    sizeBytes: number
    newestTimestamp: number
  }
}

/** List all cached tile sources by scanning IndexedDB */
export async function listCachedSources(): Promise<CachedSourceInfo[]> {
  try {
    const db = await new Promise<IDBDatabase>((resolve, reject) => {
      const req = indexedDB.open('METARDUTileCache', 1)
      req.onerror = () => reject(req.error)
      req.onsuccess = () => resolve(req.result)
      req.onupgradeneeded = (event) => {
        const d = (event.target as IDBOpenDBRequest).result
        if (!d.objectStoreNames.contains('tiles')) d.createObjectStore('tiles', { keyPath: 'url' })
        if (!d.objectStoreNames.contains('metadata')) d.createObjectStore('metadata', { keyPath: 'key' })
      }
    })

    return new Promise<CachedSourceInfo[]>((resolve) => {
      const tx = db.transaction('tiles', 'readonly')
      const store = tx.objectStore('tiles')
      const req = store.getAll()

      req.onsuccess = () => {
        const tiles = req.result as Array<{ url: string; blob: Blob; timestamp: number; sourceId?: string }>
        const sourceMap = new Map<string, { count: number; sizeBytes: number; newestTimestamp: number }>()

        for (const tile of tiles) {
          const sid = tile.sourceId || 'unknown'
          const existing = sourceMap.get(sid) || { count: 0, sizeBytes: 0, newestTimestamp: 0 }
          existing.count++
          existing.sizeBytes += tile.blob?.size || 0
          existing.newestTimestamp = Math.max(existing.newestTimestamp, tile.timestamp || 0)
          sourceMap.set(sid, existing)
        }

        resolve(Array.from(sourceMap.entries()).map(([sourceId, stats]) => ({ sourceId, stats })))
      }
      req.onerror = () => resolve([])
    })
  } catch {
    return []
  }
}

/** Delete cached tiles for a specific source */
export async function deleteCachedTiles(sourceId: string): Promise<void> {
  try {
    const db = await new Promise<IDBDatabase>((resolve, reject) => {
      const req = indexedDB.open('METARDUTileCache', 1)
      req.onerror = () => reject(req.error)
      req.onsuccess = () => resolve(req.result)
    })

    const tx = db.transaction('tiles', 'readwrite')
    const store = tx.objectStore('tiles')
    const cursorReq = store.openCursor()

    await new Promise<void>((resolve) => {
      cursorReq.onsuccess = () => {
        const cursor = cursorReq.result
        if (cursor) {
          if ((cursor.value as { sourceId: string }).sourceId === sourceId) {
            cursor.delete()
          }
          cursor.continue()
        } else {
          resolve()
        }
      }
      cursorReq.onerror = () => resolve()
    })
  } catch {
    // ignore
  }
}

/** Clear all tile cache */
export async function clearAllTileCache(): Promise<void> {
  try {
    const db = await new Promise<IDBDatabase>((resolve, reject) => {
      const req = indexedDB.open('METARDUTileCache', 1)
      req.onerror = () => reject(req.error)
      req.onsuccess = () => resolve(req.result)
    })

    const tx = db.transaction('tiles', 'readwrite')
    const store = tx.objectStore('tiles')

    await new Promise<void>((resolve) => {
      const req = store.clear()
      req.onsuccess = () => resolve()
      req.onerror = () => resolve()
    })
  } catch {
    // ignore
  }
}

/** Get a cached tile blob by URL — used by custom tileLoadFunction for offline basemaps */
export async function getCachedTileBlob(url: string): Promise<Blob | null> {
  try {
    const db = await new Promise<IDBDatabase>((resolve, reject) => {
      const req = indexedDB.open('METARDUTileCache', 1)
      req.onerror = () => reject(req.error)
      req.onsuccess = () => resolve(req.result)
    })

    return new Promise<Blob | null>((resolve) => {
      const tx = db.transaction('tiles', 'readonly')
      const store = tx.objectStore('tiles')
      const req = store.get(url)
      req.onsuccess = () => resolve((req.result as { blob: Blob } | undefined)?.blob || null)
      req.onerror = () => resolve(null)
    })
  } catch {
    return null
  }
}

/**
 * Weather & EDM Corrections Service
 * Phase 7 - Online Power Features
 * Real-time atmospheric corrections for EDM measurements
 */

export interface WeatherData {
  temperature: number
  pressure: number
  humidity: number
  elevation?: number
}

export interface EDMCorrection {
  ppm: number
  description: string
}

export interface WeatherResult {
  temperature: number
  pressure: number
  humidity: number
  elevation?: number
  edmCorrection: EDMCorrection
  atmosphericCondition: 'normal' | 'humid' | 'dry'
  recommendations: string[]
}

const ATMOSPHERIC_REFRACTIVE_INDEX = 281.85
const WATER_VAPOR_CONSTANT = 0.0024

export function calculateEDMCorrection(weather: WeatherData): WeatherResult {
  const { temperature, pressure, humidity, elevation } = weather
  
  const tempK = temperature + 273.15
  
  const saturationVaporPressure = 6.1094 * Math.exp((17.625 * temperature) / (temperature + 243.04))
  const actualVaporPressure = (humidity / 100) * saturationVaporPressure
  
  const refractiveIndex = (ATMOSPHERIC_REFRACTIVE_INDEX / tempK) * (pressure - 0.000378 * actualVaporPressure) + (WATER_VAPOR_CONSTANT * actualVaporPressure / tempK)
  
  const ppm = (refractiveIndex - 1) * 1e6
  
  let condition: 'normal' | 'humid' | 'dry' = 'normal'
  if (humidity > 80) condition = 'humid'
  else if (humidity < 30 || temperature > 40) condition = 'dry'
  
  const recommendations: string[] = []
  
  if (Math.abs(ppm) > 50) {
    recommendations.push('Extreme atmospheric conditions - consider rescheduling measurements')
  }
  
  if (temperature > 35) {
    recommendations.push('High temperature may cause thermal refraction - use multiple observations')
  }
  
  if (humidity > 85) {
    recommendations.push('High humidity affects signal quality - verify instrument settings')
  }
  
  if (elevation !== undefined && elevation > 2000) {
    recommendations.push('High altitude - standard ppm may need adjustment')
  }
  
  if (Math.abs(ppm) > 30 && Math.abs(ppm) <= 50) {
    recommendations.push('Moderate atmospheric correction applied')
  }
  
  recommendations.push(`Apply ${ppm.toFixed(1)} ppm correction to all distances`)
  
  return {
    temperature,
    pressure,
    humidity,
    elevation,
    edmCorrection: {
      ppm: Math.round(ppm * 10) / 10,
      description: `Atmospheric correction: ${ppm.toFixed(1)} ppm`
    },
    atmosphericCondition: condition,
    recommendations
  }
}

export function getRecommendedPPM(temperature: number, pressure: number): number {
  const tempK = temperature + 273.15
  const result = calculateEDMCorrection({ temperature, pressure, humidity: 50 })
  return result.edmCorrection.ppm
}

export interface ScaleCorrection {
  factor: number
  description: string
}

export function calculateScaleCorrection(
  elevation: number,
  latitude: number
): ScaleCorrection {
  const earthRadius = 6371000
  const scaleFactor = 1 + (elevation / earthRadius) + (Math.pow(latitude * Math.PI / 180, 2) / 2)
  
  return {
    factor: Math.round(scaleFactor * 1e8) / 1e8,
    description: `Height above sea level scale correction: ${((scaleFactor - 1) * 1e6).toFixed(2)} ppm`
  }
}

export function combinedEDMCorrection(
  measuredDistance: number,
  weather: WeatherData,
  elevation?: number,
  latitude?: number
): number {
  const weatherResult = calculateEDMCorrection(weather)
  let corrected = measuredDistance * (1 + weatherResult.edmCorrection.ppm / 1e6)
  
  if (elevation !== undefined && latitude !== undefined) {
    const scale = calculateScaleCorrection(elevation, latitude)
    corrected *= scale.factor
  }
  
  return corrected
}

export function getWeatherDescription(condition: 'normal' | 'humid' | 'dry'): string {
  switch (condition) {
    case 'humid':
      return 'High humidity conditions - expect possible signal attenuation'
    case 'dry':
      return 'Dry conditions - ensure adequate signal return'
    default:
      return 'Normal atmospheric conditions - optimal for surveying'
  }
}

export function estimateAccuracy(
  distance: number,
  weather: WeatherData,
  instrumentAccuracy: number = 3
): { estimatedError: number; confidence: string } {
  const correction = calculateEDMCorrection(weather)
  const ppmError = Math.abs(correction.edmCorrection.ppm) * distance / 1e6
  
  const totalError = Math.sqrt(Math.pow(instrumentAccuracy, 2) + Math.pow(ppmError * 1000, 2))
  
  let confidence: string
  if (totalError < 5) confidence = 'High'
  else if (totalError < 15) confidence = 'Medium'
  else confidence = 'Low'
  
  return {
    estimatedError: Math.round(totalError * 100) / 100,
    confidence
  }
}

import type { SurveyDataset, SurveyObservation } from '../workflows/workflowEngine'
import { detectSurveyType } from './surveyDetector'

export interface CSVInterpretResult {
  ok: boolean
  dataset?: SurveyDataset
  error?: string
  warnings: string[]
}

export function interpretCSV(csvText: string): CSVInterpretResult {
  const warnings: string[] = []
  
  try {
    const lines = csvText.trim().split('\n').filter((l) => l.trim())
    if (lines.length < 2) {
      return { ok: false, error: 'File must have headers and at least one row', warnings }
    }
    
    // Parse headers
    const headers = lines[0].split(',').map((h) => h.trim())
    
    // Parse rows
    const rows = lines.slice(1).map((line) => {
      const values = line.split(',')
      const row: Record<string, string> = {}
      headers.forEach((h, i) => {
        row[h] = (values[i] || '').trim()
      })
      return row
    })
    
    // Detect survey type
    const surveyType = detectSurveyType(headers, rows)
    
    if (surveyType === 'unknown') {
      warnings.push('Could not auto-detect survey type. Check column headers.')
    }
    
    // Build observations. For multi-measurement rows, value1/value2 must map to
    // the workflow engine's expectations rather than the first numeric cell.
    const observations = rows.map((row, i) => {
      const values = valuesForSurveyType(row, headers, surveyType)

      return {
        id: `obs_${i}`,
        station: pick(row, ['Station', 'station', 'Point', 'point', 'From', 'from']) || `P${i + 1}`,
        target: pick(row, ['Target', 'target', 'To', 'to']),
        type: mapRowToType(row, headers, surveyType),
        value1: values.value1,
        value2: values.value2,
        value3: values.value3,
      }
    })
    
    // Extract metadata
    const metadata: SurveyDataset['metadata'] = {}
    if (headers.includes('Station') || headers.includes('station')) {
      metadata.station = rows[0]?.['Station'] || rows[0]?.['station']
    }
    
    return {
      ok: true,
      dataset: { 
        surveyType, 
        observations,
        metadata 
      },
      warnings
    }
    
  } catch (err) {
    return { ok: false, error: 'Failed to parse CSV file', warnings }
  }
}

function pick(row: Record<string, string>, keys: string[]): string | undefined {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== '') return row[key]
  }
  return undefined
}

function readNumber(row: Record<string, string>, keys: string[], fallback = 0): number {
  const raw = pick(row, keys)
  if (raw === undefined) return fallback
  const n = parseFloat(raw)
  return Number.isFinite(n) ? n : fallback
}

function readOptionalNumber(row: Record<string, string>, keys: string[]): number | undefined {
  const raw = pick(row, keys)
  if (raw === undefined) return undefined
  const n = parseFloat(raw)
  return Number.isFinite(n) ? n : undefined
}

function valuesForSurveyType(
  row: Record<string, string>,
  headers: string[],
  surveyType: SurveyDataset['surveyType']
) {
  if (surveyType === 'traverse') {
    return {
      value1: readNumber(row, ['Bearing', 'bearing', 'WCB', 'wcb', 'Azimuth', 'azimuth']),
      value2: readNumber(row, ['Distance', 'distance', 'Length', 'length']),
    }
  }

  if (surveyType === 'radiation') {
    return {
      value1: readNumber(row, ['Bearing', 'bearing', 'Angle', 'angle', 'WCB', 'wcb', 'Azimuth', 'azimuth']),
      value2: readNumber(row, ['Distance', 'distance', 'Length', 'length']),
      value3: readOptionalNumber(row, ['VerticalAngle', 'verticalAngle', 'VA', 'va']),
    }
  }

  if (surveyType === 'leveling') {
    return {
      value1: readNumber(row, ['BS', 'bs', 'IS', 'is', 'FS', 'fs']),
    }
  }

  if (surveyType === 'coordinates') {
    return {
      value1: readNumber(row, ['Easting', 'easting', 'X', 'x']),
      value2: readNumber(row, ['Northing', 'northing', 'Y', 'y']),
      value3: readOptionalNumber(row, ['Elevation', 'elevation', 'RL', 'rl']),
    }
  }

  const firstNumeric = Object.values(row).find((v) => !isNaN(parseFloat(v)))
  return { value1: parseFloat(firstNumeric || '0') }
}

function mapRowToType(
  row: Record<string, string>,
  headers: string[],
  surveyType: SurveyDataset['surveyType']
): SurveyObservation['type'] {
  const h = headers.map((h) => h.toLowerCase())
  if (surveyType === 'traverse') return 'BEARING'
  if (surveyType === 'radiation') return h.includes('bearing') || h.includes('wcb') || h.includes('azimuth') ? 'BEARING' : 'ANGLE'
  if (surveyType === 'coordinates') return 'COORDINATE'
  if (h.includes('bs') && row['BS']) return 'BS'
  if (h.includes('fs') && row['FS']) return 'FS'
  if (h.includes('is') && row['IS']) return 'IS'
  if (h.includes('bearing')) return 'BEARING'
  if (h.includes('angle')) return 'ANGLE'
  if (h.includes('distance')) return 'DISTANCE'
  return 'COORDINATE'
}

import type { ParsedInput, ExtractedBuildingData, ExtractedWall, ExtractedFloor, BoundingBox2D, ExtractedAnnotation } from './types'
import { calculateConfidence } from './fileRouter'

export async function parseGLTFFile(file: File): Promise<ParsedInput> {
  try {
    const THREE = await import('three')
    const { GLTFLoader } = await import('three/examples/jsm/loaders/GLTFLoader.js')

    const arrayBuffer = await file.arrayBuffer()
    const loader = new GLTFLoader()

    return new Promise((resolve) => {
      loader.parse(arrayBuffer, '', (gltf) => {
        const scene = gltf.scene
        const box = new THREE.Box3().setFromObject(scene)
        const size = box.getSize(new THREE.Vector3())
        const center = box.getCenter(new THREE.Vector3())

        const boundingBox: BoundingBox2D = {
          minEasting: center.x - size.x / 2,
          maxEasting: center.x + size.x / 2,
          minNorthing: center.y - size.y / 2,
          maxNorthing: center.y + size.y / 2,
        }

        const floors = Math.ceil(size.z / 3)
        const extractedFloors: ExtractedFloor[] = []
        
        for (let i = 0; i < Math.max(1, floors); i++) {
          extractedFloors.push({
            id: `floor_${i}`,
            level: i,
            name: i === 0 ? 'Ground Floor' : `Floor ${i}`,
            elevation: i * 3,
            boundingBox,
          })
        }

        const walls: ExtractedWall[] = []
        scene.traverse((child) => {
          const mesh = child as InstanceType<typeof THREE['Mesh']>
          if (mesh.isMesh) {
            const geom = mesh.geometry
            if (geom?.boundingBox) {
              const meshBox = new THREE.Box3().copy(geom.boundingBox)
              const position = mesh.position
              
              const width = meshBox.max.x - meshBox.min.x
              const height = meshBox.max.z - meshBox.min.z
              
              if (width > 0.1 && height > 2) {
                walls.push({
                  id: `wall_${walls.length}`,
                  type: 'unknown',
                  startPoint: { easting: position.x + meshBox.min.x, northing: position.z + meshBox.min.z },
                  endPoint: { easting: position.x + meshBox.max.x, northing: position.z + meshBox.max.z },
                  thickness: 0.2,
                  height: height,
                  level: Math.floor(position.y / 3),
                })
              }
            }
          }
        })

        const building: ExtractedBuildingData = {
          floors: extractedFloors,
          walls,
          rooms: [],
          doors: [],
          windows: [],
          columns: [],
          beams: [],
          annotations: [],
          boundingBox,
          metadata: {
            units: 'meters',
            projectName: file.name.replace(/\.[^/.]+$/, ''),
          },
        }

        const confidence = calculateConfidence(building) * 0.75

        resolve({
          type: 'GLTF',
          sourceFileName: file.name,
          sourceFileSize: file.size,
          sourceFileLastModified: file.lastModified,
          parsedAt: new Date().toISOString(),
          version: '1.0.0',
          building,
          errors: [],
          warnings: ['3D model geometry extracted. For full semantic analysis, use AI enhancement.'],
          confidence,
        })
      }, (error) => {
        resolve({
          type: 'GLTF',
          sourceFileName: file.name,
          sourceFileSize: file.size,
          sourceFileLastModified: file.lastModified,
          parsedAt: new Date().toISOString(),
          version: '1.0.0',
          errors: [`GLTF parse error: ${error}`],
          warnings: [],
          confidence: 0,
        })
      })
    })
  } catch (error) {
    return {
      type: 'GLTF',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      errors: [error instanceof Error ? error.message : 'GLTF parsing failed'],
      warnings: ['Ensure three.js is installed and GLTFLoader is available'],
      confidence: 0,
    }
  }
}

export async function parseOBJFile(file: File): Promise<ParsedInput> {
  try {
    const content = await file.text()
    const lines = content.split('\n')
    
    const vertices: number[] = []
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, minZ = Infinity, maxZ = -Infinity

    for (const line of lines) {
      const parts = line.trim().split(/\s+/)
      if (parts[0] === 'v' && parts.length >= 4) {
        const x = parseFloat(parts[1])
        const y = parseFloat(parts[2])
        const z = parseFloat(parts[3])
        vertices.push(x, y, z)
        
        if (x < minX) minX = x
        if (x > maxX) maxX = x
        if (y < minY) minY = y
        if (y > maxY) maxY = y
        if (z < minZ) minZ = z
        if (z > maxZ) maxZ = z
      }
    }

    const boundingBox: BoundingBox2D = minX === Infinity
      ? { minEasting: 0, maxEasting: 10, minNorthing: 0, maxNorthing: 10 }
      : { minEasting: minX, maxEasting: maxX, minNorthing: minZ, maxNorthing: maxZ }

    const floors = Math.ceil((maxY - minY) / 3)
    const extractedFloors: ExtractedFloor[] = []
    
    for (let i = 0; i < Math.max(1, floors); i++) {
      extractedFloors.push({
        id: `floor_${i}`,
        level: i,
        name: i === 0 ? 'Ground Floor' : `Floor ${i}`,
        elevation: minY + i * 3,
        boundingBox,
      })
    }

    const building: ExtractedBuildingData = {
      floors: extractedFloors,
      walls: [],
      rooms: [],
      doors: [],
      windows: [],
      columns: [],
      beams: [],
      annotations: [],
      boundingBox,
      metadata: {
        units: 'meters',
        projectName: file.name.replace(/\.[^/.]+$/, ''),
      },
    }

    const confidence = 0.5

    return {
      type: 'OBJ',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      building,
      errors: [],
      warnings: ['OBJ is mesh-only format. No semantic wall/room data available.'],
      confidence,
    }
  } catch (error) {
    return {
      type: 'OBJ',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      errors: [error instanceof Error ? error.message : 'OBJ parsing failed'],
      warnings: [],
      confidence: 0,
    }
  }
}

import { SurveyDataset } from '../workflows/workflowEngine'

export function detectSurveyType(
  headers: string[], 
  rows: Record<string, string>[]
): SurveyDataset['surveyType'] {
  
  const h = headers.map((h) => h.toLowerCase().trim())
  
  // Leveling detection
  if (h.includes('bs') || h.includes('fs') || h.includes('is')) {
    return 'leveling'
  }
  
  // Traverse detection  
  if (
    (h.includes('bearing') || h.includes('wcb')) && 
    (h.includes('distance') || h.includes('length'))
  ) {
    return 'traverse'
  }
  
  // Radiation detection
  if (
    h.includes('angle') && h.includes('distance') &&
    !h.includes('bearing')
  ) {
    return 'radiation'
  }
  
  // Coordinate data
  if (h.includes('easting') && h.includes('northing')) {
    return 'coordinates'
  }
  
  return 'unknown'
}

/**
 * METARDU — Contour SVG Renderer
 * Renders contour lines from Python engine output (/api/compute/contours)
 * into SVG elements for the topographic plan.
 *
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed. (Pearson 2021), Chapter 17
 *         Survey of Kenya — Standard Symbols for Topographic Plans
 *
 * Line weight levels (Brief 12):
 *   INDEX contour   → 0.35mm stroke (heavy)
 *   FORM contour    → 0.18mm stroke (light)
 *   Spot heights    → 0.13mm text
 *   Formline        → 0.13mm dashed (supplementary half-interval)
 */

// Contour types - Python API returns { contours: ContourLine[], spotHeights: SpotHeight[], interval: number }
interface ContourLine {
  elevation: number
  isIndex: boolean
  points: Array<{ x: number; y: number }>
}

export interface SpotHeight {
  x: number
  y: number
  z: number
  label?: string
}

export interface ContourResult {
  interval_m: number
  extent?: {
    x_min: number
    x_max: number
    y_min: number
    y_max: number
  }
  contours: Array<{
    elevation: number
    is_index: boolean
    segments: Segment[]
  }>
  spot_heights: SpotHeight[]
}

// ─────────────────────────────────────────────────────────────────────────────
// LINE WEIGHT CONSTANTS — Brief 12
// Source: Survey of Kenya Topographic Plan Standards
// Four levels as specified
// ─────────────────────────────────────────────────────────────────────────────

export const LINE_WEIGHTS = {
  INDEX_CONTOUR:  0.35,   // mm — every 5th contour, labelled
  FORM_CONTOUR:   0.18,   // mm — intermediate contours
  FORMLINE:       0.13,   // mm — supplementary (dashed, half-interval)
  SPOT_HEIGHT:    0.13,   // mm — spot height text and tick mark
  BOUNDARY:       0.50,   // mm — survey/property boundary
  ROAD:           0.25,   // mm — road/track
  WATER:          0.20,   // mm — watercourse / drainage
  BUILDING:       0.25,   // mm — structure outline
} as const;

// px per mm at standard plan scale (1:1000 default, 96 dpi)
// Adjust scaleFactor when rendering at different plan scales
function mmToPx(mm: number, scaleFactor = 1): number {
  return mm * 3.7795275591 * scaleFactor;
}

// ─────────────────────────────────────────────────────────────────────────────
// WORLD → SVG COORDINATE TRANSFORM
// ─────────────────────────────────────────────────────────────────────────────

export interface ViewTransform {
  x_min: number;
  x_max: number;
  y_min: number;
  y_max: number;
  svg_width: number;
  svg_height: number;
  margin: number;
}

export function worldToSvg(
  wx: number,
  wy: number,
  t: ViewTransform
): [number, number] {
  const usable_w = t.svg_width  - 2 * t.margin;
  const usable_h = t.svg_height - 2 * t.margin;
  const world_w  = t.x_max - t.x_min;
  const world_h  = t.y_max - t.y_min;

  const sx = t.margin + ((wx - t.x_min) / world_w) * usable_w;
  // SVG Y-axis is inverted relative to survey Y (North = up)
  const sy = t.margin + ((t.y_max - wy) / world_h) * usable_h;

  return [sx, sy];
}

// ─────────────────────────────────────────────────────────────────────────────
// SEGMENT CHAIN BUILDER
// Joins adjacent segments into polylines (chains) for cleaner SVG output
// and correct label placement.
// ─────────────────────────────────────────────────────────────────────────────

type Segment = [[number, number], [number, number]];
type Chain   = [number, number][];

function buildChains(segments: Segment[]): Chain[] {
  if (!segments.length) return [];

  // Build adjacency: endpoint → segment index
  const tolerance = 1e-4;

  const chains: Chain[] = [];
  const used = new Set<number>();

  for (let start = 0; start < segments.length; start++) {
    if (used.has(start)) continue;

    const chain: Chain = [...segments[start]];
    used.add(start);

    let extended = true;
    while (extended) {
      extended = false;
      const tail = chain[chain.length - 1];

      for (let i = 0; i < segments.length; i++) {
        if (used.has(i)) continue;
        const [a, b] = segments[i];

        if (Math.abs(a[0] - tail[0]) < tolerance && Math.abs(a[1] - tail[1]) < tolerance) {
          chain.push(b);
          used.add(i);
          extended = true;
          break;
        }
        if (Math.abs(b[0] - tail[0]) < tolerance && Math.abs(b[1] - tail[1]) < tolerance) {
          chain.push(a);
          used.add(i);
          extended = true;
          break;
        }
      }
    }
    chains.push(chain);
  }

  return chains;
}

// ─────────────────────────────────────────────────────────────────────────────
// CONTOUR LABEL PLACEMENT
// Places elevation label at the midpoint of the longest chain segment.
// Source: Ghilani & Wolf Ch.17 — contour labelling conventions
// ─────────────────────────────────────────────────────────────────────────────

function contourLabelPath(chain: Chain, t: ViewTransform): { x: number; y: number; angle: number } | null {
  if (chain.length < 2) return null;

  // Find the longest segment in the chain for label placement
  let maxLen = 0;
  let bestIdx = 0;

  for (let i = 0; i < chain.length - 1; i++) {
    const [ax, ay] = worldToSvg(chain[i][0],   chain[i][1],   t);
    const [bx, by] = worldToSvg(chain[i+1][0], chain[i+1][1], t);
    const len = Math.hypot(bx - ax, by - ay);
    if (len > maxLen) { maxLen = len; bestIdx = i; }
  }

  if (maxLen < 40) return null; // Too short to label

  const [ax, ay] = worldToSvg(chain[bestIdx][0],   chain[bestIdx][1],   t);
  const [bx, by] = worldToSvg(chain[bestIdx+1][0], chain[bestIdx+1][1], t);

  const mx = (ax + bx) / 2;
  const my = (ay + by) / 2;
  let angle = Math.atan2(by - ay, bx - ax) * (180 / Math.PI);

  // Keep text readable (never upside down)
  if (angle > 90 || angle < -90) angle += 180;

  return { x: mx, y: my, angle };
}

// ─────────────────────────────────────────────────────────────────────────────
// RENDER CONTOUR LINES TO SVG STRING
// ─────────────────────────────────────────────────────────────────────────────

export interface ContourRenderOptions {
  transform: ViewTransform;
  scaleFactor?: number;
  labelIndexContours?: boolean;
  contourColor?: string;
  indexContourColor?: string;
}

export function renderContoursToSvg(
  data: ContourResult,
  options: ContourRenderOptions
): string {
  const {
    transform: t,
    scaleFactor = 1,
    labelIndexContours = true,
    contourColor = '#8B7355',
    indexContourColor = '#5C4A2A',
  } = options;

  const lines: string[] = [];
  const labels: string[] = [];

  lines.push(`<g id="contours" data-interval="${data.interval_m}">`);

  for (const contour of data.contours) {
    const isIndex    = contour.is_index;
    const strokeW    = mmToPx(isIndex ? LINE_WEIGHTS.INDEX_CONTOUR : LINE_WEIGHTS.FORM_CONTOUR, scaleFactor);
    const stroke     = isIndex ? indexContourColor : contourColor;
    const opacity    = isIndex ? '0.9' : '0.65';

    const chains = buildChains(contour.segments as Segment[]);

    for (const chain of chains) {
      if (chain.length < 2) continue;

      // Build SVG polyline points
      const pts = chain
        .map(([wx, wy]) => {
          const [sx, sy] = worldToSvg(wx, wy, t);
          return `${sx.toFixed(2)},${sy.toFixed(2)}`;
        })
        .join(' ');

      lines.push(
        `<polyline points="${pts}" fill="none" stroke="${stroke}" ` +
        `stroke-width="${strokeW.toFixed(3)}" opacity="${opacity}" ` +
        `stroke-linecap="round" stroke-linejoin="round"/>`
      );

      // Label index contours
      if (isIndex && labelIndexContours) {
        const labelPos = contourLabelPath(chain, t);
        if (labelPos) {
          const fontSize = mmToPx(1.4, scaleFactor);
          labels.push(
            `<text x="${labelPos.x.toFixed(2)}" y="${labelPos.y.toFixed(2)}" ` +
            `transform="rotate(${labelPos.angle.toFixed(1)},${labelPos.x.toFixed(2)},${labelPos.y.toFixed(2)})" ` +
            `text-anchor="middle" dominant-baseline="middle" ` +
            `font-family="Arial Narrow,Arial,sans-serif" font-size="${fontSize.toFixed(2)}" ` +
            `fill="${indexContourColor}" stroke="white" stroke-width="${(fontSize * 0.25).toFixed(2)}" ` +
            `paint-order="stroke fill">${contour.elevation.toFixed(1)}</text>`
          );
        }
      }
    }
  }

  lines.push('</g>');
  if (labels.length) {
    lines.push('<g id="contour-labels">');
    lines.push(...labels);
    lines.push('</g>');
  }

  return lines.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// RENDER SPOT HEIGHTS TO SVG
// Source: Ghilani & Wolf Ch.17 — spot height symbols on plans
// Symbol: small cross (+) with elevation label to the right
// ─────────────────────────────────────────────────────────────────────────────

export function renderSpotHeightsToSvg(
  points: SpotHeight[],
  transform: ViewTransform,
  scaleFactor = 1,
  color = '#3A3A3A'
): string {
  const lines: string[] = ['<g id="spot-heights">'];
  const tickSize  = mmToPx(1.0, scaleFactor);
  const fontSize  = mmToPx(1.2, scaleFactor);
  const strokeW   = mmToPx(LINE_WEIGHTS.SPOT_HEIGHT, scaleFactor);

  for (const pt of points) {
    const [sx, sy] = worldToSvg(pt.x, pt.y, transform);
    const label = pt.label ? `${pt.label} (${pt.z.toFixed(3)}m)` : `${pt.z.toFixed(3)}`;

    // Cross symbol
    lines.push(
      `<line x1="${(sx - tickSize).toFixed(2)}" y1="${sy.toFixed(2)}" ` +
      `x2="${(sx + tickSize).toFixed(2)}" y2="${sy.toFixed(2)}" ` +
      `stroke="${color}" stroke-width="${strokeW.toFixed(3)}"/>`,

      `<line x1="${sx.toFixed(2)}" y1="${(sy - tickSize).toFixed(2)}" ` +
      `x2="${sx.toFixed(2)}" y2="${(sy + tickSize).toFixed(2)}" ` +
      `stroke="${color}" stroke-width="${strokeW.toFixed(3)}"/>`,

      // Elevation label to the right and slightly above
      `<text x="${(sx + tickSize + 1.5).toFixed(2)}" y="${(sy - 1.5).toFixed(2)}" ` +
      `font-family="Arial Narrow,Arial,sans-serif" font-size="${fontSize.toFixed(2)}" ` +
      `fill="${color}" dominant-baseline="auto">${label}</text>`
    );
  }

  lines.push('</g>');
  return lines.join('\n');
}

/**
 * METARDU — Topographic Plan Renderer
 * Master renderer for Brief 12 topographic plan improvements.
 *
 * Composes:
 *   - Contour lines (from Python engine output)
 *   - Spot height labels
 *   - Survey of Kenya standard feature symbols
 *   - Four line weight levels
 *   - Dimension leader lines for internal measurements
 *   - Grid / graticule
 *   - North arrow
 *   - Title block (Survey Act Cap 299 compliant)
 *   - Digital signature verification block (Phase 2)
 *
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Ch.17
 *         Survey of Kenya Standard Symbols
 *         Survey Act Cap 299 (Revised 2022)
 *         Survey Regulations 1994
 */

import type { ContourResult, SpotHeight }    from './contourRenderer';
import { renderContoursToSvg, renderSpotHeightsToSvg, type ViewTransform } from './contourRenderer';
import { buildSymbolDefs, renderSymbol, type SurveySymbol }                from './surveySymbols';
import { buildLineWeightLegend, LINE_STYLES, svgStrokeAttrs, lineWeightPx } from './lineWeights';
import { buildArrowDefs, renderLinearDimension, renderLeaderLine }          from './dimensionLeaders';
import type { SignatureRecord }               from '@/lib/integrations/digitalSignature';
import { buildVerificationBlock }             from '@/lib/integrations/digitalSignature';

const MM_TO_PX = 3.7795275591;
function mm(val: number, sf = 1): number { return val * MM_TO_PX * sf; }

// ─────────────────────────────────────────────────────────────────────────────
// PLAN OPTIONS
// ─────────────────────────────────────────────────────────────────────────────

export interface TopographicPlanOptions {
  // Plan metadata
  title:            string;
  drawnBy:          string;
  checkedBy?:       string;
  scale:            string;          // e.g. '1:1000'
  date:             string;
  drawingNo?:       string;
  client?:          string;
  project?:         string;
  datum:            string;          // e.g. 'ARC1960 / UTM Zone 37S (EPSG:21037)'
  county?:          string;

  // SVG canvas
  svgWidth?:        number;          // px
  svgHeight?:       number;          // px
  margin?:          number;          // px
  scaleFactor?:     number;

  // Data layers (all optional)
  contours?:        ContourResult;
  spotHeights?:     SpotHeight[];
  featurePoints?:   FeaturePoint[];
  dimensions?:      DimensionSpec[];
  leaders?:         LeaderSpec[];
  boundaries?:      BoundaryChain[];

  // Signature (Phase 2)
  signature?:       SignatureRecord;

  // Display options
  showGrid?:        boolean;
  showNorthArrow?:  boolean;
  showLegend?:      boolean;
  showScaleBar?:    boolean;
  contourInterval?: number;
}

export interface FeaturePoint {
  x: number; y: number;
  symbolId: string;
  label?: string;
  rotation?: number;
}

export interface DimensionSpec {
  x1: number; y1: number;
  x2: number; y2: number;
  label?: string;
  offset?: number;
}

export interface LeaderSpec {
  featureX: number; featureY: number;
  labelX: number;   labelY: number;
  label: string;
  subLabel?: string;
}

export interface BoundaryChain {
  points: [number, number][];  // world coords (E, N)
  closed?: boolean;
  styleKey?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// NORTH ARROW
// ─────────────────────────────────────────────────────────────────────────────

function renderNorthArrow(x: number, y: number, sf = 1): string {
  const h  = mm(12, sf);
  const hw = mm(3,  sf);
  const fontSize = mm(3, sf).toFixed(2);

  return `
<g id="north-arrow" transform="translate(${x},${y})">
  <!-- Arrow shaft -->
  <line x1="0" y1="${h/2}" x2="0" y2="${-h/2}" stroke="#000" stroke-width="${lineWeightPx(4, sf).toFixed(3)}"/>
  <!-- North half (filled) -->
  <polygon points="0,${-h/2} ${-hw},0 ${hw},0" fill="#000"/>
  <!-- South half (outline) -->
  <polygon points="0,${h/2} ${-hw},0 ${hw},0" fill="white" stroke="#000" stroke-width="${lineWeightPx(4, sf).toFixed(3)}"/>
  <!-- N label -->
  <text x="0" y="${(-h/2 - mm(2, sf))}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${fontSize}" font-weight="bold" fill="#000">N</text>
</g>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// SCALE BAR
// ─────────────────────────────────────────────────────────────────────────────

function renderScaleBar(x: number, y: number, scaleString: string, sf = 1): string {
  const barW  = mm(40, sf);
  const barH  = mm(2.5, sf);
  const ticks = 4;
  const tickW = barW / ticks;
  const fontSize = mm(2.2, sf).toFixed(2);
  const sw = lineWeightPx(4, sf).toFixed(3);

  const parts: string[] = [`<g id="scale-bar" transform="translate(${x},${y})">`];

  for (let i = 0; i < ticks; i++) {
    const fill = i % 2 === 0 ? '#000' : '#fff';
    parts.push(
      `<rect x="${(i * tickW).toFixed(2)}" y="0" width="${tickW.toFixed(2)}" height="${barH.toFixed(2)}" fill="${fill}" stroke="#000" stroke-width="${sw}"/>`
    );
  }

  // Scale label
  parts.push(
    `<text x="${(barW / 2).toFixed(2)}" y="${(barH + mm(4, sf)).toFixed(2)}" text-anchor="middle" ` +
    `font-family="Arial,sans-serif" font-size="${fontSize}" fill="#000">Scale ${scaleString}</text>`
  );

  parts.push('</g>');
  return parts.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// TITLE BLOCK
// Survey Act Cap 299 compliant
// ─────────────────────────────────────────────────────────────────────────────

function renderTitleBlock(opts: TopographicPlanOptions, svgW: number, svgH: number, sf = 1): string {
  const margin    = opts.margin ?? mm(10, sf);
  const tbH       = mm(40, sf);
  const tbW       = svgW - 2 * margin;
  const tbY       = svgH - margin - tbH;
  const tbX       = margin;
  const bw        = lineWeightPx(1, sf).toFixed(3);
  const lw        = lineWeightPx(4, sf).toFixed(3);
  const titleSize = mm(5, sf).toFixed(2);
  const bodySize  = mm(2.8, sf).toFixed(2);
  const labelSize = mm(2.0, sf).toFixed(2);

  const col2X = tbX + mm(80, sf);
  const col3X = tbX + mm(140, sf);

  return `
<g id="title-block">
  <!-- Outer border -->
  <rect x="${tbX.toFixed(2)}" y="${tbY.toFixed(2)}" width="${tbW.toFixed(2)}" height="${tbH.toFixed(2)}" fill="white" stroke="#000" stroke-width="${bw}"/>
  
  <!-- Vertical dividers -->
  <line x1="${col2X.toFixed(2)}" y1="${tbY.toFixed(2)}" x2="${col2X.toFixed(2)}" y2="${(tbY + tbH).toFixed(2)}" stroke="#000" stroke-width="${lw}"/>
  <line x1="${col3X.toFixed(2)}" y1="${tbY.toFixed(2)}" x2="${col3X.toFixed(2)}" y2="${(tbY + tbH).toFixed(2)}" stroke="#000" stroke-width="${lw}"/>

  <!-- Column 1: Title, Client, Project -->
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(10, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${titleSize}" font-weight="bold" fill="#000">${opts.title}</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(17, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">CLIENT</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(21, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.client ?? '—'}</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(27, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">PROJECT</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(31, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.project ?? '—'}</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(38, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">${opts.datum}</text>

  <!-- Column 2: Drawing details -->
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(8, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">DRAWN BY</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(12, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.drawnBy}</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(18, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">CHECKED BY</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(22, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.checkedBy ?? '—'}</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(28, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">DATE</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(32, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.date}</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(38, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">COUNTY: ${opts.county ?? '—'}</text>

  <!-- Column 3: Scale, Drawing No -->
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(8, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">SCALE</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(13, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${(mm(4.5, sf)).toFixed(2)}" font-weight="bold" fill="#000">${opts.scale}</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(20, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">DRAWING NO.</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(25, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.drawingNo ?? '—'}</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(32, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#555">Prepared by METARDU</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(37, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#777">Survey Act Cap 299 | Regs 1994</text>

</g>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// GRID
// ─────────────────────────────────────────────────────────────────────────────

function renderGrid(t: ViewTransform, sf = 1): string {
  const strokeAttr = svgStrokeAttrs('grid_line', sf);
  const lines: string[] = ['<g id="grid" opacity="0.4">'];

  const usableW = t.svg_width  - 2 * t.margin;
  const usableH = t.svg_height - 2 * t.margin;
  const gridPx  = mm(20, sf); // grid spacing in px

  for (let x = t.margin; x <= t.margin + usableW; x += gridPx) {
    lines.push(`<line x1="${x.toFixed(1)}" y1="${t.margin}" x2="${x.toFixed(1)}" y2="${(t.margin + usableH).toFixed(1)}" ${strokeAttr}/>`);
  }
  for (let y = t.margin; y <= t.margin + usableH; y += gridPx) {
    lines.push(`<line x1="${t.margin}" y1="${y.toFixed(1)}" x2="${(t.margin + usableW).toFixed(1)}" y2="${y.toFixed(1)}" ${strokeAttr}/>`);
  }

  lines.push('</g>');
  return lines.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// MASTER RENDER FUNCTION
// ─────────────────────────────────────────────────────────────────────────────

export function renderTopographicPlan(opts: TopographicPlanOptions): string {
  const sf         = opts.scaleFactor ?? 1;
  const svgW       = opts.svgWidth    ?? mm(297, sf);   // A4 landscape width
  const svgH       = opts.svgHeight   ?? mm(210, sf);   // A4 landscape height
  const margin     = opts.margin      ?? mm(12, sf);

  const titleBlockH = mm(42, sf);
  const drawAreaH   = svgH - margin - titleBlockH - margin;

  // Build view transform
  const contourExtent = opts.contours?.extent
  const t: ViewTransform = {
    x_min:      contourExtent?.x_min ?? 0,
    x_max:      contourExtent?.x_max ?? 1000,
    y_min:      contourExtent?.y_min ?? 0,
    y_max:      contourExtent?.y_max ?? 1000,
    svg_width:  svgW,
    svg_height: svgH - titleBlockH,
    margin,
  };

  // Expand extent from spot heights if no contours
  if (!opts.contours && opts.spotHeights?.length) {
    t.x_min = Math.min(...opts.spotHeights.map((p: SpotHeight) => p.x));
    t.x_max = Math.max(...opts.spotHeights.map((p: SpotHeight) => p.x));
    t.y_min = Math.min(...opts.spotHeights.map((p: SpotHeight) => p.y));
    t.y_max = Math.max(...opts.spotHeights.map((p: SpotHeight) => p.y));
  }

  const parts: string[] = [];

  // SVG header
  parts.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}">`
  );

  // Defs
  parts.push('<defs>');
  parts.push(buildSymbolDefs());
  parts.push(buildArrowDefs(sf));
  parts.push('</defs>');

  // Background
  parts.push(`<rect width="${svgW}" height="${svgH}" fill="white"/>`);

  // Plan border
  const bw = lineWeightPx(1, sf).toFixed(3);
  parts.push(`<rect x="${margin}" y="${margin}" width="${(svgW - 2*margin).toFixed(2)}" height="${(svgH - 2*margin).toFixed(2)}" fill="none" stroke="#000" stroke-width="${bw}"/>`);

  // Drawing area clip
  const clipId = 'drawing-area-clip';
  parts.push(`<clipPath id="${clipId}"><rect x="${margin}" y="${margin}" width="${(svgW-2*margin).toFixed(2)}" height="${drawAreaH.toFixed(2)}"/></clipPath>`);
  parts.push(`<g clip-path="url(#${clipId})">`);

  // Grid
  if (opts.showGrid !== false) {
    parts.push(renderGrid(t, sf));
  }

  // Contour lines
  if (opts.contours) {
    parts.push(renderContoursToSvg(opts.contours, {
      transform: t,
      scaleFactor: sf,
      labelIndexContours: true,
    }));
  }

  // Spot heights
  if (opts.spotHeights?.length) {
    parts.push(renderSpotHeightsToSvg(opts.spotHeights, t, sf));
  }

  // Feature symbols
  if (opts.featurePoints?.length) {
    const symbolGroup: string[] = ['<g id="features">'];
    for (const fp of opts.featurePoints) {
      const [sx, sy] = [fp.x, fp.y]; // caller provides SVG coords for features
      symbolGroup.push(renderSymbol(fp.symbolId, sx, sy, {
        scaleFactor: sf,
        rotation: fp.rotation,
        label: fp.label,
      }));
    }
    symbolGroup.push('</g>');
    parts.push(symbolGroup.join('\n'));
  }

  // Boundaries
  if (opts.boundaries?.length) {
    const boundaryGroup: string[] = ['<g id="boundaries">'];
    for (const b of opts.boundaries) {
      if (b.points.length < 2) continue;
      const styleKey = (b.styleKey as keyof typeof LINE_STYLES) ?? 'survey_boundary';
      const strokeAttr = svgStrokeAttrs(styleKey, sf);
      const pts = b.points.map(([wx, wy]) => {
        const [sx, sy] = [wx, wy]; // world to SVG conversion handled upstream
        return `${sx.toFixed(2)},${sy.toFixed(2)}`;
      }).join(' ');
      const tag = b.closed ? 'polygon' : 'polyline';
      boundaryGroup.push(`<${tag} points="${pts}" fill="none" ${strokeAttr}/>`);
    }
    boundaryGroup.push('</g>');
    parts.push(boundaryGroup.join('\n'));
  }

  // Dimensions
  if (opts.dimensions?.length) {
    const dimGroup: string[] = ['<g id="dimensions">'];
    for (const d of opts.dimensions) {
      dimGroup.push(renderLinearDimension({ ...d, scaleFactor: sf }));
    }
    dimGroup.push('</g>');
    parts.push(dimGroup.join('\n'));
  }

  // Leader lines
  if (opts.leaders?.length) {
    const leaderGroup: string[] = ['<g id="leaders">'];
    for (const l of opts.leaders) {
      leaderGroup.push(renderLeaderLine({ ...l, scaleFactor: sf }));
    }
    leaderGroup.push('</g>');
    parts.push(leaderGroup.join('\n'));
  }

  parts.push('</g>'); // end clip

  // North arrow
  if (opts.showNorthArrow !== false) {
    parts.push(renderNorthArrow(svgW - margin - mm(15, sf), margin + mm(18, sf), sf));
  }

  // Scale bar
  if (opts.showScaleBar !== false) {
    parts.push(renderScaleBar(margin + mm(5, sf), svgH - margin - titleBlockH - mm(12, sf), opts.scale, sf));
  }

  // Line weight legend
  if (opts.showLegend !== false) {
    parts.push(buildLineWeightLegend(svgW - margin - mm(55, sf), margin + mm(5, sf), sf));
  }

  // Title block
  parts.push(renderTitleBlock(opts, svgW, svgH, sf));

  // Digital signature verification block (Phase 2) — below title block
  if (opts.signature) {
    const sigY = svgH - margin - mm(5, sf);
    const sigX = margin;
    parts.push(`<g transform="translate(${sigX},${sigY})">`);
    parts.push(buildVerificationBlock(opts.signature));
    parts.push('</g>');
  }

  parts.push('</svg>');
  return parts.join('\n');
}

/**
 * METARDU — GNSS Observation Log / Baseline Report
 *
 * Produces a formal GNSS observation log suitable for submission
 * to the Director of Surveys or project record-keeping.
 *
 * Includes:
 *   - Session header (project, equipment, date, operator)
 *   - Occupation schedule table (start/end, duration, satellites, PDOP)
 *   - Baseline vectors table (from/to, ΔE/ΔN/ΔU, distance, RMS)
 *   - Quality assessment summary
 *   - Surveyor's Certificate
 *
 * References:
 *   Survey Act Cap 299, s.22 (survey records)
 *   Survey Regulations 1994, Reg. 21 (instrument records)
 *   ISK — GNSS Best Practice Guidelines (2019)
 *   ISO 17123-8: GNSS field procedures
 */

import { buildPrintDocument, openPrint } from './buildPrintDocument'
import type { PrintMeta } from './buildPrintDocument'

// ── Types ─────────────────────────────────────────────────────────────────────

export interface GNSSObservationEntry {
  /** Point ID e.g. "BM_101" */
  pointId: string
  /** Session start time ISO string */
  startTime: string
  /** Session end time ISO string */
  endTime: string
  /** Duration in minutes */
  durationMin: number
  /** Number of satellites tracked */
  satellites: number
  /** Position Dilution of Precision */
  pdop: number
  /** Horizontal DOP */
  hdop: number
  /** Vertical DOP */
  vdop: number
  /** Fix type */
  fixType: 'FIX' | 'FLOAT' | 'DGNSS' | 'AUTONOMOUS' | 'RTK_FIX' | 'RTK_FLOAT'
  /** Antenna height in metres */
  antennaHeight: number
  /** Antenna measurement method */
  antennaMeasurement: 'SLANT' | 'VERTICAL' | 'ARP'
  /** Easting (projected) */
  easting?: number
  /** Northing (projected) */
  northing?: number
  /** Ellipsoidal height */
  ellHeight?: number
  /** Orthometric height */
  orthoHeight?: number
  /** RMS horizontal error (metres) */
  rmsH?: number
  /** RMS vertical error (metres) */
  rmsV?: number
  /** Notes */
  notes?: string
}

export interface GNSSBaselineEntry {
  /** From station */
  from: string
  /** To station */
  to: string
  /** Delta Easting (metres) */
  deltaE: number
  /** Delta Northing (metres) */
  deltaN: number
  /** Delta Elevation (metres) */
  deltaU: number
  /** Slope distance (metres) */
  distance: number
  /** Azimuth WCB (degrees) */
  azimuth: number
  /** Solution type */
  solution: 'FIX' | 'FLOAT' | 'DGNSS'
  /** Ratio (fix quality indicator) */
  ratio?: number
  /** RMS of baseline solution (metres) */
  rms: number
}

export interface GNSSLogInput {
  observations: GNSSObservationEntry[]
  baselines: GNSSBaselineEntry[]
  /** Equipment details */
  receiverModel: string
  receiverSerial: string
  antennaModel: string
  antennaSerial: string
  /** Reference station */
  baseStationId: string
  baseStationSource: 'OWN_BASE' | 'CORS' | 'VRS' | 'THIRD_PARTY'
  /** Coordinate system / datum */
  datum: string
  projection: string
  geoidModel: string
  /** Cutoff angle in degrees */
  elevationMask: number
  /** Epoch interval in seconds */
  epochInterval: number
  /** RINEX version if applicable */
  rinexVersion?: string
  /** Processing software */
  processingSoftware?: string
  /** Meta for header */
  meta: PrintMeta
}

// ── Formatting helpers ────────────────────────────────────────────────────────

function fmtTime(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })
  } catch { return iso }
}

function fmtDate(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleDateString('en-KE', { day: '2-digit', month: 'short', year: 'numeric' })
  } catch { return iso }
}

function fixClass(fix: string): string {
  if (fix === 'FIX' || fix === 'RTK_FIX') return 'pass'
  if (fix === 'FLOAT' || fix === 'RTK_FLOAT') return 'warn'
  return 'fail'
}

function dmsFromDec(deg: number): string {
  const d = Math.floor(deg)
  const minDec = (deg - d) * 60
  const m = Math.floor(minDec)
  const s = (minDec - m) * 60
  return `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`
}

// ── Body HTML builder ─────────────────────────────────────────────────────────

function esc(value: string | number | undefined | null): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function blank(value: string | number | undefined | null): string {
  const text = String(value ?? '').trim()
  return text ? esc(text) : '&mdash;'
}

function buildBody(inp: GNSSLogInput): string {
  const obs = inp.observations
  const bsl = inp.baselines

  // ── Equipment box ────────────────────────────────────────────
  const equipmentBox = `
<div class="summary-box" style="display:grid;grid-template-columns:1fr 1fr;gap:0;">
  <div class="summary-row"><span class="summary-label">Receiver</span><span class="summary-value">${blank(inp.receiverModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Receiver S/N</span><span class="summary-value">${blank(inp.receiverSerial)}</span></div>
  <div class="summary-row"><span class="summary-label">Antenna</span><span class="summary-value">${blank(inp.antennaModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Antenna S/N</span><span class="summary-value">${blank(inp.antennaSerial)}</span></div>
  <div class="summary-row"><span class="summary-label">Base Station</span><span class="summary-value">${blank(inp.baseStationId)} (${blank(inp.baseStationSource.replace(/_/g, ' '))})</span></div>
  <div class="summary-row"><span class="summary-label">Elevation Mask</span><span class="summary-value">${inp.elevationMask}°</span></div>
  <div class="summary-row"><span class="summary-label">Epoch Interval</span><span class="summary-value">${inp.epochInterval}s</span></div>
  <div class="summary-row"><span class="summary-label">Datum / Projection</span><span class="summary-value">${blank(inp.datum)} / ${blank(inp.projection)}</span></div>
  <div class="summary-row"><span class="summary-label">Geoid Model</span><span class="summary-value">${blank(inp.geoidModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Processing Software</span><span class="summary-value">${blank(inp.processingSoftware || 'N/A')}</span></div>
</div>`

  // ── Observation schedule table ──────────────────────────────
  const obsRows = obs.map((o, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(o.pointId)}</td>
  <td class="mono">${fmtTime(o.startTime)}</td>
  <td class="mono">${fmtTime(o.endTime)}</td>
  <td class="right mono">${o.durationMin.toFixed(0)}</td>
  <td class="center">${o.satellites}</td>
  <td class="right mono">${o.pdop.toFixed(1)}</td>
  <td class="right mono">${o.hdop.toFixed(1)}</td>
  <td class="center"><span class="${fixClass(o.fixType)}">${o.fixType.replace(/_/g, ' ')}</span></td>
  <td class="right mono">${o.antennaHeight.toFixed(3)}</td>
  <td class="center" style="font-size:7.5pt">${o.antennaMeasurement}</td>
</tr>`).join('')

  const obsTable = `
<h2>1. Occupation Schedule</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:10%">Point</th>
      <th style="width:8%">Start</th>
      <th style="width:8%">End</th>
      <th class="right" style="width:6%">Min</th>
      <th style="width:5%">Sats</th>
      <th class="right" style="width:6%">PDOP</th>
      <th class="right" style="width:6%">HDOP</th>
      <th style="width:10%">Fix</th>
      <th class="right" style="width:8%">Ant H (m)</th>
      <th style="width:5%">Meas</th>
    </tr>
  </thead>
  <tbody>
    ${obsRows || '<tr><td colspan="11" class="center" style="color:#999;font-style:italic;">No observations entered</td></tr>'}
  </tbody>
</table>`

  // ── Coordinate results table ────────────────────────────────
  const coordRows = obs.filter(o => o.easting && o.northing).map((o, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(o.pointId)}</td>
  <td class="right mono">${o.easting?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.northing?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.ellHeight?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.orthoHeight?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.rmsH?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.rmsV?.toFixed(3) ?? '—'}</td>
</tr>`).join('')

  const coordTable = coordRows ? `
<h2>2. Coordinate Results — ${blank(inp.datum)}</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:10%">Point</th>
      <th class="right" style="width:14%">Easting (m)</th>
      <th class="right" style="width:14%">Northing (m)</th>
      <th class="right" style="width:12%">Ell. Ht (m)</th>
      <th class="right" style="width:12%">Ortho Ht (m)</th>
      <th class="right" style="width:10%">RMS H (m)</th>
      <th class="right" style="width:10%">RMS V (m)</th>
    </tr>
  </thead>
  <tbody>${coordRows}</tbody>
</table>` : ''

  // ── Baseline vectors table ──────────────────────────────────
  const bslRows = bsl.map((b, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(b.from)}</td>
  <td class="bold mono">${blank(b.to)}</td>
  <td class="right mono">${b.deltaE.toFixed(3)}</td>
  <td class="right mono">${b.deltaN.toFixed(3)}</td>
  <td class="right mono">${b.deltaU.toFixed(3)}</td>
  <td class="right mono">${b.distance.toFixed(3)}</td>
  <td class="mono">${dmsFromDec(b.azimuth)}</td>
  <td class="center"><span class="${b.solution === 'FIX' ? 'pass' : b.solution === 'FLOAT' ? 'warn' : 'fail'}">${b.solution}</span></td>
  <td class="right mono">${b.ratio?.toFixed(1) ?? '—'}</td>
  <td class="right mono">${b.rms.toFixed(4)}</td>
</tr>`).join('')

  const bslTable = bsl.length > 0 ? `
<h2>${coordRows ? '3' : '2'}. Baseline Vectors</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:8%">From</th>
      <th style="width:8%">To</th>
      <th class="right" style="width:10%">ΔE (m)</th>
      <th class="right" style="width:10%">ΔN (m)</th>
      <th class="right" style="width:10%">ΔU (m)</th>
      <th class="right" style="width:10%">Dist (m)</th>
      <th style="width:12%">Azimuth</th>
      <th style="width:6%">Sol</th>
      <th class="right" style="width:6%">Ratio</th>
      <th class="right" style="width:8%">RMS (m)</th>
    </tr>
  </thead>
  <tbody>${bslRows}</tbody>
</table>` : ''

  // ── Quality assessment ──────────────────────────────────────
  const fixCount = obs.filter(o => o.fixType === 'FIX' || o.fixType === 'RTK_FIX').length
  const floatCount = obs.filter(o => o.fixType === 'FLOAT' || o.fixType === 'RTK_FLOAT').length
  const avgPdop = obs.length > 0 ? obs.reduce((a, o) => a + o.pdop, 0) / obs.length : 0
  const avgSats = obs.length > 0 ? obs.reduce((a, o) => a + o.satellites, 0) / obs.length : 0
  const maxRms = bsl.length > 0 ? Math.max(...bsl.map(b => b.rms)) : 0
  const avgRms = bsl.length > 0 ? bsl.reduce((a, b) => a + b.rms, 0) / bsl.length : 0
  const allFixed = fixCount === obs.length
  const minSats = obs.length > 0 ? Math.min(...obs.map(o => o.satellites)) : 0

  const qualitySection = `
<h2>${coordRows ? '4' : bsl.length > 0 ? '3' : '2'}. Quality Assessment</h2>
<div class="summary-box">
  <div class="summary-row"><span class="summary-label">Total observations</span><span class="summary-value">${obs.length}</span></div>
  <div class="summary-row"><span class="summary-label">Fixed solutions</span><span class="summary-value ${allFixed ? 'pass' : 'warn'}">${fixCount} / ${obs.length} (${obs.length > 0 ? ((fixCount / obs.length) * 100).toFixed(0) : 0}%)</span></div>
  <div class="summary-row"><span class="summary-label">Float solutions</span><span class="summary-value">${floatCount}</span></div>
  <div class="summary-row"><span class="summary-label">Avg PDOP</span><span class="summary-value ${avgPdop <= 3 ? 'pass' : avgPdop <= 6 ? 'warn' : 'fail'}">${avgPdop.toFixed(2)}</span></div>
  <div class="summary-row"><span class="summary-label">Avg satellites</span><span class="summary-value">${avgSats.toFixed(1)}</span></div>
  <div class="summary-row"><span class="summary-label">Min satellites</span><span class="summary-value ${minSats >= 5 ? 'pass' : 'fail'}">${minSats}</span></div>
  ${bsl.length > 0 ? `
  <div class="summary-row"><span class="summary-label">Total baselines</span><span class="summary-value">${bsl.length}</span></div>
  <div class="summary-row"><span class="summary-label">Avg baseline RMS</span><span class="summary-value ${avgRms <= 0.01 ? 'pass' : avgRms <= 0.05 ? 'warn' : 'fail'}">${avgRms.toFixed(4)} m</span></div>
  <div class="summary-row"><span class="summary-label">Max baseline RMS</span><span class="summary-value ${maxRms <= 0.02 ? 'pass' : maxRms <= 0.1 ? 'warn' : 'fail'}">${maxRms.toFixed(4)} m</span></div>
  ` : ''}
  <div class="summary-row"><span class="summary-label">Overall quality</span><span class="summary-value ${allFixed && avgPdop <= 3 ? 'pass' : 'warn'}">${allFixed && avgPdop <= 3 ? 'EXCELLENT' : fixCount > obs.length / 2 ? 'ACCEPTABLE' : 'REVIEW REQUIRED'}</span></div>
</div>`

  // ── Field notes ─────────────────────────────────────────────
  const obsWithNotes = obs.filter(o => o.notes)
  const notesSection = obsWithNotes.length > 0 ? `
<h2>Field Notes</h2>
<table>
  <thead>
    <tr>
      <th style="width:15%">Point</th>
      <th>Notes</th>
    </tr>
  </thead>
  <tbody>
    ${obsWithNotes.map(o => `<tr><td class="bold mono">${blank(o.pointId)}</td><td>${blank(o.notes)}</td></tr>`).join('')}
  </tbody>
</table>` : ''

  return `
${equipmentBox}
${obsTable}
${coordTable}
${bslTable}
${qualitySection}
${notesSection}
`
}

// ── Public API ────────────────────────────────────────────────────────────────

export function generateGNSSObservationLog(inp: GNSSLogInput): string {
  const meta: PrintMeta = {
    ...inp.meta,
    title: inp.meta.title || 'GNSS Observation Log',
    reference: 'Survey Act Cap 299 | Survey Regulations 1994, Reg. 21 | ISK GNSS Guidelines 2019 | ISO 17123-8',
  }
  return buildPrintDocument(buildBody(inp), meta)
}

export function printGNSSObservationLog(inp: GNSSLogInput): void {
  openPrint(generateGNSSObservationLog(inp))
}

import { computeTraverseAccuracy, getAccuracyBadgeLabel } from '../traverseAccuracy'
import { defined } from '@/test-utils/defined'

describe('computeTraverseAccuracy', () => {
  it('classifies 1mm error on 4km perimeter as First Order Class I', () => {
    const r = computeTraverseAccuracy(0.001, 4000)
    expect(r).not.toBeNull()
    expect(defined(r).order).toBe('FIRST ORDER CLASS I')
    expect(defined(r).m_mm).toBe(0.5)
    expect(defined(r).C_mm).toBe(1.0)
    expect(defined(r).K_km).toBe(4.0)
    expect(defined(r).allowed).toBeCloseTo(0.5, 1)
  })
  it('returns null for zero perimeter', () => {
    const r = computeTraverseAccuracy(0.001, 0)
    expect(r).toBeNull()
  })
  it('classifies 2mm error on 1km perimeter as Third Order', () => {
    const r = computeTraverseAccuracy(0.002, 1000)
    expect(r).not.toBeNull()
    expect(defined(r).order).toBe('THIRD ORDER')
  })
})

import JSZip from 'jszip'
import { createClient } from '@/lib/api-client/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { db } from '@/lib/db'
import { getActiveSurveyorProfile } from './surveyorProfile'
import { generateSubmissionRef } from './revisionNumber'
import { validateSubmission } from './validateSubmission'
import { generateFormNo4DXF } from './generators/formNo4'
import { generateStatutoryWorkbook } from './workbook/statutoryWorkbook'
import { generateWorkingDiagramDXF } from './generators/workingDiagram'
import { generatePPA2Form } from './generators/ppa2Form'
import { generateLCBConsent } from './generators/lcbConsent'
import { generateMutationForm } from './generators/mutationForm'
import type { PPA2Input } from './generators/ppa2Form'
import type { LCBConsentInput } from './generators/lcbConsent'
import type { MutationFormInput } from './generators/mutationForm'
import { coordinateArea } from '@/lib/engine/area'
import { angularClosureTolerance } from '@/lib/engine/traverse'
import type { SubmissionPackage, QAGateResult, SurveySubtype, SupportingDocument } from './types'
import { logger } from '@/lib/logger'

/** Row shape for survey_points (typed callback params for the legacy client reads). */
interface SurveyPointRow {
  id?: string | number
  idx?: number
  name?: string | null
  point_name?: string | null
  easting?: number | null
  northing?: number | null
  adjusted_easting?: number | null
  adjusted_northing?: number | null
  observed_bearing?: number | null
  observed_distance?: number | null
  distance?: number | null
}

/** Row shape for supporting_documents. */
interface SupportingDocumentRow {
  type?: SupportingDocument['type'] | null
  label?: string | null
  required?: boolean | null
  file_url?: string | null
  uploaded_at?: string | null
}

/** surveyor_profiles row (typed reads in the sequence/insert block). */
interface SurveyorProfileRow {
  id: string
  isk_number: string
}

/** project_submissions row (revision reads). */
interface ProjectSubmissionRow {
  revision_number: number
}

/** submission_sequences row (RETURNING current_sequence). */
interface SubmissionSequenceRow {
  current_sequence: number
}

interface ProjectData {
  id: string
  lr_number: string
  parcel_number: string
  division: string
  county: string
  district: string
  locality: string
  area_m2: number
  perimeter_m: number
  subtype: SurveySubtype
  survey_points: SurveyPointRow[]
  supporting_documents: SupportingDocumentRow[]
  angular_misclosure: number
  linear_misclosure: number
  precision_ratio: string
  closing_error_e: number
  closing_error_n: number
  client_name: string
  survey_type?: string
}

export async function assembleSubmissionPackage(
  projectId: string
): Promise<{ zipBuffer: Buffer; ref: string; qa: QAGateResult }> {
  const dbClient = await createClient()
  const surveyor = await getActiveSurveyorProfile()
  if (!surveyor) {
    // AUDIT FIX (H-010, 2026-07-27): guard against missing surveyor profile.
    throw new Error('Surveyor profile not found — please complete your profile before generating a submission.')
  }
  const asNum = (value: unknown, fallback = 0): number => {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : fallback
  }

  // QueryBuilder does not support DbClient-style nested relation selects,
  // so fetch project, points, and docs in separate queries.
  const projectRes = await dbClient
    .from('projects')
    .select('*')
    .eq('id', projectId)
    .single()
  const project = projectRes.data as Record<string, unknown> | null
  const projectError = projectRes.error

  if (projectError || !project) throw new Error('Project not found')

  const pointsRes = await dbClient
    .from('survey_points')
    .select('*')
    .eq('project_id', projectId)
    .limit(50_000)
  const surveyPoints = pointsRes.data as SurveyPointRow[] | null
  const pointsError = pointsRes.error // hard cap: 50k points per project (~50MB RAM for dense surveys).
                    // Exceeding this requires project splitting or cursor pagination.

  if (pointsError) {
    throw new Error(`Failed to load survey points: ${pointsError.message}`)
  }

  const docsRes = await dbClient
    .from('supporting_documents')
    .select('*')
    .eq('project_id', projectId)
  const supportingDocuments = docsRes.data as SupportingDocumentRow[] | null
  const docsError = docsRes.error

  if (docsError) {
    throw new Error(`Failed to load supporting documents: ${docsError.message}`)
  }

  const proj = {
    ...(project as Record<string, unknown>),
    survey_points: Array.isArray(surveyPoints) ? surveyPoints : [],
    supporting_documents: Array.isArray(supportingDocuments) ? supportingDocuments : []
  } as unknown as ProjectData

  const adjustedCoordinates = (proj.survey_points || [])
    .filter((pt: SurveyPointRow) => pt.adjusted_easting != null && pt.adjusted_northing != null)
    .map((pt: SurveyPointRow) => ({
      label: pt.point_name ?? pt.name ?? `P${pt.idx}`,
      easting: asNum(pt.adjusted_easting),
      northing: asNum(pt.adjusted_northing)
    }));

  let computedAreaM2 = 0;
  if (adjustedCoordinates.length >= 3) {
    const areaResult = coordinateArea(adjustedCoordinates);
    computedAreaM2 = areaResult.areaSqm;
  } else if (proj.survey_points && proj.survey_points.length >= 3) {
    const rawCoordinates = (proj.survey_points || []).map((pt: SurveyPointRow) => ({
      easting: asNum(pt.easting),
      northing: asNum(pt.northing)
    }));
    const areaResult = coordinateArea(rawCoordinates);
    computedAreaM2 = areaResult.areaSqm;
  }

  if (adjustedCoordinates.length < 3 && proj.survey_points && proj.survey_points.length >= 3) {
    logger.warn('No adjusted coordinates found - using raw coordinates for area computation');
  }

  if (adjustedCoordinates.length < 3 && (!proj.survey_points || proj.survey_points.length < 3)) {
    throw new Error(
      'Cannot assemble submission: traverse must have at least 3 points to compute area. ' +
      'Complete traverse computation before submitting.'
    );
  }

  const { ref, revision } = await generateSubmissionRef(
    projectId,
    surveyor.registration_number
  )

  const supportingDocs = (proj.supporting_documents ?? []).map((doc: SupportingDocumentRow) => ({
    type: doc.type ?? 'ppa2',
    label: doc.label ?? '',
    required: doc.required ?? false,
    fileUrl: doc.file_url ?? null,
    uploadedAt: doc.uploaded_at ?? null
  }))

  const pkg: SubmissionPackage = {
    submissionRef: ref,
    projectId,
    surveyor: { ...surveyor, registrationNumber: surveyor.registration_number } as unknown as SubmissionPackage['surveyor'],
    subtype: (proj.survey_type || 'cadastral_subdivision') as SurveySubtype,
    parcel: {
      lrNumber: proj.lr_number || '',
      parcelNumber: proj.parcel_number || proj.lr_number || '',
      county: proj.county || '',
      division: proj.division || '',
      district: proj.district || '',
      locality: proj.locality || '',
      areaM2: computedAreaM2,
      perimeterM: asNum(proj.perimeter_m),
      clientName: proj.client_name || ''
    },
    traverse: {
      points: (proj.survey_points || []).map((pt: SurveyPointRow) => ({
        pointName: pt.name || pt.point_name || `P${pt.id}`,
        easting: asNum(pt.easting),
        northing: asNum(pt.northing),
        adjustedEasting: asNum(pt.adjusted_easting, asNum(pt.easting)),
        adjustedNorthing: asNum(pt.adjusted_northing, asNum(pt.northing)),
        observedBearing: asNum(pt.observed_bearing),
        observedDistance: asNum(pt.observed_distance, asNum(pt.distance))
      })),
      angularMisclosure: asNum(proj.angular_misclosure),
      linearMisclosure: asNum(proj.linear_misclosure),
      precisionRatio: proj.precision_ratio || '1:1',
      closingErrorE: asNum(proj.closing_error_e),
      closingErrorN: asNum(proj.closing_error_n),
      adjustmentMethod: 'bowditch',
      areaM2: computedAreaM2,
      perimeterM: asNum(proj.perimeter_m)
    },
    supportingDocs,
    generatedAt: new Date().toISOString(),
    revision
  }

  const qa = validateSubmission(pkg)
  if (!qa.passed) {
    return { zipBuffer: Buffer.alloc(0), ref, qa }
  }

  const formNo4Dxf = generateFormNo4DXF(pkg)
  const firstPt = pkg.traverse.points[0]
  const workbook = await generateStatutoryWorkbook({
    project: {
      name: String(project.name ?? ''),
      lrNumber: String(project.lr_number ?? ''),
      parcelNumber: String(project.parcel_number ?? ''),
      county: String(project.county ?? ''),
      division: String(project.division ?? ''),
      district: String(project.district ?? ''),
      locality: String(project.locality ?? ''),
      surveyType: 'cadastral',
      surveyDate: String(project.survey_date ?? new Date().toISOString()),
      scaleDenominator: 2500,
    },
    surveyor: {
      name: surveyor.full_name,
      iskNumber: surveyor.registration_number,
      firmName: surveyor.firm_name ?? '',
    },
    submission: {
      referenceNumber: ref,
      revision,
      status: 'submitted',
    },
    fieldObservations: pkg.traverse.points.map((pt, i) => ({
      stationFrom: pt.pointName,
      stationTo: pkg.traverse.points[(i + 1) % pkg.traverse.points.length]?.pointName ?? '',
      observedBearingDeg: pt.observedBearing,
      observedDistanceM: pt.observedDistance,
    })),
    traverse: {
      method: pkg.traverse.adjustmentMethod,
      stations: pkg.traverse.points.map(pt => ({
        label: pt.pointName,
        observedBearing: pt.observedBearing,
        observedDistance: pt.observedDistance,
        departureRaw: pt.easting - (firstPt?.easting ?? 0),
        latitudeRaw: pt.northing - (firstPt?.northing ?? 0),
        departureCorrected: pt.adjustedEasting - pt.easting,
        latitudeCorrected: pt.adjustedNorthing - pt.northing,
        easting: pt.adjustedEasting,
        northing: pt.adjustedNorthing,
      })),
      angularMisclosureSec: pkg.traverse.angularMisclosure,
      angularToleranceSec: angularClosureTolerance(pkg.traverse.points.length),
      angularPassesQA: pkg.traverse.angularMisclosure <= angularClosureTolerance(pkg.traverse.points.length),
      linearMisclosureM: pkg.traverse.linearMisclosure,
      perimeterM: pkg.traverse.perimeterM,
      precisionRatio: parseInt(pkg.traverse.precisionRatio.replace('1:', '')),
      precisionMinimum: 5000,
      linearPassesQA: true,
    },
    adjustedStations: pkg.traverse.points.map(pt => ({
      label: pt.pointName,
      easting: pt.adjustedEasting,
      northing: pt.adjustedNorthing,
    })),
    levelling: null,
    areaComputation: {
      stations: pkg.traverse.points.map(pt => ({
        label: pt.pointName,
        easting: pt.adjustedEasting,
        northing: pt.adjustedNorthing,
      })),
      areaM2: pkg.traverse.areaM2,
      areaHa: pkg.traverse.areaM2 / 10000,
      perimeterM: pkg.traverse.perimeterM,
    },
    legs: pkg.traverse.points.map((pt, i) => ({
      fromLabel: pt.pointName,
      toLabel: pkg.traverse.points[(i + 1) % pkg.traverse.points.length]?.pointName ?? '',
      bearing: pt.observedBearing,
      distance: pt.observedDistance,
    })),
    cogoResults: null,
  })
  const workingDiagram = generateWorkingDiagramDXF(pkg)

  const zip = new JSZip()
  zip.file('form_no_4.dxf', formNo4Dxf)
  zip.file('computation_workbook.xlsx', workbook)
  zip.file('working_diagram.dxf', workingDiagram)

  // Supporting documents - PPA2 (always included)
  // ponytail: cast via unknown — the query result `project` is typed as
  // Record<string, unknown> after the Phase 6 queryBuilder tightening, so each
  // property access yields `unknown`. The PDF generator handles stringification
  // at runtime; the cast preserves the legacy `any`-typed behavior.
  const ppa2Input = {
    lrNumber: project.lr_number,
    parcelNumber: project.parcel_number,
    county: project.county,
    division: project.division,
    district: project.district,
    locality: project.locality,
    areaHa: computedAreaM2 / 10000,
    surveyType: project.survey_subtype ?? project.survey_type ?? 'Cadastral',
    applicantName: project.client_name ?? '',
    applicantAddress: project.client_address ?? '',
    applicantIdNumber: project.client_id_number,
    surveyorName: surveyor.full_name,
    iskNumber: surveyor.registration_number,
    firmName: surveyor.firm_name ?? '',
    surveyDate: project.survey_date ?? new Date().toISOString(),
    referenceNumber: ref,
  } as unknown as PPA2Input
  zip.file('supporting_docs/ppa2_form.pdf', generatePPA2Form(ppa2Input))

  // Supporting documents - LCB Consent (always included)
  // ponytail: same as PPA2 above — cast via unknown to preserve legacy runtime.
  const lcbInput = {
    lrNumber: project.lr_number,
    parcelNumber: project.parcel_number,
    county: project.county,
    division: project.division,
    district: project.district,
    areaHa: computedAreaM2 / 10000,
    landUse: project.land_use ?? 'Agricultural',
    transferorName: project.owner_name ?? '',
    transfereeName: project.client_name ?? '',
    transferorIdNumber: project.owner_id_number,
    transfereeIdNumber: project.client_id_number,
    surveyorName: surveyor.full_name,
    iskNumber: surveyor.registration_number,
    surveyDate: project.survey_date ?? new Date().toISOString(),
    referenceNumber: ref,
    lbcApplicationNumber: project.lbc_application_number,
  } as unknown as LCBConsentInput
  zip.file('supporting_docs/lcb_consent.pdf', generateLCBConsent(lcbInput))

  // Supporting documents - Mutation Form (only for mutation subtype)
  if (project.survey_subtype === 'mutation') {
    // ponytail: same as PPA2 above — cast via unknown to preserve legacy runtime.
    const mutationInput = {
      parentLRNumber: project.lr_number,
      parentParcelNumber: project.parcel_number,
      parentAreaHa: project.parent_area_ha ?? computedAreaM2 / 10000,
      resultingParcels: project.resulting_parcels ?? [],
      county: project.county,
      division: project.division,
      district: project.district,
      locality: project.locality,
      registryMapSheet: project.registry_map_sheet ?? '',
      mutationType: 'subdivision' as const,
      reasonForMutation: project.mutation_reason ?? 'Subdivision',
      affectedBeacons: adjustedCoordinates.map((st, i) => ({
        beaconId: st.label,
        action: 'new' as const,
        easting: st.easting,
        northing: st.northing,
      })),
      surveyorName: surveyor.full_name,
      iskNumber: surveyor.registration_number,
      firmName: surveyor.firm_name ?? '',
      surveyDate: project.survey_date ?? new Date().toISOString(),
      referenceNumber: ref,
      mutationNumber: project.mutation_number,
    } as unknown as MutationFormInput
    zip.file('supporting_docs/mutation_form.pdf', generateMutationForm(mutationInput))
  }

  const manifest = {
    submissionRef: ref,
    generatedAt: pkg.generatedAt,
    surveyor: pkg.surveyor.registrationNumber,
    lrNumber: pkg.parcel.lrNumber,
    areaHa: (pkg.parcel.areaM2 / 10000).toFixed(4),
    areaM2: pkg.parcel.areaM2.toFixed(2),
    perimeterM: pkg.traverse.perimeterM.toFixed(3),
    precisionRatio: pkg.traverse.precisionRatio,
    adjustmentMethod: pkg.traverse.adjustmentMethod,
    files: ['form_no_4.dxf', 'computation_workbook.xlsx', 'working_diagram.dxf', 'manifest.json'],
    supportingDocuments: pkg.supportingDocs.map(d => d.type).filter(Boolean),
    qaResult: qa
  }
  zip.file('manifest.json', JSON.stringify(manifest, null, 2))

  const zipBuffer = await zip.generateAsync({ type: 'nodebuffer' })

  // Get user from NextAuth session
  const authSession = await getServerSession(authOptions)
  const userId = (authSession?.user as { id?: string } | undefined)?.id ?? ''
  
  const { rows: profileRows } = await db.query<SurveyorProfileRow>(
    'SELECT id, user_id, isk_number, verified_isk FROM surveyor_profiles WHERE user_id = $1 LIMIT 1',
    [userId]
  )
  const profile = profileRows[0]

  if (!profile) {
    throw new Error('Surveyor profile not found')
  }

  const currentYear = new Date().getFullYear()
  const { rows: existingRows } = await db.query<ProjectSubmissionRow>(
    'SELECT revision_number FROM project_submissions WHERE project_id = $1 ORDER BY revision_number DESC LIMIT 1',
    [projectId]
  )

  const revisionNumber = (existingRows[0]?.revision_number ?? -1) + 1

  // Direct SQL replaces dbClient.rpc('increment_submission_sequence')
  const { rows: seqRows } = await db.query<SubmissionSequenceRow>(
    `INSERT INTO submission_sequences (surveyor_profile_id, year, current_sequence)
     VALUES ($1, $2, 1)
     ON CONFLICT (surveyor_profile_id, year)
     DO UPDATE SET current_sequence = submission_sequences.current_sequence + 1
     RETURNING current_sequence`,
    [profile.id, currentYear]
  )

  const sequence = seqRows[0]?.current_sequence ?? 1
  const submissionNumber = `${profile.isk_number}_${currentYear}_${String(sequence).padStart(3, '0')}_R${String(revisionNumber).padStart(2, '0')}`

  await db.query<never>(
    `INSERT INTO project_submissions (project_id, surveyor_profile_id, submission_number, revision_code, submission_year, package_status, generated_artifacts, validation_results)
     VALUES ($1, $2, $3, $4, $5, 'ready', $6, $7)`,
    [
      projectId,
      profile.id,
      submissionNumber,
      `R${String(revisionNumber).padStart(2, '0')}`,
      currentYear,
      JSON.stringify({
        form_no_4: 'form_no_4.dxf',
        computation_workbook: 'computation_workbook.xlsx',
        working_diagram: 'working_diagram.dxf'
      }),
      JSON.stringify(qa)
    ]
  )

  return { zipBuffer, ref, qa }
}

import { jsPDF } from 'jspdf'
import type { SubmissionPackage } from '../types'
import { PlanGeometry, computePlanGeometry } from '@/lib/engine/planGeometry'
import { formatPlanDate, formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers'

function stationsToAdjusted(pkg: SubmissionPackage) {
  return pkg.traverse.points.map((p) => ({
    pointName: p.pointName,
    originalEasting: p.easting,
    originalNorthing: p.northing,
    adjustedEasting: p.adjustedEasting,
    adjustedNorthing: p.adjustedNorthing
  }))
}

export function generateFormNo4PDF(pkg: SubmissionPackage): Buffer {
  const stations = stationsToAdjusted(pkg)
  const geometry = computePlanGeometry(stations)
  
  if (!geometry) {
    return Buffer.from('')
  }

  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3'
  })

  const pageWidth = 420
  const pageHeight = 297
  const margin = 10
  const titleBlockHeight = 65
  const planAreaWidth = pageWidth - margin * 2
  const planAreaHeight = pageHeight - margin * 2 - titleBlockHeight

  const scale = geometry.scale
  const ext = geometry.extent
  const padding = 10
  const drawableWidth = planAreaWidth - padding * 2
  const drawableHeight = planAreaHeight - padding * 2

  const plotWidth = ext.width
  const plotHeight = ext.height
  const scaleX = drawableWidth / plotWidth
  const scaleY = drawableHeight / plotHeight
  const plotScale = Math.min(scaleX, scaleY)

  const offsetX = margin + padding + (drawableWidth - plotWidth * plotScale) / 2
  const offsetY = margin + padding + (drawableHeight - plotHeight * plotScale) / 2

  function toPlotX(easting: number): number {
    return offsetX + (easting - ext.minEasting) * plotScale
  }

  function toPlotY(northing: number): number {
    return offsetY + (ext.maxNorthing - northing) * plotScale
  }

  doc.setLineWidth(0.3)
  doc.setDrawColor(0)

  for (let i = 0; i < geometry.edges.length; i++) {
    const edge = geometry.edges[i]
    const x1 = toPlotX(edge.from.adjustedEasting)
    const y1 = toPlotY(edge.from.adjustedNorthing)
    const x2 = toPlotX(edge.to.adjustedEasting)
    const y2 = toPlotY(edge.to.adjustedNorthing)
    doc.line(x1, y1, x2, y2)
  }

  doc.setFontSize(8)
  doc.setTextColor(0)
  for (const station of geometry.stations) {
    const x = toPlotX(station.adjustedEasting)
    const y = toPlotY(station.adjustedNorthing)
    doc.circle(x, y, 1.5, 'S')
    doc.text(station.pointName, x + 2, y - 1)
  }

  doc.setFontSize(6)
  doc.setTextColor(100)
  for (let i = 0; i < geometry.edges.length; i++) {
    const edge = geometry.edges[i]
    const x1 = toPlotX(edge.from.adjustedEasting)
    const y1 = toPlotY(edge.from.adjustedNorthing)
    const x2 = toPlotX(edge.to.adjustedEasting)
    const y2 = toPlotY(edge.to.adjustedNorthing)
    const midX = (x1 + x2) / 2
    const midY = (y1 + y2) / 2
    const bearText = formatBearingDMS(edge.bearing)
    const distText = formatDistanceM(edge.distance) + 'm'
    doc.text(bearText, midX - 5, midY - 2)
    doc.text(distText, midX - 5, midY + 2)
  }

  doc.setFontSize(10)
  doc.setTextColor(0)
  const areaText = `Area = ${geometry.areaHa.toFixed(4)} Ha`
  const centroidPlotX = toPlotX(geometry.centroid.easting)
  const centroidPlotY = toPlotY(geometry.centroid.northing)
  doc.text(areaText, centroidPlotX, centroidPlotY)

  const titleBlockY = pageHeight - margin - titleBlockHeight + 5

  doc.setFontSize(8)
  doc.text('REPUBLIC OF KENYA', margin, titleBlockY + 4)
  doc.text('SURVEY OF KENYA', margin, titleBlockY + 9)
  doc.text('FORM NO. 4 — SURVEY PLAN', margin, titleBlockY + 14)

  doc.setFontSize(7)
  doc.text(`LR No: ${pkg.parcel.lrNumber}`, margin, titleBlockY + 21)
  doc.text(`Parcel No: ${pkg.parcel.parcelNumber || pkg.parcel.lrNumber}`, margin, titleBlockY + 26)
  doc.text(`County: ${pkg.parcel.county}`, margin, titleBlockY + 31)
  doc.text(`Division: ${pkg.parcel.division || '-'}`, margin, titleBlockY + 36)
  doc.text(`District: ${pkg.parcel.district}`, margin, titleBlockY + 41)
  doc.text(`Locality: ${pkg.parcel.locality}`, margin, titleBlockY + 46)
  if (pkg.parcel.clientName) {
    doc.text(`Client: ${pkg.parcel.clientName}`, margin, titleBlockY + 51)
  }

  const col2X = margin + 60
  doc.text(`Area: ${geometry.areaHa.toFixed(4)} Ha`, col2X, titleBlockY + 21)
  doc.text(`Perimeter: ${geometry.perimeterM.toFixed(3)} m`, col2X, titleBlockY + 26)
  doc.text(`Surveyor: ${pkg.surveyor.fullName}`, col2X, titleBlockY + 31)
  doc.text(`ISK No: ${pkg.surveyor.iskNumber || pkg.surveyor.registrationNumber}`, col2X, titleBlockY + 36)
  doc.text(`Firm: ${pkg.surveyor.firmName}`, col2X, titleBlockY + 41)
  doc.text(`Survey Date: ${formatPlanDate(pkg.generatedAt)}`, col2X, titleBlockY + 46)
  
  if (pkg.surveyor.verifiedIsk) {
    doc.setFontSize(7)
    doc.setTextColor(34, 139, 34)
    doc.text(' ISK VERIFIED', col2X + 45, titleBlockY + 36)
    doc.setTextColor(0)
  }

  const col3X = margin + 120
  doc.text(`Scale: 1:${scale}`, col3X, titleBlockY + 21)
  doc.text(`Coord: Arc 1960 / UTM Zone 37S (SRID: 21037)`, col3X, titleBlockY + 26)
  doc.text(`Ref: ${pkg.submissionRef}`, col3X, titleBlockY + 31)
  doc.text(`Sheet: 1 of 1  Rev: R${String(pkg.revision).padStart(2, '0')}`, col3X, titleBlockY + 36)

  doc.line(margin, titleBlockY + 50, pageWidth - margin, titleBlockY + 50)

  doc.setFontSize(6)
  doc.text('GN', pageWidth - margin - 10, margin + 10)
  doc.line(pageWidth - margin - 8, margin + 5, pageWidth - margin - 8, margin + 20)
  doc.line(pageWidth - margin - 12, margin + 8, pageWidth - margin - 8, margin + 5)
  doc.line(pageWidth - margin - 4, margin + 8, pageWidth - margin - 8, margin + 5)

  const scaleBarLength = 50
  const scaleBarX = pageWidth - margin - scaleBarLength - 5
  const scaleBarY = margin + 25
  doc.line(scaleBarX, scaleBarY, scaleBarX + scaleBarLength, scaleBarY)
  doc.line(scaleBarX, scaleBarY - 2, scaleBarX, scaleBarY + 2)
  doc.line(scaleBarX + scaleBarLength, scaleBarY - 2, scaleBarX + scaleBarLength, scaleBarY + 2)
  doc.setFontSize(5)
  doc.text(`Scale 1:${scale}`, scaleBarX, scaleBarY - 4)

  const pdfBuffer = doc.output('arraybuffer') as ArrayBuffer
  return Buffer.from(pdfBuffer)
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Pre-Submission Validator
// ──────────────────────────────────────────────────────────────────────────
// Checks everything NLIMS/Survey of Kenya needs BEFORE the surveyor
// clicks "Submit". Catches problems early so they don't waste time
// with rejected submissions.
//
// Run this BEFORE assembleSubmissionPackage() to give the surveyor
// a clear checklist of what's ready and what's missing.
//
// Usage:
//   const check = await preSubmitCheck(projectId);
//   if (check.ready) {
//     // All good — proceed with submission
//   } else {
//     // Show check.issues to the surveyor
//   }
// ──────────────────────────────────────────────────────────────────────────

export interface PreSubmitCheckResult {
  /** Overall readiness */
  ready: boolean;
  /** Score: 0-100 (100 = perfect, ready to submit) */
  score: number;
  /** Grouped checks */
  categories: CheckCategory[];
  /** Summary message */
  summary: string;
  /** Number of blocking issues */
  blockers: number;
  /** Number of warnings (non-blocking) */
  warnings: number;
}

export interface CheckCategory {
  name: string;
  icon: string;
  items: CheckItem[];
  passed: number;
  total: number;
}

export interface CheckItem {
  label: string;
  status: 'pass' | 'fail' | 'warning' | 'skip';
  detail?: string;
  /** true = blocks submission, false = warning only */
  blocking: boolean;
}

// ─── Main Function ───────────────────────────────────────────────────────

/**
 * Run all pre-submission checks on a project.
 *
 * @param project - Project data from the database
 * @param surveyPoints - Survey points for this project
 * @param traverseResult - Computed traverse result (if available)
 * @returns Complete readiness report
 */
export function preSubmitCheck(project: {
  lr_number?: string;
  parcel_number?: string;
  county?: string;
  sub_county?: string;
  division?: string;
  locality?: string;
  client_name?: string;
  survey_type?: string;
  area_m2?: number;
  perimeter_m?: number;
  precision_ratio?: string;
  linear_misclosure?: number;
  angular_misclosure?: number;
  closing_error_e?: number;
  closing_error_n?: number;
  survey_points?: unknown[];
  supporting_documents?: unknown[];
  subtype?: string;
}, surveyPoints?: Array<{
  name: string;
  easting: number;
  northing: number;
  type?: string;
}>, traverseResult?: {
  precisionRatio: number;
  passes: boolean;
  totalDistance: number;
  linearError: number;
}): PreSubmitCheckResult {
  const categories: CheckCategory[] = [];

  // ── Category 1: Project Information ──
  categories.push(checkProjectInfo(project));

  // ── Category 2: Survey Control ──
  categories.push(checkSurveyControl(surveyPoints));

  // ── Category 3: Traverse Accuracy ──
  categories.push(checkTraverseAccuracy(project, traverseResult));

  // ── Category 4: Area & Boundary ──
  categories.push(checkAreaBoundary(project, surveyPoints));

  // ── Category 5: Documents ──
  categories.push(checkDocuments(project));

  // ── Category 6: Compliance ──
  categories.push(checkCompliance(project));

  // ── Calculate score ──
  let totalItems = 0;
  let passedItems = 0;
  let blockers = 0;
  let warnings = 0;

  for (const cat of categories) {
    for (const item of cat.items) {
      totalItems++;
      if (item.status === 'pass') passedItems++;
      if (item.status === 'fail' && item.blocking) blockers++;
      if (item.status === 'warning') warnings++;
    }
  }

  const score = totalItems > 0 ? Math.round((passedItems / totalItems) * 100) : 0;
  const ready = blockers === 0 && score >= 80;

  const summary = ready
    ? `✓ Ready to submit (${score}% complete, ${warnings} advisory notes)`
    : `✗ NOT ready — ${blockers} blocking issue(s), ${warnings} warning(s). Fix blockers before submitting.`;

  return { ready, score, categories, summary, blockers, warnings };
}

// ─── Check Categories ────────────────────────────────────────────────────

function checkProjectInfo(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  items.push({
    label: 'LR Number',
    status: project.lr_number ? 'pass' : 'fail',
    detail: project.lr_number || 'Required for all cadastral surveys',
    blocking: true,
  });

  items.push({
    label: 'Parcel Number',
    status: project.parcel_number ? 'pass' : 'fail',
    detail: project.parcel_number || 'Required for NLIMS lookup',
    blocking: true,
  });

  items.push({
    label: 'County',
    status: project.county ? 'pass' : 'fail',
    detail: project.county || 'Required',
    blocking: true,
  });

  items.push({
    label: 'Sub-County',
    status: project.sub_county ? 'pass' : 'warning',
    detail: project.sub_county || 'Recommended',
    blocking: false,
  });

  items.push({
    label: 'Client Name',
    status: project.client_name ? 'pass' : 'fail',
    detail: project.client_name || 'Required for deed plan',
    blocking: true,
  });

  items.push({
    label: 'Survey Type',
    status: project.survey_type ? 'pass' : 'fail',
    detail: project.survey_type || 'Must be one of 9 survey types',
    blocking: true,
  });

  return {
    name: 'Project Information',
    icon: '📋',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkSurveyControl(points?: Array<{ name: string; type?: string }>): CheckCategory {
  const items: CheckItem[] = [];

  if (!points || points.length === 0) {
    items.push({
      label: 'Survey Points',
      status: 'fail',
      detail: 'No survey points recorded',
      blocking: true,
    });
    return { name: 'Survey Control', icon: '📐', items, passed: 0, total: 1 };
  }

  items.push({
    label: 'Point Count',
    status: points.length >= 3 ? 'pass' : 'fail',
    detail: `${points.length} points (minimum 3 for a polygon)`,
    blocking: true,
  });

  const controlPoints = points.filter((p) => p.type === 'control' || p.type === 'beacon');
  items.push({
    label: 'Control Points',
    status: controlPoints.length >= 2 ? 'pass' : 'warning',
    detail: `${controlPoints.length} control/beacon points (minimum 2 recommended)`,
    blocking: false,
  });

  const hasBeacons = points.some((p) => p.type === 'beacon');
  items.push({
    label: 'Beacon Identification',
    status: hasBeacons ? 'pass' : 'warning',
    detail: hasBeacons ? 'Beacon points identified' : 'No beacon points tagged',
    blocking: false,
  });

  return {
    name: 'Survey Control',
    icon: '📐',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkTraverseAccuracy(
  project: Parameters<typeof preSubmitCheck>[0],
  traverseResult?: Parameters<typeof preSubmitCheck>[2],
): CheckCategory {
  const items: CheckItem[] = [];

  // Check precision ratio
  const ratioStr = project.precision_ratio;
  if (ratioStr) {
    const match = ratioStr.match(/1\s*:\s*([\d,]+)/);
    const ratio = match ? parseInt(match[1].replace(/,/g, ''), 10) : 0;

    items.push({
      label: 'Precision Ratio',
      status: ratio >= 5000 ? 'pass' : ratio >= 1000 ? 'warning' : 'fail',
      detail: ratioStr + (ratio >= 5000 ? ' (meets cadastral standard)' : ' (below 1:5,000 cadastral minimum)'),
      blocking: ratio < 1000,
    });
  } else {
    items.push({
      label: 'Precision Ratio',
      status: 'fail',
      detail: 'Not computed — run traverse adjustment first',
      blocking: true,
    });
  }

  // Check angular misclosure
  if (project.angular_misclosure !== undefined && project.angular_misclosure !== null) {
    items.push({
      label: 'Angular Misclosure',
      status: 'pass',
      detail: `${project.angular_misclosure}″`,
      blocking: false,
    });
  }

  // Check linear misclosure
  if (project.linear_misclosure !== undefined && project.linear_misclosure !== null) {
    const lm = project.linear_misclosure;
    items.push({
      label: 'Linear Misclosure',
      status: lm < 0.05 ? 'pass' : lm < 0.1 ? 'warning' : 'fail',
      detail: `${lm.toFixed(4)} m`,
      blocking: lm >= 0.5,
    });
  }

  // Check closure from traverse result
  if (traverseResult) {
    items.push({
      label: 'Traverse Closure',
      status: traverseResult.passes ? 'pass' : 'fail',
      detail: traverseResult.passes
        ? `1:${traverseResult.precisionRatio.toLocaleString()} — passes`
        : `1:${traverseResult.precisionRatio.toLocaleString()} — FAILS`,
      blocking: !traverseResult.passes,
    });
  }

  return {
    name: 'Traverse Accuracy',
    icon: '🎯',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkAreaBoundary(
  project: Parameters<typeof preSubmitCheck>[0],
  points?: Array<{ easting: number; northing: number }>,
): CheckCategory {
  const items: CheckItem[] = [];

  if (project.area_m2 && project.area_m2 > 0) {
    const ha = project.area_m2 / 10000;
    items.push({
      label: 'Area Computed',
      status: 'pass',
      detail: `${project.area_m2.toFixed(2)} m² (${ha.toFixed(4)} ha)`,
      blocking: false,
    });

    // Sanity check: very small or very large parcels
    if (ha < 0.001) {
      items.push({
        label: 'Area Sanity Check',
        status: 'warning',
        detail: `Area is very small (${ha.toFixed(6)} ha) — verify coordinates`,
        blocking: false,
      });
    }
  } else {
    items.push({
      label: 'Area Computed',
      status: 'fail',
      detail: 'Area not computed — need at least 3 boundary points',
      blocking: true,
    });
  }

  // Check perimeter
  if (project.perimeter_m && project.perimeter_m > 0) {
    items.push({
      label: 'Perimeter',
      status: 'pass',
      detail: `${project.perimeter_m.toFixed(2)} m`,
      blocking: false,
    });
  }

  // Check closing errors
  if (project.closing_error_e !== undefined && project.closing_error_n !== undefined) {
    const ce = Math.abs(project.closing_error_e);
    const cn = Math.abs(project.closing_error_n);
    const misclosure = Math.sqrt(ce * ce + cn * cn);

    items.push({
      label: 'Boundary Closure',
      status: misclosure < 0.01 ? 'pass' : misclosure < 0.05 ? 'warning' : 'fail',
      detail: `E: ${ce.toFixed(4)}m, N: ${cn.toFixed(4)}m, Total: ${misclosure.toFixed(4)}m`,
      blocking: misclosure >= 0.5,
    });
  }

  return {
    name: 'Area & Boundary',
    icon: '📐',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkDocuments(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  const docs = project.supporting_documents || [];
  items.push({
    label: 'Supporting Documents',
    status: docs.length > 0 ? 'pass' : 'warning',
    detail: `${docs.length} document(s) attached`,
    blocking: false,
  });

  return {
    name: 'Documents',
    icon: '📄',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkCompliance(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  // Survey Act Cap. 299 checks
  items.push({
    label: 'Survey Act Cap. 299',
    status: 'pass',
    detail: 'All computations follow Kenya Survey Regulations 1994',
    blocking: false,
  });

  // Check survey subtype
  const validSubtypes = [
    'cadastral', 'engineering', 'topographic', 'geodetic',
    'mining', 'hydrographic', 'drone', 'deformation', 'mixed',
  ];
  items.push({
    label: 'Survey Classification',
    status: project.subtype && validSubtypes.includes(project.subtype) ? 'pass' : 'warning',
    detail: project.subtype || 'Not classified',
    blocking: false,
  });

  return {
    name: 'Compliance',
    icon: '⚖️',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

import type {
  SubmissionPackage,
  QAGateResult,
  QABlocker,
  QAWarning
} from './types'

import { TRAVERSE_PRECISION_STANDARDS, angularClosureTolerance } from '@/lib/engine/traverse'

const LEVELLING_TOLERANCE: Record<string, number> = {
  first_order: 3,
  second_order: 6,
  third_order: 12,
  fourth_order: 20,
}

const SUBTYPE_TO_SURVEY_TYPE: Record<string, keyof typeof TRAVERSE_PRECISION_STANDARDS> = {
  cadastral_subdivision: 'cadastral',
  cadastral_amalgamation: 'cadastral',
  cadastral_resurvey: 'cadastral',
  cadastral_mutation: 'cadastral',
  topographic_site: 'topographic',
  topographic_corridor: 'topographic',
  engineering_road: 'engineering',
  engineering_bridge: 'engineering',
  engineering_dam: 'engineering',
  geodetic_control: 'geodetic',
  mining: 'mining',
  hydrographic: 'hydrographic',
  drone: 'drone',
  deformation: 'deformation',
}

export function validateSubmission(pkg: SubmissionPackage): QAGateResult {
  const blockers: QABlocker[] = []
  const warnings: QAWarning[] = []

  if (!pkg.surveyor.registrationNumber) {
    blockers.push({
      code: 'NO_REG_NUMBER',
      message: 'Surveyor registration number is missing. Update your profile before submitting.'
    })
  }

  if (!pkg.surveyor.isKMemberActive) {
    warnings.push({
      code: 'ISK_INACTIVE',
      message: 'ISK membership may not be current. Verify before submission to Director of Surveys.'
    })
  }

  if (!pkg.parcel.lrNumber) {
    blockers.push({
      code: 'NO_LR_NUMBER',
      message: 'LR Number is required for cadastral submission.'
    })
  }

  if (!pkg.parcel.county) {
    blockers.push({
      code: 'NO_COUNTY',
      message: 'County is required on Form No. 4.'
    })
  }

  if (!pkg.parcel.district) {
    blockers.push({
      code: 'NO_DISTRICT',
      message: 'District is required for cadastral submission per Survey Act Cap 299.'
    })
  }

  if (!pkg.parcel.locality) {
    warnings.push({
      code: 'NO_LOCALITY',
      message: 'Locality not specified. Recommended for Director of Surveys clarity.'
    })
  }

  const surveyType = SUBTYPE_TO_SURVEY_TYPE[pkg.subtype] || 'cadastral'
  const requiredPrecision = TRAVERSE_PRECISION_STANDARDS[surveyType]
  const precisionParts = pkg.traverse.precisionRatio.split(':')
  const denominator = parseInt(precisionParts[1], 10)

  if (isNaN(denominator) || denominator < requiredPrecision) {
    blockers.push({
      code: 'PRECISION_FAILURE',
      message: `Traverse precision ${pkg.traverse.precisionRatio} does not meet minimum 1:${requiredPrecision} required for ${pkg.subtype}.`
    })
  }

  if (pkg.traverse.points.length < 3) {
    blockers.push({
      code: 'INSUFFICIENT_POINTS',
      message: 'A minimum of 3 survey points are required.'
    })
  }

  const requiredDocs = pkg.supportingDocs.filter(d => d.required)
  const missingDocs = requiredDocs.filter(d => !d.fileUrl)

  missingDocs.forEach(doc => {
    blockers.push({
      code: `MISSING_DOC_${doc.type.toUpperCase()}`,
      message: `${doc.label} is required for this submission type and has not been uploaded.`
    })
  })

  if (pkg.parcel.areaM2 <= 0) {
    blockers.push({
      code: 'INVALID_AREA',
      message: 'Computed parcel area is zero or negative. Check traverse computation.'
    })
  }

  const angularTolerance = angularClosureTolerance(pkg.traverse.points.length)
  if (pkg.traverse.angularMisclosure > angularTolerance) {
    blockers.push({
      code: 'ANGULAR_MISCLOSURE_EXCEEDED',
      message: `Angular misclosure ${(pkg.traverse.angularMisclosure).toFixed(1)}" exceeds 20√n = ${(20 * Math.sqrt(pkg.traverse.points.length)).toFixed(1)}" limit.`
    })
  }

  const perimeterKm = pkg.traverse.perimeterM / 1000
  const levellingTolerance = 10 * Math.sqrt(perimeterKm)
  if (pkg.traverse.linearMisclosure > levellingTolerance / 1000) {
    warnings.push({
      code: 'LEVELLING_TOLERANCE_WARNING',
      message: `Linear misclosure may exceed 10√K mm tolerance. Verify levelling computations per RDM 1.1 Table 5.1.`
    })
  }

  if (pkg.revision > 1) {
    warnings.push({
      code: 'MULTIPLE_REVISIONS',
      message: `This is revision R${pkg.revision.toString().padStart(2, '0')}. Ensure all previous comments from Director of Surveys have been addressed.`
    })
  }

  return {
    passed: blockers.length === 0,
    blockers,
    warnings
  }
}

export function getSubmissionChecklist(subtype: string): { code: string; label: string; required: boolean }[] {
  const surveyType = SUBTYPE_TO_SURVEY_TYPE[subtype] || 'cadastral'
  const minPrecision = TRAVERSE_PRECISION_STANDARDS[surveyType]
  
  const base = [
    { code: 'COORD_SYS', label: 'Coordinate system specified (Arc 1960 / UTM Zone 37S)', required: true },
    { code: 'SURVEYOR_PROFILE', label: 'Licensed surveyor profile complete (ISK Reg. No.)', required: true },
    { code: 'LR_NUMBER', label: 'LR Number specified', required: true },
    { code: 'COUNTY', label: 'County specified', required: true },
    { code: 'DISTRICT', label: 'District specified', required: true },
    { code: 'AREA_COMPUTED', label: 'Parcel area computed and > 0', required: true },
    { code: 'PRECISION', label: `Traverse precision meets 1:${minPrecision}`, required: true },
    { code: 'BEACONS', label: 'Beacon types and positions verified', required: true },
    { code: 'FORM_NO4', label: 'Form No. 4 (Mutation Form) generated', required: true },
    { code: 'DXF_PLAN', label: 'DXF plan with TitleBlock generated', required: true },
  ]

  const cadastralExtras = [
    { code: 'PPA2', label: 'PPA2 (Permission to Amend) attached', required: true },
    { code: 'LCB_CONSENT', label: 'Land Control Board consent attached', required: true },
    { code: 'BEACON_CERT', label: 'Beacon completion certificate attached', required: true },
    { code: 'SEARCH_CERT', label: 'Official search certificate attached', required: false },
  ]

  const topoExtras = [
    { code: 'CONTOURS', label: 'Contour interval matches spec', required: true },
    { code: 'SPOT_HEIGHTS', label: 'Spot heights verified against field book', required: true },
    { code: 'IDW_COMPUTED', label: 'IDW interpolation completed', required: true },
  ]

  const engineeringExtras = [
    { code: 'HORIZONTAL_CURVE', label: 'Horizontal curve computation verified', required: true },
    { code: 'SUPERELEVATION', label: 'Superelevation within RDM 1.1 limits', required: true },
    { code: 'VERTICAL_CURVE', label: 'Vertical curve K-value meets SSD requirements', required: true },
    { code: 'EARTHWORKS', label: 'Cross-section volumes computed', required: false },
  ]

  if (subtype.startsWith('cadastral')) {
    return [...base, ...cadastralExtras]
  }
  if (subtype.startsWith('topographic')) {
    return [...base, ...topoExtras]
  }
  if (subtype.startsWith('engineering')) {
    return [...base, ...engineeringExtras]
  }

  return base
}

/**
 * As-Built Comparison Engine — batch comparison of field shots vs design
 *
 * PROBLEM
 * -------
 * The existing checkCoordinate() in settingOutEngine.ts compares ONE
 * observation to ONE design point. For the setting-out loop, we need to:
 *   1. Take a batch of as-built field shots (from the total station)
 *   2. Match each to the nearest design point (by ID or by proximity)
 *   3. Compute dE, dN, dH for each
 *   4. Flag anything outside tolerance — BEFORE the crew leaves site
 *   5. Produce a summary: "47/50 points within ±25mm. 3 points flagged."
 *
 * This is the "no stress" closer: the surveyor captures as-built shots,
 * and the app immediately says green/red per point, before they leave site.
 *
 * USAGE
 * -----
 *   import { compareAsBuiltToDesign } from '@/lib/survey/asBuiltComparison'
 *
 *   const report = compareAsBuiltToDesign({
 *     designPoints: [...],
 *     asBuiltPoints: [...],
 *     toleranceH: 0.025,  // ±25mm horizontal
 *     toleranceV: 0.015,  // ±15mm vertical
 *   })
 *
 *   if (report.failedPoints.length > 0) {
 *     // "3 points flagged. Re-stake before leaving site."
 *   }
 */

import type { DesignPoint } from '@/lib/computations/settingOutEngine'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface AsBuiltPoint {
  /** Point ID — should match a design point ID for automatic matching */
  id?: string
  /** Easting (meters) */
  e: number
  /** Northing (meters) */
  n: number
  /** Reduced level / elevation (meters) */
  rl?: number
  /** Description */
  description?: string
}

export interface ComparisonRow {
  /** Design point ID */
  designId: string
  /** As-built point ID (if matched by ID) */
  asBuiltId?: string
  /** Design coordinates */
  designE: number
  designN: number
  designRL: number
  /** As-built coordinates */
  asBuiltE: number
  asBuiltN: number
  asBuiltRL: number | null
  /** Offsets */
  deltaE: number  // meters
  deltaN: number
  deltaRL: number | null
  /** Horizontal offset (sqrt(dE² + dN²)) */
  horizontalOffset: number
  /** Status flags */
  hStatus: 'PASS' | 'FAIL'
  vStatus: 'PASS' | 'FAIL' | 'N/A'
  /** Whether this point is within tolerance */
  passed: boolean
  /** Matching method used */
  matchedBy: 'id' | 'proximity' | 'unmatched'
}

export interface ComparisonReport {
  /** Per-point comparison results */
  rows: ComparisonRow[]
  /** Points that passed all tolerance checks */
  passedPoints: ComparisonRow[]
  /** Points that failed horizontal or vertical tolerance */
  failedPoints: ComparisonRow[]
  /** Design points that were not matched to any as-built shot */
  unmatchedDesignPoints: DesignPoint[]
  /** As-built points that were not matched to any design point */
  unmatchedAsBuiltPoints: AsBuiltPoint[]

  /** Summary statistics */
  totalDesignPoints: number
  totalAsBuiltPoints: number
  totalMatched: number
  totalPassed: number
  totalFailed: number

  /** Overall verdict */
  verdict: 'PASS' | 'FAIL' | 'INCOMPLETE'
  /** Human-readable summary */
  summary: string

  /** Tolerances used */
  toleranceH: number
  toleranceV: number

  /** Timestamp */
  timestamp: string
}

export interface ComparisonInput {
  designPoints: DesignPoint[]
  asBuiltPoints: AsBuiltPoint[]
  /** Horizontal tolerance in meters (default: 0.025 = 25mm, RDM 1.1 Table 5.2) */
  toleranceH?: number
  /** Vertical tolerance in meters (default: 0.015 = 15mm, RDM 1.1 Table 5.2) */
  toleranceV?: number
  /** Max distance for proximity matching in meters (default: 5.0) */
  proximityMaxM?: number
}

// ─── Main Function ──────────────────────────────────────────────────────────

/**
 * Compare as-built field shots to design points and flag anything outside
 * tolerance.
 *
 * Matching strategy:
 *   1. If as-built point has an ID that matches a design point ID → match by ID
 *   2. Otherwise, find the nearest design point within proximityMaxM → match by proximity
 *   3. If no match within proximity → unmatched
 *
 * @returns ComparisonReport with per-point results and overall verdict
 */
export function compareAsBuiltToDesign(input: ComparisonInput): ComparisonReport {
  const {
    designPoints,
    asBuiltPoints,
    toleranceH = 0.025,  // ±25mm per RDM 1.1 Table 5.2 (structures, buildings)
    toleranceV = 0.015,  // ±15mm
    proximityMaxM = 5.0,
  } = input

  const rows: ComparisonRow[] = []
  const matchedDesignIds = new Set<string>()
  const matchedAsBuiltIndices = new Set<number>()

  // Build a map of design points by ID for fast lookup
  const designById = new Map<string, DesignPoint>()
  for (const dp of designPoints) {
    designById.set(dp.id, dp)
  }

  // ─── Pass 1: Match by ID ───
  for (let i = 0; i < asBuiltPoints.length; i++) {
    if (matchedAsBuiltIndices.has(i)) continue
    const ab = asBuiltPoints[i]

    if (ab.id) {
      const dp = designById.get(ab.id)
      if (dp && !matchedDesignIds.has(dp.id)) {
        const row = computeRow(dp, ab, 'id', toleranceH, toleranceV)
        rows.push(row)
        matchedDesignIds.add(dp.id)
        matchedAsBuiltIndices.add(i)
      }
    }
  }

  // ─── Pass 2: Match by proximity ───
  for (let i = 0; i < asBuiltPoints.length; i++) {
    if (matchedAsBuiltIndices.has(i)) continue
    const ab = asBuiltPoints[i]

    let nearestDesign: DesignPoint | null = null
    let nearestDist = Infinity

    for (const dp of designPoints) {
      if (matchedDesignIds.has(dp.id)) continue
      const dist = Math.sqrt((dp.e - ab.e) ** 2 + (dp.n - ab.n) ** 2)
      if (dist < nearestDist && dist <= proximityMaxM) {
        nearestDist = dist
        nearestDesign = dp
      }
    }

    if (nearestDesign) {
      const row = computeRow(nearestDesign, ab, 'proximity', toleranceH, toleranceV)
      rows.push(row)
      matchedDesignIds.add(nearestDesign.id)
      matchedAsBuiltIndices.add(i)
    }
  }

  // ─── Unmatched ───
  const unmatchedDesignPoints = designPoints.filter(dp => !matchedDesignIds.has(dp.id))
  const unmatchedAsBuiltPoints = asBuiltPoints.filter((_, i) => !matchedAsBuiltIndices.has(i))

  // ─── Summary ───
  const passedPoints = rows.filter(r => r.passed)
  const failedPoints = rows.filter(r => !r.passed)

  let verdict: 'PASS' | 'FAIL' | 'INCOMPLETE'
  let summary: string

  if (rows.length === 0) {
    verdict = 'INCOMPLETE'
    summary = 'No points matched. Check that as-built point IDs match design IDs, or capture shots within 5m of design points.'
  } else if (failedPoints.length > 0) {
    verdict = 'FAIL'
    summary = `${failedPoints.length} of ${rows.length} points FAIL tolerance (${(toleranceH * 1000).toFixed(0)}mm H / ${(toleranceV * 1000).toFixed(0)}mm V). ${failedPoints.map(p => p.designId).join(', ')} — re-stake before leaving site.`
  } else if (unmatchedDesignPoints.length > 0) {
    verdict = 'INCOMPLETE'
    summary = `${passedPoints.length}/${rows.length} matched points PASS. ${unmatchedDesignPoints.length} design points not yet staked. Continue staking remaining points.`
  } else {
    verdict = 'PASS'
    summary = `All ${passedPoints.length} points within tolerance (±${(toleranceH * 1000).toFixed(0)}mm H / ±${(toleranceV * 1000).toFixed(0)}mm V). Safe to leave site.`
  }

  return {
    rows,
    passedPoints,
    failedPoints,
    unmatchedDesignPoints,
    unmatchedAsBuiltPoints,
    totalDesignPoints: designPoints.length,
    totalAsBuiltPoints: asBuiltPoints.length,
    totalMatched: rows.length,
    totalPassed: passedPoints.length,
    totalFailed: failedPoints.length,
    verdict,
    summary,
    toleranceH,
    toleranceV,
    timestamp: new Date().toISOString(),
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function computeRow(
  design: DesignPoint,
  asBuilt: AsBuiltPoint,
  matchedBy: 'id' | 'proximity',
  toleranceH: number,
  toleranceV: number,
): ComparisonRow {
  const deltaE = asBuilt.e - design.e
  const deltaN = asBuilt.n - design.n
  const deltaRL = asBuilt.rl !== undefined ? asBuilt.rl - design.rl : null
  const horizontalOffset = Math.sqrt(deltaE ** 2 + deltaN ** 2)

  const hStatus: 'PASS' | 'FAIL' = horizontalOffset <= toleranceH ? 'PASS' : 'FAIL'
  const vStatus: 'PASS' | 'FAIL' | 'N/A' = deltaRL === null ? 'N/A' : Math.abs(deltaRL) <= toleranceV ? 'PASS' : 'FAIL'
  const passed = hStatus === 'PASS' && (vStatus === 'PASS' || vStatus === 'N/A')

  return {
    designId: design.id,
    asBuiltId: asBuilt.id,
    designE: design.e,
    designN: design.n,
    designRL: design.rl,
    asBuiltE: asBuilt.e,
    asBuiltN: asBuilt.n,
    asBuiltRL: asBuilt.rl ?? null,
    deltaE,
    deltaN,
    deltaRL,
    horizontalOffset,
    hStatus,
    vStatus,
    passed,
    matchedBy,
  }
}

// ─── Display Helpers ────────────────────────────────────────────────────────

/**
 * Format a comparison row for display in a table.
 */
export function formatRowForDisplay(row: ComparisonRow): {
  id: string
  dE: string
  dN: string
  dH: string
  hOffset: string
  status: string
  statusColor: string
} {
  const passColor = 'green'
  const failColor = 'red'
  const naColor = 'gray'

  return {
    id: row.designId,
    dE: `${(row.deltaE * 1000).toFixed(1)}mm`,
    dN: `${(row.deltaN * 1000).toFixed(1)}mm`,
    dH: row.deltaRL !== null ? `${(row.deltaRL * 1000).toFixed(1)}mm` : '—',
    hOffset: `${(row.horizontalOffset * 1000).toFixed(1)}mm`,
    status: row.passed ? '✓ PASS' : '✗ FAIL',
    statusColor: row.passed ? passColor : failColor,
  }
}

/**
 * Get the verdict color for the report summary.
 */
export function getVerdictColor(verdict: 'PASS' | 'FAIL' | 'INCOMPLETE'): string {
  switch (verdict) {
    case 'PASS': return 'green'
    case 'FAIL': return 'red'
    case 'INCOMPLETE': return 'yellow'
    default: return 'gray'
  }
}

/**
 * Get the verdict icon.
 */
export function getVerdictIcon(verdict: 'PASS' | 'FAIL' | 'INCOMPLETE'): string {
  switch (verdict) {
    case 'PASS': return '✓'
    case 'FAIL': return '✗'
    case 'INCOMPLETE': return '!'
    default: return '?'
  }
}

/**
 * EDM Atmospheric Correction Module
 * 
 * Corrects measured EDM distances for atmospheric conditions
 * (temperature, pressure, humidity) using the IAG/ISO standard formula.
 * 
 * At Nairobi altitude (~1700m, P≈830hPa), uncorrected measurements
 * accumulate ~22 ppm error — that's 22mm per kilometer.
 * 
 * References:
 * - IAG Resolution (1999) for refractivity formulae
 * - ISO 17123-4:2012 for EDM testing
 * - Rüeger, J.M. (1996) "Electronic Distance Measurement"
 */

// ─── Types ───────────────────────────────────────────────────────

export type EDMWavelength = 0.6328 | 0.850 | 0.910; // μm: HeNe, IR, common IR

export interface AtmosphericConditions {
  /** Dry bulb temperature in degrees Celsius */
  temperature: number;
  /** Atmospheric pressure in hectopascals (mbar) */
  pressure: number;
  /** Relative humidity as percentage (0-100) */
  humidity: number;
}

export interface AtmosphericCorrectionResult {
  /** Original raw slope distance (meters) */
  rawDistance: number;
  /** Corrected slope distance (meters) */
  correctedDistance: number;
  /** Correction in parts per million */
  ppmCorrection: number;
  /** Absolute correction in meters */
  correctionMeters: number;
  /** First velocity correction (ppm) */
  firstVelocityCorrection: number;
  /** Second velocity correction (ppm) — small, usually < 0.1 ppm */
  secondVelocityCorrection: number;
  /** Partial water vapor pressure (hPa) used in computation */
  vaporPressure: number;
  /** Group refractivity under reference conditions */
  nRef: number;
  /** Group refractivity under observed conditions */
  nObs: number;
  /** Reference conditions used */
  referenceConditions: AtmosphericConditions;
}

export interface EDMInstrument {
  /** Carrier wavelength in micrometers */
  wavelength: EDMWavelength;
  /** Reference refractivity (N-value) — default 273.82 for most instruments */
  referenceN: number;
  /** Instrument constant in meters (additive) */
  constant: number;
  /** PPM setting on instrument (if pre-set) */
  ppmSetting: number;
}

// ─── Constants ───────────────────────────────────────────────────

/** Standard atmospheric conditions (most EDM instruments calibrated here) */
export const STANDARD_CONDITIONS: AtmosphericConditions = {
  temperature: 20,       // °C
  pressure: 1013.25,     // hPa (1 atm)
  humidity: 0,           // 0% for dry air reference
};

/** Kenya-specific typical conditions for validation */
export const KENYA_CONDITIONS = {
  nairobi: { temperature: 20, pressure: 830, humidity: 60 },
  mombasa: { temperature: 30, pressure: 1010, humidity: 75 },
  kisumu: { temperature: 24, pressure: 880, humidity: 65 },
  eldoret: { temperature: 18, pressure: 820, humidity: 70 },
} as const;

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute partial water vapor pressure using the Magnus-Tetens formula.
 * 
 * e = (RH / 100) × 6.112 × exp(17.62 × t / (243.12 + t))
 * 
 * Valid for: -45°C < t < +60°C (sufficient for all field conditions)
 * Accuracy: ±0.2 hPa over normal survey temperature range
 * 
 * @param temperature - Dry bulb temperature (°C)
 * @param humidity - Relative humidity (%)
 * @returns Partial water vapor pressure (hPa)
 */
export function computeVaporPressure(temperature: number, humidity: number): number {
  if (temperature < -45 || temperature > 60) {
    throw new Error(`Temperature ${temperature}°C outside valid range (-45 to +60°C)`);
  }
  if (humidity < 0 || humidity > 100) {
    throw new Error(`Humidity ${humidity}% outside valid range (0-100%)`);
  }
  
  const saturationVaporPressure = 6.112 * Math.exp(
    (17.62 * temperature) / (243.12 + temperature)
  );
  
  return (humidity / 100) * saturationVaporPressure;
}

/**
 * Compute group refractivity (N-value) for a given wavelength and conditions.
 * 
 * N = (n_group - 1) × 10^6
 * 
 * Uses the IAG standard formula (Rüeger 1996) for GROUP refractivity:
 * 
 * N_grp = (n_g - 1) × 10^6
 *       = [(287.604 + 3 × 1.6288/λ² + 5 × 0.0136/λ⁴) × P × 1.0003 / (273.15 + t)]
 *         - [11.27 × e / (273.15 + t)]
 * 
 * The factors 3 and 5 on the dispersion terms convert phase refractivity
 * to group refractivity (which is what EDM instruments measure).
 * 
 * The factor 1.0003 is an enhancement factor for non-ideal gas behavior.
 * 
 * At standard conditions (20°C, 1013.25 hPa, 0% humidity, λ=0.850μm):
 *   N_ref ≈ 273-275 (consistent with most EDM instrument reference values)
 * 
 * @param wavelength - Carrier wavelength (μm)
 * @param conditions - Atmospheric conditions
 * @returns Group refractivity N-value
 */
export function computeGroupRefractivity(
  wavelength: EDMWavelength,
  conditions: AtmosphericConditions
): number {
  const { temperature, pressure, humidity } = conditions;
  
  // Partial water vapor pressure
  const e = computeVaporPressure(temperature, humidity);
  
  // Dry component of GROUP refractivity
  // The factors 3 and 5 on dispersion terms convert phase → group refractivity
  const lambdaSq = wavelength * wavelength;
  const lambdaFourth = lambdaSq * lambdaSq;
  const groupCoeff = 287.604 + (3 * 1.6288 / lambdaSq) + (5 * 0.0136 / lambdaFourth);
  
  // Enhancement factor for non-ideal gas (≈1.0003 at normal pressures)
  const enhancement = 1 + 0.0003;
  
  const N_dry = groupCoeff * pressure * enhancement / (273.15 + temperature);
  
  // Wet component (water vapor reduces refractivity)
  const N_wet = (11.27 * e) / (273.15 + temperature);
  
  return N_dry - N_wet;
}

/**
 * Apply atmospheric correction to an EDM distance measurement.
 * 
 * Corrected distance = Raw distance × (1 + (N_ref - N_obs) / 10^6)
 * 
 * This is the "first velocity correction". A second velocity correction
 * exists but is typically < 0.1 ppm and is included for completeness.
 * 
 * @param rawDistance - Raw measured slope distance (meters)
 * @param conditions - Observed atmospheric conditions
 * @param instrument - EDM instrument parameters
 * @returns Full correction result with audit trail
 */
export function applyAtmosphericCorrection(
  rawDistance: number,
  conditions: AtmosphericConditions,
  instrument: Partial<EDMInstrument> = {}
): AtmosphericCorrectionResult {
  // Defaults
  const wavelength: EDMWavelength = (instrument.wavelength as EDMWavelength) ?? 0.850;
  const referenceN = instrument.referenceN ?? computeGroupRefractivity(wavelength, STANDARD_CONDITIONS);
  const ppmSetting = instrument.ppmSetting ?? 0;
  
  // Validate inputs
  if (rawDistance < 0) {
    throw new Error(`Raw distance ${rawDistance}m must be non-negative`);
  }
  if (conditions.pressure < 500 || conditions.pressure > 1100) {
    throw new Error(`Pressure ${conditions.pressure} hPa outside valid range (500-1100 hPa)`);
  }
  
  // Compute observed refractivity
  const nObs = computeGroupRefractivity(wavelength, conditions);
  
  // First velocity correction (ppm)
  const firstVelocityCorrection = referenceN - nObs;
  
  // Second velocity correction (ppm) — small correction for the
  // difference between phase and group velocity in the atmosphere
  // Typically < 0.1 ppm, but included for completeness
  const e = computeVaporPressure(conditions.temperature, conditions.humidity);
  const secondVelocityCorrection = computeSecondVelocityCorrection(
    wavelength, conditions, e
  );
  
  // Total correction in ppm
  const ppmCorrection = firstVelocityCorrection + secondVelocityCorrection - ppmSetting;
  
  // Apply correction
  const correctionMeters = rawDistance * ppmCorrection / 1e6;
  const correctedDistance = rawDistance + correctionMeters;
  
  return {
    rawDistance,
    correctedDistance,
    ppmCorrection: Math.round(ppmCorrection * 100) / 100, // 2 decimal places
    correctionMeters: Math.round(correctionMeters * 1e6) / 1e6, // micrometer precision
    firstVelocityCorrection: Math.round(firstVelocityCorrection * 100) / 100,
    secondVelocityCorrection: Math.round(secondVelocityCorrection * 1000) / 1000,
    vaporPressure: Math.round(e * 100) / 100,
    nRef: Math.round(referenceN * 100) / 100,
    nObs: Math.round(nObs * 100) / 100,
    referenceConditions: STANDARD_CONDITIONS,
  };
}

/**
 * Compute the second velocity correction.
 * This accounts for the difference between the phase refractivity
 * (which the EDM actually measures) and the group refractivity
 * (which determines the propagation speed of the modulation).
 * 
 * Typically < 0.1 ppm but included for highest accuracy.
 * 
 * @param wavelength - Carrier wavelength (μm)
 * @param conditions - Atmospheric conditions
 * @param vaporPressure - Pre-computed vapor pressure (hPa)
 * @returns Second velocity correction in ppm
 */
function computeSecondVelocityCorrection(
  wavelength: EDMWavelength,
  conditions: AtmosphericConditions,
  vaporPressure: number
): number {
  const { temperature, pressure } = conditions;
  const T = 273.15 + temperature;
  
  // Wavelength dependence
  const lambdaSq = wavelength * wavelength;
  const lambdaFourth = lambdaSq * lambdaSq;
  
  // Derivative of dry refractivity with respect to wavelength
  const dN_dLambda2 = -2 * (1.6288 / (lambdaSq * lambdaSq)) - 4 * (0.0136 / (lambdaFourth * lambdaSq));
  
  // Second velocity correction
  const svc = dN_dLambda2 * lambdaSq * pressure / T * 1e-6;
  
  return svc;
}

// ─── Convenience Functions ───────────────────────────────────────

/**
 * Quick atmospheric correction — returns just the corrected distance.
 * Useful when you don't need the full audit trail.
 */
export function quickAtmosphericCorrection(
  rawDistance: number,
  temperature: number,
  pressure: number,
  humidity: number,
  wavelength: EDMWavelength = 0.850
): number {
  return applyAtmosphericCorrection(
    rawDistance,
    { temperature, pressure, humidity },
    { wavelength }
  ).correctedDistance;
}

/**
 * Compute the atmospheric correction ppm for given conditions.
 * Useful for checking if a measurement needs correction.
 */
export function getAtmosphericPPM(
  temperature: number,
  pressure: number,
  humidity: number,
  wavelength: EDMWavelength = 0.850
): number {
  return applyAtmosphericCorrection(
    1000, // arbitrary reference distance
    { temperature, pressure, humidity },
    { wavelength }
  ).ppmCorrection;
}

/**
 * Validate that atmospheric conditions are within reasonable ranges
 * for surveying in Kenya.
 */
export function validateAtmosphericConditions(conditions: AtmosphericConditions): {
  valid: boolean;
  warnings: string[];
} {
  const warnings: string[] = [];
  
  if (conditions.temperature < -10 || conditions.temperature > 50) {
    warnings.push(`Temperature ${conditions.temperature}°C is outside normal Kenya range (10-40°C)`);
  }
  if (conditions.pressure < 600 || conditions.pressure > 1050) {
    warnings.push(`Pressure ${conditions.pressure} hPa is unusual for Kenya (600-1050 hPa expected)`);
  }
  if (conditions.humidity > 95) {
    warnings.push(`Humidity ${conditions.humidity}% is very high — check for condensation on instrument`);
  }
  
  return {
    valid: warnings.length === 0,
    warnings,
  };
}

/**
 * Grid Scale Factor Module
 * 
 * Computes the point scale factor for UTM and Cassini-Soldner projections.
 * This is the BIGGEST accuracy gap in most surveying software.
 * 
 * At Nairobi (UTM Zone 37S, ~180km from central meridian):
 *   Scale factor ≈ 1.0004
 *   That's 400 ppm — 400mm per kilometer of uncorrected distance.
 * 
 * For cadastral work requiring 1:10,000 closure, this alone can
 * blow the misclosure on traverses longer than ~250m per line.
 * 
 * References:
 * - Snyder, J.P. (1987) "Map Projections — A Working Manual" (USGS PP 1395)
 * - Kenya Survey Department technical specifications
 */

import { WGS84_A, WGS84_E2 } from './curvature-refraction';

// ─── Types ───────────────────────────────────────────────────────

export type ProjectionType = 'UTM36S' | 'UTM37S' | 'CASSINI_SOLDNER';

export interface UTMZone {
  /** Zone number (36 or 37 for Kenya) */
  zone: number;
  /** Hemisphere: 'S' for southern */
  hemisphere: 'N' | 'S';
  /** Central meridian in degrees */
  centralMeridian: number;
  /** Central scale factor (0.9996 for UTM) */
  k0: number;
  /** False easting (500000 for UTM) */
  falseEasting: number;
  /** False northing (0 for N, 10000000 for S) */
  falseNorthing: number;
}

export interface PointScaleFactorResult {
  /** Point scale factor (dimensionless) */
  scaleFactor: number;
  /** Deviation from unity in ppm */
  ppmFromUnity: number;
  /** Easting from central meridian (meters) */
  eastingFromCM: number;
  /** Meridional radius of curvature (meters) */
  rho: number;
  /** Radius of curvature in prime vertical (meters) */
  nu: number;
  /** Mean radius of curvature (meters) */
  Rm: number;
  /** Grid convergence at point (decimal degrees) */
  convergence: number;
  /** Latitude of point (decimal degrees) */
  latitude: number;
  /** Projection used */
  projection: ProjectionType;
}

export interface LineScaleFactorResult {
  /** Line scale factor (Simpson's rule average) */
  lineScaleFactor: number;
  /** Scale factor at start point */
  startScaleFactor: number;
  /** Scale factor at midpoint */
  midScaleFactor: number;
  /** Scale factor at end point */
  endScaleFactor: number;
  /** Grid distance (meters) */
  gridDistance: number;
  /** Ellipsoidal distance (meters) */
  ellipsoidalDistance: number;
  /** Correction in ppm */
  ppmCorrection: number;
}

// ─── Pre-defined UTM Zones for Kenya ────────────────────────────

export const UTM_ZONES: Record<string, UTMZone> = {
  UTM36S: {
    zone: 36,
    hemisphere: 'S',
    centralMeridian: 33,
    k0: 0.9996,
    falseEasting: 500000,
    falseNorthing: 10000000,
  },
  UTM37S: {
    zone: 37,
    hemisphere: 'S',
    centralMeridian: 39,
    k0: 0.9996,
    falseEasting: 500000,
    falseNorthing: 10000000,
  },
};

// Cassini-Soldner parameters (varies by local system in Kenya)
export interface CassiniSoldnerParams {
  /** Origin latitude (decimal degrees) */
  originLatitude: number;
  /** Origin longitude (decimal degrees) */
  originLongitude: number;
  /** False easting (meters) */
  falseEasting: number;
  /** False northing (meters) */
  falseNorthing: number;
  /** Ellipsoid semi-major axis */
  a: number;
  /** Ellipsoid flattening reciprocal */
  rf: number;
}

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute meridional radius of curvature ρ.
 * ρ = a(1 - e²) / (1 - e² × sin²(φ))^(3/2)
 */
function computeMeridionalRadius(latitude: number, a: number = WGS84_A, e2: number = WGS84_E2): number {
  const phi = latitude * Math.PI / 180;
  const sinPhi = Math.sin(phi);
  const denom = Math.pow(1 - e2 * sinPhi * sinPhi, 1.5);
  return a * (1 - e2) / denom;
}

/**
 * Compute radius of curvature in the prime vertical ν.
 * ν = a / √(1 - e² × sin²(φ))
 */
function computePrimeVerticalRadius(latitude: number, a: number = WGS84_A, e2: number = WGS84_E2): number {
  const phi = latitude * Math.PI / 180;
  const sinPhi = Math.sin(phi);
  return a / Math.sqrt(1 - e2 * sinPhi * sinPhi);
}

/**
 * Compute grid convergence at a point.
 * 
 * For UTM:
 * γ = (λ - λ₀) × sin(φ) × [1 + (λ - λ₀)² × cos²(φ) / 3 + ...]
 * 
 * @param latitude - Latitude in decimal degrees
 * @param longitude - Longitude in decimal degrees
 * @param centralMeridian - Central meridian in decimal degrees
 * @returns Grid convergence in decimal degrees
 */
export function computeGridConvergence(
  latitude: number,
  longitude: number,
  centralMeridian: number
): number {
  const phi = latitude * Math.PI / 180;
  const dLambda = (longitude - centralMeridian) * Math.PI / 180;
  const sinPhi = Math.sin(phi);
  const cosPhi = Math.cos(phi);
  
  // First-order convergence
  let gamma = dLambda * sinPhi;
  
  // Higher-order terms for better accuracy
  const dLambda2 = dLambda * dLambda;
  gamma += (dLambda2 * dLambda / 3) * sinPhi * cosPhi * cosPhi;
  
  // Convert back to degrees
  return gamma * 180 / Math.PI;
}

/**
 * Compute point scale factor for UTM projection.
 * 
 * k = k₀ × [1 + (E'²)/(2Rm²) × (1 + e'²cos²φ) + (E'⁴)/(24Rm⁴)]
 * 
 * Where E' = easting from central meridian = E - 500,000
 * 
 * Simplified (sufficient for 2nd order accuracy):
 * k = k₀ × (1 + E'² / (2 × Rm²))
 * 
 * @param easting - UTM easting in meters
 * @param northing - UTM northing in meters
 * @param projection - UTM zone identifier
 * @returns Point scale factor result
 */
export function computeUTMPointScaleFactor(
  easting: number,
  northing: number,
  projection: 'UTM36S' | 'UTM37S'
): PointScaleFactorResult {
  const zone = UTM_ZONES[projection];
  if (!zone) {
    throw new Error(`Unknown UTM zone: ${projection}`);
  }
  
  // Easting from central meridian
  const Eprime = easting - zone.falseEasting;
  
  // Estimate latitude from northing (for computing radii of curvature)
  // This uses the approximate footpoint latitude formula
  const latitude = estimateLatitudeFromNorthing(northing, zone);
  
  // Compute radii of curvature
  const rho = computeMeridionalRadius(latitude);
  const nu = computePrimeVerticalRadius(latitude);
  const Rm = Math.sqrt(rho * nu);
  
  // Second eccentricity squared
  const ePrime2 = WGS84_E2 / (1 - WGS84_E2);
  const cosPhi = Math.cos(latitude * Math.PI / 180);
  const cosPhi2 = cosPhi * cosPhi;
  
  // Point scale factor (full formula for 2nd order accuracy)
  const Eprime2 = Eprime * Eprime;
  const Eprime4 = Eprime2 * Eprime2;
  const Rm2 = Rm * Rm;
  const Rm4 = Rm2 * Rm2;
  
  const k = zone.k0 * (
    1 + 
    (Eprime2 / (2 * Rm2)) * (1 + ePrime2 * cosPhi2) +
    (Eprime4 / (24 * Rm4))
  );
  
  // Grid convergence
  const longitude = estimateLongitudeFromEasting(easting, zone, latitude);
  const convergence = computeGridConvergence(latitude, longitude, zone.centralMeridian);
  
  return {
    scaleFactor: k,
    ppmFromUnity: Math.round((k - 1) * 1e6 * 100) / 100,
    eastingFromCM: Eprime,
    rho,
    nu,
    Rm,
    convergence,
    latitude,
    projection,
  };
}

/**
 * Compute line scale factor using Simpson's rule.
 * 
 * k_line = (k_A + 4×k_M + k_B) / 6
 * 
 * Where k_A, k_M, k_B are point scale factors at start, mid, and end.
 * This gives much better accuracy than simple averaging, especially
 * for lines that cross significant latitude or easting changes.
 * 
 * @param startEasting - Start point easting (meters)
 * @param startNorthing - Start point northing (meters)
 * @param endEasting - End point easting (meters)
 * @param endNorthing - End point northing (meters)
 * @param projection - UTM zone
 * @returns Line scale factor result
 */
export function computeLineScaleFactor(
  startEasting: number,
  startNorthing: number,
  endEasting: number,
  endNorthing: number,
  projection: 'UTM36S' | 'UTM37S'
): LineScaleFactorResult {
  // Midpoint coordinates
  const midEasting = (startEasting + endEasting) / 2;
  const midNorthing = (startNorthing + endNorthing) / 2;
  
  // Point scale factors
  const sfStart = computeUTMPointScaleFactor(startEasting, startNorthing, projection);
  const sfMid = computeUTMPointScaleFactor(midEasting, midNorthing, projection);
  const sfEnd = computeUTMPointScaleFactor(endEasting, endNorthing, projection);
  
  // Simpson's rule line scale factor
  const lineScaleFactor = (sfStart.scaleFactor + 4 * sfMid.scaleFactor + sfEnd.scaleFactor) / 6;
  
  // Compute distances
  const dE = endEasting - startEasting;
  const dN = endNorthing - startNorthing;
  const gridDistance = Math.sqrt(dE * dE + dN * dN);
  const ellipsoidalDistance = gridDistance / lineScaleFactor;
  
  const ppmCorrection = (lineScaleFactor - 1) * 1e6;
  
  return {
    lineScaleFactor,
    startScaleFactor: sfStart.scaleFactor,
    midScaleFactor: sfMid.scaleFactor,
    endScaleFactor: sfEnd.scaleFactor,
    gridDistance,
    ellipsoidalDistance,
    ppmCorrection: Math.round(ppmCorrection * 100) / 100,
  };
}

/**
 * Apply grid scale factor to convert ellipsoidal distance to grid distance.
 * 
 * Grid distance = Ellipsoidal distance × Line scale factor
 * 
 * @param ellipsoidalDistance - Distance reduced to the ellipsoid (meters)
 * @param startEasting - Start point easting
 * @param startNorthing - Start point northing
 * @param endEasting - End point easting
 * @param endNorthing - End point northing
 * @param projection - UTM zone
 * @returns Grid distance in meters
 */
export function applyGridScaleFactor(
  ellipsoidalDistance: number,
  startEasting: number,
  startNorthing: number,
  endEasting: number,
  endNorthing: number,
  projection: 'UTM36S' | 'UTM37S'
): { gridDistance: number; lineScaleFactor: number; ppm: number } {
  const result = computeLineScaleFactor(
    startEasting, startNorthing,
    endEasting, endNorthing,
    projection
  );
  
  return {
    gridDistance: ellipsoidalDistance * result.lineScaleFactor,
    lineScaleFactor: result.lineScaleFactor,
    ppm: result.ppmCorrection,
  };
}

// ─── Helper Functions ────────────────────────────────────────────

/**
 * Estimate latitude from UTM northing (footpoint latitude).
 * Uses the series expansion of the inverse meridional arc formula.
 */
function estimateLatitudeFromNorthing(northing: number, zone: UTMZone): number {
  const a = WGS84_A;
  const e2 = WGS84_E2;
  const e4 = e2 * e2;
  const e6 = e4 * e2;
  
  // Adjusted northing
  const N = northing - zone.falseNorthing;
  
  // Meridional arc
  const M = N / zone.k0;
  
  // Footpoint latitude (series expansion)
  const mu = M / (a * (1 - e2 / 4 - 3 * e4 / 64 - 5 * e6 / 256));
  
  const ePrime2 = e2 / (1 - e2);
  
  const phi1 = mu + 
    (3 * ePrime2 / 2 - 27 * ePrime2 * ePrime2 / 32) * Math.sin(2 * mu) +
    (21 * ePrime2 * ePrime2 / 16 - 55 * ePrime2 * ePrime2 * ePrime2 / 32) * Math.sin(4 * mu) +
    (151 * ePrime2 * ePrime2 * ePrime2 / 96) * Math.sin(6 * mu);
  
  return phi1 * 180 / Math.PI;
}

/**
 * Estimate longitude from UTM easting and known latitude.
 */
function estimateLongitudeFromEasting(easting: number, zone: UTMZone, latitude: number): number {
  const phi = latitude * Math.PI / 180;
  const ePrime2 = WGS84_E2 / (1 - WGS84_E2);
  const nu = computePrimeVerticalRadius(latitude);
  const rho = computeMeridionalRadius(latitude);
  const T = Math.tan(phi) * Math.tan(phi);
  const C = ePrime2 * Math.cos(phi) * Math.cos(phi);
  const N = nu;
  const R = rho;
  const D = (easting - zone.falseEasting) / (zone.k0 * N);
  
  const lon = zone.centralMeridian * Math.PI / 180 + 
    (D - (1 + 2 * T + C) * D * D * D / 6 + 
     (5 - 2 * C + 28 * T - 3 * C * C + 8 * ePrime2 + 24 * T * T) * 
     D * D * D * D * D / 120) / Math.cos(phi);
  
  return lon * 180 / Math.PI;
}

/**
 * Circular Curve Calculations
 * 
 * Horizontal circular curve computations for road and railway design.
 * Handles simple curves, compound curves, and reverse curves.
 * 
 * References:
 * - Schofield, W. (2001) "Engineering Surveying"
 * - Meyer, C.F. (1969) "Route Surveying and Design"
 */

// ─── Types ───────────────────────────────────────────────────────

export interface CircularCurveParams {
  /** Intersection angle (decimal degrees) — total deflection */
  intersectionAngle: number;
  /** Radius of the curve (meters) */
  radius: number;
}

export interface CircularCurveResult {
  /** Intersection angle (decimal degrees) */
  intersectionAngle: number;
  /** Radius (meters) */
  radius: number;
  /** Tangent length (meters) — PI to PC or PI to PT */
  tangentLength: number;
  /** Curve length (meters) — arc from PC to PT */
  curveLength: number;
  /** Length of long chord (meters) — straight line PC to PT */
  longChordLength: number;
  /** Mid-ordinate (meters) — distance from midpoint of long chord to curve */
  midOrdinate: number;
  /** External distance (meters) — distance from PI to curve midpoint */
  externalDistance: number;
  /** Degree of curvature (decimal degrees) — based on arc definition */
  degreeOfCurvature: number;
  /** Deflection angle to any point on curve (for setting out) */
  deflectionPerMeter: number; // degrees per meter of arc
}

export interface CurveStationResult {
  /** Chainage/station (meters) */
  chainage: number;
  /** Deflection angle from PC (decimal degrees) */
  deflectionAngle: number;
  /** Chord length from PC (meters) */
  chordLength: number;
  /** Easting coordinate */
  easting?: number;
  /** Northing coordinate */
  northing?: number;
}

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute circular curve parameters from intersection angle and radius.
 * 
 * Standard formulas:
 *   T = R × tan(Δ/2)          — Tangent length
 *   L = R × Δ × (π/180)       — Curve length (arc)
 *   LC = 2R × sin(Δ/2)        — Long chord
 *   M = R × (1 - cos(Δ/2))    — Mid-ordinate
 *   E = R × (sec(Δ/2) - 1)    — External distance
 *   D = 5729.578 / R           — Degree of curvature (arc definition, 30m arc)
 */
export function computeCircularCurve(params: CircularCurveParams): CircularCurveResult {
  const { intersectionAngle, radius } = params;
  
  const deltaRad = intersectionAngle * Math.PI / 180;
  const halfDelta = deltaRad / 2;
  
  const tangentLength = radius * Math.tan(halfDelta);
  const curveLength = radius * deltaRad;
  const longChordLength = 2 * radius * Math.sin(halfDelta);
  const midOrdinate = radius * (1 - Math.cos(halfDelta));
  const externalDistance = radius * (1 / Math.cos(halfDelta) - 1);
  const degreeOfCurvature = 5729.578 / radius; // Arc definition (30m arc)
  const deflectionPerMeter = (intersectionAngle / 2) / curveLength; // degrees per meter
  
  return {
    intersectionAngle,
    radius,
    tangentLength: Math.round(tangentLength * 1000) / 1000,
    curveLength: Math.round(curveLength * 1000) / 1000,
    longChordLength: Math.round(longChordLength * 1000) / 1000,
    midOrdinate: Math.round(midOrdinate * 1000) / 1000,
    externalDistance: Math.round(externalDistance * 1000) / 1000,
    degreeOfCurvature: Math.round(degreeOfCurvature * 10000) / 10000,
    deflectionPerMeter: Math.round(deflectionPerMeter * 1000000) / 1000000,
  };
}

/**
 * Compute setting-out data for a circular curve at regular intervals.
 * 
 * Generates deflection angles and chord lengths for each station
 * along the curve, suitable for field stakeout.
 * 
 * @param curve - Circular curve parameters (from computeCircularCurve)
 * @param interval - Station interval (meters), default 10m
 * @param pcChainage - Chainage of PC (Point of Curvature)
 * @param pcEasting - Easting of PI (Point of Intersection)
 * @param pcNorthing - Northing of PI
 * @param backBearing - Bearing from PI to PC (decimal degrees)
 */
export function computeCurveStations(
  curve: CircularCurveResult,
  interval: number = 10,
  pcChainage: number = 0,
  piEasting?: number,
  piNorthing?: number,
  backBearing?: number,
): CurveStationResult[] {
  const stations: CurveStationResult[] = [];
  
  // PC station
  const pcDeflection = 0;
  stations.push({
    chainage: pcChainage,
    deflectionAngle: 0,
    chordLength: 0,
  });
  
  // Intermediate stations
  const numStations = Math.floor(curve.curveLength / interval);
  
  for (let i = 1; i <= numStations; i++) {
    const arcLength = i * interval;
    const deflectionAngle = arcLength * curve.deflectionPerMeter;
    const chordLength = 2 * curve.radius * Math.sin(deflectionAngle * Math.PI / 180);
    
    stations.push({
      chainage: pcChainage + arcLength,
      deflectionAngle: Math.round(deflectionAngle * 1000) / 1000,
      chordLength: Math.round(chordLength * 1000) / 1000,
    });
  }
  
  // PT station (exact)
  const ptArcLength = curve.curveLength;
  const ptDeflection = curve.intersectionAngle / 2;
  const ptChord = curve.longChordLength;
  
  // Only add if not already at an interval station
  const lastStation = stations[stations.length - 1];
  if (Math.abs(lastStation.chainage - (pcChainage + ptArcLength)) > 0.01) {
    stations.push({
      chainage: Math.round((pcChainage + ptArcLength) * 1000) / 1000,
      deflectionAngle: Math.round(ptDeflection * 1000) / 1000,
      chordLength: ptChord,
    });
  }
  
  // Compute coordinates if PI and bearing provided
  if (piEasting !== undefined && piNorthing !== undefined && backBearing !== undefined) {
    computeCurveCoordinates(stations, curve, piEasting, piNorthing, backBearing);
  }
  
  return stations;
}

/**
 * Compute coordinates for curve stations.
 */
function computeCurveCoordinates(
  stations: CurveStationResult[],
  curve: CircularCurveResult,
  piEasting: number,
  piNorthing: number,
  backBearing: number,
): void {
  // PC coordinates
  const pcBearing = backBearing; // Bearing from PI to PC
  const pcE = piEasting - curve.tangentLength * Math.sin(pcBearing * Math.PI / 180);
  const pcN = piNorthing - curve.tangentLength * Math.cos(pcBearing * Math.PI / 180);
  
  stations[0].easting = pcE;
  stations[0].northing = pcN;
  
  // Subsequent stations — compute from PC using deflection angles
  // AUDIT FIX (M6, 2026-07-02): original code was a no-op —
  // `if (tangentBearing >= 360) tangentBearing - 360;` computed the
  // subtraction but discarded the result. Replaced with modulo to wrap
  // to [0, 360). Also changed const → let.
  let tangentBearing = (backBearing + 180) % 360;
  if (tangentBearing < 0) tangentBearing += 360;
  
  for (let i = 1; i < stations.length; i++) {
    const deflRad = stations[i].deflectionAngle * Math.PI / 180;
    const tangentBearingRad = (tangentBearing) * Math.PI / 180;
    
    // Bearing to point on curve
    const bearingToStation = tangentBearingRad + deflRad;
    const chord = stations[i].chordLength;
    
    stations[i].easting = pcE + chord * Math.sin(bearingToStation);
    stations[i].northing = pcN + chord * Math.cos(bearingToStation);
  }
}

/**
 * Compute circular curve from tangent length and intersection angle.
 * Useful when radius is not directly specified.
 */
export function computeCurveFromTangent(
  tangentLength: number,
  intersectionAngle: number
): CircularCurveResult {
  const halfDelta = intersectionAngle * Math.PI / 360;
  const radius = tangentLength / Math.tan(halfDelta);
  
  return computeCircularCurve({ intersectionAngle, radius });
}

/**
 * Compute circular curve from degree of curvature.
 * Degree of curvature (arc definition): D = 5729.578 / R
 */
export function computeCurveFromDegree(
  degreeOfCurvature: number,
  intersectionAngle: number
): CircularCurveResult {
  const radius = 5729.578 / degreeOfCurvature;
  
  return computeCircularCurve({ intersectionAngle, radius });
}

/**
 * LiveToleranceChecker — field-side, offline-first tolerance checking
 *
 * THE PROMISE
 * -----------
 * "The surveyor never has to do arithmetic in their head between the moment
 * they capture a shot and the moment it's either flagged wrong or accepted
 * as correct."
 *
 * This module wraps the existing traverse engine + RDM 1.1 tolerance tables
 * + LSA statistical testing into a single function that runs client-side,
 * offline, in < 100ms. After each shot is added to the field book, re-run
 * this check. Show a persistent badge: green (passing), yellow (marginal),
 * red (failing). When red, highlight the leg with the largest residual and
 * say "recheck setup at station X."
 *
 * WHAT IT CHECKS
 * --------------
 * 1. Traverse closure: linear misclosure / perimeter → precision ratio
 *    → RDM 1.1 Table 5.1 order classification → pass/fail
 * 2. Angular misclosure: sum of measured angles vs (n-2)×180°
 *    → per-station allowance → pass/fail
 * 3. Leveling closure: misclosure vs C√K mm → pass/fail
 * 4. LSA global test (if enough observations for redundancy)
 * 5. Worst-leg identification: which leg has the largest residual
 *
 * OFFLINE-FIRST
 * -------------
 * The entire check runs in the browser. No server round-trip. Uses the
 * observations already in IndexedDB. The result syncs when connectivity
 * returns.
 *
 * USAGE
 * -----
 *   import { checkTolerance } from '@/lib/survey/liveToleranceChecker'
 *
 *   const result = checkTolerance({
 *     surveyType: 'cadastral',
 *     observations: [...],  // from the field book
 *     openingEasting: 264000,
 *     openingNorthing: 9861000,
 *     closingEasting: 264000,  // same = closed traverse
 *     closingNorthing: 9861000,
 *   })
 *
 *   if (result.status === 'fail') {
 *     // Show: "Closure failed (1:8,234). Recheck setup at station CP3."
 *   }
 */

import { computeTraverse, type RawObservation, type TraverseComputationResult } from '@/lib/computations/traverseEngine'
import {
  checkTraverseConformance,
  checkLevelingConformance,
  RDM_TRAVERSE_ACCURACY,
  RDM_LEVELING_ACCURACY,
  type RDMConformanceResult,
} from '@/lib/standards/rdm11'
import { globalChiSquareTest } from '@/lib/survey/lsaStatisticalTesting'

// ─── Types ──────────────────────────────────────────────────────────────────

export type SurveyType =
  | 'cadastral'
  | 'engineering'
  | 'topographic'
  | 'control'
  | 'monitoring'
  | 'leveling'
  | 'construction'

export type ToleranceStatus = 'pass' | 'marginal' | 'fail' | 'insufficient_data'

export interface ToleranceCheckInput {
  /** Survey type — determines which RDM 1.1 order is required */
  surveyType: SurveyType

  /** Traverse observations (from the field book) */
  observations: RawObservation[]

  /** Opening control point */
  openingEasting: number
  openingNorthing: number
  openingStation: string

  /** Closing control point (same as opening for closed traverse) */
  closingEasting?: number
  closingNorthing?: number
  closingStation?: string

  /** Backsight bearing (for WCB computation) */
  backsightBearingDeg: number
  backsightBearingMin: number
  backsightBearingSec: number

  /** For leveling checks */
  levelingMisclosureMm?: number
  levelingDistanceKm?: number

  /** LSA results (if available from a network adjustment) */
  sigmaZero?: number
  degreesOfFreedom?: number
}

export interface WorstLegInfo {
  /** Station name where the worst residual occurs */
  station: string
  /** The leg from → to */
  from: string
  to: string
  /** Residual magnitude in mm */
  residualMm: number
  /** What this means */
  diagnosis: string
  /** What the surveyor should do */
  recommendation: string
}

export interface ToleranceCheckResult {
  /** Overall status: pass / marginal / fail / insufficient_data */
  status: ToleranceStatus

  /** Human-readable summary for the badge */
  summary: string

  /** Detailed checks (from RDM 1.1 conformance checker) */
  rdmChecks: RDMConformanceResult

  /** Achieved accuracy order (e.g., "Second Order Class II") */
  achievedOrder: string | null

  /** Required accuracy order for this survey type */
  requiredOrder: string

  /** Precision ratio (e.g., 8234 → "1:8,234") */
  precisionRatio: number | null

  /** Linear misclosure in mm */
  linearMisclosureMm: number

  /** Total traverse perimeter in km */
  perimeterKm: number

  /** The leg with the largest residual (null if can't determine) */
  worstLeg: WorstLegInfo | null

  /** LSA global test result (if applicable) */
  lsaGlobalTest?: {
    passed: boolean
    chiSquareObserved: number
    chiSquareCritical: number
    interpretation: string
  }

  /** Whether there's enough data to perform the check */
  hasEnoughData: boolean

  /** List of actionable recommendations */
  recommendations: string[]

  /** Timestamp */
  timestamp: string
}

// ─── RDM 1.1 Order Requirements per Survey Type ─────────────────────────────

/**
 * Map survey type → minimum required RDM 1.1 order.
 *
 * Source: RDM 1.1 Table 5.1 + Survey Regulations 1994 + Survey Act Cap 299
 */
const SURVEY_TYPE_REQUIREMENTS: Record<SurveyType, {
  traverseOrder: string
  levelingOrder: string
  description: string
}> = {
  cadastral: {
    traverseOrder: 'Second Order Class II',  // 1:10,000 — minimum for title surveys
    levelingOrder: 'Third Order',             // 10√K mm
    description: 'Cadastral (title) surveys require minimum Second Order Class II (1:10,000) per Survey Regulations 1994.',
  },
  engineering: {
    traverseOrder: 'Second Order Class I',   // 1:20,000 — major engineering
    levelingOrder: 'Second Order',            // 8√K mm
    description: 'Engineering surveys require minimum Second Order Class I (1:20,000) per RDM 1.1.',
  },
  topographic: {
    traverseOrder: 'Third Order',              // 1:5,000
    levelingOrder: 'Fourth Order',             // 12√K mm
    description: 'Topographic surveys require minimum Third Order (1:5,000).',
  },
  control: {
    traverseOrder: 'First Order Class II',    // 1:50,000 — secondary geodetic
    levelingOrder: 'Second Order',             // 8√K mm
    description: 'Control surveys require minimum First Order Class II (1:50,000).',
  },
  monitoring: {
    traverseOrder: 'First Order Class II',    // 1:50,000 — deformation monitoring
    levelingOrder: 'First Order',              // 4√K mm
    description: 'Deformation monitoring requires First Order Class II (1:50,000) and First Order leveling.',
  },
  leveling: {
    traverseOrder: 'Third Order',
    levelingOrder: 'Third Order',              // 10√K mm — cadastral minimum
    description: 'Leveling surveys require minimum Third Order (10√K mm).',
  },
  construction: {
    traverseOrder: 'Second Order Class I',    // 1:20,000 — setting out
    levelingOrder: 'Second Order',             // 8√K mm
    description: 'Construction setting out requires Second Order Class I (1:20,000).',
  },
}

// ─── Main Function ──────────────────────────────────────────────────────────

/**
 * Check the tolerance of the current field observations.
 *
 * This is the core function of the live tolerance checker. It runs
 * client-side, offline, in < 100ms. Call it after every shot is added
 * to the field book.
 *
 * @param input - Observations + control points + survey type
 * @returns ToleranceCheckResult with status, summary, worst-leg, recommendations
 */
export function checkTolerance(input: ToleranceCheckInput): ToleranceCheckResult {
  const requirements = SURVEY_TYPE_REQUIREMENTS[input.surveyType]
  const recommendations: string[] = []
  const timestamp = new Date().toISOString()

  // ─── Check if we have enough data ───
  const validObs = input.observations.filter(o => o.station && o.slopeDist)
  if (validObs.length < 3) {
    return {
      status: 'insufficient_data',
      summary: `Need at least 3 observations to check (have ${validObs.length}). Keep shooting.`,
      rdmChecks: { passed: false, checks: [], overallGrade: null },
      achievedOrder: null,
      requiredOrder: requirements.traverseOrder,
      precisionRatio: null,
      linearMisclosureMm: 0,
      perimeterKm: 0,
      worstLeg: null,
      hasEnoughData: false,
      recommendations: ['Continue capturing observations. The tolerance check will activate at 3+ legs.'],
      timestamp,
    }
  }

  // ─── Compute the traverse ───
  let traverseResult: TraverseComputationResult
  try {
    traverseResult = computeTraverse({
      openingEasting: input.openingEasting,
      openingNorthing: input.openingNorthing,
      openingStation: input.openingStation,
      closingEasting: input.closingEasting,
      closingNorthing: input.closingNorthing,
      closingStation: input.closingStation,
      observations: input.observations,
      backsightBearingDeg: input.backsightBearingDeg,
      backsightBearingMin: input.backsightBearingMin,
      backsightBearingSec: input.backsightBearingSec,
    })
  } catch (err) {
    return {
      status: 'fail',
      summary: `Traverse computation failed: ${err instanceof Error ? err.message : String(err)}`,
      rdmChecks: { passed: false, checks: [], overallGrade: null },
      achievedOrder: null,
      requiredOrder: requirements.traverseOrder,
      precisionRatio: null,
      linearMisclosureMm: 0,
      perimeterKm: 0,
      worstLeg: null,
      hasEnoughData: true,
      recommendations: ['Check that observations are complete and angles/distances are entered correctly.'],
      timestamp,
    }
  }

  // ─── Check RDM 1.1 traverse conformance ───
  const linearErrorM = traverseResult.linearError
  const totalDistanceM = traverseResult.totalPerimeter
  const angularErrorSec = computeAngularMisclosure(validObs)
  const numStations = validObs.length

  const rdmChecks = checkTraverseConformance(
    linearErrorM,
    totalDistanceM,
    angularErrorSec,
    numStations,
    requirements.traverseOrder,
  )

  // ─── Check leveling if provided ───
  if (input.levelingMisclosureMm !== undefined && input.levelingDistanceKm !== undefined) {
    const levelingChecks = checkLevelingConformance(
      input.levelingMisclosureMm,
      input.levelingDistanceKm,
      requirements.levelingOrder,
    )
    rdmChecks.checks.push(...levelingChecks.checks)
    rdmChecks.passed = rdmChecks.passed && levelingChecks.passed
  }

  // ─── Identify the worst leg ───
  const worstLeg = identifyWorstLeg(traverseResult)

  // ─── LSA global test (if sigmaZero + dof provided) ───
  let lsaGlobalTest: ToleranceCheckResult['lsaGlobalTest']
  if (input.sigmaZero !== undefined && input.degreesOfFreedom !== undefined && input.degreesOfFreedom > 0) {
    const test = globalChiSquareTest(input.sigmaZero, input.degreesOfFreedom, 0.05)
    lsaGlobalTest = {
      passed: test.passed,
      chiSquareObserved: test.chiSquareObserved,
      chiSquareCritical: test.chiSquareCritical,
      interpretation: test.interpretation,
    }
    if (!test.passed) {
      recommendations.push('LSA global test failed — the adjustment may contain blunders or incorrect a priori standard deviations.')
    }
  }

  // ─── Determine overall status ───
  const requiredStd = RDM_TRAVERSE_ACCURACY.find(s => s.order === requirements.traverseOrder)
  const requiredRatio = requiredStd?.ratioNumeric ?? 10000
  const achievedRatio = traverseResult.precisionRatio

  let status: ToleranceStatus
  let summary: string

  if (rdmChecks.passed && achievedRatio >= requiredRatio) {
    // Check if marginal (within 20% of the limit)
    if (achievedRatio < requiredRatio * 1.2) {
      status = 'marginal'
      summary = `Marginal: 1:${Math.round(achievedRatio).toLocaleString()} (required ≥ 1:${requiredRatio.toLocaleString()}). Passing but close — consider rechecking observations.`
      recommendations.push(`Precision ratio is within 20% of the minimum. Verify the worst leg at ${worstLeg?.station ?? 'unknown'}.`)
    } else {
      status = 'pass'
      const order = rdmChecks.overallGrade ?? 'Unknown'
      summary = `PASS — ${order} (1:${Math.round(achievedRatio).toLocaleString()}). Closure ${(traverseResult.linearError * 1000).toFixed(1)}mm over ${(totalDistanceM / 1000).toFixed(3)}km.`
    }
  } else {
    status = 'fail'
    summary = `FAIL — 1:${Math.round(achievedRatio).toLocaleString()} (required ≥ 1:${requiredRatio.toLocaleString()}). Linear misclosure ${(linearErrorM * 1000).toFixed(1)}mm.`
    if (worstLeg) {
      recommendations.push(`Recheck setup at ${worstLeg.station}. ${worstLeg.recommendation}`)
    }
    recommendations.push(`Required: ${requirements.traverseOrder} (${requirements.description})`)
  }

  // ─── Angular misclosure warning ───
  if (angularErrorSec > 10) {
    recommendations.push(`Angular misclosure is high (${angularErrorSec.toFixed(1)}″/station). Check for misread angles or instrument centering errors.`)
  }

  // ─── Courses without azimuth check ───
  if (numStations > 15) {
    recommendations.push(`${numStations} courses without azimuth check exceeds RDM 1.1 limit of 15. Add an intermediate azimuth check.`)
  }

  return {
    status,
    summary,
    rdmChecks,
    achievedOrder: rdmChecks.overallGrade,
    requiredOrder: requirements.traverseOrder,
    precisionRatio: achievedRatio,
    linearMisclosureMm: linearErrorM * 1000,
    perimeterKm: totalDistanceM / 1000,
    worstLeg,
    lsaGlobalTest,
    hasEnoughData: true,
    recommendations: recommendations.length > 0 ? recommendations : ['All checks passing. Continue to next station.'],
    timestamp,
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Compute the angular misclosure per station.
 *
 * For a closed traverse: sum of interior angles = (n-2) × 180°
 * Misclosure = sum of measured angles - (n-2) × 180°
 * Per station = misclosure / n
 */
function computeAngularMisclosure(observations: RawObservation[]): number {
  // We need the measured angles. The RawObservation has HCL/HCR which
  // give the mean angle. For a simple check, we compute the mean angle
  // per station and check if the sum closes.
  //
  // NOTE: This is a simplified check. A full angular misclosure requires
  // knowing which angles are interior vs exterior. For the field-side
  // check, we estimate from the residuals.

  // If we can't compute it (incomplete data), return 0 (no warning)
  if (observations.length < 3) return 0

  try {
    // Compute mean angle per station
    let sumAngles = 0
    let count = 0
    for (const obs of observations) {
      const hcl = (parseInt(obs.hclDeg) || 0) + (parseInt(obs.hclMin) || 0) / 60 + (parseFloat(obs.hclSec) || 0) / 3600
      const hcr = (parseInt(obs.hcrDeg) || 0) + (parseInt(obs.hcrMin) || 0) / 60 + (parseFloat(obs.hcrSec) || 0) / 3600
      if (hcl > 0 || hcr > 0) {
        let hcrAdj = hcr + 180
        if (hcrAdj >= 360) hcrAdj -= 360
        const meanAngle = (hcl + hcrAdj) / 2
        sumAngles += meanAngle
        count++
      }
    }

    if (count < 3) return 0

    // Expected sum for a closed polygon: (n-2) × 180
    const expected = (count - 2) * 180
    const misclosure = Math.abs(sumAngles - expected)
    // Per station
    return (misclosure / count) * 3600 // convert to arc-seconds
  } catch {
    return 0
  }
}

/**
 * Identify the leg with the largest residual.
 *
 * After the Bowditch adjustment, each leg has a departure correction and
 * a latitude correction. The leg with the largest combined correction is
 * the most likely source of a blunder.
 */
function identifyWorstLeg(result: TraverseComputationResult): WorstLegInfo | null {
  if (!result.legs || result.legs.length === 0) return null

  let worstLeg = result.legs[0]
  let worstResidual = 0

  for (const leg of result.legs) {
    // Combined correction magnitude (mm)
    const residualMm = Math.sqrt(
      leg.depCorrection ** 2 + leg.latCorrection ** 2,
    ) * 1000

    if (residualMm > worstResidual) {
      worstResidual = residualMm
      worstLeg = leg
    }
  }

  if (worstResidual < 1) {
    // No significant residual — all legs are fine
    return null
  }

  // Diagnose the likely cause
  let diagnosis: string
  let recommendation: string

  const depCorr = Math.abs(worstLeg.depCorrection)
  const latCorr = Math.abs(worstLeg.latCorrection)

  if (depCorr > latCorr * 2) {
    diagnosis = `Largest departure correction (${(worstLeg.depCorrection * 1000).toFixed(1)}mm) on leg ${worstLeg.from} → ${worstLeg.to}.`
    recommendation = `Distance on this leg may be wrong. Re-measure the distance from ${worstLeg.from} to ${worstLeg.to}.`
  } else if (latCorr > depCorr * 2) {
    diagnosis = `Largest latitude correction (${(worstLeg.latCorrection * 1000).toFixed(1)}mm) on leg ${worstLeg.from} → ${worstLeg.to}.`
    recommendation = `Bearing on this leg may be wrong. Re-check the angle at ${worstLeg.from}.`
  } else {
    diagnosis = `Largest combined correction (${worstResidual.toFixed(1)}mm) on leg ${worstLeg.from} → ${worstLeg.to}.`
    recommendation = `Recheck both angle and distance at station ${worstLeg.from}.`
  }

  return {
    station: worstLeg.from,
    from: worstLeg.from,
    to: worstLeg.to,
    residualMm: worstResidual,
    diagnosis,
    recommendation,
  }
}

// ─── Badge Helpers (for the UI) ─────────────────────────────────────────────

/**
