    openingEasting: 264000,
    openingNorthing: 9861000,
    openingStation: 'CP1',
    closingEasting: 264000,
    closingNorthing: 9861000,
    closingStation: 'CP1',
    backsightBearingDeg: 0,
    backsightBearingMin: 0,
    backsightBearingSec: 0,
  }
}

